object Main extends App {
  val in = new InputReader(System.in)
  val pw = new PrintWriter(System.out)

  // val ar = new Array[Int](N)

  val lpq = new PriorityQueue[Int]()
  val rpq = new PriorityQueue[Int]()(Ordering.Int.reverse)
  var lnum = 0
  var rnum = 0
  var handFlag = false
  var hand: Int = 0

  var ncnt = 0L
  var pcnt = 0L
  var pn = 0
  var nn = 0

  var ans = 0L

  val Q = in.next().toInt
  for (_ <- 1 to Q) {
    val c = in.next().toInt

    if (c == 1) {
      val a, b = in.next().toInt

      if(a < 0) {
        ncnt += a
        nn += 1
      }
      else {
        pcnt += a
        pn += 1
      }
      ans += b

      if (!handFlag) {
        hand = a
        handFlag = true
      }
      else {
        if (a == hand) {
          if (lnum < rnum) {
            lnum += 1
            lpq.enqueue(a)
          }
          else {
            rnum += 1
            rpq.enqueue(a)
          }
        }
        else if (a < hand) {
          if (lnum <= rnum) {
            lnum += 1
            lpq.enqueue(a)
          }
          else {
            rnum += 1
            rpq.enqueue(hand)
            lpq.enqueue(a)
            hand = lpq.dequeue()
          }
        }
        else if (a > hand) {
          if (lnum >= rnum) {
            rnum += 1
            rpq.enqueue(a)
          }
          else {
            lnum += 1
            lpq.enqueue(hand)
            rpq.enqueue(a)
            hand = rpq.dequeue()
          }
        }
      }
    }
    else if (c == 2) {
      var hoge = ans
      // println(hand, ncnt, pcnt)

      if (hand < 0) {
        hoge += Math.abs(pcnt - (hand.toLong * pn))
        hoge += Math.abs(ncnt - (hand.toLong * nn))
      }
      else {
        hoge += Math.abs(pcnt - (hand.toLong * pn))
        hoge += Math.abs(ncnt - (hand.toLong * nn))
      }

      pw.println(s"$hand $hoge")
    }
  }

  pw.flush()
}

