  val lpq = new PriorityQueue[Int]()
  val rpq = new PriorityQueue[Int]()(Ordering.Int.reverse)
  var lnum = 0
  var rnum = 0
  var handFlag = false
  var hand: Int = 0

  var lcnt = 0L
  var rcnt = 0L

  var ans = 0L

  val Q = in.next().toInt
  for (_ <- 1 to Q) {
    val c = in.next().toInt

    if (c == 1) {
      val a, b = in.next().toInt

      ans += b

      if (!handFlag) {
