        handFlag = true
      }
      else {
        if (a == hand) {
          if (lnum < rnum) {
            lnum += 1
            lpq.enqueue(a)
            lcnt += a
          }
          else {
            rnum += 1
            rpq.enqueue(a)
            rcnt += a
          }
        }
        else if (a < hand) {
          if (lnum <= rnum) {
            lnum += 1
            lpq.enqueue(a)
            lcnt += a
          }
          else {
            rnum += 1

            rpq.enqueue(hand)
            rcnt += hand

            lpq.enqueue(a)
            lcnt += a

            hand = lpq.dequeue()
            lcnt -= hand
          }
        }
        else if (a > hand) {
          if (lnum >= rnum) {
            rnum += 1
            rpq.enqueue(a)
            rcnt += a
          }
          else {
            lnum += 1

            lpq.enqueue(hand)
            lcnt += hand

            rpq.enqueue(a)
            rcnt += a

            hand = rpq.dequeue()
            rcnt -= hand
          }
        }
      }
