  import mutable.ArrayBuffer

  // toIntとか+7とかするならvalにしろ
  @inline private def MOD = 1000000007

  // todo debug
  val Inf = -10

  def solve(): Unit = {
    import java.util
    import java.util.Collections
    val Q = ni()
    val queries = Array.ofDim[Query](Q)
    val nums = new util.ArrayList[Integer]()

    REP(Q) { i =>
      val tpe = ni()
      queries(i) = tpe match {
        case 1 =>
          val a, b = ni()
          nums.add(a)
          Query(tpe, a, b)

        case 2 =>
          Query(tpe, 0, 0)
      }
    }
    nums.add(Inf)
    Collections.sort(nums)

    var p = 0
    val zip = mutable.HashMap[Int, Int]()
    REP(nums.size()) { i =>
      val a = nums.get(i)
      if (!zip.contains(a)) {
        zip.put(a, p)
        p += 1
      }
    }

    val x0 = new BIT(nums.size(), 0)(_ + _)
    val x1 = new BIT(nums.size(), 0)(_ + _)

    def f(id: Int): Long = {
      val x = nums.get(id)
      x1.sum(id + 1) * x + x0.sum(id + 1)
    }

//    def test(): Unit = {
//      REP(nums.size()) { i =>
//        val x = nums.get(i)
//        val id = zip(x)
//        val y = x1.sum(id + 1) * x + x0.sum(id + 1)
//        debug(s"x:$x y:$y")
//      }
//    }

    def test(id: Int): Boolean = {
      f(id) <= f(id + 1)
    }

    val infId = zip(Inf)

    var sumB = 0L
    REP(Q) { i =>
      queries(i).tpe match {
        case 1 =>
          sumB += queries(i).b
          val a = queries(i).a

          // INFで傾きを-1に、f(a)=0になるように調整する
          x1.add(infId, -1)
          x0.add(infId, a)

          // x=aで 傾きを-1 => 1 に変更
          x1.add(zip(a), 2)
          x0.add(zip(a), -2 * a)

        case 2 =>
          val id = findMin(test, 0, nums.size() - 1)
          val x = nums.get(id)
          val y = f(id) + sumB
          out.println(s"$x $y")
      }
    }
  }

  def findMin(f: Int => Boolean, min: Int, max: Int): Int = {
    var l = min - 1
    var h = max
    while(h - l > 1) {
      val x = (h + l) / 2
      if (f(x)) h = x
      else l = x
    }
    h
  }
}

