void upd(int node, int a, int b, int i, int j, int val, int tp){
    if(a > j || b < i || b < a) return;

    if(a == b){
        if(tp == 0){
            tree[node][0]++;
        } else{
            tree[node][1] += val;
        }
        return;
    }

    upd(node*2, a, (a+b)/2, i, j, val, tp);
    upd(node*2+1, 1+(a+b)/2, b, i, j, val, tp);
    tree[node][tp] = tree[node*2][tp]+tree[node*2+1][tp];
}
ll que(int node, int a, int b, int i, int j, int tp){
    if(a > j || b < i || b < a || i > j) return 0;

    if(i <= a && b <= j){
        return tree[node][tp];
    }

    ll q1 = que(node*2, a, (a+b)/2, i, j, tp);
    ll q2 = que(node*2+1, 1+(a+b)/2, b, i, j, tp);
    return q1+q2;
}

