    cin >> Q;

    ll sum_b = 0, sum_left = 0, sum_right = 0;
    for (int i = 0, type, a, b; i < Q; ++i) {
        cin >> type;
        if (type == 1) {
            cin >> a >> b;

            sum_b += b;
            if (left.empty() || a <= left.top()) {
                left.push(a);
                sum_left += a;
            }
            else {
                right.push(a);
                sum_right += a;
            }

            if (left.size() < right.size()) {
                sum_left += right.top();
                sum_right -= right.top();
                left.push(right.top());
                right.pop();
            }
            if (left.size() > right.size() + 1) {
                sum_left -= left.top();
                sum_right += left.top();
                right.push(left.top());
                left.pop();
            }
        }
        else {
            ll min_f = sum_b + a * left.size() - sum_left
                + sum_right - a * right.size();
            cout << left.top() << " " << min_f << endl;
        }
    }

    return 0;
}

