int n, t, a, b;
long long aac, bac;
priority_queue<int> fr;
priority_queue<int, vector<int>, greater<int>> bk;

int main(){
    scanf("%d", &n);
    while(n--){
        scanf("%d", &t);
        if(t == 1){
            scanf("%d%d", &a, &b);
            bac += b;
            if(fr.empty() || fr.top() >= a) fr.push(a);
            else bk.push(a);
            aac += abs(fr.top() - a);
        }else{
            int dif = (int)fr.size() - (int)bk.size();
            while(dif > 1){
                bk.push(fr.top()); fr.pop();
                aac += (dif-1)/2 * (fr.top() - bk.top());
                dif -= 2;
            }
            while(dif < 0){
                aac += (1-dif)/2 * (fr.top() - bk.top());
                fr.push(bk.top()); bk.pop();
                dif += 2;
            }
            printf("%d %lld\n", fr.top(), aac + bac);
        }
    }
}

