  int leftmax  = *(--left.end());
  int rightmin = *(right.begin());
  if (left.empty() || (leftmax <= a && rightmin <= a)) {
    result += 0;
  } else if (a < leftmax) {
    result += (leftmax - a);
  } else {
    result += (a - rightmin);
  }
