void solve() {
    i64 Q; RD(Q);

    i64 b = 0;
    i64 med;
    i64 lo = 0;
    i64 hi = 0;
    MaxHeap<i64> los;
    MinHeap<i64> his;

    {
        i64 cmd; RD(cmd);
        ASSERT(cmd == 1);
        i64 a,bb; RD(a); RD(bb);
        b += bb;
        med = a;
    }

    REP(_, Q-1) {
        i64 cmd; RD(cmd);
        if(cmd == 1) {
            i64 a,bb; RD(a); RD(bb);
            b += bb;

            if(a == med) {
                if(SIZE(los) <= SIZE(his))
                    los.emplace(a);
                else
                    his.emplace(a);
            }
            else if(a <= med) {
                if(SIZE(los) <= SIZE(his)) {
                    los.emplace(a);
                    lo += ABS(med - a);
                }
                else {
                    i64 med_new = POP(los);
                    i64 d = ABS(med - med_new);
                    lo += ABS(med_new - a);
                    lo -= d;
                    hi += d;
                    lo -= SIZE(los) * d;
                    hi += SIZE(his) * d;
                    los.emplace(a);
                    his.emplace(med);
                    med = med_new;
                }
            }
            else if(a > med) {
                if(SIZE(los) >= SIZE(his)) {
                    his.emplace(a);
                    hi += ABS(med - a);
                }
                else {
                    i64 med_new = POP(his);
                    i64 d = ABS(med - med_new);
                    hi += ABS(med_new - a);
                    hi -= d;
                    lo += d;
                    hi -= SIZE(his) * d;
                    lo += SIZE(los) * d;
                    his.emplace(a);
                    los.emplace(med);
                    med = med_new;
                }
            }
        }
        else if(cmd == 2) {
            PRINTLN(med, lo + hi + b);
        }
        else {
            ASSERT(false);
        }
    }

    // * 小さいケースで試した?
