template<class T>using p_queue = std::priority_queue<T, std::vector<T>, std::greater<>>;
template<class T>class binary_indexed_tree
{
	typedef T type;
	std::vector<type> ar;
	std::size_t size;
public:
	binary_indexed_tree(std::size_t size_) :ar(size_), size(size_)
	{

	}
	void add(type val, int index)
	{
		++index;
		while (index <= size)
		{
			ar[index - 1] += val;
			index += index & -index;
		}
	}
	auto get(int index)const
	{
		++index;
		type ret{};
		while (index != 0)
		{
			ret += ar[index - 1];
			index -= index & -index;
		}
		return ret;
	}
	auto operator[](int index)const
	{
		if (index == 0)
		{
			return get(0);
		}
		else
		{
			return get(index) - get(index - 1);
		}
	}
};
struct merge_query
{
	std::int64_t a;
	std::int64_t b;
};

struct output_query
{

};
typedef boost::variant<merge_query, output_query> query;

struct operation_t
{
	binary_indexed_tree<int> count;
	binary_indexed_tree<std::int64_t> sum;
	std::map<std::int64_t, int> indexes;
	std::vector<std::int64_t> values;
	int sz;
	std::int64_t constant;
	operation_t(std::map<std::int64_t, int>&& index, std::vector<std::int64_t>&& vs, int size) :
		count(size), 
		sum(size), 
		indexes(std::move(index)),
		values(std::move(vs)),
		sz(size),
		constant()
	{

	}
	void operator()(merge_query const& q)
	{
		auto a = q.a;
		auto b = q.b;
		auto i = indexes[a];
		count.add(1, i);
		sum.add(a, i);
		constant += b;
	}
	void operator()(output_query const&)
	{
		auto max = count.get(sz - 1);
		auto rng = boost::irange(0, sz);
		auto i = *std::partition_point(rng.begin(), rng.end(), [&](int i)
			{
				auto v = count.get(i);
				return v < max - v;
			});
		auto left = sum.get(i);
		auto right = sum.get(sz - 1) - left;
		auto c = count.get(i);
		auto d = max - c;
		auto v = (c - d) * values[i] + right - left + constant;
		std::cout << values[i] << " " << v << std::endl;
	}
};

void Main()
{
	int Q;
	std::cin >> Q;
	std::set<std::int64_t> as;
	std::vector<query> queries;
	for (int i : boost::irange(0, Q))
	{
		int q;
		std::cin >> q;
		if (q == 1)
		{
			std::int64_t a, b;
			std::cin >> a >> b;
			queries.emplace_back(merge_query{ a,b });
			as.emplace(a);
		}
		else
		{
			queries.emplace_back(output_query{});
		}
	}
	std::map<std::int64_t, int> indexes;
	std::vector<std::int64_t> values;
	indexes[-1000000001] = 0;
	values.emplace_back(0);
	int index = 1;
	for (auto a : as)
	{
		indexes[a] = index;
		values.emplace_back(a);
		++index;
	}
	operation_t op(std::move(indexes), std::move(values), index);
	for (auto const& q : queries)
	{
		boost::apply_visitor(op, q);
	}
}

