typedef priority_queue<ll, vector<ll>, greater<ll> > PQ_ASK;

ll f(vector<P> &fs, int k, ll x) {
    if (k == 0) return 0;
    return f(fs, k - 1, x) + abs(x - fs[k - 1].first) + fs[k - 1].second;
}

struct Half {

    priority_queue<ll> left;
    PQ_ASK right;

    ll left_sum = 0, right_sum = 0;

    ll half() {
        if (left.empty()) return 0;
        return left.top();
    }

    void right_push(ll v) {

        right.push(v);
        right_sum += v;
        while (left.size() < right.size()) {

            left_sum += right.top();
            right_sum -= right.top();

            left.push(right.top());
            right.pop();
        }
    }

    void left_push(ll v) {
        left.push(v);
        left_sum += v;
        while (left.size() > right.size() + 1) {
            right_sum += left.top();
            left_sum -= left.top();
            right.push(left.top());
            left.pop();
        }
    }

    void push(ll v) {
        if (v >= half()) {
            right_push(v);
        } else {
            left_push(v);
        }

    }


    ll diffSum() {
        ll rdiffsum = right_sum - half() * right.size();
        ll ldiffsum = half() * left.size() - left_sum;
        return rdiffsum + ldiffsum;
    }

};

