using namespace std;

int main()
{
    IOS;
    int q;
    cin>>q;
    ll a,b,t,sl=0,sr=0,c=0,m;
    multiset<ll> s;
    while(q--)
    {
        cin>>t;
        if(t==1)
        {
            cin>>a>>b;
            c+=b;
            if(s.empty())
            {
                sl+=a;
                m=a;
                s.insert(a);
            }
            else{
                if(s.size()%2)
                {
                    multiset<ll>::iterator it=s.lower_bound(a);
                    if(m>=*it)
                    {
                        sl+=a;
                        s.insert(a);
                        sl-=m;
                        sr+=m;
                        it=s.lower_bound(m);
                        if(m!=a) --it;
                        m=*it;
                    }
                    else{
                        sr+=a;
                        s.insert(a);
                    }
                }
                else{
                    multiset<ll>::iterator it=s.lower_bound(a);
                    if(it==s.end() || *it>m)
                    {
                        sr+=a;
                        s.insert(a);
                        it=s.upper_bound(m);
                        sr-=*it;
                        sl+=*it;
                        m=*it;
                    }
                    else{
                        s.insert(a);
                        sl+=a;
                    }
                }
            }
        }
        else{
            int nr=s.size()/2;
            int nl=s.size()-nr;
            //cout<<nl<<" "<<nr<<endl;
            cout<<m<<" "<<(nl-nr)*m-sl+sr+c<<endl;
        }
    }
    return 0;
}

