//BIT
class BinaryIndexedTree{
  int N;
  vector<int> BIT;

  public:  

  BinaryIndexedTree(int n):BIT(n+1,0){ N = n; }//1-indexed
  BinaryIndexedTree(vector<int> v):BIT(v.size()+1,0){
    N = v.size();
    for(int i=1; i<=N; i++){
      add(i,v[i-1]); 
    }
  }

  void add(int x, int y){//0-indexed originから呼び出される時
    for(int i=x+1; i <= N; i += i&-i){
      BIT[i] += y;
    }
  }

  int sum(int x){
    int ret = 0;
    for(int i=x+1; i>0; i -= i&-i){
      ret += BIT[i];
    }
    return ret;
  }

  inline int operator [] (int index) const{//読み取り
     return BIT[index];
  }
  inline int& operator [] (int index){//書き取り
     return BIT[index];
  }
};

//座標圧縮
class CC{
  public:
  map<ll,int> mp;//0-indexed
  bool isUnique = true;

  CC(vector<ll> v){//座標圧縮が必要になるのはlonglongintの時が多い？
    sort(v.begin(),v.end());
    auto result = unique(v.begin(),v.end());
    isUnique = (result == v.end());
    v.erase(result, v.end());//重複を除いてもmapから参照できる。

    for(int i=0; i<v.size(); i++){
      mp.emplace_hint(mp.end(),v[i],i);
    }
  }

  ll getKey(int value){//keyが必要な場合は座標圧縮前のベクトルから参照できるため、これは不要？
    return next(mp.begin(), value)->first; 
  }

  /*
  inline int operator [] (ll index) const{//読み取り
     if(mp.find(index) != mp.end()) return mp[index];
     else{ return -1;}
  }
  */
};

int main()
{
  //方針
  //クエリ1:aはBITに追加。bは和をとる。
  //クエリ2:aの個数の偶奇で場合分け。中央値に対して新しく追加されたaの大小で場合分け。
  cin.tie(0);
  ios::sync_with_stdio(false);

  //input
  //クエリ
  int Q; cin >> Q;
  vector<ll> vt, va, vb;
  ll sum_a = 0, sum_b = 0;

  for(int i=0; i<Q; i++){
    int T; cin >> T; vt.pb(T);
    if(T == 1){
      int a, b; cin >> a >> b;
      va.pb(a);
      //sum_b += b;
      vb.pb(b);
    }else{
      continue; 
    }
  }

  //main
  int V = va.size();//Qが上界。
  ll center = 0;

  //まず座標圧縮
  CC cc(va);
  /*for(int i=0; i<V; i++){
    va[i] = cc.mp[va[i]];//圧縮した座標を代入。
  }*/

  //aの個数を管理。
  BinaryIndexedTree bit(V);
  int c = 0;

  for(int i=0; i<Q; i++){
    if(vt[i]==1){
      bit.add(cc.mp[va[c]],1); 
      sum_b += vb[c];

      if(c == 0){
        center = va[c];
      }else if((c+1)%2){//aが偶数から奇数になる。
        if(va[c]<=center){//左側
          //center = center;
          sum_a += abs(va[c]-center);
        }else{//右側
          //最小値を求める時
          ll ok = V+1;//解が存在する最大値
          ll ng = -1;//解が存在しない最小値
          /*
          //最大値を求める時
          ll ok = -1;//解が存在する最小値
          ll ng = 1e18;//解が存在しない最大値
          */

          while(abs(ok-ng) > 1){
            ll mid = (ok+ng)/2;
            if(bit.sum(mid) >= c/2+1){//((C+1)+1)/2
              ok = mid; 
            }else{
              ng = mid;
            }
          }

          center = cc.getKey(ok);
          sum_a += abs(va[c]-center);
        }
      }else{//aが奇数から偶数になる。
        if(va[c]>=center){//右側
          //center = center;
          sum_a += abs(va[c]-center);
        }else{//左側
          //最小値を求める時
          ll ok = V+1;//解が存在する最大値
          ll ng = -1;//解が存在しない最小値
          /*
          //最大値を求める時
          ll ok = -1;//解が存在する最小値
          ll ng = 1e18;//解が存在しない最大値
          */

          while(abs(ok-ng) > 1){
            ll mid = (ok+ng)/2;
            if(bit.sum(mid) >= (c+1)/2){
              ok = mid; 
            }else{
              ng = mid;
            }
          }

          ll g = abs(center-cc.getKey(ok));
          center = cc.getKey(ok);
          sum_a += (abs(va[c]-center) + g);
        }
      }
      //cout << va[c] << " " << c << endl;
      c ++;
    }else{//クエリ2
      cout << center << " " << sum_a+sum_b << endl;
    }
  }

  // output
  return 0;
}

