  cin >> Q;

  priority_queue<ll> Q0;
  priority_queue<ll, vector<ll>, greater<ll>> Q1;
  ll A0 = 0, A1 = 0, B = 0;
  for (ll i = 0; i < Q; i++)
  {
    ll q;
