struct BIT {
	int N;
	using TYPE = int;
	std::vector<TYPE> bit;
	BIT() : N(0) {}
	BIT(int n) : N(n), bit(N + 1, 0) {}
	BIT(int n, TYPE init) : N(n), bit(N + 1, init) {}

	// bit[i] += w;
	void add(int i, TYPE w) {
		for (int x = ++i; x <= N; x += x & -x) bit[x] += w;
	}
	// return sum [0, i);
	TYPE sum(int i) {
		TYPE res = 0;
		for (int x = i; x > 0; x -= x & -x) res += bit[x];
		return res;
	}
	// return sum [i, j);
	TYPE sum(int i, int j) {
		return sum(j) - sum(i);
	}
	const TYPE& operator[](const int& i) const {
		return bit[i];
	}
};

signed main() {
	INIT;

	struct Query {
		int t, a, b;
	};

	VAR(int, Q);
	V<Query> q(Q);
	REP(i, Q) {
		VAR(int, t);
		int a = -1, b = -1;
		if (t == 1) std::cin >> a >> b;
		q[i] = Query{ t, a, b };
	}

	std::map<int, int> map;
	int sz = 0;
	{
		REP(i, Q) {
			if (q[i].t == 1) map[q[i].a];
		}
		for (auto& p : map) p.second = sz++;
	}
	BIT bit(sz + 1);

	int sum = 0;
	std::set<int> set;
	int cnt = 0;
	int now = 0;
	int low = 0;
	{
		sum += q[0].b;
		set.insert(q[0].a);
		now = q[0].a;
		bit.add(map[q[0].a], 1);
	}
	FOR(i, 1, Q) {
		int type = q[i].t, a = q[i].a, b = q[i].b;

		if (type == 1) {
			sum += b;
			low += std::abs(now - a);
			bit.add(map[a], 1);
			set.insert(a);
			[&]{
				auto it = set.upper_bound(now);
				if (it == set.end()) return;
				int to = *it;
				int tlow = low;
				tlow += (to - now) * bit.sum(map[to]);
				tlow -= (to - now) * bit.sum(map[to], sz + 1);
				if (low > tlow) {
					now = to;
					low = tlow;
				}
			}();
			[&]{
				auto it = std::prev(set.lower_bound(now));
				if (it == set.end()) return;
				int to = *it;
				int tlow = low;
				tlow += (to - now) * bit.sum(map[to] + 1);
				tlow -= (to - now) * bit.sum(map[to] + 1, sz + 1);
				if (low >= tlow) {
					now = to;
					low = tlow;
				}
			}();
		}
		else {
			OUT(now)SP OUT(low + sum)BR;
		}
	}

	return 0;
}

