signed main() {

	int Q;
	cin >> Q;

	priority_queue<int> down;	// 大きい順に取り出せる。medianはこっちに入れる。
	priority_queue<int, vector<int>, greater<>> up;	// 小さい順に取り出せる
	int downsum = 0, upsum = 0;

	int sum = 0;
	while (Q--) {
		int kind;
		cin >> kind;
		if (kind == 1) {
			int a, b;
			cin >> a >> b;
			sum += b;

			if (down.size() == 0) {
				down.push(a);
				downsum += a;
				continue;
			}

			if (down.size() == up.size()) {
				if (a <= down.top()) {
					// dddd|uuuu -> dddad|uuuu
					down.push(a);	downsum += a;
				}
				else {
					// dddd|uuuu -> ddddu|uauu
					down.push(up.top());	downsum += up.top();
					up.pop();				upsum -= up.top();

					up.push(a);				upsum += a;
				}
			}
			else if (down.size() == up.size() + 1) {
				if (a <= down.top()) {
					// dddd|uuu -> ddad|duuu
					up.push(down.top());	upsum += down.top();
					down.pop();				downsum -= down.top();

					down.push(a);			downsum += a;
				}
				else {
					// dddd|uuu -> dddd|uauu
					up.push(a);		upsum += a;
				}
			}
			else {
				assert(1);
			}

		}
		else {
			int median = down.top();
			int ans = sum;
			ans += upsum - (int)up.size() * median;
			ans += (int)down.size() * median - downsum;
			cout << median << " " << ans << endl;
		}
	}


	return 0;
}

