int main() {
    int Q;
    cin >> Q;
    vector<P> ans;
    priority_queue<ll, vector<ll>, greater<ll>> gq;
    priority_queue<ll> lq;
    ll B = 0;
    ll G = 0;
    ll L = 0;
    for (int q = 0; q < Q; q++) {
        int c;
        cin >> c;

        if (c == 1) {
            int a, b;
            cin >> a >> b;
            B += b;
            if (lq.empty() || gq.empty()) {
                lq.push(a);
                L += a;
            } else {
                if (gq.top() <= a) {
                    gq.push(a);
                    G += a;
                } else {
                    lq.push(a);
                    L += a;
                }
            }
            if (lq.size() + 1 <= gq.size()) {  // g が多くなっている
                ll now = gq.top();
                gq.pop();
                lq.push(now);
                L += now;
                G -= now;
            } else if (lq.size() > gq.size() + 1) {
                ll now = lq.top();
                lq.pop();
                gq.push(now);
                L -= now;
                G += now;
            }
            //cout << lq.size() << " " << gq.size() << " " << L << " " << G << " " << B << endl;
        } else if (c == 2) {
            ll now = lq.top();
            ans.push_back(make_pair(now, B + G - now * gq.size() + now * lq.size() - L));
        }
    }
    for (auto i : ans) {
        cout << i.first << " " << i.second << "\n";
    }
}

