void _main()
{
    ll qcnt; llin(qcnt);

    ll bsum = 0LL;

    priority_queue<ll> qleft;
    priority_queue_incr<ll> qright;
    ll sum = 0LL;

    rep (i, qcnt) {
        ll type; llin(type);

        if (type == 2LL) {
            printf("%lld %lld\n", qleft.top(), sum + bsum);
            continue;
        }

        ll a; llin(a);
        ll b; llin(b);

        bsum += b;

        if (qleft.empty()) {
            qleft.push(a);
            continue;
        }
        if (qright.empty()) {
            ll old = qleft.top(); qleft.pop();
            qleft.push(min(a, old));
            qright.push(max(a, old));
            sum = abs(a - old);
            continue;
        }

        ll leftval = qleft.top();
        ll rightval = qright.top();
        assert(leftval <= rightval);
        ll old_x = leftval;

        if (a < leftval) {
            if (qleft.size() == qright.size()) {
                qleft.push(a);
                sum += (old_x - a);
            }
            else {
                qleft.pop();
                ll cnt = qleft.size();
                assert(cnt == qright.size());
                qright.push(old_x);
                qleft.push(a);
                ll new_x = qleft.top();
                assert(new_x <= old_x);
                sum -= (old_x - new_x) * cnt;
                sum += (old_x - new_x) * cnt;
                sum += (new_x - a);
                sum += (old_x - new_x);
            }
        }
        if (leftval <= a && a < rightval) {
            if (qleft.size() == qright.size()) {
                ll new_x = a;
                ll cnt = qleft.size();
                assert(cnt == qright.size());
                qleft.push(a);
                assert(old_x <= new_x);
                sum += (new_x - old_x) * cnt;
                sum -= (new_x - old_x) * cnt;
            }
            else {
                qright.push(a);
                sum += (a - old_x);
            }
        }
        if (rightval <= a) {
            if (qleft.size() == qright.size()) {
                ll cnt = qleft.size();
                ll new_x = qright.top(); qright.pop();
                qleft.push(new_x);
                qright.push(a);
                assert(old_x <= new_x);
                sum += (new_x - old_x) * cnt;
                sum -= (new_x - old_x) * cnt;
                sum += (a - new_x);
            }
            else {
                qright.push(a);
                sum += (a - old_x);
            }
        }
    }
}

