struct BIT{
private:
    vector<ll> bit;
    int N;
public:
    BIT(){init();}
    BIT(int N):N(N){init();}
    void init(){
        bit.clear();
        bit.resize(N+1,0);
    }
    ll sum(int i){
        ll s = 0;
        while(i>0){
            s += bit[i];
            i -= i&-i;
        }
        return s;
    }
    ll sum_range(int l,int r){
        return (sum(r)-sum(l-1));
    }
    void add(int i,ll x){
        while(i<=N){
        bit[i] += x;
        i += i&-i;
        }
    }
    ll sum0(int i){
        return sum(i+1);
    }
    void add0(int i,ll x){
        add(i+1,x);
    }
};


