using namespace std;
typedef long long ll;
const int mod = 1e9 + 7, INF = 1e9;
const int N = 100010;
int n;
ll sum = 0, Now = 0;
ll s[N * 40], sz[N * 40];
int tot = 0, rt, lf[N * 40], rf[N * 40];

void mdy(int &u, int l, int r, int x) {
	if(!u) u = ++tot; if(l >= r) { ++sz[u], s[u] += x; return ; }
	int mid = (l + r) >> 1;
	x <= mid ? mdy(lf[u], l, mid, x) : mdy(rf[u], mid + 1, r, x);
	s[u] = s[lf[u]] + s[rf[u]], sz[u] = sz[lf[u]] + sz[rf[u]];
}
int find(int u, int l, int r, int x) {
	if(l >= r) return l;
	int mid = (l + r) >> 1;
	if(sz[lf[u]] >= x) return find(lf[u], l, mid, x);
	return find(rf[u], mid + 1, r, x - sz[lf[u]]);
}
ll ask(int u, int l, int r, int x) {
	if(l >= r) return 0;
	int mid = (l + r) >> 1; ll ss = 0;
	if(x <= mid) {
		ss += s[rf[u]] - sz[rf[u]] * x;
		return ask(lf[u], l, mid, x) + ss;
	}
	ss += sz[lf[u]] * x - s[lf[u]];
	return ask(rf[u], mid + 1, r, x) + ss;
}
int main() {
	scanf("%d", &n);
	for(int opt; n; n--) {
		scanf("%d", &opt);
		if(opt == 1) {
			int x, y; scanf("%d%d", &x, &y);
			Now += y, mdy(rt, -INF, INF, x);
		}
		else {
			int x = find(rt, -INF, INF, (sz[rt] + 1) / 2);
			printf("%d %lld\n", x, Now + ask(rt, -INF, INF, x));
		}
	}
	return 0;
}

