template <typename T, typename Pr = less<T>>
class pqueue {
public:
	pqueue() : total_(T()) {}
	void   push(T x)     { total_ += x;             values_.push(x); }
	void   pop()         { total_ -= values_.top(); values_.pop(); }
	T      top()   const { return values_.top(); }
	bool   empty() const { return values_.empty(); }
	T      total() const { return total_; }
	size_t size()  const { return values_.size(); }
private:
	priority_queue<T, vector<T>, Pr> values_;
	T total_;
};


int main(int argc, char** argv) {
    int Q, qtype;

    cin >> Q;

	pqueue<long long, less<long long>> first_half;
	pqueue<long long, greater<long long>> last_half;
	long long a, b, b_sum = 0;


	for (int i = 0; i < Q; i++) {
		cin >> qtype;

		if (qtype == 1) {
			cin >> a >> b;

			if (first_half.size() <= last_half.size()) {
				first_half.push(a);
			}
			else {
				last_half.push(a);
			}

			// swap
			if (!first_half.empty() && !last_half.empty() &&  first_half.top() > last_half.top()) {
				first_half.push(last_half.top());
				last_half.pop();
				last_half.push(first_half.top());
				first_half.pop();
			}
			b_sum += b;
		}
		else {
			auto median = first_half.top();

			auto sum = (first_half.size() * median - first_half.total()) + (last_half.total() - last_half.size() * median) + b_sum;

			cout << median << ' ' << sum << endl;
		}
	}
}

