int main() {
    ll Q;
    cin >> Q;
    V<TLL> query;
    V<ll> nlis;
    for(ll i = 0; i < Q; i++) {
        ll q;
        cin >> q;
        if(q == 1) {
            ll a, b;
            cin >> a >> b;
            query.emplace_back(q, a, b);
            nlis.push_back(a);
        } else {
            query.emplace_back(q, 0, 0);
        }
    }

    {
        sort(ALL(nlis));
        auto ite = unique(ALL(nlis));
        nlis.erase(ite, nlis.end());
    }

    auto get_idx = [&](ll n) {
        return distance(nlis.begin(),
                        lower_bound(ALL(nlis), n));
    };

    Bit<ll> bt(nlis.size() + 10, 0);
    ll asum = 0;
    ll bsum = 0;
    ll cnt = 0;


    for(const auto ele : query) {
        ll q, a, b;
        tie(q, a, b) = ele;
        if(q == 1) {
            bt.add(get_idx(a), 1);
            asum += a;
            bsum += b;
            cnt++;
            continue;
        }
        ll xidx0 = 0, xidx3 = nlis.size() - 1;
        auto calc_f = [&](ll xidx) {
            ll cnt_p = bt.sum(0, xidx);
            ll cnt_m = cnt - cnt_p;
            ll x = nlis[xidx];
            return asum + cnt_p * x - cnt_m * x + bsum;
        };
        while(abs(xidx0 - xidx3) > 3) {
            ll dic = xidx3 - xidx0;
            ll xidx1 = xidx0 + dic / 3;
            ll xidx2 = xidx0 + dic * 2 / 3;
            ll f1 = calc_f(xidx1);
            ll f2 = calc_f(xidx2);
            if(f1 < f2) xidx3 = xidx2;
