                    base += b[i] + a[i]-mr;
                    r.insert(a[i]);
                    mr = *r.begin();
                }
            } else {
                if (ml <= a[i] && a[i] <= mr) {
                    l.insert(-ml);
                    r.insert(mr);
                    ml = mr = a[i];
                    base += b[i];
                } else if (a[i] < ml) {
                    base += b[i] + ml-a[i];
                    r.insert(mr);
