ll sumL, sumR, sumb, tot;
multiset<int> L, R;
void insert(int a)
{
	if(R.empty() || a < *R.begin())
	{
		L.insert(a);
		sumL += a;
	}
	else
	{
		R.insert(a);
		sumR += a;
	}
	if(L.size() == R.size() + 2)
	{
		auto it = L.rbegin();
		int rmid = *it;
		R.insert(rmid);
		L.erase((++it).base());
		sumR += rmid;
		sumL -= rmid;
	}
	if(R.size() == L.size() + 1)
	{
		int mid = *R.begin();
		L.insert(mid);
		R.erase(R.begin());
		sumL += mid;
		sumR -= mid;
	}
}
pii query()
{
	int mid = *L.rbegin();
	return mp(mid, (sumR - 1ll * R.size() * mid) + (1ll * L.size() * mid - sumL));
}
