#define MAX 200005
#define MOD 998244353
#define EPS 0.00000000001
#define INF 1000000000
map<int,int> M;
set<int> S;
pair<long long,int> segment_tree[MAX*4];
int values[MAX];
int n;
void update(int index,int l,int r,int ind)
{
    if(ind<l||ind>r) return;
    if(l==r)
    {
        segment_tree[index].second++;
        segment_tree[index].first=segment_tree[index].first+values[l];
        return;
    }
    int m=(l+r)/2;
    update(index*2,l,m,ind);
    update(index*2+1,m+1,r,ind);
    segment_tree[index].second=segment_tree[index*2].second+segment_tree[index*2+1].second;
    segment_tree[index].first=segment_tree[index*2].first+segment_tree[index*2+1].first;
}
pair<long long,int> query(int index,int l,int r,int ind)
{
    pair<long long,int> ans;
    if(l==r)
    {
        ans.first=ans.second=values[l];
        ans.first=ans.first*ind;
        return ans;
    }
    int m=(l+r)/2;
    if(segment_tree[index*2].second>=ind)
    {
        ans=query(index*2,l,m,ind);
    }
    else
    {
        ans=query(index*2+1,m+1,r,ind-segment_tree[index*2].second);
        ans.first=ans.first+segment_tree[index*2].first;
    }
    return ans;
}
