        cin >> x;
        query.push_back(x);
        if(x == 1){
            int aa, bb;
            cin >> aa >> bb;
            a.push_back(aa + UP);
            b.push_back(bb);
            za.push_back(aa + UP);
        }
    }
    sort(za.begin(), za.end());
    //za.erase(unique(za.begin(), za.end()), za.end());

    SegmentTree<int> seg1(za.size(), 0, marge);
    SegmentTree<int> seg2(za.size(), 0, marge);

    int ap = 0;
    int cnt = 0;
    int ans = 0;
    for(int p = 0;p < q;p++){
        if(query[p] == 1){
            seg1.add(lower_bound(za.begin(), za.end(), a[ap]) - za.begin(), 1);
            seg2.add(lower_bound(za.begin(), za.end(), a[ap]) - za.begin(), a[ap]);
            ans += b[ap];
            ap++;
            cnt++;
        }else{
            int l = 0;
            int r = za.size();
            while(r - l > 1){
                int mid = (r+l)/2;
