int main(){
  ll Q;
  cin >> Q;

  vll abox(0);
  priority_queue<Pll, vector<Pll>, greater<Pll>> ue;
  priority_queue<Pll> shita;
  ll uenum = 0, shitanum = 0;
  Pll mid = Pll(-1, -1);
  ll C = 0;
  ll sum = 0;
  vector<Pll> ans(0);
  for(int tmp = 0; tmp < Q; tmp++){
    int query;
    cin >> query;

    if(query == 1){
      ll a, b;
      cin >> a >> b;
      C += b;
      if(mid.first == -1){
        mid = Pll(a, 1);
      }
      else{
        if(a == mid.first) mid.second++;
        else if(a > mid.first){
          sum += a - mid.first;
          uenum++;
          ue.push(Pll(a, 1));
        }
        else{
          sum += mid.first - a;
          shitanum++;
          shita.push(Pll(a, 1));
        }
      }

      if(uenum > mid.second + shitanum){ //上が大きくなりすぎた
        ll newmid = ue.top().first;
        ll newmidnum = ue.top().second;
        ue.pop();
        while(!ue.empty() && ue.top().first == newmid){
          newmidnum += ue.top().second;
          ue.pop();
        }
        sum -= (newmid - mid.first) * uenum;
        sum += (newmid - mid.first) * (shitanum + mid.second);
        uenum -= newmidnum;
        shitanum += mid.second;
        shita.push(mid);
        mid = Pll(newmid, newmidnum);
      }
      else if(uenum + mid.second <= shitanum){
        ll newmid = shita.top().first;
        ll newmidnum = shita.top().second;
        shita.pop();
        while(!shita.empty() && shita.top().first == newmid){
          newmidnum += shita.top().second;
          shita.pop();
        }
        sum += (mid.first - newmid) * (uenum + mid.second);
        sum -= (mid.first - newmid) * shitanum;
        shitanum -= newmidnum;
        uenum += mid.second;
        ue.push(mid);
        mid = Pll(newmid, newmidnum);
      }
    }
    else{
      ans.push_back(Pll(mid.first, sum+C));
    }
  }
  for(int i = 0; i < ans.size(); i++){
    cout << ans.at(i).first << ' ' << ans.at(i).second << endl;
  }
}

