    ll res = 0;
    priority_queue<ll, vector<ll>, less<ll> > pq_less;
    priority_queue<ll, vector<ll>, greater<ll> > pq_greater;
    ll sum_less = 0, sum_greater = 0;
    while(Q--){
        ll q;
