using namespace std;

class BIT {
public:
	int size_ = 0;
	vector<long long> bit;

	void init(int sz) {
		size_ = sz + 2;
		bit.resize(size_, 0);
	}
	void add(int pos, long long x) {
		pos++;
		while (pos <= size_) {
			bit[pos] += x;
			pos += (pos&-pos);
		}
	}
	long long sum(int pos) {
		pos++; long long s = 0;
		while (pos >= 1) {
			s += bit[pos];
			pos -= (pos&-pos);
		}
		return s;
	}
	long long getpoint(long long val) {
		long long cl = 0, cr = size_ + 1, cm, minx = (1 << 30);
		for (int i = 0; i < 25; i++) {
			cm = (cl + cr) / 2;
			long long v = sum(cm);
			if (v < val) { cl = cm; }
			else { cr = cm; minx = min(minx, cm); }
		}
		return minx;
	}
};

