	}
	sort(X.begin(), X.end());
	X.erase(unique(X.begin(), X.end()), X.end());

	Z1.init(X.size() + 2);
	Z2.init(X.size() + 2);

	for (int i = 1; i <= Q; i++) {
		if (ty[i] == 1) {
			K++; V += b[i];
			int pos1 = lower_bound(X.begin(), X.end(), a[i]) - X.begin();
			Z1.add(pos1, 1);
			Z2.add(pos1, a[i]);
		}
		if (ty[i] == 2) {
			long long pos = Z1.getpoint((K + 1) / 2);
			long long pos2 = Z1.sum(pos);
			long long v1 = Z2.sum(pos);
