int lsum = 0,rsum = 0;
priority_queue<int>l;
priority_queue<int,vector<int>,greater<int>>r;

void update_lsum(int t){
	if(l.size()==0)l.push(t);
	else if(l.top()<=t){
		lsum += abs(t - l.top()) * l.size();
		l.push(t);
	}else{
		lsum += abs(l.top() - t);
		l.push(t);
	}
}
void update_rsum(int t){
	if(r.size()==0)r.push(t);
	else if(r.top()>=t){
		rsum += abs(r.top() - t) * r.size();
		r.push(t);
	}else{
		rsum += abs(t - r.top());
		r.push(t);
	}
}

