template <typename T>
struct BIT {
private:
    vector<T> v;
public:
    BIT(int n) : v(n, 0) {}
    T sum(int i) {
        T s = 0;
        while (i > 0) {
            s += v[i];
            i = (i & (i + 1)) - 1;
        }
        return s;
    }
    void add(int i, T x) {
        while (i < (int)v.size()) {
            v[i] += x;
            i |= i + 1;
        }
    }
};

int main() {
    int q;
    cin >> q;
    struct Query {
        int k, a, b;
    };
    vector<Query> qa(q);
    vector<int> x;
    for (int i = 0; i < q; ++i) {
        cin >> qa[i].k;
        if (qa[i].k == 1) {
            cin >> qa[i].a >> qa[i].b;
            x.push_back(qa[i].a);
        }
    }

    sort(x.begin(), x.end());
    x.erase(unique(x.begin(), x.end()), x.end());

    BIT<int> bit(x.size()+2);
    int xt = lower_bound(x.begin(), x.end(), qa[0].a) - x.begin();
    bit.add(0, -1);
    bit.add(xt+1, 2);
    int prev = xt+1;
    ll c = qa[0].b;

    for (int i = 1; i < q; ++i) {
        if (qa[i].k == 2) {
            cout << x[prev-1] << " " << c << endl;
            continue;
        }
        int a = -bit.sum(prev-1), b = bit.sum(prev);
        int xt = lower_bound(x.begin(), x.end(), qa[i].a) - x.begin();
        bit.add(0, -1);
        bit.add(xt+1, 2);
        int l = 0, r = x.size()+1;
        while (r - l > 1) {
            int m = (r + l) / 2;
            if (bit.sum(m) >= 0) {
                r = m;
            } else {
                l = m;
            }
        }
        c += qa[i].b;
        c += abs(qa[i].a - x[r-1]);
        if (prev > r) {
            c += (ll)a * (x[prev-1] - x[r-1]);
        } else {
            c += (ll)b * (x[r-1] - x[prev-1]);
        }
        prev = r;
    }

    return 0;
}

