      rq.push(a);
      m.push_back(rq.top());
      rq.pop();
    } else {
      lq.push(a);
      m.push_back(lq.top());
      lq.pop();
      swap(m[0], m[1]);
    }
    mi += m[1] - m[0];
  } else {
