using namespace std;

int main(){
    ll q; cin >> q;
    ll sum = 0;
    priority_queue<ll,vector<ll>,less<ll>> up; ll up_sum = 0; // maxを優先
    priority_queue<ll,vector<ll>,greater<ll>> back; ll back_sum = 0; // minを優先
    rep(i,q){
        ll type; cin >> type;
        if(type == 1){
            ll a, b; cin >> a >> b;
            sum += b;
            if(up.size() > back.size()){
                ll check = up.top();
                if(a >= check){
                    back.push(a);
                    back_sum += a;
                }
                else{
                    up.pop();
                    up_sum -= check;
                    up.push(a);
                    up_sum += a;
                    back.push(check);
                    back_sum += check;
                }
            }
            else{
                if(up.empty()){
                    up.push(a);
                    up_sum += a;
                }
                else{
                    ll check = back.top();
                    if(a <= check){
                        up.push(a);
                        up_sum += a;
                    }
                    else{
                        back.pop();
                        back_sum -= check;
                        back.push(a);
                        back_sum += a;
                        up.push(check);
                        up_sum += check;
                    }
                }
            }
        }
        else{
            ll x = up.top();
            ll res = x*(ll)up.size()-up_sum + back_sum-x*(ll)back.size() + sum;
            cout << x << " " << res << endl;
        }
    }
    return 0;
}

