void balance(multiset<int>& l, multiset<int>& r, ll& lsum, ll& rsum) {
	while (l.size() > r.size() + 1) {
		auto it = --l.end();
		int tmp = *it;
		l.erase(it);
		r.insert(tmp);
		lsum -= tmp;
		rsum += tmp;
	}
	while (r.size() > l.size()) {
		auto it = r.begin();
		int tmp = *it;
		r.erase(it);
		l.insert(tmp);
		rsum -= tmp;
		lsum += tmp;
	}
}

