    std::multiset<ll> F, L;
    for (int q = 0, t; q < Q; q++) {
        std::cin >> t;
        if (t == 1) {
            ll a, b;
            std::cin >> a >> b;
            B += b;
            if ((F.size() + L.size()) % 2 == 0) {
                if (L.empty() or *L.begin() >= a) {
                    F.insert(a), FS += a;
                } else {
                    L.insert(a), LS += a;
                    const ll l = *L.begin();
                    FS += l, LS -= l;
                    L.erase(L.begin()), F.insert(l);
                }
            } else {
                if (*F.rbegin() <= a) {
                    L.insert(a), LS += a;
                } else {
                    F.insert(a), FS += a;
                    auto it = F.end();
                    it--;
                    const ll f = *it;
                    FS -= f, LS += f;
                    F.erase(it), L.insert(f);
                }
            }
        } else {
            const int FN = F.size(), LN = L.size();
            if (FN == 0) {
                std::cout << "0 0" << std::endl;
            } else {
                const ll f = *F.rbegin();
                std::cout << f << " " << FN * f - FS - LN * f + LS + B << std::endl;
            }
        }
    }
    return 0;
}

