struct SegmentTree {
private:
  int n;
  vector<pair<LL,LL>> node;
  vector<LL> pos;

public:
  SegmentTree(int sz, vector<LL> v) {
    n = 1; while(n < sz) n *= 2;
    node.resize(2*n-1, {0,0});
    pos = v;
  }

  LL get(int x) {
    LL ans=0;
    int p = x;
    x += (n - 1);
    ans += node[x].first*pos[p]+node[x].second;
    while(x > 0) {
      x = (x - 1) / 2;
      ans += node[x].first*pos[p]+node[x].second;
    }
    return ans;
  }

  void add(int a, int b, int x, int y, int k=0, int l=0, int r=-1) {
    if(r < 0) r = n;
    if(r <= a || b <= l) return;
    if(a <= l && r <= b){
      node[k].first += x;
      node[k].second += y;
      return;
    }
    add(a, b, x, y, 2*k+1, l, (l+r)/2);
    add(a, b, x, y, 2*k+2, (l+r)/2, r);
  }
};

struct SegmentTree2 {
private:
  int n;
  vector<int> node;

public:
  SegmentTree2(int sz) {
    n = 1; while(n < sz) n *= 2;
    node.resize(2*n-1, 0);
  }

  int get(int x) {
    int ans=0;
    x += (n - 1);
    ans += node[x];
    while(x > 0) {
      x = (x - 1) / 2;
      ans += node[x];
    }
    return ans;
  }

  void add(int a, int b, int k=0, int l=0, int r=-1) {
    if(r < 0) r = n;
    if(r <= a || b <= l) return;
    if(a <= l && r <= b){
      node[k]++;
      return;
    }
    add(a, b, 2*k+1, l, (l+r)/2);
    add(a, b, 2*k+2, (l+r)/2, r);
  }
};

