void solve() {
  int Q;
  cin >> Q;
  multiset<int> as;
  auto med = as.begin();
  int asum = 0, bsum = 0, cnt = 0;
  rep(_, Q) {
    int q;
    cin >> q;
    if(q == 1) {
      cnt++;
      int a, b;
      cin >> a >> b;
      as.insert(a);
      if(med != as.end()) {
        bool is_l = a < *med;
        asum += abs(a - *med);
        if(is_l && cnt % 2 == 0) {
          med--;
        } else if(!is_l && cnt % 2) {
          int tmp = *med;
          med++;
          asum -= *med - tmp;
        }
      } else {
        med--;
      }
      bsum += b;
    } else {
      COUT(*med, asum + bsum);
    }
  }
}


