template<class T> class Segment_Tree_Range_Sum_Query {
	size_t N,M;
	T ini;
	vector<T> node;

public:
	Segment_Tree_Range_Sum_Query(const vector<T> & ar, const T ini) : M(ar.size()), ini(ini) {
		for (N = 1; N < M; N *= 2);
		node.resize(2 * N - 1, ini);
		for (int i = 0; i < M; ++i) node[i + N - 1] = ar[i];
		for (int i = N - 2; i >= 0; --i) node[i] = node[2 * i + 1]+node[2 * i + 2];
	}

	Segment_Tree_Range_Sum_Query(const size_t M, const T ini) : M(M), ini(ini) {
		for (N = 1; N < M; N *= 2);
		node.resize(2 * N - 1, ini);
	}

	void update(size_t idx, const T var) {
		idx += (N - 1);
		node[idx] += var;
		while (idx > 0) {
			idx = (idx - 1) / 2;
			node[idx] = node[2 * idx + 1]+node[2 * idx + 2];
		}
	}

	T getvar(const int a, const int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = N;
		if (r <= a || b <= l) return ini;
		if (a <= l && r <= b) return node[k];
		T vl = getvar(a, b, 2 * k + 1, l, (l + r) / 2);
		T vr = getvar(a, b, 2 * k + 2, (l + r) / 2, r);
		return vl+vr;
	}

	T operator[](size_t idx) {
		return node[idx + N - 1];
	}

	T operator[](pair<size_t, size_t> p) {
		return getvar(p.first, p.second);
	}


	void print(){
		cout << "{ " << getvar(0,1);
		for(int i = 1; i < M; ++i) cout << ", " << getvar(i,i+1);
		cout << " }" << endl;
	}
};


//Seat Pressure O(NlogN)
template<class T> vector<int> Zarts(const vector<T> & ar, int cnt = 0) {
    vector<int> res;
    map<T, int> mp;
    for (auto &e : ar) mp[e] = 0;
    for (auto &e : mp) e.second = cnt++;
    for (auto &e : ar) res.push_back(mp[e]);
    return res;
}


int main() {
    int Q; cin >> Q;
    V<ll> q(Q),a(Q,0),b(Q,0);
    for(int i = 0; i < Q; ++i){
        cin >> q[i];
        if(q[i]==2) continue;
        cin >> a[i] >> b[i];
    }
    auto c = Zarts(a);
    map<ll,ll> mp;
    for(int i = Q-1; 0 <= i; --i) mp[c[i]] = a[i];
    Segment_Tree_Range_Sum_Query<ll> Seg1(Q,0),Seg2(Q,0);

    ll n = 0,sum = 0;
    for(int i = 0; i < Q; ++i){
        if(q[i]==1){
            n++;
            sum += b[i];
			Seg1.update(c[i],a[i]);
			Seg2.update(c[i],1);

        }
		if(q[i]==2){
			ll ok = Q,ng = 0,md;
			while(ok-ng>1){
				md = (ok+ng)/2;
				ll cnt = Seg2.getvar(0,md+1);
				ll m = (n/2) + (n%2?1:0);
				(cnt>=m?ok:ng) = md;
			}
			ll L = Seg2.getvar(0,ok)*mp[ok] - Seg1.getvar(0,ok);
			ll R = Seg1.getvar(ok+1,Q) - Seg2.getvar(ok+1,Q)*mp[ok];
			cout << mp[ok] << " " << L + R + sum << endl;
		}
    }

    return 0;
}

