int main() {
  using LL = long long;
  struct Query {LL n, a, b, g;};
  LL D = 1e9+1;

  int N;
  cin >> N;

  vector<Query> Q;
  for(auto i=0; i<N; ++i) {
    LL n, a, b, g = 0;
    cin >> n;
    if(n == 1) cin >> a >> b;
    else       a = b = g = 1;
    if(i)      g += Q.back().g;
    Q.push_back({n, a+D, b, g});
  }
  sort(begin(Q), end(Q), [](const auto& l, const auto& r) {
    if(l.g != r.g) return l.g < r.g;
    if(l.n != r.n) return l.n > r.n;
    if(l.a != r.a) return l.a < r.a;
    return l.b < r.b;
  });

  LL b = 0, e = 0;
  queue<LL> median;
  for(LL i=0; i<N; ++i) {
    auto q = Q[i];
    if(q.n == 1) {
      e = i;
    } else {
      median.emplace(Q[(b+e)/2].a);
      b = e = i + 1;
    }
  }

  vector<LL> p = {0, LL(1e9+D)};
  for(const auto& q: Q) if(q.n == 1) p.emplace_back(q.a);
  Compression<LL> comp(p);

  SegmentTree<LL> sum(comp.size()+1), num(comp.size()+1);
  auto f = [&](auto x) {return sum.sum(0, comp.size()) - x * num.sum(0, comp.size());};
  LL c = 0;
  for(const auto& q: Q) {
    if(q.n == 1) {
      c += q.b;
      sum.add(comp.index(q.a), q.a);
      num.add(comp.index(q.a), 1);
    } else {
      auto x = median.front(); median.pop();
      cout << x-D << " " << f(x)+c << endl;
    }
  }
}

