template <typename T, typename Pr = less<T>>
class pqueue {
public:
	pqueue() : total_(T()) {}
	void   push(T x)     { total_ += x;             values_.push(x); }
	void   pop()         { total_ -= values_.top(); values_.pop(); }
	T      top()   const { return values_.top(); }
	bool   empty() const { return values_.empty(); }
	T      total() const { return total_; }
	T      size()  const { return (T)values_.size(); }
private:
	priority_queue<T, vector<T>, Pr> values_;
	T total_;
};


int main(int argc, char** argv) {
    int Q, qtype;

    cin >> Q;

	pqueue<long long, less<long long>> fst_half;
	pqueue<long long, greater<long long>> lst_half;
	long long a, b, b_sum = 0;

	for (int i = 0; i < Q; i++) {
		cin >> qtype;

		if (qtype == 1) {
			cin >> a >> b;

			if (fst_half.size() <= lst_half.size()) {
				fst_half.push(a);
			}
			else {
				lst_half.push(a);
			}

			// swap
			if (!fst_half.empty() && !lst_half.empty() &&  fst_half.top() > lst_half.top()) {
				fst_half.push(lst_half.top()); lst_half.pop();
				lst_half.push(fst_half.top()); fst_half.pop();
			}
			b_sum += b;
		}
		else {
			long long median = fst_half.top();
			long long sum = (fst_half.size() * median - fst_half.total()) + (lst_half.total() - lst_half.size() * median) + b_sum;
			cout << median << ' ' << sum << endl;
		}
	}
}

