class MiddlePoint {
public:
	MiddlePoint() : N(0), sumQ2(0), sumQ1(0) {}
	void push(lolo a) {
		if (min(Q2.size(), Q1.size()) == 0) {
			if (Q2.empty()) {
				Q2.push(a);
				sumQ2 += a;
			}
			else {
				if (Q2.top() > a) {
					auto pv = Q2.top(); Q2.pop();
					Q2.push(a);
					Q1.push(pv);
					sumQ2 += a - pv;
					sumQ1 += pv;

				}
			}
			N += 1;
			return ;
		} /////////////////

		if (Q2.size() == Q1.size()) {
			// 下側のキューに値を入れたい
			if (Q2.top() > a) {
				auto pv = Q2.top();
				Q2.pop();
				Q1.push(pv);
				Q2.push(a);
				sumQ2 = sumQ2 - pv + a;
				sumQ2 += pv;
			}
			else {
				Q2.push(a);
				sumQ2 += a;
			}
		}
		else {
			// 上側のQ1に値を入れたい
			// 上側のQ1の方が値が小さい
			if (Q1.top() < a) {
				auto pv = Q1.top(); Q1.pop();
				Q1.push(a);
				Q2.push(pv);
				sumQ1 -= pv;
				sumQ1 += a;
				sumQ2 += pv;
			}
			else {
				Q1.push(a);
				sumQ1 += a;
			}
		}
		N += 1;
	}
	lolo getMiddle() const { return Q2.top(); }
	lolo getSumQ1() const { return sumQ1;  }
	lolo getSumQ2() const { return sumQ2;  }
	lolo getSize() const { return N; }
	lolo getQ1Size() const { return Q1.size(); }
	lolo getQ2Size() const { return Q2.size(); }
	priority_queue<lolo, vector<lolo>, greater<lolo>> Q1; // 小さい方から抜けてく。上側のキュー
	priority_queue<lolo> Q2;														  // 大きい方から抜けてく。 下側のキュー
	lolo N;
	//lolo data;
	lolo sumQ2;
	lolo sumQ1;
};


int main()
{
	lolo Q;
	cin >> Q;

	MiddlePoint	gm;

	lolo sumB = 0;
	FOR(i, Q) {
		lolo c, A, B; // |X-A| + B
		cin >> c;
		if (c == 1) {
			cin >> A >> B;
			gm.push(A);
			sumB += B;
		}
		else {
			// 下側midlepointの座標を 全体サイズは gm.getSize()
			//auto Sum = gm.GetMiddle() * ( Q2の個数 - Q1の個数) + sumB - Q2の合計 + Q1の合計
			lolo idx = -1;
			auto size = gm.getSize();
			if (size % 2 == 0) {
				idx = size / 2 - 1;
			}
			else {
				idx = size / 2;
			}

			lolo Sum = gm.getMiddle() * (gm.getQ2Size() - gm.getQ1Size()) + sumB - gm.getSumQ2() + gm.getSumQ1();
			cout << gm.getMiddle() << " " << Sum << endl;
		}
	}
}

