// TernarySearch,三分探索 (下に凸な整数関数 TX -> TY の極値を求める)
// left: 値の下限
// right: 値の上限
// get: 対象となる関数(上に凸の場合は返り値にマイナスを付けること)
// eps: 終了距離
template <typename TX, typename TY = TX>
pair<TX, TX> TerSearch(TX left, TX right, function<TY(TX)> get, TX eps) {
    while (right - left > eps) {
        TX lmid = (right + 2 * left) / 3;
        TX rmid = (left + 2 * right) / 3;
        TY j = get(lmid) - get(rmid);
        if (j >= 0) left = lmid;
        if (j < 0) right = rmid;
    }
    return make_pair(left, right);
}

// 二分探索（改）
// judge を満たすような下限を求める
// left:[X] 定義域の下限
// right:[X] 定義域の上限
// judge:[X -> bool] X を評価する関数
// lower:[bool] falseにすると代わりに上限を求める
// eps:[X] 終了距離

template <typename X>
X BinSearch(X left, X right, function<bool(X)> judge, bool lower = true, X eps = 1) {
    while (right - left > eps) {
        X mid = (right + left) / 2;
        if (judge(mid) == lower) {
            right = mid;
        } else {
            left = mid;
        }
    }
    return lower ? right : left;
}

