            i64 l, r;
            tie(l, r) = TerSearch<i64, i64>(-2e9, 2e9, f, 2);
            i64 K = min({f(l), f(l + 1), f(l + 2)});
            i64 ans = BinSearch<i64>(-2e9 - 1, r, [&](i64 x) -> bool {
                i64 y = f(x);
                return y == K;
            });
