class GetMiddle {
public: 
	GetMiddle() { N = 0; };
	void push(lolo a) {
		if (Q1.empty()) {
			Q1.push(a);
		}
		else if ( (Q1.size() == Q2.size() and Q1.top() <= a)) {
			// Q1に入れたいけど入れられないパターン？  Q2のtopの方が大きい
			auto pv = Q2.top(); Q2.pop();
			Q2.push(a);
			Q1.push(pv);
		}
		else if (Q2.empty() or Q1.size() > Q2.size() and Q2.top() < a) {
			Q2.push(a);
		}
		else if (Q1.size() > Q2.size() and Q2.top() >=  a) {
			// ならQ2に入れちゃえ
			// Q2に入れたいが、Q2のトップの方が大きい
			auto pv = Q2.top(); Q2.pop();
			Q2.push(a);
			Q1.push(pv);			
		}

		else if (Q1.size() == Q2.size()) {
			Q1.push(a);
		}
		else {
			throw "Error!";
		}
		N += 1;
	}
	lolo getM() {
		if (N % 2 == 0) {
			return Q2.top();
		}
		else {
			return Q1.top();
		}
		//return Q1.top();
	}
	lolo N;
	priority_queue<lolo> Q2; // 下側
	priority_queue<lolo, vector<lolo>, greater<lolo>> Q1; // 上側
};

