unsigned xor128() {
	static unsigned x = 123456789, y = 362436069, z = 521288629, w = 88675123;
	unsigned t = x ^ (x << 11);
	x = y; y = z; z = w;
	return w = w ^ (w >> 19) ^ (t ^ (t >> 8));
}

namespace randomized_binary_search_tree
{
	using T = ll;
	const T id = 0;
	T op(T l, T r) {
		return l + r;
	}

	struct node {
		T val, all;
		node *lch, *rch;
		int size;
		node(T v, node* l = nullptr, node* r = nullptr)
			: val(v), all(v), lch(l), rch(r), size(1) {}
	};

	int count(node *t) { return t ? t->size : 0; }
	T que(node *t) { return t ? t->all : id; }

	node *update(node *t) {
		t->size = count(t->lch) + count(t->rch) + 1;
		t->all = op(op(que(t->lch), t->val), que(t->rch));
		return t;
	}
	node *merge(node *l, node *r) {
		if (!l || !r) return !l ? r : l;
		if (xor128() % (l->size + r->size) < (unsigned)l->size) {
			l->rch = merge(l->rch, r);
			return update(l);
		}
		r->lch = merge(l, r->lch);
		return update(r);
	}
	pair<node*, node*> split(node *t, int k) {
		if (!t) return make_pair(nullptr, nullptr);
		if (k <= count(t->lch)) {
			pair<node*, node*> s = split(t->lch, k);
			t->lch = s.second;
			return make_pair(s.first, update(t));
		}
		pair<node*, node*> s = split(t->rch, k - count(t->lch) - 1);
		t->rch = s.first;
		return make_pair(update(t), s.second);
	}
	node *insert(node *t, int k, T v) {
		pair<node*, node*> s = split(t, k);
		node *r = merge(s.first, new node(v));
		r = merge(r, s.second);
		return r;
	}
	void update_val(node *t, int k, T v) {
		if (!t) return;
		int c = count(t->lch);
		if (k < c)
			update_val(t->lch, k, v);
		else if (k > c)
			update_val(t->rch, k - (c + 1), v);
		else
			t->val = v;
		t->all = op(op(que(t->lch), t->val), que(t->rch));
	}
	T find(node *t, int l, int r) {
		if (!t) return id;
		if (r <= 0 || count(t) <= l) return id;
		if (l <= 0 && count(t) <= r) return t->all;
		int c = count(t->lch);
		return op(find(t->lch, l, r), op(l <= c && c < r ? t->val : id, find(t->rch, l - (c + 1), r - (c + 1))));
	}
	int count_lower(node *t, T v) {
		if (!t) return 0;
		if (t->val < v) return count(t->lch) + 1 + count_lower(t->rch, v);
		if (t->val == v) return count(t->lch);
		return count_lower(t->lch, v);
	}
}

