            } else {
                if (query[i][1] <= left_que.top()) {
                    cur_pos++;
                    left_que.push(query[i][1]);
                    if (num % 2 == 1) {
                        right_que.push(left_que.top());
                        left_que.pop();
                    }
                } else {
