  long long sumh = 0;

  std::priority_queue<long long, std::vector<long long>, std::greater<long long>> gq;
  std::priority_queue<long long> sq;

  bool first = true;
  for (long long i = 0; i < q; ++i)
  {
    long long type;
    scanf("%lld", &type);
    if (type == 1)
    {
      long long a, b;
      scanf("%lld%lld", &a, &b);
      sum += a + b;
      if (first)
      {
        sumh += a;
        sq.emplace(a);
        first = false;
      }
      else if (gq.size() == sq.size())
      {
        if (gq.top() <= a)
        {
          sq.emplace(gq.top());
          sumh += gq.top();
          gq.pop();
          gq.emplace(a);
        }
        else
        {
          sq.emplace(a);
          sumh += a;
        }
      }
      else
      {
        if (sq.top() >= a)
        {
          gq.emplace(sq.top());
          sumh -= sq.top();
          sq.pop();
          sq.emplace(a);
          sumh += a;
        }
        else
        {
          gq.emplace(a);
        }
      }
    }
