struct SegmentTree{
    int numLeaves;
    std::vector<ll> data;

    SegmentTree(int n){
        numLeaves = 1;
        while(numLeaves < n){
            numLeaves *= 2;
        }

        data.resize(numLeaves * 2);
        std::fill(data.begin(), data.end(), 0);
    }

    void add(int k, ll v){
        k += numLeaves;
        data[k] += v;

        while(k > 1){
            k /= 2;
            data[k] = data[k*2] + data[k*2+1];
        }
    }

    ll sum(int l, int r){
        l += numLeaves;
        r += numLeaves;

        ll s = 0;

        for(;l<r;l/=2,r/=2){
            if(l & 1){
                s += data[l];
                l += 1;
            }

            if(r & 1){
                r -= 1;
                s += data[r];
            }
        }

        return s;
    }

    // [0, i] の和が v 以上である最小の i を計算する
    int lower_bound(int v){
        int index = 0;
        int k = 1;
        ll s = 0;

        while(k < numLeaves){
            index *= 2;

            if(s + data[k*2] < v){
                index += 1;
                s += data[k*2];
                k = k * 2 + 1;
            }else{
                k = k * 2;
            }
        }

        return index;
    }

    ll at(int k){
        return data[k + numLeaves];
    }
};

