	for (int i = 0; i < kkt; i++) {
		int t; cin >> t;
		vector<int> v; v.emplace_back(t);
		if (t == 1) {
			int a, b; cin >> a >> b;
			v.emplace_back(a);
			v.emplace_back(b);
			comp.add(a);
		}
		query[i] = move(v);
	}
	comp.build();
	BIT<ll> bc(comp.size()), bs(comp.size());
	ll cur = 0;
	int cnt = 0;
	for (auto& v : query) {
		if (v[0] == 1) {
			bc.add(comp.get(v[1]), 1);
			bs.add(comp.get(v[1]), v[1]);
			cur += v[2];
			cnt++;
		}
		else {
			int idx = bc.lower_bound((cnt + 1) / 2);
			ll mid = comp[idx];
			ll res = cur;
			res += bs.sum(idx + 1, comp.size()) - mid * bc.sum(idx + 1, comp.size()) + mid * bc.sum(0, idx) - bs.sum(0, idx);
			cout << mid << " " << res << "\n";
		}
	}
	return 0;
}

