    int q;
    cin >> q;
    priority_queue<ll> low;
    priority_queue<ll, vector<ll>, greater<ll>> high;
    ll mid = 0;
    ll ex = 0;
    ll low_s = 0;
    ll high_s = 0;
    q--;
    int i, j, k;
    cin >> i >> j >> k;
    mid = j;
    ex += k;
    while(q--)
    {
        int x;
        cin >> x;
        if(x == 2)
        {
            cout << mid << " " << ex + low_s + high_s << endl;
        }
        else if(x == 1)
        {
            int a, b;
            cin >> a >> b;
            ex += b;
            if(a >= mid)
            {
                high.push(a);
                high_s += a - mid;
                ll lsize = low.size();
                ll hsize = high.size();
                if(lsize + 2 == hsize)
                {
                    ll newmid = high.top();
                    low_s += lsize * (newmid - mid) + newmid - mid;
                    low.push(mid);
                    high_s -= (hsize-1) * (newmid - mid);
                    high_s -= (newmid - mid);
                    high.pop();
                    mid = newmid;
                }
            }
            else
            {
                ll bsize = low.size();
                ll hsize = high.size();
                low.push(a);
                low_s += mid - a;
                if(low.size() <= high.size()) continue;
                ll newmid = low.top();
                low_s -= bsize * (mid - newmid);
                high.push(mid);
                high_s += hsize * (mid - newmid);
                high_s += mid - newmid;
                mid = newmid;
                low.pop();
            }
        }
    }
}

