/* Fast I/O */
inline int scanInt() {
	int n = 0;
	char ch = getchar();
	int sign = 1;
	while(ch < '0' || ch > '9') {
		if(ch == '-')	sign = -1;
		ch = getchar();
	}
	while(ch >= '0' && ch <= '9') {
		n = (n<<1)+(n<<3)+(int)(ch-'0');
		ch = getchar();
	}
	return n*sign;
}

inline LL scanLong() {
	LL n = 0;
	char ch = getchar();
	LL sign = 1;
	while(ch < '0' || ch > '9') {
		if(ch == '-')	sign = -1;
		ch = getchar();
	}
	while(ch >= '0' && ch <= '9') {
		n = (n<<1)+(n<<3)+(LL)(ch-'0');
		ch = getchar();
	}
	return n*sign;
}

PLL solve(multiset<LL> As) {
	LL n = As.size();

	VLL presum; presum.push_back(0);
	srep(it, As.begin(), As.end())
		presum.push_back(presum.back() + (*it));

	LL minVal = LONG_MAX, minX = LONG_MIN;
	rep(i, 0, n+1) {
		LL cons = (presum[n] - 2 * presum[i]);
		LL coeff = 2*i - n;
		LL tempVal, tempX;
		if(coeff >= 0) {
			tempVal = cons + coeff * (presum[i]-presum[i-1]);
			tempX = (presum[i]-presum[i-1]);
		}
		else {
			tempVal = cons + coeff * (presum[i+1]-presum[i]);
			tempX = presum[i+1]-presum[i];
		}
		if(tempVal < minVal) {
			minVal = tempVal;
			minX = tempX;
		}
		else if(tempVal == minVal && tempX < minX)
			minX = tempX;
	}
	return MP(minX, minVal);
}

