ll k;
vector < ll > lst;
ll mini, maxi;
void update(int a, int b){
	mini = min(mini, (ll)a);
	maxi = max(maxi, (ll)a);
	lst.push_back(a);
	k += b;
}

ll f(ll x){
	ll ret = 0;
	for(int i=0; i<lst.size(); i++){
		ret += abs(lst[i] - x);
	}
	return ret + k;
}

void compare(ll& val, ll& x, ll v, ll m){
	if(val < v){
		val = v;
		x = m;
	}
	else if(val == v){
		x = min(x, m);
	}
}

pll ternary(ll l, ll r){
	ll lt = l, rt = r, m1, m2, ret = r;
	ll val = -OO, v1, v2;
	while(lt <= rt){
		m1 = lt + (rt - lt) / 3;
		m2 = rt - (rt - lt) / 3;
		v1 = f(m1);
		v2 = f(m2);
//		printf("m1 %lld %lld, m2 %lld %lld\n",m1,v1,m2,v2);
		if(v1 >= v2){
			rt = m2 - 1;
			compare(val, ret, v1, m1);
		}
		else{
			lt = m1 + 1;
			compare(val, ret, v2, m2);
		}
	}
	return make_pair(ret, val);
}

void query(){
	pll ret = ternary(mini, maxi);
	cout << ret.first << " " << ret.second << endl;
}

