#include "bits/stdc++.h"

using namespace std;

template <typename T>
struct BIT
{
	int N, K;
	vector<T> bit;

	BIT(int X)
	{
		bit = vector<T>(X + 1, 0);
		N = X + 1;
		K = pow(2, (int)(log(X) / log(2)));
	}

	void add(int idx, T w)
	{
		for (int x = idx; x <= N; x += x & -x)
		{
			bit[x] += w;
		}
	}

	T sum(int idx)
	{
		T res = 0;
		for (int x = idx; x > 0; x -= x & -x)
			res += bit[x];
		return res;
	}

	int lb(T w)
	{
		int k = K, idx = 0;

		while (k > 0)
		{
			if (idx + k <= N && w > bit[idx + k])
			{
				w -= bit[idx + k];
				idx += k;
			}
			k >>= 1;
		}

		return idx + 1;
	}
};

void solve(void)
{
	int q, x, a, b;
	cin >> q;
	vector<pair<int, pair<int, int>>> qs(q);
	set<int> s;
	for (int i = 0; i < q; i++)
	{
		cin >> x;
		if (x == 1)
		{
			cin >> a >> b;
			qs[i] = {x, {a, b}};
			s.insert(a);
		}
		else
		{
			qs[i] = {x, {0, 0}};
		}
	}
	int cnt = 0;
	map<int, int> mp, rev;
	for (int v : s)
	{
		mp[v] = ++cnt;
		rev[cnt] = v;
	}
	BIT<long> bitcnt(cnt), bitsum(cnt);
	long sumb = 0;
	int now = 0;
	for (auto &q : qs)
	{
		if (q.first == 1)
		{
			sumb += q.second.second;
			long z = q.second.first, v = mp[z];
			bitcnt.add(v, 1);
			bitsum.add(v, z);
			now++;
		}
		else
		{
			int idx = bitcnt.lb((now+1)/2);
			long res = sumb, rv = rev[idx];
			res += bitsum.sum(cnt) - 2*bitsum.sum(idx) + (bitcnt.sum(idx)*2 - now) * rv;
			cout << rv << ' ' << res << endl;
		}
	}

}

