struct update
{
	std::int64_t a, b;
};
struct output
{

};
typedef boost::variant<update, output> query;
template<class T>class binary_indexed_tree
{
	typedef T type;
	std::vector<type> ar;
	std::size_t size;
public:
	binary_indexed_tree(std::size_t size_) :ar(size_), size(size_)
	{

	}
	void add(type val, int index)
	{
		++index;
		while (index <= size)
		{
			ar[index - 1] += val;
			index += index & -index;
		}
	}
	auto get(int index)const
	{
		++index;
		type ret{};
		while (index != 0)
		{
			ret += ar[index - 1];
			index -= index & -index;
		}
		return ret;
	}
};
struct operation
{
	binary_indexed_tree<int> count;
	binary_indexed_tree<std::int64_t> sum;
	std::map<std::int64_t, int> indexes;
	std::vector<std::int64_t> values;
	std::size_t size;
	std::int64_t update_count;
	std::int64_t constant;

	operation(
		std::map<std::int64_t, int>&& _indexes,
		std::vector<std::int64_t>&& _values,
		std::size_t _size) :
		count(_size),
		sum(_size),
		indexes(std::move(_indexes)),
		values(std::move(_values)),
		size(_size),
		update_count(),
		constant()
	{

	}

	void operator()(update const& q)
	{
		auto a = q.a;
		auto b = q.b;
		auto i = indexes[a];
		count.add(1, i);
		sum.add(a, i);
		constant += b;
		++update_count;
	}
	void operator()(output const&)
	{
		auto j = (update_count + 1) / 2;
		auto rng = boost::irange<std::size_t>(0, size);
		auto i = *std::partition_point(rng.begin(), rng.end(), [&](std::size_t k)
			{
				auto c = count.get(k);
				return c < j;
			});
		auto v = (2 * count.get(i) - update_count) * values[i] + sum.get(size - 1) - 2 * sum.get(i) + constant;
		std::cout << values[i] << " " << v << std::endl;
	}
};

void Main()
{
	int Q;
	std::cin >> Q;
	std::vector<query> queries;
	std::set<std::int64_t> as;
	for (int i : boost::irange(0, Q))
	{
		int q;
		std::cin >> q;
		if (q == 1)
		{
			std::int64_t a, b;
			std::cin >> a >> b;
			as.emplace(a);
			queries.emplace_back(update{ a,b });
		}
		else
		{
			queries.emplace_back(output{});
		}
	}
	std::map<std::int64_t, int> indexes;
	std::vector<std::int64_t> values;
	std::size_t index = 1;
	const std::int64_t min = -1000000000;
	indexes.emplace(min - 1, 0);
	values.emplace_back(min - 1);
	for (auto a : as)
	{
		indexes[a] = index;
		values.emplace_back(a);
		++index;
	}
	operation op(std::move(indexes), std::move(values), index);
	for (auto const& q : queries)
	{
		boost::apply_visitor(op, q);
	}
}

