int main(){
    ll Q;
    cin >> Q;

    priority_queue<ll> que1;
    priority_queue<ll, vector<ll>, greater<ll>> que2;

    ll sum1 = 0, sum2 = 0, bb = 0;

    REP(i, Q){
        ll q;
        cin >> q;
        if(q == 1){
            ll a, b;
            cin >> a >> b;
            bb += b;

            if(que1.empty()){
                que1.push(a);
                continue;
            }
            if(que2.empty()){
                que1.push(a);
                que2.push(que1.top());
                que1.pop();
                sum2 += que2.top() - que1.top();
                continue;
            }

            ll t1 = que1.top(), t2 = que2.top();
            if(a < t2){
                if(t1 < a){
                    sum1 += (a - t1) * que1.size();
                    sum2 -= (a - t1) * que2.size();
                    que1.push(a);
                }
                else{
                    sum1 += t1 - a;
                    que1.push(a);
                }

                if(que1.size() > que2.size() + 1){
                    ll t3 = que1.top(); que1.pop();
                    ll t4 = que1.top();
                    sum1 -= (t3 - t4) * que1.size();
                    que2.push(t3);
                    sum2 += (t3 - t4) * que2.size();
                }
            }
            else{
                sum2 += a - t1;
                que2.push(a);
                if(que1.size() < que2.size()){
                    sum2 -= (t2 - t1) * que2.size();
                    sum1 += (t2 - t1) * que1.size();
                    que1.push(t2);
                    que2.pop();
                }
            }
        }
        else{
            cout << que1.top() << " " << sum1 + sum2 + bb << endl;
        }
    }
}

