void solve(){
  int q; cin >> q;int sz = 0;
  std::multiset<ll> sl, sr; ll A = 0;ll B=0;
  sl.insert( -LINF); sr.insert( LINF );
  FOR(_,0,q){
    int qw; cin >> qw; 
    if(qw==1){
      ll a, b; cin >> a >> b;
      ll l_r = *sl.rbegin(), r_l = *sr.begin();
      if(a < l_r ){
        auto it = sl.end();
        --it;
        sl.erase( it, sl.end() );
        sr.insert( l_r );
        sl.insert( a);
        sl.insert( a);
        A += l_r - a;
      }
      else if(a > r_l){
        auto it = sr.begin();
        ++it;
        sr.erase( sr.begin(), it );
        sl.insert( r_l );
        sr.insert( a);
