	for(t[p+=n] += a;p>1;p >>= 1){
		t[p>>1] = t[p] + t[p^1];
	}
}

ll query(int l, int r){
	ll sum = 0;
	for(l += n, r += n; l<r; l >>= 1,r >>= 1){
		if(l&1) sum += t[l++];
		if(r&1) sum += t[--r];
	}
	return sum;
}
int midi(int x,int y){
	int l = 0,r = x;
	while(r - l>1){
		int mid = (l + r)/2;
		if(query(l,mid)>=(y + 1)/2) r = mid;
		else l = mid;
	}
	return l;
}

