using namespace std;

class median_tree{
public:
    priority_queue<int>lower_than_med,higher_than_med;
    int count=0;
    int low=0;
    int high=0;
    int median=0;
    int y;
    int push(int x){
        count=1-count;
        if (count){
            higher_than_med.push(-x);
            y=higher_than_med.top();
            higher_than_med.pop();
            lower_than_med.push(-y);
            low+=y;
            high+=x+y;
        }
        else{
            lower_than_med.push(x);
            y=lower_than_med.top();
            lower_than_med.pop();
            higher_than_med.push(-y);
            low-=x-y;
            high+=y;
        }
        median=lower_than_med.top();
        return 0;
    }
};

int main(void){
    int n;
    int tmp,a,b,B=0;
    median_tree m;
    cin>>n;
    for(int i=0  ;i<n  ;i++){
        cin>>tmp;
        if (tmp==1){
            cin>>a>>b;
            m.push(a);
            B+=b;
        }
        else{
            cout<<m.median<<" "<<m.median*m.count+B+m.low+m.high<<endl;
        }
    }
}

