struct data {
  // Use required attributes
  int mn;
  int cnt;
  int val;

  // Default Values
  data() : mn(0), cnt(0){};
};

struct SegTree {
  int N;
  vector<data> st;
  vector<bool> cLazy;
  vector<int> lazy;

  void init(int n) {
    N = n;
    st.resize(4 * N + 5);
    cLazy.assign(4 * N + 5, false);
    lazy.assign(4 * N + 5, 0);
  }

  // Write reqd merge functions
  void merge(data &cur, data &l, data &r) {
    cur.mn = l.mn + r.mn;
    cur.cnt = l.cnt + r.cnt;
  }

  // Handle lazy propagation appriopriately
  void propagate(int node, int L, int R) {
    st[node].mn += lazy[node];
    st[node].cnt += 1;
    cLazy[node] = 0;
    lazy[node] = 0;
  }

  void build(int node, int L, int R) {
    if (L == R) {
      st[node].mn = 1e9;
      return;
    }
    int M = (L + R) / 2;
    build(node * 2, L, M);
    build(node * 2 + 1, M + 1, R);
    merge(st[node], st[node * 2], st[node * 2 + 1]);
  }
  ll Query(int node, int L, int R, int pos) {
    if (L == R) {

      ll ans = st[node].mn / st[node].cnt;
      return ans * pos;
    }
    int M = (L + R) / 2;

    ll cnt = st[node * 2].cnt;
    if (pos <= cnt)
      return Query(node * 2, L, M, pos);
    else
      return st[node * 2].mn + Query(node * 2 + 1, M + 1, R, pos - cnt);
  }

  data pQuery(int node, int L, int R, int pos) {
    if (L == R) {
      st[node].val = L;
      return st[node];
    }
    int M = (L + R) / 2;

    ll cnt = st[node * 2].cnt;
    if (pos <= cnt)
      return pQuery(node * 2, L, M, pos);
    else
      return pQuery(node * 2 + 1, M + 1, R, pos - cnt);
  }

  void pUpdate(int node, int L, int R, int pos, int val) {
    if (cLazy[node])
      propagate(node, L, R);
    if (L == R) {
      cLazy[node] = 1;
      lazy[node] = val;
      propagate(node, L, R);
      return;
    }
    int M = (L + R) / 2;
    if (pos <= M)
      pUpdate(node * 2, L, M, pos, val);
    else
      pUpdate(node * 2 + 1, M + 1, R, pos, val);
    merge(st[node], st[node * 2], st[node * 2 + 1]);
  }

  ll query(int pos) { return Query(1, 1, N, pos); }

  data PQuery(int pos) { return pQuery(1, 1, N, pos); }

  void update(int pos, int val) { pUpdate(1, 1, N, pos, val); }
};

