  ll q;
  cin >> q;
  ll c = 0;

  ll query[q + 5][3];
  map<ll, ll> par;
  for (ll i = 1; i <= q; i++) {
    ll type;
    cin >> type;
    query[i][0] = type;
    if (type == 1) {
      ll a, b;
