      par[a];
      query[i][1] = a;
      query[i][2] = b;
    } else {
    }
  }
  ll cnt = 0;
  ll rm[q + 5];
  for (auto &it : par) {
    it.second = ++cnt;
    rm[cnt] = it.first;
  }

  SegTree obj;
  obj.init(q);
  c = 0;
  ll sz = 0;
  ll sum1 = 0;
  for (ll i = 1; i <= q; i++) {
    if (query[i][0] == 1) {

      ll a = query[i][1];
      c += query[i][2];
      obj.update(par[a], a);
      sz++;
      sum1 += a;
    } else {
      ll indx = sz / 2;

