int main() {
	int n, a, b, c;
	scanf("%d", &n);
	int cnt = 0;
	ll t = 0;
	ll res = 0;
	for (int i = 0; i < n; i++) {
		scanf("%d", &a);
		if (a == 1) {
			scanf("%d %d", &b, &c);
			t += c;
			cnt++;
			if (max_heap.size() == min_heap.size()) {
				if (min_heap.empty()) {
					max_heap.push({ b });
					res = 0;
				}
				else {
					if (min_heap.top().n > b) {
						max_heap.push({ b });
						res += max_heap.top() - b;
					}
					else {
						int tmp = min_heap.top().n;
						min_heap.pop();
						max_heap.push(tmp);
						min_heap.push({ b });
						res += b - max_heap.top();
					}
				}
			}
			else {
				if (max_heap.top() < b) {
					min_heap.push({ b });
					res += b - max_heap.top();
				}
				else {
					int tmp = max_heap.top();
					max_heap.pop();
					min_heap.push({ tmp });
					max_heap.push(b);
					res += min_heap.top().n - b;
				}
			}
		}
		else {
			int tmp = max_heap.top();
