void update() {
    B += b;
    if (mxh.empty()) {
        mxh.push(a);
    } else if (mnh.empty() || (a <= mxh.top())) {
        A += std::abs(mxh.top() - a);
        mxh.push(a);
    } else {
        A += a - mxh.top();
        mnh.push(a);
    }
    while (mxh.size() >= (mnh.size() + 2u)) {
        mnh.push(mxh.top());
        mxh.pop();
        A -= 1LL * (mnh.top() - mxh.top()) * (mxh.size() - mnh.size());
