template<typename T>
struct BIT {
  int n;
  vector<T> bit;
  BIT() {}
  BIT(int n, T e = 0) : n(n), bit(n+1,e){}
  T sum(int i) {
    T s = bit[0];
    for(int x = i;x > 0; x -= (x & -x))
      s += bit[x];
    return s;
  }
  void add(int i, T a){
    if(i == 0) return;
    for(int x = i; x <= n; x += (x & -x))
      bit[x] += a;
  }
  int lower_bound(T w){
    if(w <= 0) return 0;
    int x = 0,r = 1;
    while(r < n) r <<= 1;
    for(int k = r; k > 0; k >>= 1){
      if(x+k <= n && bit[x+k] < w){
        w -= bit[x+k];
        x += k;
      }
    }
    return x+1;
  }
};

