int main() {

	int q;
	cin >> q;

	ll sum = 0;
	ll first_sum = 0;
	ll latter_sum = 0;

	priority_queue<ll>	first;
	priority_queue < ll, vector<ll>, greater<ll> > latter;


	for (int _ = 0; _ < q; _++)
	{
		int a, b, c;
		cin >> a;
		if (a == 1) {
			cin >> b >> c;
			sum += c;//

			if (first.size() > latter.size()) {
				//後半に追加


				ll t = first.top();

				if (b >= t) {
					latter.push(b);
					latter_sum += b;
				}
				else
				{
					//前半の最大値を後半にもっていく
					//前半の最大値を取り出す
					first.pop();
					first_sum -= t;

					//後半に追加
					latter.push(t);
					latter_sum += t;

					//前半にクエリのxを加える
					first.push(b);
					first_sum += b;
				}

			}
			else
			{
				//前半に追加
				if (first.empty()) {
					first_sum += b;
					first.push(b);
				}
				else
				{
					//まずは後半の最大のものと比較
					ll t = latter.top();
					if (b <= t) {
						//後半の最小値以下ならば前半に追加
						first.push(b);
						first_sum += b;
					}
					else
					{
						//後半に追加すべきもの
						//後半の最大値を取り出す
						latter.pop();
						latter_sum -= t;

						//前半に入れる
						first.push(t);
						first_sum += t;

						//クエリの値は後半に入れる
						latter.push(b);
						latter_sum += b;
					}
				}
			}
		}
		else
		{

			ll mid = first.top();
			ll ans = (mid * (ll)first.size() - first_sum) + (latter_sum - mid * (ll)latter.size()) + sum;

			cout << mid << " " << ans << endl;
		}
	}

	return 0;
}

