  R.push(a);
  if (L.top() <= R.top())
  {
    // nothing
  }
  else
  {
    ll l = L.top();
    ll r = R.top();
    L.pop();
    R.pop();
    L.push(r);
    R.push(l);
  }
  sum.update(M[a], a);
  cnt.update(M[a], 1);
}

void flush()
{
  ll p = L.top();
  int ind = M[p];
  ll v = -sum.find(0, ind) + cnt.find(0, ind) * p + sum.find(ind + 1, S.size()) - cnt.find(ind + 1, S.size()) * p;
  cout << p << " " << v + B << endl;
}

