struct median{
	ll ans,suml,sumr,sum;
	priority_queue<int,vector<int>> mx;
	priority_queue<int,vector<int>,greater<int>> mn;
	median()
	{
		ans = suml = sumr = 0,sum = 0;
	}
	void insert(ll item){
		sum += item;
		if(item > ans){
			mn.push(item);
			sumr += item;
		}
		else{
			mx.push(item);
			suml += item;
		}
		if(((int)mx.size() - (int)mn.size()) > 1){
			ll temp = mx.top();
			mx.pop();
			suml -= temp;
			mn.push(temp);
			sumr += temp;
		}
		if(((int)mn.size() - (int)mx.size()) > 1){
			ll temp = mn.top();
			mn.pop();
			sumr -= temp;
			mx.push(temp);
			suml += temp;
		}
		if((mx.size() + mn.size()) % 2 == 1){
			if(mn.size() > mx.size()){
				ll temp = mn.top();
				mn.pop();
				sumr -= temp;
				mx.push(temp);
				suml += temp;
			}
		}
		if(ans == 0)
			ans = item;
		else
			ans = mx.top();
	}
	ll getMedian(){
		return ans;
	}
	ll LeftSum(){
		return suml;
	}
	ll RightSum(){
		return sumr;
	}
	ll LeftSize(){
		return (ll)mx.size();
	}
	ll RightSize(){
		return (ll)mn.size();
	}
};

