typedef long long ll;

struct median {
private:
    priority_queue<int> L;
    priority_queue<int, vector<int>, greater<int> > R;
    ll sumL = 0LL, sumR = 0LL;

public:
    void add(int x) {
        if(L.size() == 0 || x <= L.top()) {
            L.push(x);
            sumL += x;
        }
        else {
            R.push(x);
            sumR += x;
        }

        while(L.size() < R.size()) {
            sumL += R.top();
            sumR -= R.top();
            L.push(R.top());
            R.pop();

        }

        while(R.size() + 1 < L.size()) {
            sumR += L.top();
            sumL -= L.top();
            R.push(L.top());
            L.pop();
        }
    }
    ll getMedian() {
        return L.top() * 1LL;
    }
    ll getLowerSum() {
        return sumL * 1LL;
    }
    ll getUpperSum() {
        return sumR * 1LL;
    }
    ll getSizeL() {
        return L.size() * 1LL;
    }
    ll getSizeR() {
        return R.size() * 1LL;
    }
};

int main() {
    ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);

    priority_queue<int> L;
    priority_queue<int, std::vector<int>, std::greater<int> > R;

    int n;
    cin >> n;

    ll c = 0;

    median g;

    for(int i = 0; i < n; i++) {
        int t;
        cin >> t;

        if(t == 1) {
            int a, b;
            cin >> a >> b;

            c += b * 1LL;
            g.add(a);
        }
        else {
            ll med = g.getMedian();
            cout << med << " ";
            cout << c + med * g.getSizeL() - g.getLowerSum() + g.getUpperSum() - med * g.getSizeR() << endl;
        }
    }
}

