    std::cin >> q;
    for (int p = 0; p < q; ++p) {
        int t;
        std::cin >> t;
        if (t == 1) {
            lint a, b;
            std::cin >> a >> b;
            c += b;

            if (back.empty() || a < *back.begin()) {
                fore.insert(a);
                fsum += a;
            } else {
                back.insert(a);
                bsum += a;
            }

            while (fore.size() > back.size() + 1) {
                auto it = --fore.end();
                a = *it;
                fore.erase(it);
                fsum -= a;

                back.insert(a);
                bsum += a;
            }

            while (back.size() > fore.size()) {
                auto it = back.begin();
                a = *it;
                back.erase(it);
                bsum -= a;

                fore.insert(a);
                fsum += a;
            }
        } else {
            lint x = *(--fore.end());
            std::cout << x << ' '
                      << ((lint)fore.size() * x - fsum) +
                             (bsum - (lint)back.size() * x) + c
                      << std::endl;
        }
    }
    return 0;
}

