#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

int main(){
	int q;
	cin >> q;
	multiset<int64> l, r;
	int64 sum = 0;
	int ans = 0;
	for(int i = 0; i < q; i++){
		int id;
		cin >> id;
		if(id == 1){
			int64 a, b;
			cin >> a >> b;
			sum += b;
			if(l.size() % 2 == 0){
				if(r.size() == 0){
					l.insert(a);
					ans = a;
					continue;
				}
				int64 vr = *r.begin();
				if(vr < a){
					r.erase(r.begin());
					r.insert(a);
					l.insert(vr);
					sum = sum - vr + a;
					ans = vr;
				}else{
					l.insert(a);
					auto it = l.end();
					it--;
					ans = *it;
				}
			}else{
				auto it = l.end();
				it--;
				int64 vl = *it;
				if(vl <= a){
					r.insert(a);
					sum = sum + a - vl;
					ans = vl;
				}else{
					l.erase(it);
					l.insert(a);
					r.insert(vl);
					sum = sum + vl - a;
					it = l.end();
					it--;
					ans = *it;
				}
			}
		}else{
			cout << ans << ' ' << sum << endl;
		}
	}
}

