multiset <ll> s1;
multiset <ll,greater<ll> >s2;
ll ans,sum1,sum2,nmid;

int main()
{
	int n=read();

	for(int i=1;i<=n;i++)
	{
		int opt=read();
		if(i==1) {int x=read(),y=read(); ans+=y; nmid=x; continue;}
		else if(opt==1)
		{
			ll x=read(),y=read(); ans+=y;
			if(x<nmid) s2.insert(x),sum2+=x; else s1.insert(x),sum1+=x;
			if(s2.size()>s1.size())
			{
				s1.insert(nmid); sum1+=nmid; nmid=*s2.begin();
				sum2-=*s2.begin(); s2.erase(s2.begin());
			}
			else if(s1.size()>s2.size())
			{
				s2.insert(nmid); sum2+=nmid; nmid=*s1.begin();
				sum1-=*s1.begin(); s1.erase(s1.begin());
			}
			//cout<<s1.size()<<" "<<s2.size()<<" "<<nmid<<endl;
		}
		else
		{
			ll t1=sum1-nmid*s1.size(),t2=nmid*s2.size()-sum2;
			printf("%lld %lld\n",nmid,t1+t2+ans);
		}
	}
	return 0;
}

