int Q;
vector<int> qry;
vector<ll> A,B;

int main(){
  cin>>Q;
  qry.resize(Q);
  A.resize(Q,0);
  B.resize(Q,0);
  for(int i=0;i<Q;i++){
    cin>>qry[i];
    if(qry[i]==2) continue;
    cin>>A[i]>>B[i];
  }

  multiset<ll> mse;
  ll dif=0;
  vector<ll> v;
  for(int i=0;i<Q;i++){
    if(qry[i]==2) continue;
    mse.insert(A[i]);
    v.push_back(A[i]);
    dif+=B[i];
  }

  sort(v.begin(),v.end());

  ll mid=(v.size()-1)/2;
  ll ans=dif;
  for(int i=0;i<v.size();i++) ans+=abs(v[i]-v[mid]);

  vector<pair<int,ll>> res;
  int num=0;
  auto midr=mse.begin();
  for(;midr!=mse.end();midr++){
    if(num==mid) break;
    num++;
  }

  for(int q=Q-1;q>=0;q--){
    //cout<<q<<endl;
    if(qry[q]==2){
      res.push_back(mkp(*midr,ans));
      continue;
    }

    auto itr=mse.lower_bound(A[q]);
    int n=mse.size();
    int midnum=*midr;
    int ernum=*itr;

    ll mia=abs(midnum-ernum);
    if(n==1) continue;
    if(n%2){
      if(midnum<=ernum){
        midr--;
        ans=ans+(ernum-midnum)*((n-num)-num);
        num--;
      }
    }else{
      if(midnum>=ernum){
        midr++;
        ans=ans+(midnum-ernum)*(num+1-(n-(num+1)));
        num++;
      }
    }
    mse.erase(itr);
    ans=ans-abs(*midr-ernum);
    ans-=B[q];
  }

  reverse(res.begin(),res.end());
  for(int i=0;i<res.size();i++) cout<<res[i].first<<" "<<res[i].second<<endl;


  return 0;
}

#include <functional>
#include <memory>
#include <utility>

template<typename T, typename Compare = ::std::less<T>>
class skew_heap {
    using value_type = T;
    using const_reference = const value_type &;
    using size_type = ::std::size_t;
    using value_compare = Compare;

    class node_type {
    public:
        ::std::unique_ptr<node_type> left, right;
        value_type value;

        explicit constexpr node_type(const value_type &_value = T()) : value(_value), left(nullptr), right(nullptr) {}
    };

    using pointer_type = ::std::unique_ptr<node_type>;

    pointer_type root;

    value_compare comp;

    size_type _size;

    pointer_type meld(pointer_type a, pointer_type b) {
        if (!a)return b;
        if (!b)return a;
        if (comp(a->value, b->value))a.swap(b);
        a->right = meld(::std::move(a->right), ::std::move(b));
        a->left.swap(a->right);
        return a;
    }

public:
    constexpr skew_heap() : root(nullptr), comp(), _size(1) {}

    explicit constexpr skew_heap(const value_compare &_comp) : root(nullptr), comp(_comp), _size(1) {}

    constexpr bool empty() const noexcept { return !_size; }

    constexpr size_type size() const noexcept { return _size; }

    constexpr const_reference top() const noexcept {
        return root->value;
    }

    void push(const_reference val) {
        root = meld(::std::move(root), ::std::make_unique<node_type>(val));
        ++_size;
    }

    void push(value_type &&val) {
        root = meld(::std::move(root), ::std::make_unique<node_type>(::std::move(val)));
        ++_size;
    }

    template<class... Args>
    void emplace(Args &&... args) {
        root = meld(::std::move(root), ::std::make_unique<node_type>(::std::forward<Args>(args)...));
        ++_size;
    }

    void pop() {
        root = meld(::std::move(root->right), ::std::move(root->left));
        --_size;
    }

    void meld(skew_heap &x) {
        _size += x.size();
        x._size = 0;
        root = meld(::std::move(root), ::std::move(x.root));
    }
};


