struct pbds_sum {
    //@formatter:off
    //@formatter:on
    template<typename T = int> class BIT {
    public:
        int n;
        vector<T> dat;
        BIT(int n) : n(n) { dat.assign(n, 0); }
        T sum(int k) {
            if (k >= n) k = n - 1;
            T ret = 0;
            for (int x = k - 1; x >= 0; x = (x & (x + 1)) - 1) { ret += dat[x]; }
            return ret;
        }
        T sum(int l, int r) { return sum(r) - sum(l); }
        T get(int l, int r) { return sum(r) - sum(l); }
        T get(int k) { return sum(k); }
        T operator[](int k) {
            assert(0 <= k && k < n);
            return sum(k + 1) - sum(k);
        }
        T operator()(int k) { return sum(k); }
        T operator()(int l, int r) { return sum(l, r); }
        void add(int k, T val = 1) { for (int x = k; x < n; x |= x + 1)dat[x] += val; }
        void update(int k, T val = 0) { add(k, -operator[](k) + val); }
        void del(int k) { update(k, 0); }
        void clear() { fill(dat, 0); }
        void debu() {
#ifdef _DEBUG
            vi res;
            rep(i, min(10, n)) { res.push_back(operator[](i)); }
            deb(res);
#endif
        }
        int lower_bound(int w) {
            if (w <= 0) return -1;
            int x = 0;
            int k = 1;
            while ((k << 1) <= n) k <<= 1;
            for (; k > 0; k >>= 1) {
                if (x + k <= n && dat[x + k - 1] < w) {
                    w -= dat[x + k - 1];
                    x += k;
                }
            }
            return x;
        }
    };
    //@formatter:on
    BIT<int> bco, bsu;
    umapi v_i;
    vi i_v;
    int count = 0;

    //クエリの順番が分かってる場合の高速化

    //クエリの順番が入れ替わってもいいようにする
    pbds_sum(vi &a) : bco(sz(a) + 3), bsu(sz(a) + 3) {
        vi b = a;
        b.push_back(-linf - 100);
        b.push_back(linf + 100);
        i_v = compress(b);
        rep(i, sz(a)) { v_i[a[i]] = b[i]; }
    }
    pbds_sum(vi &a, vi &b) : bco(sz(a) + sz(b) + 3), bsu(sz(a) + sz(b) + 3) {
        vi c = a;
        vi d = b;
        c.push_back(-linf - 100);
        c.push_back(linf + 100);
        d.push_back(-linf - 100);
        d.push_back(linf + 100);
        i_v = compress(c, d);
        rep(i, sz(a)) {
            v_i[a[i]] = c[i];
            v_i[b[i]] = d[i];
        }
    }
    pbds_sum(vi &a, vi &b, vi &c) : bco(sz(a) + sz(b) + sz(c) + 3), bsu(sz(a) + sz(b) + sz(c) + 3) {
        vi d = a;
        vi e = b;
        vi f = c;
        d.push_back(-linf - 100);
        d.push_back(linf + 100);
        e.push_back(-linf - 100);
        e.push_back(linf + 100);
        f.push_back(-linf - 100);
        f.push_back(linf + 100);
        i_v = compress(d, e, f);
        rep(i, sz(a)) {
            v_i[a[i]] = d[i];
            v_i[b[i]] = e[i];
            v_i[c[i]] = f[i];
        }
    }
    void add(int v, int c = 1) {
        count += c;
        int ind = v_i[v];
        bco.add(ind, c);
        bsu.add(ind, v * c);
    }
    //開区間
    int sum(int rv) {
        int i = (std::lower_bound(all(i_v), rv) - i_v.begin());
        return bsu.sum(i);
    }
    //半開区間 l rは存在しない値でもいい
    int sum(int l, int r) {
        return sum(r) - sum(l);
    }
    //圧縮された座標を渡す
    int sum_fast_i(int li, int ri) {
        return bsu.sum(ri) - bsu.sum(li);
    }
    int cou(int rv) {
        int i = (std::lower_bound(all(i_v), rv) - i_v.begin());
        return bco.sum(i);
    }
    //半開区間 l rは存在しない値でもいい
    int cou(int l, int r) {
        return cou(r) - cou(l);
    }
    int find_by_order(int k) {
        int i = bco.lower_bound(k + 1);
        return i_v[i];
    }
    int order_by_key(int v) {
        v = *std::lower_bound(all(i_v), v);
        int i = v_i[v];
        return bco.sum(i);
    }
    //中央値を返す 左より)
    int mid() {
        return find_by_order((count - 1) >> 1);
    }
    //全要素との 最小の差の和をかえす (中央値との差)
    int min_dis() {
        int mv = mid();
        int mi = v_i[mv];
        int lcou = bco.sum(mi);
        int rcou = bco.sum(mi + 1, linf);
        int lsum = mv * lcou - bsu.sum(mi);
        int rsum = bsu.sum(mi + 1, linf) - mv * rcou;
        return lsum + rsum;
    }
    //存在しない場合マイナスになってしまう
    void erase(int v, int c = 1) {
        int ind = v_i[v];
        assert(bco[ind] >= c);
        count -= c;
        bco.add(ind, -c);
        bsu.add(ind, v * -c);
    }
    int lower_bound(int v) {
        v = *std::lower_bound(all(i_v), v);
        int i = v_i[v];
        int needc = bco.sum(i) + 1;
        i = bco.lower_bound(needc);
        return i_v[i];
    }
    int upper_bound(int v) {
        return lower_bound(v + 1);
    }

};
