		if(opt==1){
			int a,b,tmp;
			scanf("%d%d",&a,&b);
			ret+=b;
			if(q1.size()==q2.size()){
				if(q1.empty()){
					q1.push(a);
					sum1+=a;
				}else if(a>=q1.top()){
					q2.push(a);
					sum2+=a;
				}else{
					q1.push(a);
					sum1+=a;
				}
			}else if(q1.size()<q2.size()){
				if(a<q2.top()){
					q1.push(a);
					sum1+=a;
				}else
					tmp=q2.top();
					sum2-=tmp;
					q2.pop();
					sum1+=tmp;
					sum2+=a;
					q2.push(a);
					q1.push(tmp);
			}else{
				if(a>q1.top()){
					q2.push(a);
					sum2+=a;
				}else
					tmp=q1.top();
					sum1-=tmp;
					q1.pop();
					sum2+=tmp;
					sum1+=a;
					q1.push(a);
					q2.push(tmp);
			}
		}else{
			int x=q1.top();
			ll ans=ret+sum2-sum1;
			if(q1.size()>q2.size()) ans+=q1.top();
			else if(q1.size()<q2.size()){
				ans-=q2.top();
				x=q2.top();
			}
			printf("%d %lld\n",x,ans);
		}
	}
	return 0;
}

