    priority_queue<ll, vector<ll>, greater<ll>> pq2; // 大きいものを入れる
    int cnt = 0;
    constexpr long long LLINF = 1e18 + 1;
    pq1.push(-LLINF);
    pq1.push(-LLINF);
    pq2.push(LLINF);
    pq2.push(LLINF);
    ll sum = 0;
    ll total1 = 0, total2 = 0;
    for (int i = 0; i < q; i++) {
        int t; cin >> t;
        if (t == 1) {
            ll a, b; cin >> a >> b;
            sum += b;
            if (cnt & 1) {
                if (pq1.top() == a) {
                    pq1.push(a);
                    pq2.push(a);
                }
                else if (a < pq1.top()) {
                    ll tmp = pq1.top(); pq1.pop();
                    if (pq1.top() != -LLINF) total1 -= (tmp - pq1.top()) * (cnt / 2);
                    if (pq1.top() < a) {
                        total1 += (a - pq1.top()) * (cnt / 2);
                    }
                    else {
                        total1 += pq1.top() - a;
                    }
                    pq1.push(a);
                    pq1.push(a);
                    pq2.push(tmp);
                }
                else {
                    ll tmp = pq2.top(); pq2.pop();
                    if (pq2.top() != -LLINF) total2 -= (pq2.top() - tmp) * (cnt / 2);
                    if (pq2.top() > a) {
                        total2 += (pq2.top() - a) * (cnt / 2);
                    }
                    else {
                        total2 += a - pq2.top();
                    }
                    pq2.push(a);
                    pq2.push(a);
                    pq1.push(tmp);
                }
            }
            else {
                if (pq1.top() == a || pq2.top() == a) {
                    total1 += (a - pq1.top()) * (cnt / 2);
                    total2 += (pq2.top() - a) * (cnt / 2);
                    pq1.push(a);
                    pq2.push(a);
                }
                else if (pq1.top() < a && a < pq2.top()) {
