template <class T>
struct BIT{
  int n;
  vector<T> bit; //[1,N]

  BIT(int _n){
    n = _n + 1;
    bit.resize(n,0);
  }

  T sum(int i){
    T sum = 0;
    while(i > 0){
      sum += bit[i];
      i -= i & -i;
    }
    return sum;
  }

  void add(int i,T x){
    while(i < n){
      bit[i] += x;
      i += i & -i;
    }
  }

  int lower_bound(T x) {
    int left = -1, right = n;
    while(right - left > 1) {
      int mid = (left + right)/2;
      if(sum(mid) >= x) right = mid;
      else left = mid;
    }
    return right;
  }
};

