      cnt++;
    }
    else {
      int idx = bit2.lower_bound((cnt+1)/2);
      int x = v[idx-1];
      int ans = 0;
      ans += x * bit2.sum(idx-1) - bit1.sum(idx-1);
      ans += -x * (bit2.sum(v.size()) - bit2.sum(idx)) + (bit1.sum(v.size()) - bit1.sum(idx));
      cout << x << " " << ans + add << endl;
    }
  }

  return 0;
}

