int main(){
  ll Q,Bs=0;
  cin>>Q;

  // Eは小さいものを降順 Fは大きいものを昇順
  priority_queue<ll> E;
  priority_queue<ll,vector<ll>,greater<ll>> F;
  ll Es=0,Fs=0;

  REP(q,Q){
    ll X,A,B;
    cin>>X;
    if(X==1){
      cin>>A>>B;
      Bs+=B;
      if(E.size()>F.size()){
        ll P=E.top();
        if(A>=P){
          F.push(A);
          Fs+=A;
        }
        else{
          E.pop();
          Es-=P;
          E.push(A);
          Es+=A;
          F.push(P);
          Fs+=P;
        }
      }
      else{
        if(E.empty()){
          E.push(A);
          Es+=A;
        }
        else{
          ll P=F.top();
          if(A<=P){
            E.push(A);
            Es+=A;
          }
          else{
            F.pop();
            Fs-=P;
            F.push(A);
            Fs+=A;
            E.push(P);
            Es+=P;
          }
        }
      }
    }
    else{
      ll W=E.top();
      ll ans=(W*(int)E.size()-Es)+(Fs-W*(int)F.size())+Bs;
      cout<<W<<" "<<ans<<endl;
    }
  }
  return 0;
}

