int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);

    int q;
    cin >> q;
    ll sum = 0, front = 0, back = 0;

    priority_queue<ll> small;

    priority_queue<ll, vector<ll>, greater<ll>> large;
    while (q--)
    {
        int t;
        cin >> t;
        if (t == 1)
        {

            ll a, b;
            cin >> a >> b;
            sum += b;
            if (small.size() == 0)
            {
                small.push(a);
                front += a;
                continue;
            }
            else
            {
                if (small.size() == large.size() + 1)
                {
                    if (small.top() <= a)
                    {
                        large.push(a);
                        back += a;
                    }
                    else
                    {

                        ll tmp = small.top();
                        front -= tmp;
                        small.pop();
                        large.push(tmp);
                        back += tmp;
                        small.push(a);
                        front += a;
                    }
                }
                else if (small.size() == large.size())
                {
                    ll t = large.top();
                    if (a <= t)
                    {
                        small.push(a);
                        front += a;
                    }
                    else
                    {
                        large.pop();
                        back -= t;
                        small.push(t);
                        front += t;
                        large.push(a);
                        back += a;
                    }
                }
            }
        }
        else if (t == 2)
        {
            ll med = small.top();
            cout << med << " " << (med * (ll)small.size() - front) + (back - med * (ll)large.size()) + sum << endl;
        }
        //cout << small.size() << " " << large.size() << endl;
    }
    return 0;
}

