ll ls, rs, bs;

int main(){
    cin >> Q;
    for(int i = 0; i < Q; i++){
        int q;
        cin >> q;
        if(q == 1){
            ll a, b;
            cin >> a >> b;
            bs += b;

            if(x < a){
                r.push(a);
                rs += a;
            }else{
                l.push(a);
                ls += a;
            }

            if(l.size() > r.size() + 1){
                ll t = l.top(); l.pop();
                ls -= t, rs += t;
                r.push(t);
            }
            if(l.size() < r.size()){
                ll t = r.top(); r.pop();
                rs -= t, ls += t;
                l.push(t);
            }

            x = l.top();
        }else{
            ll res = bs + rs - ls + (ll)(l.size() - r.size()) * x;
            cout << x << " " << res << endl;
        }
    }
    return 0;
}

