void solve() {
  int q;
  cin >> q;

  LL mn = 10000000000LL;
  int cnt = 0;
  LL B = 0;
  LL res = 0;
  REP(_, q) {
    int k;
    cin >> k;
    if(k == 1) {
      LL a, b;
      cin >> a >> b;
      B += b;
      cnt++;
      if(a >= mn) {
        res += a-mn;
      } else {
        res += (mn-a)*(cnt-1);
        mn = a;
      }
    } else {
      cout << mn << " " << res + B << endl;
    }
  }
}

