int main() {
  using LL = long long;
  struct Query {LL n, a, b;};

  int N;
  cin >> N;

  vector<Query> Q(N);
  for(auto& q: Q) {
    cin >> q.n;
    if(q.n == 1) cin >> q.a >> q.b;
  }

  for(auto& q: Q) q.a += 1e9+1;
  vector<LL> p = {0, LL(2e9+1)};
  for(const auto& q: Q) if(q.n == 1) p.emplace_back(q.a);
  Compression<LL> comp(p);

  SegmentTree<LL> sum(comp.size()+1), num(comp.size()+1);
  auto f = [&](auto i) {
    auto x = comp[i];
    return x*num.sum(0, i)-sum.sum(0, i) + sum.sum(i+1, comp.size())-x*num.sum(i+1, comp.size());
  };
  LL c = 0;
  for(const auto& q: Q) {
    if(q.n == 1) {
      c += q.b;
      sum.add(comp.index(q.a), abs(q.a));
      num.add(comp.index(q.a), 1);
    } else {
      LL l = 0, h = comp.size()-1;
      while(l+3 < h) {
        LL m1 = (2*l+h)/3, m2 = (l+2*h)/3;
        if(f(m1) <= f(m2)) h = m2;
        else               l = m1;
      }
      if(f(l)>f(l+1)) ++l;
      if(f(l)>f(l+1)) ++l;
      if(f(l)>f(l+1)) ++l;
      cout << comp[l]-1e9-1 << " " << f(l)+c << endl;
    }
  }
}

