int main(){
    ll Q;
    cin >> Q;
    priority_queue<ll> p;
    priority_queue<ll,vector<ll>,greater<ll>> q;
    ll sum_p=0,sum_q=0;
    ll c=0;
    ll i=0;
    ll ps=0,qs=0;
    map<ll,ll> m;
    while(Q--){
        ll k;
        cin >> k;
        if(k==1){
            ll a,b;
            cin >> a >> b;
            c+=b;
            if(p.empty() && q.empty()){
                p.push(a);
                q.push(a);
                sum_p+=a;
                sum_q+=a;
                m[a]++;
                ps++;
                qs++;
                i++;
                continue;
            }
            ll x=p.top();
            ll y=q.top();
            if(i%2==0){
                if(a!=x && a!=y){
                    i++;
                    if(a<x){
                        p.push(a);
                        q.push(x);
                        sum_p+=a;
                        sum_q+=x;
                        ps++;
                        qs++;
                        m[a]++;

                    }
                    if(x<a && a<y){
                        p.push(a);
                        q.push(a);
                        sum_p+=a;
                        sum_q+=a;
                        ps++;
                        qs++;
                        m[a]++;

                    }
                    if(y<a){
                        q.push(a);
                        p.push(y);
                        sum_p+=y;
                        sum_q+=a;
                        ps++;
                        qs++;
                        m[a]++;
                    }
                }
                else if(a==x){
                    sum_p+=a;
                    ps++;
                }
                else if(a==y){
                    sum_q+=a;
                    qs++;
                }
            }
            else{
                if(a!=x){
                    i++;
                    if(a<x){
                        p.pop();

                        sum_p-=x*m[x];
                        sum_p+=a;
                        if(!m.count(a)){
                            p.push(a);
                        }
                        m[a]++;
                        ps-=m[x];
                        ps++;


                    }
                    if(x<a){
                        q.pop();
                        sum_q-=y*m[y];
                        sum_q+=a;
                        if(!m.count(a)){
                            q.push(a);
                        }
                        qs-=m[y];
                        qs++;
                    }
                }
                else{

                    sum_p+=a;
                    sum_q+=a;
                    ps++;
                    qs++;
                    m[a]++;
                }
            }

        }
        if(k==2){
            ll x=p.top();
            ll y=q.top();
            ll ans=0;
            ans+=ps*x-sum_p;
            ans+=sum_q-qs*x;
            ans+=c;
            cout << x << " " << ans << endl;
        }
    }
    return 0;
}

