#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    // b の和は別で管理
    // a_n を左半分(降順)と右半分(昇順)で2つヒープを作る
    // 左半分の要素の数 >= 右半分の要素の数 で差は0か1
    // これで左半分の最大値が求める x になる
    // \sum abs(x-a_n) の値はヒープの維持と同時に更新

    int Q;
    cin >> Q;
    ll aSum = 0; // \sum abs(x-a_n)
    ll bSum = 0; // \sum b_n
    priority_queue<int> queL; // 左半分の降順ヒープ
    priority_queue<int, vector<int>, greater<int>> queR; // 右半分の昇順ヒープ

    for (int i = 0; i < Q; ++i) {
        int type;
        cin >> type;
        if(type == 1){
            int a, b;
            cin >> a >> b;
            bSum += b;
            // 2つのヒープのサイズの合計が偶数か奇数か, aがqueL.top()以上かどうかで場合分け
            if(queL.size() == queR.size()){
                if(queL.top() > a){
                    aSum = aSum + (queL.top() - a);
                    queL.push(a);
                } else{
                    queR.push(a);
                    int minR = queR.top(); // これが次の queL.top() になる
                    queR.pop();
                    // 閉区間[queL.top(), minR]でf'(x) = 0 なので変更なし
                    aSum = aSum + (a - minR); // aの追加分
                    queL.push(minR);
                }
            } else{
                if(queL.top() > a){
                    queL.push(a);
                    int maxL = queL.top();
                    queL.pop();
                    // 閉区間[queL.top(), maxL]でf'(x) = -1
                    aSum = aSum + (maxL - queL.top());
                    aSum = aSum + (queL.top() - a); // aの追加分
                    queR.push(maxL);
                } else{
                    aSum = aSum + (a - queL.top());
                    queR.push(a);
                }
            }
        } else if(type == 2){
            cout << queL.top() << " " << aSum + bSum << endl;
        }
    }
    return 0;
}

