multiset<ll> sm, lg;
int sz=0;
ll sm_sum=0, lg_sum=0;
ll med;
ll sum=0;
void fix() {
	while(sz(sm)<sz(lg)) {
		ll akt=*lg.begin();
		lg.erase(lg.begin());
		lg_sum-=akt;

		sm.insert(med);
		sm_sum+=med;		

		med=akt;
	}


	while(sz(sm)>sz(lg)) {
		ll akt=*prev(sm.end());
		sm.erase(prev(sm.end()));
		sm_sum-=akt;

		lg.insert(med);
		lg_sum+=med;		

		med=akt;
	}


}
void insert(ll x) {
	sz++;
	if(sz==1) med=x;
	else if(x<med) {
		sm.insert(x);
		sm_sum+=x;
	}else {
		lg.insert(x);
		lg_sum+=x;
	}
	fix();
}	



