    // auto h = [](i64 a, i64 b) {return a + b;};
    // auto p = [](i64 a, i64 b) {return a;};
    // LazySegTree<i64, i64> tree(as, f, g, h, p, 1e18, 0);

    // RUQ, RSQ
    const i64 INF = 1e18;
    auto f = [](i64 a, i64 b) {return a + b;};
    auto g = [](i64 a, i64 b) {return b == INF ? a : b;};
    auto h = [](i64 a, i64 b) {return b == INF ? a : b;};
    auto p = [](i64 a, i64 b) {return a == INF ? INF : a * b;};
    LazySegTree<i64, i64> sum(vi(as.size()), f, g, h, p, 0, INF);
    LazySegTree<i64, i64> cnt(vi(as.size()), f, g, h, p, 0, INF);


    for (int i = 0; i < q; i++) {
        int x = qs[i][0], a = qs[i][1], b = qs[i][2];
        if (x == 1) {
            base += b;
            int p = pos[i];
            cnt.update(p, p + 1, 1);
            sum.update(p, p + 1, a);
        } else {
            int N = as.size();
            int tmp = cnt.query(0, N);
            if (tmp == 0) {
                cout << 0 << '\n';
                continue;
            }
            int l = -1, r = N;
            // lを中心
            while (l < r - 1) {
                int m = (l + r) / 2;
                assert(0 <= m && m <= N);
                if (sum.query(0, m) < (tmp + 1) / 2) {
                    l = m;
                } else {
                    r = m;
                }
            }

            i64 left = sum.query(0, l);
            i64 lcnt = cnt.query(0, l);
            i64 right = sum.query(l + 1, N);
            i64 rcnt = cnt.query(l + 1, N);
            cout << as[l].first << ' ' << base + lcnt * as[l].first - left + right - rcnt * as[l].first << '\n';
        }
    }
}

