struct Compress{
    vector<int> d, unzip;
    map<int, int> zip;        
    Compress(vector<int> a){
        vector<int> b = a;
        d.resize(a.size());
        sort(b.begin(), b.end());
        b.erase(unique(b.begin(), b.end()), b.end());
        unzip.resize(b.size());
        for(int i = 0; i < b.size(); i++){
            zip[b[i]] = i;
            unzip[i] = b[i];
        }
        for(int i = 0; i < a.size(); i++){
            d[i] = lower_bound(b.begin(), b.end(), a[i]) - b.begin();
        }
    }
};

template< typename T, typename E >
struct SegmentTree{
	using F = function< T(T, T) >;
	using G = function< T(T, E) >;
	int sz;
	vector<T> dat;
	F f;
	G g;
	T t1;
	SegmentTree(int n, F f, G g, T t1) : f(f), g(g), t1(t1) {
		sz = 1;
		while(sz < n) sz *= 2;
		dat.clear();
		dat.resize(2 * sz - 1, t1);
	}
	void set(int k, T x) { dat[k + sz - 1] = x; }
	void build() {
		for(int k = sz - 2; k >= 0; k--) {
			dat[k] = f(dat[2 * k + 1], dat[2 * k + 2]);
		}
	}
	void update(int k, E x) {
		k += sz - 1;
		dat[k] = g(dat[k], x);
		while(k > 0) {
			k = (k - 1) / 2;
			dat[k] = f(dat[2 * k + 1], dat[2 * k + 2]);
		}
	}
	T query(int a, int b, int k, int l, int r) {
		if(r <= a || b <= l) return t1;
		if(a <= l && r <= b) return dat[k];
		T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return f(vl, vr);
	}
	T query(int a, int b){ return query(a, b, 0, 0, sz); }
	T operator[](int k) { return dat[k + sz - 1]; }
};

signed main(){
