    int q;
    cin >> q;
    int bb = 0;
    SegmentTree<P, P> center(q, 
		[](P a, P b){ 
            vector<int> c;
            c.push_back(a.first);
            c.push_back(a.second);
            c.push_back(b.first);
            c.push_back(b.second);
            sort(c.begin(), c.end());
            int nz = 0;
            rep(i, 0, c.size()) if(c[i] != INF) nz++;
            if(nz % 2 == 1) return P(c[nz / 2], INF);
            return P(c[nz / 2 - 1], c[nz / 2]);
        }, 
		[](P a, P b){
            vector<int> c;
            c.push_back(a.first);
            c.push_back(a.second);
            c.push_back(b.first);
            c.push_back(b.second);
            sort(c.begin(), c.end());
            int nz = 0;
            rep(i, 0, c.size()) if(c[i] != INF) nz++;
            if(nz % 2 == 1) return P(c[nz / 2], INF);
            return P(c[nz / 2 - 1], c[nz / 2]);
        }, 
		P(INF, INF));
    SegmentTree<int, int> sum(q, 
		[](int a, int b){ return a + b; }, 
		[](int a, int b){ return a + b; }, 
		0LL);
    SegmentTree<int, int> cnt(q, 
