const int inf = 0x3f3f3f3f;
const LL infLL = 0x3f3f3f3f3f3f3f3fLL;

const int maxn = 200000 + 5;

int psz;
struct Node {
  int key, siz;
  LL sum;
  Node *ch[2];
  void update() {
    siz = ch[0]->siz + ch[1]->siz + 1;
    sum = ch[0]->sum + ch[1]->sum + key;
  }
} pool[maxn], *null = new Node();

Node *new_node(int k) {
  Node *i = pool + psz++;
  i->key = i->sum = k, i->siz = 1, i->ch[0] = i->ch[1] = null;
  return i;
}

class SBT {
  Node *root;

  void rotate(Node *&u, int d) {
    Node *v = u->ch[d ^ 1];
    u->ch[d ^ 1] = v->ch[d], u->update();
    v->ch[d] = u, v->update();
    u = v;
  }

  void maintain(Node *&u, int d) {
    if (u == null) return;
    if (u->ch[d]->ch[d]->siz > u->ch[d ^ 1]->siz)
      rotate(u, d ^ 1);
    else if (u->ch[d]->ch[d ^ 1]->siz <= u->ch[d ^ 1]->siz)
      return;
    else
      rotate(u->ch[d], d), rotate(u, d ^ 1);
    maintain(u->ch[0], 0);
    maintain(u->ch[1], 1);
    maintain(u, 0);
    maintain(u, 1);
  }

  void insert(Node *&u, int k) {
    if (u == null) {
      u = new_node(k);
      return;
    }
    int d = (k > u->key);
    insert(u->ch[d], k);
    maintain(u, d);
  }

 public:
  SBT() : root(null) { null->sum = 0, null->ch[0] = null->ch[1] = null; }
  int size() { return root->siz; }
  void insert(int k) { insert(root, k); }
  int select(int k, LL &s) {
    for (Node *u = root; u != null;) {
      int t = u->ch[0]->siz;
      if (k == t) {
        s += u->ch[0]->sum;
        return u->key;
      }
      if (k > t) s += u->ch[0]->sum + u->key;
      u = u->ch[k > t], k -= (k > t ? t + 1 : 0);
    }
    return inf;
  }
};

int main() {
  int n;
  scanf("%d", &n);
  SBT bst;
  LL sum = 0;
  while (n--) {
    int op, a, b;
    scanf("%d", &op);
    if (op == 1) {
      scanf("%d%d", &a, &b);
      bst.insert(a);
      sum += a + b;
    } else {
      int i = (bst.size() - 1) / 2;
      LL s = 0;
      int x = bst.select(i, s);
      printf("%d %lld\n", x, sum - 2 * s - (LL)x * (bst.size() - 2 * i));
    }
  }

  return 0;
}

