            {
                ll t = upper.top();
                upper.pop();
                lower.push(t);
            }
            else if (lower.size() - upper.size() > 1)
            {
                ll t = lower.top();
                lower.pop();
                upper.push(t);
            }

            //! lowerのtopが次のX
            ll p = X - lower.top();
            S += -(lower.size() - 1) * p + upper.size() * p;
            X = lower.top();
            if (X > a)
                S += abs(X - a) + p;
            else if (X < a)
