	ll lt = mini, rt = maxi, m1, m2, ret = maxi;
	ll val = -OO, v1, v2;
	while(rt - lt > 10){
		m1 = lt + (rt - lt) / 3;
		m2 = rt - (rt - lt) / 3;
		v1 = f(m1);
		v2 = f(m2);
