			compare(val, ret, v1, m1);
		}
		else{
			lt = m1 + 1;
			compare(val, ret, v2, m2);
		}
	}
	for(ll i=lt; i<=rt; i++){
		compare(val, ret, f(i), i);
	}
	cout << ret << " " << val << endl;
}

