struct FloatingMedian{
    priority_queue<ll> zen;
    priority_queue<ll, vector<ll>, greater<ll> > kou;
    ll zensum = 0;
    ll kousum = 0;

    ll const med(){
        return zen.top();
    }

    void push(ll n){
        if (zen.size() > kou.size()) {
            // kou に
            int t = zen.top();
            if (n >= t) {
                kou.push(n); kousum += n;
            }
            else {
                zen.pop(); zensum -= t;
                zen.push(n); zensum += n;
                kou.push(t); kousum += t;
            }
        }
        else {
            // zen に
            if (zen.empty()){
                zen.push(n);
                zensum += n;
            }
            else {
                int t = kou.top();
                if (n <= t) {
                    zen.push(n); zensum += n;
                }
                else {
                    kou.pop(); kousum -= t;
                    kou.push(n); kousum += n;
                    zen.push(t); zensum += t;
                }
            }
        }
    }
};

