            floatingmedian.push(a);
            sum += b;
        }
        else {
            ll x = floatingmedian.med();
            ll tmp1 = x * floatingmedian.zen.size() - floatingmedian.zensum;
            ll tmp2 = x * floatingmedian.kou.size() - floatingmedian.kousum;
            ll res = tmp1 - tmp2 + sum;
            cout << x << " " << res << endl;
        }
    }
    return 0;
}

