#include<bits/stdc++.h>
using namespace std;

struct median
{
private:
    priority_queue<int> firstHalf;
    priority_queue<int, vector<int>, greater<int> > secondHalf;
    long long int firstHalfSum = 0LL, secondHalfSum = 0LL;

public:
    void addValue(int num)
    {
        if(firstHalf.size() == 0 || firstHalf.top() >= num)
        {
            firstHalf.push(num);
            firstHalfSum += num;
        }
        else
        {
            secondHalf.push(num);
            secondHalfSum += num;
        }

        while(firstHalf.size() < secondHalf.size())
        {
            secondHalfSum -= secondHalf.top();
            firstHalfSum += secondHalf.top();
            firstHalf.push(secondHalf.top());
            secondHalf.pop();
        }

        while(firstHalf.size() - 1 > secondHalf.size())
        {
            firstHalfSum -= firstHalf.top();
            secondHalfSum += firstHalf.top();
            secondHalf.push(firstHalf.top());
            firstHalf.pop();
        }
    }

    long long int getMedian()
    {
        return firstHalf.top() * 1LL;
    }
    long long int getFirstHalfSum()
    {
        return firstHalfSum * 1LL;
    }
    long long int getSecondHalfSum()
    {
        return secondHalfSum * 1LL;
    }
    long long int getFirstHalfSize()
    {
        return firstHalf.size() * 1LL;
    }
    long long int getSecondHalfSize()
    {
        return secondHalf.size() * 1LL;
    }
};

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(NULL);
    cout.tie(NULL);

    int n;
    cin >> n;

    median m;
    long long int bSum = 0;
    while(n--)
    {
        int type;
        cin >> type;
        if(type == 1)
        {
            int a, b;
            cin >> a >> b;
            bSum += b;
            m.addValue(a);
        }
        else
        {
            long long int medianValue = m.getMedian();
            long long int firstHalfSize = m.getFirstHalfSize() - 1;
            long long int secondHalfSize = m.getSecondHalfSize();
            long long int firstHalfSum = m.getFirstHalfSum() - medianValue;
            long long int secondHalfSum = m.getSecondHalfSum();
            long long int ans = ((medianValue * firstHalfSize) - firstHalfSum) + (secondHalfSum - (medianValue * secondHalfSize));
            cout << medianValue << " " << ans + bSum << endl;
        }
    }
    return 0;
}

