int COUNT(long long int K) {

	int D, U;
	if (S.count(K) != 0) {
		auto it = S.find(K);
		U = distance(it, S.end())-S.count(K); 
	}
	else {
		S.insert(K);
		auto it = S.find(K);
		it++;
		U = distance(it, S.end());
		S.erase(K);
	}

	D = S.size() - U;

	//cout << "K= " << K << " U= " << U <<" D= " << D<< endl;

	return D-U;
}

long long int BINARY_SEARCH(void) {

	long long int left = -100000000002;
	long long int right = 1000000000003;

	long long int med;

	while (right - left > 1) {
		med = (right + left) / 2;
		if (COUNT(med) >= 0) { right = med; }
		else { left = med; }
	}

	return right;
}


long long int B[500005];

void UPDATE(int k, long long int val) {

	while (k <= 200005) {
		B[k] += val;
		k += (k&(-k));
	}
}

long long int SUM(int k) {
	long long int ret = 0;
	while (k > 0) {
		ret += B[k];
		k -= (k&(-k));
	}

	return ret;
}

