int main(void){
    std::multiset<int> vs1, vs2;
    int Q;
    std::cin >> Q;
    int qi = 0;
    int med = -1;
    int sum_abs = 0;
    int bias = 0;
    for(int ii = 0; ii < Q; ++ii){
        int q;
        std::cin >> q;
        if(q == 1){
            int v, b;
            std::cin >> v >> b;
            qi++;
            bias += b;
            if(qi == 1){
                vs1.insert(v);
                med = v;
            } else if(qi == 2){
                int w = *vs1.begin();
                if(w <= v){
                    vs2.insert(v);
                } else {
                    vs1.clear();
                    vs1.insert(v);
                    vs2.insert(w);
                }
                med = *vs1.begin();
                sum_abs = *vs2.begin() - med;
            } else {
                auto vs1_size = vs1.size(), vs2_size = vs2.size();
                if(*vs1.rbegin() >= v){
                    vs1.insert(v);
                    if(vs1.size()-2 >= vs2.size()){
                        int w = *vs1.rbegin();
                        vs1.erase(--vs1.end());
                        vs2.insert(w);
                    }
                } else {
                    vs2.insert(v);
                    if(vs2.size() > vs1.size()){
                        int w = *vs2.begin();
                        vs2.erase(vs2.begin());
                        vs1.insert(w);
                    }
                }
                int new_med = *vs1.rbegin();
                sum_abs += std::abs(new_med - v);
                sum_abs += std::abs(static_cast<int>((new_med - med) * (vs1_size - vs2_size)));
                med = new_med;
            } // end of insertion
        } else {
            std::cout << med << " " << sum_abs + bias << std::endl;
        }
    }
    return 0;
}

