#include <bits/stdc++.h>
using namespace std;
using large = long long;

int main() {
    int nq;
    cin >> nq;

    auto a_left = multiset<int, greater<int>>();
    auto a_right = multiset<int>();
    auto a_cnt = 0;
    auto a_left_sum = 0LL;
    auto a_right_sum = 0LL;
    auto b_sum = 0LL;

    for (int i = 0; i < nq; ++i) {
        large type, a, b;
        cin >> type;

        if (type == 1) {
            cin >> a >> b;
            b_sum += b;
            ++a_cnt;

            if (a_left.empty()) {
                a_left.insert(a);
                a_left_sum += a;
            } else if (a_left.size() == a_right.size()) { // insert to left
                auto largest_left = *a_left.begin();
                if (a <= largest_left) {
                    a_left.insert(a);
                    a_left_sum += a;
                } else {
                    auto smallest_right = *a_right.begin();
                    a_right.erase(a_right.begin());
                    a_right_sum -= smallest_right;
                    a_right.insert(a);
                    a_right_sum += a;

                    a_left.insert(smallest_right);
                    a_left_sum += smallest_right;
                }
            } else { // insert to right
                auto largest_left = *a_left.begin();
                if (a >= largest_left) {
                    a_right.insert(a);
                    a_right_sum += a;
                } else {
                    a_left.erase(a_left.begin());
                    a_left_sum -= largest_left;
                    a_left.insert(a);
                    a_left_sum += a;

                    a_right.insert(largest_left);
                    a_right_sum += largest_left;
                }
            }
        } else {
            // SUM( a[i] - a ) ---> SUM( a[i] ) - N*a

            auto a_mid = *a_left.begin();
            auto left_sum = a_left_sum - ((large)a_left.size() * a_mid);
            auto right_sum = a_right_sum - ((large)a_right.size() * a_mid);
            auto sum = left_sum + right_sum;

            cout << a << " " << (sum + b_sum) << "\n";
        }
    }

    return 0;
}

