  vector<i64> imp(2 * q);
  for (i64 i = 0; i < q; ++i) {
    cin >> qs[i].type;
    if (qs[i].type == 1) {
      cin >> qs[i].a >> qs[i].b;
      st.insert(qs[i].a);
    }
  }
  for (i64 x : st) {
    mp[x] = mp.size() + 1;
    imp[mp[x]] = x;
  }

  Fenwick<i64> fen(2 * q);
  i64 med = 0, sum = 0, size = 0, pos = 0;
  for (i64 i = 0; i < q; ++i) {
    i64 type = qs[i].type, a = qs[i].a, b = qs[i].b;
    if (type == 1) {
      bs += b;
      sum += a;
      ++size;
      fen.add(mp[a], 1);
    } else {
      i64 j = bisect(0, q + 1, [&](i64 x) {
        return fen.sum(x) >= size / 2;
      });
      i64 med = imp[j];
      cout << med << ' ' << sum - size * med + bs << '\n';
    }
  }
