struct point {ll x; ll y;
    bool operator<(const point& p) const{
        if (x == p.x) return y < p.y;
        return x < p.x;
    }

    point& operator+=(const ll a){
        x += a, y += a;
        return *this;
    }

    point& operator-=(const ll a){
        x -= a, y -= a;
        return *this;
    }

    point& operator*=(const ll a){
        x *= a, y *= a;
        return *this;
    }

    point& operator+=(const point p){
        x += p.x, y += p.y;
        return *this;
    }

    point& operator-=(const point p){
        x -= p.x, y -= p.y;
        return *this;
    }

    point& operator*=(const point p){
        x *= p.x, y *= p.y;
        return *this;
    }

    void operator++(int){x++, y++;}
    void operator++(){x++, y++;}
    void operator--(int){x--, y--;}
    void operator--(){x--, y--;}
    point operator+(const point p) const {return point(*this) += p;}
    point operator-(const point p) const {return point(*this) -= p;}
    point operator*(const point p) const {return point(*this) *= p;}

};

