class Solver{
private:
  multiset<int, greater<int>> l;
  multiset<int> r;

  ll sum_b, m;

  void smooth_set(){
    const int ls = l.size(), rs = r.size(), ds = abs(ls - rs);

    if(ls < rs){
      copy(r.begin(), next(r.begin(), ds/2), inserter(l, l.end()));
      r.erase(r.begin(), next(r.begin(), ds/2));
    }

    if(rs < ls){
      copy(l.begin(), next(l.begin(), ds/2), inserter(r, r.end()));
      l.erase(l.begin(), next(l.begin(), ds/2));
    }
  }

  void insert(int a){
    if(a < *l.begin()){
      l.insert(a); l.insert(a);
    } else if(a <= *r.begin()){
      l.insert(a); r.insert(a);
    } else {
      r.insert(a); r.insert(a);
    }
  }

public:
  Solver(){
    sum_b = m = 0;
  }

  void query1(int a, int b){
    sum_b += b;

    if(l.size() && (a < *l.begin() || *r.begin() < a)){
        m += min(abs(a - *l.begin()), abs(a - *r.begin()));
    } 

    insert(a);

    smooth_set();
  }

  void query2(){
    cout << *l.begin() << " " << m + sum_b << endl;
  }
};

