template<typename T> struct BIT {/*{{{*/
  int n;
  vector<T> dat;

  BIT(int n=0){/*{{{*/
    initialize(n);
  }/*}}}*/

  void initialize(int nin){/*{{{*/
    n = nin;
    dat.resize(n);
    for(int i = 0; i<n; i++) dat[i] = 0;
  }/*}}}*/

  T sum(int i){/*{{{*/
    T s = 0;
    while(i >= 0){
      s += dat[i];
      i = (i & (i+1)) - 1;
    }
    return s;
  }/*}}}*/

  T sum_between(int i, int j){/*{{{*/
    if(i > j) return 0;
    return sum(j) - sum(i-1);
  }/*}}}*/

  void plus(int i, T x){/*{{{*/
    while(i < n){
      dat[i] += x;
      i |= i+1;
    }
  }/*}}}*/

  int lower_bound(T x){ // a[0]+...+a[ret] >= x{{{
    int ret = -1;
    int k = 1;
    while(2*k <= n) k <<= 1;
    for( ;k>0; k>>=1){
      if(ret+k < n && dat[ret+k] < x){
        x -= dat[ret+k];
        ret += k;
      }
    }
    return ret + 1;
  }/*}}}*/
};/*}}}*/

