const int MOD = 2286661337;

mt19937 rnd(rand());

struct node
{
	int x, y, mx, sz;
	int sum;
	node *l, *r;
	node(int _x) {
		x = mx = sum = _x;
		y = rnd() % MOD;
		sz = 1;
		l = r = NULL;
	}
};

int get_sz(node *v) {
	if (!v) return 0;
	return v->sz;
}

int get_mx(node *v) {
	if (!v) return -MOD;
	return v->mx;
}

int get_sum(node *v) {
	if (!v) return 0;
	return v->sum;
}

void update(node *&v) {
	if (v) {
		v->sz = 1 + get_sz(v->l) + get_sz(v->r);
		v->mx = max(v->x, max(get_mx(v->l), get_mx(v->r)));
		v->sum = v->x + get_sum(v->l) + get_sum(v->r);
	}
}

void split(node *v, int x, node *&l, node *&r) {
	if (!v) {
		l = r = NULL;
		return;
	}
	if (1 + get_sz(v->l) <= x) {
		l = v;
		split(v->r, x - 1 - get_sz(v->l), l->r, r);
		update(l);
	} else {
		r = v;
		split(v->l, x, l, r->l);
		update(r);
	}
}

node* merge(node *a, node *b) {
	if (!a) return b;
	if (!b) return a;
	if (a->y > b->y) {
		a->r = merge(a->r, b);
		update(a);
		return a;
	}
	b->l = merge(a, b->l);
	update(b);
	return b;
}

int find_pos(node *v, int x) {
	if (!v) return 0;
	if (v->x == x) return 1 + get_sz(v->l);
	if (x > v->x) return 1 + get_sz(v->l) + find_pos(v->r, x);
	return find_pos(v->l, x);
}

node *L, *M, *R;

void insert(node *&v, int x, int pos) {
	split(v, pos, L, R);
	v = merge(L, merge(new node(x), R));
}

int ith(node *v, int pos) {
	if (1 + get_sz(v->l) == pos) return v->x;
	if (1 + get_sz(v->l) < pos) return ith(v->r, pos - 1 - get_sz(v->l));
	return ith(v->l, pos);
}

int get(node *v, int l, int r) {
	split(v, l - 1, L, v);
	split(v, r - l + 1, M, R);
	int ans = get_sum(M);
	v = merge(L, merge(M, R));
	return ans;
}

