struct BIT {
private:
	vector<ll> node; int n;
public:
	BIT(int n_) {
		n = n_; node.assign(n + 1, 0);
	}
	void add(int i, ll x) {
		while(i <= n) {
			node[i] += x;
			i += i & -i;
		}
	}
	ll sum(int i) {
		ll ret = 0;
		while(i > 0) {
			ret += node[i];
			i -= i & -i;
		}
		return ret;
	}
    ll sum(int a, int b) {
        return sum(b) - sum(a - 1);
    }
};

