queue<ll> L;
queue<ll> R;
ll L_size,R_size;
ll min_value,min_x;
ll L_max,R_min;
int Q;

void f1(ll a,ll b){
  min_value += b;
  ll x;
  if(a < L_max){
    L.push(-a);
    L_size++;
    if(L_size == R_size){
      min_value += min_x - a;
      min_x = L_max;
      return;
    }
    if(L_size == R_size+1){
      min_x = L_max;
      min_value += min_x - a;
      return;
    }
    L_size -= 1;
    R_size++;
    x = -L.front();
    L.pop();
    R.push(x);
    L_max = -L.front();
    R_min = x;
    min_value += x-a;
    min_x = L_max;
    return;
  }
  if(a > R_min){
    R.push(a);
    R_size++;
    if(L_size == R_size){
      min_value += a-min_x;
      return;
    }
    if(R_size == L_size + 1){
      min_x = R_min;
      min_value += a-min_x;
      return;
    }
    R_size -= 1;
    L_size++;
    x = R.front();
    R.pop();
    L.push(-x);
    R_min = R.front();
    L_max = x;
    min_x = x;
    min_value += a-x;
    return;
  }
  // 真ん中に足す場合
  if(L_size > R_size){
    R.push(a);
    R_size++;
    R_min = a;
    min_value += a-L_max;
    min_x = L_max;
    return;
  }
  if(R_size > L_size){
    L.push(-a);
    L_size++;
    L_max = a;
    min_x = a;
    min_value += R_min - a;
    return;
  }
  L.push(-a);
  L_size++;
  L_max = a;
  min_x = a;
  return;
}

void f2(){
  cout << min_x << " " << min_value << endl;
  return;
}

