long long int BP[500005];

void UPDATE_BP(int k, long long int v) {


	while (k <= Q) {
		BP[k] += v;
		k += k&(-k);
		//cout << k << endl;
	}
	//cout << "check" << endl;
}

long long int SUM_BP(int K) {
	long long int tmp = 0;

	while (K > 0) {
		tmp += BP[K];
		K -= K&(-K);
	}
	return tmp;
}

long long int BQ[500005];
void UPDATE_BQ(int k, long long int v) {
	while (k <= Q) {
		BQ[k] += v;
		k += k&(-k);
	}
}

long long int SUM_BQ(int K) {
	long long int tmp = 0;

	while (K > 0) {
		tmp += BQ[K];
		K -= K&(-K);
	}
	return tmp;
}



int BINARY_SEARCH(void) {

	int left = 0, right = Q+1;
	int med;
	while (right - left > 1) {
		med = (left + right) / 2;
		long long int D = SUM_BP(med);
		long long int U = SUM_BP(Q + 1) - D;
		//cout << "med= " << med << "D= " << D << " U= " << U << endl;
		if (D-U>=0) {
			right = med;
		}
		else {
			left = med;
		}
	}

	return right;
}

