class query {
public:
    int type;
    int a, b;
    query(int tin, int ain, int bin) {
        type = tin;
        a = ain;
        b = bin;
    }
};

signed main() {
    int Q;
    cin >> Q;
    vector<query> queries;
    rep(i, Q) {
        int t, a = -1, b = -1;
        cin >> t;

        if (t == 1) {
            cin >> a >> b;
        }

        queries.emplace_back(t, a, b);
    }
    priority_queue<int> smaller;    //中央値 イカ
    priority_queue<int, vector<int>, greater<int>> bigger;  //bigger は小さい順に取り出したい
    int SSum = queries[0].a, BSum = 0, med = queries[0].a, constantsSum = queries[0].b, aNum = 1;
    smaller.push(queries[0].a);

    //奇数の場合はSmallerに寄せる(簡単のため) -> smaller のtop がつねに中央値
    REPS(i, Q-1) {
        if (queries[i].type == 1) {
            aNum++;
            constantsSum += queries[i].b;
            //とりあえずてきとうにsmaller に入れる
            smaller.push(queries[i].a);
            SSum+= queries[i].a;


            //サイズをそろえる
            while (bigger.size() > smaller.size()) {
                auto t = bigger.top();
                bigger.pop();
                smaller.push(t);
                BSum -= t;
                SSum += t;
            }
            if (aNum % 2 == 1) {
                //この時点でsmaller の方が大きいはず
                while (smaller.size() > aNum / 2 + 1) {
                    auto t = smaller.top();
                    smaller.pop();
                    bigger.push(t);
                    BSum += t;
                    SSum -= t;
                }
            }
            else {
                while (smaller.size() > aNum / 2) {
                    auto t = smaller.top();
                    smaller.pop();
                    bigger.push(t);
                    BSum += t;
                    SSum -= t;
                }
            }
            //中央値: smaller.top
            med = smaller.top();
        }
        else {
            int ans = BSum - bigger.size() * med + smaller.size() * med - SSum + constantsSum;
            cout << smaller.top() << " " << ans << "\n";
        }

    }


    return 0;
}

