struct BIT {
	vector<int> bit;
	int n;

	BIT(int N) :n(N+2), bit((N+2) * 2){}

	int sum(int i) {
		++i;
		int s = 0;
		while (i > 0) {
			s += bit[i];
			i -= i&-i;
		}
		return s;
	}

	void add(int i, int x) {
		++i;
		while (i <= n) {
			bit[i] += x;
			i += i & (-i);
		}
	}
};

// 左にcnt個ある要素を探す
int search_index(BIT& bit, int size, int cnt, const set<int>& points) {
	int ok = 0;
	int ng = size;
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		if (bit.sum(mid) <= cnt) {
			ok = mid;
		}
		else {
			ng = mid;
		}
	}
	auto it = points.upper_bound(ok);
	--it;
	return *it;
}

void solve() {
	vector<tuple<int, int, int> > Q;
	int lleft = numeric_limits<int>::max();
	int rright = numeric_limits<int>::min();

	set<int> all_points;

	{
		int Qsize; cin >> Qsize;
		REP(i, Qsize) {
			int t; cin >> t;
			if (t == 1) {
				int a, b; cin >> a >> b;
				Q.emplace_back(t,a,b);
				lleft = min(a, lleft);
				rright = max(a, rright);
				all_points.emplace(a);
			}
			else {
				Q.emplace_back(t, 0, 0);
			}
		}
	}

	BIT BITleft(all_points.size());
	BIT BITleftcnt(all_points.size());
	BIT BITright(all_points.size());
	BIT BITrightcnt(all_points.size());
	unordered_map<int, int> enc;
	vector<int> dec;

	for (auto& p : all_points) {
		dec.push_back(p);
		enc[p] = dec.size() - 1;
	}

	int bsum = 0;
	set<int> points;
	for (auto& query : Q) {
		int t, p, b; tie(t, p, b) = query;

		if (t == 1) {
			bsum += b;
			BITleft.add(enc[p], p - lleft);
			BITleftcnt.add(enc[p], 1);
			BITright.add(enc.size() - enc[p] - 1, rright - p);
			BITrightcnt.add(enc.size() - enc[p] - 1, 1);
			points.emplace(enc[p]);
		}
		if (t == 2) {
			if (points.size() == 0) {
				cout << "0 0" << endl;
				continue;
			}
			int half = points.size()/2 + (points.size()%2);
			int index = search_index(BITleftcnt, all_points.size(), half, points);
			int p = dec[index];
			int res = 0;
			res += BITleftcnt.sum(index) * (p - lleft);
			res -= BITleft.sum(index);
			res += BITrightcnt.sum(enc.size() - index - 1) * (rright-p);
			res -= BITright.sum(enc.size() - index - 1);
			//cout << BITleftcnt.sum(index) * (p - lleft) << endl;
			//cout << BITleft.sum(index) << endl;
			//cout << BITrightcnt.sum(enc.size() - index - 1) * (rright-p) << endl;
			//cout << BITright.sum(enc.size() - index - 1) << endl;
			cout << p << " " << res + bsum << endl;
		}
	}
}

