using namespace std;
using ll = long long;

template <class T>
struct BIT {
	vector<T> data;
	BIT(int n) {
		data.assign(n, 0);
	}

	T sum(int i) {
		T res = 0;
		while (i > 0) {
			res += data[i];
			i -= i & -i;
		}
		return res;
	}
	T sum(int l, int r) { return sum(r) - sum(l - 1); }

	void add(int i, T x) {
		while (i < data.size()) {
			data[i] += x;
			i += i & -i;
		}
	}
};

int main() {
	const ll INF = 1e18;
	int Q;
	cin >> Q;
	vector<int> q(Q);
	vector<ll> a(Q);
	vector<ll> b(Q);
	vector<ll> unzip;
	for (int i = 0; i < Q; ++i) {
		cin >> q[i];
		if (q[i] == 1) {
			cin >> a[i] >> b[i];
			unzip.push_back(a[i]);
		}
	}

	unzip.push_back(-INF);
	sort(unzip.begin(), unzip.end());
	unzip.erase(unique(unzip.begin(), unzip.end()), unzip.end());
	map<ll, int> zip;
	int sz = unzip.size();
	for (int i = 0; i < sz; ++i) { zip[unzip[i]] = i; }

	BIT<ll> Anum(sz + 1);
	BIT<ll> Asum(sz + 1);
	ll sumB = 0;
	for (int i = 0; i < Q; ++i) {
		if (q[i] == 1) {
			sumB += b[i];
			Anum.add(zip[a[i]], 1);
			Asum.add(zip[a[i]], a[i]);
			continue;
		}
		int n = (Anum.sum(sz) + 1) / 2;
		int low = 1, high = sz;
		while (high - low > 1) {
			int m = (high + low) / 2;
			if (Anum.sum(m) > n) { high = m; }
			else { low = m; }
		}
		ll x = unzip[low];
		ll f = x*Anum.sum(low - 1) - Asum.sum(low - 1) + Asum.sum(low + 1, sz) - x*Anum.sum(low + 1, sz) + sumB;
		cout << x << " " << f << endl;
	}

	return 0;
}

