using namespace std;

struct side{
	stack<ll> st;
	ll size;
	ll su;
	side(){
		st = stack<ll>();
		size  = 0;
		su = 0;
	}
	ll remove(){
		ll ret = st.top();
		st.pop();
		size--;
		su -= ret;
		return ret;
	}
	void add(ll x){
		st.push(x);
		su+=x;
		size++;
		return;
	}
	ll cal(ll x){
		return abs(size*x - su);
	}
};

struct minima{
	side small, large;
	ll cons;
	minima(){
		small = side();
		large = side();
		cons = 0;
	}
	void add(ll a, ll b){
		cons += b;
		large.add(a);
		if(large.size > small.size){
			small.add(large.remove());
		}
	}
	Pll query(){
		int mi = small.st.top();
		return mapa(mi, cons + large.cal(mi) + small.cal(mi));
	}
};


int main(){
	int q;cin >> q;
	vector<Pll> ans(0);
	minima da;
	int a,b,c;
	rip(i,q,0){
		cin >> a;
		if(a == 1){
			cin >> b >> c;
			da.add(b, c);
		}
		else ans.push_back(da.query());
	}
	rip(i, ans.size(), 0) printf("%lld %lld\n", ans[i].first, ans[i].second);
}

