			f += m.leftCount() * med - m.leftTotal();
			f += m.rightTotal() - m.rightCount() * med;
			f += totalB;
			DEBUG("-> ", med, f);
			WRITE(med, f);
		}

		if (q == 1)
		{
			READ(llong, a, b);
			totalB += b;
			m.insert(a);
