            if(i == 0){
                median = make_pair(a, cnt);
            }
            else{
                if(make_pair(a, cnt) < median){
                    if(cnt % 2 == 0){
                        // left
                        auto temp = s.find(median);
                        temp--;
                        rightSum += median.first;
                        leftSum += a;
                        median = *temp;
                    }
                    else{
                        // same
                        leftSum += a;
                        leftSum -= median.first;
                    }
                }
                else{
                    if(cnt % 2 == 0){
                        // same
                        rightSum += a;
                        leftSum += median.first;
                    }
                    else{
                        // right
                        auto temp = s.find(median);
                        temp++;
                        rightSum += a;
                        median = *temp;
                        rightSum -= median.first;
                    }
                }
            }
        }
        else{
            long long ans = bSum - leftSum + rightSum;
            cout << median.first << " " << ans << "\n";
        }
    }

