struct BIT{
    vector<ll> bt;
    ll n,m;
    BIT(ll n_){
        n=n_;m=1;
        while(m<=n_) m*=2;
        m/=2;
        bt.resize(n+1);
    }
    ll sum(ll i){
        if(!i) return 0;
        return bt[i]+sum(i-(i&-i));
    }
    ll sum(ll i,ll j){
        return sum(j-1)-sum(i-1);
    }
    ll ad(ll i,ll x){
        if(i>n) return i;
        bt[i]+=x;
        ad(i+(i&-i),x);
        return i;
    }
    ll lb(ll k){
        ll x=0;
        for(int i=m;i>0;i/=2){
            if(x+i<=n&&bt[x+i]<k) {
                k-=bt[x + i];
                x+=i;
            }
        }
        return x+1;
    }
};

