ll lower = -1000000000000LL;
priority_queue<ll> L;
priority_queue<ll, vector<ll>, greater<ll>> R;

void merge()
{
  ll x = L.top();
  ll y = R.top();
  if (a <= x)
  {
    L.push(a);
  }
  else if (a >= y)
  {
    R.push(a);
  }
  else
  {
    L.push(a);
  }
  while (L.size() > R.size())
  {
    ll t = L.top();
    L.pop();
    R.push(t);
  }
  while (L.size() < R.size())
  {
    ll t = R.top();
    R.pop();
    L.push(t);
  }
  B += b;
  if (a < 0)
  {
    cnt_l++;
    A += abs(a);
  }
  else if (a > 0)
  {
    cnt_r++;
    A += abs(a);
  }
  else
  {
    cnt_zero++;
  }
}

void flush()
{
  ll val = L.top();
  ll ans = A + B;
  ll dist = abs(val);
  ll c = 0;
  if (val < 0)
  {
    c = cnt_l - cnt_r - cnt_zero;
  }
  else
  {
    c = cnt_r - cnt_l - cnt_zero;
  }
  ans -= dist * c;
  cout << val << " " << ans << endl;
}

int main()
{
  cin >> Q;
  L.push(-1000000000000LL);
  R.push(1000000000000LL);
  for (auto i = 0; i < Q; i++)
  {
    cin >> c;
    if (c == '1')
    {
      cin >> a >> b;
      merge();
    }
    else
    {
      flush();
    }
  }
}

