void update(long long a){
    long long first_top;
    long long last_top;
    if(!first_half.empty() && !last_half.empty()){
        first_top = first_half.top();
        last_top = last_half.top();

        if(a <= first_top){
            min_value += first_top - a;
        }    
        if(a >= last_top){
            min_value += a - last_top;
        }
    }
    first_half.push(a);
    last_half.push(a);
    if(first_half.top() > last_half.top()){
        first_top = first_half.top();
        first_half.pop();
        last_top = last_half.top();
        last_half.pop();
        first_half.push(last_top);
        last_half.push(first_top);
    }
}

