/// 逐次中央値更新するやつ。
template <class T = llong>
class MedianUpdater
{
	priority_queue<T, vector<T>, less<T> > leftQueue_;
	priority_queue<T, vector<T>, greater<T> > rightQueue_;
	T leftTotal_ = 0;
	T rightTotal_ = 0;
	T median_ = 0;

public:

	T median() const { return median_; }
	T leftTotal() const { return leftTotal_; }
	T leftCount() const { return leftQueue_.size(); }
	T rightTotal() const { return rightTotal_; }
	T rightCount() const { return rightQueue_.size(); }

	void insert(T a)
	{
		if (a < median_)
		{
			leftQueue_.push(a); leftTotal_ += a;
			if (leftQueue_.size() > rightQueue_.size())
			{
				rightQueue_.push(median_); rightTotal_ += median_;
				median_ = leftQueue_.top(); 
				leftQueue_.pop(); leftTotal_ -= median_;
			}
		}
		else
		{
			rightQueue_.push(a); rightTotal_ += a;
			if (rightQueue_.size() > leftQueue_.size() + 1)
			{
				leftQueue_.push(median_); leftTotal_ += median_;
				median_ = rightQueue_.top();
				rightQueue_.pop(); rightTotal_ -= median_;
			}
		}
	}
};

void solve()
{
	READ(int, Q);

	MedianUpdater m;
	llong totalB = 0;

	REP(i, Q)
	{
		READ(int, q);
		if (q == 2)
		{
			llong f = 0;
			llong med = m.median();
			f += m.leftCount() * med - m.leftTotal();
			f += m.rightTotal() - m.rightCount() * med;
			f += totalB;
			DEBUG("-> ", med, f);
			WRITE(med, f);
		}

		if (q == 1)
		{
			READ(llong, a, b);
			totalB += b;
			m.insert(a);
		}
	}



}

