                }

            }
            else {
                // idx = s.lower_bound(m);
                if(s.size()%2) {
                    idx = prev(idx);
                    pos--;
                    // cout << "a <\n" << endl;

                    dif = m-(*idx);
                    sa -= dif*pos;
                    sa += dif*(ll)(s.size()-pos-1);
                    m = *idx;
                }

            }
            // cout << "foi" << endl;
            // cout << "novo *idx = " << (*idx) << endl;

        }
        else {
            cout << m << " " << sa + sb << endl;
        }

    }


