using ll = long long;
using vec = vector<ll>;
using mat = vector<vec>;
using lst = list<int>;


int main()
{
	int Q;
	cin >> Q;
	map<int, int> mp;
	ll ans = 0;

	--Q;
	int q;
	int num = 1;
	int a, b;
	cin >> q >> a >> b;
	mp[a] = 1;
	ans = b;
	int xi = 0; // 配列の何番目を見ているか
	int xj = 0; // 同じ数字の何番目を見ているか
	auto x = mp.find(a);

	for (int i = 0; i < Q; ++i)
	{
		cin >> q;
		if (q == 2)
		{
			cout << x->first << " " << ans << endl;
			continue;
		}
		cin >> a >> b;
		ans += b;
		if (num % 2 == 1)
		{
			// xi , x
			if (mp.count(a))mp[a]++;
			else mp[a] = 1;
			ans += abs(a - x->first);
		}
		else
		{
			if (xi == num / 2 && x->first >= a) // 1
			{
				if (mp.count(a))mp[a]++;
				else mp[a] = 1;
				ans += abs(a - x->first);
			}
			else if(xi == num / 2 && x->first < a) // 2
			{
				--xi;
				if (mp.count(a))mp[a]++;
				else mp[a] = 1;
				ans += abs(a - x->first);

				if (xj == 0)
				{
					ans -= x->first;

					x--;

					xj = x->second - 1;
					ans += x->first;
				}
				else
				{
					xj--;
				}
			}
			if (xi == num / 2-1 && x->first >= a) // 3
			{
				++xi;
				if (mp.count(a))mp[a]++;
				else mp[a] = 1;
				ans = +abs(a - x->first);

				if (xj == x->second - 1)
				{
					ans += x->first;
					x++;
					xj = 0;
					ans -= x->first;
				}
				else
				{
					xj++;
				}
			}
			else
			{
				if (mp.count(a))mp[a]++;
				else mp[a] = 1;
				ans = abs(a - x->first);
			}
			++num;
		}

	}


	return 0;
}

