int main(){
  int q;
  cin >> q;

  priority_queue<int, vector<int>, less<int>> l;
  priority_queue<int, vector<int>, greater<int>> r;

  long long l0 = -1000000000;
  long long r0 = +1000000000;

  long long lv = 0;
  long long rv = 0;

  long long k = 0;
  long long c = 0;

  vector<long long> med;

  while(q--){
    int t;
    cin >> t;
    if(t == 1){
      long long a, b;
      cin >> a,b;

      k += b;
      if(l.size() == 0){
        l.push(a);
        lv += abs(a - l0);
      }else if(l.top() >= a){
        l.push(a);
        lv += abs(a - l0);
        if(l.size() - r.size() > 1){
          long long tmp = l.top();
          lv -= abs(tmp - l0);
          l.pop();
          r.push(tmp);
          rv += abs(r0 - tmp);
        }
      }else{
        r.push(a);
        rv += abs(r0 - a);
        if(r.size() > l.size()){
          long long tmp = r.top();
          rv -= abs(r0 - tmp);
          r.pop();
          l.push(tmp);
          lv += abs(tmp - lv);
        }
      }

      assert((int)l.size() - (int)r.size() >= 0);
      assert((int)l.size() - (int)r.size() <= 1);
      if(l.size() && r.size())
        assert(l.top() <= r.top());

      c = l.top();

      med.push_back(a);
      sort(med.begin(), med.end());
      eprintln(med, ":",  med[(med.size()-1)/2], c);
      assert(med[(med.size()-1)/2] == c);

    }else if(t==2){
      long long ans = (long long)l.size() * abs(c - l0) - lv;
      ans += (long long)r.size() * abs(r0 - c) - rv;
      ans += k;

      println(c, ans);
    }
  }


  return 0;
}

