int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int Q; cin >> Q;
    priority_queue<int> que1;
    priority_queue<int, vector<int>, greater<int>> que2;
    int q, a, b; cin >> q >> a >> b;
    que1.push(a);
    ll ans = b;
    for (int i = 1; i < Q; i++) {
        cin >> q;
        if (q == 1) {
            cin >> a >> b;
            if (que1.size() == que2.size()) {
                int l = que1.top(); que1.pop();
                int r = que2.top(); que2.pop();
                if (a <= l) {
                    que1.push(a);
                    que1.push(l);
                    que2.push(r);
                    ans += l - a;
                }
                else if (a >= r) {
                    que1.push(l);
                    que1.push(r);
                    que2.push(a);
                    ans += a - r;
                }
                else {
                    que1.push(l);
                    que1.push(a);
                    que2.push(r);
                }
            }
            else {
                int c = que1.top(); que1.pop();
                if (a <= c) {
                    que1.push(a);
                    que2.push(c);
                    ans += c - a;
                }
                else {
                    que1.push(c);
                    que2.push(a);
                    ans += a - c;
