template<class T> struct BIT{
    int n;
    vector<T> node;

    BIT(int n_){
        n = n_;
        node.resize(n+1, 0);
    }

    T sum(int i){
        T s = 0;
        while(i){
            s += node[i];
            i -= i & -i;
        }
        return s;
    }

    void add(int i, T x){
        while(i <= n){
            node[i] += x;
            i += i & -i;
        }
    }
};

