                        l.emplace(s.top());
                        ls += s.top();
                        ss -= s.top();
                        s.pop();
                        s.emplace(a);
                        ss += a;
                    } else {
                        l.emplace(a);
                        ls += a;
                    }
                } else {
                    if (a > l.top()) {
                        s.emplace(a);
                        ss += a;
                    } else {
                        s.emplace(l.top());
                        ss += l.top();
                        ls -= l.top();
                        l.pop();
                        l.emplace(a);
                        ls += a;
                    }
                }
            } else {
                i32 v;
                if ((S(l) + S(s)) % 2) {
                    if (S(l) > S(s)) {
                        v = l.top();
                    } else {
                        v = s.top();
                    }
                } else {
                    v = l.top();
                }
                cout << v << ' ' << v * i64(S(l)) - ls * S(l) + ss * S(s) - v * i64(S(s)) + c << endl;
            }
        }
    }
    return 0;
}

