const int MAXcomb = 2000010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

const int MAXkai = 200010;
ll kai_memo[MAXkai];
ll kai(ll N){
  if(kai_memo[N] != 0) return kai_memo[N];
  if(N <= 1) return 1;
  return kai_memo[N] = N * kai(N-1) % MOD;
}

ll disit(ll s, ll base = 10){
  ll res = 0;
  while(s){
    res++;
    s /= base;
  }
  return res;
}


ll comb_naive(ll N, ll K){//Kが小さい時
  ll res = 1;
  ll nkai = 1;
  ll kkai = 1;
  ll n_kkai = 1;
  for(ll i = 1; i <= N; i++){
    nkai *= i;
    nkai %= MOD;
  }
  for(ll i = 1; i <= K; i++){
    kkai *= i;
    kkai %= MOD;
  }
  for(ll i = 1; i <= N-K; i++){
    n_kkai *= i;
    n_kkai %= MOD;
  }
  res = nkai * inverse(kkai) % MOD * inverse(n_kkai) % MOD;
  return res;
}



