template<typename T>
struct TriSearch {
	T solve(T left, T right, function<T(T)> pred, function<bool(T, T)> condition) {
		while (condition(left, right))
		{
			T lmid = (left * 2 + right) / 3;
			T rmid = (left + right * 2) / 3;
			T L = pred(lmid);
			T R = pred(rmid);
			if (L > R) left = lmid;
			else right = rmid;
		}
		return right;

	}
};

