struct LinerPart {//y=ax+b ,LB<= x <= RB
	int a;
	int b;
	int LB, RB;
	LinerPart(int a,int b,int lb,int rb):
		a(a),b(b),LB(lb),RB(rb){}
	bool operator<(const LinerPart ot)const {
		return LB < ot.LB || LB == ot.LB && (RB < ot.RB || RB == ot.RB && a < b);
	}
	LinerPart() {}
	 contanier<LinerPart> Seperate(const int a,const int b) const {
		if (a >= RB) {
			return { LinerPart(this->a - 1, this->b + a + b, this->LB, this->RB) };
		}else
			if (a <= LB)
			{
				return { LinerPart(this->a + 1,this->b - a + b,this->LB,this->RB) };
			}
			else
			{
				return{ LinerPart(this->a - 1, this->b + a + b, this->LB, a),
					LinerPart(this->a + 1,this->b - a + b,a,this->RB) };
			}
	}
	 pair<int, int> getminimPos()const {
		 if (a >= 0)
			 return pair<int, int>(LB, LB * a + b);
		 else
			 return pair<int, int>(RB, RB * a + b);
	}
};
