using namespace std;

priority_queue<LL> minHeap, maxHeap;

void balance() {
    while (abs((LL) (minHeap.size() - maxHeap.size())) > 1) {
        if (minHeap.size() > maxHeap.size()) {
            LL tmp = minHeap.top();
            minHeap.pop();
            maxHeap.push(tmp);
        } else {
            LL tmp = maxHeap.top();
            maxHeap.pop();
            minHeap.push(tmp);
        }
    }
}

int median_retrieve(void) {
    if (minHeap.empty() && maxHeap.empty()) return 0;

    if (minHeap.size() == maxHeap.size()) {
        return min(minHeap.top(), maxHeap.top());
    } else {
        if (minHeap.size() > maxHeap.size()) {
            return minHeap.top();
        } else {
            return maxHeap.top();
        }
    }
}

void median_insert(LL x) {
    if (x > median_retrieve()) {
        minHeap.push(x);
    } else {
        maxHeap.push(x);
    }
    balance();
}


