template<typename T>class DynamicMedian {
public:
    unsigned int num = 0;
    std::priority_queue<T> min_heap;                                   // 中央値より小さい値を管理
    std::priority_queue<T, std::vector<T>, std::greater<T>> max_heap;  // 中央値より大きい値を管理
    T total_minimum = 0;
    T total_maximum = 0;

    // xを挿入O(log n)
    void insert(T x) {
        if (num % 2 == 0) {
            this->max_heap.push(x);
            this->total_maximum += x;
        } else {
            this->min_heap.push(x);
            this->total_minimum += x;
        }
        balance();
        this->num++;
    }

    // 中央値を見つけるO(1)
    // 存在しない場合は0
    T find_median() {
        // 要素が存在しない
        if (this->num == 0) {
            return 0;
        }

        // サイズが偶数のときは小さい方を中央値とする
        if (num % 2 == 0) {
            return min_heap.top();
        } else {
            return max_heap.top();
        }
    }

    T absolute() {
        T x = this->find_median();
        T mini = std::abs(x * (T)this->min_heap.size() - this->total_minimum);
        T maxi = std::abs(x * (T)this->max_heap.size() - this->total_maximum);

        return mini + maxi;
    }


private:
    void balance() {
        if (min_heap.empty() or max_heap.empty()) {
            return;
        }

        // swap
        if (min_heap.top() > max_heap.top()) {
            T tmp;

            tmp = max_heap.top(); max_heap.pop();
            min_heap.push(tmp);
            this->total_maximum -= tmp;
            this->total_minimum += tmp;

            tmp = min_heap.top(); min_heap.pop();
            max_heap.push(tmp);
            this->total_maximum += tmp;
            this->total_minimum -= tmp;
        }
    }
};

