template <typename T>
struct BITCell {
	struct Inner {
		std::vector<T> buf;
		std::size_t lcount = 0;
		std::size_t rcount = 0;
	};
	std::unique_ptr<Inner> innerptr;
	void resize(size_t rdiff) {
		if (!innerptr) {
			innerptr =make_unique<typename BITCell<T>::Inner>();
			innerptr->buf.reserve(count + rdiff * 2 * 8);
		}
		//innerptr->buf.resize(innerptr->buf.size() + u6(count));
	}
	template <typename U,typename C>
	pair<s6,s6> calc(U & results,const C  & counts,u6 rcount) {
		for (auto p = start; p; p = p->next) {
			innerptr->buf.push_back(p->a);
		}
		start = nullptr;
		std::nth_element(innerptr->buf.begin(), innerptr->buf.begin() + rcount-1, innerptr->buf.end());
		s6  mean = innerptr->buf[rcount-1];
		results[0] = mean * counts[0] - results[0];
		results[1] -= mean * counts[1];
		for (auto d : innerptr->buf) {
			results[0] += mean>d?mean-d:d-mean;
		}
		return { mean,results[0] + results[1] };
	}
	DataBufT * start;
	T value=0;//sum
	u3 count = 0;
};
template <typename T>
struct BIT {
	constexpr static u6 bufsize = 1 << 10;
	BITCell<T> buf[bufsize+1];
	u6 count = 0;
	void insert(DataBufT & in) {
		auto k = BIT_traits<T>::calcKey(in.a);
		u6 x = k;
		if (buf[x].start) in.next=buf[x].start;
		buf[x].start = &in;
		for (; x<= bufsize;x+=u6(s6(x)& -s6(x))) {
			buf[x].value += in.a;
			++buf[x].count;
		}
		++count;
	}
	pair<s6, s6> sum() {
		u6 meancount = (count +1)/ 2;
		u6 counts[2] = {};
		s6 results[2] = {};
		u6 depth = bufsize;
		u6 prevcount = count;
		s6 prevvalue = buf[1024].value;
		u6 kbase = 0;
		while (1) {
			depth >>= 1;
			auto & bufref = buf[kbase + depth ];
			auto & bufrefc = buf[kbase + depth ].count;
			if (counts[0] + bufrefc < meancount) {
				results[0] += bufref.value;
				counts[0] += bufrefc;
				prevcount -= bufrefc;
				prevvalue -= bufref.value;
				kbase |= depth;
			}
			else {
				results[1] += prevvalue -bufref.value;
				counts[1] += prevcount-bufrefc;
				prevcount = bufrefc;
				prevvalue = bufref.value;
			}
			if (depth == 1)break;
		}
		//std::vector<int > v;
		//v.reserve
		u6 k = kbase + 1;
		u6 rcount = meancount-counts[0];
		auto & bufref = buf[k];
		u6 rdiff = abs<s6>(rcount- (bufref.count-rcount));
		bufref.resize(rdiff);
		return bufref.calc(results, counts, rcount);
		//v.resize(v.size() + bufref.count);
	}
};
