multiset<ll> low,high;
ll low_sum, high_sum;

void balance(){
	while(1){
		int ls = low.size();
		int hs = high.size();
		if(ls == hs || ls == hs+1) break;
		if(ls < hs){
			auto v = high.begin();
			low.insert(*v);
			low_sum += *v;
			high_sum -= *v;
			high.erase(v);
		} else{
			auto v = low.end();
			--v;
			high.insert(*v);
			high_sum += *v;
			low_sum -= *v;
			low.erase(v);
		}
	}
}

// optimal x is median of a's
void solve(){
	ll q; cin >> q;
	ll b_sum = 0;
	FOR(q){
		int n; cin >> n;
		// b value doesnt matter, we want to minimize |x-ai| for all valid i
		if(n==1){
			ll a,b; cin >> a >> b;
			b_sum += b;
			low.insert(a);
			low_sum += a;
			balance();
		} else{
			//debugs(low);
			//debugs(high);
			auto itr = low.end();
			--itr;
			ll median = *itr;
			ll ans = b_sum + median*low.size() - low_sum + high_sum - median*high.size();
			cout << median << " " << ans << '\n';
		}
	}
}

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);

	solve();
	return 0;
}

