template<class Type>
Type solve(Type res = Type()){
    ll asum = 0,bsum = 0;
    using Item = tuple<ll,ll,ll>;
    int Q; cin >> Q;
    vector<Item> Qs(Q);
    for(int i = 0; i < Q;i++){
        ll mode; cin >> mode;
        if(mode == 1){
            ll a,b; cin >> a >> b;
            Qs[i] = Item(mode,a,b);
        }else{
            Qs[i] = Item(mode,-1,-1);
        }
    }

    multiset<ll> lst,rst;
    for(int q = 0; q < Q; q++){
        ll mode,a,b; tie(mode,a,b) = Qs[q];
        if(q == 0){
            bsum += b;
            lst.insert(a);
            continue;
        }
        if(mode == 1){
            asum+=abs(*lst.rbegin()-a);


            lst.insert(a);
            if((lst.size() + rst.size())%2 == 1){ // odd
                while(lst.size() != 1 + rst.size()){
                    rst.insert(*lst.rbegin());

                    lst.erase(lst.lower_bound(*lst.rbegin()));
                }
            }else{ // even
                while(lst.size() != rst.size()){
                    rst.insert(*lst.rbegin());
                    lst.erase(lst.lower_bound(*lst.rbegin()));
                }
            }
            bsum+=b;
        }else{
            cout << *lst.rbegin() << " " << asum + bsum << endl;
        }
    }
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    solve(0);
    // cout << fixed << setprecision(15) << solve<ll>() << endl;
    return 0;
}

