using namespace std;
using ll = long long;

int const MAXN=220000;

vector<int> A;

int findPos(int x) {
	return int(upper_bound(A.begin(),A.end(),x)-A.begin()) - 1; 
}

struct fenwick {
	static const int SZ=2*MAXN;
	int cnt[SZ];
	ll sum[SZ];
	int totalCount;
	ll totalSum;

	void update(int pos,int d) {
		totalCount+=d;
		totalSum+=d*A[pos];
		for (int i=pos; i<SZ; i|=i+1) {
			cnt[i]+=d;
			sum[i]+=d*A[pos];
		}
	}

	void add(int x) {
		update(findPos(x),+1);
	}

	int queryCount(int x) const {
		int c=0;
		for (int i=findPos(x); i>=0; i&=i+1, i--) c+=cnt[i];
		return c;
	}

	ll querySum(int x) const {
		ll s=0;
		for (int i=findPos(x); i>=0; i&=i+1, i--) s+=sum[i];
		return s;
	}
};

int Q;
vector<tuple<int,int,int>> query;
fenwick F;

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(0);
	cout<<fixed<<setprecision(10);


	cin>>Q;
	rep(i,0,Q) {
		int q,a=0,b=0;
		cin>>q;
		if (q==1) cin>>a>>b;
		query.emplace_back(q,a,b);
		A.push_back(a);
	}

	sort(A.begin(),A.end());
	A.resize(int(unique(A.begin(),A.end())-A.begin()));

	ll totalB=0;
	rep(i,0,Q) {
		int q,a,b;
		tie(q,a,b)=query[i];

		if (q==1) {
			F.add(a);
			totalB+=b;
		} else {
			int l=-int(1e9+1),r=int(1e9+1);
			while (l<r) {
				int m=l+(r-l)/2;
				if (2*F.queryCount(m)<F.totalCount) l=m+1; else r=m;
			}

			int x=l;
			ll cnt=F.queryCount(x);
			ll sum=F.querySum(x);
			ll val=cnt*l-sum + (F.totalSum-sum)-(F.totalCount-cnt)*x + totalB;
			cout<<x<<" "<<val<<"\n";
		}
	}
}

