priority_queue<ll>l;
priority_queue<ll,vector<ll>,greater<ll> >r;

int main(){
  ll q;
  ll sum=0,lsum=0,rsum=0;
  cin>>q;

  for(int i=0;i<q;i++){
    int t;
    cin>>t;
    if(t==1){
      ll a,b;
      cin>>a>>b;
      sum+=b;

      ll max_l=INF;
      if(!l.empty())max_l=l.top();
      if(a<=max_l){
	l.push(a);
	lsum+=a;
      }
      else{
	r.push(a);
	rsum+=a;
      }

      if(!l.empty()&&(int)l.size()-(int)r.size()>1){
    	ll temp=l.top();l.pop();
    	r.push(temp);
    	lsum-=temp;
    	rsum+=temp;
      }
      else if(!r.empty()&&(int)r.size()-(int)l.size()>0){
	ll temp=r.top();r.pop();
	l.push(temp);
	rsum-=temp;
	lsum+=temp;
      }
    }
    else{
      if((int)l.size()-(int)r.size()==1){
    	ll x=l.top();
    	cout<<x<<' '<<x-lsum+rsum+sum<<endl;
      }
      else{
    	ll x=l.top();
    	cout<<x<<' '<<-lsum+rsum+sum<<endl;
      }
    }
  }

  return(0);
}

