template <typename T> class FenwickTree {
  const int n;
  std::vector<T> data;

public:
  /// @brief
  /// 長さ count の Fenwick Tree を作り，全ての要素を 0 で初期化する．
  /// @complexity $O(n)$
  FenwickTree(int count) : n(count), data(count, 0) { ; }

  /// @brief
  /// pos 番目の要素に値 value を加える．
  /// @complexity $O(\\log(n))$
  void add(int pos, const T &value) {
    assert(0 <= pos && pos < n);
    for (int i = pos; i < n; i |= i + 1) data[i] += value;
  }

  /// @brief
  /// 区間 [0, pos) 番目の範囲の和を求める．(pos = 0 のときは 0 を返す．)
  /// @complexity $O(\\log(n))$
  T sum(int pos) const {
    assert(0 <= pos && pos <= n);
    T res = 0;
    for (int i = pos - 1; i >= 0; i = (i & (i + 1)) - 1) {
      res += data[i];
    }
    return res;
  }

  /// @brief
  /// 区間 [l, r) 番目の範囲の和を求める．(l = r のときは 0 を返す．)
  /// @complexity $O(\\log(n))$
  T sum(int l, int r) const {
    assert(0 <= l && l <= r && r <= n);
    return sum(r) + (-sum(l));
  }
  using value_type = T;
  using update_type = T;
};

int main(void)
{
  LL q;
  cin >> q;
  vector<pair<LL,LL>> as;
  vector<LL> bs(1);
  vector<LL> qs;
  REP(i,q) {
    LL co;
    cin >> co;
    if(co == 1) {
      LL a,b;
      cin >> a >> b;
      as.emplace_back(a,as.size());
      bs.push_back(bs.back()+b);
    } else {
      qs.push_back(as.size());
    }
  }
  LL ass = as.size();
  sort(as.begin(),as.end());
  vector<pair<LL,LL>> upd(ass);
  REP(i,ass) {
    upd[as[i].second] = make_pair(i,as[i].first);
  }
  FenwickTree<LL> cbit(ass);
  FenwickTree<LL> bit(ass);
  LL pushed = 0;
  for(auto sz:qs) {
    while(pushed<sz) {
      auto p=upd[pushed];
      cbit.add(p.first, 1);
      bit.add(p.first, p.second);
      ++pushed;
    }
    LL l=0,r=ass;
    while(r-l>1) {
      LL p = (r+l)/2;
      if(cbit.sum(p)<=(sz-1)/2) l=p;
      else r=p;
    }
    LL x=as[l].first;
    LL answer = bs[pushed];
    answer += cbit.sum(l)*x - bit.sum(l);
    answer += bit.sum(l,ass) - cbit.sum(l,ass)*x;
    cout << x << " " << answer << endl;
  }
  return 0;
}

