struct MedianFinder {
  priority_queue<int> small;
  priority_queue<int, vector<int>, greater<>> large;
  int64_t s1 = 0, s2 = 0;
  void addNum(int num) {
    small.push(num);
    s1 += num;
    large.push(small.top());
    s2 += small.top();
    s1 -= small.top();
    small.pop();
    if (small.size() < large.size()) {
      s1 += large.top();
      small.push(large.top());
      s2 -= large.top();
      large.pop();
    }
  }

  int findMedian() {
    return small.top();
  }
};

void solve(std::istream &in, std::ostream &out) {
  int Q;
  in >> Q;
  MedianFinder median;
  int64_t sumb = 0;
  for (int i = 0; i < Q; ++i) {
    int a, b;
    in >> a;
    if (a == 1) {
      in >> a >> b;
      sumb += b;
      median.addNum(a);
    } else {
      int m = median.findMedian();
      out  << m << ' ' << sumb - median.s1 + median.s2 + (int64_t) m * ((int)median.small.size() - (int)median.large.size()) << '\n';
    }
  }
}

