namespace NyaGadget
{
	/*** 中央値分割ライブラリ ***/

	template <class T> struct MedianSplittingResult
	{
		priority_queue<T> lpq;
		priority_queue<T, vt<T>, greater<T>> rpq;

		vt<T> median;
		vt<T> add_lv;
		vt<T> add_rv;
		vt<T> sub_lv;
		vt<T> sub_rv;
	};

	template <class T> void MedianSplitting
	(T add, MedianSplittingResult<T>& res)
	{
		res.median.clear();
		res.add_lv.clear(); res.add_rv.clear();
		res.sub_lv.clear(); res.sub_rv.clear();
		if (res.lpq.empty())
		{	// 1つめの要素はlpqへ挿入
			res.lpq.push(add);
			res.add_lv.push_back(add);
			res.median.push_back(add);
			return;
		}

		if (Size(res.rpq) < Size(res.lpq))
		{	// Size(rpq)が小さいときだけrpqへの要素挿入を許可
			res.rpq.push(add);
			res.add_rv.push_back(add);
			if (res.rpq.top() < res.lpq.top())
			{	// rpqが小さいのはngなので交換
				ll ltemp = res.lpq.top();
				ll rtemp = res.rpq.top();
				res.lpq.pop(); res.rpq.pop();
				res.sub_lv.push_back(ltemp); res.sub_rv.push_back(rtemp);
				res.lpq.push(rtemp); res.rpq.push(ltemp);
				res.add_lv.push_back(rtemp); res.add_rv.push_back(ltemp);
			}
		}
		else
		{
			res.lpq.push(add);
			res.add_lv.push_back(add);
			if (res.rpq.top() < res.lpq.top())
			{	// rpqが小さいのはngなので交換
				ll ltemp = res.lpq.top();
				ll rtemp = res.rpq.top();
				res.lpq.pop(); res.rpq.pop();
				res.sub_lv.push_back(ltemp); res.sub_rv.push_back(rtemp);
				res.lpq.push(rtemp); res.rpq.push(ltemp);
				res.add_lv.push_back(rtemp); res.add_rv.push_back(ltemp);
			}
		}

		if (Size(res.lpq) != Size(res.rpq))
		{
			res.median.push_back(res.lpq.top());
		}
		else
		{
			res.median.push_back(res.lpq.top());
			res.median.push_back(res.rpq.top());
		}
	}
}

using namespace NyaGadget;

struct Query
{
	ll q = 0;
	ll a = 0;
	ll b = 0;
};

struct Ans
{
	ll x = 0;
	ll sum = 0;
};

int main(void)
{
	ll Q; cin >> Q;
	vt<Query> q(Q);

	ll lsum = 0;
	ll rsum = 0;
	ll bsum = 0;
	vector<Ans> ans;
	MedianSplittingResult<ll> msr;
	each(i, e, q)
	{
		cin >> e.q;
		if (e.q == 1)
		{
			cin >> e.a >> e.b;
			bsum += e.b;

			MedianSplitting<ll>(e.a, msr);
			each(i, e, msr.sub_lv) lsum -= e;
			each(i, e, msr.sub_rv) rsum -= e;
			each(i, e, msr.add_lv) lsum += e;
			each(i, e, msr.add_rv) rsum += e;
		}
		else
		{
			ll x = (Size(msr.median) == 1) ? msr.median[0] : min(msr.median[0], msr.median[1]);
			ll sum = abs(x * Size(msr.lpq) - lsum) + abs(x * Size(msr.rpq) - rsum) + bsum;
			ans.push_back({ x, sum });
		}
	}

	each(i, e, ans) cout << e.x << " " << e.sum << endl;
