  R_min = -L_max;
  cin >> Q;
  for(int i=0;i<Q;i++){
    ll mode,a,b;
    cin >> mode;
    if(mode == 1){
      cin >> a >> b;
      f1(a,b);
    } else {
      f2();
    }
  }
}

