multiset<ll> low,high;
ll low_sum, high_sum;

void balance(){
	while(1){
		int ls = low.size(), hs = high.size();
		if(ls == hs || ls == hs + 1) break;
		if(ls < hs){
			auto v = high.begin();
			low.insert(*v);
			low_sum += *v;
			high_sum -= *v;
			high.erase(v);
		} else{
			auto v = low.end();
			--v;
			high.insert(*v);
			high_sum += *v;
			low_sum -= *v;
			low.erase(v);
		}
	}
}


void solve(){
	ll q; cin >> q;
	ll b_sum = 0;
	FOR(q){
		int n; cin >> n;
		if(n==1){
			ll a,b; cin >> a >> b;
			b_sum += b;

			if(low.empty()){
				low.insert(a);
				low_sum += a;
			} else{
				auto itr = low.end();
				--itr;
				int prev_med = *itr;
				if(prev_med >= a){
					low.insert(a);
					low_sum += a;
				} else{
					high.insert(a);
					high_sum += a;
				}
			}
			balance();
		} else{
			auto itr = low.end();
			--itr;
			ll median = *itr;
			ll ans = b_sum + median*low.size() - low_sum + high_sum - median*high.size();
			cout << median << " " << ans << '\n';
		}
	}
}

