void solve(void)
{
  int Q; cin >> Q;

  // 最大値を取ってこれるようにする
  std::priority_queue<ll, vector<ll>, std::less<ll>> queMin{};

  // 最小値を取ってこれるようにする
  std::priority_queue<ll, vector<ll>, std::greater<ll>> queMax{};

  // 各キューの累積和
  ll sumMin{}, sumMax{};

  // 定数項
  ll teisuKou{};

  for (int _ = 0; _ < Q; ++_) {
    int cmd; cin >> cmd;
    if (cmd == 1) {
      // 更新クエリ
      ll a, b; cin >> a >> b;
      a += INF;
      teisuKou += b;

      if (queMin.size() <= queMax.size()) {
        // queMinを増やしたい
        if (queMax.empty()) {
          queMin.push(a);
          sumMin += a;
          continue;
        } else {
          auto m = queMax.top();
          if (a < m) {
            queMin.push(a);
            sumMin += a;
          } else {
            // a > m ならば、mをqueMinに移動してaをqueMaxに追加
            queMax.pop();
            sumMax -= m;

            queMin.push(m);
            sumMin += m;

            queMax.push(a);
            sumMax += a;
          }
        }
      } else {
        // queMaxを増やしたい。
        assert(!queMin.empty());

        auto m = queMin.top(); // 集合の最大値
        if (a > m) { // より大きいのでqueMaxに追加
          queMax.push(a);
          sumMax += a;
          continue;
        } else {
          // m をqueMaxに移動
          queMin.pop();
          sumMin -= m;

          queMax.push(m);
          sumMax += m;

          // aはqueMinに入れる
          queMin.push(a);
          sumMin += a;
        }
      }
    }

    if (cmd == 2) {
      // 求値クエリ

      // 中央値
      ll center;
      if (queMin.size() < queMax.size()) {
        center = queMax.top();
      } else {
        center = queMin.top();
      }

      ll distanceA = center * queMin.size() - sumMin;
      ll distanceB = sumMax - center * queMax.size();
      assert(distanceA >= 0);
      assert(distanceB >= 0);

      // 答える。
      ll x = center - INF;
      ll fx = distanceA + distanceB + teisuKou;
      cout << x << SPACE << fx << CRLF;
    }
  }
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

