ll Q;


void input() {
	scanf("%lld", &Q);
}

void solve() {
	vector<ll> a;
	ll b=0;
	ll sum=0;
	ll size=0;
	ll que1sum=0;
	ll que2sum=0;
	priority_queue<ll> que1;
	priority_queue<ll, vector<ll>, function<bool(ll,ll)>>que2(
		[](const ll &x, const ll &y){
			return x > y;
		}
	);	

	rep(i,Q){
		ll q;
		cin >> q;
		if(q==1){
			ll aa,bb;
			cin>>aa>>bb;
			sum+=aa;
			b+=bb;
			size++;
			if(size==1){
				que1.push(aa);
				que1sum=aa;
				continue;
			}
			if(size==2){
				ll q1=que1.top();
				if(q1<aa){
					que2.push(aa);
					que1sum=q1;
					que2sum=aa;
				}else{
					que2.push(q1);
					que1.pop();
					que1.push(aa);
					que1sum=aa;
					que2sum=q1;
				}
				continue;
			}
			if(que1.size()==que2.size()){
				ll q2=que2.top();
				if(q2<aa){
					que1.push(q2);
					que2.pop();
					que2.push(aa);
					que1sum+=q2;
					que2sum+=aa-q2;
				}else{
					que1.push(aa);
					que1sum+=aa;
				}
			}else{
				ll q1=que1.top();
				if(q1<aa){
					que2.push(aa);
					que2sum+=aa;
				}else{
					ll q1=que1.top();
					que2.push(q1);
					que1.pop();
					que1.push(aa);
					que1sum+=aa-q1;
					que2sum+=q1;
				}
			}
		}else{
			ll center=que1.top();
			ll ans=b;
			ans+=center*que1.size()-que1sum;
			ans+=que2sum-center*que2.size();
			printf("%lld %lld\n",center,ans);
		}
	}
}

signed main() {
	input();
	solve();
	return 0;
}

