int x[100010];
int base = 1e9;
template<class Type>
Type solve(Type res = Type()){
    ll asum = 0,bsum = 0;
    using Item = tuple<int,int,int>;
    int Q; cin >> Q;
    vector<Item> Qs(Q);
    int N = 0;
    for(int i = 0; i < Q;i++){
        int mode; cin >> mode;
        if(mode == 1){
            int a,b; cin >> a >> b;
            a+=base;
            Qs[i] = Item(mode,a,b);
            x[N++] = a;
        }else{
            Qs[i] = Item(mode,-1,-1);
        }
    }
    wavelet<int,100010,31> wv(N,x);

    int r = 0;
    for(int i = 0; i < Q;i++){
        if(i == 0){
            bsum += get<2>(Qs[i]);
            r++;
            continue;
        }
        int mode,a,b; tie(mode,a,b) = Qs[i];

        int k = r/2;
        ll targeta = wv.kth_number(0, r+1, k);

        if(mode == 1){
            asum += abs(targeta-a);
            bsum += b;
            r++;
        }else{
            cout << targeta-base << " " << asum + bsum << endl;
        }

    }
    return res;
}
