    priority_queue<ll, vector<ll>, greater<ll>> Ap;
    ll sm=0, sp=0;
    ll B = 0;

    rep(i,q){
        int tp;
        cin >>tp;
        if(tp==1){
            ll a,b;
            cin >>a >>b;

            if(Am.empty()){
                Am.push(a);
                sm += a;
            }
            else{
                if(Am.size() == Ap.size()){
                    ll t = Ap.top();
                    if(a < t){
                        Am.push(a);
                        sm += a;
                    }
                    else{
                        Am.push(t);
                        sm += t;
                        Ap.pop();
                        sp -= t;
                        Ap.push(a);
                        sp += a;
                    }
                }
                else{
                    assert(Am.size() == Ap.size()+1);
                    ll t = Am.top();
                    if(t < a){
                        Ap.push(a);
                        sp += a;
                    }
                    else{
                        Ap.push(t);
                        sp += t;
                        Am.pop();
                        sm -= t;
                        Am.push(a);
                        sm += a;
                    }
                }
            }
            B += b;
        }
        else{
            ll x = Am.top();

            ll ans = sp - sm + B;
            if(Am.size() > Ap.size()) ans += x;

            // dbg(vector<ll>(all(Am)));
            // dbg(vector<ll>(all(Ap)));
            cout << x << " " << ans << "\n";
        }
    }

    return 0;
}

