template<typename T>
class BITree {
    public:
        BITree(int n) : m_N(n + 1) { m_Tree.assign(m_N, 0); }
        // [1, i] の合計値を返す (log m_N)
        // 閉区間であることに注意
        T Sum(int i) {
            assert(i >= 1 && i < m_N);
            T s = 0;
            while(i > 0) { s += m_Tree[i]; i -= i & -i; }
            return s;
        }
        // [i, j] の合計値を返す (log m_N)
        // i < j
        // 閉区間であることに注意
        T Sum(int i, int j) {
            assert(i <= j);
            return Sum(j) - Sum(i-1);
        }
        // i 番目の要素(1-indexed)に x を足して更新 O(log m_N)
        void Add(int i, T x){ while(i < m_N) { m_Tree[i] += x; i += i & -i; } }
    private:
        int m_N;            // 要素数
        vector<T> m_Tree;   // BIT 本体
};

// 中央値を O(log N) で返せる multiset
class MedianMultiSet {
    public:
        void Insert(ll n) {
            m_Set.insert(n);
            if(m_Set.size() == 1) {
                m_Median = m_Set.begin();
            }
            else if(m_Set.size() % 2 == 0) {
                // 奇数 -> 偶数になった場合
                // 自分より大きい値なら、依然 m_Median が中央値
                // そうでないなら、一つポジションを下げる
                if(*m_Median > n) { m_Median--; }
            }
            else {
                // 偶数 -> 奇数になった場合
                // 自分より小さい値なら、依然 m_Median が中央値
                // そうでないなら、一つポジションを上げる
                if(*m_Median <= n) { m_Median++; }
            }
        }
        size_t Size() { return m_Set.size(); }
        const multiset<ll>& Get() const { return m_Set; }

        ll GetMedian() const { return *m_Median; }
    private:
        multiset<ll> m_Set;
        multiset<ll>::iterator m_Median;         // 中央値
};

ll Q;

signed main()
{
    cin >> Q;

    BITree<ll> neg_tree(MAX_N);
    BITree<ll> pos_tree(MAX_N);
    ll neg_size = 0;
    ll pos_size = 0;
    MedianMultiSet mset;

    ll sum_b = 0;
    REP(q, Q) {
        ll num;
        cin >> num;
        if(num == 1) {
            ll a, b;
            cin >> a >> b;
            sum_b += b;
            mset.Insert(a);
            // a の BIT への追加
            if(a < 0) {
                neg_size++;
                neg_tree.Add(neg_size, a);
            }
            else {
                pos_size++;
                pos_tree.Add(pos_size, a);
            }
        }
        else {
            ll median = mset.GetMedian();
            ll ans = sum_b;
            if(median < 0) {
                if(neg_size > 0) { ans += neg_tree.Sum(neg_size) - (median * neg_size); }
                if(pos_size > 0) { ans += pos_tree.Sum(pos_size) + (median * pos_size); }
            }
            else {
                if(neg_size > 0) { ans += neg_tree.Sum(neg_size) + (median * neg_size); }
                if(pos_size > 0) { ans += pos_tree.Sum(pos_size) - (median * pos_size); }
            }
            printf("%lld %lld\n", median, ans);
        }
    }
    return 0;
}

