const int maxn = 2e5 + 1000;

struct node
{
	int flag;
	ll a; ll b;
};

node Ask[maxn]; ll V[maxn]; ll Cpos[maxn]; ll C[maxn];

void add(int x, ll y, ll* c)
{
	while (x < maxn)
	{
		c[x] += y; x += lowbit(x);
	}
}

ll getsum(int x, ll* c)
{
	ll s = 0;
	while (x > 0)
	{
		s += c[x]; x -= lowbit(x);
	}
	return s;
}

int main()
{
	std::ios::sync_with_stdio(false);
	int T; cin >> T;
	int cnt = 0;
	for (int i = 1; i <= T; i++)
	{
		int flag; cin >> flag;
		Ask[i].flag = flag;
		if (flag == 2) continue;
		else
		{
			cin >> Ask[i].a >> Ask[i].b;
			V[cnt++] = Ask[i].a;
		}
	}
	V[cnt++] = -1e10;
	sort(V, V + cnt);
	cnt = unique(V, V + cnt) - V;
	ll num = 0; ll cons = 0;
	for (int i = 1; i <= T; i++)
	{
		if (Ask[i].flag == 1)
		{
			num += 1;
			int pos = lower_bound(V, V + cnt, Ask[i].a) - V;
			add(pos, 1, C); add(pos, V[pos], Cpos);
			cons += Ask[i].b;
		}
		else
		{
			int L = 0; int R = cnt; int mid;
			while (L <= R)
			{
				mid = (L + R) >> 1;
				if (getsum(mid, C) * 2 <= num)
					L = mid + 1;
				else  R = mid - 1;
			}

			if (mid != 1 && getsum(mid - 1, C) * 2 >= num) mid = mid - 1;

			ll c1 = getsum(mid, C); ll c2 = getsum(maxn - 1, C);
			ll cpos1 = getsum(mid, Cpos); ll cpos2 = getsum(maxn - 1, Cpos);
			ll pos = V[mid];

			ll ans = c1 * pos - cpos1 - (c2 - c1) * pos + (cpos2 - cpos1);
			ans += cons;
			cout << pos << ' ' << ans << endl;
		}
	}
	return 0;
}

