        Ls += R.top();
        L.push(R.top());
        Rs -= R.top();
        R.pop();
      }
      Assert((int)L.size() - (int)R.size() == 0 || (int)L.size() - (int)R.size() == 1);
    }
    else if (type == 2)
    {
      ll sz = (int)L.size() + (int)R.size();
      ll x = L.top();
      ll val = Rs - Ls + x * (sz % 2) + b_sum;
      cout << x << " " << val << "\n";
    }
  }
  return 0;
}

