	{
		ll sum,tot;
		int l,r;
	}Tree[MAXN<<2];
#define root Tree[o]
#define lson Tree[o<<1]
#define rson Tree[o<<1|1]
	void pushup(int o)
	{
		root.sum=lson.sum+rson.sum;
	}
	void BuildTree(int o,int l,int r)
	{
		root.l=l,root.r=r;
		root.sum=0;
		if(l==r)
			return;
		int mid=(l+r)>>1;
		BuildTree(o<<1,l,mid);
		BuildTree(o<<1|1,mid+1,r);
	}
	void upd(int o,int pos,int c)
	{
		int l=root.l,r=root.r;
		if(l==r)
		{
			root.sum+=c;
			return;
		}
		int mid=(l+r)>>1;
		if(pos<=mid)
			upd(o<<1,pos,c);
		else
			upd(o<<1|1,pos,c);
		pushup(o);
	}
	ll query(int o,int L,int R)
	{
		if(L>R)
			return 0;
		int l=root.l,r=root.r;
		if(L<=l && r<=R)
			return root.sum;
		ll res=0;
		int mid=(l+r)>>1;
		if(L<=mid)
			res+=query(o<<1,L,R);
		if(R>mid)
			res+=query(o<<1|1,L,R);
		return res;
	}
}Seg;
