  ll v = 0;

  for (int i = 0; i < AX.size(); ++i) {
    v += abs(x - AX[i]);
  }

  return v + B;
}

ll search(ll left, ll right) {
  for (int loop = 0; loop < maxLoop; ++loop) {
    if (fs((left * 2 + right) / 3) <= fs((left + right * 2) / 3)) {
      right = (left + right * 2) / 3;
    } else {
      left = (left * 2 + right) / 3;
    }
  }

  return (right + left) / 2;
}

