struct node{
  int l,r,lft,rgt;
  ll dsum,val;
  int lazy,req;
  node(){
    l = -(1<<30);
    r = (1<<30);
    lft = -1;
    rgt = -1;
    dsum = 0;
    val = 0;
    lazy = 0;
    req = 0;
  }
};

const int MX = 6500000;

node seg[MX];
int SZ = 1;

void propagate(int ind){
  int mid = (seg[ind].l+seg[ind].r);
  if(mid >= 0) mid /= 2;
  else{
  	mid = (mid-1)/2;
  }
  if(seg[ind].lft == -1){
    // seg.pb(node());
    seg[ind].lft = SZ;
    seg[SZ].l = seg[ind].l;
    seg[SZ].r = mid;
    SZ++;
  }
  if(seg[ind].rgt == -1){
    // seg.pb(node());
    seg[ind].rgt = SZ;
    seg[SZ].r = seg[ind].r;
    seg[SZ].l = mid+1;
    SZ++;
  }
  if(seg[ind].req == 0 or seg[ind].l == seg[ind].r) return;
  seg[seg[ind].lft].dsum = (ll)seg[ind].lazy*((ll)seg[seg[ind].lft].r-(ll)seg[seg[ind].lft].l+1);
  seg[seg[ind].lft].val = seg[seg[ind].lft].dsum;
  seg[seg[ind].lft].lazy = seg[ind].lazy;
  seg[seg[ind].lft].req = 1;

  seg[seg[ind].rgt].dsum = seg[seg[ind].lft].dsum;
  seg[seg[ind].rgt].val = seg[seg[ind].lft].val;
  seg[seg[ind].rgt].lazy = seg[seg[ind].lft].lazy;
  seg[seg[ind].rgt].req = 1;

  seg[ind].req = 0;
}

void upd(int ind, int l,int r,int d){

  if(seg[ind].l > r or seg[ind].r < l) return;
  if(seg[ind].l == seg[ind].r){
    seg[ind].dsum = d;
    seg[ind].val = d;
    return;
  }
  propagate(ind);
  // trace(ind,seg[ind].l,seg[ind].r,l,r,seg[ind].val,seg[ind].lft,seg[ind].rgt);
  if(l <= seg[ind].l and seg[ind].r <= r){
  	// cout << "bkl\n";
    seg[ind].dsum = (ll)d*((ll)seg[ind].r-(ll)seg[ind].l+1);
    seg[ind].val = seg[ind].dsum;
    seg[ind].lazy = d;
    seg[ind].req = 1;
    return;
  }
  upd(seg[ind].lft,l,r,d);
  upd(seg[ind].rgt,l,r,d);
  seg[ind].dsum = seg[seg[ind].lft].dsum+seg[seg[ind].rgt].dsum;
  seg[ind].val = min(seg[seg[ind].lft].val,seg[seg[ind].rgt].val+seg[seg[ind].lft].dsum);
  // trace(ind,seg[ind].l,seg[ind].r,l,r,seg[ind].val);
}

pair<int,int> query(int ind){
  // cout << ind << " " << h << " " << seg[ind].l << " " << seg[ind].r << endl;
  if(seg[ind].l == seg[ind].r) return {seg[ind].l,seg[ind].val};
  propagate(ind);
  if(seg[seg[ind].lft].val <= seg[seg[ind].lft].dsum+seg[seg[ind].rgt].val) return query(seg[ind].lft);
  pair<int,int> lol = query(seg[ind].rgt);
  return {lol.F,lol.S+seg[seg[ind].lft].dsum};
}

