/*
      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
const size_t MAX_BIT = 160 * 160 + 10;
typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;

struct MedianManager{
    ll sz = 0, median = 0;
    priority_queue<ll> lower;
    priority_queue<ll, vl, greater<ll>> upper;
    vl in, out;

    MedianManager(){in.resize(2); out.resize(2);}

    void update(ll v){
        sz++;
        if (sz == 1) median = v, in[0] = in[1] = out[0] = out[1] = -INF;
        else if (sz % 2 == 0){
            if (v < median) lower.push(v), upper.push(median), in[0] = v, in[1] = median, out[0] = out[1] = -INF;
            else lower.push(median), upper.push(v), in[0] = median, in[1] = v, out[0] = out[1] = -INF;
        }else if (sz % 2){
            ll lower_top = lower.top(), upper_bottom = upper.top();
            if (v < lower_top) median = lower_top, lower.pop(), lower.push(v), in[0] = v, out[0] = median, in[1] = out[1] = -INF;
            else if (v > upper_bottom) median = upper_bottom, upper.pop(), upper.push(v), in[1] = v, out[1] = median, in[0] = out[0] = -INF;
            else median = v, in[0] = out[0] = in[1] = out[1] = -INF;
        }
    }

    ll size(){return sz;}
    pl medians(){return sz % 2 ? mp(median, median) : mp(lower.top(), upper.top());}
};

void solve(){
    // generate_array(size, min, max);
    ll Q; in1(Q);
    ll exc = 0, l = 0, u = 0;
    MedianManager med;

    rep(i, Q){
        ll mode; in1(mode);
        if (mode == 1){
            ll a, b; in2(a, b);
            ll cl, cu, nl, nu; exc += b;
            med.update(a);
            l += max(0LL, med.in[0]) - max(0LL, med.out[0]);
            u += max(0LL, med.in[1]) - max(0LL, med.out[1]);
        }else{
            if (med.size() % 2) prl2(med.median, u - l + exc);
            else prl2(med.lower.top(), u - l + exc);
        }
    }

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

void test(ll num = 0, bool verbose = false){
