typedef long long ll;

const int maxLoop = 100;
vector<ll> A;
ll B = 0;

ll f(ll x) {
  ll v = 0;

  for (int i = 0; i < A.size(); ++i) {
    v += abs(x - A[i]);
  }

  return v + B;
}

ll search(ll left, ll right) {
  for (int loop = 0; loop < maxLoop; ++loop) {
    if (f((left * 2 + right) / 3) <= f((left + right * 2) / 3)) {
      right = (left + right * 2) / 3;
    } else {
      left = (left * 2 + right) / 3;
    }
  }

  return (right + left) / 2;
}

int main() {
  int Q;
  cin >> Q;
  ll cache = 0;
  ll cx;

  for (int i = 0; i < Q; ++i) {
    int type, a, b;
    cin >> type;

    if (type == 1) {
      cin >> a >> b;
      A.push_back(a);
      B += b;
      cache = -1;
    } else if (cache > 0) {
      cout << cx << " " << cache << endl;
    } else {
      ll x = search(-10000000000, 10000000000);
      cache = f(x);
      cx = x;
      cout << x << " " << cache << endl;
    }
  }

  return 0;
}

