                sm0 += a0;
                sm1 -= a0;
            }
        }else{
            long long med = pq0.top();
            long long ans = med * (pq0.size() - pq1.size()) + B;
            ans += sm1 - sm0;
            cout << med << " " << ans << endl;
        }
    }

    return 0;
}

