struct AINT_MED {
    vector<int> aint;

    AINT_MED(int sz) {
        aint.resize(4 * sz + 5, 0);
    }

    void update(int pos, int node, int le, int ri) {
        if(le == ri)
            aint[node] ++;
        else {
            int mid = (le + ri) / 2;
            if(pos <= mid)
                update(pos, node * 2, le, mid);
            else
                update(pos, node * 2 + 1, mid + 1, ri);
            aint[node] = (aint[node * 2] + aint[node * 2 + 1]);
        }
    }

    int query(int nr, int node, int le, int ri) {
        if(le == ri)
            return le;
        else {
            int mid = (le + ri) / 2;
            if(nr <= aint[node * 2])
                return query(nr, node * 2, le, mid);
            else
                return query(nr - aint[node * 2], node * 2 + 1, mid + 1, ri);
        }
    }

    int query2(int from, int to, int node, int le, int ri) {
        if(from > to)
            return 0;

        if(from <= le & ri <= to)
            return aint[node];
        else {
            int mid = (le + ri) / 2;
            int ans = 0;
            if(from <= mid)
                ans += query2(from, to, node * 2, le, mid);
            if(mid < to)
                ans += query2(from, to, node * 2 + 1, mid + 1, ri);
            return ans;
        }
    }
};

struct AINT_SUM {
    vector<ll> aint;

    AINT_SUM(int sz) {
        aint.resize(4 * sz + 1, 0);
    }

    void update(int pos, int val, int node, int le, int ri) {
        if(le == ri)
            aint[node] += 1LL * val;
        else {
            int mid = (le + ri) / 2;
            if(pos <= mid)
                update(pos, val, node * 2, le, mid);
            else
                update(pos, val, node * 2 + 1, mid + 1, ri);
            aint[node] = aint[node * 2] + aint[node * 2 + 1];
        }
    }

    ll query(int from, int to, int node, int le, int ri) {
        if(from > to)
            return 0;
        if(from <= le && ri <= to)
            return aint[node];
        int mid = (le + ri) / 2;
        ll ans = 0;
        if(from <= mid)
            ans += query(from, to, node * 2, le, mid);
        if(mid < to)
            ans += query(from, to, node * 2 + 1, mid + 1, ri);
        return ans;
    }
};



