            if (n % 2)
            {
                if (a >= mid)
                {
                    s2 += a;
                }
                else
                {
                    s2 += mid;
                    auto it = set.lower_bound(mid);
                    if (it == set.begin())
                    {
                        mid = a;
                    }
                    else
                    {
                        --it;
                        if (a >= *it)
                            mid = a;
                        else
                        {
                            s1 += a;
                            s1 -= *it;
                            mid = *it;
                        }
                    }
                }
            }
            else
            {
                if (a <= mid)
                {
                    s1 += a;
                }
                else
                {
                    s1 += mid;
                    auto it = set.lower_bound(mid);

                    ++it;

                    if (a >= *it)
                    {
                        s2 += a;
                        mid = *it;
                        s2 -= mid;
                    }
                    else
                        mid = a;
                }
            }
            ++n;
            set.insert(a);
        }
        else
        {
            //std::cerr << "SS " << s1 << ' ' << s2 << std::endl;
            std::cout << mid << ' ' << bsum + s2 - n / 2 * mid + (n - 1) / 2 * mid - s1 << std::endl;
        }
    }

    return 0;
}

