multiset<ll, greater<ll>> med1;
multiset<ll> med2;
ll total1 = 0, total2 = 0;

ll med() {
  return *med1.begin();
}

void ins(ll v) {
  med1.insert(v);
  total1 += v;
  if (med1.size() > med2.size()+1) {
    auto it = med1.begin();
    total1 -= *it;
    total2 += *it;
    med2.insert(*it);
    med1.erase(it);
  }
}

