void solve() {
    //const i64 mod = 1'000'000'007;
    i64 Q;
    cin >> Q;

    priority_queue<i64,vector<i64>> l;
    priority_queue<i64,vector<i64>,greater<i64>> r;
    i64 ans=0,base=0;
    rep(i,0,Q){
        i64 q;
        cin >> q;
        if(q==1){
            i64 a,b;
            cin >> a >> b;
            base+=b;
            l.push(a);
            if(l.size()==1) continue;
            if(r.size()==0 and l.size()==2){
                i64 x=l.top();
                l.pop();
                i64 y=l.top();
                l.pop();
                ans+=x-y;
                l.push(y);
                r.push(x);
                continue;
            }
            if(l.top()<=r.top()) continue;
            else {
                i64 x=l.top(),y=r.top();
                ans+=x-y;
                l.pop();
                r.pop();
                l.push(y);
                r.push(x);
            }
        }else{
            cout << (l.size()>=r.size()?l.top():r.top()) << " " << ans+base << endl;
        }
    }
}

