template<class T, class U>
struct Zarted {
    unordered_map<T,ll> corresp_table; // corresp_table[x] → z
    unordered_map<T,ll> inv_corresp_table; // inv_corresp_table[z] → x
    vector<U> Z; 
};

template<class T, class U>
U id_convert(T t) { return t; } 

// 座標圧縮 & T → U 
// Xの位置情報は固定したままXを変換してZに格納する: Z[i] = convert(X[j])
// Xはコピーされる
template<class T, class U>
Zarted<T,U> zarts(vector<T> X, bool already_sorted, bool already_unique, const auto sort_algorism, function<U(T)> convert=id_convert<T,U>) { 
    unordered_map<T,ll> corresp_table;
    unordered_map<T,ll> inv_corresp_table;

    vector<U> Z(X.size());

    if (!already_sorted) {
        sort(ALL(X),sort_algorism);
    }
    if (!already_unique) {
        X.erase(unique(ALL(X)), X.end());
    }

    rep(i,X.size()) {
        T x = X[i];
        ll z = lower_bound(ALL(X), x, sort_algorism) - X.begin();
        corresp_table[x] = z; // x → z
        inv_corresp_table[z] = x; // z → x
        Z[z] = convert(x); // Z[z] = ?
    }

    return Zarted<T,U>{corresp_table,inv_corresp_table,Z};
}




