    LL la=0,ra=0;
    LL sum = 0;
    for(int i=0;i<n;i++){
        int x;cin >> x;
        if(x==1){
            LL l,r;cin >> l >> r;
            sum+=r;
            if(pa.size()==pb.size()){
                pa.push(l);
                la+=l;
            }
            else if(pa.size()>pb.size()){
                if(pa.top()>=l){
                    LL t = pa.top();pa.pop();
                    la+=l;
                    la-=t;
                    ra+=t;
                    pa.push(l);
                    pb.push(t);
                }
                else{
                    ra+=l;
                    pb.push(l);
                }
            }
        }
        else if(x==2){
            LL s=pa.top();
            cout <<s<<" " <<sum+(LL)pa.size()*s-la+ra-(LL)pb.size()*s << endl;
        }
    }
    return 0;
}

