struct UnionFind{
  //par[i]データiの属する木の親の番号。i==par[i]のときデータiは木の根ノードである
  vector<int>par;
  //sizes[i]:根ノードiの木に含まれるデータ数、iが根ノードでないときは無意味な値になる
  vector<int>sizes;

  UnionFind(int n):par(n),sizes(n,1){
    //最初は全てのデータiがグループiに存在するものとして初期化
    for(int i=0;i<n;i++){
      par[i]=i;
    }
  }
  //データxが属する木の根を得る
  int find(int x){
    if(x==par[x]){
      return x;
    }
    return par[x]=find(par[x]);

  }
  //2つのデータx,yが属する木をマージする
  void unite(int x,int y){
    //データの根ノードを得る
    x=find(x);
    y=find(y);
    //もしすでに同じ木に属しているならマージの必要はない
    if(x==y){
      return;
    }
    //xの木がyの木よりも大きくなるようにする
    if(sizes[x]<sizes[y]){
      swap(x,y);
    }
    //xがyの親になるように連結する
    par[y]=x;
    sizes[x]+=sizes[y];

  }
  //2つのデータx,yが属する木が同じならtrueを返す
  bool same(int x,int y){
    return find(x)==find(y);
  }
  //データxが含まれる木の大きさを返す
  int size(int x){
    return sizes[find(x)];
  }

};

//クラスカル法
//頂点a,bをつなぐコストcostの（無向）辺
struct Edge{
  int a,b,cost;
  //コストの大小で順序定義
  bool operator<(const Edge& o)const{
    return cost<o.cost;
  }
};
//頂点数と辺集合の組として定義したグラフ
struct Graph{
  int n;//頂点数
  vector<Edge>es;//辺集合
  //クラスカル法で無向最小全域木のコストの和を計算する
  //グラフが非連結の時は最小全域森のコストの和になる
  //使い方http://dai1741.github.io/maximum-algo-2012/docs/minimum-spanning-tree/
  int kruskal(){
    //コストが小さい順にソーと
    sort(es.begin(),es.end());
    UnionFind uf(n);
    int min_cost=0;
    for(int ei=0;ei<es.size();ei++){
      Edge& e=es[ei];
      if(!uf.same(e.a,e.b)){
        //その辺によって2つの木が連結される
        min_cost+=e.cost;
        uf.unite(e.a,e.b);

      }
    }
    return min_cost;
  }
};
