                if(zen.empty()) zen.push(A[i]), z_sum += A[i];
                else{
                    int x = kou.top();
                    if(A[i] <= x) zen.push(A[i]), z_sum += A[i];
                    else {
                        kou.pop(), k_sum -= x;
                        kou.push(A[i]), k_sum += A[i];
                        zen.push(x), z_sum += x;
                    }
                }
            }
        }
        else {
            ll y = zen.top();
            long long res = (y * (int)zen.size() - z_sum) + (k_sum - y * (int)kou.size()) + sum;
            cout << y << " " << res << endl;
        }
    }
}

