using namespace std;
typedef long long ll;

int main()
{
    int Q;
    cin >> Q;

    int t, a, b;
    ll min = 0;
    priority_queue<int> p;
    priority_queue<int, vector<int>, greater<int>> q;
    vector<pair<int, ll>> res;

    for (int i = 0; i < Q; i++) {
        cin >> t;
        if (t == 1) {
            cin >> a >> b;
            if (p.empty() || p.top() > a) {
                p.push(a);
                min += p.top() - a + b;
                if (p.size() > q.size() + 1) {
                    q.push(p.top());
                    p.pop();
                }
            }
            else if (q.empty() || q.top() < a) {
                q.push(a);
                min += a - q.top() + b;
                if (q.size() > p.size()) {
                    p.push(q.top());
                    q.pop();
                }
            }
            else {
                if (p.size() == q.size()) {
                    min += b;
                    p.push(a);
                }
                else {
                    min += a - p.top() + b;
                    q.push(a);
                }
            }
        }
        else {
            res.emplace_back(make_pair(p.top(), min));
        }
    }

    for (int i = 0; i < res.size(); i++) {
        cout << res[i].first << " " << res[i].second<< endl;
    }

    return 0;
}

