template <class T> struct Fenwick {
	int n;
	V<T> seg;
	Fenwick(int _n = 0) : n(_n), seg(n + 1) {}
	/// i番目の要素にxを追加する
	void add(int i, T x) {
		i++;
		while (i <= n) {
			seg[i] += x;
			i += i & -i;
		}
	}
	/// [0, i)のsum
	T sum(int i) {
		T s = 0;
		while (i > 0) {
			s += seg[i];
			i -= i & -i;
		}
		return s;
	}
	/// [a, b)のsum
	T sum(int a, int b) { return sum(b) - sum(a); }

	// sum[0, idx) >= xなる最小のidx(sum[0, n) < x なら n+1)
	int sum_lower_bound(T x) {
		if (x <= 0) return 0;
		int res = 0, len = 1;
		while (2 * len <= n) len *= 2;
		for (; len >= 1; len /= 2) {
			if (res + len <= n && seg[res + len] < x) {
				res += len;
				x -= seg[res];
			}
		}
		return res + 1;
	}
};


signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int N;
	cin >> N;
	vector<pair<int, int> > res;
	Fenwick<int> ft1(N + 10);
	Fenwick<int> ft2(N + 10);
	int sum = 0;
	vector<int> T(N);
	vector<int> A(N);
	vector<int> B(N);
	vector<pair<int, int> > X;
	for (int i = 0; i < N; i++) {
		cin >> T[i];
		if (T[i] == 1) {
			cin >> A[i] >> B[i];
			X.emplace_back(A[i], i);
		}
	}

	int t = 0;
	map<pair<int, int>, int>mp;
	vector<int> rev;
	sort(X.begin(), X.end());
	for (int i = 0; i < X.size(); i++) {
		rev.push_back(X[i].first);
		mp[X[i]] = t;
		t++;

	}
	int cnt = 0;
	for (int i = 0; i < N; i++) {
		if (T[i] == 1) {
			sum += B[i];
			int z = mp[make_pair(A[i], i)];
			ft1.add(z, 1);
			ft2.add(z, A[i]);
			cnt++;
		}
		else {
			int L = (cnt + 1) / 2;
			int idx = ft1.sum_lower_bound(L) - 1;

			int val = rev[idx] * L - ft2.sum(idx + 1);
			val += ft2.sum(idx + 1, N + 2) - rev[idx] * (cnt - L);
			res.emplace_back(rev[idx], val + sum);
		}
	}
	for (int i = 0; i < res.size(); i++) {
		cout << res[i].first << " " << res[i].second << endl;
	}
}

