int main() {
	cin >> q;
	rep(i, q) {
		int t;
		cin >> t;
		if (t == 1) {
			update[i] = true;
			cin >> a[i] >> b[i];
			compress.push_back(a[i]);
		}
		sum_b[i + 1] += sum_b[i] + b[i];
	}

	//sort(compress.begin(), compress.end());
	compress.erase(unique(All(compress)), compress.end());
	m = compress.size();
	binary_indexed_tree<int> bit1(m + 10);
	binary_indexed_tree<lint> bit2(m + 10);

	rep(i, q) {
		if (update[i]) {
			n++;
			int index = lower_bound(All(compress), a[i]) - compress.begin();
			bit1.add(index + 1, 1);
			bit2.add(index + 1, a[i]);
		}
		else {
			int mid_index;
			{
				int l = 0, r = m;
				while (r - l > 1) {
					int mid = l + (r - l) / 2;
					if (bit1.sum(mid) >= (n + 1) / 2) r = mid;
					else l = mid;
				}
				mid_index = r - 1; //0-indexed
			}

			lint j = mid_index;

			lint x = compress[j];
			lint left = bit1.sum(j) * x - bit2.sum(j);
