int Q;
long long f_b = 0;
multiset<pair<long long, int>> as;
pair<long long, int> mid = make_pair(0, -1);
long long dist_sum = 0;


void insert(long long a){
    auto target_itr = as.lower_bound(make_pair(a + 1, 0));
    int idx = 0;
    if(prev(target_itr)->first == a){
        idx = prev(target_itr) -> second + 1;
    }
    as.insert(make_pair(a, idx));
}


void query1(long long a, long long b){
    f_b += b;
    if(mid.second == -1){
        as.insert(make_pair(a, 0));
        mid = make_pair(a, 0);
        return;
    }
    insert(a);
    if(as.size() % 2){
        if(a < mid.first){
            dist_sum += mid.first - a;
        }else{
            mid = *next(as.find(mid));
            dist_sum += (a - mid.first);
        }
    }else{
        if(a < mid.first){
            auto new_mid = *prev(as.find(mid));
            dist_sum += mid.first - a;
            mid = new_mid;
        }else{
            dist_sum += a - mid.first;
        }
    }

}

void query2(){
    cout << mid.first << " " << dist_sum + f_b << endl;
}

