// set (multiset) を二本もって左半分と右半分に分ける
struct MedianList {
  const ll INF = 10e10;
  multiset<ll> left, right;

  double median() { 
    ll l = *(--left.end());
    ll r = *right.begin();
    if (left.size() > right.size()) return l;
    else if (left.size() < right.size()) return r;
    // left.size() == right.size()
    return (l+r)/2;
  }

  ll getLeft() { 
    auto it = left.end();
    --it;
    return *it;
  }
  ll getRight() { 
    auto it = right.begin();
    return *it;
  }

  void insert(ll x) { 
    if (right.size() == 0) {
      left.insert(x);
    }
    else {
      ll r = getRight();
      if (x < r) left.insert(x);
      else right.insert(x);
    }
    int nl = left.size();
    int nr = right.size();
    while (nl-nr > 1) {
      auto it = left.end();
      --it;
      right.insert(*it);
      left.erase(it);
      nl = left.size();
      nr = right.size();
    }
    while (nr-nl > 1) {
      auto it = right.begin();
      left.insert(*it);
      right.erase(it);
      nl = left.size();
      nr = right.size();
    }
