					int tmp = big.top();
					if(a <= tmp) {
						small.push(a);
						small_sum += a;
					} else {
						big.pop();
						small.push(tmp);
						big.push(a);
						big_sum += a;
					}

				} else {
					if(big.empty()) {
						big.push(a);
						big_sum += a;
