			query[i] = {q, a, b};
		}
		else {
			query[i] = {q, -1, -1};
		}
	}

	cx.push_back(-INF);
	cx.push_back(INF);

	sort(ALL(cx));
	cx.erase(unique(ALL(cx)), cx.end());

	int sz = cx.size();
	LazySegTree seg(cx.size());
	SegmentTree<int> seg2(cx.size(), [](int l, int r) {
		return l + r;
	}, 0);

	ll base = 0;
	for (auto cur : query) {
		int q, a, b;
		tie(q, a, b) = cur;
