			seg.add(0, idx, a);
			seg2.add(idx, 1);
			base += b;
		}
		else {
			int allc = seg2.fold(0, sz);
			int ob = (allc + 1) / 2;
			int idx = seg2.lower_bound(ob);
			ll ans = seg.query(idx, idx + 1);

			int c = seg2.fold(0, idx + 1);
			ans += (ll)(c - (allc - c)) * cx[idx];
			ans += base;
			printf("%d %lld\n", cx[idx], ans);
		}
	}
