            if(lque.size() != 0) precenter = lque.top();
            ans += abs(precenter - a);
            if(lque.size() == 0) lque.push(a);
            else if(lque.top() <= a) {
                if(rque.size() >= lque.size()) {
                    int trans = rque.top();
                    rque.pop();
                    lque.push(trans);
                    rque.push(a);
                }else {
                    rque.push(a);
                }
            }else {
                if(lque.size() > rque.size()) {
                    int trans = lque.top();
                    lque.pop();
                    rque.push(trans);
                    lque.push(a);
                }else {
                    lque.push(a);
                }
            }

            int center = a;
            if(lque.size() != 0) center = lque.top();
            if(precenter < center) ans -= center - precenter;
            ans += (center - precenter) * (lque.size() - rque.size());
        }
    }
}

