int main() {
	int q = in;
	multiset<ll> S, B;
	ll sumS = 0, sumB = 0;
	ll T = 0;

	auto Bin = [&](ll x) {
		B.insert(x);
		sumB += x;
	};
	auto Sin = [&](ll x) {
		S.insert(x);
		sumS += x;
	};
	auto BtoS = [&] {
		ll tmp = *B.begin(); B.erase(B.begin()); sumB -= tmp;
		S.insert(tmp); sumS += tmp;
	};
	auto StoB = [&] {
		ll tmp = *prev(S.end()); S.erase(prev(S.end())); sumS -= tmp;
		B.insert(tmp); sumB += tmp;
	};

	auto fit = [&]() {
		while (sz(S) > sz(B) + 1) { StoB(); }
		while (sz(S) < sz(B)) { BtoS(); }
	};

	auto update = [&](ll a, ll b) {
		T += b;
		if (sz(B) && *B.begin() <= a) {
			Bin(a);
		} else {
			Sin(a);
		}
		fit();
		dump(S, B, T);
	};

	auto answer = [&]() {
		dump(S, B);
		ll X = *prev(S.end());
		ll Y = abs(sumS - X * sz(S)) + abs(sumB - X * sz(B)) + T;
		out(X, Y);
	};

	rep(i, q) {
		int com = in;
		if (com == 1) {
			LL(a, b);
			update(a, b);
		} else {
			answer();
		}
	}
}

