int bsum, q, a, b;
int ls, rs;
multiset<int> stl, str;

void balance() {
	if(str.size() > stl.size()) {
		int x = *str.begin();
		stl.insert(x);
		str.erase(str.find(x));
		rs -= x;
		ls += x;
	}
	else if(stl.size() - 1 > str.size()) {
		auto it = stl.end();
		it--;
		int x = *it;
		str.insert(x);
		stl.erase(stl.find(x));
		rs += x;
		ls -= x;
	}
}

void upd() {
	cin >> a >> b;
	bsum += b;
	if(stl.empty()) {
		stl.insert(a);
		ls += a;
		return;
	}
	auto it = stl.end();
	it--;
	int med = *it;
	if(a <= med) {
		ls += a;
		stl.insert(a);
	}
	else {
		str.insert(a);
		rs += a;
	}
	balance();
}

void solve() {
	int res = bsum;
	auto it = stl.end();
	it--;
	int x = *it;
	res -= ls;
	res += rs;
	res += -x * str.size();
	res += x * stl.size();
	cout << x << " " << res << '\n'; 
}

