	a_distance += a-center;
	upper.insert(a);
      }else{
	a_distance += center-a;
	lower.insert(a);
      }


      if(upper.size() > lower.size() + 1){
	int prev_center = center;
	a_distance += (center-prev_center)*(lower.size() + 1 - upper.size());
	lower.insert(center);
	center = *(upper.begin());
	upper.erase(upper.begin());
