#include<bits/stdc++.h>
using namespace std;
using ll=long long;

class lazyseg
{
	int n,size;
	vector<ll> node,lazy;
public:
	lazyseg(vector<ll> a)
	{
		n=a.size();
		size=1;
		while (size<n) size*=2;
		node.resize(2*size-1,0);
		lazy.resize(2*size-1,0);
	}

	void lazy_eva(int k,int l,int r)
	{
		if (lazy[k]!=0)
		{
			node[k]+=lazy[k];
			if (r-l>1)
			{
				lazy[2*k+1]=lazy[k]/2;
				lazy[2*k+2]=lazy[k]/2;
			}
			lazy[k]=0;
		}
	}
	void add_point (int a,int x) //0-indexed
	{
        a+=size-1;
		node[a]+=x;
		while (a>0)
        {
            a=(a-1)/2;
            node[a]+=x;
        }
		return;
	}

	void add(int a,int b,ll x,int k=0,int l=0, int r=0) //0-indexed 
	{
		if (l>=r) {r=size;}
		lazy_eva(k,l,r);
		if (b<=l || r<=a) return ;
		if (a<=l && r<=b)
		{
			lazy[k]+=(r-l)*x;
			lazy_eva(k,l,r);
		}
		else
		{
			add(a,b,x,2*k+1,l,(l+r)/2);
			add(a,b,x,2*k+2,(l+r)/2,r);
			node[k]=node[2*k+1]+node[2*k+2];
		}
		return ;
	}

	ll sum(int a,int b, int k=0,int l=0,int r=0) //0-indexed
	{
		if (r<=l) r=size;

		if (r<=a || b<=l ) return 0;
		lazy_eva(k,l,r);
		if (a<=l && r<= b) return node[k];
		else return sum(a,b,2*k+1,l,(l+r)/2)+sum(a,b,2*k+2,(l+r)/2,r);
	}
};

int main()
{
	int Q;cin >>Q;
	ll a,b,q;
	ll su=0,ans=0;
	pair<ll,ll> ans_pair=make_pair(10000000000,0); //firstは数字、secondは個数
	map<ll,ll> cnt;
	vector<ll> A,order;
	vector<pair<ll,ll>> input;
	for (int i=0;i<Q;i++)
	{
		cin >>q;
		order.push_back(q);
		if (q==1)
		{
			cin >> a >>b;
			A.push_back(a);
			input.push_back(make_pair(a,b));
		}
	}
	sort(A.begin(),A.end());
 	lazyseg seg_plus(A);
	lazyseg seg_minus(A);
	lazyseg seg_count(A);
	int  addquery=0,index=0;
	auto itr=A.begin();
	for (int i=0;i<Q;i++)
	{
		if (order[i]==1)
		{
			a=input[addquery].first;
			su+=input[addquery].second;
			itr=lower_bound(A.begin(),A.end(),a);
			index=itr-A.begin()+cnt[a];
			seg_plus.add_point(index,a);
			seg_count.add_point(index,1);
			seg_minus.add_point(index,-a);
			cnt[a]++;
			addquery++;
			if (ans_pair.second<=cnt[a])
			{
				if (ans_pair.first>a || ans_pair.second<cnt[a])
					ans_pair.first=a;
					ans_pair.second=cnt[a];
			}
		}
		else
		{
			ans=0;
			a=ans_pair.first;
			itr=lower_bound(A.begin(),A.end(),a);
			index=itr-A.begin();


			seg_plus.add(index,A.size(),-a);
			seg_minus.add(0,index,a);
			ans=su+seg_plus.sum(index,A.size())+seg_minus.sum(0,index)+a*(A.size()-index-seg_count.sum(index,A.size()))-a*(index-seg_count.sum(0,index));

			seg_plus.add(index,A.size(),a);
			seg_minus.add(0,index,-a);
			cout << a << " " << ans << endl;
		}

	}


	return 0;
}

