            cin >> a >> b;
            base+=b;
            l.push(a);
            if(l.size()==1) continue;
            if(r.size()==0 and l.size()==2){
                i64 x=l.top();
                l.pop();
                i64 y=l.top();
                l.pop();
                ans+=x-y;
                l.push(y);
                r.push(x);
                continue;
            }
            if(l.top()<=r.top()) continue;
            else {
                i64 x=l.top(),y=r.top();
                ans+=x-y;
                l.pop();
                r.pop();
                l.push(y);
                r.push(x);
            }
        }else{
            cout << l.top() << " " << ans+base << endl;
        }
    }
}

