            if (first == -2000000000) first = u[i];
        }
        else {
            if (cnt == 1) {
                cout << first << ' ' << sumB << "\n";
                continue;
            }
            if (cnt == 2) {
                ll last = sumA - first;
                cout << min(first, last) << ' ' << sumB + abs(last - first) << "\n";
                continue;
            }
            ll x = sumA / cnt;
            // cout << x << endl;
            ll res = 0, vt = 0;
            if (sumA % cnt == 0) {
                res = getRes(x, N) + sumB;
                vt = x;
            }
            else {
                ll w = getRes(x-1, N);
                ll p = getRes(x, N);
                ll q = getRes(x+1, N);
                res = w;
                vt = x-1;
                if (p < res) {
                    res = p;
                    vt = x;
                }
                if (q < res) {
                    res = q;
                    vt = x+1;
                }
                res += sumB;
            }
            cout << vt << ' ' << res << "\n";
        }
    }
    return 0;
}

