        loop++;
        cout << '#' << loop << "#------\n";
        solver(fs, cout).run();
    }
    if(loop <= 1) {
        cout << "===" << endl;
        while(cin) solver(cin, cout).run();
    }
#else
    solver(cin, cout).run();
#endif
    return 0;
}


void solver::run(){
    ll Q = 0;
    is >> Q;
    while(Q--){
        int t; is >> t;
        if(t == 2) {
            ll x = 0;
            if(right.size() != left.size()){
                x = left.top();
            }
            os << left.top() << ' ' ;
            os << bs + as + x << endl;
            continue;
        }
        ll a, b;
        is >> a >> b;
        bs += b;
        if(left.size() <= right.size()){
            left.push(a);
            as -= a;
        }
        else {
            right.push(a);
            as += a;
        }
        if(right.empty()) continue;

        while(left.top() > right.top()){
            auto lm = left.top();
            auto rm = right.top();
            right.pop();
            left.pop();
            right.push(lm);
            left.push(rm);
            as += 2*(lm - rm);
        }
    }
}

