template <typename T = s6>
struct midianset {
	multiset<T> s;
	typename multiset<T>::iterator mid;
	s6 lsum = 0;
	s6 rsum = 0;
	s6 sums[2] = {};
	auto size()const { return s.size(); }
	void insert(T val) {
		if (s.size() == 0) mid = s.insert(val);
		else {
			s.insert(val);
			if (val < *mid) {
				lsum += val;
				if ((s.size() & 1) == 0) {
					rsum += *mid;
					--mid;
					lsum -= *mid;
				}
			}
			else {
				rsum += val;
				if ((s.size() & 1) == 1) {
					lsum += *mid;
					++mid;
					rsum -= *mid;
				}
			}
		}
	}
	auto sum() const noexcept {
		return tuple<T, T, T>(lsum, *mid, rsum);
	}
};

