{
    cout << fixed << setprecision(15);
    ll Q;
    cin >> Q;

    //　降順のキュー
    priority_queue<ll> max_que;

    // 昇順のキュー
    priority_queue<
      ll,                // 要素の型はint
      vector<ll>,   // 内部コンテナはstd::vector (デフォルトのまま)
      greater<ll>   // 昇順 (デフォルトはstd::less<T>)
    > min_que;


    ll ans = 0;

    ll left;
    ll right;

    REP(i, Q){
        ll query;
        cin >> query;
        if(query == 1){
            ll a, b;
            cin >> a >> b;

            ans += b;

            // 最初に何もないとき
            if(max_que.empty()){
                max_que.push(a);
                left = a;
                continue;
            }
            // 2番目の値が来たとき
            if(min_que.empty()){
                min_que.push(a);

                // 左右のキューで大小が異なるとき
                if(max_que.top() > min_que.top()){
                    ll tempa = max_que.top();
                    max_que.pop();
                    ll tempb = min_que.top();
                    min_que.pop();

                    // キューの最小と最大を入れ替え
                    max_que.push(tempb);
                    min_que.push(tempa);
                }

                ans += min_que.top() - max_que.top();
                left = max_que.top();
                right = min_que.top();
                continue;
            }

            // 同じが左側のほうが数が少ないとき
            if(max_que.size() <= min_que.size()){
                max_que.push(a);

                // 左右のキューで大小が異なるとき
                if(max_que.top() > min_que.top()){
                    ll tempa = max_que.top();
                    max_que.pop();
                    ll tempb = min_que.top();
                    min_que.pop();

                    // キューの最小と最大を入れ替え
                    max_que.push(tempb);
                    min_que.push(tempa);
                }

                if(a < left || right > a){
                    ans += abs(left - a);
                }

                left = max_que.top();
                right = min_que.top();
                continue;
            }

            // 右側側のほうが数が少ないとき
            if(max_que.size() > min_que.size()){
                min_que.push(a);

                // 左右のキューで大小が異なるとき
                if(max_que.top() > min_que.top()){
                    ll tempa = max_que.top();
                    max_que.pop();
                    ll tempb = min_que.top();
                    min_que.pop();

                    // キューの最小と最大を入れ替え
                    max_que.push(tempb);
                    min_que.push(tempa);
                }

                ans += abs(left - a);

                left = max_que.top();
                right = min_que.top();
                continue;
            }

        }
        else{
            cout << left << " " << ans << endl;
        }
    }
    return 0;
}

