const int maxn = 500000 + 5;

int psz;
struct Node {
  int key, siz;
  LL sum;
  Node *ch[2];
  void update() {
    siz = ch[0]->siz + ch[1]->siz + 1;
    sum = ch[0]->sum + ch[1]->sum + key;
  }
} pool[maxn], *null = new Node();

Node *new_node(int k) {
  Node *i = pool + psz++;
  i->key = i->sum = k, i->siz = 1, i->ch[0] = i->ch[1] = null;
  return i;
}

class SBT {
  Node *root;

  void rotate(Node *&u, int d) {
    Node *v = u->ch[d ^ 1];
    u->ch[d ^ 1] = v->ch[d];
    v->ch[d] = u;
    v->siz = u->siz;
    u->update();
    u = v;
  }

  void maintain(Node *&u, int d) {
    if (u == null) return;
    if (u->ch[d]->ch[d]->siz > u->ch[d ^ 1]->siz)
      rotate(u, d ^ 1);
    else if (u->ch[d]->ch[d ^ 1]->siz <= u->ch[d ^ 1]->siz)
      return;
    else
      rotate(u->ch[d], d), rotate(u, d ^ 1);
    maintain(u->ch[0], 0);
    maintain(u->ch[1], 1);
    maintain(u, 0);
    maintain(u, 1);
  }

  void insert(Node *&u, int k) {
    if (u == null) {
      u = new_node(k);
      return;
    }
    // if (u->key == k) return false;
    int d = (k > u->key);
    insert(u->ch[d], k);
    maintain(u, d), u->update();
  }

  void erase(Node *&u, int k) {
    if (u == null) return;
    if (u->key == k) {
      if (u->ch[1] == null) {
        u = u->ch[0];
        return;
      }
      if (u->ch[0] == null) {
        u = u->ch[1];
        return;
      }
      Node *v = u->ch[1];
      while (v->ch[0] != null) v = v->ch[0];
      u->key = v->key;
      erase(u->ch[1], v->key);
      u->update();
      return;
    }
    erase(u->ch[k > u->key], k);
    u->update();
  }

 public:
  SBT() : root(null) { null->ch[0] = null->ch[1] = null; }
  int size() { return root->siz; }
  bool empty() { return root == null; }
  void clear() { root = null; }
  void insert(int k) { insert(root, k); }
  void erase(int k) { erase(root, k); }
  int rank(int k) {
    int ret = 0;
    for (Node *u = root; u != null;) {
      if (k > u->key) ret += u->ch[0]->siz + 1;
      u = u->ch[k > u->key];
    }
    return ret;
  }
  int select(int k, LL &y) {
    for (Node *u = root; u != null;) {
      int t = u->ch[0]->siz;
      if (k >= t) y += u->ch[0]->sum;
      if (k == t) return u->key;
      u = u->ch[k > t], k -= (k > t ? t + 1 : 0);
    }
    return inf;
  }
};

int main() {
  int n;
  scanf("%d", &n);
  SBT bst;
  LL s1 = 0, s2 = 0;
  while (n--) {
    int op, a, b;
    scanf("%d", &op);
    if (op == 1) {
      scanf("%d%d", &a, &b);
      s1 += a, s2 += b;
      bst.insert(a);
    } else {
      LL s = 0;
      int x = bst.select((bst.size() - 1) / 2, s), c = bst.rank(x);
      printf("%d %lld\n", x,
             (LL)x * c - s + s1 - s - (LL)x * (bst.size() - c) + s2);
    }
  }

  return 0;
}

