using namespace std;

typedef long long ll;
typedef unsigned long long ull;

struct F {
    vector<ll> a;
    priority_queue<ll, vector<ll>> less_a;
    priority_queue<ll, vector<ll>, greater<ll>> greater_a;
    ll b;

    F() {
        this->a = vector<ll>();
        this->b = 0;
    }

    void update(ll a, ll b) {
        if(less_a.empty())
            less_a.push(a);
        else if(less_a.size()==greater_a.size()) {
            if(a <= less_a.top()) {
                less_a.push(a);
            } else {
                less_a.push(greater_a.top());
                greater_a.pop();
                greater_a.push(a);
            }
        } else if(less_a.size()-greater_a.size()==1) {
            if(a < less_a.top()) {
                greater_a.push(less_a.top());
                less_a.pop();
                less_a.push(a);
            } else {
                greater_a.push(a);
            }
        }
        this->a.push_back(a);
        this->b = (this->b + b);
    }

    void print_minimum() {
        if(this->a.empty()) {
            cout << "0 0";
            return;
        }

        ll x = this->less_a.top();
        ll ans = 0;
        for(auto a : this->a)
            ans += abs(a - x);
        ans += this->b;
        cout << x << ' ' << ans << endl;
    }
};

int main() {
    int Q;
    cin >> Q;
    F f = F();

    for(int q=0; q<Q; q++) {
        char query_number;
        cin >> query_number;
        if(query_number == '1') {
            ll a, b;
            cin >> a >> b;
            f.update(a, b);
        } else {
            f.print_minimum();
        }

    }    
    return 0;
}

