    seg->v+=val;
    seg->prsu+=in;
    if(seg->l==seg->r)
    {
        return;
    }
    else
    {
        int m=(seg->l+seg->r)>>1;
        if(in<=m)
        {
            if(seg->le==NULL)
                seg->le=new node(seg->l,m);
            up(seg->le,in,val);
        }
        else{
            if(seg->ri==NULL)
                seg->ri=new node(m+1,seg->r);
            up(seg->ri,in,val); 
        }
    }
}
