using namespace std;

using ll = long long;
using Pl = pair < ll, ll >;

constexpr ll LLINF = (1LL << 60);

template < typename T > 
struct BIT {
    vector < T > dat;
    BIT (int n) { dat.assign(n + 1, 0); }

    void add(int k, T x) {
        k++;
        while ( k <= dat.size() ) dat[k] += x, k += k & -k;
    }

    T query(int k) {
        T sum = 0;
        k++;
        while ( k > 0 ) sum += dat[k], k -= k & -k;
        return ( sum );
    }

    int lower_bound(T x) {
        int l, r;
        l = -1, r = dat.size();
        while ( l + 1 < r ) {
            int m = (l + r) / 2;
            if ( query(m) >= x ) r = m;
            else l = m;
        }
        return ( r );
    }
};

int Q;
int inst[200005], A[200005], B[200005];
ll sum = 0;
vector < Pl > compress;
int main()
{
    cin >> Q;
    for ( int i = 0; i < Q; i++ ) {
        cin >> inst[i];
        if ( inst[i] == 1 ) {
            cin >> A[i] >> B[i];
            compress.emplace_back(A[i], i);
        }
    }
    sort(begin(compress), end(compress));

    BIT < ll > tree1(compress.size());
    BIT < ll > tree2(compress.size());
    int cnt = 0; 

    for ( int i = 0; i < Q; i++ ) {
        if ( inst[i] == 1 ) {
            int pos = lower_bound(begin(compress), end(compress), Pl(A[i], i)) - begin(compress);
            tree1.add(pos, 1);
            tree2.add(pos, A[i]);
            sum += B[i], cnt++;
        } else {
            int pos = tree1.lower_bound((cnt + 1) / 2);
            ll x = compress[pos].first;
            int pos1 = lower_bound(begin(compress), end(compress), Pl(x, -LLINF)) - begin(compress);
            int pos2 = lower_bound(begin(compress), end(compress), Pl(x + 1, -LLINF)) - begin(compress);
            int num1 = tree1.query(pos1 - 1);
            int num2 = tree1.query(compress.size() - 1) - tree1.query(pos2 - 1);
            ll left = num1 * x - tree2.query(pos1 - 1);
            ll right = tree2.query(compress.size() - 1) - tree2.query(pos2 - 1) - num2 * x;

            cout << x << " " << left + right + sum << endl;
        }
    }


    return ( 0 );
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

using T = ll;
const T id = 0;
T op(T l, T r) {
	return l + r;
}

struct node;
node *update(node *t);

struct node {
	T val, all;
	node *ch[2];
	int dep, size;
	node() {}
	void init(T v) {
		val = all = v;
		dep = size = 1;
		ch[0] = ch[1] = nullptr;
	}
	void init(node* l, node* r) {
		val = id;
		ch[0] = l, ch[1] = r;
		update(this);
	}
};

const int pmax = 1e6;
node pool[pmax];
queue<int> deleted;
int it = 0;

int depth(node *t) { return t ? t->dep : 0; }
int count(node *t) { return t ? t->size : 0; }
int que(node *t) { return t ? t->all : id; }

node *new_leaf(T v) {
	if (!deleted.empty()) {
		auto pos = deleted.front(); deleted.pop();
		pool[pos].init(v);
		return pool + pos;
	}
	assert(it < pmax);
	pool[it].init(v);
	return pool + it++;
}

node *new_node(node *l, node *r) {
	if (!deleted.empty()) {
		auto pos = deleted.front(); deleted.pop();
		pool[pos].init(l, r);
		return pool + pos;
	}
	assert(it < pmax);
	pool[it].init(l, r);
	return pool + it++;
}

void delete_node(node* t) {
	deleted.push(t - pool);
}

node *update(node *t) {
	t->dep = max(depth(t->ch[0]), depth(t->ch[1])) + 1;
	t->all = op(que(t->ch[0]), op(t->val, que(t->ch[1])));
	t->size = count(t->ch[0]) + count(t->ch[1]) + (!t->ch[0]);
	return t;
}

node *rotate(node *t, int b) {
	node *s = t->ch[1 - b];
	t->ch[1 - b] = s->ch[b];
	s->ch[b] = t;
	t = update(t);
	s = update(s);
	return s;
}

node *fix(node *t) {
	if (!t) return t;
	int dd = depth(t->ch[0]) - depth(t->ch[1]);
	if (abs(dd) < 2) return t;
	int b = dd < 0;
	if (depth(t->ch[b]->ch[!b]) > depth(t->ch[b]->ch[b])) {
		t->ch[b] = rotate(t->ch[b], b);
	}
	return rotate(t, !b);
}

node *merge(node *l, node *r) {
	if (!l) return r;
	if (!r) return l;
	if (l->dep == r->dep) return new_node(l, r);
	if (l->dep < r->dep) {
		r->ch[0] = merge(l, r->ch[0]);
		return fix(update(r));
	}
	l->ch[1] = merge(l->ch[1], r);
	return fix(update(l));
}

pair<node*, node*> split(node *t, int k) {
	if (!t) return make_pair(nullptr, nullptr);
	if (k == 0) return make_pair(nullptr, t);
	if (k >= count(t)) return make_pair(t, nullptr);
	int c = count(t->ch[0]);
	node *l = t->ch[0], *r = t->ch[1];
	delete_node(t);
	if (k == c) return make_pair(l, r);
	if (k < c) {
		pair<node*, node*> p = split(l, k);
		return make_pair(p.first, merge(p.second, r));
	}
	pair<node*, node*> p = split(r, k - c);
	return make_pair(merge(l, p.first), p.second);
}

node *insert(node *t, int k, T v) {
	pair<node*, node*> s = split(t, k);
	return merge(merge(s.first, new_leaf(v)), s.second);
}

node *erase(node *t, int k) {
	pair<node*, node*> s1 = split(t, k), s2 = split(s1.second, 1);
	return merge(s1.first, s2.second);
}

node *find(node *t, int k) {
	if (!t) return t;
	int c = count(t->ch[0]), b = (!t->ch[0]);
	return c == 0 && b ? t : k < c ? find(t->ch[0], k) : find(t->ch[1], k - c - b);
}

T find(node *t, int l, int r) {
	if (!t) return id;
	if (r < 0 || l >= count(t)) return id;
	if (l <= 0 && r >= t->size) return t->all;
	int c = count(t->ch[0]), d = c + (!t->ch[0]);
	return op(!t->ch[0] ? id : find(t->ch[0], l, r), op(l <= c && c < r ? t->val : id, !t->ch[1] ? id : find(t->ch[1], l - d, r - d)));
}

void update(node *t, int k, T val) {
	if (!t) return;
	int c = count(t->ch[0]), b = (!t->ch[0]);
	if (c == 0 && b) {
		t->val = val;
	}
	else if (k < c) {
		update(t->ch[0], k, val);
	}
	else {
		update(t->ch[1], k - c - b, val);
	}
	update(t);
}

node* build(const vector<T>& a, int lb, int ub) {
	if (ub - lb == 1) return new_leaf(a[lb]);
	int m = (lb + ub) >> 1;
	return merge(build(a, lb, m), build(a, m, ub));
}

int count_lower(node *t, T v) {
	if (t == nullptr) return 0;
	if (t->val < v) return count(t->ch[0]) + 1 + count_lower(t->ch[1], v);
	if (t->val == v) return count(t->ch[0]);
	return count_lower(t->ch[0], v);
}

