                x = t1;
                now += t2;
                continue;
            }
            now += t2;
            if(sz1 < sz2) pq1.push(t1), sz1++, sum1 += t1;
            else pq2.push(t1), sz2++, sum2 += t1;
            if(!pq1.empty() && pq1.top() > x)
            {
                ll t3 = pq1.top();
                pq1.pop();
                sum1 += x - t3;
                pq1.push(x);
                x = t3;
            }
            if(!pq2.empty() && x > pq2.top())
            {
                ll t3 = pq2.top();
                pq2.pop();
                sum2 += x - t3;
                pq2.push(x);
                x = t3;
            }
            if(!pq1.empty() && pq1.top() > x)
            {
                ll t3 = pq1.top();
                pq1.pop();
                sum1 += x - t3;
                pq1.push(x);
                x = t3;
            }
        }
    }
    return 0;
}

