      va.pb(a);
      //sum_b += b;
      vb.pb(b);
    }else{
      continue; 
    }
  }

  //main
  int V = va.size();//Qが上界。
  ll center = 0;

  //まず座標圧縮
  CC cc(va);
  /*for(int i=0; i<V; i++){
    va[i] = cc.mp[va[i]];//圧縮した座標を代入。
  }*/

  //aの個数を管理。
  BinaryIndexedTree bit(V);
  int c = 0;

  for(int i=0; i<Q; i++){
    if(vt[i]==1){
      bit.add(cc.mp[va[c]],1); 
      sum_b += vb[c];

      if(c == 0){
        center = va[c];
      }else if((c+1)%2){//aが偶数から奇数になる。
        if(va[c]<=center){//左側
          //center = center;
          sum_a += abs(va[c]-center);
        }else{//右側
          //最小値を求める時
          ll ok = V+1;//解が存在する最大値
          ll ng = -1;//解が存在しない最小値
          /*
          //最大値を求める時
          ll ok = -1;//解が存在する最小値
          ll ng = 1e18;//解が存在しない最大値
          */

          while(abs(ok-ng) > 1){
            ll mid = (ok+ng)/2;
            if(bit.sum(mid) >= c/2+1){//((C+1)+1)/2
              ok = mid; 
            }else{
              ng = mid;
            }
          }

          center = cc.getKey(ok);
          sum_a += abs(va[c]-center);
        }
      }else{//aが奇数から偶数になる。
        if(va[c]>=center){//右側
          //center = center;
          sum_a += abs(va[c]-center);
        }else{//左側
          //最小値を求める時
