          /*
          //最大値を求める時
          ll ok = -1;//解が存在する最小値
          ll ng = 1e18;//解が存在しない最大値
          */

          while(abs(ok-ng) > 1){
            ll mid = (ok+ng)/2;
            if(bit.sum(mid) >= (c+1)/2){
              ok = mid; 
            }else{
              ng = mid;
            }
          }

          ll g = abs(center-cc.getKey(ok));
          center = cc.getKey(ok);
          sum_a += (abs(va[c]-center) + g);
        }
      }
      //cout << va[c] << " " << c << endl;
      c ++;
    }else{//クエリ2
      printf("%d %lld\n", center, sum_a+sum_b);
    }
  }

  // output
  return 0;
}

