set<t3> lefts;
set<t3> rights;
ll left_sum = 0LL;
ll right_sum = 0LL;
ll bsum = 0LL;

void f(ll a, int i)
{
        if (lefts.empty()) {
                lefts.insert(t3(-a, a, i));
        }

        else if (rights.empty()) {
                t3 b_t3 = *(lefts.begin());
                ll b = get<1>(b_t3);
                lefts.erase(lefts.begin());

                ll minval = min(a, b);
                ll maxval = max(a, b);
                lefts.insert(t3(-minval, minval, i));
                rights.insert(t3(maxval, maxval, i));
                right_sum = maxval - minval;
        }

        else if (lefts.size() == rights.size()) {
                t3 old_med_t3 = *(lefts.begin());
                ll old_med = get<1>(old_med_t3);
                t3 right_top_t3 = *(rights.begin());
                ll right_top = get<1>(right_top_t3);

                if (a < old_med) {
                        lefts.insert(t3(-a, a, i));
                        left_sum += (old_med - a);
                }
                if (old_med <= a && a <= right_top) {
                        lefts.insert(t3(-a, a, i));
                        left_sum += (lefts.size() - 1LL) * (a - old_med);
                        right_sum -= rights.size() * (a - old_med);
                }
                if (right_top < a) {
                        rights.erase(rights.begin());
                        rights.insert(t3(a, a, i));
                        lefts.insert(t3(-right_top, right_top, i));
                        left_sum += (lefts.size() - 1LL) * (right_top - old_med);
                        right_sum -= rights.size() * (right_top - old_med);
                        right_sum += (a - right_top);
                }
        }

        else {
                t3 old_med_t3 = *(lefts.begin());
                ll old_med = get<1>(old_med_t3);

                if (a <= old_med) {
                        lefts.erase(lefts.begin());
                        lefts.insert(t3(-a, a, i));
                        rights.insert(t3(old_med, old_med, i));
                        t3 new_med_t3 = *(lefts.begin());
                        ll new_med = get<1>(new_med_t3);
                        left_sum -= (lefts.size() - 1LL) * (old_med - new_med);
                        left_sum += (new_med - a);
                        right_sum += rights.size() * (old_med - new_med);
                }
                else {
                        rights.insert(t3(a, a, i));
                        right_sum += (a - old_med);
                }

        }
}

