class floating_median {
  public:
    priority_queue<ll> former;
    priority_queue<ll, vector<ll>, greater<ll>> latter;
    void push_former(ll num) {
        former.push(num);
        sum_former += num;
    }
    void push_latter(ll num) {
        latter.push(num);
        sum_latter += num;
    }

    ll sum_former = 0, sum_latter = 0;
    void push(ll num) {
        if (former.size() > latter.size()) {
            ll t = former.top();
            if (num >= t) {
                push_latter(num);
            } else {
                former.pop();
                sum_former -= t;
                push_former(num);
                push_latter(t);
            }
        } else {
            if (former.empty()) {
                push_former(num);
            } else {
                ll t = latter.top();
                if (num <= t) {
                    push_former(num);
                } else {
                    ll t = latter.top();
                    if (num <= t) {
                        push_former(num);
                    } else {
                        latter.pop();
                        sum_latter -= t;
                        push_latter(num);
                        push_former(t);
                    }
                }
            }
        }
    }
    ll get() { return former.top(); };
};

