typedef long long ll;

class Bit {
  int n_;
  map<int, ll> m_;
public:
  explicit Bit(int n) : n_(n) {}
  void insert(int a, int w) {
    for (ll x = a; x <= n_; x += x & -x) {
      m_[x] += w;
    }
  }
  ll sum(int a) {
    ll ret = 0;
    for (ll x = a; x > 0; x -= x & -x) {
      auto it = m_.find(x);
      if (it != m_.end()) ret += it->second;
    }
    return ret;
  }
};

int main() {
  int Q;
  scanf("%d", &Q);
  int B = 1000000000;
  Bit f(B*2+1);
  Bit v(B*2+1);
