      n++;
      t += b;
      //printf("a=%d b=%d\n", a, b);
      f.insert(B+1+a, 1);
      v.insert(B+1+a, a);
    } else {
      int l = 0;
      int r = 2*B+1;
      for (int j = 0; j < 32; j++) {
        int mid = ((ll)l + r) / 2;
