void solve() {
  int Q; cin >> Q;
  pqdesc<int> mins;
  pqasc<int> maxs;
  i64 bsum = 0;
  i64 ans = 0;
  rep(_, Q) {
    int __; cin >> __;
    if (__ == 1) {
      int a, b; cin >> a >> b;
      bsum += b;
      if (_ == 0) {
        mins.push(a), maxs.push(a);
        continue;
      }
      int mi = mins.top(), ma = maxs.top();
      if (a < mi) {
        mins.pop();
        mins.push(a), maxs.push(mi);
        ans += mi - a;
      } else if (a > ma) {
        maxs.pop();
        maxs.push(a), mins.push(ma);
        ans += a - ma;
      } else {
        maxs.push(a), mins.push(a);
      }
    } else {
      cout << mins.top() << " " << ans + bsum << '\n';
    }
  }
}

