template<typename T> struct BinaryIndexedTree {
private : 
    vector<T> data;
public :
    BinaryIndexedTree () { }

    BinaryIndexedTree (int n) { data.assign(n+1, 0); }

    T get(int i) {
        T ret = 0;
        for (; i > 0; i -= i&-i) ret += data[i];
        return ret;
    }

    void add (int i, const T &x) {
        for (++i; i < (int)data.size(); i += i&-i) data[i] += x;
    }

};

