void solve() {
  int Q;
  cin >> Q;
  multiset<int> as;
  auto med = as.begin();
  int sum = 0, cnt = 0;
  rep(_, Q) {
    int q;
    cin >> q;
    if(q == 1) {
      cnt++;
      int a, b;
      cin >> a >> b;
      as.insert(a);
      if(med != as.end()) {
        sum += abs(a - *med);
        bool is_l = a < *med;
        if(is_l && cnt % 2 == 0) {
          med--;
        } else if(!is_l && cnt % 2) {
          int tmp = *med;
          med++;
          sum -= *med - tmp;
        }
      } else {
        med--;
      }
      sum += b;
    } else {
      COUT(*med, sum);
    }
  }
}


