priority_queue<long> q1, q2;

long c() {
    if(!q1.size() && !q2.size()) return 0;
    if(!q2.size()) return q1.top();
    if(!q1.size()) return -q2.top();
    long a = q1.top(), b = -q2.top();
    long m = q1.size(), n = q2.size();

    if (n % 2) return b;
    return a;
}

int main(void) {
    long bsum = 0;
    long q1s = 0, q2s = 0;

    long q;
    cin >> q;
    for(int i=0; i<q; i++) {
        int type;
        cin >> type;
        if(type == 1) {
            long a, b;
            cin >> a >> b;
            bsum += b;

            long m = c();
            if(m < a) {
                q2.push(-a);
                q2s += a;
            } else {
                q1.push(a);
                q1s += a;
            }

            if (q1.size() > q2.size()) {
                q1s -= q1.top();
                q2s += q1.top();
                q2.push(-q1.top()), q1.pop();
            }
            if (q1.size() < q2.size()) {
                q2s -= -q2.top();
                q1s += -q2.top();
                q1.push(-q2.top()), q2.pop();
            }
            if (q1.size() < q2.size()) {
                q2s -= -q2.top();
                q1s += -q2.top();
                q1.push(-q2.top()), q2.pop();
            }

            if (q1.size() % 2) {
                q1s -= q1.top();
                q2s += q1.top();
                q2.push(-q1.top()), q1.pop();
            }
            /* cout << '!' << q1.top() << ',' << q1.size() << ' ' << q2.top() << ',' << q2.size() << endl; */
        } else if (type == 2) {
            long m = c();
            cout << m << ' ' << (m * (signed long)(q1.size() - q2.size()) + q1s + q2s + bsum) << endl;
        }
    }
}

