  cin.tie(nullptr);
  int Q;
  cin >> Q;
  set<int> ext;
  map<int,int> num;
  ll sum = 0;
  int now_num = -1;
  int now_cnt = 1;
  int cnt = 0;
  while(Q--){
    int id;
    cin >> id;
    if(id == 1){
      int a,b;
      cin >> a >> b;
      sum += b;
      ext.emplace(a);
      num[a]++;
      if(now_num == -1){
        now_num = a;
        now_cnt = 1;
        ext.emplace(a);
      }else{
        sum += abs(now_num-a);
        if(a < now_num){
          // 左が増える
          if(cnt%2){
            // 奇数で左増えるので移動
            if(now_cnt == 1){
              auto pos = ext.lower_bound(now_num);
              pos--;
              now_num = *pos;
              now_cnt = num[now_num];
            }else{
              now_cnt--;
            }
          }else{
            // 偶数で左増えるので不動
          }
        }else{
          // 右が増える
          if(cnt%2){
            // 奇数で右増えるので不動
          }else{
            // 偶数で右増えるので移動
            if(num[now_num] == now_cnt){
              auto pos = ext.lower_bound(now_num);
              pos++;
              now_num = *pos;
              now_cnt = 1;
            }else{
              now_cnt++;
            }
          }
        }
      }
      cnt++;
    }else{
      cout << now_num << " " << sum << "\n";
    }
  }
  return 0;
}

