template<class T>
struct Median{
    priority_queue<T> q1;
    priority_queue<T,vector<T>,greater<T>> q2;
    T dist;
    Median():dist(){}
    void insert(T x){
        if(!q1.size()){
            q1.push(x);
        }else if(q1.size()==q2.size()){
            if(x>q2.top()){
                q1.push(q2.top());
                q2.pop();
                q2.push(x);
            }else{
                q1.push(x);
            }
        }else{
            int p=q1.top();
            if(x>q1.top()){
                q2.push(x);
            }else{
                q2.push(q1.top());
                q1.pop();
                q1.push(x);
            }
            dist+=abs(p-q1.top());
        }
        dist+=abs(x-q1.top());
    }
    T median(){
        return q1.top();
    }
    T distance(){
        return dist;
    }
    void debug(){
        auto t1=q1;
        vector<T> l,r;
        while(t1.size()){l.push_back(t1.top());t1.pop();}
        auto t2=q2;
        while(t2.size()){r.push_back(t2.top());t2.pop();}
        cerr<<l<<","<<r<<endl;
    }
};
