int main()
{
    set <pll> st;

    ll C = 0;               /// constant sum
    ll Cnt1 = 0, Sum1 = 0;  /// less or equal
    ll Cnt2 = 0, Sum2 = 0;  /// greater

    ll q;  cin >> q;

    pll x;

    ll T, a, b;    scanf("%lld%lld%lld", &T, &a, &b);

    st.insert(pll(a, 0));
    x = pll(a, 0);
    Cnt1++;
    C += (ll) b;
    Sum1 += (ll) a;

    for(ll i = 1; i < q; i++)
    {
        scanf("%lld", &T);

        if(T == 1)
        {
            scanf("%lld%lld", &a, &b);

            pll p = pll(a, i);

            st.insert(p);

            if(p > x)   Cnt2++, Sum2 += (ll) a;
            else        Cnt1++, Sum1 += (ll) a;

            set <pll> :: iterator it = st.lower_bound(x);

            while(Cnt2 > Cnt1)
            {
                Cnt1++;
                Cnt2--;
                Sum1 += (*it).first;
                Sum2 -= (*it).first;
                it++;
            }

            while(Cnt1 > Cnt2)
            {
                Cnt1--;
                Cnt2++;
                Sum1 -= (*it).first;
                Sum2 += (*it).first;
                it--;
            }

            x = *it;

            C += (ll) b;
        }

        else
        {
            ll Ans = x.first * Cnt1 - Sum1 - x.first * Cnt2 + Sum2;

            printf("%lld %lld\n", x.first, Ans + C);
