    void init(int m){
        n=m; rep(i,0,n)val[i]=0;
    }
    void add(int i,ll x){
        i++;
        while(i<=n){
            val[i]+=x; i+=(i&-i);
        }
    }
    ll sum(int i){
        i++; ll res=0;
        while(i){
            res+=val[i]; i-=(i&-i);
        }return res;
    }
    int search(){
        ll flag=(sum(n)+1)/2-1;
        int l=0,r=n;
        while(r-l>1){
            int m=(l+r)/2;
            if(sum(m)>flag)r=m; else l=m;
        } return l;
