struct Segmenttree{
    int n;
    vector<long long> node;

    Segmenttree(vector<long long> v){
        n = (int)(v.size());
        node.resize(2*n);
        for(int i=0;i<n;i++) node[i+n] = v[i];
        for(int i=n-1;i>=0;i--) node[i] = node[i<<1] + node[i<<1|1];
    }
    //i番目の要素にxを足す
    void update(int i,long long x){
        i += n;
        node[i] += x;
        while(i>1){
            i >>= 1;
            node[i] = node[i<<1] + node[i<<1|1];
        }
    }
    //[l,r)の要素の和を求める
    long long query(int l,int r){
        if(r>n) r=n;
        if(l>n) return 0;
        if(l>=r) return 0;
        long long res = 0;
        l += n; r += n;
        while(l<r){
            if(l&1) res += node[l++];
            if(r&1) res += node[--r];
            l >>= 1; r >>= 1;
        }
        return res;
    }
    //i番目の要素にアクセス
    long long getval(int i){
        return node[i+n];
    }
};

