          */

          while(abs(ok-ng) > 1){
            ll mid = (ok+ng)/2;
            if(bit.sum(mid) >= count/2+1){//((C+1)+1)/2
              ok = mid; 
            }else{
              ng = mid;
            }
          }

          center = cc.getKey(ok);
