struct node
{
    int l,r;
    int v=0;
    int prsu=0;
    node* le,*ri;
    node(int a,int b)
    {
        l=a;
        r=b;
        le=NULL;
        ri=NULL;
    }
};
void up(node* seg,int in,int val)
{
    seg->v+=val;
    seg->prsu+=in;
    if(seg->l==seg->r)
    {
        return;
    }
    else
    {
        int m=(seg->l+seg->r)>>1;
        if(in<=m)
        {
            if(seg->le==NULL)
                seg->le=new node(seg->l,m);
            up(seg->le,in,val);
        }
        else{
            if(seg->ri==NULL)
                seg->ri=new node(m+1,seg->r);
            up(seg->ri,in,val); 
        }
    }
}
pair<int,int> query(node* seg,int v)
{
    if(seg==NULL||v==0)
        return {0,0};
    if(seg->l==seg->r)
    {
        return {seg->l,(seg->prsu*v)/seg->v};
    }
    if(seg->le!=NULL&&seg->le->v>=v)
    	return query(seg->le,v);
    pair<int,int> p={0,0};
    if(seg->le!=NULL)
    {
    	p={seg->le->v,seg->le->prsu};
    }
    pair<int,int> p2=query(seg->ri,v-p.F);
    return {p2.F,p2.S+p.S};
}

