    if (mid <  pos) upd(RS,pos,t);
    tree[rt] = tree[lson] + tree[rson];
    add[rt] = add[lson] + add[rson];
}
void query(int rt,int l,int r,int rest, int &pos){
    if (l == r){
        pos = l;
        return;
    }
    int mid = (l + r) >>1;
    if (tree[lson] >= rest) query(LS, rest, pos);
    else{
        rest -= tree[lson];
        query(RS, rest, pos);
    }
}
LL qs(int rt,int l,int r,int L,int R, int &q){
    if (L <= l && r <= R){
        q = tree[rt];
        return add[rt];
    }
    int mid = (l + r) >> 1;
    LL ans = 0 ; int qq = 0;
    if (L <= mid) ans += qs(LS, L, R, q), qq += q;
    if (mid < R)  ans += qs(RS, L, R, q), qq += q;
    q = qq;
    return ans;
}
