                sumH += A;
            } else {
                int mid = low.top();
                if (A <= mid) {
                    low.pop();
                    low.push(A);
                    high.push(mid);
                    sumL += A - mid;
                    sumH += mid;

                } else {
                    high.push(A);
                    int tmp = high.top();
                    high.pop();
                    low.push(tmp);
                    sumH += A - tmp;
                    sumL += tmp;
                }
            }
        } else {
            int mid = low.top();
            dump(mid, k, sumL, sumH);
            int f = mid * low.size() - sumL + sumH - mid * high.size() + k;
            cout << mid << " " << f << endl;
        }
    }
}

