				mn += abs(a - small.top());
			} else {
				unless (small.top() <= a and a <= big.top()) {
					if (abs(a - small.top()) <= abs(a - big.top())) {
						mn += abs(a - small.top());
					} else {
						mn += abs(a - big.top());
					}
				}
			}

			if (small.top() >= a) {
				small.push(a);
			} else {
				big.push(a);
			}

			if (small.size() >= big.size() + 2) {
				big.push(small.top()); small.pop();
			}

			while (big.size() >= small.size() + 1) {
				small.push(big.top()); big.pop();
			}

			x = small.top();
		} else {
			printf("%lld %lld\n", x, mn + S);
		}
	}
}

