	if (a.first != b.first) {
		return a.first > b.first;
	}
	else {
		return a.second > b.second;
	}
}

//約数
void divisor(ll n, vector<ll>& ret) {
	for (ll i = 1; i * i <= n; i++) {
		if (n % i == 0) {
			ret.push_back(i);
			if (i * i != n) ret.push_back(n / i);
		}
	}
	sort(ret.begin(), ret.end());
}

//最大公約数
ll gcd(ll m, ll n) {
	if (n == 0)return m;
	return gcd(n, m % n);
}//gcd

//最小公倍数
ll lcm(ll m, ll n) {
	return m / gcd(m, n) * n;
}

//繰り返し自乗法
ll pow2(ll x, ll n) { //x^n 計算量O(logn)
	ll ans = 1ll;
	while (n > 0) {
		if ((n & 1) == 1) {
			ans = ans * x%MOD;
		}
		x = x * x%MOD; //一周する度にx, x^2, x^4, x^8となる
		n >>= 1; //桁をずらす n = n >> 1
	}
	return ans;
}

class MedSet{
public:
	multiset<ll> left, right;
	ll med;//中央値
	MedSet() {}
	MedSet(ll _med)  {

	}
	void insert(ll a) {
		if (left.size() == 0) {
			med = a;
			left.insert(med);
		}
		else {
			if (a < med) {
				left.insert(a);
				if (left.size() > right.size() + 1) {
					//left->right
					right.insert(*(--left.end()));
					left.erase(--left.end());
				}
				med = *(--left.end());
			}
			else {
				right.insert(a);
				if (right.size() > left.size()) {
					//right->left
					left.insert(*(right.begin()));
					right.erase(right.begin());
				}
				med = *(--left.end());
			}
		}
	}
};

