struct LazySegmentTree{
    int n;
    vec node,lazy;

    LazySegmentTree(int N){
        n=1;
        while(n<N)n*=2;
        node.resize(2*n-1,0);
        lazy.resize(2*n-1,0);
    }

    //k番目のノードについて遅延評価
    void eval(int k,int l,int r){
        if(lazy[k]!=0){
            node[k]+=lazy[k];

            if(r-l>1){
                lazy[2*k+1]+=lazy[k]/2;
                lazy[2*k+2]+=lazy[k]/2;
            }
            lazy[k]=0;
        }
    }

    //[a,b)にxを加算、kは区間[l,r)の節点
    void add(int a,int b,ll x,int k,int l,int r){
        eval(k,l,r);

        if(b<=l || r<=a)return;

        if(a<=l && r<=b){
            lazy[k]+=x*(ll)(r-l);
            eval(k,l,r);
        }

        else{
            add(a,b,x,2*k+1,l,(l+r)/2);
            add(a,b,x,2*k+2,(l+r)/2,r);
            node[k]=node[2*k+1]+node[2*k+2];
        }
    }

    //[a,b)の区間和を取得
    ll getsum(int a,int b,int k,int l,int r){
        if(b<=l || r<=a) return 0;

        eval(k,l,r);
        if(a<=l && r<=b) return node[k];
        ll vl=getsum(a,b,2*k+1,l,(l+r)/2);
        ll vr=getsum(a,b,2*k+2,(l+r)/2,r);
        return vl+vr;
    }   
};

LazySegmentTree LST2(200000);
int BS(int x,int l,int r){
    if(r-l==1) return l;
    int m=(l+r)/2;
    if(LST2.getsum(0,m,0,0,LST2.n)<x) return BS(x,m,r);
    else                              return BS(x,l,m);
}

int main(){
    int Q;cin>>Q;
    vec Query,B;
    vector<P> A;
    int k=0;
    for(int q=0;q<Q;q++){
