        if(s==1){
            ll a,b;cin>>a>>b;
            A.push_back((P){a,k});
            B.push_back(b);
            k++;
        }
    }
    sort(A.begin(),A.end());
    vector<P> X(k);
    for(int j=0;j<k;j++){
        X[A[j].second]=(P){A[j].first,j};
    }
    LazySegmentTree LST1(k);
    int count=0;ll rev=0;
    for(int q=0;q<Q;q++){
        if(Query[q]==1){
            rev+=B[count];
            LST1.add(X[count].second,X[count].second+1,X[count].first,0,0,LST1.n);
            LST2.add(X[count].second,X[count].second+1,1,0,0,LST2.n);
            count++;
        }
        else{
            int index=BS((count+1)/2,0,k);
            ll x=A[index].first,g=rev+LST1.getsum(index+1,k,0,0,LST1.n)-LST1.getsum(0,index+1,0,0,LST1.n);
            if(count%2==1) g+=x;
