					mn += abs(a - small.top());
				} else {
					if (sz % 2) {
						unless (small.top() <= a and a <= big.top()) {
							mn += min(abs(a - small.top()), abs(a - big.top()));
						}
					} else {
						mn += abs(a - small.top());
					}
				}

				if (small.top() >= a) {
					small.push(a);
				} else {
					big.push(a);
				}

				if (small.size() >= big.size() + 2) {
					big.push(small.top()); small.pop();
				}

				while (big.size() >= small.size() + 1) {
					small.push(big.top()); big.pop();
				}

				if (big.size() > small.size()) return 1;

				x = small.top();
			}
		} else {
			printf("%lld %lld\n", x, mn + S);
		}
	}
}

