template< typename T >
struct BinaryIndexedTree {
  vector< T > data;
  int n;

  BinaryIndexedTree(int sz) {
    n=sz;
    data.assign(++sz, 0);
  }

  T sum(int k) {
    T ret = 0;
    for(++k; k > 0; k -= k & -k) ret += data[k];
    return (ret);
  }

  void add(int k, T x) {
    for(++k; k < data.size(); k += k & -k) data[k] += x;
  }

  T sum_between(int i, int j){
      if(i>j)return 0;
      return sum(j)-sum(i-1);
  }

  // a[0]+...+a[ret+1] >= x
    int lower_bound(T x){
        int ret = -1;
        int k = 1;
        while(2*k <= n) k <<= 1;
        for( ;k>0; k>>=1){
            if(ret+k < n && data[ret+k] < x){
                x -= data[ret+k];
                ret += k;
            }
        }
        return ret + 1;
    }
};

