using namespace std;

template<typename T>
struct BIT {
    int n;
    vector<T> dat;

    BIT(int n=0){
        initialize(n);
    }

    void initialize(int nin){
        n = nin;
        dat.resize(n, 0);
    }

    T sum(int i){
        T s = 0;
        while(i >= 0){
            s += dat[i];
            i = (i & (i+1)) - 1;
        }
        return s;
    }

    T sum_between(int i, int j){
        return sum(j) - sum(i-1);
    }

    void plus(int i, T x){
        while(i < n){
            dat[i] += x;
            i |= i+1;
        }
    }

    // a[0]+...+a[ret] >= x
    int lower_bound(T x){
        int ret = -1;
        int k = 1;
        while(2*k <= n) k <<= 1;
        for( ;k>0; k>>=1){
            if(ret+k < n && dat[ret+k] < x){
                x -= dat[ret+k];
                ret += k;
            }
        }
        return ret + 1;
    }
};

int main(){
    int Q;
    cin >> Q;
    vector<int> T(Q), A(Q), B(Q);
    map<int, int> mp;
    for(int i=0; i<Q; i++){
        cin >> T[i];
        if(T[i] == 1){
            cin >> A[i] >> B[i];
            mp[A[i]] = 0;
        }
    }
    vector<int> cmp;
    int sz = 0;
    for(auto p : mp){
        mp[p.first] = sz++;
        cmp.push_back(p.first);
    }

    BIT<int64_t> bit_num(sz), bit_sum(sz);
    int64_t Bsum = 0;
    int s = 0;
    for(int i=0; i<Q; i++){
        if(T[i] == 1){
            int a = A[i], b = B[i];
            s++;
            Bsum += b;
            bit_num.plus(mp[a], 1);
            bit_sum.plus(mp[a], a);
        }else{
            int mi = bit_num.lower_bound((s+1)/2);
            int s1 = bit_num.sum_between(0, mi);
            int64_t med = cmp[mi];
            int64_t ans = s1 * med - bit_sum.sum_between(0, mi) + bit_sum.sum_between(mi+1, sz-1) - (s-s1) * med + Bsum;
            cout << med << " " << ans << endl;
        }
    }
    return 0;
}

