            // cout << a << " " << b << "\n";
            sum_b += b;

            smaller_half.emplace(a);
            sum_smaller_half += a;
            lint poped_item = smaller_half.top();
            larger_half.emplace(poped_item);
            sum_smaller_half -= poped_item;
            sum_larger_half += poped_item;
            smaller_half.pop();
            if (larger_half.size() > smaller_half.size()) {
                lint poped_item = larger_half.top();
                smaller_half.emplace(poped_item);
                sum_larger_half -= poped_item;
                sum_smaller_half += poped_item;
