long long sm1 = 0, sm2 = 0;
multiset<int> s1, s2;

int add(int x) {
    if (x > (*s1.rbegin())) {
        s2.insert(x);
        ++sm2;
    } else {
        s1.insert(x);
        sm1 += x;
    }
    while (s2.size() > s1.size()) {
        x = *s2.begin();
        s1.insert(*s2.begin());
        s2.erase(s2.begin());
        sm1 += x;
        sm2 -= x;
    }
    while (int(s1.size() - s2.size()) > 1) {
        x = *s1.rbegin();
        s2.insert(*s1.rbegin());
        s1.erase(--s1.end());
        sm1 -= x;
        sm2 += x;
    }
    return *s1.rbegin();
}


