                    pq_greater.push(tmp);
                    sum_greater += tmp;
                    pq_less.pop();
                    sum_less += a - tmp;
                    pq_less.push(a);

                }
            }else{
                ll p1 = pq_less.top();
                ll p2 = pq_greater.top();
                if(a <= p1){
                    if(pq_less.size() <= pq_greater.size()){
                        pq_less.push(a);
                        sum_less += a;
                    }else{
                        pq_less.pop();
                        pq_greater.push(p1);
                        pq_less.push(a);
                        sum_less += a - p1;
                        sum_greater += p1;
                    }
                }else{
                    if(pq_greater.size() <= pq_less.size()){
                        pq_greater.push(a);
                        sum_greater += a;
                    }else{
                        pq_greater.pop();
                        pq_less.push(p2);
                        pq_greater.push(a);
                        sum_greater += a - p2;
                        sum_less += p2;
                    }
                }
            }
        }else{
            ll ans = res;
            ll mid = pq_less.top();
            ans += mid * pq_less.size() - sum_less;
            ans += sum_greater - mid * pq_greater.size();
            print(mid, ans);

        }
    }

}

