//// Utility functions 

// exchange a and b 
inline
void Exch(int &a, int &b) 
{ 
    int aux = a; 
    a = b; 
    b = aux; 
} 

// Greater and Smaller are used as comparators 
bool Greater(int a, int b) 
{ 
    return a > b; 
} 

bool Smaller(int a, int b) 
{ 
    return a < b; 
} 

int Average(int a, int b) 
{ 
    return (a + b) / 2; 
} 

// Signum function 
// = 0  if a == b  - heaps are balanced 
// = -1 if a < b   - left contains less elements than right 
// = 1  if a > b   - left contains more elements than right 
int Signum(int a, int b) 
{ 
    if( a == b ) 
        return 0; 

    return a < b ? -1 : 1; 
} 

// Heap implementation 
// The functionality is embedded into 
// Heap abstract class to avoid code duplication 
class Heap 
{ 
public: 
    // Initializes heap array and comparator required 
    // in heapification 
    Heap(int *b, bool (*c)(int, int)) : A(b), comp(c) 
    { 
        heapSize = -1; 
    } 

    // Frees up dynamic memory 
    virtual ~Heap() 
    { 
        if( A ) 
        { 
            delete[] A; 
        } 
    } 

    // We need only these four interfaces of Heap ADT 
    virtual bool Insert(int e) = 0; 
    virtual int  GetTop() = 0; 
    virtual int  ExtractTop() = 0; 
    virtual int  GetCount() = 0; 

protected: 

    // We are also using location 0 of array 
    int left(int i) 
    { 
        return 2 * i + 1; 
    } 

    int right(int i) 
    { 
        return 2 * (i + 1); 
    } 

    int parent(int i) 
    { 
        if( i <= 0 ) 
        { 
            return -1; 
        } 

        return (i - 1)/2; 
    } 

    // Heap array 
    int   *A; 
    // Comparator 
    bool  (*comp)(int, int); 
    // Heap size 
    int   heapSize; 

    // Returns top element of heap data structure 
    int top(void) 
    { 
        int max = -inf; 

        if( heapSize >= 0 ) 
        { 
            max = A[0]; 
        } 

        return max; 
    } 

    // Returns number of elements in heap 
    int count() 
    { 
        return heapSize + 1; 
    } 

    // Heapification 
    // Note that, for the current median tracing problem 
    // we need to heapify only towards root, always 
    void heapify(int i) 
    { 
        int p = parent(i); 

        // comp - differentiate MaxHeap and MinHeap 
        // percolates up 
        if( p >= 0 && comp(A[i], A[p]) ) 
        { 
            Exch(A[i], A[p]); 
            heapify(p); 
        } 
    } 

    // Deletes root of heap 
    int deleteTop() 
    { 
        int del = -inf; 

        if( heapSize > -1) 
        { 
            del = A[0]; 

            Exch(A[0], A[heapSize]); 
            heapSize--; 
            heapify(parent(heapSize+1)); 
        } 

        return del; 
    } 

    // Helper to insert key into Heap 
    bool insertHelper(int key) 
    { 
        bool ret = false; 

        if( heapSize < MAX_HEAP_SIZE ) 
        { 
            ret = true; 
            heapSize++; 
            A[heapSize] = key; 
            heapify(heapSize); 
        } 

        return ret; 
    } 
}; 

// Specilization of Heap to define MaxHeap 
class MaxHeap : public Heap 
{ 
private: 

public: 
    MaxHeap() : Heap(new int[MAX_HEAP_SIZE], &Greater)  {  } 

    ~MaxHeap()  { } 

    // Wrapper to return root of Max Heap 
    int GetTop() 
    { 
        return top(); 
    } 

    // Wrapper to delete and return root of Max Heap 
    int ExtractTop() 
    { 
        return deleteTop(); 
    } 

    // Wrapper to return # elements of Max Heap 
    int  GetCount() 
    { 
        return count(); 
    } 

    // Wrapper to insert into Max Heap 
    bool Insert(int key) 
    { 
        return insertHelper(key); 
    } 
}; 

