    priority_queue<int,vector<int>,greater<int>> q2;
    q1.push(-INF);
    q2.push(INF);
    ll sum = 0;
    ll q1_sum = 0;
    ll q2_sum = 0;
    while(q--) {
        int t; cin >> t;
        if(t == 1) {
            int a,b; cin >> a >> b;
            sum += b;
            int n = q1.size();
            int m = q2.size();
            int u = q1.top();
            int v = q2.top();
            if(n == m){
                if(a < u){
                    q1_sum += a;
                    q1.push(a);
                }else{
                    q2_sum += a;
                    q2.push(a);
                }
            }
            else if(n < m){
                if(a < v){
                    q1_sum += a;
                    q1.push(a);
                }else{
                    q2.pop();
                    q1.push(v);
                    q2.push(a);
                    q1_sum += v;
                    q2_sum += a-v;
                }
            }
            else{
                if(a > u){
                    q2.push(a);
                    q2_sum += a;
                }else{
                    q1.pop();
                    q2.push(u);
                    q1.push(a);
                    q1_sum += a-u;
                    q2_sum += u;
                }
            }
        }else{
            int n = q1.size();
            int m = q2.size();
            int x = 0;
            ll ans = 0;
            if(n >= m){
                x = q1.top();
                ans = (ll)x*(n-1)-q1_sum+q2_sum-(ll)x*(m-1)+sum;
            }else{
                x = q2.top();
                ans = (ll)x*(n-1)-q1_sum+q2_sum-(ll)x*(m-1)+sum;
            }
            cout << x << " " << ans << endl;
        }
    }
}

