}

struct SegTree {
	std::vector<int64_t> data;
	int n;
	SegTree(int n_) {
		for (n = 1; n < n_; n *= 2);
		data.resize(2 * n);
	}
	void add(int index, int64_t value) {
		for (index += n; index; index >>= 1) data[index] += value;
	}
	int64_t sum(int l, int r) {
		int64_t res = 0;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (r & 1) r--, res += data[r];
			if (l & 1) res += data[l], l++;
		}
		return res;
	}
	int bin_search() {
		int64_t big = sum(0, n);
		int index = (big + 1) / 2 - 1;
		int l = 0;
		int r = n;
		while (r - l > 1) {
			int m = l + (r - l) / 2;
			if (sum(0, m) > index) r = m; // out
			else l = m;
		}
		return l;
	}
};


struct Query {
	int type;
	int a;
	int b;
};

int main() {
	int q = ri();
	std::set<int> inserts;
	std::vector<Query> qs;
	for (int i = 0; i < q; i++) {
		int type = ri();
		if (type == 1) {
			int a = ri();
			int b = ri();
			qs.push_back({type, a, b});
			inserts.insert(a);
		} else qs.push_back({type, 0, 0});
	}
	SegTree tree(inserts.size());
	SegTree sum(inserts.size());
	std::vector<int> decomp;
	for (auto i : inserts) decomp.push_back(i);
	std::map<int, int> comp;
	for (size_t i = 0; i < decomp.size(); i++) comp[decomp[i]] = i;
	int64_t add = 0;
	int optimized = -1;
	for (int i = 0; i < q; i++) {
		if (qs[i].type == 1) { // add
			add += qs[i].b;
			tree.add(comp[qs[i].a], 1);
			sum.add(comp[qs[i].a], qs[i].a);
			optimized = tree.bin_search();
			assert(optimized >= 0 && optimized < inserts.size());
		} else {
			if (optimized == -1) std::cout << 0 << std::endl;
			else {
				int value = decomp[optimized];
				int64_t res = tree.sum(0, optimized) * value - sum.sum(0, optimized);
				res += sum.sum(optimized, inserts.size()) - tree.sum(optimized, inserts.size()) * value;
				std::cout << value << " " << res + add << std::endl;
			}
		}
	}

	return 0;
}

