const double pi = (double) acos(-1.0);

struct Node
{
    LL sum;
    int cnt;
    Node *lch, *rch;

    Node() {sum = cnt = 0; lch = rch = NULL;}
};

void ins(int val, int l, int r, int id, Node *&rt)
{
//    cout <<l <<" " <<r <<endl;
    if(rt == NULL) rt = new Node();
    rt->cnt++;
    rt->sum += val;
    if(l == r) return ;
    int mid = MID(l, r);

    if(val <= mid) ins(val, lson, rt->lch);
    else ins(val, rson, rt->rch);
}

inline int sz(Node *rt) {if(rt == NULL) return 0;  return rt->cnt;}
int find_mid(int k, int l, int r, int id, Node *rt)
{
    if(l == r) return l;
    int mid = MID(l, r);
    if(sz(rt->lch) < k) return find_mid(k - sz(rt->lch), rson, rt->rch);
    return find_mid(k, lson, rt->lch);
}

complex<LL> get(int L, int R, int l, int r, int id, Node *rt)
{
    if(rt == NULL || L > R) return complex<LL> (0, 0);
    if(L <= l && r <= R) return complex<LL> (rt->cnt, rt->sum);

    int mid = MID(l, r);
    if(R <= mid) return get(L, R, lson, rt->lch);
    if(mid < L)  return get(L, R, rson, rt->rch);
    return get(L, R, lson, rt->lch) + get(L, R, rson, rt->rch);
}


