ll tree[5000000],tree2[5000000];


void update(int node,int l,int r,int i,ll x)
{
    if(i<l || r<i)
        return;
    if(l==r)
    {
        tree[node]=(tree[node]+x);
        ++tree2[node];
        return;
    }
    update(node*2,l,(l+r)/2,i,x);
    update(node*2+1,(l+r)/2+1,r,i,x);
    tree[node]=(tree[node*2]+tree[node*2+1]);    //Change for min/sum
    tree2[node]=(tree2[node*2]+tree2[node*2+1]);    //Change for min/sum
}

pll query(int node,int l,int r,int i,int j)
{
    if(j<l || r<i)
        return {0,0};   //Change for min/sum
    if(i<=l && r<=j)
    {
        return {tree[node],tree2[node]};
    }
    pll q1=query(node*2,l,(l+r)/2,i,j);
    pll q2=query(node*2+1,(l+r)/2+1,r,i,j);
    return {q1.f+q2.f,q1.s+q2.s};  //Change for min/sum
}   


ll tree3[5000000];


void update2(int node,int l,int r,int i,ll x)
{
    if(i<l || r<i)
        return;
    if(l==r)
    {
        //cout<<l<<" "<<r<<" "<<tree3[node]<<endl;
        ++tree3[node];
        return;
    }
    update2(node*2,l,(l+r)/2,i,x);
    update2(node*2+1,(l+r)/2+1,r,i,x);
    tree3[node]=(tree3[node*2]+tree3[node*2+1]);    //Change for min/sum
}

ll query2(int node,int l,int r,int i,int j)
{
    if(j<l || r<i)
        return 0;   //Change for min/sum
    //cout<<l<<" "<<r<<" "<<i<<" "<<j<<" "<<tree3[node]<<endl;
    if(i<=l && r<=j)
    {
        return tree3[node];
    }
    ll q1=query2(node*2,l,(l+r)/2,i,j);
    ll q2=query2(node*2+1,(l+r)/2+1,r,i,j);
    return (q1+q2);  //Change for min/sum
}   


