//Range Minimum Query
struct segment {
    int n;
    vvi dat;
    // n_は範囲
    segment(int n_) { // nはn_以上の2^?
        n = 1<<(32-__builtin_clz(n_));
        if(n == 2*n_) n >>= 1;
        dat.resize(2*n-1);
    }
    inline int chld(int i) {return 2*i+1;}
    inline int chrd(int i) {return 2*i+2;}
    //更新の手順
    inline void theorem(int i, vi &v) {
        v.resize(dat[chld(i)].size() + dat[chrd(i)].size());
        merge(all(dat[chld(i)]), all(dat[chrd(i)]), v.begin());
    }
    // k番目の値をaに変更
    void update(int k, int64_t a) {
        // 葉の節点
        k += n-1;
        dat[k].push_back(a);
        // 登りながら更新
        while(k>0) {
            k = (k-1)/2;
            theorem(k, dat[k]);
        }
    }
};


int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int q;
    cin >> q;
    int l = 0, r = 0;
    ll sum = 0;
    segment seg(2*100000);
    int j = 0;
    while(q--) {
        int tt;
        cin >> tt;
        if(tt == 1) {
            ll a, b;
            cin >> a >> b;
            sum += b;
            seg.update(j++, a);
        }
        else {
            ll num = seg.dat[0][(j-1)/2];
            ll que = sum;
            rep(i, j) {
                que += abs(num-seg.dat[0][i]);
            }
            cout << num << ' ' << que << '\n';
        }
    }
}

