          if (cmd == 1) {
             int a, b;
             scanf("%d %d", &a, &b);
             sumb += b;
             if (stS.empty() || (*stS.rbegin() >= a)) {
                stS.insert(a);
                sumS += a;
             } else {
                stL.insert(a);
                sumL += a;
             }
             int num = stS.size() + stL.size();
             int md_idx = num / 2 + ((num % 2) ? 1 : 0);
             while ((int)stS.size() > md_idx) {
                   int tmp = *stS.rbegin();
                   sumS -= tmp, sumL += tmp;
                   stS.erase(prev(stS.end()));
                   stL.insert(tmp);
             }
             while ((int)stS.size() < md_idx) {
                   int tmp = *stL.begin();
                   sumS += tmp, sumL -= tmp;
                   stS.insert(tmp);
                   stL.erase(stL.begin());
             }
          } else {
             LL md = *stS.rbegin();
             LL ans = (LL)stS.size() * md - sumS - (LL)stL.size() * md + sumL;
             printf(" %lld\n", ans + sumb);
          }
