	priority_queue<ll,vector<ll>,greater<ll>> qr;

	ll qlsum = 0; // ql に入っているaの合計
	ll qrsum = 0; // qr に入っているaの合計
	ll bsum = 0;

	auto qlpush = [&](ll a){
		ql.push(a);
		qlsum += a;
	};
	auto qrpush = [&](ll a){
		qr.push(a);
		qrsum += a;
	};
	auto qlpop = [&](){
		ll a = ql.top();
		ql.pop();
		qlsum -= a;
		return a;
	};
	auto qrpop = [&](){
		ll a = qr.top();
		qr.pop();
		qrsum -= a;
		return a;
	};



