			ll a, b;
			cin >> a >> b;
			bsum += b;

			if ( ql.size() == 0 ){
				qlpush(a);
			}
			else if ( ql.top() < a ){
				qrpush(a);

				if ( ql.size() < qr.size() ){
					qlpush(qrpop());
				}
			}
			else {
				qlpush(a);

				if ( ql.size() > qr.size()+1 ){
					qrpush(qlpop());
				}
			}
