using namespace std;

struct tree{
	long long int val;
	struct tree* left;
	struct tree* right;
	int w;
	long long int weight;
};
typedef struct tree* Tree;

Tree insertNode(long long value, Tree root) {
	if (root == nullptr) {
		root = new struct tree();
		root -> val = value;
		root -> left = root -> right = nullptr;
		root -> w = 1;
		root -> weight = root -> val;
		return root;
	}	
	root -> w += 1;	
	root -> weight += value;
	if (root -> val == value) {
		return root;
	}

	if (root -> val > value) {
		root -> left = insertNode(value, root -> left);
	}
	else {
		root -> right = insertNode(value, root -> right);
	}
	return root;
}
// return w and weight
pair<long long int, long long int> searchNode(int n, Tree root, long long int previousWeight) {

	if (root -> right != nullptr && root -> w - root -> right -> w < n) {
		return searchNode(n - root -> w + root -> right -> w, 
			root -> right, 
			root -> weight - root -> right -> weight + previousWeight) ;
	}

	if ((root -> left == nullptr) || root -> left -> w < n) {
		if (root -> left == nullptr) 
			return make_pair(root -> val, root -> val * n + previousWeight);
		else
			return make_pair(root -> val, previousWeight + root -> left -> weight + root -> val * (n - root -> left -> w));
	}
	return searchNode(n, root -> left, previousWeight);
}

int main(int argc, char *argv[]) {
	Tree root = nullptr;
	int q;
