#include <bits/stdc++.h>
using namespace std;

#define int long long

const int N = 2e5 + 10;
int n, sz, sum, ans, point, cntl;
map <int, int> cnt;
set <int> st;

void go_left() {
	auto it = st.find(point);
	assert(it != st.begin() && it != st.end());
	it--;

	int x = *it, d = point - x;
	ans += (sz - cntl) * d;
	ans -= cntl * d;
	cntl -= cnt[x];
	point = x;
}

void go_right() {
	auto it = st.upper_bound(point);
	assert(it != st.end());

	int x = *it, d = x - point;
	ans += (cntl + cnt[point]) * d;
	ans -= (sz - cntl - cnt[point]) * d;
	cntl += cnt[point];
	point = x;
}

void add(int x) {
	cnt[x]++;
	st.insert(x);
	sz++;
	if (sz == 1) {
		point = x;
		return;
	}

	if (x > point)
		ans += x - point;
	else if (x < point)
		ans += point - x, cntl++;

	while ((sz + 1) / 2 > cntl + cnt[point])
		go_right();
	while ((sz + 1) / 2 <= cntl)
		go_left();
}

