void addmid(ll v){
    if(l.size()==r.size()){
        if(l.size()&&l.top()>v){
            r.emplace(l.top());
            l.pop();
            l.emplace(v);
        }
        else r.emplace(v);
    }else{
        if(r.top()<v){
            l.emplace(r.top());
            r.pop();
            r.emplace(v);
        }else l.emplace(v);
    }
}
ll getmid(){
    if(l.size()==r.size())return l.top();
    return r.top();
}
