// 1-indexed BIT 空間O(N), クエリO(log N)
// validated: https://joisc2011.contest.atcoder.jp/submissions/3210568
// [arg]
// N: 必要な要素数
template <typename T>
struct BIT {
    int n;
    vector<T> bit;
    BIT(int n_) : n(n_), bit(n_ + 1) {}

    // add: v[a] += w;
    void add(int a, T w) {
        for(int x = a; x <= n; x += x & -x) bit[x] += w;
    }
    // sum: v[1] + ... + v[a]
    T sum(int a) {
        T ret = 0;
        for(int x = a; x > 0; x -= x & -x) ret += bit[x];
        return ret;
    }

    // update: v[x] = f(v[x], w);
    void update(int a, T w, function<T(T, T)> f) {
        for(int x = a; x <= n; x += x & -x) bit[x] = f(bit[x], w);
    }

    // accumulate: f(init, f(v[1], f(v[2], ..., f(v[a - 1], v[a])...))
    T accumulate(int a, function<T(T, T)> f, T init = 0) {
        T ret = init;
        for(int x = a; x > 0; x -= x & -x) {
            ret = f(ret, bit[x]);
        }
        return ret;
    }
};

struct Query {
    ll type;
    ll a, b, c;
};

void solve() {
    int N;
    cin >> N;
    ll h = 0;
    BIT<ll> bit(N + 2);
    BIT<ll> bit_cnt(N + 2);

    vector<Query> Q(N);
    map<ll, ll> mp;
    for (int i = 0; i < N; i++) {
        ll t, a, b;
        cin >> t;
        if (t == 1) {
            int a, b;
            cin >> a >> b;
            mp[a] = 0;
            Q[i] = (Query){t, a, b, 0};
        } else {
            Q[i] = (Query){t, 0, 0, -1};
        }
    }

    ll num = 0;
    for (auto x : mp) {
        mp[x.first] = num;
        num++;
    }

    for (int i = 0; i < N; i++) {
        if (Q[i].type == 2) continue;
        Q[i].c = mp[Q[i].a];
    }

    tree<ll, null_type, less<ll>, rb_tree_tag, tree_order_statistics_node_update> T;
    for (int i = 0; i < N; i++) {
        if (Q[i].type == 1) {
            ll a = Q[i].a; ll b = Q[i].b; ll c = Q[i].c;
            T.insert(a);
            int k = T.order_of_key(a);
            bit.add(c + 1, a);
            bit_cnt.add(c + 1, 1);
            h += b;
        } else {
            ll n = T.size();
            int k = (n - 1) / 2;
            ll minx = *T.find_by_order(k);
            int c = mp[minx];
            //cout << "aaa:" << bit.sum(c) << endl; 
            ll sum1 = bit.sum(c);
            ll c1 = bit_cnt.sum(c);
            // cout << bit.sum(N) << ":::" << bit.sum(c + 1) << endl;
            ll sum2 = bit.sum(N) - bit.sum(c + 1);
            ll c2 = bit_cnt.sum(N) - bit_cnt.sum(c + 1);
            //cout << "h:" << h << endl;
            //cout << sum1 << ":" << sum2 << endl;
            cout << minx << " " << h - sum1 + sum2 + c1 * minx - c2 * minx << endl;


        }
    }

}

