                lq.push(a);
                L += a;
            } else {
                if (a <= lq.top()) {
                    lq.push(a);
                    L += a;
                } else if (gq.top() <= a) {
                    gq.push(a);
                    G += a;
                } else {
                    lq.push(a);
                    L += a;
                }
            }
            if (lq.size() + 1 <= gq.size()) {  // g が多くなっている
                ll now = gq.top();
                gq.pop();
                lq.push(now);
