                pre.insert(a);
                sum[0] = a;
                continue;
            }
            if (pre.size()==post.size()) {
                auto it = post.begin();
                if (*it < a) {
                    post.erase(it);
                    post.insert(a);
                    pre.insert(*it);
                    sum[1] += a-*it;
