                pre.insert(a);
                post.insert(*it);
                sum[0] += a - *it;
                sum[1] += *it;
            } else {
                post.insert(a);
                sum[1]+=a;
            }
        } else {
            int x = *(pre.rbegin());
            int s = ans + pre.size()*x - sum[0] + sum[1] - post.size()*x;
            _PN(x,s);
