template <typename T>
struct LRPrique {
    using F = function<int(int)>;
    const F f;
    priority_queue<T> L;
    priority_queue<T, vector<T>, greater<>> R;
    int L_sz, R_sz;
    T L_sum, R_sum;
    // f(sz) -> size of L
    // e.g.) median : [](int sz) -> int { return (sz + 1) / 2; }
    LRPrique(F f)
        : f(f), L_sz(0), R_sz(0), L_sum(0), R_sum(0) {}
    void L_push(T x) {
        ++L_sz;
        L_sum += x;
        L.emplace(x);
    }
    void R_push(T x) {
        ++R_sz;
        R_sum += x;
        R.emplace(x);
    }
    T L_pop() {
        T ret = L.top();
        L.pop();
        --L_sz;
        L_sum -= ret;
        return ret;
    }
    T R_pop() {
        T ret = R.top();
        R.pop();
        --R_sz;
        R_sum -= ret;
        return ret;
    }
    void emplace(T x) {
        if (L.empty() or L.top() > x)
            L_push(x);
        else
            R_push(x);
    }
    void flatten() {
        int gL_sz = f(L_sz + R_sz);
        while (L.size() < gL_sz) {
            T tp = R_pop();
            L_push(tp);
        }
        while (L.size() > gL_sz) {
            T tp = L_pop();
            R_push(tp);
        }
    }
    T get() {
        flatten();
        return L.top();
    }
};

signed main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    // MedianPrique
    LRPrique<ll> lr([](int sz) -> int { return (sz + 1) / 2; });

    int Q;
    cin >> Q;
    ll margin = 0;

    while (Q--) {
        int T;
        cin >> T;
        if (T == 1) {
            int a, b;
            cin >> a >> b;
            lr.emplace(a);
            margin += b;
        } else {
            ll med = lr.get();
            ll mn  = margin + (lr.R_sum - med * lr.R_sz) + (med * lr.L_sz - lr.L_sum);
            cout << med << ' ' << mn << endl;
        }
    }
}

