int Q;
PP ans;

priority_queue<LL> F;
priority_queue<LL, vector<LL>, greater<LL>> G;
LL X;
LL Y;
void sub(int a) {
	X += a;
	F.push(a);

	if (F.size() >= G.size() + 2) {
		LL k = F.top(); F.pop();
		G.push(k);
		X -= k;
		Y += k;
	}

	LL pos = F.top();
	LL val = (Y - X) - pos * ((int)G.size() - F.size());
	ans = PP(pos, val);
}

