void solver() {
  int Q = input();

  priority_queue< int64 > lhs;
  priority_queue< int64, vector< int64 >, greater< int64 > > rhs;
  int64 lhs_sum = 0, rhs_sum = 0, b_sum = 0;

  range(i, 0, Q) {
    int com;
    cin >> com;

    if (com == 1) {
      int64 a = input(), b = input();
      b_sum += b;

      if (i == 0 || lhs.top() > a) {
        lhs.push(a);
        lhs_sum += a;

        if (lhs.size() == rhs.size() + 2) {
          rhs.push(lhs.top());
          rhs_sum += lhs.top();

          lhs_sum -= lhs.top();
          lhs.pop();
        }
      } else {
        if (lhs.size() > rhs.size()) {
          rhs.push(a);
          rhs_sum += a;
        } else {
          lhs.push(a);
          lhs_sum += a;
        }
      }
    }

    else {
      cout << lhs.top() << " " << (int)lhs.size() * lhs.top() - lhs_sum + rhs_sum - (int)rhs.size() * lhs.top() + b_sum << endl;
    }
  }
}

signed main(int argc, char *argv[]) {
  solver();
}

