using namespace std;

class query {
public:
    int type;
    int a, b;
    query(int tin, int ain, int bin) {
        type = tin;
        a = ain;
        b = bin;
    }
};

signed main() {
    int Q;
    cin >> Q;
    vector<query> queries;
    rep(i, Q) {
        int t, a = -1, b = -1;
        cin >> t;

        if (t == 1) {
            cin >> a >> b;
        }

        queries.emplace_back(t, a, b);
    }
    priority_queue<int> smaller;    //中央値 イカ
    priority_queue<int, vector<int>, greater<int>> bigger;  //bigger は小さい順に取り出したい
    int SSum = 0, BSum = 0, constantsSum = 0;

    //奇数の場合はSmallerに寄せる(簡単のため) -> smaller のtop がつねに中央値
    rep(i, Q) {
        if (queries[i].type == 1) {
            constantsSum += queries[i].b;
            if (smaller.size() > bigger.size()) {
                //bigger にいれる
                int t = smaller.top();
                if (queries[i].a >= t) {
                    bigger.push(queries[i].a);
                    BSum += queries[i].a;
                }
                else {
                    smaller.pop();
                    SSum -= t;
                    smaller.push(queries[i].a);
                    SSum += queries[i].a;
                    bigger.push(t);
                    BSum += t;
                }
            }
            else {
                //smaller にいれる
                if (smaller.empty()) {
                    smaller.push(queries[i].a);
                    SSum += queries[i].a;
                }
                else {
                    int t = bigger.top();
                    if (queries[i].a <= t) {
                        smaller.push(queries[i].a);
                        SSum += queries[i].a;
                    }
                    else {
                        bigger.pop();
                        BSum -= t;
                        bigger.push(queries[i].a);
                        BSum += queries[i].a;
                        smaller.push(t);
                        SSum += t;
                    }
                }
            }
        }
        else {
            int med = smaller.top();
            int ans = BSum - bigger.size() * med + smaller.size() * med - SSum + constantsSum;
            cout << smaller.top() << " " << ans << "\n";
        }

    }


    return 0;
}

