void query1(ll a, ll b)
{
  B += b;
  if (m.size() == 1) {
    mi += abs(a - m[0]);
    if (m[0] < a) {
      rq.push(a);
      m.push_back(rq.top());
      rq.pop();
    } else {
      lq.push(a);
      m.push_back(lq.top());
      lq.pop();
      swap(m[0], m[1]);
    }
  } else {
    if (a <= m[0]) {
      lq.push(a);
      rq.push(m[1]);
      mi += m[0] - a;
      m.pop_back();
    } else if (m[1] <= a) {
      rq.push(a);
      lq.push(m[0]);
      mi += a - m[1];
      m[0] = m[1];
      m.pop_back();
    } else {
      lq.push(m[0]);
      rq.push(m[1]);
      m[0] = a;
      m.pop_back();
    }
  }
}

