// priority_queueをふたつ用意して
// 区間の左側と右側を管理すれば良い。
int writer_solve(){

    ll sumB=0;
    int n=0;
    ll f=0;
    ll sum_for=0,sum_back=0;
    priority_queue<ll> foward; // 最大値を返す。
    priority_queue<ll,vector<ll>,greater<ll>> back; // 最小値を返す。
    vector<pair<int,ll>> ans;
    for (int i = 0; i < Q; i++)
    {
        int q;
        cin >> q;
        if(q==1){
            n++;
            ll a,b;
            cin >> a >> b;
            sumB+=b;
            if(foward.size()>back.size()){
                // 後方に入れる。
                ll t=foward.top();
                if(a>=t){
                    back.push(a);
                    sum_back+=a;
                }
                else{
                    back.push(t);
                    sum_back+=t;
                    sum_for-=t;
                    sum_for+=a;
                    foward.pop();
                    foward.push(a);
                }
            }
            else{
                // 前方に入れる。
                if(foward.empty()) {foward.push(a);sum_for+=a;continue;}
                ll t=back.top();
                if(a<=t){
                    foward.push(a);
                    sum_for+=a;
                }
                else{
                    foward.push(t);
                    sum_for+=t;
                    sum_back-=back.top();
                    sum_back+=a;
                    back.pop();
                    back.push(a);
                }
            }

        }
        else{
            ll mid=foward.top();
            ll a=mid*(int)foward.size()-sum_for+sum_back-mid*(int)back.size();
            ans.emplace_back(mid,a+sumB);
        }
    }

    for(auto a:ans) cout << a.first << " " << a.second << "\n";
    return 0;
}

