// 中央値を O(1) で返し、動的に要素を追加できるデータ構造
// 要素数の合計が偶数なら、 2 つある中央値のうち小さい方を返す
class Median {
public:
    Median() : m_SumL(0), m_SumR(0) {}

    // 要素 x を追加
    void Add(ll x) {
        if(m_L.size() == 0 || x <= m_L.top()) {
            m_L.push(x);
            m_SumL += x;
        }
        else {
            m_R.push(x);
            m_SumR += x;
        }
        if((m_L.size() + m_R.size()) % 2 == 0) {
            // 要素数が偶数なら m_L と m_R の数は同じになるはず
            // (この時点で m_R の方が大きい状況はあり得ない)
            if(m_L.size() > m_R.size()) {
                m_SumL -= m_L.top();
                m_SumR += m_L.top();
                m_R.push(m_L.top());
                m_L.pop();
            }
            assert(m_L.size() == m_R.size());
        }
        else {
            // 要素数が奇数なら m_L の数が m_R より一つ多くなる
            if(m_L.size() < m_R.size()) {
                m_SumL += m_R.top();
                m_SumR -= m_R.top();
                m_L.push(m_R.top());
                m_R.pop();
            }
