    // 中央値より右側の値の合計を返します
    ll GetRSum() { return m_SumR; }
    // 中央値含む左側の要素数
    ll GetSizeL() { return m_L.size(); }
    // 中央値より右側の要素数
    ll GetSizeR() { return m_R.size(); }

private:
