          lo.erase(*lo.rbegin());
        }
      } else {
        hi.insert(a);
        hi_sum += a - *mid;
        while (lo.size() + 1 < hi.size()) {
          ll change = *hi.begin() - *mid;

          lo.insert(*mid);
          lo_sum += change * lo.size();

          mid = *hi.begin();

          hi_sum -= change * hi.size();
          hi.erase(hi.begin());
        }
      }
