int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int Q;
  while(cin >> Q){
    LLI B = 0;

    LLI s1 = 0, s2 = 0;
    priority_queue<pair<LLI,int>> q1;
    rev_priority_queue<pair<LLI,int>> q2;

    REP(i,Q){
      int c; cin >> c;

      if(c == 1){
	LLI a,b; cin >> a >> b;

	pair<LLI,int> p = {a,i};

	if(q1.size() == q2.size()){
	  q2.push(p); s2 += a;
	  auto pp = q2.top(); q2.pop(); s2 -= pp.fst;

	  q1.push(pp); s1 += pp.fst;
	}else{
	  q1.push(p); s1 += a;
	  auto pp = q1.top(); q1.pop(); s1 -= pp.fst;

	  q2.push(pp); s2 += pp.fst;
	}

	B += b;
      }else{
	LLI x1 = q1.top().fst;
	LLI x2 = q2.top().fst;

	LLI ans1 = abs(s1-x1*q1.size())+abs(s2-x1*q2.size()) + B;
	LLI ans2 = abs(s1-x2*q1.size())+abs(s2-x2*q2.size()) + B;

	if(ans1 <= ans2)
	  cout << x1 << " " << ans1 << endl;
	else
	  cout << x2 << " " << ans2 << endl;
      }
    }

  }

  return 0;
}

