using namespace std;
int cnt;
long long bsum, lsum = 0, rsum = 0;
bool isodd = true;
multiset<int> lft, rit;
void lins(int x){
    lft.insert(x);
    lsum += x;
}
void rins(int x){
    rit.insert(x);
    rsum += x;
}
void update(int a, int b){
    if(isodd){
        if(a < cnt){
            lins(a);
            rins(cnt);
        }else{
            lins(cnt);
            rins(a);
        }
    }else{
        auto lmax = lft.end(); lmax--;
        auto rmin = rit.begin();
        if(a < *lmax){
            lins(a);
            auto itr = lft.end(); itr--;
            lsum -= *itr;
            cnt = *itr;
            lft.erase(itr);
        }else{
            rins(a);
            auto itr = rit.begin();
            rsum -= *itr;
            cnt = *itr;
            rit.erase(itr);
        }
    }
    isodd = !isodd;
    bsum += b;
}
void ans(int &x, long long &fmin){
    if(isodd){
        x = cnt;
        fmin = bsum - lsum + rsum;
    }else{
        auto itr = lft.end(); itr--;
        x = *itr;
        fmin = bsum - lsum + rsum;
    }
}
int main() {
    int q, a, b, c;
    cin >> q;
    cin >> c >> cnt >> bsum; // 
    lft.insert(-1e9);
    rit.insert(1e9);
    for(int i=1;i<q;i++){
        cin >> c;
        if(c == 1){
            cin >> a >> b;
            update(a, b);
        }else{
            int x;
            long long fmin;
            ans(x, fmin);
            cout << x << " " << fmin << endl;
        }
    }
	return 0;
}

