class Median {
private:
    priority_queue<ll> former;
    priority_queue<ll,vector<ll>,greater<ll>> latter;
public:
    ll former_sum = 0, latter_sum = 0;
    Median();
    void add(ll x);
    ll get();
    P sizes();
    ~Median();
};

Median::Median() {
}

// pair(former, latter)
P Median::sizes() {
    P ret = P((ll)former.size(), (ll)latter.size());
    return ret;
}

// add a number into data structure
void Median::add(ll x) {
    // どちらに入る？
    if (former.empty()) {
        former.push(x);
        former_sum += x;
    }
    else {
        ll former_top = former.top();
        if (former_top < x) {
            latter.push(x);
            latter_sum += x;
        }
        else {
            former.push(x);
            former_sum += x;
        }
    }

    // 数を合わせる
    // when latter has one more element
    if ((int)latter.size() == (int)former.size()+1) {
        ll tmp = latter.top(); latter.pop();
        latter_sum -= tmp;
        former.push(tmp);
        former_sum += tmp;
    }
    // when former has two more elements
    else if ((int)(former.size()) == (int)latter.size()+2) {
        ll tmp = former.top(); former.pop();
        former_sum -= tmp;
        latter.push(tmp);
        latter_sum += tmp;
    }
    else if ((int)former.size() == (int)latter.size() || (int)former.size() == (int)latter.size()+1) {}
    else {
        assert(false);
        cout << "I don't consider this situation" << '\n';
        cout << "the size of former is " << former.size() << '\n';
        cout << "and the size of latter is " << latter.size() << '\n';
    }
}

// get the median
ll Median::get() {
    return former.top();
}

Median::~Median() {
}


int main(int argc, char const *argv[]) {
    int q; cin>>q;
    Median med;
    ll b_sum = 0;
    ll pl = 0; int pl_cnt = 0;
    ll mi = 0; int mi_cnt = 0;
    while (q--) {
        int type; cin>>type;
        if (type==1) {
            ll a,b; cin>>a>>b;
            med.add(a);
            if (a>0) {
                pl_cnt++;
                pl += a;
            }
            else {
                mi_cnt++;
                mi += abs(a);
            }
            b_sum += b;
        }
        else {
            ll m = med.get();
            ll ret = 0;
            ll former_sum = med.former_sum;
            ll latter_sum = med.latter_sum;
            ll fs,ls;
            tie(fs, ls) = med.sizes();
            ret += fs*m-former_sum;
            ret += latter_sum-ls*m;
            ret += b_sum;
            cout << m << ' ' << ret << '\n';
        }
    }
    return 0;
}

