		}
	}
	sort(ord.begin(), ord.end());
	vector<int> rev(n, -1);
	//query -> idx
	int m = ord.size();
	map<lli, int> numrev;
	for(int i=0; i<m; i++){
		rev[ord[i].second] = i;
		numrev[ord[i].first] = i;
	}

	segmentTree seg(vector<lli>(m, 0));
	segmentTree segnum(vector<lli>(m, 0));
	vector<int> nums;
	lli bsum = 0;
	for(int i=0; i<n; i++){
		if(query[i][0] == 1){
			seg.Set(query[i][1], rev[i]);
			segnum.Set(1, rev[i]);
			bsum += query[i][2];
			nums.insert(lower_bound(nums.begin(), nums.end(), query[i][1]), query[i][1]);
		}else{
			lli pos = (int)nums.size()%2 == 0? nums[nums.size()/2-1] :nums[nums.size()/2];
			int idx = numrev[pos];
