    root = NULL;
    ll q;
    cin >> q;
    for (int i = 1; i <= q; i++) {
        cin >> tp;
        if (tp == 1) {
            cin >> a >> b;
            upd(root, -inff, inff, a);
            cb += b;
            cnt++;
            sm += a;
        } else {
            L = -inff;
            R = inff;
            pll ans = {inf, inf};
            while (L <= R) {
                M = getmid(L, R);
                ans = min(ans, {getv(M), M});
                if (getv(M) <= getv(M + 1))
                    R = M - 1;
                else
                    L = M + 1;
            }
            cout << ans.se << " " << ans.f << "\n";
        }
    }
    return 0; 
}

