                auto itr = av.begin();
                if(av.size() % 2 == 0){
                    REP(j,av.size() / 2) itr++;
                    ansx = *itr;
                    if(ansx == preansx){
                        anssum += b + llabs(ansx - a);
                    }else{
                        anssum += b + llabs(preansx - a);
                    }
                }else{
                    REP(j,(av.size()+1) / 2) itr++;
                    ansx = *itr;
                    if(ansx == preansx){
                        anssum += b + llabs(ansx - a);
                    }else{
                        anssum += b + llabs(ansx - a);
                    }
                }
            }
        }
    }
}

