             tree_order_statistics_node_update>
    ordered_set;

int main(int argc, char *argv[]) {
  // read number of queries
  long Q, ts[MAX_Q], as[MAX_Q], bs[MAX_Q];
  scanf("%ld", &Q);
  for (long q = 0; q < Q; q++) {
    scanf("%ld", &ts[q]);
    if (ts[q] == 1) {
      scanf("%ld %ld", &as[q], &bs[q]);
    }
  }

  // respond to each query
  long total_b = 0, total_d = 0, min_q = -1, min_a = -1;
  ordered_set ps;
  // process query 0
  total_b += bs[0];
  ps.insert(make_pair(as[0], 0));
  min_q = 0;
  min_a = as[0];
  // printf("q = %ld, total_b = %ld, min_a = %ld, total_d = %ld\n", 0L, total_b,
  //        min_a, total_d);
  // process the other queries
  for (long q = 1; q < Q; q++) {
    const long t = ts[q];
    if (t == 1) {
      const long a = as[q], b = bs[q];
      total_b += b;
      ps.insert(make_pair(a, q));
      const long k = ps.size();
      total_d += abs(a - min_a);
      // does min_q, min_a change?
      if (k % 2L == 0L && a < min_a) {
        const pair<long, long> new_min_p = *ps.find_by_order((k - 1) / 2);
        const long new_min_a = new_min_p.first, new_min_q = new_min_p.second;
        // total_d -= abs(new_min_a - min_a);
        // printf("min_a changed from %ld to %ld\n", min_a, new_min_a);
        min_a = new_min_a;
        min_q = new_min_q;
      } else if (k % 2L == 1L && a > min_a) {
        const pair<long, long> new_min_p = *ps.find_by_order((k - 1) / 2);
        const long new_min_a = new_min_p.first, new_min_q = new_min_p.second;
        total_d -= abs(new_min_a - min_a);
        // printf("min_a changed from %ld to %ld\n", min_a, new_min_a);
        min_a = new_min_a;
        min_q = new_min_q;
      }
      // printf("q = %ld, total_b = %ld, min_a = %ld, total_d = %ld\n", q, total_b,
      //        min_a, total_d);
    } else {
      printf("%ld %ld\n", min_a, total_b + total_d);
    }
  }

  return 0;
}

