priority_queue<int> L, R;
long long sum, sl, sr;

void push(int x) {
	if (L.empty() || x < L.top()) L.push(x), sl += x;
	else R.push(-x), sr += x;
	if (L.size() > R.size() + 1) {
		sl -= L.top(), sr += L.top();
		R.push(-L.top()), L.pop();
	}
	if (L.size() < R.size()) {
		sl += -R.top(), sr -= -R.top();
		L.push(-R.top()), R.pop();
	}
}

long long ans() {
	int x = L.top();
	printf("%d %lld\n", x, x * (long long)L.size() - sl + sr - x * (long long)R.size() + sum);
}

