        if (s.size() > g.size()) {
            if (x <= (medl + medr)/2) {
                g.push(s.top());
                s.pop();
                s.push(x);
            } else
                g.push(x);

            medl = min(s.top(),g.top()),medr = max(s.top(), g.top());
        }

            // case2(both heaps are balanced)
        else if (s.size() == g.size()) {
            if (x < (medl + medr)/2) {
                s.push(x);
                medl = medr = (ll) s.top();
            } else {
                g.push(x);
                medl = medr = (ll) g.top();
            }
        }

            // case3(right side heap has more elements)
        else {
            if (x > (medl + medr)/2) {
                s.push(g.top());
                g.pop();
                g.push(x);
            } else
                s.push(x);

            medl = min(s.top(),g.top()),medr = max(s.top(), g.top());
        }
        if(i&1)sum += max({mx_t - *st.rbegin(),*st.begin() - mi_t,medl_t - medl,  medr - medr_t});
