int main(void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int q; cin>>q;
    RichMultiSet<ll> s(q);
    ll sum=0;
    while(q--){
        int t; cin>>t;
        if (t==1){
            ll a,b; cin>>a>>b;
            sum+=b;
            s.ins(a);
        }else{
            int n = s.size();
            int k = (n-1)/2;
            ll x = s[k];
            ll L = x*k-s.query(0,k);
            ll R = s.query(k+1,n)-x*(n-k-1);
            cout<<x<<" "<<L+R+sum<<"\n";
        }
    }
    return 0;
}

