		SINT64 len = 0;
		// L S LMS判定 初期値は全てS
		rrep(i,Vstr.size()-2,0) {
			len++;
			if (Vstr[i] > Vstr[i+1]) {
				lms_type[i] = 0;					// L
				if (lms_type[i+1] == 1) {
