#define ll long long
#define N 200005

int type[N];
int a[N],b[N];

ll cc[N],sum[N];

void update(ll *pen,int ind,ll val) {
  while(ind<N) {
    pen[ind] += val;
    ind += ind&(-ind);
  }
}

ll val[N];
ll query(ll *pen,int ind) {
  ll ret = 0;
  while(ind>0) {
    ret += pen[ind];
    ind = ind&(ind-1);
  }
  return ret;
}
void solve() {
  int Q;scanf("%d ", &Q);
  map<int,int> Hash;
  for(int i=0;i<Q;++i) {
    scanf("%d ", &type[i]);
    if(type[i]==1) {
      scanf("%d %d ", &a[i],&b[i]);
      Hash[a[i]];
    }
  }
  int pos=0;
  for(map<int,int>::iterator it = Hash.begin();it!= Hash.end();++it) {
    it->second = ++pos;
    val[pos] = it->first;
  }
  long long sumOfB = 0;
  int numTypeOne = 0;
  for(int i=0;i<Q;++i) {
    if(type[i]==1) {
      sumOfB += b[i];
      int aId = Hash[a[i]];
      update(cc,aId,1);
      update(sum,aId,a[i]);
      ++numTypeOne;
    } else {
      int l = 1 , r= pos,mid;
      while(l<r) {
        mid = (l+r+1)/2;
        if(query(cc,mid)*2<=numTypeOne) {
          l = mid;
        } else {
          r = mid-1;
        }
      }
      ll R = 1e18;ll k;
      for(int j=max(1,l-1);j<=min(pos,l+1);++j) {
        ll v = val[j];
        ll numLow = query(cc,j),sumLow = query(sum,j);
        ll numHigh = numTypeOne-numLow, sumHigh = query(sum,N-1) - sumLow;
        ll tmp = numLow*v - sumLow + sumHigh - numHigh*v;
        if(R>tmp)
        {
          R = tmp;
          k = v;
        }
      }
      printf("%lld %lld\n",k, R + sumOfB);
    }
  }
}

int main() {
  //freopen("input.txt","r",stdin);
  solve();
  return 0;
}

