		int val = *(--st.end());
		s -= val;
		st.erase(--st.end());
		return val;
	}
	int pop_front() {
		int val = *st.begin();
		s -= val;
		st.erase(st.begin());
		return val;
	}
	int front() {
		return *st.begin();
	}
