// Binary Indexed Tree (0-indexed)
template<class T> struct BIT {
    int n;
    vector<T> bit;
    void init(int _n) { n = _n; bit.assign(n+1, 0); }

    // [0, i)
    T sum(int i) {
        assert(0 <= i && i <= n);
        T res = 0;
        while(i)  res += bit[i], i -= i & (-i);
        return res;
    }

    void add(int i, T x) {
        assert(0 <= i && i <= n-1);
        i++;
        while(i <= n)  bit[i] += x, i += i & (-i);
    }

    // sum(i) >= val なる最小のiを返す
    int lower_bound(T val) {
        int ok = n;
        int ng = 0;
        while(ok - ng > 1) {
            int m = (ok + ng) / 2;
            (sum(m) >= val ? ok : ng) = m;
        }
        return ok;
    }
};

