        if(t == 2)  qs.emplace_back(t, 0, 0);
    }

    map<lint, lint> rank;
    sort(as.begin(), as.end());
    as.erase(unique(as.begin(), as.end()), as.end());
    for(lint i = 0; i < as.size(); i++)  rank[as[i]] = i;

