        if (right.size() > left.size()) {
          int era = *right.begin();
          right.erase(right.find(era));
          left.insert(era);
          right_sum -= x;
          left_sum += x;
        }
      }
      long long med = *left.rbegin();
      val = (med * left.size() - left_sum) + (right_sum - med * right.size());
    }
    if (t == 2) {
      printf("%d %lld\n", *left.rbegin(), val + b);
    }
  }
  return 0;
}

