            else if(n%2==0 && a<(*mid).first){
                // a1 a2 a3 からanの追加
                // a a1 a2 a3 mid=a2→a1の場合とか
                f+=abs((*mid).first-a);
                --mid;
                // auto itr = se.find(mid);
                // ll mid_tmp = max(a,*(--itr));
                // f+=abs(mid-mid_tmp);
                // mid = mid_tmp;
            }
            else if(n%2==1 && a>=(*mid).first){
                f+=abs((*mid).first-a);
                // auto itr = se.find(mid);
                // ll mid_tmp = max(a,*(++itr));
                auto mid_tmp = mid;
                mid_tmp++;
                f+=((*mid).first-(*mid_tmp).first);
                mid = mid_tmp;
            }
            else{f+=abs((*mid).first-a);}
        }
        else{
            ans.emplace_back((*mid).first,f+sumB);
        }
    }

    for(auto a:ans) cout << a.first << " " << a.second << "\n";
    return 0;
}

