template <typename T>
struct bit {
    vector<T> a;
    function<T(T,T)> bin_op;
    const T init;
    explicit bit(int n, function<T(T,T)> bin_op, T init):bin_op(bin_op), init(init) {
        a.assign(n + 1, init);
    }

    T prefix(T x) {
        auto res = init;
        while (x) {
            res = bin_op(a[x], res);
            x -= x & -x;
        }
        return res;
    }
    void modify(int x, T v) {
        while (x < (int)a.size()) {
            a[x] = bin_op(a[x], v);
            x += x & -x;
        }
    }
    void clear(){
        fill(a.begin(), a.end(), init);
    }
};

template <typename T>
struct r_bit {
    vector<T> a;
    function<T(T,T)> bin_op;
    const T init;
    explicit r_bit(int n, function<T(T,T)> bin_op, T init):bin_op(move(bin_op)), init(init) {
        a.ssign(n + 1, init);
    }
    T suffix(int x) {
        T res = init;
        while (x < SZ(a)) {
            res = bin_op(res, a[x]);
            x += x & -x;
        }
        return res;
    }
    void modify(int x, T v) {
        while (x > 0) {
            a[x] = bin_op(a[x], v);
            x -= x & -x;
        }
    }
    void clear(){
        fill(a.begin(), a.end(), init);
    }
};

vi get_prime(int n) {
    vi minp((ul)n + 1), p;
    for (int i = 2; i <= n; i++) {
        if (!minp[i]) {
            minp[i] = i;
            p.pb(i);
        }
        FOR(x, p) {
            if (x <= minp[i] && x * i <= n)
                minp[x * i] = x;
            else break;
        }
    }
    return p;
}

