int main(){
  int Q;
  cin >> Q;

  ll bsum = 0;
  multiset<ll> l, r;
  ll lsum = 0, rsum = 0;
  rep(i,Q){
    int x;
    cin >> x;
    if(x == 1){
      ll a, b;
      cin >> a >> b;

      bsum += b;
      l.insert(a);
      lsum += a;
      if(l.size()-r.size()>1){
        auto itr = --l.end();
        ll x = *itr;
        l.erase(itr);
        lsum -= x;
        r.insert(x);
        rsum += x;
      }
      while(true){
        if(r.size() == 0) break;
        auto itrl = --l.end();
        auto itrr = r.begin();
        ll x = *itrl;
        ll y = *itrr;
        if(x <= y) break;
        l.erase(itrl);
        lsum -= x;
        r.erase(itrr);
        rsum -= y;
        l.insert(y);
        lsum += y;
        r.insert(x);
        rsum += x;
      }
    }else{
      if(l.size() == 0){
        cout << 0 << endl;
      }else{
        auto itr = --l.end();
        ll x = *itr;

        ll N = l.size();
        ll M = r.size();
