multiset<long long> A, B;
long long bs, as, q, sz;

void lax() {
	while (A.size() > (sz + 1) / 2) {
		multiset<long long>::iterator it = A.end();
		it--;
		as += 2 * (*it);
		B.insert(*it);
		A.erase(*it);
	}
	while (!B.empty()) {
		multiset<long long>::iterator it = A.end();
		it--;
		if (*it > *B.begin()) {
			int a = *it, b = *B.begin();
			A.erase(it);
			B.erase(B.begin());
			A.insert(b);
			B.insert(a);
		}
		else
			break;
	}
}
long long geten() {
	multiset<long long>::iterator it = A.end();
	it--;
	return *it;
}

