	return *(maxset.begin());
}

inline int deletemax(int k)
{
	--maxsz;
	auto it=maxset.find(k);
	assert(it!=maxset.end());
	maxset.erase(it);
	maxsum-=k;
}

inline int deletemin(int k)
{
	--minsz;
	auto it=minset.find(k);
	assert(it!=minset.end());
	minset.erase(it);
	minsum-=k;
}

void rearrange()
{
	if(minsz<maxsz)
	{
		int k = extractmax();
		insertmin(k);
	}
	else if(minsz-maxsz <= 1) 
		return;
	else
	{
		int k=extractmin();
		insertmax(k);
	}
}

void insert(int k)
{
	if(k>median) insertmax(k);
	else insertmin(k);
	rearrange();
	median = mintop();
}

