template<typename T> void push_val(T& pq, long long& sum, long long val)
{
  if (pq.empty()) {
    pq.push(val);
    return;
  }
  long long old_top = pq.top();
  pq.push(val);
  if (old_top == pq.top()) {
    sum += abs(old_top - val);
  } else {
    sum += abs(old_top - val) * (pq.size() - 1);
  }
}

template <typename T> long long pop_val(T& pq, long long& sum)
{
  long long old_top = pq.top();
  pq.pop();
  sum -= abs(old_top - pq.top()) * pq.size();
  return old_top;
}

