          push_val(smaller_half, smaller_sum, old_top);
        } else {
          push_val(smaller_half, smaller_sum, a);
        }
      } else {
        if (smaller_half.top() <= a) {
          push_val(larger_half, larger_sum, a);
        } else {
          long long old_top = pop_val(smaller_half, smaller_sum);
          push_val(smaller_half, smaller_sum, a);
          push_val(larger_half, larger_sum, old_top);
        }
      }
    } else {
      long long x = smaller_half.top();
      long long fx;
      if (larger_half.empty()) {
        fx = 0;
      } else {
        fx = smaller_sum + larger_sum + abs(x-larger_half.top()) * larger_half.size();
      }
      std::cout << x << ' ' << fx+bsum << '\n';
    }
  }
  return 0;
}

