			else {
				auto it = std::prev(map.lower_bound(now));
				if (it == map.end()) continue;
				int to = it->first;
				int tlow = low;
				tlow += (to - now) * bit.sum(map[to] + 1);
				tlow -= (to - now) * bit.sum(map[to] + 1, sz);
				if (low >= tlow) {
					now = to;
					low = tlow;
				}
			}
		}
