int main()
{
	int Q;
	std::priority_queue<long, std::vector<long>, std::less<long>> L; // 中央値より小さい a_i
	std::priority_queue<long, std::vector<long>, std::greater<long>> R; // 中央値より大きい a_i;

	std::cin >> Q;
	std::stringstream ss;

	long bsum = 0;
	long lsum = 0;
	long rsum = 0;
	for (int i = 0; i < Q; ++i) {
		int qtype;
		std::cin >> qtype;
		if (qtype == 1) {
			// update
			long a, b;
			std::cin >> a >> b;
			bsum += b;

			if (L.empty()) {
//std::cout << ":case 1\n";
				L.push(a);
			} else if (R.empty()) {
//std::cout << ":case 2\n";
				if (L.top() > a) {
					R.push(L.top());
					L.pop();
					L.push(a);
				} else {
					R.push(a);
				}
				rsum = R.top() - L.top();
			} else if (L.size() == R.size()) {
				if (L.top() > a) {
//std::cout << ":case 3c\n";
					lsum += (L.top() - a);
					L.push(a);
				} else if (R.top() > a){
//std::cout << ":case 3a\n";
					lsum += L.size() * (a - L.top());
					rsum -= (a - L.top()) * R.size();
					L.push(a);
				} else {
//std::cout << ":case 3b\n";
					rsum -= (R.top() - L.top());
					long x = R.top();
					R.pop();

					lsum += L.size() * (x - L.top());
					rsum -= (x - L.top()) * R.size();
					L.push(x);

					rsum += (a - L.top());
					R.push(a);
				}
			} else {
				if (L.top() > a) {
//std::cout << ":case 4a\n";
					long x = L.top();
					L.pop();
					lsum -= L.size() * (x - L.top());
					rsum += (x - L.top()) * R.size();

					lsum += (x - L.top());
					R.push(x);

					lsum += L.size() * (a - L.top());
					rsum -= (a - L.top()) * R.size();
					L.push(a);
				} else {
//std::cout << ":case 4b\n";
					rsum += (a - L.top());
					R.push(a);
				}
			}
		} else {
			ss << L.top() << " " << (lsum + rsum + bsum) << "\n";
		}
	}

	std::cout << ss.str();
}

