						if (a > R.top()) {
							p = R.top();
							r -= p;
							R.push(a);
							r += a;
						} else {
							p = a;
						}
					}
				} else if (L.top() >= a) {
					L.push(a);
					l += a;
				} else {
					L.push(p);
					l += p;
					p = R.top();
					R.pop();
					r -= p;
					R.push(a);
					r -= a;
				}
			} else {
				if (R.size() == 0 || R.top() <= a) {
					if (p >= a) {
						R.push(a);
						r+= a;
					} else {
						R.push(p);
						r += a;
						if (a > L.top()) {
							p = L.top();
							l -= p;
							L.push(a);
							l += a;
						} else {
							p = a;
						}
					}
					R.push(a);
					r += a;
				} else {
					R.push(p);
					r += p;
					p = L.top();
					L.pop();
					l -= p;
					L.push(a);
					l -= a;
				}
			}
		} else {
			cout << p << " " << sum + r - l + ((int)L.size() * p) - ((int)R.size() * p) << endl;
		}
	}
