    res += b;
    if(i==0) {
      mid = a;
      continue;
    }
    if(mid <= a) {
      _right.push(a);
      res += a-mid;
    } else {
      _left.push(a);
      res += mid-a;
    }
    if (SZ(_left)+2 == SZ(_right)) {
      LL next_mid = _right.top();
      LL diff = next_mid - mid;

      res -= diff*SZ(_right);
      _right.pop();

      _left.push(mid);
      res += diff*SZ(_left);

      mid = next_mid;
    } else if (SZ(_left) > SZ(_right)) {
      LL next_mid = _left.top();
      LL diff = mid - next_mid;

      res -= diff*SZ(_left);
      _left.pop();

      _right.push(mid);
      res += diff*SZ(_right);

      mid = next_mid;
    }
  }
}

