#define all(x) x.begin(),x.end()

#include <vector>

namespace niu {

  /* 
   *
   * ---- Segment Tree ----
   *
   * Segment Tree can do the following operation
   *  - accumulate the elements in any range of array in time O(logN)
   *  - update the value of element in time O(logN)
   * 
   * ====> template argments <====
   * 
   * Monoid
   *  required -> 
   *   + static Monoid::operation(Monoid, Monoid) -> Monoid
   *   + static Monoid::identity()                -> Monoid
   *
   * ====> member types <====
   *
   *  + size_type       | std::size_t
   *  + value_type      | Monoid
   *  + const_reference | ontainer_type::const_reference
   *
   * ====> member functions <====
   *
   *  * N = the number of elements
   *
   *  + update(const size_type idx, value_type val)
   *   - change the value of the idx-th elements to "val"
   *   - in time O(logN)
   *  + at(const size_type idx)
   *   - access the idx-th element
   *   - in time O(1)
   *  + accumulate(size_type left, size_type right)
   *   - accumulate the elements in [left, right)
   *   - in time O(logN)
   *
   */

  template<class Monoid>
  class segment_tree {

  public:
    using value_type = Monoid;

  private:
    using container_type = std::vector<value_type>;

  public:
    using const_reference = typename container_type::const_reference;
    using size_type = std::size_t;

  protected: 

    container_type node;
    size_type size_;

    static size_type pow_bound(const size_type size) {
      size_type p = 1;
      while(p < size) p <<= 1;
      return p;
    }

    void fix(const size_type idx) {
      node[idx] = value_type::operation(node[idx << 1], node[idx << 1 | 1]);
    }

  public:

    segment_tree(): node() {}
    segment_tree(const size_type size): size_(pow_bound(size)), node(pow_bound(size) << 1, value_type::identity()) {}

    void update(size_type idx, value_type val) {
      assert(idx < size_);
      node[idx += size_] = std::move(val);
      while(idx >>= 1) fix(idx);
    }

    const_reference at(const size_type idx) const {
      assert(idx < size_);
      return node[idx + size_];
    }

    value_type accumulate(size_type left, size_type right) const {
      assert(left <= node.size());
      assert(right <= node.size());
      value_type lf = value_type::identity();
      value_type rf = value_type::identity();
      for(left += size_, right += size_; left < right; left >>= 1, right >>= 1) {
        if(left & 1) lf = value_type::operation(std::move(lf), node[left++]);
        if(right & 1) rf = value_type::operation(node[right - 1], std::move(rf));
      }
      return value_type::operation(std::move(lf), std::move(rf));
    }

    size_type search(i64 s, size_type k = 1, size_type l = 0, size_type r = 0) {
      if(r == 0) r = size_;
      if(l + 1 == r) return l;
      if(node[k << 1].val <= s) {
        return search(s - node[k << 1].val, (k << 1) + 1, (l + r) / 2, r);
      }
      else 
        return search(s, (k << 1), l, (l + r) / 2);
    }
  };

}


