  scan(q);
  ll minval = 0;
  multiset<int> left, right;
  rep (i, q) {
    int t;
    scan(t);
    if (t == 1) {
      int a, b;
      scan(a, b);
      if (left.size() == 0) {
        left.insert(a);
        minval = b;
      } else if (left.size() == right.size()) {
        auto rp = right.begin();
        int vrp = *rp;
        if (vrp < a) {
          minval += b + abs(a - vrp);
          left.insert(vrp);
          right.erase(rp);
          right.insert(a);
        } else {
          auto lp = left.end();
          --lp;
          int vlp = *lp;
          minval += b + abs(vlp - a);
          left.insert(a);
        }
      } else {
        auto lp = left.end();
        --lp;
        int vlp = *lp;
        if (vlp <= a) {
          minval += b + abs(a - vlp);
          right.insert(a);
        } else {
          minval += b + abs(vlp - a);
          right.insert(vlp);
          left.erase(lp);
          left.insert(a);
        }
      }
    } else {
      auto lp = left.end();
      --lp;
      int vlp = *lp;
      printf("%d %lld\n", vlp, minval);
    }
  }

