long long N;
multiset < long long > st;
multiset < long long >::iterator p;

int main(){
    scanf("%lld", &N);
    long long sum = 0, l = 0, r = 0, ans = 0;
    while(N--){
        long long num; scanf("%lld", &num);
        if(num == 1){
            long long A, B; scanf("%lld %lld", &A, &B);
            sum += B;
            if(!(long long)st.size()){
                st.insert(A); p = st.begin();
            }
            else{
                st.insert(A); ans += abs(A - *p);
                auto q = p;
                if(A >= *p){
                    ++r;
                    if(r >= l + 2){
                        ++q;
                        ans += (*q - *p) * (l + 1 - r);
                        --r, ++l; ++p;
                    }
                }
                else{
                    ++l;
                    if(l > r){
                        --q;
                        ans += (*p - *q) * (r + 1 - l);
                        --l, ++r, --p;
                    }
                }
            }
        }
        else{
            printf("%lld %lld\n", *p, ans + sum);
        }
    }
    return 0;
}

