                setNodeL.insert(min(sqLMax, sqInput_a));
                setNodeR.insert(max(sqLMax, sqInput_a));

                sqOffsetSum += (abs(sqLMax - sqInput_a) + sqInput_b);
            } else {
                auto it_l = setNodeL.end();
                it_l--;
                SQWORD sqLMax = *it_l;
                auto it_r = setNodeR.begin();
                SQWORD sqRMin = *it_r;

                if (setNodeR.size() < setNodeL.size()) {
                    auto it_l = setNodeL.end();
                    it_l--;
                    SQWORD sqLMax = *it_l;
                    setNodeL.erase(it_l);
                    setNodeL.insert(min(sqInput_a, sqLMax));
                    setNodeR.insert(max(sqInput_a, sqLMax));
                    sqOffsetSum += (abs(sqInput_a - sqLMax) + sqInput_b);

                } else {
                    it_l = setNodeL.end();
                    it_l--;
                    it_r = setNodeR.begin();

                    SQWORD sqAddOffset;
                    if (sqInput_a <= *it_l) {
                        sqAddOffset = 0;
                    } else if (*it_r <= sqInput_a) {
                        sqAddOffset = sqInput_a - *it_r;
                    } else {
                        sqAddOffset = *it_r - *it_l;
                    }

                    SQWORD sqRMin = *(setNodeR.begin());
                    setNodeR.erase(setNodeR.begin());
                    setNodeL.insert(min(sqInput_a, sqRMin));
                    setNodeR.insert(max(sqInput_a, sqRMin));

                    sqOffsetSum += (sqAddOffset + sqInput_b);
                }


            }
        } else {
            /* calculate val */
            auto it_l = setNodeL.end();
            it_l--;
            SQWORD sqLMax = *it_l;


            printf("%lld %lld\n", sqLMax, sqOffsetSum);
        }
    }


    return 0;
}

