// Returns a const char* representation of a container, such as a vector.
// Works for a container whose iterator has begin() and end()
string toString(auto v) {
  stringstream ss;
  ss << "[";
  for (auto it = v.begin(); it != v.end(); it++) {
    if (it != v.begin())  ss << ", ";
    ss << *it;
  }
  ss << "]";
  return ss.str();
}

vector<ll> toVector(auto q)
{
  vector<ll> v;
  while (!q.empty()) {
    v.push_back(q.top());
    q.pop();
  }
  return v;
}


