                if(tree.size() % 2 == 1){
                    ll t = tree[c + 1] - tree[c];
                    l += c * t;
                    r -= (tree.size() - c - 1) * t;
                }
                else{
                    c--;
                }
            }
            else if(idx > c){
                r -= abs(tree[c] - a);
                tree.erase(idx);
                if(tree.size() % 2 == 0){
                    ll t = tree[c] - tree[c - 1];
                    l -= (c + 1) * t;
                    r += (tree.size() - c) * t;
                    c--;
                }
            }
            else{
                if(tree.size() % 2 <= 2){
                    tree.erase(idx);
                    l = r = c = 0;
                    continue;
                }
                if(tree.size() % 2 == 1){
                    ll t = tree[c] - tree[c - 1];
                    l -= c * t;
                    r += (tree.size() - 1 - c) * t;
                    c--;

                    tree.erase(idx);
                }
                else{
                    ll t = tree[c + 1] - tree[c];
                    l += c * t;
                    r -= (tree.size() - 1 - c) * t;
                    c++;

                    tree.erase(idx);
                }
            }
        }
        else{
            ans.push_back({tree[(tree.size() - 1) / 2], l + r + b});
        }
    }

    for(int i = (int)ans.size() - 1; i >= 0; i--){
        printf("%lld %lld\n", ans[i].first, ans[i].second);
    }

    // tree.dump();
}

