    ans += sumfenw[i];
  }
  return ans;
}

int sumsum(int i, int j) {
  if (i > j) return 0;
  return sumsum(j) - (i > 1 ? sumsum(i - 1) : 0);
}

int findmid(int x) {
  int l = 1, r = N - 1, ans;
  while (l <= r) {
    int mid = (l + r) >> 1;
    if (cntsum(mid) >= x) {
      ans = mid;
      r = mid - 1;
    } else {
      l = mid + 1;
    }
  }
  return ans;
}

int go(int el, int pos) {
  int ans = 0;
  ans += el * cntsum(1, pos) - sumsum(1, pos);
  ans += sumsum(pos, N - 1) - el * cntsum(pos, N - 1);
  return ans;
}

