                    sum_latter += tmp;
                } else { // そのままlatterに入れる
                    latter.push(a);

                    sum_latter += a;
                }
            } else { // firstに埋める
                if (sz(first) == 0) { // ないとbad access
                    first.push(a);

                    sum_first += a;
                } else if (a > latter.top()) {
                    int tmp = latter.top();
                    first.push(tmp);
                    latter.pop();
                    latter.push(a);

                    sum_first += tmp;
                    sum_latter += a - tmp;
                } else {
                    first.push(a);

                    sum_first += a;
                }
            }
        }
    }
}

