int type, a, b, Q;
multiset<int, greater<int> > maxh;
multiset<int, less<int> > minh;

long long maxh_sum = 0, minh_sum = 0;
long long B = 0;

void update_ds() {
  B += b;
  int maxh_sz = maxh.size();
  int minh_sz = minh.size();

  if(maxh_sz == 0) {
    maxh.insert(a);
    maxh_sum += a;
  } else if(maxh_sz == minh_sz) {
    auto it = maxh.begin();
    if(a <= *it) {
      maxh.insert(a);
      maxh_sum += a;
    } else {
      minh.insert(a);
      minh_sum += a;
      auto it = minh.begin();
      minh_sum -= *it;
      maxh_sum += *it;
      maxh.insert(*it);
      minh.erase(it);
    }
  } else {
    auto it = maxh.begin();
    if(a >= *it) {
      minh.insert(a);
      minh_sum += a;
    } else {
      maxh.insert(a);
      maxh_sum += a;
      auto it = maxh.begin();
      maxh_sum -= *it;
      minh_sum += *it;
      minh.insert(*it);
      maxh.erase(it);
    }
  }
}

long long find_answer() {
  long long maxh_sz = maxh.size();
  long long minh_sz = minh.size();
  long long val = *maxh.begin();
