multiset<int> ms;

int get_next(int x) {
	multiset<int>::iterator iter = ms.find(x);
	iter++;
	return *iter;
}

int get_prev(int x) {
	multiset<int>::iterator iter = ms.find(x);
	iter--;
	return *iter;
}

int main() {
	//freopen("input.txt", "r", stdin);
	//freopen("output.txt", "w", stdout);

	int q;
	scanf("%d", &q);

	min_val = 0;
	long long last_mx = -LL_INF, last_mn = LL_INF;
	int was = 0;
	int only_one = 1;
	long long XX = -LL_INF;

	for (int i = 0; i < q; i++) {
		int tp;
		scanf("%d", &tp);
		if (tp == 1) {
			int a, b;
			scanf("%d%d", &a, &b);
			a = -a;

			min_val += b;
			long long x_root = -a;

			ms.insert(x_root);
			if (!was) {
				xx1 = xx2 = x_root;
				was = 1;
				XX = x_root;
				continue;
			}

			if (x_root > xx2) {
				min_val += x_root - xx2;
				if (xx1 != xx2) xx1 = xx2;
				else {
					if (last_mx < -LL_INF / 2 || only_one)
						xx2 = x_root;
					else
						xx2 = get_next(xx2);
				}
			}
			else if (x_root < xx1) {
				min_val += xx1 - x_root;
				if (xx2 != xx1) xx2 = xx1;
				else {
					if (last_mn > LL_INF / 2 || only_one)
						xx1 = x_root;
					else
						xx1 = get_prev(xx1);
				}
			}
			else {
				xx1 = xx2 = x_root;
			}

			if (x_root >= 0) last_mx = max(last_mx, x_root);
			if (x_root <= 0) last_mn = min(last_mn, x_root);

			was = 1;
			if (XX != x_root) only_one = 0;
		}
		else {
			print_ans();
		}
	}
	return 0;
}

