#include <bits/stdc++.h>

using namespace std;
using ll = long long;

template <typename T>
struct BIT {
	int N;
	vector<T> data;

	BIT(int n) {
		N = n;
		data.assign(N, 0);
	}

	T sum(int idx) {
		T ret = 0;
		for (int i = idx; i > 0; i -= i & -i) { ret += data[i]; }
		return ret;
	}
	T sum(int l, int r) {
		if (l > r) { return 0; }
		return sum(r) - sum(l - 1);
	}

	void add(int idx, T x) {
		for (int i = idx; i <= N; i += i & -i) { data[i] += x; }
	}

	// data[1]+...data[m] >= x となる最小のm 
	int lower_bound(T x) {
		int ret = 0;
		int k = 1;
		while (2*k <= N) { k <<= 1; }
		for ( ; k > 0; k /= 2) {
			if (ret + k <= N && data[ret + k] < x) {
				x -= data[ret + k];
				ret += k;
			}
		}
		return ret + 1;
	}
};

