	vector<ll> a(Q), b(Q);
	vector<ll> unzip;
	for (int i = 0; i < Q; ++i) {
		cin >> q[i];
		if (q[i] == 1) {
			cin >> a[i] >> b[i];
			unzip.push_back(a[i]);
		}
	}

	unzip.push_back(-INF);
	sort(unzip.begin(), unzip.end());
	unzip.erase(unique(unzip.begin(), unzip.end()), unzip.end());
	map<ll, int> zip;
	int sz = unzip.size();
	for (int i = 0; i < sz; ++i) { zip[unzip[i]] = i; }

	BIT<ll> bitnum(sz);
	BIT<ll> bitsum(sz);
	ll sumB = 0;
	int cnt = 0;
	for (int i = 0; i < Q; ++i) {
		if (q[i] == 1) {
			sumB += b[i];
			bitnum.add(zip[a[i]], 1);
			bitsum.add(zip[a[i]], a[i]);
			++cnt;
		} else {
			int m = bitnum.lower_bound((cnt + 1) / 2);
			ll x = unzip[m];
			ll f = sumB;
			f += (x*bitnum.sum(m) - bitsum.sum(m));
			f += (bitsum.sum(m, sz - 1) - x*bitnum.sum(m, sz - 1));
			cout << x << " " << f << endl;
		}
	}

	return 0;
}

