template <typename T>
struct DynamicMedian {
  // size: q1 >= q2
  multiset<T> q1, q2;
  DynamicMedian() {}
  void move_l() {
    T tmp = *q2.begin();
    q2.erase(q2.begin());
    q1.emplace(tmp);
  }
  void move_r() {
    T tmp = *q1.rbegin();
    q1.erase(--q1.end());
    q2.emplace(tmp);
  }
  void add(T x) {
    if (q1.size() == q2.size()) {
      q2.emplace(x);
      move_l();
    } else {
      q1.emplace(x);
      move_r();
    }
  }
  bool del(T x) {
    bool f1 = q1.find(x) != q1.end();
    bool f2 = q2.find(x) != q2.end();
    if (f1)
      q1.erase(q1.find(x));
    else if (f2)
      q2.erase(q2.find(x));
    else
      return false;
    if (q1.size() == q2.size() + 2)
      move_r();
    else if (q1.size() + 1 == q2.size())
      move_l();
    return true;
  }
  // for even size
  // mode = 0: min
  // mode = 1: mean
  // mode = 2: max
  T median(int mode = 0) {
    assert(0 <= mode && mode <= 2);
    assert(q1.size());
    if (q1.size() == q2.size()) {
      switch(mode) {
      case 0:
        return *q1.rbegin();
      case 1:
        return (*q1.rbegin() + *q2.begin()) / 2;
      case 2:
        return *q2.begin();
      default:
        return -1;
      }
    } else {
      return *q1.rbegin();
    }
  }
};

