		else {
			s.insert(val);
			if (val < *mid) {
				lsum += val;
				if ((s.size() & 1 )== 0) {
					rsum += *mid;
					--mid;
					lsum -= *mid;
				}
			}
			else {
				rsum += val;
				if ((s.size() & 1 )== 1) {
					lsum += *mid;
					++mid;
					rsum -= *mid;
				}
			}
