	while (q--) {
		int t;
		scanf("%d", &t);
		if (t == 1) {
			int a, b;
			scanf("%d %d", &a, &b);
			sumB += b;
			sumA += a;
			++cntA;
			update(root, a);
		} else {
			int idx = 0;
			long long mn = 1e18;
			for (int i = sumA / cntA; i <= sumA / cntA + 1; ++i) {
				auto a = query(root, i + 1, OO);

				long long cur = 0;
				if (i > 0) {
					cur += a.second - 1LL * a.first * i;
					a = query(root, -OO, i - 1);
					cur += -a.second - 1LL * a.first * -i;
				} else {
					cur += a.second + 1LL * a.first * i;
					a = query(root, -OO, i - 1);
					cur += -a.second + 1LL * a.first * -i;
				}
				if (cur < mn) {
					mn = cur;
					idx = i;
				}
			}
