struct _solver {
  long long ls, rs, bs;
  priority_queue<int, vector<int>, less<int>> lhs;
  priority_queue<int, vector<int>, greater<int>> rhs;

  void clear() {
    ls = rs = bs = 0;
    while (!lhs.empty()) lhs.pop();
    while (!rhs.empty()) rhs.pop();
  }

  void update(int a, int b) {
    bs += b;
    lhs.push(a);
    ls += a;
    if (lhs.size() > rhs.size() + 1) {
      int k = lhs.top();
      ls -= k;
      rs += k;
      lhs.pop();
      rhs.push(k);
    }
  }

  pair<long long, long long> query(long long k) {
    long long l = k * (long long)lhs.size() - ls;
    long long r = rs - k * (long long)rhs.size();
    return mp(k, l + r + bs);
  }

  pair<long long, long long> query() {
    auto ans = query(lhs.top());
    return ans;
    if (rhs.size() == 0) {
      return ans;
    } else {
      auto other = query(rhs.top());
      if (other.se < ans.se) {
        return other;
      } else {
        return ans;
      }
    }
  }
} solver;

int q, a, b, c;

int main(int argc, char const *argv[]) {
  // freopen("F.txt", "r", stdin);

  while (cin >> q) {
    solver.clear();
    range(_, 0, q, 1) {
      cin >> c;
      if (c == 1) {
        cin >> a >> b;
        solver.update(a, b);
      } else {
        auto ans = solver.query();
        cout << ans.fi << " " << ans.se << endl;
      }
    }
  }
  return 0;
}

