void solve()
{
	ll Q;
	cin >> Q;

	std::multiset<ll> aSet;
	auto it_min_a = aSet.begin();
	ll min_a;
	ll min_a_val = 0;
	ll bSum = 0;

	REP(qIdx, Q){
		ll qKind;
		cin >> qKind;

		/////////更新クエリ時
		if (qKind == 1){
			ll a, b;
			cin >> a >> b;

			//////////// 1番目のクエリの時の処理
			if (qIdx == 0){
				aSet.insert(a);
				min_a = a;
				min_a_val = 0;
				it_min_a = aSet.begin();
				bSum += b;
				continue;
			}
			///////////// 2番目以降の時の処理
			bSum += b;
			min_a_val += abs(a-min_a);
			aSet.insert(a);

			//元偶数＆右追加の時
			if ((ll)aSet.size() % 2 == 1 && min_a<=a){
				it_min_a++;
				ll oldmin_a = min_a;
				min_a = *it_min_a;
				min_a_val -= abs(min_a - oldmin_a);
			}
			//元奇数＆左追加の時
			else if ((ll)aSet.size() % 2 == 0 && a<min_a){
				it_min_a--;
				min_a = *it_min_a;
			}
		}
		/////////求値クエリ時
		else{
			cout << min_a << ' ' << min_a_val + bSum << '\n';
		}
	}
}



