struct RSQ{
  int n=(1<<15),data[(1<<16)];
  RSQ(){
    memset(data,0,sizeof(data));
  }

  // 0 index
  void add(int i,int v){
    i++;
    while(i<=n){
      data[i]+=v;
      i+=i&-i;
    }
  }
  int sum(int i){
    int res=0;
    while(i>0){
      res+=data[i];
      i-=i&-i;
    }
    return res;
  }

  //[a,b) 0indexed
  int sum(int x,int y){
    return sum(y)-sum(x);
  }

  int K_number(int k){
    int l = 0,r = (1<<16)+1;
    while( l < r ) {
      int mid = (l+r) / 2;
      if( sum( 0 , mid+1 ) >= k ) r = mid;
      else l = mid+1;
    }
    cout<<l<<' '<<r<<endl;
    return l;
  }

};

