    for(int i=0;i<Q;i++){
        cin >> qs[i].i;
        if(qs[i].i == 1){
            cin >> qs[i].a >> qs[i].b;
            st.insert(qs[i].a);
        }
    }
    vector<ll> pd(st.size());
    int idx=0;
    for(auto&& v : st){
        pd[idx++] = v;
    }
    //debug(pd);


    BIT bit(pd.size());
    BIT sum(pd.size());
    ll bs = 0;
    int n=0;
    rep(i,Q){
        if(qs[i].i == 1){
            bs += qs[i].b;
            int idx = lower_bound(pd.begin(),pd.end(),qs[i].a) - pd.begin();
            assert(idx>=0);
            bit.add(idx,1);
            sum.add(idx,pd[idx]);
            n++;
        }else if(qs[i].i==2){
            const int idx = bit.lower_bound((n+1)/2)-1;
            assert(idx>=0);
            const ll value = pd[idx];
            ll left = sum.sum(idx+1);
            ll lc = bit.sum(idx+1);
            ll right = sum.sum(pd.size()) - left;
            ll rc = bit.sum(pd.size()) - lc;    // RE
            cout << value << " " << lc * value - left + right - rc * value + bs << endl;
        }
    }
}

