template<class Type>
Type solve(Type res = Type()){
    ll asum = 0,bsum = 0;
    using Item = tuple<ll,ll,ll>;
    int Q; cin >> Q;
    vector<Item> Qs(Q);
    for(int i = 0; i < Q;i++){
        ll mode; cin >> mode;
        if(mode == 1){
            ll a,b; cin >> a >> b;
            Qs[i] = Item(mode,a,b);
        }else{
            Qs[i] = Item(mode,-1,-1);
        }
    }

    priority_queue<ll> l;
    priority_queue<ll,vector<ll>,greater<ll>> r;

    ll lsum = 0, rsum = 0;
    for(int q = 0; q < Q; q++){
        ll mode,a,b; tie(mode,a,b) = Qs[q];
        if(q == 0){
            bsum += b;
            l.push(a);
            lsum = a;
            continue;
        }
        if(mode == 1){
            bsum += b;


            if(a <= l.top()){
                l.push(a);
                lsum += a;
            }else{
                r.push(a);
                rsum += a;
            }

            if(!l.empty() && l.size() > r.size() + 1){
                r.push(l.top());
                lsum -= l.top(); rsum += l.top();
                l.pop();
            }else if(!r.empty() && r.size() > l.size()){
                l.push(r.top());
                lsum += r.top(); rsum -= r.top();
                r.pop();
            }
        }else{
            if(l.size() == r.size() + 1){
                cout << l.top() << " " << l.top()-lsum + rsum + bsum << endl;
            }else{
                cout << l.top() << " " << -lsum + rsum + bsum << endl;
            }
        }
    }
    return res;
}
