void solve() {
	ll Q;
	cin>>Q;

	auto F = [&](ll x,ll y){ return x+y; };
	OrderedMultiSet<ll,ll,decltype(F)> rbst(Q, F, 0);
	using Node = OrderedMultiSet<ll,ll,decltype(F)>::Node;
	Node* node = rbst.makeset();

	vector<pair<ll,ll>> anslist;
	ll bsum=0;
	rep(_,Q){
		ll q;
		cin>>q;
		if(q==1){
			ll a,b;
			cin>>a>>b;
			bsum+=b;
			rbst.insert_key(node, a);
		}else{
			pair<ll,ll> ans;
			ll size=rbst.size(node);
			ll pos=(size-1)/2;
			ans.first=rbst.query(node, pos, pos+1);

			ll t=rbst.query(node, 0, pos);
			ll tt=ans.first*pos-t;
			ll s=rbst.query(node, pos+1, size);
			ll ss=s-ans.first*(size-(pos+1));
			ans.second=tt+ss+bsum;
			anslist.push_back(ans);
		}
	}
	rep(i,anslist.size())p(anslist[i].first, anslist[i].second);
}

signed main() {
	solve();
	return 0;
}

