  priority_queue<Int, vector<Int>, greater<Int>> LQ, RQ;
  priority_queue<Int> lq, rq;

  //LQ.push(0);
  //RQ.push(0);
  lq.push(0);
  rq.push(0);

  auto calcL =[&](BIT &bit){
    return LQ.top();
    Int L = 1, R = LENGTH;
    while(L + 1 < R){
      Int M = (L + R) / 2;
      bit.sum(M, M + 1) >= 0? (L = M):(R = M);
    };

    assert(L == LQ.top());
    return L;
  };

  auto calcR =[&](BIT &bit){
    return rq.top();
    Int L = 1, R = LENGTH;
    while(L + 1 < R){
      Int M = (L + R) / 2;
      bit.sum(M, M + 1) > 0? (L = M):(R = M);
    }
    assert(L == rq.top());
    return L;
  };

  auto updateL = [&](){
    auto &Q = LQ;
    auto &q = lq;
    while(Q.size() > q.size()){
      q.push(Q.top()), Q.pop();
    }

    while(Q.size() && q.size() && Q.top() < q.top()){
      Int a = Q.top(); Q.pop();
      Int b = q.top(); q.pop();
      Q.push(b);
      q.push(a);
    }
  };

  auto updateR = [&](){
    auto &Q = RQ;
    auto &q = rq;

    while(Q.size() >= q.size()){
      //pr(Q.size(), q.size());
      q.push(Q.top()), Q.pop();

    }

    while(Q.size() && q.size() && Q.top() < q.top()){
      Int a = Q.top(); Q.pop();
      Int b = q.top(); q.pop();
      Q.push(b);
      q.push(a);
    }
  };

  Int cntL = 0, cntR = 0;
  Int addL = 0, addR = 0;
  while(q--){
    Int cmd;
    cin>>cmd;
    if(cmd == 1){
      Int a, b;
      cin>>a>>b;
      ofset += abs(a) + b;
      if(a < 0){
	bitL.add(1, abs(a)+1, 2);
	addL--; //bitL.add(abs(a)+1, LENGTH, -1);
	addR--; //bitR.add(1, LENGTH, -1);


	LQ.push(abs(a));
	RQ.push(0);

	cntL++;
	cntR--;
      }
      else if(a > 0){
	bitR.add(1, abs(a)+1, 2);
	addR--;	//bitR.add(abs(a)+1, LENGTH, -1);
	addL--; //bitL.add(1, LENGTH, -1);

	RQ.push(abs(a));
	LQ.push(0);


	cntR++;
	cntL--;
      }
      else{
	addL--; //bitL.add(1, LENGTH, -1);
	addR--; //bitR.add(1, LENGTH, -1);

	RQ.push(0);
	LQ.push(0);


	cntL--;
	cntR--;
      }
    }
    else{

      if(addL) bitL.add(1, LENGTH, addL), addL = 0;
      if(addR) bitR.add(1, LENGTH, addR), addR = 0;
      updateL();
      updateR();

      Int ans = ofset;
      Int x = 0;

      if(cntL >= 0) {
	x = calcL(bitL);
	ans = ofset - bitL.sum(1, x+1);
	x *= -1;
      }
      else if(cntR > 0) {
	x = calcR(bitR);
	ans = ofset - bitR.sum(1, x+1);
      }

      if(ofset < ans) ans = ofset, x = 0;
      cout<<x<<" "<<ans<<endl;

    }
  }




  return 0;
}

