set<t2> lefts;
set<t2> rights;
ll left_sum = 0;
ll right_sum = 0;
ll bsum = 0;

void f(ll a)
{
        if (lefts.empty()) {
                lefts.insert(t2(-a, a));
        }

        else if (rights.empty()) {
                t2 b_t2 = *(lefts.begin());
                ll b = get<1>(b_t2);
                lefts.erase(lefts.begin());

                ll minval = min(a, b);
                ll maxval = max(a, b);
                lefts.insert(t2(-minval, minval));
                rights.insert(t2(maxval, maxval));
                right_sum = maxval - minval;
        }

        else if (lefts.size() == rights.size()) {
                t2 old_med_t2 = *(lefts.begin());
                ll old_med = get<1>(old_med_t2);
                t2 right_top_t2 = *(rights.begin());
                ll right_top = get<1>(right_top_t2);

                if (a < old_med) {
                        lefts.insert(t2(-a, a));
                        left_sum += (old_med - a);
                }
                if (old_med <= a && a <= right_top) {
                        lefts.insert(t2(-a, a));
                        left_sum += (lefts.size() - 1) * (a - old_med);
                        right_sum -= rights.size() * (a - old_med);
                }
                if (right_top < a) {
                        rights.erase(rights.begin());
                        rights.insert(t2(a, a));
                        lefts.insert(t2(-right_top, right_top));
                        left_sum += (lefts.size() - 1) * (right_top - old_med);
                        right_sum -= rights.size() * (right_top - old_med);
                        right_sum += (a - right_top);
                }
        }

        else {
                t2 old_med_t2 = *(lefts.begin());
                ll old_med = get<1>(old_med_t2);
                t2 right_top_t2 = *(rights.begin());
                ll right_top = get<1>(right_top_t2);

                if (a < old_med) {
                        lefts.erase(lefts.begin());
                        lefts.insert(t2(-a, a));
                        rights.insert(t2(old_med, old_med));
                        t2 new_med_t2 = *(lefts.begin());
                        ll new_med = get<1>(new_med_t2);
                        left_sum -= (lefts.size() - 1) * (old_med - new_med);
                        left_sum += (new_med - a);
                        right_sum += rights.size() * (old_med - new_med);
                }
                else if (old_med <= a) {
                        rights.insert(t2(a, a));
                        right_sum += (a - old_med);
                }

        }
}

