			++cnt;
		} else {
			int m = bitnum.lower_bound((cnt + 1) / 2);
			ll x = unzip[m];
			ll f = sumB;
			f += (x*bitnum.sum(m - 1) - bitsum.sum(m - 1));
			f += (bitsum.sum(m + 1, sz - 1) - x*bitnum.sum(m + 1, sz - 1));
			cout << x << " " << f << endl;
		}
	}

	return 0;
}

