class HeapTree
{
private:
	int data[1000000];
	int n;


public:
	HeapTree() : n(0) {}

	void push(int x) {
		int i = n++;

		while (i > 0) {
			int p = (i - 1) / 2;
			if (data[p] <= x) break;
			data[i] = data[p];
			i = p;
		}

		data[i] = x;
	}

};



