            if(x>q1.top()){
                q2.push(x);
            }else{
                q2.push(q1.top());
                q1.pop();
                q1.push(x);
            }
            dist+=abs(p-q1.top());
        }
        dist+=abs(x-q1.top());
    }
    T median(){
        return q1.top();
    }
