	priority_queue<long,vector<long>,greater<long>> pq1;
	priority_queue<long> pq2;
	int Q = rei()-1;
	rei();
	long f = rei();
	long t = f;
	long minv = rei();
	for(int i=0;i<Q;i++){
		int q = rei();
		if(q == 2){
			cout << f << " " << minv << "\n";
		}
		else{
			long a = rei();
			long b = rei();
			minv += b;
			if(a < f){
				pq1.push(t);
				pq2.push(a);
				t = f;
				minv += f-a;
				f = pq2.top();
				pq2.pop(); 
			}
			else if(a > t){
				pq1.push(a);
				pq2.push(f);
				f = t;
				minv += a-t;
				t = pq1.top();
				pq1.pop();
			}
			else{
				pq1.push(t);
				pq2.push(f);
				f = a;
				t = a;
			}
		}
	}
}
