ll bin_search(vector<ll>v1,ll num)
{
    ll size=v1.size();
    ll low=0,high=size-1;
    ll ans=high,mid;
    while(low<=high)
    {
        mid=(low+high)/2;
        if(v1[mid]>=num)
        {
            high=mid-1;
            ans=mid;
        }
        else
        {
            low=mid+1;
        }
    }
    return ans;
}

