            sum += a;
            B += b;
        } else {
            int n = rope.size();
            if (n & 1) {
                int mid = n / 2;
                long long M = rope[mid];
                long long large = rope.sum(mid);
                long long small = sum - large - M;
                cout << M << ' ' << M * mid - small + large - mid * M + B << '\n';
            } else {
                int mid = n / 2;
