long long A, B;
priority_queue<int>l;
priority_queue<int, vector<int>, greater<int>>r;

void update()
{
	B += b;
	if (l.empty())
		l.push(a);
	else if (a <= l.top())
	{
		A += l.top() - a;
		l.push(a);
	}
	else
	{
		A += a - l.top();
		r.push(a);
	}

	while (l.size() >= r.size() + 2)
	{
		r.push(l.top());
		l.pop();
		A -= 1ll * (r.top() - l.top())*(l.size() - r.size());
	}
	while (r.size() > l.size())
	{
		A -= 1ll * (l.top() - r.top())*(r.size() - l.size());
		l.push(r.top());
		r.pop();
	}

}

int query()
{
	return l.top();
}

