    }
  }

  // 圧縮
  sort(All(as));
  as.erase(unique(All(as)), as.end());
  map<int, int> mp;
  int sz = as.size();
  rep(i, 0, sz) mp[as[i]] = i; // 値に対応するindex(小さい方から何番目か)

  BIT<ll> bitnum(sz); // 何個かを管理するBIT
  BIT<ll> bitsum(sz); // 和を管理するBIT
  ll fix = 0; // 不変の部分
  int all = 0; // 何個追加されたか(つまりq = 1が何回か)
  rep(i, 0, Q) {
