#include <bits/stdc++.h>
using namespace std;

int Q;
long long sumL = 0, sumR = 0;
multiset <int> L, R;
long long addB;

void update(int x) {
    if(L.empty()) {
        sumL += x;
        L.insert(x);
        return;
    }
    int naxL = *(L.rbegin());

    if(x >= naxL) {
        R.insert(x);
        sumR += x;
    } else {
        L.insert(x);
        sumL += x;
    }

    if(L.size() + 1 < R.size()) {
        int val = *R.begin();
        L.insert(val);
        R.erase(R.find(val));
        sumL += val;
        sumR -= val;
    } else if(R.size() + 1 < L.size()) {
        int val = *L.rbegin();
        R.insert(val);
        L.erase(L.find(val));
        sumR += val;
        sumL -= val;
    }
}

void get() {
    int val;
    if(L.size() + 1 == R.size())
        val = *R.begin();
    else
        val = *L.rbegin();

    long long ans = addB + L.size() * 1LL * val - sumL + sumR - R.size() * 1LL * val;
    cout << val << " " << ans << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin >> Q;
    while(Q --> 0) {
        int type;
        cin >> type;
        if(type == 1) {
            int a, b;
            cin >> a >> b;
            addB += b;
            update(a);
        } else {
            get();
        }
    }
}

