// |x - a|の総和を最小化
// 中央値ゲー
// setで前後半に分けて管理
// bは適当に合計取って終わり

#include <iostream>
#include <algorithm>
#include <set>
using namespace std;
using ll = long long;

multiset<ll> left_hirf;
multiset<ll> right_hirf;
ll left_sum;
ll right_sum;
ll b_sum;

ll q;
ll com, a, b;

ll mid(void);
void insert(ll x);

int main()
{
    cin >> q;
    for (int i = 0; i < q; i++) {
        cin >> com;

        if (com == 1) {
            cin >> a >> b;

            b_sum += b;

            insert(a);
        }
        else {
            ll ans = b_sum;
            ll x = mid();

            ans += x * left_hirf.size() - left_sum;
            ans += -x * right_hirf.size() + right_sum;

            cout << mid() << ' ' << ans << endl;
        }
    }

    return 0;
}

ll mid(void)
{
    return *left_hirf.rbegin();
}

void insert(ll x)
{
    if (left_hirf.empty()) {
        left_sum += x;
        left_hirf.insert(x);
        return;
    }

    if (x <= mid()) {
        left_sum += x;
        left_hirf.insert(x);
    }
    else {
        right_sum += x;
        right_hirf.insert(x);
    }

    if (right_hirf.size() > left_hirf.size()) {
        x = *right_hirf.begin();

        left_sum += x;
        right_sum -= x;

        left_hirf.insert(x);
        right_hirf.erase(right_hirf.lower_bound(x));
    }
    else if (left_hirf.size() - 1 > right_hirf.size()) {
        left_sum -= mid();
        right_sum += mid();

        right_hirf.insert(mid());
        left_hirf.erase(left_hirf.lower_bound(mid()));
    }
}

