void solve() {
	// f(x) = 0
	// 1 4 2
	// f(x) = 0 + |x - 4| + 2
	// 2 -> 2
	// 1 1 -8
	// f(x) = |x-4| + 2 + |x-1| -8
	// f(x) = |x-4| + |x-1| + 2 - 8
	// sigma_1-Q |x-ai| + bi
	// グラフは下がって上がる
	// あるxについて、下がっている絶対値の数と上がっている絶対値の数を比較
	// 下がりが多い -> 下がっているので続ける
	// 等しいとき-> 値の変化がないので最小
	// 上りが多い -> 上がっているので、上がり始めるときに最小
	cin >> Q;
	vpii Ans;

	multiset<pair<ll, ll>> A;
	vi As;

	ll B = 0;

	ll up = 0;
	ll down = 0;

	{
		ll i, a, b;
		cin >> i >> a >> b;
		A.insert(mp(a, 0));
		As.pb(a);
		B += b;
		down += a;
	}

	auto itr = A.begin();
	auto size = 1;


	repa(i, 1, Q) {
		ll query;
		cin >> query;

		ll m = (*itr).first;

		if (query == 1) {
			ll a, b;
			cin >> a >> b;
			A.insert(mp(a, i));
			As.pb(a);
			B += b;
			size++;

			if (a < m) {
				down += a;
				if (size % 2 == 0) {
					up += m;
					down -= m;
					itr--;
				}
			}
			else {
				up += a;
				if (size % 2 == 1) {
					itr++;

					ll nex = (*itr).first;
					down += nex;
					up -= nex;
				}
			}
		}
		else {
			ll ds = (size + 1) / 2;
			ll us = size - ds;

			ll a = up - us * m + ds * m - down;
			Ans.pb(mp(m, a + B));
		}
	}

	for (auto a : Ans) {
		cout << a.first << " " << a.second << endl;
	}
}

