ll C = 0;

void solve() {
    sort(a.begin(), a.end());
    ll low = -1000000000, high = 1000000000;
    ll ans = LLONG_MAX;
    while (1) {
        low = *lower_bound(a.begin(), a.end(), low);
        high = *(upper_bound(a.begin(), a.end(), high) - 1);
        ll mid = (low + high) / 2;
        ll p = mid, q = mid + 1;
        if (low == high) {
            p = q = low;
        }
        ll s = 0, t = 0;
        for (auto _a:a) {
            s += abs(p - _a);
            t += abs(q - _a);
        } // 累積和
        ans = min({ans, s, t});
        if (s == t) {
            low = p, high = q;
            break;
        } else if (s < t) {
            high = q;
        } else if (s > t) {
            low = p;
        }
    }
    low = *(upper_bound(a.begin(), a.end(), low) - 1);
    ans += C;
    cout << low << " " << ans << endl;
}

