using namespace std;

class fenwick {
public:
	fenwick(int n)
		: n(n)
		, tree(n, 0)
	{}
	void set_value(int i, long long v) {
		while (i < n) {
			tree[i] += v;
			i |= (i + 1);
		}
	}
	long long get_sum(int l, int r) {
		if (l) {
			return get_sum(0, r) - get_sum(0, l - 1);
		} else {
			long long answer = 0;
			while (r >= 0) {
				answer += tree[r];
				r = (r & (r + 1)) - 1;
			}
			return answer;
		}
	}
private:
	int n;
	vector<long long> tree;
};

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	int q = 200000;
	cin >> q;
	vector<vector<long long>> queries(q, vector<long long>(3, 0LL));
	vector<long long> a;
	int size_a = 0;
	for (int i = 0; i < q; ++i) {
		if (1) {
			cin >> queries[i][0];
			if (queries[i][0] == 1) {
				size_a += 1;
				cin >> queries[i][1] >> queries[i][2];
				a.push_back(queries[i][1]);
			}
		} else {
			if (i < q / 2) {
				++size_a;
				queries[i][0] = 1;
				queries[i][1] = rand() % (long long)2e9 - (long long)1e9;
				queries[i][2] = rand() % (long long)2e9 - (long long)1e9;
				a.push_back(queries[i][1]);
			} else {
				queries[i][0] = 2;
			}
		}
	}
	//puts("!");
	fenwick f(size_a);
	fenwick fidx(size_a);
	sort(a.begin(), a.end());
	map<long long, vector<long long> > place;
	multiset<long long> s;
	for (int i = 0; i < size_a; ++i) {
		place[a[i]].push_back(i);
	}
	map<int, int> copy;
	for (auto& [k, v] : place) {
		copy[k] = v.front();
	}
	long long delta = 0;
	long long tot = 0;
	auto F = [&](long long x) -> long long {
		long long idx = copy[x];
		long long left_sum = 0;
		long long right_sum = 0;
		if (idx > 0) {
			left_sum = f.get_sum(0, idx - 1);
		}
		right_sum = tot - left_sum;
		long long c1 = idx > 0 ? fidx.get_sum(0, idx - 1) : 0;
		long long c2 = s.size() - c1;
		long long f = -left_sum + c1 * x + right_sum - c2 * x + delta;
		return f;
	};
	for (int i = 0; i < q; ++i) {
		if (queries[i][0] == 1) {
			tot += queries[i][1];
			s.insert(queries[i][1]);
			delta += queries[i][2];
			long long idx = place[queries[i][1]].back();
			place[queries[i][1]].pop_back();
			fidx.set_value(idx, 1);
			f.set_value(idx, queries[i][1]);
		} else {
			//puts("!");
			int l = 0, r = s.size() - 1;
			while (r - l > 3) {	
				long long a = *next(s.begin(), l + 2 * (l + r) / 3);
				long long b = *next(s.begin(), l + (l + r) / 3);
				if (F(a) < F(b)) {
					r = l + (l + r) / 3;
				} else {
					l = l + 2 * (l + r) / 3;
				}
				//cout << l << ' ' << r << endl;
			}
			long long xx = *next(s.begin(), l), ff = F(xx);
			for (auto it = next(s.begin(), l + 1); it != next(s.begin(), r + 1); ++it) {
				long long cur_x = *it;
				long long cur_f = F(cur_x);
				if (cur_f < ff) {
					xx = cur_x;
					ff = cur_f;
				}
			}
			cout << xx << ' ' << ff << '\n';
		}
	}
	return 0;
}

