				swap(heap[fa],heap[fa>>1]);
				fa=fa>>1;
			}
			else break;
		}
	}
	inline void push(int v){
		heap[++n]=v;
		up(n);
	}
	inline void down(int fa){
		int s=fa<<1;
		while(s<=n){
			if(s<n&&heap[s]>heap[s+1])s++;
			if(heap[s]<heap[fa]){
				swap(heap[s],heap[fa]);
				fa=s;s=fa<<1;
			}
			else break;
		}
	}
	inline void pop(){
		heap[1]=heap[n--];
		down(1);
	}
	inline int size(){
		return n;
	}
	inline int top(){
