      if (a <= center) {
        left.push(a);
      } else {
        right.push(a);
      }
      sum_xa += abs(a - center);
      while (left.size() > size_t(m)) {
        int64_t new_center = left.top();
        int64_t d          = abs(center - new_center);
        sum_xa -= int64_t(left.size()) * d;
        left.pop();
        right.push(center);
        center = new_center;
        sum_xa += int64_t(right.size()) * d;
      }
      while (left.size() < size_t(m)) {
        int64_t new_center = right.top();
        int64_t d          = abs(new_center - center);
        sum_xa -= int64_t(right.size()) * d;
        right.pop();
        left.push(center);
        center = new_center;
        sum_xa += int64_t(left.size()) * d;
      }
