    ll leftSum = 0, rightSum = 0;
    priority_queue<ll> left;
    priority_queue<ll, vector<ll>, greater<ll>> right;
    ll constant = 0;

    int q; cin >> q;
    while(q--) {
        int kind; cin >> kind;
        if (kind == 2) {
            ll x = left.top();
            cout << x << " " << constant + x*ll(left.size()) - leftSum - x*ll(right.size()) + rightSum << endl;
        } else {
            int a, b; cin >> a >> b;
            constant += b;

            // 求値クエリの時に left.top() を見ればいいように，0 ≤ left.size()-right.size() ≤ 1 になるように実装する．
            if (left.size() == 0 && right.size() == 0) {
                left.push(a);
                leftSum += a; 
            } else if (right.size() != left.size()) { // right.size()+1 == left.size()
                ll ltmp = left.top();
                if (a < ltmp) {
                    left.pop();
                    leftSum -= ltmp;
                    right.push(ltmp);
                    rightSum += ltmp;
                    left.push(a);
                    leftSum += a;
                } else {
                    right.push(a);
                    rightSum += a;
                }
            } else { // right.size()>0 && left.size()>0 && left.size()==right.size()
                ll rtmp = right.top();
                if (a < rtmp) {
                    left.push(a);
                    leftSum += a;
                } else {
                    right.pop();
                    rightSum -= rtmp;
                    left.push(rtmp);
                    leftSum += rtmp;
                    right.push(a);
                    rightSum += a;
                }
            }
        }
    }

    return 0;
}

