/// Segment Tree
const int max_node = 10000000;
pair<ll,int> tree[max_node];
void update(int node , int start , int _end , int idx , int val)
{
    if(start == _end)
    {
        tree[node] = mp(tree[node].fr + val,tree[node].sc+1);
    }
    else
    {
        int mid = (start+_end)/2;
        if(start <= idx && idx <= mid)
        {
            update(node*2,start,mid,idx,val);
        }
        else
        {
            update(node*2+1,mid+1,_end,idx,val);
        }
        tree[node] = mp(tree[2*node].fr+tree[2*node+1].fr ,tree[2*node].sc+tree[2*node+1].sc) ;
    }
 }

pair < ll , int > query(int node , int start , int _end, int r)
{
    if(start == _end)
    {
        return tree[node];
    }
    int mid = (start+_end)/2;
    if(mid >= r)
    {
        return query(2*node  ,start , mid , r);
    }
    else
    {
        pair<ll,int> x1 = tree[node*2];
        pair<ll,int> x2 = query(2*node+1,mid+1 ,_end , r);
        return mp(x1.fr+x2.fr , x2.sc+x1.sc);
    }
}

