struct SegmentTree
{
    using T = int;

    int N;
    vector<T> dat;

    T id = 0;
    T F(T &a, T &b) { return a + b; }

    SegmentTree(int n){
        N = 1;
        while(n > N) N = N << 1;
        dat = vector<T>(2 * N - 1, id);
    }

    SegmentTree(int n, vector<T> &v){
        N = 1;
        while(n > N) N = N << 1;
        dat = vector<T>(2 * N - 1, id);
        for(int i = 0; i < n; i++) dat[i + N - 1] = v[i];
        for(int i = N - 2; i >= 0; i--) dat[i] = F(dat[i * 2 + 1], dat[i * 2 + 2]); 
    }


    void update(int k, T a){
        k += N - 1;
        dat[k] = a;
        while(k > 0){
            k = (k - 1) / 2;
            dat[k] = F(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    void reset() { fill(dat.begin(), dat.end(), id); }

    T get(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return id;
        if(a <= l && r <= b) return dat[k];
        else{
            T vl = get(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = get(a, b, k * 2 + 2, (l + r) / 2, r);
            return F(vl, vr);
        }
    }
    T get(int a, int b) { return get(a, b, 0, 0, N); }

    T val(int k){ return dat[k + N - 1]; }
};

signed main(){

    int Q; cin >> Q;
    vec t(Q), a(Q), b(Q);
    set<int> s;
    REP(q, Q){
        cin >> t[q];
        if(t[q] == 1){
            cin >> a[q] >> b[q];
            s.insert(a[q]);
        }
    }
    vec v;
    for(int i: s) v.pb(i);
    int n = SZ(v);

    SegmentTree ST1(n), ST2(n);
    int B = 0;
    pairs ans;
    REP(q, Q){
        if(t[q] == 1){
            int i0 = Lower_bound(v, a[q]);
            B += b[q];
            ST1.update(i0, ST1.val(i0) + 1);
            ST2.update(i0, ST2.val(i0) + a[q]);
        }else{
            int N = ST1.get(0, n);
            int i0 = 0, i1 = n;
            while(i1 - i0 > 1){
                int i = (i0 + i1) / 2;
                if(ST1.get(0, i) < (N + 1) / 2) i0 = i;
                else i1 = i;
            }
            int tmp = B;
            tmp += ST2.get(i0 + 1, n) - ST1.get(i0 + 1, n) * v[i0];
            tmp += -ST2.get(0, i0 + 1) + ST1.get(0, i0 + 1) * v[i0];
            ans.pb(Pii(v[i0], tmp));
        }
    }
    REP(i, SZ(ans)){
        cout << ans[i].f << " " << ans[i].s << endl;
    }

    return 0;
}

