    		cnt++;
    		if(cnt==1){
    			L.push(a);
    			R.push(a);
    			sum_L+=a;
    			sum_R+=a;
    		}
    		else if(cnt%2==1){
    			if(a<L.top()){
    				R.push(L.top());
    				sum_R+=L.top();
    				L.push(a);
    				sum_L+=a;
    			}
    			else if(a>R.top()){
