void solve()
{
	READ(int, Q);
	Q--;

	llong median;
	llong totalB;
	{
		READ(int, q, a, b);
		median = a;
		totalB = b;
	}

	llong totalL = 0, totalR = 0;
	priority_queue<llong,vector<llong>, less<> > l;
	priority_queue<llong,vector<llong>, greater<> > r;

	REP(i, Q)
	{
		READ(int, q);
		if (q == 2)
		{
			llong f = 0;
			f += l.size() * median - totalL;
			f += totalR - r.size() * median;
			f += totalB;
			DEBUG("-> ", median, f);
			WRITE(median, f);
		}

		if (q == 1)
		{
			READ(llong, a, b);
			totalB += b;

			if (a < median) { l.push(a); totalL += a; }
			else { r.push(a); totalR += a; }

			if (l.size() > r.size())
			{
				r.push(median); totalR += median;
				median = l.top(); l.pop(); totalL -= median;
			}

			if (r.size() > l.size() + 1)
			{
				l.push(median); totalL += median;
				median = r.top(); r.pop(); totalR -= median;
			}
		}
	}



}

