		return x;
	ll mid = (x + y) / 2;
	if (seg[node*2] >= val)
		return check(val, node * 2, x, mid);
	else
		return check(val-seg[node*2], node * 2 + 1, mid + 1, y);
}
ll query(ll lo, ll hi, ll node, ll x, ll y) {
	if (hi < x || y < lo)return 0;
	if (lo <= x && y <= hi)return seg[node];
	ll mid = (x + y) / 2;
	return query(lo, hi, node * 2, x, mid) + query(lo, hi, node * 2 + 1, mid + 1, y);
}
ll query1(ll lo, ll hi, ll node, ll x, ll y) {
	if (hi < x || y < lo)return 0;
	if (lo <= x && y <= hi)return seg1[node];
	ll mid = (x + y) / 2;
	return query1(lo, hi, node * 2, x, mid) + query1(lo, hi, node * 2 + 1, mid + 1, y);
}
