        lv += a - l0;
        if(l.size() - r.size() > 1){
          long long tmp = l.top();
          lv -= tmp - l0;
          l.pop();
          r.push(tmp);
          rv += r0 - tmp;
        }
      }else{
        r.push(a);
        rv += r0 - a;
        if(r.size() > l.size()){
          long long tmp = r.top();
          rv -= r0 - tmp;
          r.pop();
          l.push(tmp);
          lv += tmp - lv;
