map<ll, ll> mp;
void add(ll x) {
	if (mp.find(x) == mp.end()) {
		mp.insert({ x,1 });
	}
	else {
		mp[x]++;
	}
}

int main() {
	int Q; cin >> Q;
	ll bsum = 0;
	ll Lsum = 0, Rsum = 0;
	ll L = 0, R = 0;
	ll x;
	cin >> x; cin >> x >> bsum;
	Lsum += x;
	L++;

	add(x);
	auto itr = mp.find(x);

	ll N = 1;
	for (int q = 1; q < Q; q++) {
		int i; cin >> i;
		if (i == 2) {
			cout << itr->first << " " << L * itr->first - Lsum - R * itr->first + Rsum + bsum << endl;
		}
