			ll a, b; cin >> a >> b;
			bsum += b;

			add(a);
			if (a <= itr->first) {
				L++;
				Lsum += a;
			}
			else {
				R++;
				Rsum += a;
			}
			N++;

			while (L < (N + 1) / 2) {
				itr++;
				L += itr->second;
				R -= itr->second;
				Lsum += itr->second * itr->first;
				Rsum -= itr->second * itr->first;
			}
			while (L - itr->second >= (N + 1) / 2) {
				L -= itr->second;
				R += itr->second;
				Lsum -= itr->second * itr->first;
				Rsum += itr->second * itr->first;
