void update(int a,int b)
{
    kq+=b;
    if ((fi>0)&&(first.top()>a))
    {
        first.push(a);
        fi++;
        k+=a;
    }
    else
    {
        if ((se>0)&&(second.top()<a))
        {
            second.push(a);
            se++;
            l+=a;
        }
        else
        {
            first.push(a);
            fi++;
            k+=a;
        }
    }
    long e;
    if (fi>se+1)
    {
        e=first.top();
        second.push(e);
        fi--;
        k-=e;
        l+=e;
        se++;
        first.pop();
    }
    if (se>fi+1)
    {
        e=second.top();
        first.push(e);
        se--;
        fi++;
        k+=e;
        l-=e;
        second.pop();
    }
}

