  int64_t Q;
  In(Q);
  // vector<int64_t> a, b;
  int64_t n = 0;
  priority_queue<int64_t> left;
  priority_queue<int64_t, vector<int64_t>, greater<int64_t>> right;
  int64_t center = 0;
  int64_t sum_b  = 0;
  int64_t sum_xa = 0;
  rep(i, Q) {
    int64_t com;
    In(com);
    if (com == 1) {
      int64_t a, b;
      In(a, b);
      n++;
      int64_t m = (n - 1) / 2;
      sum_b += b;
      if (n == 1) {
        center = a;
        continue;
      }
      if (a <= center) {
        left.push(a);
      } else {
        right.push(a);
      }
      sum_xa += abs(a - center);
      while (left.size() > size_t(m)) {
        int64_t new_center = left.top();
        int64_t d          = center - new_center;
        sum_xa -= int64_t(left.size()) * d;
        left.pop();
        right.push(center);
        center = new_center;
        sum_xa += int64_t(right.size()) * d;
      }
      while (left.size() < size_t(m)) {
        int64_t new_center = right.size();
        int64_t d          = new_center - center;
        sum_xa -= int64_t(right.size()) * d;
        right.pop();
        left.push(center);
        center = new_center;
        sum_xa += int64_t(left.size()) * d;
      }
    } else {
      cout << center << " " << sum_b + sum_xa << endl;
    }
  }
  return EXIT_SUCCESS;
}

