// ----- Solve -----

class Solve
{
  int q;
  ll c;
  max_heap<ll> l;
  min_heap<ll> r;

public:
  Solve(int q) : q{q}, c{0}
  {
    for (auto t{0}; t < q; ++t)
    {
      int val;
      cin >> val;
      if (val == 1)
      {
        update();
      }
      else
      {
        query();
      }
    }
  }

private:
  void update()
  {
    ll a, b;
    cin >> a >> b;
    c += b;
    l.push(a);
    r.push(a);
    ll x{l.top()};
    ll y{r.top()};
    l.pop();
    r.pop();
    c += abs(x - y);
    if (x > y)
    {
      swap(x, y);
    }
    l.push(x);
    r.push(y);
  }

  void query()
  {
    cout << l.top() << " " << c << endl;
  }
};

// ----- main() -----

int main()
{
  int q;
  cin >> q;
  Solve solve(q);
}

