using namespace std;

struct BstNode
{
    BstNode(int64_t key) : count(1), sum(key), key(key) {}

    ~BstNode()
    {
        if (left) {
            delete left;
        }
        if (right) {
            delete right;
        }
    }

    BstNode *left = nullptr;
    BstNode *right = nullptr;

    int64_t count = 0;
    int64_t sum = 0;
    int64_t key;
};

void Insert(BstNode *&root, int64_t key)
{
    if (!root) {
        root = new BstNode(key);
        return;
    }

    root->count += 1;
    root->sum += key;

    if (key < root->key) {
        Insert(root->left, key);
    } else {
        Insert(root->right, key);
    }
}

int64_t KthKey(const BstNode *root, int64_t count)
{
    if (!root) {
        return -1;
    }

    if (root->left) {
        if (count <= root->left->count) {
            return KthKey(root->left, count);
        }
        count -= root->left->count;
    }

    if (count == 1) {
        return root->key;
    }
    return KthKey(root->right, count - 1);
}

int64_t SumSmaller(const BstNode *root, int64_t count)
{
    if (!root || count <= 0) {
        return 0;
    }

    int64_t sum = 0;
    if (root->left) {
        if (root->left->count >= count) {
            return SumSmaller(root->left, count);
        }
        count -= root->left->count;
        sum += root->left->sum;
    }

    sum += root->key;
    return sum + SumSmaller(root->right, count - 1);
}

class Bst
{
public:
    ~Bst()
    {
        if (root_) {
            delete root_;
        }
    }

    int Size() const { return size_; }

    int MiddlePos() const { return (size_ + 1) / 2; }

    int64_t MiddleKey() const { return ::KthKey(root_, MiddlePos()); }

    int64_t SumSmaller(int64_t pos) const { return ::SumSmaller(root_, pos); }

    int64_t Total() const { return (root_ ? root_->sum : 0); }

    void Insert(int64_t key)
    {
        size_ += 1;
        ::Insert(root_, key);
    }

private:
    BstNode *root_ = nullptr;
    int size_ = 0;
};

int64_t FindMin(const Bst &bst)
{
    auto mid = bst.MiddlePos();
    auto key = bst.MiddleKey();

    auto n1 = mid;
    auto n2 = bst.Size() - n1;

    auto sum1 = bst.SumSmaller(mid);
    auto sum2 = bst.Total() - sum1;

    return n1 * key - sum1 + sum2 - n2 * key;
}

int main()
{
    int n;
    cin >> n;

    Bst bst;
    int64_t bs = 0;

    for (auto i = 0; i < n; i += 1) {
        int type;
        cin >> type;

        if (type == 1) {
            int64_t a, b;
            cin >> a >> b;

            bst.Insert(a);
            bs += b;
        } else {
            cout << bst.MiddleKey() << " ";
            cout << bs + FindMin(bst) << "\n";
        }
    }
    return 0;
}

