  } else if (a < leftmax) {
    left.insert(a);
    left.insert(a);
    left.erase(--(left.end()));
    right.insert(leftmax);
  } else if (rightmin < a) {
    right.insert(a);
    right.insert(a);
    right.erase(right.begin());
    left.insert(rightmin);
  } else {
    left.insert(a);
    right.insert(a);
  }
  if (left.size() == 1 || (leftmax <= a && a <= rightmin)) {
    result += 0;
  } else if (rightmin < a) {
    result += (a - rightmin);
  } else {
    result += (leftmax - a);
  }
}
void Solve() {
  cout << *(--left.end()) << " " << result << endl;
}

