struct Query { ll cmd, a, b; };

vector<ii> solve(const vector<Query>& qs)
{
    vector<ii> ans;

    priority_queue<int> L;
    priority_queue<int, vector<int>, greater<int>> R;

    ll ls = 0, rs = 0, bs = 0;

    for (auto q : qs)
    {
        switch (q.cmd) {
        case 1:
            {
                L.push(q.a);
                ls += q.a;

                while (not R.empty() and L.top() > R.top())
                {
                    auto x = L.top(), y = R.top();

                    L.pop();
                    R.pop();

                    ls -= x;
                    ls += y;
                    L.push(y);

                    rs -= y;
                    rs += x;
                    R.push(x);
                }

                if (L.size() - R.size() > 1)
                {
                    auto x = L.top();
                    L.pop();

                    ls -= x;
                    rs += x;

                    R.push(x);
                }

                bs += q.b;
            } 
            break;

        default:
            {
                auto median = L.top();
                auto f = bs + (median * L.size() - ls) + (rs - median * R.size());

                ans.push_back(ii(median, f));
            }

            break;
        }
    }

    return ans;
}

int main()
{
    ios::sync_with_stdio(false);

    int Q;
    cin >> Q;

    vector<Query> qs(Q);

    for (int i = 0; i < Q; ++i)
    {
        cin >> qs[i].cmd;

        if (qs[i].cmd == 2)
            continue;

        cin >> qs[i].a >> qs[i].b;
    }

    auto ans = solve(qs);

    for (auto p : ans)
        cout << p.first << ' ' << p.second << '\n';

    return 0;
}

