void prog()
{
    int q = read<int>();
    std::vector<std::int64_t> floor;
    std::int64_t sum_b = 0;

    for (int i = 0; i < q; ++i) {
        if (read<int>() == 1) {
            std::int64_t a, b;
            std::cin >> a >> b;
            sum_b += b;
            floor.push_back(a);
        } else {
            if (floor.size() == 1) {
                out(floor[0], sum_b);
                continue;
            }
            if (floor.size() == 2) {
                out(std::min(floor[0], floor[1]), std::abs(floor[0] - floor[1]) + sum_b);
                continue;
            }
            auto mid = floor.begin() + floor.size() / 2;
            if (floor.size() % 2 == 0) --mid;
            std::nth_element(floor.begin(), mid, floor.end());
            std::int64_t sum = 0;
            sum -= std::accumulate(floor.begin(), mid, 0l);
            sum += std::accumulate(mid + 2 - floor.size() % 2, floor.end(), 0l);
            out(*mid, sum + sum_b);
        }
    }
}

