/// 逐次中央値更新するやつ。
template <class T>
class MedianUpdater
{
	multiset<T> left_;
	multiset<T> right_;
	T leftTotal_ = 0;
	T rightTotal_ = 0;
	T median_ = 0;
	int inserted = 0;

public:

	T median() const { return median_; }
	T leftTotal() const { return leftTotal_; }
	T leftCount() const { return left_.size(); }
	T rightTotal() const { return rightTotal_; }
	T rightCount() const { return right_.size(); }

	void insert(T a)
	{
		if (inserted == 0)
		{
			median_ = a;
		}
		else if (a < median_)
		{
			left_.insert(a); leftTotal_ += a;
			if (left_.size() > right_.size())
			{
				right_.insert(median_); rightTotal_ += median_;
				auto it = left_.end(); --it; median_ = *it;
				left_.erase(it); leftTotal_ -= median_;
			}
		}
		else
		{
			right_.insert(a); rightTotal_ += a;
			if (right_.size() > left_.size() + 1)
			{
				left_.insert(median_); leftTotal_ += median_;
				auto it = right_.begin(); median_ = *it;
				right_.erase(right_.begin()); rightTotal_ -= median_;
			}
		}
		inserted++;
	}
};

void solve()
{
	READ(int, Q);

	MedianUpdater<llong> m;
	llong totalB = 0;

	REP(i, Q)
	{
		READ(int, q);
		if (q == 2)
		{
			llong f = 0;
			llong med = m.median();
			f += m.leftCount() * med - m.leftTotal();
			f += m.rightTotal() - m.rightCount() * med;
			f += totalB;
			DEBUG(med, f);
			WRITE(med, f);
		}

		if (q == 1)
		{
			READ(llong, a, b);
			totalB += b;
			m.insert(a);
		}
	}



}

