int main()
{
	ll Q;
	cin >> Q;
	ll sumb = 0;
	ll gradl = 0;
	ll gradr = 0;
	priority_queue<ll> pql;
	priority_queue<ll, vector<ll>, greater<ll>> pqr;


	REP(i, Q) {
		ll kind;
		cin >> kind;
		if (kind == 1) {
			ll a, b;
			cin >> a >> b;

			// add
			if (pqr.empty() || a < pqr.top()) {
				pql.push(a);
				gradl += a;
			}
			else {
				pqr.push(a);
				gradr += a;
			}
			// save
			while (pql.size() >= pqr.size() + 2) {
				ll now = pql.top(); pql.pop();
				gradl -= now;

				pqr.push(now);
				gradr += now;
			}
			while (pqr.size() + 2 <= pqr.size()) {
				ll now = pqr.top(); pqr.pop();
				gradr -= now;

				pql.push(now);
				gradl += now;
			}

			sumb += b;
		}
		else {
			ll res1, res2;
			if (pql.size() == pqr.size()) {
				res1 = pql.top();
			}
			else if (pql.size() == pqr.size() + 1) {
