using As = std::multimap<int64_t, bool>;

template <typename Map>
void print_map(const Map &c, const std::string &name)
{
  std::cout << name << ": ";
  std::for_each(c.cbegin(), c.cend(),
                [](auto &x) { std::cout << x.first << ":" << x.second << ", "; });
  std::cout << std::endl;
}

void update(As &lefts, As &rights,
            int64_t &n, int64_t &min)
{
  int64_t a, b;
  std::cin >> a >> b;

  min += b;

  if(n == 0) {
    lefts.insert(std::make_pair(a, true));
    // print_map(lefts, "first left");
    n++;
    return;
  }

  int64_t old_argmin = lefts.rbegin()->first;
  bool appends_left =  a <= old_argmin;

  if(appends_left && n%2 == 1) {
    // std::cout << "left[-1] -> rights " << std::endl;
    // print_map(lefts, "left");
    // remove lefts[-1] and append it to rights
    auto old = *(--lefts.cend());
    // std::cout << "old: " << old.first << ": " << old.second << std::endl;
    lefts.erase(--lefts.cend());
    // std::cout << "erase left[-1]" << std::endl;
    rights.insert(old);
  } if(!appends_left && n%2 == 0) {
    // std::cout << "right[0] -> left" << std::endl;
    // remove right[0] and append it to lefts
    auto old = *rights.begin();
    rights.erase(rights.begin());
    lefts.insert(old);

  }

  // append a
  auto new_a = std::make_pair(a, true);
  if(appends_left) {
    lefts.insert(new_a);
  } else {
    rights.insert(new_a);
  }

  // update min
  int64_t new_argmin = lefts.rbegin()->first;
  if(n % 2 == 1) {
    min += std::abs(old_argmin - new_argmin);
  }
  min += std::abs(new_argmin - a);

  n++;
}

void print( As &lefts, As &rights,
            int64_t n, int64_t min)
{
  int64_t argmin = lefts.rbegin()->first;
  std::cout << argmin << " " << min << std::endl;
}

int main()
{
  int Q;
  std::cin >> Q;

  As lefts, rights;
  int64_t n = 0;         // number of added |x-a| + b
  int64_t min = 0;   // mimimum now

  for(int i=0; i<Q; i++) {
    int c;
    std::cin >> c;
    if(c == 1) {
      update(lefts, rights, n, min);
    } else if(c == 2) {
      print(lefts, rights, n, min);
    }
  }

  return 0;
}

