class MinSumAbs {
  std::multiset<ll> l, r;
  ll lsum, rsum;
public:
  MinSumAbs():lsum(0),rsum(0){}
  void add(ll a){
    l.insert(a); lsum += a;
    if(l.size()-r.size()>1){
      auto itr = --l.end();
      ll x = *itr;
      l.erase(itr); lsum -= x;
      r.insert(x); rsum += x;
    }
    if(r.size() != 0){
      auto itrl = --l.end();
      auto itrr = r.begin();
      ll x = *itrl, y = *itrr;
      if(x > y){
        l.erase(itrl); lsum -= x;
        r.erase(itrr); rsum -= y;
        l.insert(y); lsum += y;
        r.insert(x); rsum += x;
      }
    }
  }
  std::pair<ll,ll> get() {
    if(l.empty()) return std::make_pair(0, 0);
    auto itr = --l.end();
    ll x = *itr;
    ll N = l.size();
    ll M = r.size();
    return std::make_pair(x, N * x - lsum + rsum - M * x);
  }
};


int main(){
  int Q;
  cin >> Q;

  ll bsum = 0;
  MinSumAbs msa;
  rep(i,Q){
    int x;
    cin >> x;
    if(x == 1){
      ll a, b;
      cin >> a >> b;

      bsum += b;
      msa.add(a);
    }else{
      pair<ll,ll> res = msa.get();
      cout << res.first << " " << res.second + bsum << endl;
    }
  }

  return 0;
}

