namespace BST {
    template <typename T>
    struct Node {
        Node *lch, *rch;
        T val;
        T pri;
        T sum;
        int cnt;

        Node() {}
        Node(T val, T pri) : lch(nullptr), rch(nullptr), val(val), pri(pri), sum(val), cnt(1) {}
    };

    template <typename T>
    struct NodePool {
        std::vector<Node<T>> v;
        std::mt19937 engine;
        std::uniform_int_distribution<T> dist;
        int pos;

        NodePool(int size) : v(size),
            engine(std::chrono::steady_clock::now().time_since_epoch().count()),
            dist(std::numeric_limits<T>::min(), std::numeric_limits<T>::max()),
            pos(0) {}

        Node<T> *alloc(T val) {
            return new(&v[pos++]) Node<T>(val, dist(engine));
        }
    };

    template <typename T>
    int count(Node<T> *t) { return t ? t->cnt : 0; }
    template <typename T>
    int sum(Node<T> *t) { return t ? t->sum : 0; }

    template <typename T>
    Node<T> *update(Node<T> *t) {
        t->cnt = count(t->lch) + count(t->rch) + 1;
        t->sum = sum(t->lch) + sum(t->rch) + t->val;
        return t;
    }

    template <typename T>
    Node<T> *merge(Node<T> *l, Node<T> *r) {
        if (!l || !r) return l ? l : r;

        if (l->pri > r->pri) {
            l->rch = merge(l->rch, r);
            return update(l);
        } else {
            r->lch = merge(l, r->lch);
            return update(r);
        }
    }

    // count-based: [0, k), [k, n)
    template <typename T>
    std::pair<Node<T>*, Node<T>*> split(Node<T> *t, int k) {
        if (!t) return { nullptr, nullptr };

        if (k <= count(t->lch)) {
            auto s = split(t->lch, k);
            t->lch = s.second;
            return { s.first, update(t) };
        } else {
            auto s = split(t->rch, k - count(t->lch) - 1);
            t->rch = s.first;
            return { update(t), s.second };
        }
    }

    template <typename T>
    T kth_element(Node<T> *t, const int k) {
        if (!t) return std::numeric_limits<T>::max();
        if (k == count(t->lch)) return t->val;
        if (k < count(t->lch)) return kth_element(t->lch, k);
        else return kth_element(t->rch, k - count(t->lch) - 1);
    }

    // returns index of lower_bound of x in t
    template <typename T>
    int lower_bound(const Node<T> * const t, const T x) {
        if (!t) return 0;
        if (x <= t->val) return lower_bound(t->lch, x);
        else return count(t->lch) + 1 + lower_bound(t->rch, x);
    }

    template <typename T>
    int upper_bound(const Node<T> * const t, const T x) {
        if (!t) return 0;
        if (x < t->val) return upper_bound(t->lch, x);
        else return count(t->lch) + 1 + upper_bound(t->rch, x);
    }

    template <typename T>
    struct BinarySearchTree {
        NodePool<T> pool;
        Node<T> *root;

        BinarySearchTree(int size) : pool(size), root(nullptr) {}
        T kth_element(int k) const { return BST::kth_element(root, k); }
        int size() const { return count(root); }
        T sum(int a, int b) {
            // [a, b)
            auto s = split(root, a);
            auto t = split(s.second, b - a);
            auto ret = BST::sum(t.first);
            root = merge(s.first, merge(t.first, t.second));
            return ret;
        }
    };

    template <typename T>
    struct OrderedMultiSet : BinarySearchTree<T> {
        OrderedMultiSet(int size) : BinarySearchTree<T>(size) {}

        int count(const T val) const {
            return upper_bound(BinarySearchTree<T>::root, val) - lower_bound(BinarySearchTree<T>::root, val);
        }

        void insert(const T val) {
            int k = lower_bound(BinarySearchTree<T>::root, val);
            auto s = split(BinarySearchTree<T>::root, k);
            BinarySearchTree<T>::root = merge(merge(s.first, BinarySearchTree<T>::pool.alloc(val)), s.second);
        }

        void erase(const T val) {
            int lb = lower_bound(BinarySearchTree<T>::root, val), ub = upper_bound(BinarySearchTree<T>::root, val);
            if (lb == ub) return;
            auto s = split(BinarySearchTree<T>::root, lb);
            auto t = split(s, ub - lb);
            BinarySearchTree<T>::root = merge(s.first, t.second);
        }
    };
}

