using namespace std;

int main() {
  int q;
  scan(q);
  ll minval = 0;
  priority_queue<int> left;
  priority_queue<int, vector<int>, greater<int> > right;
  rep (i, q) {
    int t;
    scan(t);
    if (t == 1) {
      int a, b;
      scan(a, b);
      if (left.size() == 0) {
        assert(right.size() == 0);
        left.push(a);
        minval = b;
      } else if (left.size() == right.size()) {
        int vrp = right.top();
        if (vrp < a) {
          minval += b + abs(a - vrp);
          left.push(vrp);
          right.pop();
          right.push(a);
        } else {
          int vlp = left.top();
          minval += b + abs(vlp - a);
          left.push(a);
        }
      } else {
        int vlp = left.top();
        if (vlp <= a) {
          minval += b + abs(a - vlp);
          right.push(a);
        } else {
          minval += b + abs(vlp - a);
          right.push(vlp);
          left.pop();
          left.push(a);
        }
      }
    } else {
      int vlp = left.top();
      printf("%d %lld\n", vlp, minval);
    }
  }

  return 0;
}

