using namespace std;

const int N = 200010;
const int INF = 2e9;

int q;
vector<int> val;
pair<int, int> a[N];

struct BIT {
    long long t[N];

    void add(int x, int v) {
        while (x < N) {
            t[x] += v;
            x += (x & -x);
        }
    }
    long long get(int x) {
        long long res = 0;
        while (x) {
            res += t[x];
            x -= x & -x;
        }
        return res;
    }
} t, tx;

struct IT {
    int t[N << 2];

    void add(int node, int l, int r, int x) {
        if (x > r || x < l) return;
        if (l == r) {
            t[node]++;
            return;
        }
        int m = l + r >> 1;
        add(node << 1, l, m, x);
        add(node << 1 | 1, m + 1, r, x);
        t[node] = t[node << 1] + t[node << 1 | 1];
    }

    int get(int node, int l, int r, int need) {
        if (l == r) return l;
        int m = l + r >> 1;
        if (t[node << 1] <= need) return get(node << 1 + 1, m + 1, r, need - t[node << 1]);
        return get(node << 1, l, m, need);
    }
} it;

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> q;
    for (int i = 1; i <= q; i++) {
        int op;
        cin >> op;
        if (op == 1) {
            cin >> a[i].first >> a[i].second;
            val.push_back(a[i].first);
        } else {
            a[i] = {INF, INF};
        }
    }
    val.push_back(-INF);
    sort(val.begin(), val.end());
    int n = val.size() - 1;
    long long delta = 0;
    for (int i = 1; i <= q; i++) {
        if (a[i].first == INF) {    
            int tot = it.t[1] - 1;
            int id = it.get(1, 1, n, tot / 2);
            long long res = delta;
            res += t.get(id);
            res += 1ll * val[id] * tx.get(id);
            cout << val[id] << ' ' << res << '\n';
        } else {
            int pos = lower_bound(val.begin(), val.end(), a[i].first) - val.begin();
            it.add(1, 1, n, pos);

            tx.add(1, -1);
            tx.add(pos, 2);
            t.add(1, a[i].first);
            t.add(pos, -2 * a[i].first);
            delta += a[i].second;
        }
    }
    return 0;
}

