// dp[i][l] := 活発な順にソートされた幼児のi番目(0-indexed)を見終わっていて、一番左の空きマスがl, 一番右の空きマスがN-1-(i+1-l)
int dp[2010][2010];

void solve(ostringstream& aout, long long N, std::vector<long long> A){

	// 活発度、インデックスのペア
	vector<pair<int, int>> ps;
	rep(i, N) {
		ps.emplace_back(A[i], i);
	}

	sort(ALLOF(ps));
	reverse(ALLOF(ps));

	rep(i, 2010) {
		rep(j, 2010) {
			dp[i][j] = -1;
		}
	}

	dp[0][0] = ((N - 1) - ps[0].second) * ps[0].first;
	dp[0][1] = ps[0].second * ps[0].first;

	// すでに求まっているdp[i] から dp[i+1]をもとめる
	rep(i, N-1) {
		rep(left, N) {
			if (dp[i][left] == -1) {
				continue;
			}

			int active = ps[i+1].first;
			int distL = abs(ps[i+1].second - left);
			int right = N - 1 - (i + 1 - left);
			int distR = abs(ps[i+1].second - right);

			// i+1 の子をleftにいれる
			chmax(dp[i + 1][left + 1], dp[i][left] + distL * active);
			// rightにいれる
			chmax(dp[i + 1][left], dp[i][left] + distR * active);
		}
	}

	int ans = -1;
	rep(i, 2010) {
		chmax(ans, dp[N - 1][i]);
	}
	cout << ans << "\n";
}

