			}
			else {
				pqmax.push(a);
				sumax += a;
			}
			sumb += b;
			// 末尾が逆転してたらswap
			if (pqmax.size() > 0 && pqmin.size() > 0 && pqmin.top() > pqmax.top()) {
				int tmin = pqmin.top();
				int tmax = pqmax.top();
				sumin -= tmin;
