void push(int x) {
  if(!h1.empty() && x <= *h1.rbegin()) {
    h1.insert(x);
    sh1 += x;
  }
  else {
    h2.insert(x);
    sh2 += x;
  }
  while(h1.size() > h2.size()) {
    const int cur = *h1.rbegin();
    h2.insert(cur);
    auto it = h1.end(); it--;
    h1.erase(it);
    sh2 += cur;
    sh1 -= cur;
  }
  while(h2.size() > h1.size()) {
    const int cur = *h2.begin();
    h1.insert(cur);
    h2.erase(h2.begin());
    sh1 += cur;
    sh2 -= cur;
  }
}
