int main() {
	quickio();
	int q; cin >> q;
	priority_queue<ll> l;
	priority_queue<ll, vll, greater<ll>> r;
	ll sl = 0;
	ll sr = 0;
	ll m = 0;
	ll buf = 0;
	Loop(i, q) {
		int op; cin >> op;
		if (op == 1) {
			ll a, b; cin >> a >> b;
			buf += b;
			if (i == 0) m = a;
			else if (a <= m) {
				l.push(a);
				sl += a;
			}
			else {
				r.push(a);
				sr += a;
			}
			int diff = int(r.size()) - int(l.size());
			if (diff == 2) {
				l.push(m);
				sl += m;
				m = r.top();
				r.pop();
				sr -= m;
			}
			else if (diff == -1) {
				r.push(m);
				sr += m;
				m = l.top();
				l.pop();
				sl -= m;
			}
		}
		else {
			ll ans = (m * l.size() - sl) + (sr - m * r.size()) + buf;
			cout << m << " " << ans << endl;
		}
	}
}

