//[i] := i番として圧縮されたものを返す
vi compress(vi &a) {
    vi b;
    int len = a.size();
    for (int i = 0; i < len; ++i) {
        b.push_back(a[i]);
    }
    sort(b);
    unique(b);
    for (int i = 0; i < len; ++i) {
        a[i] = lower_bound(all(b), a[i]) - b.begin();
    }
    int blen = sz(b);
    vi ret(blen);
    rep(i, blen) {
        ret[i] = b[i];
    }
    return ret;
}
