    //合計がw以上となる最小のxを返す
    //閉区間
    inline int lower_bound(int w) {
        if (w <= 0) return -1;
        int x = 0;
        int k = 1;
        while ((k << 1) <= n) k <<= 1;
        for (; k > 0; k >>= 1) {
            if (x + k <= n && dat[x + k - 1] < w) {
                w -= dat[x + k - 1];
                x += k;
            }
        }
        return x;
    }
