    while(q--){
        int c; cin>>c;
        if (c==1){
            ll a,b; cin>>a>>b;
            bsum += b;
            //同じときはlowerに詰める
            if (lower.size()==upper.size()){
                if (upper.empty()){
                    lower.push(a);
                    lowsum += a;
                    continue;
                }
                ll tmp = upper.top();
                if (a > tmp){
                    upper.pop();
                    upper.push(a);
                    upsum += a-tmp;
                    lower.push(tmp);
                    lowsum += tmp;
                }else{
                    lower.push(a);
                    lowsum += a;
                }
            }else{
                ll tmp = lower.top();
                if (a < tmp){
                    lower.pop();
                    lower.push(a);
                    lowsum += a-tmp;
                    upper.push(tmp);
                    upsum += tmp;
                }else{
                    upper.push(a);
                    upsum += a;
                }
            }
        }else{
            ll med = lower.top();
            ll ans=(med*lower.size()-lowsum)+(upsum-med*upper.size())+bsum;
            cout<<med<<" "<<ans<<endl;
        }
    }
    return 0;
}

