struct BIT {
    //[1, size]
    vector<int> data;
    int size;

    BIT(int s = 0) {
        size = s;
        data.assign(size + 1, 0);
    }

    //sum [1, i]
    int sum(int i) {
        int s = 0;
        while (i > 0) {
            s += data[i];
            i -= i & -i;
        }
        return s;
    }

    void add(int i, int x) {
        while (i <= size) {
            data[i] += x;
            i += i & -i;
        }
    }

    // x <= sum(i) を満たす最小のi
    int lower_bound(int x) {
        int ng = -1;
        int ok = size + 1;

        while (abs(ok - ng) > 1) {
            int mid = (ok + ng) / 2;

            if (x <= sum(mid)) ok = mid;
            else ng = mid;
        }
        return ok;
    }
};

