ordered_set SET;

vi queries[N];
pair < pii, int > a[N];
map < int, int > mapp;
ll st[M], arr[N];

void update(int node, int l, int r, int ind, ll val)
{
	if(l > r || ind < l || ind > r)
		return;
	if(l == r)
	{
		st[node] = val;
		return;
	}
	int mid = (l+r)>>1;
	int left = node<<1;
	int right = left|1;
	update(left,l,mid,ind,val);
	update(right,mid+1,r,ind,val);
	st[node] = st[left] + st[right];
	return;
}

ll query(int node, int l, int r, int p, int q)
{
	if(l > r || p > q || l > q || p > r)
		return 0LL;
	if(l >= p && r <= q)
		return st[node];
	int mid = (l+r)>>1;
	int left = node<<1;
	int right = left|1;
	return (query(left,l,mid,p,q) + query(right,mid+1,r,p,q));
}

void solve()
{
	int q, i, t, x, y, cnt_upd_queries = 0, ind, SIZE;
	ll sum = 0, ans, left, right, cnt_left, cnt_right;
	cin >> q;
	fo(i,1,q+1)
	{
		cin >> t;
		if(t == 1)
		{
			cin >> x >> y;
			queries[i] = {t,x,y,++cnt_upd_queries};
			a[cnt_upd_queries] = {{x,cnt_upd_queries},cnt_upd_queries};
		}
		else
			queries[i] = {t};
	}
	sort(a+1,a+cnt_upd_queries+1);
	fo(i,1,cnt_upd_queries+1)
		mapp[a[i].S] = i;
	sum = 0;
	fo(i,1,q+1)
	{
		if(sz(queries[i]) == 1)
		{
			SIZE = sz(SET);
			if(SET.empty())
				ans = 0;
			else if(SIZE&1)
			{
				ind = SET.find_by_order(SIZE/2)->S;
				cnt_left = cnt_right = SIZE/2;
				left = query(1,1,cnt_upd_queries,1,mapp[ind]-1);
				right = query(1,1,cnt_upd_queries,mapp[ind]+1,cnt_upd_queries);
				ans = (cnt_left*arr[ind] - left) + (right - cnt_right*arr[ind]);
			}
			else
			{
				ind = SET.find_by_order((SIZE-1)/2)->S;
				cnt_left = SIZE/2 - 1;
				cnt_right = SIZE/2;
				left = query(1,1,cnt_upd_queries,1,mapp[ind]-1);
				right = query(1,1,cnt_upd_queries,mapp[ind]+1,cnt_upd_queries);
				ans = (cnt_left*arr[ind] - left) + (right - cnt_right*arr[ind]);
			}
			// cout << "pre ans : " << ans << " " << sum << " : " << ind << '\n';
			ans += sum;
			cout << arr[ind] << " " << ans << '\n';
		}
		else
		{
			x = queries[i][1];
			y = queries[i][2];
			ind = queries[i][3];
			sum += y;
			SET.insert({x,ind});
			arr[ind] = x;
			// cout << "qu : " << x << " " << y << " " << ind << " " << arr[ind] << '\n';
			update(1,1,cnt_upd_queries,mapp[ind],x);
		}
	}
	return;
}

