            b_sum += b;

            insert(a);
        }
        else {
            ll ans = b_sum;

            ans += -left_sum + mid() * left_hirf.size();
            ans += right_sum - mid() * right_hirf.size();

            cout << mid() << ' ' << ans << endl;
        }
    }

