}

ll mid(void)
{
    return *(left_hirf.rbegin());
}

void insert(ll x)
{
    if (left_hirf.empty()) {
        left_sum += x;
        left_hirf.insert(x);
        return;
    }

    if (left_hirf.size() <= right_hirf.size()) {
        if (x > *(left_hirf.rbegin())) {
            right_sum += x;
            right_hirf.insert(x);

            left_sum += x;
            left_hirf.insert(*right_hirf.begin());

            right_sum -= *right_hirf.begin();
            right_hirf.erase(right_hirf.lower_bound(*right_hirf.begin()));
        }
        else {
            left_hirf.insert(x);
            left_sum += x;
        }
    }
    else {
        if (x > *(left_hirf.rbegin())) {
            right_hirf.insert(x);
            right_sum += x;
        }
        else {
            left_sum += x;
            left_hirf.insert(x);

            right_sum += *left_hirf.rbegin();
            right_hirf.insert(*left_hirf.rbegin());

            left_sum -= *left_hirf.rbegin();
            left_hirf.erase(left_hirf.lower_bound(*left_hirf.rbegin()));
        }
    }
}

