			erase(ch[u][d], x);
		}
	} else {
		int d = (x > key[u]);
		erase(ch[u][d], x);
	}
	if (u) update(u);
}
int Rank(int u,int x) {
	if(!u) return 0;
	if(x <= key[u]) return Rank(ch[u][0],x);
	else return sz[ch[u][0]] + 1 + Rank(ch[u][1],x);
}
int zhui(int u, int x){
	if(!u) return 0;
	if (x == sz[ch[u][0]] + 1) return h[u];
	else if (x <= sz[ch[u][0]]) return zhui(ch[u][0], x);
	else return h[ch[u][0]]+zhui(ch[u][1], x - sz[ch[u][0]] - 1);
}
int select(int u,int x) {
	if (x == sz[ch[u][0]] + 1) return key[u];
	else if (x <= sz[ch[u][0]]) return select(ch[u][0], x);
	else return select(ch[u][1], x - sz[ch[u][0]] - 1);
}
void dfs(int u) {
	if (ch[u][0]) dfs(ch[u][0]);
	//cout << key[u] << " ";
	if (ch[u][1]) dfs(ch[u][1]);
}
