class Median {
public:
	//中央値以下の値を管理
	priority_queue<ll> qa;
	//中央値以上の値を管理
	priority_queue<ll, vector<ll>, greater<ll>> qb;

	Median() {}

	void push(ll val) {
		if (qa.size() <= qb.size()) {
			qa.push(val);
		} else {
			qb.push(val);
		}
		while (!qa.empty() && !qb.empty() && qa.top() > qb.top()) {
			ll tmp = qa.top();
			qa.pop();
			qa.push(qb.top());
			qb.pop();
			qb.push(tmp);
		}
	}

	//中央値を返す
	ll query() {
		return qa.top();
	}
	//中央値の小さい方を返す
	ll queryLeft() {
		return qa.top();
	}
	//中央値の大きい方を返す size%2==1のときは中央値より１つ大きい値
	ll queryRight() {
		return qb.top();
	}
};

