			bsum+=b;
			if(count==1){
				qasum+=a;
			}else if(count==2){
				qbsum+=a;
				if(qasum>qbsum)swap(qasum,qbsum);
			}else{
				ll l=median.queryLeft();
				qasum-=l;
				ll r=median.queryRight();
				qbsum-=r;
				vector<ll> v({a, l, r});
				sort(all(v));
				qasum+=v[0];
				qbsum+=v[2];
				if (median.qa.size() <= median.qb.size()) {
					qasum+=v[1];
				} else {
					qbsum+=v[1];
				}
			}
			median.push(a);
		}else{
			ll med=median.query();
			ll ans=bsum;
			ans+=med*median.qa.size()-qasum;
			ans+=qbsum-med*median.qb.size();
