#include <bits/stdc++.h>
using namespace std;
using lint = long long int;

template<class T> class Treap {
    random_device seed;
    mt19937 random;
    T ie;
    function<T(T, T)> f;

    struct Node {
        T value;
        T sum;
        int priority;
        int size = 1;
        Node* l = nullptr;
        Node* r = nullptr;

        Node(T value, int priority) : value(value), priority(priority) {}
    };
    Node* root = nullptr;
    using tree = Node*;

    int size(tree t) {
        return t ? t->size : 0;
    }

    T sum(tree t) {
        return t ? t->sum : ie;
    }

    void update(tree t) {
        if(t) {
            t->size = 1 + size(t->l) + size(t->r);
            t->sum = f(t->value, f(sum(t->l), sum(t->r)));
        }
    }

    // l = [min, bound), r = [bound, max)
    void split(tree t, T bound, tree& l, tree& r) {
        if(!t) {
            l = r = nullptr;
        } else if(t->value < bound) {
            split(t->r, bound, t->r, r), l=t;
        } else {
            split(t->l, bound, l, t->l), r=t;
        }
        update(t);
    }

    // t <- l + r
    void merge(tree l, tree r, tree& t) { 
        if(!l || !r) {
            t = l ? l : r;
        } else if(l->priority < r->priority) {
            merge(l, r->l, r->l), t = r;
        } else {
            merge(l->r, r, l->r), t = l;
        }
        update(t);
    }

    // t <- t + item
    void insert(tree& t, tree item) {
        tree l, r;
        split(t, item->value, l, r);
        merge(item, r, r);
        merge(l, r, t);
    }

    // t <- t - [left, right)
    void erase(tree& t, T left, T right) {
        tree l, r, _;
        split(t, left, l, r);
        split(r, right, _, r);
        merge(l, r, t);
    }

    T at(tree& t, int k) {
        if(size(t->l) == k) {
            return t->value;
        } else if(size(t->l) < k) {
            return at(t->r, k - size(t->l) - 1);
        } else {
            return at(t->l, k);
        }
    }

public:
    Treap() {}
    Treap(T ie, function<T(T, T)> f=plus<T>()) : ie(ie), f(f) {
        random = mt19937(seed());
    }

    void insert(T value) {
        insert(root, new Node(value, random()));
    }

    void erase(T left, T right) {
        erase(root, left, right);
    }

    int size() {
        return size(root);
    }

    // [min, right)
    T query(T right) {
        tree l, r;
        split(root, right, l, r);
        return sum(l);
    }

    // [left, right)
    T query(T left, T right) {
        tree l, r;
        split(root, left, l, r);
        split(r, right, r, l);
        return sum(r);
    }

    T operator[](int k) {
        return at(root, k);
    }
};

int main() {
    lint q;
    cin >> q;

    using P = pair<lint, lint>; // (value, timestamp)
    Treap<P> treap(P(0, 0), [](P a, P b){return P(a.first + b.first, 0);});

    lint timestamp = 0;    
    lint bsum = 0;
    while(q--) {
        lint t;
        cin >> t;

        if(t == 1) {
            lint a, b;
            cin >> a >> b;
            treap.insert({a, timestamp++});
            bsum += b;
        }

        if(t == 2) {
            lint sz = treap.size();
            auto median = treap[(sz-1)/2];

            lint before = treap.query(median).first;
            lint after = treap.query(median, {1e18, 0}).first;

            lint sum = (median.first * (sz-1)/2 - before) 
                     + (after - median.first * (sz - (sz-1)/2))
                     + bsum;

            cout << median.first << " " << sum << endl;
        }
    }
}

