int main(){
    int q; cin>>q;
    priority_queue<int64_t,vector<int64_t>> left;
    priority_queue<int64_t,vector<int64_t>,greater<int64_t>> right;
    int64_t lsum=0,rsum=0;
    int64_t bsum=0;
    while(q--){
        int op; cin>>op;
        int ln=left.size();
        int rn=right.size();
        if(op==1){
            int64_t a,b; cin>>a>>b;
            bsum+=b;
            // leftが1個多くなるように
            if(ln>rn){
                left.push(a);
                lsum+=a;
                int64_t ll=left.top(); left.pop();
                lsum-=ll;
                right.push(ll);
                rsum+=ll;
            }else{
                right.push(a);
                rsum+=a;
                int64_t rr=right.top(); right.pop();
                rsum-=rr;
                left.push(rr);
                lsum+=rr;
            }
        }else{
            int64_t mid=left.top();
            int64_t f=0;
            f+=mid*ln-lsum;
            f+=rsum-mid*rn;
            cout<<mid<<" "<<f+bsum<<endl;
        }
    }
    return 0;
}

