class Solver{
private:
  priority_queue<int> l;
  priority_queue<int, vector<int>, greater<int>> r;

  ll sum_b, m;

  void insert(int a){
    if(l.size() == 0 || a < l.top()){
      l.push(a); l.push(a);
      r.push(l.top()); l.pop();
    } else if(a <= r.top()){
      l.push(a); r.push(a);
    } else {
      r.push(a); r.push(a);
      l.push(r.top()); r.pop();
    }
  }

public:
  Solver(){
    sum_b = m = 0;
  }

  void query1(int a, int b){
    sum_b += b;

    if(l.size() && (a < l.top() || r.top() < a)){
        m += min(abs(a - l.top()), abs(a - r.top()));
    } 

    insert(a);
  }

  void query2(){
    cout << l.top() << " " << m + sum_b << endl;
  }
};

