multiset<ll> left_hirf;
multiset<ll> right_hirf;
ll left_sum;
ll right_sum;
ll b_sum;

ll q;
ll com, a, b;

ll mid(void);
void insert(ll x);

int main()
{
    cin >> q;
    for (int i = 0; i < q; i++) {
        cin >> com;

        if (com == 1) {
            cin >> a >> b;

            b_sum += b;

            insert(a);
        }
        else {
            ll ans = b_sum;
            ll m = mid();

            for (ll x : left_hirf) {
                ans += abs(x - m);
            }
            for (ll x : right_hirf) {
                ans += abs(x - m);
            }

            cout << mid() << ' ' << ans << endl;
        }
    }

    return 0;
}

ll mid(void)
{
    return *(left_hirf.rbegin());
}

void insert(ll x)
{
    left_sum += x;

    left_hirf.insert(x);

    if (left_hirf.size() == right_hirf.size() + 2) {
        left_sum -= *left_hirf.rbegin();
        right_sum += *left_hirf.rbegin();

        right_hirf.insert(*left_hirf.rbegin());
        left_hirf.erase(left_hirf.lower_bound(*left_hirf.rbegin()));
    }
}

