    std::priority_queue<int, std::vector<int>, std::greater<int>> U;
    while(Q--){
        int k; scanf("%d", &k);
        if(k == 1){
            int a, b; scanf("%d%d", &a, &b); B += b;
            if(L.size() == U.size()){
                if(U.empty()){ L.push(a); SL += a; }
                else if(U.top() < a){
                    int v = U.top(); U.pop(); U.push(a); SU += a - v;
                    L.push(v); SL += v;
                }
                else{ L.push(a); SL += a; }
            }
            else{
                if(L.top() > a){
                    int v = L.top(); L.pop(); L.push(a); SL += a - v;
                    U.push(v); SU += v;
                }
                else{ U.push(a); SU += a; }
            }
        }
        else{
            if(L.empty()){ puts("0 0"); continue; }
            int arg = L.top();
            lli val = SU - SL + B; if(L.size() > U.size()) val += arg;
            printf("%d %lld\n", arg, val);
        }
    }
    return 0;
}

