ll sum(ll i, ll *BIT) {
  ll res = 0;
  while (i > 0) {
    res += BIT[i];
    i -= i & (-i);
  }
  return res;
}


void add(ll i, ll x, ll *BIT) {
  while (i <= n) {
    BIT[i] += x;
    i += i & (-i);
  }
}

int binarySearch(int m, ll *BIT = BIT1) {
    int lb = 0, ub = n, mid;
    while ((ub-lb)>1) {
        mid = (lb+ub)/2;
        ll s = sum(mid, BIT);
        if (s < m) {
            lb = mid;
        } else {
            ub = mid;
        }
    }
    return ub;
}

void update(ll a, int idx) {
    add(idx+1, 1, BIT1);
    add(idx+1, a, BIT2);
}

