    cerr << "idx: " << idx << endl;

    ll median = vp[idx-1].fi;
    cout << median << ' ';

    ll ans = sum(n, BIT2) + (2*m-k)*median; 
    ans -= 2*sum(idx, BIT2);
    ans += sumB;

    cout << ans << endl;
}

