ll t_sum[N]; /// <--- Fenwick Tree for sum
ll value[N];

ll prefix_sum(ll p) {
        ll r = 0LL;
        for (ll i = p; i >= 1; i -= i & (-i)) {
                r += t_sum[i];
        }
        return r;
}

void add_sum(ll p, ll x) {
        for (ll i = p; i < N; i += i & (-i)) {
                t_sum[i] += x;
        }
}

ll t_cnt[N]; /// <--- Fenwick Tree for cnt

ll prefix_cnt(ll p) {
        ll r = 0;
        for (ll i = p; i >= 1; i -= i & (-i)) {
                r += t_cnt[i];
        }
        return r;
}

void add_cnt(ll p, ll x) {
        for (ll i = p; i < N; i += i & (-i)) {
                t_cnt[i] += x;
        }
}

ll find_k(ll k) {
        ll r = 0, pas = (1 << 17);
        ll kolbar = 0LL;
        while (pas > 0) {
                if (r + pas < N && t_cnt[r + pas] + kolbar < k) {
                        r += pas;
                        kolbar += t_cnt[r];
                }
                pas >>= 1;
        }
        r++;
        return r;
}

/// Operators for Question :

bool cmp1(Question x, Question y) {
        return x.a < y.a;
}

bool cmp2(Question x, Question y) {
        return x.i < y.i;
}

