template <typename T>
void make_fenwick(vector<T>& nums) {
	for (size_t i = 0; i < nums.size(); ++i) {
		nums[i | (i + 1)] += nums[i];
	}
}

template <typename T>
int64_t fenwick_sum(const vector<T>& fenwick, const int amount) {
	int64_t result = 0;
	int ind = amount - 1;
	for (; ind >= 0; ind = (ind&(ind+1)) - 1) {
		result += fenwick[ind];
	}
	return result;
}

template <typename T>
void fenwick_update(vector<T>& fenwick, int ind, T new_value) {
	T old_val = fenwick_sum(fenwick, ind + 1) - fenwick_sum(fenwick, ind);
	T dif = new_value -  old_val;
	for (; ind < fenwick.size(); ind = (ind | (ind + 1))) {
		fenwick[ind] += dif;
	}
}

