void solve() {
	vector<vector<int>> queries = read_input();
	vector<pair<int, int>> a;
	for (size_t i = 0; i < queries.size(); ++i) {
		if (queries[i][0] == 1) {
			a.push_back({ queries[i][1],(int)i });
		}
	}
	sort(a.begin(), a.end());
	vector<int64_t> fenwick(a.size(), 0);
	vector<int64_t> fenwick_count(a.size(), 0);
	int64_t b_sum = 0;
	int lhs = 0;
	int rhs = 0;
	multiset<int> readed;
	auto it = readed.end();
	//ParamsForMin par = { fenwick ,fenwick_count ,a,0 };
	for (size_t i = 0; i < queries.size(); ++i) {
		if (queries[i][0] == 1) {
			b_sum += queries[i][2];
			int ind = lower_bound(a.begin(), a.end(), pair<int, int>{ queries[i][1], (int)i }) - a.begin();
			fenwick_update(fenwick, ind, (int64_t)queries[i][1]);
			readed.insert(queries[i][1]);
			if (it == readed.end()) {
				it = readed.begin();
			}
			else {
				if (queries[i][1] >= * it) {
					++rhs;
				}
				else {
					++lhs;
				}
				if (lhs < rhs) {
					++lhs;
					--rhs;
					++it;
				}
				if (lhs > rhs) {
					--it;
					--lhs;
					++rhs;
				}
			}
			fenwick_update(fenwick_count, ind, (int64_t)1);
		}
		else {
			int ind = upper_bound(a.begin(), a.end(), pair<int, int>{ *it,-1 }) - a.begin();
			int64_t left = fenwick_sum(fenwick_count, ind) * (*it) - fenwick_sum(fenwick, ind);
			int64_t right = fenwick_sum(fenwick, fenwick.size()) + left - fenwick_sum(fenwick_count, fenwick_count.size()) * (*it);
			cout << *it << " " << left + right + b_sum << "\n";
		}
	}
}

