const int N = 1e5 + 5, OO = 1e9;

struct Node {
	Node *left, *right;
	int cnt;
	long long sum;
	Node() : left(NULL), right(NULL), cnt(0), sum(0) {}
};

void relax(Node *node) {
	if (!node->left)
		node->left = new Node();
	if (!node->right)
		node->right = new Node();
}

void update(Node *node, int idx, int l = -OO, int r = OO) {
	int mid = l + (r - l) / 2;
	if (l > idx || r < idx)
		return;
	relax(node);
	if (idx <= l && r <= idx) {
		++node->cnt;
		node->sum += idx;
		return;
	}
	update(node->left, idx, l, mid);
	update(node->right, idx, mid + 1, r);

	node->cnt = node->left->cnt + node->right->cnt;
	node->sum = node->left->sum + node->right->sum;
}

pair<int, long long> query(Node *node, int x, int y, int l = -OO, int r = OO) {
	int mid = l + (r - l) / 2;
	if (l > y || r < x)
		return {0, 0};
	relax(node);
	if (x <= l && r <= y)
		return {node->cnt, node->sum};
	auto a = query(node->left, x, y, l, mid);
	auto b = query(node->right, x, y, mid + 1, r);
	return {a.first + b.first, a.second + b.second};
}
int main() {
#ifndef ONLINE_JUDGE
//	freopen("input.in", "r", stdin);
#endif
	Node *root = new Node();
	int q;
	scanf("%d", &q);
	long long sumB = 0, sumA = 0;
	int cntA = 0;
	while (q--) {
		int t;
		scanf("%d", &t);
		if (t == 1) {
			int a, b;
			scanf("%d %d", &a, &b);
			sumB += b;
			sumA += a;
			++cntA;
			update(root, a);
		} else {
			int idx = 0;
			long long mn = 1e18;
			for (int i = sumA / cntA; i <= sumA / cntA + 1; ++i) {
				auto a = query(root, i + 1, OO);
				long long cur = a.second - 1LL * a.first * i;
				a = query(root, -OO, i - 1);
				cur += -a.second - 1LL * a.first * -i;
				if (cur < mn) {
					mn = cur;
					idx = i;
				}
			}
			printf("%d %lld\n", idx, mn + sumB);
		}
	}
	return 0;
}

