}

template <class T>
inline void write(T x) {
    if (x < 0) {
        putchar('-');
        x = -x;
    }
    T y = 1;
	int len = 1;
    for (; y <= x / 10; y *= 10) ++len;
    for (; len; --len, x %= y, y /= 10) putchar(x / y + 48);
}

const int MAXN = 2e5;
int q, n;
LL ans;
struct Splay {
    int sum, root, fa[MAXN + 5], cnt[MAXN + 5], val[MAXN + 5], size[MAXN + 5], ch[2][MAXN + 5];

    inline bool check(int x) { return ch[1][fa[x]] == x; }
    inline void pushUp(int x) { size[x] = size[ch[0][x]] + size[ch[1][x]] + cnt[x]; }
    inline void rotate(int x) {
        int a = fa[x], b = fa[a], tx = check(x), ty = check(a), y = ch[tx ^ 1][x];
        ch[tx][a] = y; fa[y] = a;
        ch[ty][b] = x; fa[x] = b;
        ch[tx ^ 1][x] = a; fa[a] = x;
        pushUp(a); pushUp(x);
    }
    inline void splay(int x, int k = 0) {
        while (fa[x] != k) {
            int y = fa[x];
            if (fa[y] != k) {
                if (check(x) == check(y)) rotate(y);
                else rotate(x);
            }
            rotate(x);
        }
        if (!k) root = x;
    }
    inline void insert(int x) {
        int u = root, p = 0;
        while (u && val[u] != x) { p = u; u = ch[x > val[u]][u]; }
        if (u) ++cnt[u];
        else {
            u = ++sum;
            ch[x > val[p]][p] = u;
            ch[0][u] = ch[1][u] = 0;
            fa[u] = p; val[u] = x;
            cnt[u] = size[u] = 1;
        }
        splay(u);
    }
    inline void find(int x) {
        int u = root;
        while (x != val[u] && ch[x > val[u]][u]) u = ch[x > val[u]][u];
        splay(u);
    }
    inline int kth(int k) {
        int u = root;
        while (1) {
            if (ch[0][u] && k <= size[ch[0][u]]) u = ch[0][u];
            else if (k > size[ch[0][u]] + cnt[u]) { k -= size[ch[0][u]] + cnt[u]; u = ch[1][u]; }
            else return val[u];
        }
    }
} bst;

int main() {
	bst.insert(0x7fffffff), bst.insert(-0x7fffffff);
	read(q);
	for (int opt, a, b, i = 1; i <= q; ++i) {
		read(opt);
		if (opt == 1) {
			read(a), read(b);
			ans += b;
			if (!n) {
				++n;
				bst.insert(a);
			} else {
				int c = bst.kth((n + 1) / 2 + 1);
				++n;
				bst.insert(a);
				ans += abs(c - a);
			}
		} else {
			int c = bst.kth((n + 1) / 2 + 1);
			write(c);
			putchar(' ');
			write(ans); 
			putchar('\n'); 
		}
	}
	return 0;
}

