multiset<int> pre,post;
int ans = 0;
int sum[2] = {0,0};

void solve() {
    cin>>Q;
    int t,a,b;
    while(Q--) {
        cin>>t;
        if (t==1) {
            cin>>a>>b;
            ans += b;
            if (pre.empty()) {
                pre.insert(a);
                sum[0] = a;
                continue;
            }
            if (pre.size()==post.size()) {
                auto it = post.begin();
                if (*it < a) {
                    post.erase(it);
                    post.insert(a);
                    pre.insert(*it);
                    sum[1] += a-*it;
                    sum[0] += *it;
                } else {
                    pre.insert(a);
                    sum[0] += a;
                }
                continue;
            }
            // pre.size() > post.size()
            auto it = pre.end();
            it--;
            if (a < *it) {
                pre.erase(it);
                pre.insert(a);
                post.insert(*it);
                sum[0] += a - *it;
                sum[1] += *it;
            } else {
                post.insert(a);
                sum[1]+=a;
            }
        } else {
            int x = *(pre.rbegin());
            int s = ans + pre.size()*x - sum[0] + sum[1] - post.size()*x;
            _PN(x,s);
        }
    }
}

