using namespace std;
template< typename T >
class segment_tree {
	public:
	const vector<long long> coord;
	const map<long long, long long> mp;
	const long long sz;
	const long long Sz;
	vector<T> seg;
	const function<T(T, T)> o;
	const T id;

		segment_tree (
				const vector<long long> coord,
				const function<T(T, T)> o,
				const T id
			) :
			coord([&](){
					vector<long long> v = coord;
					long long p = 1;
					for (; p < (long long)v.size(); p <<= 1) {}
					v.resize(p, (long long)((1LL << 31) - 1));
					return v;
				}()),
			mp([&](){
					map<long long, long long> m;
					long long i = 0;
					for (auto const& e : coord) {
						m[e] = i++;
					}
					return m;
				}()),
			sz([&](){
					int ret = 1;
					for (; ret < (int)coord.size(); ret <<= 1) {}
					return ret;
				}()),
			Sz(sz << 1),
			seg(Sz, id),
			o(o),
			id(id)
			{
			}

		void update (long long k, const T& x) {
			auto it = mp.find(k);
			assert(it != mp.end());
			k = it->second;
			k += sz;
			seg[k] = x;
			while(k >>= 1) {
				seg[k] = o(seg[2 * k], seg[2 * k + 1]);
			}
		}
		void add (long long k, const T& x) {
			update(k, x + at(k));
		}
		T query (long long l, long long r) {
			l = lower_bound(coord.begin(), coord.end(), l) - coord.begin();
			r = lower_bound(coord.begin(), coord.end(), r) - coord.begin();
			T L = id, R = id;
			for(l += sz, r += sz; l < r; l >>= 1, r >>= 1) {
				if(l & 1) L = o(L, seg[l++]);
				if(r & 1) R = o(seg[--r], R);
			}
			return o(L, R);
		}
		T at (long long k) const {
			auto it = mp.find(k);
			assert(it != mp.end());
			return seg[it->second + sz];
		}
};
int main() {
	const long long inf = 1e17;
	cin.tie(0); cin.sync_with_stdio(false);
	long long q;
	cin >> q;
	vector<tuple<long long, long long, long long>> query;
	vector<long long> a;
	while (q--) {
		long long c;
		cin >> c;
		if (c == 1) {
			long long x, y;
			cin >> x >> y;
			query.emplace_back(1, x, y);
			a.push_back(x);
		} else {
			query.emplace_back(2, 0, 0);
		}
	}
	sort(a.begin(), a.end());
	a = decltype(a)(a.begin(), unique(a.begin(), a.end()));
	segment_tree<long long> sgt(
		a,
		[](long long x, long long y) {return x + y;},
		0
	);
	long long base = 0;
	for (auto const& p : query) {
		long long c, x, y; tie(c, x, y) = p;
		if (c == 1) {
			sgt.add(x, 1);
			base += y;
		}
		else {
			long long n = sgt.query(-inf, inf);
			long long m = (n + 1) >> 1;
			long long ok = -inf, ng = inf, md;
			while (ng - ok > 1) {
				md = (ok + ng) >> 1;
				if (sgt.query(-inf, md + 1) < m) ok = md;
				else ng = md;
			}
			cout << ng << " ";
			long long ret = base;
			if (!(n & 1)) {
				ret -= ng;
				ok = -inf, ng = inf;
				while (ng - ok > 1) {
					md = (ok + ng) >> 1;
					if (sgt.query(-inf, md + 1) < m + 1) ok = md;
					else ng = md;
				}
				ret += ng;
			}
			cout << ret << endl;
		}
	}
	return 0;	
}

