using namespace std;
template< typename T >
class segment_tree {
	const vector<long long> coord;
	const map<long long, long long> mp;
	const long long sz;
	const long long Sz;
	vector<T> seg;
	const function<T(T, T)> o;
	const T id;

	public:
		segment_tree (
				const vector<long long> coord,
				const function<T(T, T)> o,
				const T id
			) :
			coord([&](){
					vector<long long> v = coord;
					long long p = 1;
					for (; p < (long long)v.size(); p <<= 1) {}
					v.resize(p, (long long)((1LL << 31) - 1));
					return v;
				}()),
			mp([&](){
					map<long long, long long> m;
					long long i = 0;
					for (auto const& e : coord) {
						m[e] = i++;
					}
					return m;
				}()),
			sz(coord.size()),
			Sz(sz << 1),
			seg(Sz, id),
			o(o),
			id(id)
			{
			}

		void update (long long k, const T& x) {
			auto it = mp.find(k);
			assert(it != mp.end());
			k = it->second;
			k += sz;
			seg[k] = x;
			while(k >>= 1) {
				seg[k] = o(seg[2 * k], seg[2 * k + 1]);
			}
		}
		void add (long long k, const T& x) {
			update(k, x + at(k));
		}
		T query (long long l, long long r) {
			l = lower_bound(coord.begin(), coord.end(), l) - coord.begin();
			r = lower_bound(coord.begin(), coord.end(), r) - coord.begin();
			T L = id, R = id;
			for(l += sz, r += sz; l < r; l >>= 1, r >>= 1) {
				if(l & 1) L = o(L, seg[l++]);
				if(r & 1) R = o(seg[--r], R);
			}
			return o(L, R);
		}
		T at (long long k) const {
			auto it = mp.find(k);
			assert(it != mp.end());
			return seg[it->second + sz];
		}
};
