void swap(int *a,int *b){
	int temp=*a;
	*a=*b;
	*b=temp;
}
void quicksort(int a[],int lower,int upper){
	int bound=a[lower],l=lower,u=upper;
	do{
		while(a[l]<bound)l++;
		while(a[u]>bound)u--;
		if(l<=u){
			swap(&a[l],&a[u]);
			l++;
			u--;
		}
	}while(l<u);
	if(lower<u)quicksort(a,lower,u);
	if(l<upper)quicksort(a,l,upper);
}
