/*
      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
const size_t MAX_BIT = 160 * 160 + 10;
typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;

void solve(){
    // generate_array(size, min, max);
    ll Q; in1(Q);
    ll exc = 0, l = 0, u = 0, m = 0;
    pq ql; pql qu; ll cur = 0;

    auto update = [&](ll a) -> void{
        if (cur == 1) m = a;
        else if (cur == 2){
            if (a < m) ql.push(a), qu.push(m), l = a, u = m;
            else ql.push(m), qu.push(a), l = m, u = a;
        }else if (cur % 2 == 0){
            ll lt = ql.top(), ub = qu.top();
            if (a < lt) m = lt, ql.pop(), ql.push(a), l += a - m;
            else m = ub, qu.pop(), qu.push(a), u += a - m;
        }else{
            ll lt = ql.top(), ub = qu.top();
            if (a < m) ql.push(a), qu.push(m), l += a, u += m;
            else ql.push(m), qu.push(a), l += m, u += a;
        }
    };

    rep(i, Q){
        ll mode; in1(mode);
        if (mode == 1){
            ll a, b; in2(a, b);
            exc += b; cur++; update(a);
        }else{
            if (cur % 2) prl2(m, u - l + exc);
            else prl2(ql.top(), u - l + exc);
        }
    }

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

