typedef long long ll;
const ll INF = 1e18;

int main(){
    int q;
    cin >> q;
    ll s0=0,s1=0;
    priority_queue<ll> left;
    priority_queue<ll,vector<ll>,greater<>> right;

    left.push(-INF);
    right.push(INF);

    for(int i = 0;i < q;i ++){
        int que;
        cin >> que;
        if(que==1){
            ll a,b;
            cin >> a >> b;
            s1 += b;

            if(left.size()==right.size()){ 
                if(a<left.top() || a>right.top())
                    s0 += min(abs(left.top()-a),abs(a-right.top()));
            }else{
                s0 += abs(left.top()-a);
            }

            if(a>=right.top()) right.push(a);
            else left.push(a);

            if(right.size()>left.size()){
                left.push(right.top());
                right.pop();
            }else if(left.size()>right.size()+1){
                right.push(left.top());
                left.pop();
            }
        }else{
            cout << left.top() << " " << s0 + s1 << endl;
        }
    }
    return 0;
}

