int fibonacci_mod_L(unsigned long long n, int md){
  unsigned long long a=1, b=0, c=1, ma=1, mb=1, mc=0, ta, tb, tc;
  while(n){
    if(n%2){
      ta = a*ma + b*mb;
      tb = a*mb + b*mc;
      tc = b*mb + c*mc;
      a = ta % md;
      b = tb % md;
      c = tc % md;
    }
    ta = ma*ma + mb*mb;
    tb = ma*mb + mb*mc;
    tc = mb*mb + mc*mc;
    ma = ta % md;
    mb = tb % md;
    mc = tc % md;
    n/=2;
  }
  return b;
}
