using T = long long;

class xorshift{
private:
    uint64_t x;
public:
    xorshift(){
        random_device rnd;
        mt19937 mt(rnd());
        x = mt();
        for(int i = 0; i < 50; i++){
            random();
        }
    }
    uint64_t random(){
        x = x ^ (x << 7);
        return x = x ^ (x >> 9);
    }
};



struct SumMonoid{
    static constexpr T id(){
        return 0;
    }
    static T op(T a, T b){
        return a + b;
    }
};

struct MinMonoid{
    static constexpr T id(){
        return INF;
    }
    static T op(T a, T b){
        return min(a, b);
    }
};

struct MaxMonoid{
    static constexpr T id(){
        return -INF;
    }
    static T op(T a, T b){
        return max(a, b);
    }
};

struct UpdateMonoid{
    static constexpr T id(){
        return INF;
    }
    static T op(T a, T b){
        return b;
    }
};



// RSQ
struct Modifier{
    static T op(T a, T b, int sz){
        return b == UpdateMonoid::id() ? a : b * sz;
    }
};

