			root = insertNode(a, root);
		}
		else {
			pair<long long int, long long int> p = searchNode((num - 1) / 2 + 1, root, 0);
			int n = (num - 1) / 2 + 1;
			// cout << p.second << endl;
			cout << p.first << " " << (n * p.first - p.second) - (num - n) * p.first + as - p.second + bs << endl;
		}
	}

}

