      }
      else if (R.empty())
      {
        if (a < L.top())
        {
          Rs += L.top();
          R.push(L.top());
          Ls -= L.top();
          L.pop();
          Ls += a;
          L.push(a);
        }
        else
        {
          Rs += a;
          R.push(a);
        }
      }
      else if (a < L.top())
      {
        Rs += L.top();
        R.push(L.top());
        Ls -= L.top();
        L.pop();
        Ls += a;
        L.push(a);
      }
