int COUNT(long long int K) {

	int D, U;
	if (S.count(K) != 0) {
		auto it = S.find(K);
		U = distance(it, S.end())-S.count(K); 
	}
	else {
		S.insert(K);
		auto it = S.find(K);
		it++;
		U = distance(it, S.end());
		S.erase(K);
	}

	D = S.size() - U;

	//cout << "K= " << K << " U= " << U <<" D= " << D<< endl;

	return D-U;
}

long long int BINARY_SEARCH(void) {

	long long int left = -100000000002;
	long long int right = 1000000000003;

	long long int med;

	while (right - left > 1) {
		med = (right + left) / 2;
		if (COUNT(med) >= 0) { right = med; }
		else { left = med; }
	}

	return right;
}


