int main()
{
    int q;
    cin >> q;
    priority_queue<long long int> firstHalf;
    priority_queue<long long int, vector<long long int>, greater<long long int> > secondHalf;
    long long int firstHalfSum = 0, secondHalfSum = 0;
    long long int sum = 0;
    while(q--)
    {
        int type;
        cin >> type;
        if(type == 1)
        {
            long long int a, b;
            cin >> b >> a;
            sum += a;
            if(firstHalf.size() == 0)
            {
                firstHalf.push(b);
                firstHalfSum += b;
                continue;
            }
            if(firstHalf.size() == secondHalf.size())
            {
                long long int tp1 = firstHalf.top();
                long long int tp2 = secondHalf.top();
                if(b <= tp2)
                {
                    firstHalf.push(b);
                    firstHalfSum += b;
                }
                else
                {
                    firstHalf.push(secondHalf.top());
                    firstHalfSum += secondHalf.top();

                    secondHalfSum -= secondHalf.top();
                    secondHalfSum -= secondHalf.top();
                    secondHalf.pop();

                    secondHalf.push(b);
                    secondHalfSum += b;
                }
            }
            else if(firstHalf.size() > secondHalf.size())
            {
                long long int tp = firstHalf.top();
                if(b >= tp)
                {
                    secondHalf.push(b);
                    secondHalfSum += b;
                }
                else
                {
                    secondHalf.push(firstHalf.top());
                    secondHalfSum += firstHalf.top();

                    firstHalfSum -= firstHalf.top();
                    firstHalf.pop();

                    firstHalf.push(b);
                    firstHalfSum += b;
                }
            }
        }
        else
        {
            long long int sizee = firstHalf.size();
            sizee--;
            long long int sizee2 = secondHalf.size();
            long long int tp = firstHalf.top();
            long long int tmp = (tp * sizee) - (firstHalfSum - tp);
            tmp += ((secondHalfSum) - (tp*sizee2));
            cout << tp << " " << tmp + sum << endl;
        }
    }
    return 0;
}

