	ll lsum=0,hsum=0,bsum=0;
	while(q--){
		int t,a,b;
		cin >> t;
		if(t == 2){
			ll med = (low.size()>=high.size()?low.top():high.top());
			ll val = low.size() * med - lsum + hsum - high.size() * med;
			cout << med << " " << val + bsum << '\n';
		}
		else{
			cin >> a >> b;
			bsum += b;
			ll med = (low.size() + high.size() != 0?(low.size()>=high.size()?low.top():high.top()):0);
