			b_sum += b;

			if (_q == 0)
				mid = a;
			else {
				if (a < mid)
					left_pq.push(a);
				else
					right_pq.push(a);
			}


		}
		else if (task == 2)
		{
			if (left_pq.size() + 1 < right_pq.size())
				while (left_pq.size() + 1 < right_pq.size()) {
					left_pq.push(mid);
					mid = right_pq.top();
					right_pq.pop();
				}
			else if (left_pq.size() > right_pq.size())
