                }
            }
            else if(left.size() <= right.size()) {
                if(a <= right.top()) {
                    lsum += a; left.push(a);
                }
                else {
                    // right.top()をleftに移す
                    lsum += right.top(); rsum -= right.top();
                    left.push(right.top()); right.pop();
                    // aをrightに
                    rsum += a; right.push(a);
