int main()
{
  ll Q;
  cin >> Q;
  priority_queue<ll> head;
  priority_queue<ll, vector<ll>, greater<ll>> back;
  ll head_sum = 0, back_sum = 0, sum = 0;
  for (ll i = 0; i < Q; ++i) {
    ll q, a, b;
    cin >> q;
    if (q == 1) {
      cin >> a >> b;
      sum += b;
      if (head.size() == 0) {
        head_sum += a;
        head.push(a);
        continue;
      }
      if (head.size() > back.size()) {
        ll head_last = head.top();
        if (head_last > a) {
          head_sum -= head_last;
          head_sum += a;
          back_sum += head_last;
          head.pop();
          head.push(a);
          back.push(head_last);
        }
        else {
          back.push(a);
          back_sum += a;
        }
      }
      else {
        ll back_first = back.top();
        if (back_first < a) {
          back_sum -= back_first;
          back_sum += a;
          head_sum += back_first;
          back.pop();
          back.push(a);
          head.push(back_first);
        }
        else {
          head_sum += a;
          head.push(a);
        }
      }
    }
    else {
      ll mid = head.top();
      ll ans = head_sum - mid * head.size() + back_sum - mid * back.size() + sum;
      cout << mid << " ";
      cout << ans << "\n";
    }
  }
}

