const ll MAX_N = 2e5 + 10;
ll n;
ll fenSum[MAX_N];
ll cnt[MAX_N];
pii Query[MAX_N];

ll Arr[MAX_N];
ll ind;

ll Map (ll d) {
	return lower_bound(Arr, Arr + ind, d) - Arr + 1;
}

void upd (ll d) {
	ll tmp = d;
	for (; tmp < MAX_N; tmp += tmp & -tmp) {
		fenSum[tmp] += Arr[d - 1];
		cnt[tmp]++;
	}
}

ll getNum (ll d) {
	ll c = 0, pointer = 0;
	for (ll i = 20; ~i; i--)
		if ((pointer | (1 << i)) < MAX_N && c + cnt[pointer | (1 << i)] < d) {
			pointer |= (1 << i);
			c += cnt[pointer];
		}

	return pointer + 1;
}

ll getSum (ll d) {
	ll res = 0;
	for (; d; d -= d & -d)
		res += fenSum[d];

	return res;
}

ll getCnt (ll d) {
	ll res = 0;
	for (; d; d -= d & -d)
		res += cnt[d];

	return res;
}

int main() {
	ios::sync_with_stdio(false), cin.tie(0);
	cin >> n;
	for (ll i = 0; i < n; i++) {
		ll type;
		cin >> type;

		Query[i] = {-1, -1};
		if (type == 1) {
			ll a, b;
			cin >> a >> b;

			Query[i] = {a, b};
			Arr[ind++] = a;
		}
	}

	sort(Arr, Arr + ind);
	ind = unique(Arr, Arr + ind) - Arr;

	ll num = 0;
	ll val = 0;

	for (ll i = 0; i < n; i++) {
		if (Query[i].first != -1) {
			upd(Map(Query[i].first));
			val += Query[i].second;
			num++;
		}
		else {
			ll tmp = getNum((num + 1) / 2);
			ll calc = getCnt(tmp) * Arr[tmp - 1] - getSum(tmp);
			calc += (getSum(MAX_N - 1) - getSum(tmp)) - (num - getCnt(tmp)) * Arr[tmp - 1];
			cout << Arr[tmp - 1] << " " << val + calc << "\n";
		}
	}
	return 0;
}

