 while (index != midPos)
 {
 index = partitio(arra, left, right);

 if (index < midPos)
 {
  left = index + 1;
 }
 else if (index > midPos)
 {
  right = index - 1;
 }
 else
 {
  break;
 }
 }

 assert(index == midPos);
 return arra[index];
}
