using namespace std;

#define ll long long
#define N 200005

int type[N];
int a[N],b[N];

ll cc[N],sum[N];

void update(ll *pen,int ind,ll val) {
  while(ind<N) {
    pen[ind] += val;
    ind += ind&(-ind);
  }
}

ll val[N];
ll query(ll *pen,int ind) {
  ll ret = 0;
  while(ind>0) {
    ret += pen[ind];
    ind = ind&(ind-1);
  }
  return ret;
}
void solve() {
  int Q;scanf("%d ", &Q);
  map<int,int> Hash;
  for(int i=0;i<Q;++i) {
    scanf("%d ", &type[i]);
    if(type[i]==1) {
      scanf("%d %d ", &a[i],&b[i]);
      Hash[a[i]];
    }
  }
  int pos=0;
  for(map<int,int>::iterator it = Hash.begin();it!= Hash.end();++it) {
    it->second = ++pos;
    val[pos] = it->first;
  }
  long long sumOfB = 0;
  int numTypeOne = 0;
  set<int> s;

  for(int i=0;i<Q;++i) {
    if(type[i]==1) {
      sumOfB += b[i];
      int aId = Hash[a[i]];
      update(cc,aId,1);
      update(sum,aId,a[i]);
      s.insert(a[i]);
      ++numTypeOne;
    } else {
      int l = 1 , r= pos,mid;
      while(l<r) {
        mid = (l+r)/2;
        if(query(cc,mid)*2>numTypeOne) {
          r = mid;
        } else {
          l = mid+1;
        }
      }
      ll R = 4e18;ll k=1e18;
      set<int>::iterator it = s.lower_bound(val[l]);
      if(it!=s.end()) {
        int numCount = 2;
        while(numCount>0 && it!= s.end()) {
          ll v = *it;
          int xx = Hash[v];
          ll numLow = query(cc,xx);
          ll sumLow = query(sum,xx);
          ll numHigh = numTypeOne-numLow, sumHigh = query(sum,N-1) - sumLow;
          ll tmp = numLow*v - sumLow + sumHigh - numHigh*v;
          if(R>=tmp) {
            if(R==tmp) {
              k = min(k,v);
            } else {
              R = tmp;
              k = v;
            }
          }
          --numCount;
          ++it;
        }
      }
      it = s.lower_bound(val[l]);
      if(it!=s.begin()) {
        --it;
        int numCount = 2;
        while(numCount>0 ) {
          ll v = *it;
          int xx = Hash[v];
          ll numLow = query(cc,xx);
          ll sumLow = query(sum,xx);
          ll numHigh = numTypeOne-numLow, sumHigh = query(sum,N-1) - sumLow;
          ll tmp = numLow*v - sumLow + sumHigh - numHigh*v;
          if(R>=tmp) {
            if(R==tmp) {
              k = min(k,v);
            } else {
              R = tmp;
              k = v;
            }
          }
          if(it==s.begin()) {
            break;
          }
          --numCount;
          --it;
        }
      }
      printf("%lld %lld\n",k, R + sumOfB);
    }
  }
}

