			cin >> a[i] >> b[i];
			ca.push_back(a[i]);
		}
	}
	sort(ca.begin(), ca.end());
	ta = ca;
	int S = ca.size();
	fenwick_tree<long long> bita(S), bitb(S);
	long long sb = 0;
	int cnt = 0;
	for (int i = 0; i < Q; ++i) {
		if (tp[i] == 1) {
			int ptr = lower_bound(ta.begin(), ta.end(), a[i]) - ta.begin();
			sb += b[i];
			bita.add(ptr, 1);
			bitb.add(ptr, a[i]);
			--ta[ptr];
			++cnt;
		}
		else {
			int ptr = bita.binary_search((cnt + 1) / 2);
			long long ans = 0;
			if (cnt % 2 == 0) {
				ans = bitb.getsum(ptr, S) - bitb.getsum(0, ptr);
			}
			else {
				ans = bitb.getsum(ptr, S) - bitb.getsum(0, ptr - 1);
			}
			cout << ca[ptr - 1] << ' ' << ans + sb << '\n';
		}
	}
