        if (a[i] == 1) cin >> b[i] >> c[i];
    }

    vector<ll> S;
    rep(i, Q) {
        if (a[i] == 1) S.push_back(b[i]);
    }
    sort(ALL(S));
    map<ll, int> mp;
    mp[S[0]] = 0;
    REP(i, SZ(S)) {
        if (S[i - 1] == S[i]) continue;
        mp[S[i]] = mp[S[i - 1]] + 1;
    }
    vector<ll> T(Q, 0);
    for (auto p : mp) T[p.second] = p.first;

    int cnt = 0;
    vector<int> C(Q, 0);
    FenwickTree FT1(Q), FT2(Q);
    ll sum = 0;
    rep(i, Q) {
        if (a[i] == 1) {
            sum += b[i] + c[i];
            FT1.add(mp[b[i]], 1);
            FT2.add(mp[b[i]], b[i]);
            ++C[mp[b[i]]];
            ++cnt;
        } else {
            int idx = FT1.lowerBound((cnt + 1) / 2);
            --idx;
            cout << T[idx] << " ";
            cout << sum + 2 * FT2.getsum(idx) - T[idx] * cnt << "\n";
