class OnlineMedian {
 private:
  priority_queue<int64, vector<int64>, less<int64>> pq_less;
  priority_queue<int64, vector<int64>, greater<int64>> pq_greater;
 public:
  void Add(int64 x) {
    if (pq_less.empty() || x <= pq_less.top()) {
      pq_less.push(x); pq_less.push(x);
    } else {
      pq_greater.push(x); pq_greater.push(x);
    }
    if (pq_less.size() > pq_greater.size()) {
      int64 t = pq_less.top(); pq_less.pop(); pq_greater.push(t);
    } else if (pq_greater.size() > pq_less.size()) {
      int64 t = pq_greater.top(); pq_greater.pop(); pq_less.push(t);
    }
  }
  // Returns a median. When there are two, returns a less one.
  int64 LessMedian() { return pq_less.top(); }
  // Returns a median. When there are two, returns a greater one.
  int64 GreaterMedian() { return pq_greater.top(); }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int num_queries;
  cin >> num_queries;

  OnlineMedian online_median;
  int64 absolute_sum = 0;
  int64 base = 0;
  for (int i = 0; i < num_queries; i++) {
    int command;
    cin >> command;
    if (command == 1) {
      int64 a, b;
      cin >> a >> b;

      base += b;

      online_median.Add(a);

      if (a > online_median.GreaterMedian()) {
        absolute_sum += a - online_median.GreaterMedian();
      } else if (a < online_median.LessMedian()) {
        absolute_sum += online_median.LessMedian() - a;
      }
    } else {
      // Output
      cout << online_median.LessMedian() << " "
          << absolute_sum + base << endl;
    }
  } 
}

