            v.push_back({1,{a,b}});
            mp[a].push_back(1);
        }else{
            v.push_back({0,{0,0}});
        }
    }
    int cnt=1;
    for (auto&i:mp) {
        rep(j,i.second.size()){
            i.second[j]=cnt;
            gya[cnt]=i.first;
            cnt++;
        }
    }
    cnt=0;
    rep(i,q){
        if (v[i].first) {
            bits.add(mp[v[i].second.first].back(), 1);
//            cout<<mp[v[i].second.first]<<endl;
            seg.change(mp[v[i].second.first].back(), v[i].second.first);
            mp[v[i].second.first].pop_back();
            cnt++;
            b+=v[i].second.second;
        }else{
            int l=1,r=q;
            while (l+1!=r) {
                int m=(l+r)/2;
                int c=bits.sum(m-1);
//                cout<<bits.sum(1)<<endl;
                int k=cnt-c;
                if (k>=(cnt+2)/2) {
                    l=m;
                }else{
                    r=m;
                }
            }
            int c=bits.sum(l-1);
            int k=cnt-c;
            int ans=gya[l]*c-seg.query(0, l);
            ans+=seg.query(l, q+1)-gya[l]*k;
            cout<<gya[l]<<' '<<ans+b<<endl;
        }
    }
}

