using Size = int;
template<typename T> class SegmentTree {
 public:
  SegmentTree(Size N) : N(size(N)), node_(2 * size(N) - 1) {}
  void add(Size i, T v) {
    i += N - 1;
    node_[i] += v;
    while(i != parent(i)) {
      i = parent(i);
      node_[i] = node_[lchild(i)] + node_[rchild(i)];
    }
  }
  T sum(Size a, Size b) const {return sum(a, b, 0, 0, N);}
 private:
  constexpr Size pop_lsb(Size N) const {return N & (N - 1);}
  constexpr Size msb(Size N) const {while(pop_lsb(N)) N = pop_lsb(N); return N;}
  constexpr Size size(Size N) const {return pop_lsb(N) ? msb(N) << 1 : N;}
  inline Size parent(Size n) const {return (n - 1) / 2;}
  inline Size lchild(Size n) const {return 2 * n + 1;}
  inline Size rchild(Size n) const {return 2 * n + 2;}
  T sum(Size a, Size b, Size k, Size l, Size r) const {
    if(b <= l || r <= a) return 0;
    if(a <= l && r <= b) return node_[k];
    auto m = (l + r) / 2;
    return sum(a, b, lchild(k), l, m) + sum(a, b, rchild(k), m, r);
  }
  const Size N;
  std::vector<T> node_;
};

#include<bits/stdc++.h>
using namespace std;

int main() {
  using LL = long long;
  struct Query {LL n, a, b;};
  LL D = 1e9 + 1;

  int N;
  cin >> N;

  vector<Query> Q(N);
  for(auto& q: Q) {
    cin >> q.n;
    if(q.n == 1) cin >> q.a >> q.b;
  }

  vector<LL> p = {0, LL(1e9+D)};
  for(auto& q: Q) q.a += D;
  for(const auto& q: Q) if(q.n == 1) p.emplace_back(q.a);
  Compression<LL> comp(p);

  SegmentTree<LL> sum(comp.size()+1), num(comp.size()+1);
  auto f = [&](auto i) {
    auto x = comp[i];
    return x*num.sum(0, i)-sum.sum(0, i) + sum.sum(i+1, comp.size())-x*num.sum(i+1, comp.size());
  };
  LL c = 0;
  for(const auto& q: Q) {
    if(q.n == 1) {
      c += q.b;
      sum.add(comp.index(q.a), abs(q.a));
      num.add(comp.index(q.a), 1);
    } else {
      LL l = 0, h = comp.size()-1;
      while(1 < h-l) {
        LL m = (l+h)/2;
        if(f(m)-f(m-1) < 0) l = m;
        else                h = m;
      }
      cout << comp[l]-D << " " << f(l)+c << endl;
    }
  }
}

