int main(){
    int q; cin>>q;
    priority_queue<long, vector<long>, greater<long> > L, R; long c = 0; int k = 0;
    long lsum,rsum,bsum; lsum=rsum=bsum=0;
    rep(i,q){
        int flag; cin>>flag;
        if(flag == 1){
            long a,b; cin>>a>>b;
            k++;
            bsum += b;
            if (k%2 == 0){
                if (a < c){
                    L.push(-a); R.push(c);
                    lsum -= a; rsum += c;
                }
                else{
                    L.push(-c); R.push(a);
                    lsum -= c; rsum += a;
                }
            }
            else if(!L.empty()){
                long lmax = -L.top(); long rmin = R.top();
                if(a < lmax){
                    L.pop(); L.push(-a); c = lmax;
                    lsum -= (a-lmax);
                }
                else if(rmin < a){
                    R.pop(); R.push(a); c = rmin;
                    rsum += (a-rmin);
                }
                else c = a;
            }
            else c = a;
        }
        else{
            long arg, val;
            if (k%2 == 0) arg = -L.top();
            else arg = c;
            val = lsum + rsum + bsum;
            cout << arg << " " << val << endl;
        }
    }
}

