		if(q==1){
			int a,b;
			cin>>a>>b;
			query.push_back({1,a,b});
			ind.push_back(a);
		}else{
			query.push_back({2});
		}
	}
	sort(ALL(ind));
	ind.erase(unique(ALL(ind)),ind.end());
	st = SegmentTree<pair<int,Int> >(ind.size()+1,{0,0},append);
	REP(i,Q){
		auto q = query[i];
		if(q[0]==1){
			Int a = q[1], b = q[2];
			a_num++;
			a_sum += a;
			b_sum += b;
			int t = lower_bound(ALL(ind),(int)a) - ind.begin();
			st.point_update(t,{1,a});
		}else{
			int l = 0, r = ind.size();
			Int lval = calc(l), rval = calc(r);
			while(r-l>=3){
				int d = (r-l)/3;
				int l1 = l + d, r1 = r - d;
				Int l1val = calc(l1), r1val = calc(r1);
				if(l1val<=r1val){
					r = r1;
					rval = r1val;
				}else{
					l = l1;
					lval = l1val;
				}
			}
			Int ans = inf<Int>();
			int ans_i = -1;
			for(int i = l; i <= r;i++){
				Int v = calc(i);
				if(v < ans)ans = v, ans_i = i;
			}
			cout<<ind[ans_i]<<" "<<ans<<endl;
		}
	}
}

