class BIT   // 1-indexed (0 is not used)
{
private:
    int num;
    vector<ll> bit;
public:
    BIT(int n):bit(vector<ll>(n+1, 0)), num(n) {}

    ll sum(int i) {   // sum of 1..i
        if (!i) return 0;
        return bit[i] + sum(i-(i&-i));
    }

    void add(int i, ll x) {
        if (i > num) return;
        bit[i] += x;
        add(i+(i&-i), x);
    }
};


