int solve(){
    ll sumB=0;
    int n=0;
    ll mid=0;
    ll f=0;
    multiset<ll> se;
    vector<pair<int,ll>> ans;
    for (int i = 0; i < Q; i++)
    {
        int q;
        cin >> q;
        if(q==1){
            n++;
            ll a,b;
            cin >> a >> b;
            se.insert(a);
            sumB+=b;
            if(n==1){mid = a;}
            else if(n%2==0 && a<mid){
                // a1 a2 a3 からanの追加
                // a a1 a2 a3 mid=a2→a1の場合とか
                f+=abs(mid-a);
                auto itr = se.find(mid);
                ll mid_tmp = max(a,*(--itr));
                // f+=abs(mid-mid_tmp);
                mid = mid_tmp;
            }
            else if(n%2==1 && a>mid){
                f+=abs(mid-a);
                auto itr = se.find(mid);
                ll mid_tmp = max(a,*(++itr));
                f+=(mid-mid_tmp);
                mid = mid_tmp;
            }
            else{f+=abs(mid-a);}
        }
        else{
            ans.emplace_back(mid,f+sumB);
        }
    }

    for(auto a:ans) cout << a.first << " " << a.second << "\n";
    return 0;
}

