struct q
{
	ll t,a,b;
};

vector <q> query;
vector <ll> cor;

ll segTree[200001];
void update(int i, ll v)
{
	while (i <= 200001)
	{
		segTree[i] += v;
		i += i & -i;
	}
}

ll getVal(int i)
{
	ll res = 0;
	while (i)
	{
		res += segTree[i];
		i -= i & -i;
	}
	return res;
}

ll getVal(int i, int j)
{
	return getVal(j) - getVal(i - 1);
}

int sz = 447;
int cnt[250001];
int bucket[448];

int getIndex(ll a)
{
	return lower_bound(cor.begin(),cor.end(),a) - cor.begin() + 1;
}

int main()
{
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);

	int Q; cin >> Q;
	while (Q--)
	{
		q cq;
		cin >> cq.t;
		if (cq.t == 1)
		{
			cin >> cq.a >> cq.b;
			cor.push_back(cq.a);
		}

		query.push_back(cq);
	}

	sort(cor.begin(), cor.end());
	cor.erase(unique(cor.begin(), cor.end()), cor.end());

	int csz = 0;
	ll curB = 0;
	for (int i = 0; i < query.size(); i++)
	{
		if (query[i].t == 1)
		{
			ll idx = getIndex(query[i].a);
			update(idx, query[i].a);

			cnt[idx]++;
			bucket[idx / sz]++;

			curB += query[i].b;
			csz++;
		}
		else
		{
			int k = csz / 2 + 1;

			int cSum = 0;

			int j = 447;
			for (; j >= 0; j--)
			{
				if (cSum + bucket[j] >= k) break;
				cSum += bucket[j];
			}

			int i = (j + 1)*sz - 1;
			for (; i >= 0; i--)
			{
				if (cSum + cnt[i] >= k) break;
				cSum += cnt[i];
			}

			ll x = cor[i - 1];

			ll lsum = getVal(1, i - 1);
			lsum -= ((csz-1)/2) * x;

			ll rsum = getVal(i, 200000) - x;
			rsum -= ((csz) / 2) * x;

			ll fx = lsum + rsum + curB;

			cout << x << ' ' << fx << '\n';
		}
	}
}

