		if(command == 1){

			scanf("%lld %lld",&a,&b);

			add += b;

			if(L.size() > R.size()){

				ll tmp = L.top().value;
				if(a >= tmp){ //なるべく均衡させるのでaをRに入れる

					R.push(B(a));
					sum_R += a;

				}else{ //tmpをRに入れて、aをLに入れる

					L.pop();
					sum_L -= tmp;
					L.push(A(a));
					sum_L += a;
					R.push(B(tmp));
					sum_R += tmp;
				}

			}else{ //L.size() <= R.size()

				if(L.empty()){

					L.push(A(a));
					sum_L += a;

				}else{

					ll tmp = R.top().value;

					if(a <= tmp){ //なるべく均衡させるのでLにaを入れる

						L.push(A(a));
						sum_L += a;

					}else{ //tmpをLに移し、aをRに入れる

						R.pop();
						sum_R -= tmp;
						R.push(B(a));
						sum_R += a;
						L.push(A(tmp));
						sum_L += tmp;
					}
				}
			}

		}else{

			//xを直線状の点と見た時、各拠点からの距離の総和を取る
			ll x = L.top().value;
			ll num = (x*L.size()-sum_L)+(sum_R-x*R.size())+add;

			printf("%lld %lld\n",x,num);
		}
	}

	return 0;
}

