void update(As &lefts, As &rights,
            int64_t &n, int64_t &min)
{
  int64_t a, b;
  std::cin >> a >> b;

  min += b;

  if(n == 0) {
    lefts.insert(std::make_pair(a, true));
    // print_map(lefts, "first left");
    n++;
    return;
  }

  int64_t old_argmin = lefts.rbegin()->first;
  bool appends_left = a <= old_argmin;

  // prepair before appending
  if(appends_left && n%2 == 1) {
    // remove lefts[-1] and append it to rights
    auto old = *(--lefts.cend());
    // std::cout << "old: " << old.first << ": " << old.second << std::endl;
    lefts.erase(--lefts.cend());
    // std::cout << "erase left[-1]" << std::endl;
    rights.insert(old);
  } if(!appends_left && n%2 == 0) {
    // remove right[0] and append it to lefts
    auto old = *rights.begin();
    rights.erase(rights.begin());
    lefts.insert(old);
  }

  // append a
  auto new_a = std::make_pair(a, true);
  if(appends_left) {
    lefts.insert(new_a);
  } else {
    rights.insert(new_a);
  }

  // print_map(lefts, "lefts");
  // print_map(rights, "rights");

  // update min
  int64_t new_argmin = (--lefts.end())->first;
  if(new_argmin < old_argmin || n%2 != 0) {
    min += std::abs(old_argmin - new_argmin);
  }
  min += std::abs(new_argmin - a);

  n++;
}

