class BinaryIndexedTree {
	std::vector<long long int> vec;
public:
	BinaryIndexedTree(int size) : vec(size, 0) {};
	long long int get(int position) const {
		long long int result = 0;
		while (position >= 0) {
			result += vec[position];
			position -= ~position & (position + 1);
		}
		return result;
	}
	void increase(int position, int value) {
		while (position < vec.size()) {
			vec[position] += value;
			position += ~position & (position + 1);
		}
	}
};
