void merge()
{
  ll x = L.top();
  ll y = R.top();
  if (a <= x)
  {
    L.push(a);
  }
  else if (a >= y)
  {
    R.push(a);
  }
  else
  {
    L.push(a);
  }
  while (L.size() > R.size())
  {
    ll t = L.top();
    L.pop();
    R.push(t);
  }
  while (L.size() < R.size())
  {
    ll t = R.top();
    R.pop();
    L.push(t);
  }
  B += b;
  if (a < 0)
  {
    cnt_l++;
    A += abs(a);
  }
  else if (a > 0)
  {
    cnt_r++;
    A += abs(a);
  }
}

void flush()
{
  ll val = L.top();
  ll ans = A + B;
  ll dist = abs(val);
  ll c = abs(cnt_l - cnt_r);
  ans -= dist * c;
  cout << val << " " << ans << endl;
}

