		}
	}


	int lenum = 0;
	ll coef = 0, ad = 0;
	ll mid = -INF;
	auto itr = st.begin();
	rep(i, q) {
		if(v[i].id == 2) {
			cout << mid << " " << coef * mid + ad << endl;
		}
