priority_queue<int> Maxheap;//大根堆 
priority_queue<int,vector<int>,greater<int> > Minheap;//小根堆 

ll l,r,B;

void insert(int x){ 
	if(Maxheap.empty()) {
		Maxheap.push(x);
		l+=x;
	}
	else {
		if(x<=Maxheap.top()){
			Maxheap.push(x);
			l+=x;
			if((int)Maxheap.size()-(int)Minheap.size()>=2){
				int t=Maxheap.top();
				Maxheap.pop();
				Minheap.push(t);
				l-=t;
				r+=t; 
			}
		}
		else {
			Minheap.push(x);
			r+=x;
			if(Minheap.size()>Maxheap.size()){
				int t=Minheap.top();
				Minheap.pop();
				Maxheap.push(t);
				l+=t;
				r-=t;
			}
		}
	}
} 

int main(){
	ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
	int q,op,a,b,x;
	cin>>q;
	l=r=B=0;
	while(q--){
		cin>>op;
		if(op==1) {
			cin>>a>>b;
			insert(a);
			B+=b;
		}
		else{
			if(!Maxheap.empty()) x=Maxheap.top();
			else x=0;
			cout<<x<<' '<<((ll)Maxheap.size()*x-l)+(r-(ll)Minheap.size()*x)+B<<endl;
		}
	}
	return 0;
}
/*
对于f(x)=|x-a1|+|x-a2|+……+|x-an|+B，
作函数图象(作弊操作) 
可以知道若绝对值部分的个数为奇数，那么最小值在
ai的中位数处，如果个数为偶数，那么最小值在中间两个
数之间的所有数，因为要取最小的，自然取中间两个数中小的那个。
思路一：因为是要找中位数，可以用nth_eleemnt找到，时间复杂度为O(n),
然后计算结果，也是要遍历一次，时间复杂度也是O(n),q次询问的时间
复杂度为O(q^2)，故不能这么做。
思路二：用一个大根堆和一个小根堆维护中位数。
用大根堆记录中位数和其左边的数，小根堆记录其右边的数，
这样维护过程的时间复杂度为O(qlogq)，访问中位数的时间复杂度为O(1),
但是如果遍历所有a求解结果，时间复杂度仍是O(n)，总的时间复杂度还是O(q^2),
只是找中位数快了。但是转念一想，既然都知道了中位数x，
中位数左边的值都小于中位数，如果还知道左边数的个数N，那么显然
左边绝对值结果为左边数的个数N乘中位数x减去左边数的和L，同理右边相似， 
右边绝对值计算结果为右边数的和R减去个数M乘中位数x。 
最后结果为(N*x-L)+(R-M*x)+B。
注意容器的size函数返回值为unsigned int类型，避免被其它类型强制转换导致计算错误。 
*/

