const int N = 200010;
const int INF = 2e9;

int q;
vector<int> val;
pair<int, int> a[N];

struct BIT {
    long long t[N];

    void add(int x, int v) {
        while (x < N) {
            t[x] += v;
            x += (x & -x);
        }
    }
    long long get(int x) {
        long long res = 0;
        while (x) {
            res += t[x];
            x -= x & -x;
        }
        return res;
    }
} t, tx;

struct IT {
    int t[N << 2];

    void add(int node, int l, int r, int x) {
        if (x > r || x < l) return;
        if (l == r) {
            t[node]++;
            return;
        }
        int m = l + r >> 1;
        add(node << 1, l, m, x);
        add(node << 1 | 1, m + 1, r, x);
        t[node] = t[node << 1] + t[node << 1 | 1];
    }

    int get(int node, int l, int r, int need) {
        if (l == r) return l;
        int m = l + r >> 1;
        if (t[node << 1] <= need) return get(node << 1 | 1, m + 1, r, need - t[node << 1]);
        return get(node << 1, l, m, need);
    }
} it;

