template<class T> class segtree {
    int n = 1;
    vector<T> dat;
    T def;

public:
    segtree(int _n, T _def) : def(_def) {
        while (n < _n)n *= 2;
        dat.resize(2 * n, def);
    }
    segtree(vector<T> a, T _def) : def(_def) {
        int _n = a.size();
        while (n < _n)n *= 2;
        dat.resize(2 * n, def);
        FOR(i, 0, _n)dat[i + n] = a[i];
        rFOR(i, 1, n)dat[i] = fun(dat[2 * i], dat[2 * i + 1]);
    }

    T fun(T x, T y) { return x + y; }

    void update(int i, T a) {
        i += n;
        dat[i] += a;
        while (i > 1) {
            i /= 2;
            dat[i] = fun(dat[2 * i], dat[2 * i + 1]);
        }
    }

    T value(int l, int r) {
        l += n, r += n;

        T ret = def;
        for (; l < r; l /= 2, r /= 2) {
            if (l & 1) {
                ret = fun(ret, dat[l]);
                l++;
            }
            if (r & 1) {
                --r;
                ret = fun(ret, dat[r]);
            }
        }

        return ret;
    }

    T operator[](int k) { return dat[k + n]; }
};


int main() {
    init();

    int q; cin >> q;
    VI type(q);
    VL a(q), b(q);
    map<ll, int> m;
    FOR(i, 0, q) {
        cin >> type[i];
        if (type[i] == 1) {
            cin >> a[i] >> b[i];
            m[a[i]];
        }
    }

    VL x;
    auto itr = m.begin();
    for (int i = 0; itr != m.end(); ++itr, ++i) {
        itr->second = i;
        x.push_back(itr->first);
    }
    int Size = m.size();
    segtree<ll> seg(Size, 0), cnt(Size, 0);

    function<ll(int)> f = [&](int k) {
        ll ret = 0;
        ret += cnt.value(0, m[x[k]]) * x[k] - seg.value(0, m[x[k]]);
        ret += seg.value(m[x[k]], Size) - cnt.value(m[x[k]], Size) * x[k];
        return ret;
    };

    ll base = 0;
    FOR(i, 0, q) {
        if (type[i] == 1) {
            seg.update(m[a[i]], a[i]);
            cnt.update(m[a[i]], 1);
            base += b[i];
        }
        else {
            int l = 0, r = Size - 1;
            while (r - l > 2) {
                int m1 = (l * 2 + r) / 3, m2 = (l + r * 2) / 3;
                if (f(m1) <= f(m2))r = m2;
                else l = m1;
            }

            int s = l; ll t = f(l);
            if (chmin(t, f(l + 1)))s = l + 1;
            if (chmin(t, f(r)))s = r;
            cout << x[s] << " " << t + base << "\n";
        }
    }
}

