			}
			if (s.size() > b.size() + 1) {
				int box = *s.begin();
				box *= -1;
				s.erase(s.begin());
				bb += box;
				ss -= box;
				b.insert(box);
			}
		}
		else {
			long long int box = -(*s.begin());
			long long int ans = M;
			ans += bb - box * b.size();
			ans += box * s.size();
			ans -= ss;
			cout << box << " " << ans << endl;
		}
	}
}

