void add(ll val){
    if(esq.empty() and dir.empty()){
        sumdir += val;
        dir.insert(val);
    }
    else if(esq.empty()){
        if(sumdir >= val){
            sumesq += val;
            esq.insert(val);
        }
        else{
            sumesq = sumdir;
            sumdir = val;
            dir.clear();
            esq.insert(sumesq);
            dir.insert(sumdir);
        }
    }
    else{
        ll valesq = *(--esq.end()), valdir = *dir.begin();
        if(val >= valesq){ // go to right
            sumdir += val;
            dir.insert(val);
        }
        else{ // go to left
            sumesq += val;
            esq.insert(val);
        }
        while(dir.size() > esq.size()){
            valdir = *dir.begin();
            dir.erase(dir.begin());
            sumdir -= valdir;
            esq.insert(valdir);
            sumesq += valdir;
        }
        while(esq.size() > dir.size()){
            valesq = *(--esq.end());
            esq.erase(--esq.end());
            sumesq -= valesq;
            dir.insert(valesq);
            sumdir += valesq;
        }
    }
}

