            a.pb(x);
            b.pb(y);
        }
    }
    compress<int> comp(a);
    auto f = [](int a, int b) { return a + b;};
    auto g = [](ll a, ll b) { return a + b;};
    SegmentTree<int> segcnt(0, f);
    SegmentTree<ll> segsum(0, g);
    segcnt.init(q); segsum.init(q);
    ll b_sum = 0;
    int cnt = 0;
    int nowidx = 0;
    rep(i, q) {
        if (t[i] == 1) {
            int x = comp.zip[a[nowidx]];
            segcnt.set(x, segcnt[x] + 1);
            segsum.set(x, segsum[x] + a[nowidx]);
            cnt++;
            b_sum += b[nowidx];
            nowidx++;
        } else {
            auto check = [&](int a) { return a >= (cnt+1)/2;};
            int mid = segcnt.find(0, check);
            // cout << mid << endl;
            ll ans = b_sum;
