template<class V, int ME> class BIT {
public:
    V bit[1<<ME];
    V total(int e) {
        if(e < 0) return 0;
        V s=0;e++;while(e) s+=bit[e-1],e-=e&-e; return s;
    }
    void add(int e, V val) {e++; while(e<=1<<ME) bit[e-1]+=val,e+=e&-e;}
};

const ll MA = 16;
const ll len = (1<<MA);
map<ll,ll> zip;
ll unzip[len];

typedef pair<ll, pll> plll;

ll compress(vector<ll> &x) {
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(),x.end()),x.end());
    for(ll i = 0; i < x.size(); i++){
        zip[x[i]] = i;
        unzip[i] = x[i];
    }
    return x.size();
}

