struct que {
  priority_queue<int> minqueue;
  priority_queue<int, vector<int>, greater<int>> maxqueue;

  int B = 0;
  void push(int v, int b){
    B += b;
    if(!minqueue.empty() && !maxqueue.empty()){
      if(!(minqueue.top() <= v && v <= maxqueue.top())){
        B += min(abs(minqueue.top()-v), abs(maxqueue.top()-v));
      }
    }else if(!minqueue.empty()){
      B += abs(minqueue.top()-v);
    }

    if(minqueue.empty() || v <= minqueue.top()){
      minqueue.push(v);
    }
    else{
      maxqueue.push(v);
    }

    while(minqueue.size() > maxqueue.size()+1){
      int tmp = minqueue.top();
      minqueue.pop();
      maxqueue.push(tmp);
    }
    while(minqueue.size() < maxqueue.size()){
      int tmp = maxqueue.top();
      maxqueue.pop();
      minqueue.push(tmp);
    }
    return;
  }

  void ans(){
    cout << minqueue.top() << " " << B << "\n";
  }

  que(): B(0){}
};

