typedef pair<ll, int> IIl;
vector<II> listA;
int ch[MAXQ], u[MAXQ], v[MAXQ], f[MAXQ];
IIl t[MAXQ*8];

void update(int k, int l, int r, int u) {
    if (l > r || r < u || u < l) return;
    if (l == r) {
        t[k] = IIl(listA[u].FI, 1);
        return;
    }
    int m = (l + r) >> 1;
    update(k * 2, l, m, u);
    update(k * 2 + 1, m + 1, r, u);
    t[k] = IIl(t[k*2].FI + t[k*2+1].FI, t[k*2].SE + t[k*2+1].SE);
}

IIl get(int k, int l, int r, int u, int v) {
    if (l > r || r < u || v < l) return IIl(0, 0);
    if (u <= l && r <= v) return t[k];
    int m = (l + r) >> 1;
    IIl g = get(k * 2, l, m, u, v);
    IIl h = get(k * 2 + 1, m + 1, r, u, v);
    return IIl(g.FI + h.FI, g.SE + h.SE);
}

ll getRes(ll x, int N) {
    int dau = 1, cuoi = N, mid;
    while (dau <= cuoi) {
        mid = (dau + cuoi) >> 1;
        if (listA[mid].FI <= x) dau = mid+1;
        else cuoi = mid-1;
    }
    int k = cuoi;
    // cout << x << ' ' << k << endl;
    IIl g = get(1,1,N,1,k);
    IIl h = get(1,1,N,k+1,N);
    //cout << g.FI << ' ' << g.SE << ' ' << h.FI << ' ' << h.SE << endl;
    return x * g.SE - g.FI + h.FI - x * h.SE;
}

