int bs(int l, int r, int a, const vector<ll> &v) {
    if (l == r) return l-1;
    if (r - l < 2) return l;
    int mid = l + (r - l) / 2;

    if (v[mid] > a) {
        return bs(l, mid, a, v);
    } else {
        return bs(mid, r, a, v);
    }
}

