        if      (x >  t_max)               setvaI(x);
        else if (x <  t_min)               setvaA(x);
        else if (x == t_min && x == t_max) setvaA(x);
    }
}

void impartial()
{
    t_min = heap_min.top();
    t_max = heap_max.top();
    if (t_max > t_min)
    {
        popvaA(t_max);
        popvaI(t_min);
        setvaA(t_min);
        setvaI(t_max);
    }
}

void equitable()
{
    while (heap_max.size() > heap_min.size())
    {
        t_max = heap_max.top();
        popvaA(t_max);
        setvaI(t_max);
    }
    while (heap_max.size() < heap_min.size())
    {
        t_min = heap_min.top();
        popvaI(t_min);
        setvaA(t_min);
    }
}

void ketqua()
{
    lld temp = heap_max.top();
    if (l_min == l_max)
        temp = b_sum + (s_min - s_max);
    else if (l_max = l_min + 1)
        temp = b_sum + (s_min - s_max + temp);

    if (result > temp)
    {
        result = temp;
        xmin   = heap_max.top();
    }
    else if (result == temp)
        xmin = min(xmin, heap_max.top());
}

