  priority_queue<ll, vector<ll>, greater<ll>> qR;
  ll sumL = 0, sumR = 0;

  for (int i = 0; i < Q; i++) {
    int temp;
    cin >> temp;

    if (temp == 1) {

      ll tempA, tempB;
      cin >> tempA >> tempB;

      b += tempB;

      if ( qL.size() == 0 ) {
        qL.push(tempA);
        sumL += tempA;

      } else if ( qL.size() == qR.size() ) {
        ll topR = qR.top();
        if (tempA <= topR) {
          qL.push(tempA);
          sumL += tempA;
        } else {
          qR.pop();
          qL.push(topR);
          sumL += topR;
          qR.push(tempA);
          sumR = sumR - topR + tempA;
        }
      } else {
        ll topL = qL.top();
        if (topL <= tempA) {
          qR.push(tempA);
          sumR += tempA;
        } else {
          qL.pop();
          qR.push(topL);
          sumR += topL;
          qL.push(tempA);
          sumL = sumL - topL + tempA;
        }
      }

    } else {
      ll s = qL.size() + qR.size();
      ll ans1 = qL.top();
      ll ans2 = ans1 * (s % 2) - sumL + sumR + b;

      cout << ans1 << SP << ans2 << BR;
    }
  }

  return 0;
}

