	std::sort(a_all.begin(), a_all.end());
	std::unordered_map<int, int> map;
	for (auto i = 0; i < a_all.size(); ++i) {
		if (i > 0 && a_all[i] == a_all[i - 1]) continue;
		map[a_all[i]] = i;
	}
	BinaryIndexedTree sum_bit(a_all.size()), count_bit(a_all.size());
	long long int a_sum{ 0 }, b_sum{ 0 };
	int count{ 0 };
	for (const auto vec : query) {
