				}
				else {
					max = mid;
				}
			}
			const auto minus = sum_bit.get(max) - (count_bit.get(max) - ((count + 1) >> 1)) * a_all[max];
			const auto plus = a_sum - minus;
			const auto min_value = (count & 1) * a_all[max] + b_sum + plus - minus;
			std::cout << a_all[max] << ' ' << min_value << '\n';
		}
		else {
			a_sum += vec[0]; b_sum += vec[1];
			const auto pos = map[vec[0]];
			sum_bit.increase(pos, vec[0]);
			count_bit.increase(pos, 1);
			++count;
		}
	}
