using namespace std;

class fenwick {
public:
	fenwick(int n)
		: n(n)
		, tree(n, 0)
	{}
	void set_value(int i, long long v) {
		while (i < n) {
			tree[i] += v;
			i |= (i + 1);
		}
	}
	long long get_sum(int l, int r) {
		if (l) {
			return get_sum(0, r) - get_sum(0, l - 1);
		} else {
			long long answer = 0;
			while (r >= 0) {
				answer += tree[r];
				r = (r & (r + 1)) - 1;
			}
			return answer;
		}
	}
private:
	int n;
	vector<long long> tree;
};

