}

struct node;
node *update(node *t);

struct node {
	T val, all;
	node *ch[2];
	int dep, size;
	node() {}
	void init(T v) {
		val = all = v;
		dep = size = 1;
		ch[0] = ch[1] = nullptr;
	}
	void init(node* l, node* r) {
		val = id;
		ch[0] = l, ch[1] = r;
