};

int main(void)
{
	ll Q; cin >> Q;
	vt<Query> q(Q);
	priority_queue<ll> lpq;
	priority_queue<ll, vt<ll>, greater<ll>> rpq;

	ll lsum = 0;
	ll rsum = 0;
	ll bsum = 0;
	vector<Ans> ans;
	each(i, e, q)
	{
		cin >> e.q;
		if (e.q == 1)
		{
			cin >> e.a >> e.b;
			bsum += e.b;

			if (lpq.empty())
			{
				lpq.push(e.a);
				lsum += e.a;
				continue;
			}

			if (Size(rpq) < Size(lpq))
			{	// Size(rpq)のときだけrpqへの要素挿入を許可
				rpq.push(e.a); rsum += e.a;

				if (rpq.top() < lpq.top())
				{	// rpqが小さいのはngなので交換
					ll ltemp = lpq.top();
					ll rtemp = rpq.top();
					lpq.pop(); rpq.pop();
					lsum -= ltemp; rsum -= rtemp;
					lpq.push(rtemp); rpq.push(ltemp);
					lsum += rtemp; rsum += ltemp;

				}
			}
			else
			{
				lpq.push(e.a); lsum += e.a;

				if (rpq.top() < lpq.top())
				{	// rpqが小さいのはngなので交換
