					lsum -= ltemp; rsum -= rtemp;
					lpq.push(rtemp); rpq.push(ltemp);
					lsum += rtemp; rsum += ltemp;
				}
			}
		}
		else
		{
			ll x = lpq.top();
			ll sum = abs(x * Size(lpq) - lsum) + abs(x * Size(rpq) - rsum) + bsum;
			ans.push_back({ x, sum });
		}
	}

	each(i, e, ans) cout << e.x << " " << e.sum << endl;
	return 0;
}

