typedef long long LL;
class RunningMedian {
public:
    priority_queue<int> left;
    priority_queue<int, vector<int>, std::greater<int>> right;
    LL leftSum = 0, rightSum = 0;

    void insert(int x) {
        if(left.empty()) {
            left.push(x);
            leftSum += x;
            return;
        }

        if(left.top() > x) {
            left.push(x);
            leftSum += x;
        } else {
            right.push(x);
            rightSum += x;
        }
        if (left.size()-2 == right.size()) {
            int t = left.top();
            left.pop();
            right.push(t);
            leftSum -= t;
            rightSum += t;
        } else if (left.size() == right.size() - 1) {
            int t = right.top();
            right.pop();
            left.push(t);
            rightSum -= t;
            leftSum += t;
        }
    }
    int median() {
        return left.top();
    }
    LL sum() {
        int m = left.top();
        LL leftAns = m * left.size() - leftSum;
        LL rightAns = m * right.size() - rightSum;
        return leftAns - rightAns;
    }
};

int main() {
    int N;
    LL C = 0;
    RunningMedian rm;
    cin >> N;
    for(int i = 0; i < N; i++) {
        int op, a, b;
        cin >> op;
        if (op == 1) {
            cin >> a >> b;
            C += b;
            rm.insert(a);
        } else {
            int m = rm.median();
            cout << m << " ";
            cout << rm.sum() + C << "\n";
        }
    }
}

