struct Tree{
  int len;
  vector<int> bit;
  vector<ll> sum;
  Tree(int n = 0) : len(n), bit(n+1, 0), sum(n+1, 0) {}

  void Update(int p){
    for (int i = p; i <= len; i += i & (-i)) bit[i]++, sum[i] += vec[p-1];
  }

  int Get_Num(int i){
    int ret = 0;
    for (; i > 0; i -= i & (-i)) ret += bit[i];
    return ret;
  }

  int Get_Median(int p){
    int k = (p + 1) / 2;
    int l = 1, r = len;
    while (l <= r){
      int mid = (l + r) / 2;
      if (Get_Num(mid) >= k) r = mid - 1;
      else l = mid + 1;
    }
    return r + 1;
  }

  ll Get_Sum(int i){
    ll ret = 0;
    for (; i > 0; i -= i & (-i)) ret += sum[i];
    return ret;
  }

};

