      int numLeft = f.Get_Num(pos), numRight = n - numLeft;
      ll sumLeft = f.Get_Sum(pos), sumRight = total - sumLeft;
      ll median = vec[pos-1];
      cout << median << ' ' << median * numLeft - sumLeft + sumRight - numRight * median + c << '\n';
    }

  }
}

