		}
		q.push_back(tmp);
	}

	sort(aa.begin(), aa.end());
	map<ll, ll> mp;
	zep(i, 0, aa.size()){
		mp[aa[i]] = i;
	}
	ll m = aa.size();
	vector<ll> v(m, 0);
	segtree<ll> sg(v);
	vector<ll> vv(m, 0);
	segtree<ll> sgs(vv);

	median_set s;
