#include<bits/stdc++.h>
using namespace std;
const int N = 2e5 + 10;
int q, A[N], B[N];
long long S[N], T[N];
vector < int > U;
inline void Add(int i, int val, long long * F)
{
    for (i ++; i < N; i += i & -i)
        F[i] += val;
}
inline long long Get(int i, long long * F)
{
    long long rt = 0;
    for (i ++; i; i -= i & -i)
        rt += F[i];
    return rt;
}
int main()
{
    scanf("%d", &q);
    for (int i = 0; i < q; i++)
    {
        int tp;
        scanf("%d", &tp);
        if (tp == 1)
            scanf("%d%d", &A[i], &B[i]), U.push_back(A[i]);
        else
            A[i] = INT_MAX;
    }
    sort(U.begin(), U.end());
    U.resize(unique(U.begin(), U.end()) - U.begin());
    int n = 0;
    long long sum = 0, suma = 0;
    for (int i = 0; i < q; i++)
    {
        if (A[i] != INT_MAX)
        {
            sum += B[i];
            suma += A[i];
            int a = lower_bound(U.begin(), U.end(), A[i]) - U.begin();
            Add(a, 1, S);
            Add(a + 1, A[i], T);
            n ++;
        }
        else
        {
            int le = -1, ri = (int)U.size(), md;
            while (ri - le > 1)
            {
                md = (le + ri) >> 1;
                if (Get(md, S) >= ((n + 1) >> 1))
                    ri = md;
                else
                    le = md;
            }
            long long res = sum + suma - Get(ri, T) - Get(ri + 1, T);
            if (n % 2 == 0)
                res -= U[ri];
            printf("%d %lld\n", U[ri], res);
        }
    }
    return 0;
}

