long long a, b;
long long A, B;
priority_queue<long long>l;
priority_queue<long long, vector<long long>, greater<long long>>r;

void update()
{
	B += b;
	if (l.empty())
		l.push(a);
	else if (a <= l.top())
	{
		A += l.top() - a;
		l.push(a);
	}
	else
	{
		A += a - l.top();
		r.push(a);
	}

	while (l.size() >= (r.size() + 2))
	{
		r.push(l.top());
		l.pop();
		A -= 1ll * (r.top() - l.top())*(l.size() - r.size());
	}
	while (r.size() > l.size())
	{
		A -= 1ll * (r.top() - l.top())*(r.size() - l.size());
		l.push(r.top());
		r.pop();
	}

}

int main()
{
	int n;
	scanf("%d", &n);
	while (n--)
	{
		int opt;
		scanf("%d", &opt);
		if (opt == 1)
		{
			scanf("%lld%lld", &a, &b);
			update();
		}
		else
			printf("%d %lld\n", l.top(), A + B);
	}
	return 0;
}

