    ios::sync_with_stdio(false);

    ll Q;
    cin >> Q;
    BIT<ll, bitsu> bit;
    REP(i, length) bit.bit[i] = 0;
    vector<ll> as;
    vector<pll> query;
    vector<ll> bs(Q, 0);
    REP(i, Q){
    	ll type;
    	cin >> type;
    	if(type == 1){
    		ll a, b;
    		cin >> a >> b;
    		as.push_back(a);
    		query.push_back({0, a});
    		bs[i] = b;
    	}else{
    		query.push_back({1, 0});
    	}
    }
    compress(as);

    vector<ll> c;
    ll B = 0;
    REP(i, Q){
    	pll q = query[i];
    	if(q.first == 0){
    		ll val = q.second;
    		c.push_back(val);
    		bit.add(zip[val], val);
    		B += bs[i];

    		sort(c.begin(), c.end());

    		//cout << "c; ";
    		//cout << c << endl;
    	}else{
    		ll res = 0;
    		ll mix = c[(c.size()-1)/2];
    		ll ichi = zip[mix];
    		ll saki = bit.total(ichi);
    		ll ato = bit.total(length-1) - bit.total(ichi);
    		res -= saki;
    		res += ato;
    		dump(ichi)
    		dump(saki)
    		dump(ato)
    		dump(B)
    		res += B;
