void update(ll u) {
	sz[u] = sz[ch[u][0]] + sz[ch[u][1]] + 1;
	h[u] = h[ch[u][0]]+h[ch[u][1]]+key[u];
}
void rotate(ll &u, ll d /* 0 or 1 */) {
	ll v = ch[u][d^1];
	ch[u][d^1] = ch[v][d];
	ch[v][d] = u;
	update(u);
	update(v);
	u = v;
}
void insert(ll &u, ll k) {
	if (u == 0) {
		u = ++tot;
		key[u] = k, pri[u] = rand(), sz[u]=1, h[u]=k;
		return;
	}
	int d = (k > key[u]);
	insert(ch[u][d], k);
	update(u); 
	if (pri[ch[u][d]] < pri[u]) rotate(u, d ^ 1);
}
