	map<int, int> mp, rev;
	for (int v : s)
	{
		mp[v] = ++cnt;
		rev[cnt] = v;
	}
	BIT<long> bitcnt(cnt+1), bitsum(cnt+1);

	long sumb = 0;
	int now = 0;
	for (auto &q : qs)
	{
		if (q.first == 1)
