			bitcnt.add(v, 1);
			bitsum.add(v, z);
			now++;
		}
		else
		{
			int idx = bitcnt.lb((now + 1) / 2);
			long res = sumb, rv = rev[idx];
			res += bitsum.sum(cnt) - 2 * bitsum.sum(idx) + (bitcnt.sum(idx)*2 - now) * rv;
