                    int x_next = a_right.top(); a_right.pop();
                    sum_left += x;  sum_right += A[i] - x_next;
                    x = x_next;
                }
                else {
                    a_left.push(A[i]);
                    sum_left += A[i];
                }
                cnt_left++;
