int main() {
  int q;
  cin>>q;
  int median = -1e9 - 1;
  long long val = 0;
  multiset<int> left, right;

  for (int i=0; i<q; i++) {
    int type;
    cin>>type;
    if (type == 1) {
      int a, b;
      cin>>a>>b;
      val += b;
      if (median == -1e9 - 1) {
        median = a;
        continue;
      }
      if (left.size() == right.size()) {
        if (a <= median) {
          left.insert(a);
        } else {
          right.insert(a);
        }
        val += abs(a - median);
        if (left.size() > right.size()) {
          int prev_median = median;
          auto it = left.rbegin();
          median = *it;
          right.insert(prev_median);
          left.erase(next(it).base());
        }
      } else  {
        val += abs(a - median);
        if (a <= median) {
          left.insert(a);
        } else {
          right.insert(a);
        }
        if (left.size() - right.size() == 2) {
          int prev_median = median;
          auto it = left.rbegin();
          right.insert(median);
          median = *it;
          left.erase(next(it).base());
          val -= prev_median - median;
        } else if (right.size() - left.size() == 2) {
          int prev_median = median;
          auto it = right.begin();
          left.insert(median);
          median = *it;
          right.erase(it);
          val -= median - prev_median;
        }
      }
    } else {
      cout<<median<<" "<<val<<endl;
    }
  }
}

