int N,M,L,R,K,Q,X,Y,Z;
multiset<int> pre,post;
int ans = 0;
int sum[2] = {0,0};

void solve() {
    cin>>Q;
    int t,a,b;
    while(Q--) {
        cin>>t;
        if (t==1) {
            cin>>a>>b;
            ans += b;
            if (pre.empty()) {
                pre.insert(a);
                sum[0] = a;
                continue;
            }
            if (pre.size()==post.size()) {
                int v = *post.begin();
                if (v < a) {
                    post.erase(post.begin());
                    post.insert(a);
                    pre.insert(v);
                    sum[1] += a-v;
                    sum[0] += v;
                } else {
                    pre.insert(a);
                    sum[0] += a;
                }
                continue;
            }
            // pre.size() > post.size()
            int v = *pre.rbegin();
            if (a < v) {
                sum[0] += a - v;
                sum[1] += v;
                pre.erase(--pre.end());
                pre.insert(a);
                post.insert(v);
            } else {
                post.insert(a);
                sum[1]+=a;
            }
        } else {
            int x = *(pre.rbegin());
            int s = ans + (int)pre.size()*x - sum[0] + sum[1] - (int)post.size()*x;
            out("%lld %lld\n",x,s);
        }
    }
}

