// mp[a[i]]で圧縮後の座標
map<ll, ll> zatu(vector<ll> a) {
    map<ll, ll> mp;
    for(int i = 0; i < a.size(); i++) {
        mp[a[i]] = 0;
    }
    int k = 0;
    for(auto &e : mp) { // autoは&をつけないと代入されない
        e.second = k;
        k++;
    }
    return mp;
}
template <typename Mnd> struct segment_tree {
    int sz;
    vector<Mnd> data;
    function<Mnd(Mnd, Mnd)> f;
    Mnd e;
    //サイズだけ指定して初期化
    segment_tree(int _sz, function<Mnd(Mnd, Mnd)> _f, Mnd _e) : f(_f), e(_e) {
        sz = 1;
        while(sz < _sz)
            sz <<= 1;
        data.assign(sz * 2, e);
    }
    //参照渡しなので代入とかもできる
    Mnd &operator[](const int &k) { return data[k + sz]; }
    //木を構築 O(n)
    void build() {
        for(int i = sz - 1; i > 0; i--)
            data[i] = f(data[2 * i], data[2 * i + 1]);
    }
    //更新しつつ木を再構築 O(log n)
    void update(int k, Mnd x) {
        data[k += sz] = x;
        while(k >>= 1)
            data[k] = f(data[2 * k], data[2 * k + 1]);
    }
    //[a,b)でのクエリに答える　O(log n)
    Mnd query(int a, int b) const {
        Mnd l = e, r = e;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
            if(a & 1)
                l = f(l, data[a++]);
            if(b & 1)
                r = f(r, data[--b]);
        }
        return f(l, r);
    }
};
int main() {
    int q;
    cin >> q;
    vector<ll> ord(q, -1), a, b(1, 0);
    for(int i = 0; i < q; i++) {
        int r;
        cin >> r;
        ord[i] = r;
        if(r == 1) {
            ll t, s;
            cin >> t >> s;
            a.push_back(t);
            b.push_back(s + b.back());
        }
    }
    int m = a.size();
    auto res = zatu(a);
    map<ll, ll> decode;
    for(auto e : res) {
        decode[e.second] = e.first;
    }
    segment_tree<ll> seg(m, [](ll a, ll b) { return a + b; }, 0);
    segment_tree<ll> seg2(m, [](ll a, ll b) { return a + b; }, 0);
    seg.build();
    seg2.build();
    vector<ll> ans, ind;
    for(int i = 0; i < m; i++) {
        seg.update(res[a[i]], seg[res[a[i]]] + 1);
        seg2.update(res[a[i]], seg2[res[a[i]]] + a[i]);
        int l = 0, r = m + 2;
        while(l + 1 < r) {
            int mid = (l + r) / 2;
            if(seg.query(0, mid) <= (i) / 2) {
                l = mid;
            } else {
                r = mid;
            }
        }
        /*
        for(int k = 0; k < m; k++) {
            cout << seg[k] << " ";
        }
        cout << endl;
        cout << "l=" << l << endl;
        */
        ind.push_back(decode[l]);
        ll hoge = (a[i] * seg.query(0, l) - seg2.query(0, l)) -
                  (a[i] * seg.query(l, m) - seg2.query(l, m)) + b[i + 1];
        ans.push_back(hoge);
    }
    int p = -1;
    for(int i = 0; i < q; i++) {
        if(ord[i] == 2) {
            cout << ind[p] << " " << ans[p] << endl;
        } else {
            p++;
        }
    }
}

