            long long f = 0;
            for (const auto& v : ab) {
                const auto a = v.first;
                const auto b = v.second;
                f += b;
                f += std::max(x - a, a - x);
            }
            printf("%d %lld\n", x, f);
        }
    }
    return 0;
}

