			//cerr << "Add : " << add.first << " " << add.second << endl;

			if (i == 0) {
				center = add;
			}
			else {
				sum_abs += abs(center.first - a);
				if (n & 1) { // odd
					if (center > add) {
						auto it = abs_set.lower_bound(center);
						--it;
						center = *it;
					}
				}
				else { // even
					if (center < add) {
						auto it = abs_set.upper_bound(center);
						sum_abs -= (it->first - center.first);
						center = *it;
					}
				}
			}
			//cerr << "Center : " << center.first << " " << center.second << endl;
		}
		else {
			cout << center.first << " " << sum_abs + sum_b << endl;
		}
	}
