template <typename Tp, typename Comparator = std::less<Tp>>
class median {
public:
  using value_type = Tp;
  using key_compare = Comparator;

private:
  using container = std::multiset<value_type, key_compare>;
  using iterator = typename container::iterator;
  container M_c;
  iterator M_it;
  key_compare M_comp = Comparator();
  size_t M_size = 0;
  value_type M_lower_sum = Tp();
  value_type M_upper_sum = Tp();

public:
  median() = default;

  bool empty() const { return M_c.empty(); }
  value_type get() const { return *M_it; }
  value_type lower_sum() const { return M_lower_sum; }
  value_type upper_sum() const { return M_upper_sum; }
  void insert(value_type const& x) {
    ++M_size;
    if (empty()) {
      M_it = M_c.insert(x);
      M_lower_sum += x;
      return;
    }
    M_c.insert(x);
    if (M_comp(x, *M_it)) {
      if (M_size % 2 == 0) {
        // x ? ! ?
        M_lower_sum -= *M_it;
        M_upper_sum += *M_it;
        --M_it;
        M_lower_sum += x;
      } else {
        // x ? ! ? ?
        M_lower_sum += x;
      }
    } else {
      if (M_size % 2 == 0) {
        // ? ! ? x
        M_upper_sum += x;
      } else {
        // ? ! ? ? x
        ++M_it;
        M_lower_sum += *M_it;
        M_upper_sum -= *M_it;
        M_upper_sum += x;
      }
    }
  }
  void erase(value_type const& x);
};

int main() {
  size_t Q;
  scanf("%zu", &Q);

  intmax_t bs = 0;
  intmax_t n = 0;
  median<intmax_t> md;
  for (size_t i = 0; i < Q; ++i) {
    int t;
    scanf("%d", &t);

    if (t == 1) {
      intmax_t a, b;
      scanf("%jd %jd", &a, &b);
      md.insert(a);
      bs += b;
      ++n;
    } else if (t == 2) {
      intmax_t x = md.get();
      intmax_t y = bs;
      y -= md.lower_sum();
      y += md.upper_sum();
      if (n % 2 == 1) y += x;
      printf("%jd %jd\n", x, y);
    } else {
      assert(false);
    }
  }
}

