#define MOD 1000000007

long long int intpow(long long int base, long long int p)
{
	if (1 == p){
		return base;
	}

	if (0 == p % 2){
		long long int val = intpow(base, p / 2);
		return (val*val) % MOD;
	}
	else{
		return (intpow(base, p - 1) * base) % MOD;
	}
}

long long int comb(long long int n, long long int k)
{
	if (1 == n){
		return 1;
	}
	if (0 == k){
		return 1;
	}
	return (((comb(n - 1, k - 1)*n) % MOD) * intpow(k, MOD - 2)) % MOD;
}

void solv()
{
	int Q; scanf("%d", &Q);

	long long int mid = 0, sumb = 0, sumleft = 0, sumright = 0;
	multiset<int> leftset, rightset;

	int p, a, b; scanf("%d%d%d", &p, &a, &b);
	mid = a; sumb += b;
	for (int i = 1; i < Q; i++){
		int p; scanf("%d", &p);
		if (1 == p){
			int a, b; scanf("%d%d", &a, &b);
			sumb += b;
			if (a < mid){
				leftset.insert(a);
				sumleft += mid - a;
			}
			else{
				rightset.insert(a);
				sumright = a - mid;
			}
			if (leftset.size() > rightset.size()){
				multiset<int>::iterator itr = leftset.end(); itr--;

				rightset.insert(mid);
				sumright += (mid - *itr)*rightset.size();
				sumleft -= (mid - *itr)*leftset.size();

				mid = *itr;
				leftset.erase(itr);
			}
			else if (rightset.size() > leftset.size()+1){
				multiset<int>::iterator itr = rightset.begin();

				leftset.insert(mid);
				sumleft += (*itr - mid)*leftset.size();
				sumright -= (*itr - mid)*rightset.size();

				mid = *itr;
				rightset.erase(itr);
			}
		}
		else{
			printf("%lld %lld\n", mid, sumleft + sumright + sumb);
		}
	}

	return;
}

int main()
{
	FILE *fin = NULL, *fout = NULL;
	//fin = freopen("input.txt", "r", stdin);
	//fout = freopen("output.txt", "w", stdout);

	solv();

	//finalize
	if (NULL != fin) fclose(fin);
	if (NULL != fout) fclose(fout);

	return 0;
}

