#include<bits/stdc++.h>
using namespace std;
#define int long
struct segment_tree {
  segment_tree *left, *right;
  int from, to, value;
  segment_tree(int from, int to) : from(from), to(to), left(NULL), right(NULL), value(0) { }
};

segment_tree* build(const vector<int> &arr, int l, int r) {
  if (l > r) return NULL;
  segment_tree *res = new segment_tree(l, r);
  if (l == r) {
    res->value = arr[l];
  } else {
    int m = (l + r) / 2;
    res->left = build(arr, l, m);
    res->right = build(arr, m + 1, r);
    if (res->left != NULL) res->value += res->left->value;
    if (res->right != NULL) res->value += res->right->value;
  }
  return res;
}

int query(segment_tree *tree, int l, int r) {
  if (tree == NULL) return 0;
  if (l <= tree->from && tree->to <= r) return tree->value;
  if (tree->to < l) return 0;
  if (r < tree->from) return 0;
  return query(tree->left, l, r) + query(tree->right, l, r);
}

int update(segment_tree *tree, int i, int val) {
  if (tree == NULL) return 0;
  if (tree->to < i) return tree->value;
  if (i < tree->from) return tree->value;
  if (tree->from == tree->to && tree->from == i) {
    tree->value = val;
  } else {
    tree->value = update(tree->left, i, val) + update(tree->right, i, val);
  }
  return tree->value;
}
int partition(vector<int>& arr,int l,int r,int pivi){
  int pivotValue=arr[pivi];
  swap(arr[pivi],arr[r]);
  int storeIndex=l;
  for(int i=l;i<r;++i)if(arr[i]<pivotValue)swap(arr[storeIndex++],arr[i]);
  swap(arr[r],arr[storeIndex]);
  return storeIndex;
}

int select(vector<int>& arr, int l, int r, int k){
  srand((unsigned)time(NULL));
  while(true){
    if(l==r)return arr[l];
    int pivotIndex=l+(rand()%(r-l+1));
    pivotIndex=partition(arr,l,r,pivotIndex);
    if(k==pivotIndex)return arr[k];
    else if(k<pivotIndex)r=pivotIndex-1;
    else l=pivotIndex+1;
  }
}

