class BIT {
public:
  int n;
  vector<int> bit;

  BIT(int n_) {
    n = 1;
    while (n < n_) {
      n <<= 1;
    }
    bit.resize(n + 1);
  }

  // add v[a] + w
  void add(int a, int w) {
    a++;
    if (a == 0 || a > n)
      return;
    for (int x = a; x <= n; x += x & -x)
      bit[x] += w;
  }

  // [0, a)
  int sum(int a) {
    if (a == 0)
      return 0;
    int ret = 0;
    for (int x = a; x > 0; x -= x & -x)
      ret += bit[x];
    return ret;
  }
};

