#include <bits/stdc++.h>
using namespace std;

template <typename T>
class seg {
	T t;
	using N = typename T::N;
	using F = typename T::F;
	vector<N> nt;
	vector<F> ft;
	void eval(int p, int l, int r) {
		if (ft[p] == t.IF)
			return;
		nt[p] = t.FN(ft[p], r - l, nt[p]);
		if (l + 1 < r) {
			t.FF(ft[p], ft[p + 1]);
			t.FF(ft[p], ft[p + (r - l & -2)]);
		}
		ft[p] = t.IF;
	}
	N init(N n, int p, int l, int r) {
		if (l + 1 == r)
			return nt[p] = n;
		int m = (l + r) / 2;
		return nt[p] = t.NN(init(n, p + 1, l, m), init(n, p + (r - l & -2), m, r));
	}
	N upd(int a, int b, F f, int p, int l, int r) {
		eval(p, l, r);
		if (b <= l || r <= a)
			return nt[p];
		if (a <= l && r <= b)
			return t.FN(ft[p] = f, r - l, nt[p]);
		int m = (l + r) / 2;
		return nt[p] = t.NN(upd(a, b, f, p + 1, l, m), upd(a, b, f, p + (r - l & -2), m, r));
	}
	N get(int a, int b, int p, int l, int r) {
		if (b <= l || r <= a)
			return t.IN;
		eval(p, l, r);
		if (a <= l && r <= b)
			return nt[p];
		int m = (l + r) / 2;
		return t.NN(get(a, b, p + 1, l, m), get(a, b, p + (r - l & -2), m, r));
	}
public:
	const int s;
	seg(int s) :s(s), nt(s * 2 - 1, t.IN), ft(s * 2 - 1, t.IF) {}
	seg(int s, N n) :seg(s) {
		init(n, 0, 0, s);
	}
	void upd(int a, int b, F f) {
		upd(a, b, f, 0, 0, s);
	}
	N get(int a, int b) {
		return get(a, b, 0, 0, s);
	}
};
struct L {
	typedef long N, F;
	const N IN = 0;
	const F IF = 0;
	N NN(N m, N n) { return m + n; }
	N FN(F f, int, N n) { return f + n; }
	void FF(F f, F &g) { g += f; }
};
int main() {
	int q;
	cin >> q;
	seg<L> m(222222), a(222222);
	vector<long> u;
	vector<tuple<int, int, long>> v;
	for (int i = 0; i < q; i++) {
		int c, a, b;
		scanf("%d", &c);
		if (c > 1)
			continue;
		scanf("%d%d", &a, &b);
		v.emplace_back(i, a, b);
	}
	sort(v.begin(), v.end(), [](auto x, auto y) {return get<1>(x) < get<1>(y); });
	for (auto &a : v) {
		u.push_back(get<1>(a));
		if (u.size() > 1 && u.back() == u.rbegin()[1])
			u.erase(u.end() - 1);
		get<1>(a) = u.size() - 1;
	}
	sort(v.begin(), v.end());
	int j = 0;
	for (int i = 0; i < q; i++) {
		if (j < v.size() && i == get<0>(v[j])) {
			m.upd(0, get<1>(v[j]), -1);
			a.upd(0, get<1>(v[j]), u[get<1>(v[j])] + get<2>(v[j]));
			m.upd(get<1>(v[j]), 222222, 1);
			a.upd(get<1>(v[j]), 222222, -u[get<1>(v[j])] + get<2>(v[j]));
			j++;
			continue;
		}
		int l = -1, r = 222000;
		while (l + 1 < r) {
			int t = (l + r) / 2;
			if (t + 1 < u.size() && m.get(t, t + 1)*u[t] + a.get(t, t + 1) > m.get(t + 1, t + 2)*u[t + 1] + a.get(t + 1, t + 2))
				l = t;
			else r = t;
		}
		cout << u[r] << ' ' << m.get(r, r + 1)*u[r] + a.get(r, r + 1) << '\n';
	}
	cout << flush;
	return 0;
}

