int main(int argc, char* argv[]) {
    ll bs_sum = 0;
    priority_queue<ll> as_former;
    ll as_former_sum = 0;
    priority_queue<ll, vector<ll>, std::greater<ll>> as_latter;
    ll as_latter_sum = 0;
    int q;
    cin >> q;
    while (q > 0) {
        q--;
        int query_type;
        cin >> query_type;
        if (query_type == 1) {
            ll a,b;
