            bs_sum += b;
            if (as_former.empty() || a < as_former.top()) {
                as_former.push(a);
                as_former_sum += a;
            } else {
                as_latter.push(a);
                as_latter_sum += a;
            }
            while (as_latter.size() > as_former.size()) {
                ll v = as_latter.top();
                as_latter.pop();
                as_latter_sum -= v;
                as_former.push(v);
                as_former_sum += v;
