            while (as_former.size() > as_latter.size() + 1) {
                ll v = as_former.top();
                as_former.pop();
                as_former_sum -= v;
                as_latter.push(v);
                as_latter_sum += v;
            }
        } else {
            ll x = as_former.top();
            ll val = bs_sum + (x * (ll)as_former.size() - as_former_sum) + (as_latter_sum - x * (ll)as_latter.size());
