      b_sum += b;
      if(left.empty() && right.empty()){
        right.push(-a);
        a_right_sum += a;
      }else if(left.size() == right.size()){
        ll a_middle = left.top();
        if(a<a_middle){
          left.pop();
          a_left_sum -= a_middle;
          left.push(a);
          a_left_sum += a;
          right.push(-a_middle);
          a_right_sum += a_middle;
        }else{
          right.push(-a);
          a_right_sum += a;
        }
      }else{
        ll a_middle = -right.top();
        if(a<a_middle){
          left.push(a);
          a_left_sum += a;
        }else{
          right.pop();
          a_right_sum -= a_middle;
          right.push(-a);
          a_right_sum += a;
          left.push(a_middle);
          a_left_sum += a_middle;
        }
      }
    }else{
      if(left.size() == right.size()){
        OUT(left.top(), a_right_sum - a_left_sum + b_sum);
      }else{
        ll a_middle = -right.top();
        OUT(a_middle, a_right_sum - a_left_sum - a_middle + b_sum);
      }
    }
  }


  return 0;
}

