void update(int a, int b, priority_queue<int>& less,
            priority_queue<int, vector<int>, greater<int>>& more,
            int& dless, int& dmore, int& off) {
    off += b;

    int n = less.size(), m = more.size();

    if(n == 0) {
        less.push(a);
    } else if(m == 0) {
        if(a < less.top()) {
            more.push(less.top());
            less.pop();
            less.push(a);
        } else {
            more.push(a);
        }
    } else if(a < less.top()) {
        if(n <= m) {
            dless += less.top()-a;
            less.push(a);
        } else {
            int cur = less.top(); less.pop();
            dless -= (cur-less.top())*less.size();
            dmore += (more.top()-cur)*more.size();
            more.push(cur);
            if(a > less.top()) {
                dless += (a-less.top())*less.size();
            } else {
                dless += less.top()-a;
            }
            less.push(a);
        }
    } else if(a > more.top()) {
        if(m <= n) {
            dmore += a-more.top();
            more.push(a);
        } else {
            int cur = more.top(); more.pop();
            dmore -= (more.top()-cur)*more.size();
            dless += (cur-less.top())*less.size();
            less.push(cur);
            if(a < more.top()) {
                dmore += (more.top()-a)*more.size();
            } else {
                dmore += a-more.top();
            }
            more.push(a);
        } 
    } else {
        if(n <= m) {
            dless += a-less.top();
            less.push(a);
        } else {
            dmore += more.top()-a;
            more.push(a);
        }
    }
}

void print(priority_queue<int>& less, priority_queue<int, vector<int>, greater<int>>& more,
           int dless, int dmore, int off) {
    int n = less.size(), m = more.size();
    if(m == 0) {
        cout << less.top() << " " << off << endl;
    } else if(n < m) {
        int mid = more.top();
        int dist = dmore + dless + n*(more.top()-less.top());
        cout << mid << " " << dist+off << endl;
    } else {
        int mid = less.top();
        int dist = dmore + dless + m*(more.top()-less.top());
        cout << mid << " " << dist+off << endl;
    }
}

