	segment_tree<Monoid::sum_t<>> seg_s(SZ(auni));

	segment_tree<Monoid::sum_t<>> seg(SZ(auni));

	ll cnt = 0;
	rep(i, 0, q) {
		if (f[i] == 1) {
			cnt++;
			sumb += b[i];
