std::multiset<int64_t> left, right;
int64_t result = 0;

void Update() {
  int64_t a, b;
  cin >> a >> b;
  result += b;
  int64_t leftmax  = *(--left.end());
  int64_t rightmin = *(right.begin());
  if (left.empty()) {
    left.insert(a);
    right.insert(a);
  } else if (a < leftmax) {
    left.insert(a);
    left.insert(a);
    left.erase(--(left.end()));
    right.insert(leftmax);
  } else if (rightmin < a) {
    right.insert(a);
    right.insert(a);
    right.erase(right.begin());
    left.insert(rightmin);
  } else {
    left.insert(a);
    right.insert(a);
  }
  if (left.empty() || (leftmax <= a && a <= rightmin)) {
    result += 0;
  } else if (rightmin < a) {
    result += (a - rightmin);
  } else {
    result += (leftmax - a);
  }
}
void Solve() {
  cout << *(--left.end()) << " " << result << endl;
}

int main(void) {
  cout << std::fixed << std::setprecision(10);
  cin.tie(0);
