void solve() {
  int Q; cin >> Q;
  pqdesc<int> mins;
  pqasc<int> maxs;
  i64 ans = 0;
  rep(_, Q) {
    int q; cin >> q;
    if (q == 1) {
      int a, b; cin >> a >> b;
      ans += b;
      mins.push(a), maxs.push(a);
      int mi = mins.top(), ma = maxs.top();
      if (mi > ma) {
        mins.pop(), maxs.pop();
        mins.push(ma), maxs.push(mi);
        ans += mi - ma;
      }
    } else {
      cout << mins.top() << " " << ans << '\n';
    }
  }
}

