int main() {
	cin >> Q;

	priority_queue<int> Al;
	priority_queue< int, std::vector<int>, std::greater<int> > Ar;
	ll A = 0, B = 0;

	ll a, b;
	cin >> type >> a >> b;
	Al.push(a);
	A = 0;
	B = b;

	REP(i, Q-1) {
		cin >> type;
		if (1 == type) {
			cin >> a >> b;
