				if (a <= Al.top()) {
					A += (Al.top() - a);
					Al.push(a);
					Ar.push(Al.top());
					Al.pop();
				} else {
					A += (a - Al.top());
					Ar.push(a);
				}
			} else { //偶数(Al.topとAr.topの間に入るならそれが最小値
				if (a <= Al.top()) {
					A += (Al.top() - a);
					Al.push(a);
				} else if (Ar.top() <= a) {
					A += (a - Ar.top());
					Ar.push(a);
					Al.push(Ar.top());
					Ar.pop();
				} else {
					Al.push(a);
