int q;
long long qi = 0,med = -1,sum = 0,bs = 0;

int main(){
    scanf("%d",&q);
    for(int i = 0; i < q; ++i){
        int opt;
        scanf("%d",&opt);
        if(opt == 1){
            long long a, b;
            scanf("%lld%lld",&a,&b);
            ++qi,bs += b;
            if(qi == 1)
                hmax.insert(a),
                med = a;
            else if(qi == 2){
                long long w = *hmax.begin();
                if(w <= a) hmin.insert(a);
                else
                    hmax.clear(),
                    hmax.insert(a),hmin.insert(w);
                med = *hmax.begin(),sum = *hmin.begin() - med;
            } else {
                unsigned vs1_size = hmax.size(), vs2_size = hmin.size();
                if(*hmax.rbegin() >= a){
                    hmax.insert(a);
                    if(hmax.size()-2 >= hmin.size()){
                        long long w = *hmax.rbegin();
                        hmax.erase(--hmax.end()),hmin.insert(w);
                    }
                } else {
                    hmin.insert(a);
                    if(hmin.size() > hmax.size()){
                        long long w = *hmin.begin();
                        hmin.erase(hmin.begin()),hmax.insert(w);
                    }
                }
                long long tmp = *hmax.rbegin();
                sum += abs(tmp - a), sum += abs(static_cast<long long>((tmp - med) * (vs1_size - vs2_size))), med = tmp;
            }
        } else printf("%lld %lld\n",med,sum+bs);
    }
    return 0;
}

