int Q;
ll Query[200005][3];
priority_queue<ll, vector<ll>, greater<ll> > right_que;
priority_queue<ll> left_que;
ll l_sum,r_sum, middle;

void relocate_que(ll x) {
  if (right_que.size()==0) { // 初回のみ
    ll l_top = left_que.top();
    if (l_top<=x) right_que.push(x);
    else {
      left_que.pop();
      left_que.push(x);
      right_que.push(l_top);  
    }
    middle = left_que.top();
    l_sum = middle-left_que.top();
    r_sum = right_que.top()-middle;
    return;
  }
  if (right_que.top()>x) {
    ll r_top = right_que.top();
    right_que.pop();
    right_que.push(x);
    left_que.push(r_top);
  } else if (left_que.top()<x) {
    ll l_top = left_que.top();
    left_que.pop();
    left_que.push(x);
    right_que.push(l_top);
  } else if (right_que.size()<left_que.size()) right_que.push(x);
  else left_que.push(x);
  assert(left_que.size()-right_que.size() <= 1);

  ll pre_middle = middle;
  middle = right_que.size() > left_que.size()?right_que.top():left_que.top();
  l_sum += (middle-left_que.top())*left_que.size();
  r_sum += (right_que.top()-middle)*right_que.size();
}

