      sz++;
      if (sz==1) {
        left_que.push(Query[i][1]);
        continue;
      }
      relocate_que(Query[i][1]);
    } else {
      ll a = right_que.size()>left_que.size()?right_que.top():left_que.top();
      cout << a << ' ';
      cout << B+l_sum+r_sum << endl;
    }
  }
  return 0;
}

