priority_queue <LL, vector<LL>,greater<int> > Q2;
priority_queue <LL> Q1;

LL k=0;
LL Ans=0;
//int sum1=0; int sum2=0;

void ADD(LL x){

	if(Q1.size()==0){
		Q1.push(x);
		return;
	}
	if(Q2.size()==0){
		if(x<Q1.top()){
			Q1.push(x);
			Q2.push(Q1.top());
			Q1.pop();
		}
		else
			Q2.push(x);
		Ans=Q2.top()-Q1.top();
		return;
	}

	int tot=Q1.size()+Q2.size();
	int lim=(tot+1+1)/2;
	if(Q1.top()>=x){
		//sum1+=x;
		Ans+=abs(Q1.top()-x);
		Q1.push(x);
	}
	else{
		//sum2+=x;
		Ans+=abs(Q1.top()-x);
		Q2.push(x);
	}
	while(Q1.size()>lim){
		Q2.push(Q1.top()); Q1.pop();
		Ans=Ans+(Q2.size()-Q1.size())*(Q2.top()-Q1.top());
	}
	while(Q1.size()<lim){
		int tri=Q2.top()-Q1.top();
		Q1.push(Q2.top()); Q2.pop();
		Ans=Ans+((Q1.size()-1)-(Q2.size()+1))*tri;
	}
}

int main(){

	int n=read();
	FOR(i,1,n){

		int mode=read();

		if(mode==1){
			ADD(read());
			k+=read();
			//cout<<" A "<<Ans<<endl;
			//cout<<" Q "<<Q1.top()<<endl;
		}
		else{
			cout<<Q1.top()<<" "<<Ans+k<<endl;
		}

	}

	return 0;
}

