数を追加する .push
最小の値を得る .top
最小の値を取り出す .pop O(log n)

逆順に解く
最大値をとるところから順に操作していく
*/
priority_queue<ll> zen;
priority_queue<ll,vector<ll>, greater<ll>> kou;
vector<ll> a,b;
ll b_sum = 0;

int main() {
	// 入力
    ll Q;cin>>Q;
    ll zensum = 0;
    ll kousum = 0;
    // printf("Q: %lld\n", Q);
    REP(i,Q){
        ll tmp;
        cin>>tmp;
        if (tmp==1){// f(x)の更新
            // printf("query = 1\n");
            ll a_tmp, b_tmp;cin>>a_tmp>>b_tmp;
            a.pb(a_tmp);b.pb(b_tmp);b_sum+=b_tmp;

            if (zen.size()==0){
                zen.push(a_tmp);zensum += a_tmp; // 前半に追加
            }
            else if (a_tmp>zen.top()){//aが前半の最大値より大きい
                kou.push(a_tmp);kousum += a_tmp; // 後半に追加
            }
            else{
                zen.push(a_tmp);zensum += a_tmp; // 前半に追加
            }
            if (zen.size()<kou.size()){// 後半が前半より多い
                zen.push(kou.top());zensum += kou.top(); // 後半の最小値を前半へ
                kousum -= kou.top();kou.pop();
            }
            if (zen.size()>=kou.size()+2){ // 前半が後半より2多い
                kou.push(zen.top());kousum += zen.top();
                zensum -= zen.top();zen.pop();
            }
            // printf("zen size: %i, kou size: %i\n", zen.size(), kou.size());
            // if (zen.size()>0) printf("zen top :%lld\n", zen.top());
            // if (kou.size()>0) printf("kou top :%lld\n", kou.top());
        }
        else{// f(x)の最小値の出力
            // printf("query = 2\n");
            ll x = zen.top();
            ll ans = (x*zen.size()-zensum) + (kousum-x*kou.size()) + b_sum;
            // REP(i,a.size()){
            //     ans += abs(a[i]-x);
            // }
            // printf("x: %lld. min: %lld\n", x, ans);
            printf("%lld %lld\n", x, ans);
        }
        // printf("zen %lld\n", zen.top());
    }
}

