#include <bits/stdc++.h>
#define LL long long
#define lson rt<<1
#define rson rt<<1|1
#define LS lson,l,mid
#define RS rson,mid+1,r
using namespace std;
const int maxn = 2e5+10;
int tree[maxn<<2];
LL add[maxn<<2];
int a[maxn], tot, ty[maxn], b[maxn] ,c[maxn];
void upd(int rt,int l,int r,int pos, LL t){
    if (l == r){
        tree[rt]++;
        add[rt] += t;
        return;
    }
    int mid = (l+r) >> 1;
    if (pos <= mid) upd(LS,pos,t);
    if (mid <  pos) upd(RS,pos,t);
    tree[rt] = tree[lson] + tree[rson];
    add[rt] = add[lson] + add[rson];
}
void query(int rt,int l,int r,int rest, int &pos){
    if (l == r){
        pos = l;
        return;
    }
    int mid = (l + r) >>1;
    if (tree[lson] >= rest) query(LS, rest, pos);
    else{
        rest -= tree[lson];
        query(RS, rest, pos);
    }
}
LL qs(int rt,int l,int r,int L,int R){
    if (L <= l && r <= R) return add[rt];
    int mid = (l + r) >> 1;
    LL ans = 0 ;
    if (L <= mid) ans += qs(LS, L, R);
    if (mid < R)  ans += qs(RS, L, R);
    return ans;
}
int qn(int rt,int l,int r,int L,int R){
    if (L <= l && r <= R) return tree[rt];
    int mid = (l + r) >> 1;
    int ans = 0 ;
    if (L <= mid) ans += qn(LS, L, R);
    if (mid < R)  ans += qn(RS, L, R);
    return ans;
}
