            LL cntl = qs(1, 1, tot, 1, pos);
            int cl = qn(1, 1, tot, 1, pos);
            LL cntr = pos + 1 > tot ? 0 : qs(1, 1, tot, min(tot, pos+1), tot);
            int cr = pos + 1 > tot ? 0 : qn(1, 1, tot, min(tot, pos+1), tot);

