priority_queue<li> pq[2];

li add_base = 0;

inline void add(li a) {
    pq[0].push(a);
    while (sz(pq[0]) > sz(pq[1]) + 1) {
        li pass = pq[0].top();
        pq[0].pop();
        pq[1].push(-pass);
        add_base += -pq[1].top() - pq[0].top();
    }
}

