struct segmentTree{
    vector<lli> node;
    int n;

    segmentTree(vector<lli> v){
        int s = v.size();
        n = 2;
        while(n < s) n *= 2;
        node = vector<lli>(2*n -1, 0);
        for(int i=0; i<s; i++){
            node[i +n-1] = v[i];
        }
        for(int i=n-2; i>=0; i--){
            node[i] = node[2*i +1] +node[2*i +2];
        }
    }
    segmentTree(){}

    void Set(lli val, int pos){
        int idx = n-1 + pos;
        node[idx] = val;
        do{
            idx = (idx -1)/2;
            node[idx] = node[2*idx +1] +node[2*idx +2];
        }while(idx != 0);
    }
    int Get(int l, int r){
        if(l == r) return 0;
        return _get(l, r, 0, 0, n);
    }
    int _get(int l, int r, int k, int cl, int cr){
        if(l <= cl && cr <= r){
            return node[k];
        }
        if(r <= cl || cr <= l){
            return 0;
        }
        int m = (cl +cr)/2;
        return _get(l, r, 2*k+1, cl, m) + _get(l, r, 2*k+2, m, cr);
    }
};

