int main() {
    priority_queue<ll> zen;
    priority_queue<ll, vl, greater<>> kou;
    int q;
    ll z_sum = 0, k_sum = 0, sum = 0;
    cin >> q;
    rep(i, q) {
        int t;
        cin >> t;
        if(t == 1) {
            cin >> A[i] >> B[i];
            sum += B[i];
            if(zen.size() > kou.size()){
                int x = zen.top();
                if(A[i] >= x) {
                    kou.push(x);
                    k_sum += x;
                }
                else {
                    zen.pop(); z_sum -= x;
                    zen.push(A[i]); z_sum += A[i];
                    kou.push(x); k_sum += x;
                }
            }
            else {
                if(zen.empty()) zen.push(A[i]), z_sum += A[i];
                else{
                    int x = kou.top();
                    if(A[i] <= x) zen.push(A[i]), z_sum += A[i];
                    else {
                        kou.pop(), k_sum -= x;
                        kou.push(A[i]), k_sum += A[i];
                        zen.push(x), z_sum += x;
                    }
                }
            }
        }
        else {
            ll y = zen.top();
            ll ans = y * zen.size() - z_sum + k_sum - y * kou.size() + sum;
            cout << y << " " << ans << endl;
        }
