using namespace std;
using LLONG = long long;

int main()
{
    int Q;
    cin >> Q;
    LLONG a, b, bsum = 0;
    bool flat = true;
    LLONG left = -1e10, right = 1e10;
    LLONG peak;
    for (int i = 0; i < Q; ++i)
    {
        int type;
        cin >> type;
        // 更新クエリ
        if (type == 1)
        {
            cin >> a >> b;
            bsum += b;
            // フラットな最低値領域が存在しているとき
            if (flat)
            {
                flat = false;
                // 追加ピークがフラット領域の左側ならば，左側が新しいピークになり，
                // 追加ピーク位置からフラット領域右端までが傾き１の領域になる
                if (a < left)
                {
                    bsum += left - a;
                    peak = left;
                    left = a;
                }
                // 追加ピークがフラット領域の右側ならば，右側が新しいピークに
                // 領域左端から追加ピーク位置までが傾き１の領域になる
                else if (right < a)
                {
                    bsum += a - right;
                    peak = right;
                    right = a;
                }
                // 追加ピークがフラット領域内ならば，そのまま新しいピークに
                // 領域はそのまま
                else
                {
                    peak = a;
                }
            }
            // ピークが存在しているとき
            else
            {
                flat = true;
                bsum += abs(a - peak);
                if (a < left)
                {
                    left = a;
                    right = peak;
                }
                else if (right < a)
                {
                    left = peak;
                    right = a;
                }
                else
                {
                    left = a < peak ? a : peak;
                    right = a < peak ? peak : a;
                }
            }
        }
        // 求値クエリ
        else
        {
            if (flat)
            {
                cout << left << ' ' << bsum << endl;
            }
            else
            {
                cout << peak << ' ' << bsum << endl;
            }
        }
    }

    return 0;
}

