constexpr ll lsb(ll x){ return x&(-x);}

struct fenwick{
  vector<ll> ft;

  void init(int n){
    ft.resize(n+5);
  }

  void add(ll k,ll val){
    for(++k;k<conv.size();k+=lsb(k))
      ft[k] += val;
  }

  ll query(ll k){
    ll ans = 0;
    for(++k;k;k-=lsb(k))
      ans += ft[k];
    return ans;
  }
};

fenwick m,q;

vector<tuple<bool,ll,ll>> query;

ll eval(ll x){
  return m.query(x) * conv[x] + q.query(x);
}


