template< typename T >
struct BinaryIndexedTree {
  vector< T > data;
  int n;

  BinaryIndexedTree(int sz) {
    n=sz;
    data.assign(++sz, 0);
  }

  T sum(int k) { //0-indexed
    T ret = 0;
    for(++k; k > 0; k -= k & -k) ret += data[k];
    return (ret);
  }

  void add(int k, T x) { 
    for(++k; k < data.size(); k += k & -k) data[k] += x;
  }

  T sum_between(int i, int j){
      if(i>j)return 0;
      return sum(j)-sum(i-1);
  }

  // data[0]+...+data[ret+1] >= x
  int lower_bound(T w){
    if(w<=0)return 0;
    int x=0;
    int k=1;
    while(2*k<=n)k<<=1;
    for(;k>0;k/=2){
      if(x+k<=n&&data[x+k]<w){
        w-=data[x+k];
        x+=k;
      }
    }
    return x+1;
  }
};

