typedef long long ll;

const ll N = (ll) 2e5 + 7;

ll n;
map <ll, ll> normal;
ll cur_normal = 0;

struct Question {
        ll type;
        ll a, b;
        ll i;
};

Question q[N];



ll t_sum[N]; /// <--- Fenwick Tree for sum
ll value[N];

ll prefix_sum(ll p) {
        ll r = 0LL;
        for (ll i = p; i >= 1; i -= i & (-i)) {
                r += t_sum[i];
        }
        return r;
}

void add_sum(ll p, ll x) {
        for (ll i = p; i < N; i += i & (-i)) {
                t_sum[i] += x;
        }
}

ll t_cnt[N]; /// <--- Fenwick Tree for cnt

ll prefix_cnt(ll p) {
        ll r = 0;
        for (ll i = p; i >= 1; i -= i & (-i)) {
                r += t_cnt[i];
        }
        return r;
}

void add_cnt(ll p, ll x) {
        for (ll i = p; i < N; i += i & (-i)) {
                t_cnt[i] += x;
        }
}

ll find_k(ll k) {
        ll r = 0, pas = (1 << 17);
        while (pas > 0) {
                if (r + pas < N && prefix_cnt(r + pas) < k) {
                        r += pas;
                }
                pas >>= 1;
        }
        r++;
        return r;
}

/// Operators for Question :

bool cmp1(Question x, Question y) {
        return x.a < y.a;
}

bool cmp2(Question x, Question y) {
        return x.i < y.i;
}

signed main() {
        ios::sync_with_stdio(false);
        cin.tie(0);

        cin >> n;
        for (ll i = 1; i <= n; i++) {
                cin >> q[i].type;
                if (q[i].type == 1) {
                        cin >> q[i].a >> q[i].b;
                }
                q[i].i = i;
        }

        sort(q + 1, q + n + 1, cmp1);

        for (ll i = 1; i <= n; i++) {
                if (q[i].type == 1) {
                        if (normal[q[i].a] == 0) {
                                cur_normal++;
                                normal[q[i].a] = cur_normal;
                                value[cur_normal] = q[i].a;
                        }
                }
        }

        sort(q + 1, q + n + 1, cmp2);

        ll bSum = 0LL, aSum = 0LL;
        ll cate = 0;

        for (ll i = 1; i <= n; i++) {
                if (q[i].type == 1) {
                        bSum += q[i].b;
                        aSum += q[i].a;
                        ll x = normal[q[i].a];
                        add_cnt(x, 1);
                        add_sum(x, value[x]);
                        cate++;
                } else {
                        ll poz = find_k((cate + 1) / 2);
                        ll FirstHalf = (cate + 1) / 2, SecondHalf = cate - FirstHalf;
                        ll SumFirstHalf = prefix_sum(poz - 1) + (FirstHalf - prefix_cnt(poz - 1)) * value[poz], SumSecondHalf = aSum - SumFirstHalf;
                        ll total = bSum + (FirstHalf * value[poz] - SumFirstHalf) + (SumSecondHalf - value[poz] * SecondHalf);

                        cout << value[poz] << " " << total << "\n";
                }
        }

}

