template<class comp>
class sum_pri_queue : public priority_queue<ll, deque<ll>, comp> {
private:
    ll ss = 0;
public:
    void push2(ll n) {
        this->push(n);
        ss += n;
    }

    ll pop2() {
        auto r = this->top();
        ss -= r;
        this->pop();
        return r;
    }

    ll sum() {
        return ss;
    }
};

int main() {
    ll a, b, c, p = 0, q;
    cin >> q;
    sum_pri_queue<greater<>> bigger;
    sum_pri_queue<less<>> smaller;
    for (ll i = 0; i < q; i++) {
        cin >> c;
