            if (bigger.size() == smaller.size()) smaller.push2(a);
            else bigger.push2(a);
            while ((!bigger.empty()) && smaller.top() > bigger.top()) {
                smaller.push2(bigger.pop2());
                bigger.push2(smaller.pop2());
            }
        } else if (c == 2) {
            ll center = smaller.top();
            ll r = center * smaller.size() - smaller.sum() + bigger.sum() - center * bigger.size();
