int push_alt(vector<int>x, int a){
    int lb = -1;
    int ub = x.size();
    int mid;
    while (ub - lb > 1) {
        mid = (ub+lb)/2;
        if (x[mid]>=a){
            ub = mid;
        }
        else{
            lb = mid;
        }
    }
    return ub;
}



