                upper_a.insert(a);
                upper_a_sum += a;
            }
            if (lower_a.size() > 0 && upper_a.size() > 0) {
                int x = *lower_a.rbegin();
                int y = *upper_a.begin();
                if (x > y) {
                    lower_a.erase(lower_a.find(x));
