struct SegmentTree{
  ll n;
  vll tree;

  SegmentTree(ll len){
    n=1;
    while(len>n)
      n*=2;

    tree.assign(2*n-1, 0);
  }

  void update(ll index, ll value){
    index += n-1;
    tree[index] += value;

    while(index>0){
      index=(index-1)/2;
      tree[index] = tree[index*2+1]+tree[index*2+2];
    }
  }


  //[a, b)
  ll query(ll a, ll b){
    return query(a,b,0,0,n);
  }

  ll query(ll a, ll b, ll index, ll l, ll r){
    if(b<=l || r<=a)
      return 0;

    if(a<=l && r<=b)
      return tree[index];

    ll value_l = query(a,b,2*index+1,l,(l+r)/2);
    ll value_r = query(a,b,2*index+2,(l+r)/2,r);
    return value_l+value_r;
  }

  ll lower_bound(ll m){
    ll ok=n;
    ll ng=0;
    while(ok-ng>1){
      ll mid=(ok+ng)/2;
      if(m<=query(0,mid))
        ok=mid;
      else
        ng=mid;
    }

    return ok-1;
  }
};


