void solve() {
    int N; cin >> N;
    priority_queue<ll> dw;
    priority_queue<ll, vector<ll>, greater<ll>> up;
    ll cnt1=0, cnt2=0, sum1=0, sum2=0, sumb=0;
    rep(i, N){
        int q; cin >> q;
        if(q == 1){
            ll a, b; cin >> a >> b;
            sumb += b;
            if(up.empty()){
                up.push(a);
                cnt2++;
                sum2 += a;
                continue;
            }
            if(dw.empty()){
                dw.push(a);
                cnt1++;
                sum1 += a;

                ll td = dw.top(), tu = up.top();
                if(td > tu){
                    sum1 += tu - td;
                    sum2 += td - tu;
                    dw.pop();
                    up.pop();
                    dw.push(tu);
                    up.push(td);
                }
                continue;
            }
            if(cnt1 == cnt2) {
                up.push(a);
                cnt2++;
                sum2 += a;
            }else{
                up.push(a);
                sum2 += a;
                dw.push(up.top());
                sum1 += up.top();
                sum2 -= up.top();
                up.pop();
                cnt1++;
            }
        }else{
            if(cnt1 == cnt2){
                cout << dw.top() << " " << sumb + abs(sum1-sum2) << endl;
            }else{
                cout << up.top() << " " << sumb + abs(sum1-sum2) - abs(up.top()) << endl;
            }
        }
    }
}

