multiset<ii> s;

long long ans[100005];

long long left1 = 0;
long long right1 = 0;

multiset<ii>::iterator median;

void insert1(ii x){
	if(s.empty()){
		s.insert(x);
		median = s.begin();
	}else if(s.size() % 2 == 1){
		if(x > (*median)){
			s.insert(x);
			right1 += x.first;
		}else{
			s.insert(x);
			left1 += x.first;
			right1 += (*median).first;
			median --;
			left1 -= (*median).first;
		}
	}else{
		if(x > (*median)){
			s.insert(x);
			right1 += x.first;
			left1 += (*median).first;
			median ++;
			right1 -= (*median).first;
		}else{
			s.insert(x);
			left1 += x.first;
		}
	}
}

