			while( bot < top ){
				xint L= Sum( bot, As );
				xint R= Sum( top, As );
				xint C= Sum( mid, As );

				if( L > C && C > R ){
					bot= mid;
				}else if( L < C && C < R ){
					top= mid;
				}else if( L > R ){
					if( bot== mid ) bot++;
					else bot= mid;
				}else{
					if( top== mid ) top--;
