  SegmentTree<int> seg(aa.size(), [](int x, int y) { return x + y; }, 0);
  SegmentTree<int> teg(aa.size(), [](int x, int y) { return x + y; }, 0);

  RBST<int> rbst;
  int B = 0;
  rep(i, 0, Q) {
    int q = qs[i].t;

    if (q == 1) {
