template<class T>
struct side{
	T st;
	ll size;
	ll su;
	side(){
		st = T();
		size  = 0;
		su = 0;
	}
	ll remove(){
		ll ret = st.top();
		st.pop();
		size--;
		su -= ret;
		return ret;
	}
	void add(ll x){
		st.push(x);
		su+=x;
		size++;
		return;
	}
	ll cal(ll x){
		return abs(size*x - su);
	}
};

struct minima{
	side<MaxHeap<ll>> small;
	side<MinHeap<ll>> large;
	ll cons;
	minima(){
		small = side<MaxHeap<ll>>();
		large = side<MinHeap<ll>>();
		cons = 0;
	}
	void add(ll a, ll b){
		cons += b;
		if(small.st.top() < a){
			large.add(a);
			if(large.size > small.size){
				small.add(large.remove());
			}
		}
		else{
			small.add(a);
			if(small.size > large.size+1){
				large.add(small.remove());
			}
		}
	}
	Pll query(){
		int mi = small.st.top();
		return mapa(mi, cons + large.cal(mi) + small.cal(mi));
	}
};


