            if(a >= mid)
            {
                high.push(a);
                high_s += a - mid;
                int lsize = low.size();
                int hsize = high.size();
                if(lsize + 2 == hsize)
                {
                    int newmid = high.top();
                    low_s += lsize * (newmid - mid) + newmid - mid;
                    low.push(mid);
                    high_s -= (hsize-1) * (newmid - mid);
                    high_s -= newmid - mid;
