    sort(all(abs), [](auto l, auto r){ return l.first<r.first; });
    ll last = -1, count = 0;
    unordered_map<ll, ll> m;
    vll xs;
    rep(i, abs.size()){
        if(last!=abs[i].first){
            m[abs[i].first] = count;
            xs.push_back(abs[i].first);
            ++count;
        }
        last = abs[i].first;
    }

    ll n = m.size();
    SSTree t1 = SSTree(n+1);
    SSTree t2 = SSTree(n+1);

    rep(i, Q){
