#define mod 1000000007

long long int getabssum(vector<long long int> a, long long int x)
{
	long long int ans = 0;
	for(int i = 0; i < a.size(); i++){
		ans += abs(x - a[i]);
	}
	return ans;
}

void solve(vector<long long int> a, long long int b)
{
	long long int l = -mod;
	long long int r = mod;
	while(r - l > 2){
		long long int mid1 = l + (r - l) / 3;
		long long int mid2 = l + (2 * (r - l)) / 3;
		long long int ans1 = getabssum(a, mid1);
		long long int ans2 = getabssum(a, mid2);
		if(ans1 > ans2){
			l = mid1;
		} else {
			r = mid2;
		}
	}
	long long int ans1 = getabssum(a, l);
	long long int ans2 = getabssum(a, l + 1);
	long long int ans3 = getabssum(a, l + 2);
	long long int minans = min(ans1, min(ans2, ans3));
	if(minans == ans1) cout << l << " " << ans1 + b << endl;
	else if(minans == ans2) cout << l + 1 << " " << ans2 + b << endl;
	else cout << l + 2 << " " << ans3 + b << endl;
}

