class Median {
private:
    priority_queue<ll> former;
    priority_queue<ll,vector<ll>,greater<ll>> latter;
public:
    Median();
    void add(ll x);
    ll get();
    ~Median();
};

Median::Median() {
}

// add a number into data structure
void Median::add(ll x) {
    // どちらに入る？
    if (former.empty()) {
        former.push(x);
    }
    else {
        ll former_top = former.top();
        if (former_top < x) latter.push(x);
        else former.push(x);
    }

    // 数を合わせる
    // when latter has one more element
    if ((int)latter.size()-1 == (int)former.size()) {
        ll tmp = latter.top(); latter.pop();
        former.push(tmp);
    }
    // when former has two more elements
    else if ((int)(former.size())-2 == (int)latter.size()) {
        ll tmp = former.top(); former.pop();
        latter.push(tmp);
    }
    else if ((int)former.size() == (int)latter.size() || (int)former.size()-1 == (int)latter.size()) {}
    else {
        cout << "I don't believe this situation" << '\n';
        cout << "the size of former is " << former.size() << '\n';
        cout << "and the size of latter is " << latter.size() << '\n';
    }
}

// get the median
ll Median::get() {
    return former.top();
}

Median::~Median() {
}


int main(int argc, char const *argv[]) {
    int q; cin>>q;
    Median med;
    ll b_sum = 0;
    ll pl = 0; int pl_cnt = 0;
    ll mi = 0; int mi_cnt = 0;
    while (q--) {
        int type; cin>>type;
        if (type==1) {
            ll a,b; cin>>a>>b;
            med.add(a);
            if (a>0) {
                pl_cnt++;
                pl += a;
            }
            else {
                mi_cnt++;
                mi -= a;
            }
            b_sum += b;
        }
        else {
            ll m = med.get();
            ll ret = 0;
            ret += (pl - (m*pl_cnt));
            ret += (mi + (m*mi_cnt));
            ret += b_sum;
            cout << m << ' ' << ret << '\n';
        }
    }
    return 0;
}

