    priority_queue<int> q0;
    priority_queue<int, vector<int>, greater<>> q1;
    ll s0 = 0, s1 = 0;

    ll s = 0;
    int k = 0;

    for (int h = 0; h < q; h++) {
        int t;
        cin >> t;

        if (t == 1) {
            int a, b;
            cin >> a >> b;

            if (k % 2 == 0) {
                auto v = k == 0 ? a : q1.top();
                if (a > v) {
                    q0.push(v);
                    s0 += v;
                    q1.pop();
                    s1 -= v;
                    q1.push(a);
                    s1 += a;
                } else {
                    q0.push(a);
                    s0 += a;
                }
            } else {
                auto v = q0.top();
                if (a < v) {
                    q1.push(v);
                    s1 += v;
                    q0.pop();
                    s0 -= v;
                    q0.push(a);
                    s0 += a;
                } else {
                    q1.push(a);
                    s1 += a;
                }
            }

            s += b;
            k++;

        } else {
            auto x = q0.top();
            auto r = ((ll)q0.size() * x - s0) + (s1 - (ll)q1.size() * x) + s;
