int main(){
    using namespace std;
    size_t Q;
    cin >> Q;
    priority_queue<long, vector<long>, less<>> pq1;
    priority_queue<long, vector<long>, greater<>> pq2;
    long C{0};
    for(unsigned long i = 0, a, b; i < Q; ++i){
        char c;
        cin >> c;
        if(c == '1'){
            cin >> a >> b;
            C += b;
            pq1.push(a);
            C -= a;
            auto t = pq1.top();
            pq1.pop();
            C += 2 * t;
            pq2.push(t);
            if(pq1.size() < pq2.size()){
                auto k = pq2.top();
                pq2.pop();
                C -= 2 * k;
                pq1.push(k);
            }
        }else cout << pq1.top() << " " << C + (pq1.size() != pq2.size()) * pq1.top() << endl;
    }
    return 0;
}

