void change(int now,int l,int r,int ql,int qr,ll num)
{
    if(l==ql&&r==qr){pushit(now,num);return;}
    pushdown(now);
    if(qr<=mid)change(lnode,l,mid,ql,qr,num);
    else if(ql>mid)change(rnode,mid+1,r,ql,qr,num);
    else change(lnode,l,mid,ql,mid,num),change(rnode,mid+1,r,mid+1,qr,num);
    tree[now]=tree[lnode]+tree[rnode];
}
