#include <bits/stdc++.h>

using namespace std;
using ll = long long;
using ii = pair<ll, ll>;

struct Query { ll cmd, a, b; };

vector<ii> solve(const vector<Query>& qs)
{
    vector<ii> ans;

    priority_queue<int> L;
    priority_queue<int, vector<int>, greater<int>> R;

    ll ls = 0, rs = 0, bs = 0;

    for (auto q : qs)
    {
        switch (q.cmd) {
        case 1:
            {
                L.push(q.a);
                ls += q.a;

                while (not R.empty() and L.top() > R.top())
                {
                    auto x = L.top(), y = R.top();

                    L.pop();
                    R.pop();

                    ls -= x;
                    ls += y;
                    L.push(y);

                    rs -= y;
                    rs += x;
                    R.push(x);
                }

                if (L.size() - R.size() > 1)
                {
                    auto x = L.top();
                    L.pop();

                    ls -= x;
                    rs += x;

                    R.push(x);
                }

                bs += q.b;
            } 
            break;

        default:
            {
                auto median = L.top();
                auto f = bs + (median * L.size() - ls) + (rs - median * R.size());

//cout << "-- median: " << median << endl;
//cout << "-- f: " << f << endl;

                ans.push_back(ii(median, f));
            }

            break;
        }
    }

    return ans;
}

