{
    ios::sync_with_stdio(false);

    int Q;
    cin >> Q;

    vector<Query> qs(Q);

    for (int i = 0; i < Q; ++i)
    {
        cin >> qs[i].cmd;

        if (qs[i].cmd == 2)
            continue;

        cin >> qs[i].a >> qs[i].b;
    }

    auto ans = solve(qs);

    for (auto p : ans)
        cout << p.first << ' ' << p.second << '\n';

    return 0;
}

