			pe(med); print(sm + B);
		}
		else {
			int a = aa[i], b = bb[i];
			B += b;
			int x = a;
			if (st.size() % 2 == 1) {
				//左にずれる
				if (x < med) {
					st.insert(x);
					itr--;
					sm += abs(med - x);
					med = *itr;
				}
				//ずれない
				else if (x == med) {
					st.insert(x);
					med = *itr;
				}
				//ずれない
				else {
					st.insert(x);
					sm += abs(med - x);
				}
			}
			else {
				//ずれない
				if (x < med) {
					st.insert(x);
					sm += abs(med - x);
					med = *itr;
				}
				//ずれない
				else if (x == med) {
					st.insert(x);
					itr++; med = *itr;
				}
				//右にずれる
				else {
					auto itr2 = itr; itr2++;
					int med2 = *itr2;					

					if (x <= med2) {
						st.insert(x);
						itr++;
						med = *itr;
					}
					else {
						int d = med2 - med;
						int N = st.size();
						sm += d * (N / 2 - 1);
						sm -= d * (N - 1 - N / 2);
						sm += abs(med2 - x);
						st.insert(x);
						itr++;
						med = *itr;
					}
				}
			}
		}
	}
}

