    cin.tie(0);


    int n;
    cin >> n;

    priority_queue<int> first; // 5 4 1
    priority_queue<int, vector<int>, greater<int> > latter; // 6 7 9

    ll sum_first = 0, sum_latter = 0;
    ll cons = 0; // 定数項の和

    while (n--) {
        int que;
        cin >> que;
        if (que == 2) {
            int x = first.top();
            cout << x << " ";
            out(1LL * sz(first) * x - sum_first + sum_latter - 1LL * sz(latter) * x + cons);
        } else {
            int a, b;
            cin >> a >> b;

            cons += b;

            // 基本firstに埋めていく方針で
            if (sz(first) > sz(latter)) {
                // latterに埋める
                if (sz(latter) == 0 || a < latter.top()) {
                    int tmp = first.top();
                    latter.push(tmp);
                    first.pop();
                    first.push(a);

                    sum_first += a - tmp;
                    sum_latter += tmp;
                } else {
                    latter.push(a);

                    sum_latter += a;
                }
            } else { // firstに埋める
                if (sz(first) == 0) { // ないとbad access
                    first.push(a);

                    sum_first += a;
                }
                if (a > first.top()) {
                    int tmp = latter.top();
                    first.push(tmp);
                    latter.pop();
                    latter.push(a);

                    sum_first += tmp;
                    sum_latter += a - tmp;
                } else {
                    first.push(a);

                    sum_first += a;
                }
            }
        }
    }
