int main()
{
    int q;
    ll ans = 0;
    priority_queue<int> left;
    priority_queue<int, vector<int>, greater<int>> right;
    int mid = inf;
    scanf("%d", &q);
    while (q--)
    {
        int op;
        scanf("%d", &op);
        if (op == 1)
        {
            int x, y;
            scanf("%d%d", &x, &y);
            ans += y;
            if (mid == inf)
            {
                if (left.empty())
                    mid = x;
                else
                {
                    if (x >= left.top())
                    {
                        if (x < right.top())
                            mid = x;
                        else
                        {
                            right.push(x);
                            mid = right.top(), right.pop();
                            ans += x - mid;
                        }
                    }
                    else
                    {
                        left.push(x);
                        mid = left.top(), left.pop();
                        ans += mid - x;
                    }
                }
            }
            else
            {
                if (left.empty())
                {
                    left.push(min(mid, x)), right.push(max(mid, x));
                    ans += abs(mid - x), mid = inf;
                }
                else
                {
                    if (x >= mid)
                    {
                        right.push(x), left.push(mid);
                        ans += x - mid, mid = inf;
                    }
                    else
                    {
                        left.push(x), right.push(mid);
                        ans += mid - x, mid = inf;
                    }
                }
            }
        }
        else
        {
