constexpr ll lsb(ll x){ return x&(-x);}

struct fenwick{
  unordered_map<ll,ll> ft;

  void add(ll k,ll val){
    k += 1e9 + 100;
    for(++k;k<=3e9;k+=lsb(k))
      ft[k] += val;
  }

  ll query(ll k){
    k += 1e9 + 100;
    ll ans = 0;
    for(++k;k;k-=lsb(k))
      ans+=ft[k];
    return ans;
  }
};

fenwick m,q;

ll eval(ll x){
  return m.query(x) * x + q.query(x);
}


