      q.add(a,-2*a);
    }else{
      ll l = -1e9 - 1;
      ll r = 1e9 + 2;
      while(l<r){
        ll mid = l + (r-l)/2;
        if(eval(mid) <= eval(mid + 1)){
          r = mid;
        }else{
          l = mid+1;
        }
      }
