                    auto itr = left.end();
                    --itr;
                    temp.insert(*itr);
                    left.erase(itr);
                    leftSum -= *itr;
                }
                {
                    // right
                    auto itr = right.begin();
                    temp.insert(*itr);
                    right.erase(itr);
                    rightSum -= *itr;
                }
                left.insert(*temp.begin());
                leftSum += *temp.begin();
                right.insert(*temp.rbegin());
                rightSum += *temp.rbegin();
                middle = *next(temp.begin(), 1);
            }
            calc();
        } else {
            int down = min(a, middle);
            int up = max(a, middle);
            left.insert(down);
            leftSum += down;
            right.insert(up);
            rightSum += up;
            middle = -1;
            calc();
        }
    };

    for (int i = 0; i < Q; i++) {
        int q;
        cin >> q;
        if (q == 1) {
            int a, b;
            cin >> a >> b;
            update(a, b);
        } else {
            cout << ans.first << " " << ans.second << endl;
        }
    }
}

