            rec[i][0]=op;
            if(op==1)
            {
                ll a,b;
                scanf("%lld %lld",&a,&b);
                rec[i][1]=a;rec[i][2]=b;
                bb[++cnt]=a;
                bb[++cnt]=a-1;
                bb[++cnt]=a+1;
            }
        }
        solve();
    }
}
