#include <bits/stdc++.h>

using namespace std;
using ll = long long;

template <typename T>
struct BIT {
	int N;
	vector<T> data;

	BIT(int n) {
		N = n;
		data.assign(N, 0);
	}

	T sum(int idx) {
		T ret = 0;
		for (int i = idx; i > 0; i -= i & -i) { ret += data[i]; }
		return ret;
	}
	T sum(int l, int r) {
		if (l > r) { return 0; }
		return sum(r) - sum(l - 1);
	}
	T all() { return sum(N - 1); }

	void add(int idx, T x) {
		for (int i = idx; i <= N; i += i & -i) { data[i] += x; }
	}

	// data[1]+...data[m] >= x となる最小のm 
	int lower_bound(T x) {
		int ret = 0;
		int k = 1;
		while (2*k <= N) { k <<= 1; }
		for ( ; k > 0; k >>= 1) {
			if (ret + k <= N && data[ret + k] < x) {
				x -= data[ret + k];
				ret += k;
			}
		}
		return ret + 1;
	}
};

int main() {
	const ll INF = 1e18;
	int Q;
	cin >> Q;
	vector<int> q(Q);
	vector<ll> a(Q), b(Q);
	vector<ll> unzip;
	for (int i = 0; i < Q; ++i) {
		cin >> q[i];
		if (q[i] == 1) {
			cin >> a[i] >> b[i];
			unzip.push_back(a[i]);
		}
	}

	unzip.push_back(-INF);
	sort(unzip.begin(), unzip.end());
	unzip.erase(unique(unzip.begin(), unzip.end()), unzip.end());
	map<ll, int> zip;
	int sz = unzip.size();
	for (int i = 0; i < sz; ++i) { zip[unzip[i]] = i; }

	BIT<ll> bitnum(sz);
	BIT<ll> bitsum(sz);
	ll sumB = 0;
	for (int i = 0; i < Q; ++i) {
		if (q[i] == 1) {
			sumB += b[i];
			bitnum.add(zip[a[i]], 1);
			bitsum.add(zip[a[i]], a[i]);
		} else {
			int m = bitnum.lower_bound((bitnum.all() + 1) / 2);
			ll x = unzip[m];
			ll f = sumB;
			f += (x*bitnum.sum(1, m) - bitsum.sum(1, m));
			f += (bitsum.sum(m, sz - 1) - x*bitnum.sum(m, sz - 1));
