int64_t nth_rec(std::vector<int64_t> &xs, size_t begin, size_t end, size_t n) {
    size_t len = end - begin;
    size_t n_left = 0, n_right = 0;
    while (n_left + n_right + 1 < len) {
        if (xs[begin + n_left] > xs[begin + n_left + 1]) {
            std::swap(xs[begin + n_left], xs[begin + n_left + 1]);
            n_left++;
        } else {
            std::swap(xs[begin + n_left+1], xs[begin + len - 1 - n_right]);
            n_right++;
        }
    }

    if (n_left == n) {
        return xs[begin + n];
    } else if (n_left < n) {
        return nth_rec(xs, begin + n_left + 1, end, n - n_left - 1);
    } else {
        return nth_rec(xs, begin, begin + n_left, n);
    }

}

int64_t nth(std::vector<int64_t> &xs, size_t n) {
    return nth_rec(xs, 0, xs.size(), n);
}

int64_t eval(const std::vector<int64_t> &minimas, int64_t b_sum, int64_t x) {
    int64_t y = b_sum;
    for (auto a : minimas) {
        y += std::abs(a - x);
    }
    return y;
}

int64_t bf(const std::vector<int64_t> &minimas, int64_t b_sum) {
    int64_t x_begin = *std::min_element(minimas.begin(), minimas.end());
    int64_t x_end = 1 + *std::max_element(minimas.begin(), minimas.end());

    int64_t minx = x_begin;
    int64_t minval = eval(minimas, b_sum, minx);

