void update(int a, int b) {
  bsum += b;

  if (maxh.size() == 0 || maxh.top() >= a) {
    maxh.push(a);
    leftsum += a;
  } else {
    minh.push(a);
    rightsum += a;
  }

  if (maxh.size() > minh.size() + 1) {
    leftsum -= maxh.top();
    rightsum += maxh.top();
    minh.push(maxh.top());
    maxh.pop();
  } else if (minh.size() > maxh.size()) {
    leftsum += maxh.top();
    rightsum -= maxh.top();
    maxh.push(minh.top());
    minh.pop();
  }
}

