class Median {
    priority_queue<ll> low;
    priority_queue<ll, vector<ll>, greater<ll> > high;
    ll lsum, hsum;

public:
    Median() {
        low.push(-1e18);
        high.push(1e18);
        lsum = hsum = 0;
    }

    // [1, 2, 3] [3, 5, 6]
    void update(ll x) {
        if (low.top() > x) {
            low.push(x);
            lsum += x;
        } else {
            high.push(x);
            hsum += x;
        }
        while (low.size() > high.size()) {
            hsum += low.top();
            lsum -= low.top();
            high.push(low.top());
            low.pop();
        }

        while (high.size() > low.size() + 1) {
            hsum -= high.top();
            lsum += high.top();
            low.push(high.top());
            high.pop();
        }
    }


    pair<ll, ll> query() {
        if (high.size() > low.size()) {
            assert(high.size() == low.size() + 1);
            ll med = high.top();
            ll sum = med * low.size() - lsum;
            sum += hsum - med * high.size();
            return {med, sum};
        } else {
            assert(high.size() == low.size());
            ll med = low.top();
            ll sum = med * low.size() - lsum;
            sum += hsum - med * high.size();
            return {med, sum};
        }
    }


};

int main() {

    int Q;
    cin >> Q;
    Median med;

    ll ans = 0;
    for (int i = 0; i < Q; i++) {
        int a;
        cin >> a;
        if (a == 1) {
            int b, c;
            cin >> b >> c;
            med.update(b);
            ans += c;
        } else {
            auto r = med.query();
            cout << r.first << " " << r.second + ans << endl;
        }
    }

}

