}

int climb(long long n, int t){
    int idx = 0;
    long long s = 0;
    for(int i = 18; i>=0; i--){
        if((1<<i) <= N && s + BIT[(1<<i)+idx][t] < n){
            s += BIT[(1<<i)+idx][t];
            idx += (1<<i);
        }
    }
    return idx+1;
}

long long query(int n, int t){
    long long s = 0;
    for(int i = n; i>0; i-=i&-i){
        s += BIT[i][t];
    }
    return s;
}

