struct _solver {
  long long ls, rs, bs;
  priority_queue<int, vector<int>, less<int>> lhs;
  priority_queue<int, vector<int>, greater<int>> rhs;

  void clear() {
    ls = rs = bs = 0;
    while (!lhs.empty()) lhs.pop();
    while (!rhs.empty()) rhs.pop();
  }

  inline void push_l(int x) {
    lhs.push(x);
    ls += x;
  }

  inline void push_r(int x) {
    rhs.push(x);
    rs += x;
  }

  inline long long pop_l() {
    long long k = lhs.top();
    ls -= k;
    lhs.pop();
    return k;
  }

  inline long long pop_r() {
    long long k = rhs.top();
    rs -= k;
    rhs.pop();
    return k;
  }

  void update(int a, int b) {
    bs += b;
    if (lhs.size() == 0 || lhs.top() >= a) {
      push_l(a);
    } else {
      push_r(a);
    }
    if (lhs.size() > rhs.size() + 1) {
      push_r(pop_l());
    }
    if (rhs.size() > lhs.size() + 1) {
      push_l(pop_r());
    }
    while (rhs.size() > 0 && lhs.top() > rhs.top()) {
      long long ll = pop_l();
      long long rr = pop_r();
      push_l(rr);
      push_r(ll);
    }
  }

  pair<long long, long long> query() {
    long long k = lhs.top();
    long long l = k * (long long)lhs.size() - ls;
    long long r = rs - k * (long long)rhs.size();
    return mp(k, l + r + bs);
  }
} solver;

int q, a, b, c;

int main(int argc, char const *argv[]) {
  // freopen("F.txt", "r", stdin);

  while (cin >> q) {
    solver.clear();
    range(_, 0, q, 1) {
      cin >> c;
      if (c == 1) {
        cin >> a >> b;
        solver.update(a, b);
      } else {
        auto ans = solver.query();
        cout << ans.fi << " " << ans.se << endl;
      }
    }
  }
  return 0;
}

