				if (x_root >= 0) last_mx = max(last_mx, x_root);
				if (x_root <= 0) last_mn = min(last_mn, x_root);
				was = 1;
				XX = x_root;
				continue;
			}

			if (x_root > xx2) {
				min_val += x_root - xx2;
				if (xx1 != xx2) xx1 = xx2;
				else {
					if (last_mx < -LL_INF / 2 || only_one)
						xx2 = x_root;
					else
						xx2 = last_mx;
				}
			}
			else if (x_root < xx1) {
				min_val += xx1 - x_root;
				if (xx2 != xx1) xx2 = xx1;
				else {
					if (last_mn > LL_INF / 2 || only_one)
						xx1 = x_root;
					else
						xx1 = last_mn;
				}
			}
			else {
				xx1 = xx2 = x_root;
			}

			if (x_root >= 0) last_mx = max(last_mx, x_root);
			if (x_root <= 0) last_mn = min(last_mn, x_root);

			was = 1;
			if (XX != x_root) only_one = 0;
		}
		else {
			print_ans();
		}
	}
	return 0;
}

