using namespace std;

template<class T> struct SegmentTree {
    using func = function<T(T, T)>;
private:
    int n;
    T ie;
    func operation;
    func updater;
    vector<T> node;

    T _query(int l, int r, int k, int kl, int kr) {
        if(kr <= l || r <= kl)
            return ie;
        if(l <= kl && kr <= r)
            return node[k];
        T v1 = _query(l, r, 2*k+1, kl, (kl+kr)/2);
        T v2 = _query(l, r, 2*k+2, (kl+kr)/2, kr);
        return operation(v1, v2);
    }

public:
    void init(size_t _n, T _ie, func _operation, func _updater) {
        n = 1; while(n < _n) n *= 2;
        ie = _ie;
        operation = _operation;
        updater = _updater;
        node.assign(2*n-1, ie);
    }

    void update(int i, T x) {
        i += n-1;
        node[i] = updater(node[i], x);
        while(i > 0) {
            i = (i-1) / 2;
            node[i] = operation(node[2*i+1], node[2*i+2]);
        }
    }

    T query(int l, int r) {
        return _query(l, r, 0, 0, n);
    }

    // query(0, ans) == x なる最小の ans
    int binary_search(T x) {
        int ans = n/2;

        T sub;
        do {
            sub = x - query(0, ans);
            if(sub > 0)
                ans = (ans + n + 1) / 2;
            if(sub < 0)
                ans = (0 + ans) / 2;
        } while( sub != 0 );
        return ans;
    }

};

