int q;
ll t[20010], a[20010], b[20010];
ll b_sum;

int main() {
    cin >> q;
    vector<ll> v;
    for(int i = 0; i < q; i++) {
        cin >> t[i];
        if(t[i] == 1) {
            cin >> a[i] >> b[i];
            v.push_back(a[i]);
        }
    }
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());

    int vn = v.size();
    unordered_map<ll, int> v2r; // value to rank
    for(int i = 0; i < vn; i++)
        v2r[v[i]] = i;

    SegmentTree<ll> sum, med;
    sum.init(vn, 0, [](ll a, ll b){return a + b;}, [](ll a, ll b){return b;});
    med.init(vn, 0, [](ll a, ll b){return a + b;}, [](ll a, ll b){return b;});
    for(int i = 0; i < q; i++) {
        switch(t[i]) {
            case 1:
                sum.update(v2r[a[i]], a[i]);
                med.update(v2r[a[i]], 1);
                b_sum += b[i];
                break;
            case 2:
                int count = med.query(0, vn);
                int mi = med.binary_search( (count + 1)/2 ) - 1;
                ll ans = b_sum;
                ans -= sum.query(0, mi+1);
                ans += sum.query(mi+1, vn);
                ans += (count % 2 == 1) ? v[mi] : 0;
                cout << v[mi] << " " << ans << endl;
        }
    }
}

