int main() {
	ll Q;
	cin >> Q;

	priority_queue<ll> pqDown;
	priority_queue<ll, vector<ll>, greater<ll>> pqUp;
	ll bias = 0;
	ll sumAdown = 0;
	ll sumAup = 0;

	rep(i, Q) {
		ll k;
		cin >> k;

		if (k == 1ll) {
			ll a;
			cin >> a;
			ll b;
			cin >> b;

			bias += b;

			if (pqDown.size() == 0) {
				//pqDownに入る
				pqDown.push(a);
				sumAdown += a;
			}
			else if (a < pqDown.top()) {
				//pqDownに入る
				if (pqDown.size() > pqUp.size()) {
					//pqDown→pqUpにひとつ移動
					sumAdown -= pqDown.top();
					sumAup += pqDown.top();

					pqUp.push(pqDown.top());
					pqDown.pop();
				}

				pqDown.push(a);
				sumAdown += a;
			}
			else if (pqUp.size() == 0) {
				//pqUpに入る
				pqUp.push(a);
				sumAup += a;
			}
			else if (a > pqUp.top()) {
				//pqUpに入る
				if (pqDown.size() == pqUp.size()) {
					//pqUp→pqDownにひとつ移動
					sumAup -= pqUp.top();
					sumAdown += pqUp.top();

					pqDown.push(pqUp.top());
					pqUp.pop();
				}

				pqUp.push(a);
				sumAup += a;
			}
			else {
				//中間
				if (pqDown.size() == pqUp.size()) {
					pqDown.push(a);
					sumAdown += a;
				}
				else {
					pqUp.push(a);
					sumAup += a;
				}
			}
		}
		else if (k == 2ll) {
			ll x = pqDown.top();
			ll a = abs(x * ((ll)pqDown.size() - 1ll) - (sumAdown - x));
			a += abs(x * (ll)pqUp.size() - sumAup);
			ll ans = a + bias;

			cout << x << " " << ans << endl;
		}
	}

	return 0;
}



