#include <iostream>
#include <queue>
#define ll long long
using namespace std;

ll a[110];

int main() {
	int Q;
	cin >> Q;
	ll sum=0, smallSum=0, largeSum=0;
	ll cnt=0;
	priority_queue<ll> small;
	priority_queue<ll, vector<ll>, greater<ll>> large;
	for(int t=0; t<Q; ++t){
		int dum;
		cin >> dum;
		if(dum==1){
			ll a, b;
			cin >> a >> b;
			sum += b;
			if(cnt==0){
				smallSum=a;
				small.push(a);
			}
			else if(cnt%2==0){
				if(a<=large.top()){
					smallSum += a;
					small.push(a);
				}else{
					smallSum += large.top();
					largeSum += a-large.top();
					small.push(large.top());
					large.pop();
					large.push(a);
				}
			}else{
				if(small.top()<=a){
					largeSum += a;
					large.push(a);
				}else{
					largeSum += small.top();
					smallSum += a-small.top();
					large.push(small.top());
					small.pop();
					small.push(a);
				}
			}
			++cnt;
		}else{
			ll half=(cnt+1)/2;
			ll ans=sum+(small.top()*half-smallSum)+(largeSum-small.top()*(cnt-half));
			cout << small.top() << ' ' << ans << endl;
		}
	}
	return 0;
}

