signed main() {

	int Q;
	cin >> Q;

	priority_queue<int> down;	// 大きい順に取り出せる。medianはこっちに入れる。
	priority_queue<int, vector<int>, greater<>> up;	// 小さい順に取り出せる
	int downsum = 0, upsum = 0;

	int sum = 0;
	while (Q--) {
		int kind;
		cin >> kind;
		if (kind == 1) {
			int a, b;
			cin >> a >> b;
			sum += b;

			if (down.size() == 0) {
				down.push(a);
				downsum += a;
				continue;
			}

			if (down.size() == up.size() + 1) {
				int t = down.top();
				if (a < down.top()) {
					// dddd|uuu -> ddad|duuu
					up.push(t);		upsum += t;
					down.pop();		downsum -= t;

					down.push(a);	downsum += a;
				}
				else {
					// dddd|uuu -> dddd|uauu
					up.push(a);		upsum += a;
				}
			}
			else if (down.size() == up.size()) {
				int t = up.top();
				if (a <= down.top()) {
					// dddd|uuuu -> dddad|uuuu
					down.push(a);	downsum += a;
				}
				else {
					// dddd|uuuu -> ddddu|uauu
					down.push(t);	downsum += t;
					up.pop();		upsum -= t;

					up.push(a);		upsum += a;
				}
			}
			else {
				assert(1);
			}

		}
		else {
			int median = down.top();
			int ans = sum;
			ans += upsum - (int)up.size() * median;
			ans += (int)down.size() * median - downsum;
			cout << median << " " << ans << endl;
		}
	}


	return 0;
}

