#include<bits/stdc++.h>

using namespace std;

using LL = long long;
const int NQue = (int)2e5 + 5;

int nQue, type[NQue], a[NQue], b[NQue], nA;
LL sumB;
vector<int> compA;

int compAId(int num) { return (int)(lower_bound(compA.begin(), compA.end(), num) - compA.begin() ) + 1; }

template<class T>
struct Bit {
    T a[NQue];
    Bit() { fill(a, a + NQue, 0); }
    void upd(int pos, int val) {
        for (; pos < NQue; pos += pos & -pos) a[pos] += val;
    }
    T get(int pos) {
        T ret = 0;
        for (; pos > 0; pos -= pos & -pos) ret += a[pos];
        return ret;
    }
    T getPos(int id) {
        int ret = 0;
        for (int lg = __lg(NQue); lg >= 0; --lg) if ( (ret | (1 << lg) ) < NQue && a[ret | (1 << lg)] < id) {
            ret |= (1 << lg);
            id -= a[ret];
        }
        return ret + 1;
    }
};
Bit<int> cnt;
Bit<LL> sum;

int main() {
    scanf(" %d", &nQue);
    for (int i = 1; i <= nQue; ++i) {
        scanf(" %d", type + i);
        if (type[i] == 1) {
            scanf(" %d %d", a + i, b + i);
            compA.emplace_back(a[i]);
        }
    }

    sort(compA.begin(), compA.end() );
    compA.erase(unique(compA.begin(), compA.end() ), compA.end() );

    for (int i = 1; i <= nQue; ++i) {
        if (type[i] == 1) {
            ++nA;
            sumB += b[i];
            cnt.upd(compAId(a[i]), 1);
            sum.upd(compAId(a[i]), a[i]);
        }
        else {
            int pos = cnt.getPos(nA / 2 + (nA & 1) );
            printf("%d %lld\n", compA[pos - 1], sumB + (LL)compA[pos - 1] * (2 * cnt.get(pos) - nA) + sum.get(NQue - 1) - 2LL * sum.get(pos) );
        }
    }

    return 0;
}

