  As lefts, rights;
  int64_t n = 0;         // number of added |x-a| + b
  int64_t min = 0;   // mimimum now

  for(int i=0; i<Q; i++) {
    int c;
    std::cin >> c;
    if(c == 1) {
      update(lefts, rights, n, min);
    } else if(c == 2) {
      print(lefts, rights, n, min);
    }
  }

  return 0;
}

