    set<ll> A,B;
    ll sumA=0,sumB=0;
    int cnt=0;
    ll now=0;
    while(Q--){
        int t;
        cin>>t;
        if(t==1){
            ll a,b;
            cin>>a>>b;
            now+=b;
            if(cnt==0){
                A.insert(a); sumA+=a;
            }else if(cnt==1){
                ll x=*(--A.end());
                A.erase(x); sumA-=x;
                if(a>x) swap(a,x);
                A.insert(a); B.insert(x);
                sumA+=a; sumB+=x;
            }else{
                ll aa,bb;
                aa=*(--A.end()); A.erase(aa); sumA-=aa;
                bb=*B.begin(); B.erase(bb); sumB-=bb;
                vector<ll> v;
                v.emplace_back(aa); v.emplace_back(bb); v.emplace_back(a);
                vsort(v);
                A.insert(v[0]); B.insert(v[2]); sumA+=v[0]; sumB+=v[2];
                if(cnt%2==1) B.insert(v[1]),sumB+=v[1];
                else A.insert(v[1]),sumA+=v[1];
            }
            cnt++;
        }else{
            if(cnt%2==0){
                cout<<*(--A.end())<<" "<<sumB-sumA+now<<endl;
            }else{
