    cin >> q;
    priority_queue<LL> left;
    priority_queue<LL, vector<LL>, greater<LL>> right;
    LL B = 0;
    LL A = 0;
    while (q--) {
        int t;
        cin >> t;
        LL last_mid;
        if (t == 1) {
            LL a, b;
            cin >> a >> b;
            B += b;
            if (left.empty() || left.top() >= a) {
                if (left.size() > right.size()) {
                    LL tmp = left.top();
                    left.pop();
                    right.push(tmp);
                }
                left.push(a);
            } else {
                if (left.size() == right.size()) {
                    LL tmp = right.top();
                    right.pop();
                    left.push(tmp);
                }
                right.push(a);
            }
            if (left.size() > 0 && left.size() == right.size()) {
                A += abs(left.top() - last_mid);
            }
            A += abs(a - left.top());
            // printf("A = %lld, B = %lld\n", A, B);
            last_mid = left.top();
        } else {
            cout << left.top() << " " << A + B << endl;
        }
    }
