template<class T>
struct BIT {
	lint n;
	T neutral;
	vect<T> v;

	BIT(lint _n, T _neutral = 0) : n(_n), neutral(_neutral), v(n, neutral) {}

	using FT = T(T, T);
	FT* un, * dun;

	void add(lint i, lint val) {
		i++;
		while (i <= n) {
			v[i - 1] += val;
			i += i & -i;
		}
	}

	void update(lint i, T val) {
		add(i, dun(val, query(i, i + 1)));
	}

	T query_impl(lint r) {
		T ans = neutral;
		while (r > 0) {
			ans = un(ans, v[r - 1]);
			r -= r & -r;
		}
		return ans;
	}

	T query(lint l, lint r) {
		return dun(query_impl(r), query_impl(l));
	}

};

template<class T>
struct BITs : public BIT<T> {
	BITs(lint n) : BIT<T>(n, T(0)) {
		this->un = [](T a, T b) { return a + b; };
		this->dun = [](T a, T b) { return a - b; };
	}
};

template<class T, class Pred>
pair<T, T> bin(T begin, T end, Pred p)
{
	while (end - begin > 1)
	{
		T tgt = begin + (end - begin) / 2;

		if (p(tgt))
		{
			begin = tgt;
		}
		else
		{
			end = tgt;
		}
	}

	return make_pair(begin, end);
}


