std::multiset<int> left, right;
int64_t result = 0;

void Update() {
  int a, b;
  cin >> a >> b;
  result += b;
  int leftmax  = *(--left.end());
  int rightmin = *(right.begin());
  if (leftmax <= a && rightmin <= a) {
    result += 0;
  } else if (a < leftmax) {
    result += (leftmax - a);
  } else {
    result += (a - rightmin);
  }
  if (left.empty()) {
    left.insert(a);
    right.insert(a);
  } else if (a < leftmax) {
    left.insert(a);
    left.insert(a);
    left.erase(--(left.end()));
    right.insert(leftmax);
  } else if (rightmin < a) {
    right.insert(a);
    right.insert(a);
    right.erase(right.begin());
    left.insert(rightmin);
  } else {
    left.insert(a);
    right.insert(a);
  }
}
void Solve() {
  cout << *(--left.end()) << " " << result << endl;
}

