	priority_queue<ll> le;
	priority_queue<ll, vector<ll>, greater<ll>> ri;
	ll suml = 0, sumr = 0, sumb = 0;
	int cnt = 0;
	while (Q--) {
		int tp; cin >> tp;
		if (tp == 1) {
			ll a, b; cin >> a >> b;
			cnt++;
			sumb += b;

			if (ri.empty() || a >= ri.top()) {
				ri.push(a);
				sumr += a;
			}
			else {
				le.push(a);
				suml += a;
			}
			while (ri.size() > (cnt + 1) / 2) {
				ll v = ri.top();
				le.push(v);
				ri.pop();
				sumr -= v;
				suml += v;
			}
			while (le.size() > cnt / 2) {
				ll v = ri.top();
				ri.push(v);
				le.pop();
				suml -= v;
				sumr += v;
			}
		}
		else {
			int med = -1;
			if (cnt & 1) med = ri.top();
			else med = le.top();
			ll f = sumb;
			f += sumr - med*ri.size();
			f += med*le.size() - suml;
			cout << med << " " << f << endl;
		}
	}
	return 0;
}

