template<class T>
struct Median{
    priority_queue<T> q1;
    priority_queue<T,vector<T>,greater<T>> q2;
    T dist;
    Median():dist(){}
    void insert(T x){
        if(!q1.size()){
            q1.push(x);
        }else if(q1.size()==q2.size()){
            if(x<q1.top()){
                q2.push(q1.top());
                q1.pop();
                q1.push(x);
            }else{
                q1.push(x);
            }
        }else{
            int p=q1.top();
            if(x>q1.top()){
                q2.push(x);
            }else{
                q2.push(q1.top());
                q1.pop();
                q1.push(x);
            }
            dist+=abs(p-q1.top());
        }
        dist+=abs(x-q1.top());
    }
    T median(){
        return q1.top();
    }
    T distance(){
        return dist;
    }
};
