			if (down.size() == 0) {
				down.push(a);
				downsum += a;
				continue;
			}

			if (down.size() == up.size()) {
				if (a <= down.top()) {
					// dddd|uuuu -> dddad|uuuu
					down.push(a);
					downsum += a;
				}
				else {
					// dddd|uuuu -> ddddu|uauu
					down.push(up.top());
					downsum += up.top();
					upsum -= up.top();
					up.pop();

					up.push(a);
					upsum += a;
				}
			}
			else if (down.size() == up.size() + 1) {
				if (a <= down.top()) {
					// dddd|uuu -> ddad|duuu
					up.push(down.top());
					upsum += down.top();
					downsum -= down.top();
					down.pop();

					down.push(a);
					downsum += a;
				}
				else {
