						down.push(up.top());
						downsum += up.top();
						up.pop();
					}

					up.push(a);
					upsum += a;
				}
			}
			else {
				assert(1);
			}

		}
		else {
			int median = down.top();
			int ans = sum;
			ans += upsum - up.size() * median;
			ans += down.size() * median - downsum;
			cout << median << " " << ans << endl;
		}
	}


	return 0;
}

