typedef long long ll;
mt19937 gen;
struct node;
using pnode = node*;
int sz(pnode a);
ll dd(pnode a);
struct node
{
	node *l = NULL, *r = NULL;
	int w;
	int val;
	int dyd = 1;
	ll dyd1;
	node(int val): val(val)
	{
		w = gen();
		dyd1 = val;
	}
	void fixS()
	{
		dyd = 1 + sz(l) + sz(r);
		dyd1 = val + dd(l) + dd(r);
	}
};
int sz(pnode a)
{
	if (a)
		return a->dyd;
	return 0;
}
ll dd(pnode a)
{
	if (a)
		return a->dyd1;
	return 0;
}
pnode merge(pnode a, pnode b)
{
	if (a == NULL)
		return b;
	if (b == NULL)
		return a;
	if (a->w < b->w)
	{
		a->r = merge(a->r, b);
		a->fixS();
		return a;
	}
	else
	{
		b->l = merge(a, b->l);
		b->fixS();
		return b;
	}
}
pnode merge(pnode a, pnode b, pnode c)
{
	return merge(merge(a, b), c);
}
void split(pnode a, int v, pnode &x, pnode &y)
{	// (x <= v), (y > v)
	if (a == NULL)
	{
		x = NULL;
		y = NULL;
		return;
	}
	if (a->val <= v)
	{
		split(a->r, v, a->r, y);
		x = a;
	}
	else
	{
		split(a->l, v, x, a->l);
		y = a;
	}
	a->fixS();
}
void split_(pnode a, int k, pnode &x, pnode &y)
{	// (x->sz = min(a->sz, k))
	if (a == NULL)
	{
		x = NULL;
		y = NULL;
	}
	else
	{
		if (k <= 0)
		{
			x = NULL;
			y = a;
		}
		else if (a->dyd < k)
		{
			x = a;
			y = NULL;
		}
		else
		{
			if (sz(a->l) + 1 <= k)
			{
				split_(a->r, k - 1 - sz(a->l), a->r, y);
				x = a;
			}
			else
			{
				split_(a->l, k, x, a->l);
				y = a;
			}
			a->fixS();
		}
	}
}
void print(pnode a, char g = '\n')
{
	if (a == NULL)
	{
		if (g != ' ')
			cout << g;
		return;
	}
	print(a->l, ' ');
	cout << a->val << ' ';
	print(a->r, g);
}

