					max_heap.push({ b });
					res = 0;
				}
				else {
					if (min_heap.top().n > b) {
						max_heap.push({ b });
					}
					else {
						int tmp = min_heap.top().n;
						min_heap.pop();
						max_heap.push(tmp);
						min_heap.push({ b });
						res += b - max_heap.top();
