const double PI=3.14159265358979323846;


int main() {
    int q; cin >> q;
    priority_queue<ll> left;
    priority_queue<ll, vector<ll>, greater<ll>> right;
    ll lsum = 0;
    ll rsum = 0;
    ll b_sum = 0;
    while(q--) {
        int type;
        cin >> type;
        if(type == 1) {
            ll a, b;
            cin >> a >> b;
            b_sum += b;
            if(left.empty()) {
                left.push(a);
                lsum += a;
            }
            else if(left.size() == right.size()) {
                if(a <= left.top()) {
                    left.push(a);
                    lsum += a;
                }
                else {
                    right.push(a);
                    rsum += a;
                }
            }
            else if(left.size() > right.size()) {
                if(a <= left.top()) {
                    // left.top()をrightに移す
                    lsum -= left.top(); rsum += left.top();
                    right.push(left.top()); left.pop();
                    // aをleftに
                    lsum += a; left.push(a);
                }
                else {
                    right.push(a); rsum += a;
                }
            }
            else if(left.size() < right.size()) {
                if(a <= left.top()) {
                    lsum += a; left.push(a);
                }
                else {
                    // right.top()をleftに移す
                    lsum += right.top(); rsum -= right.top();
                    left.push(right.top()); right.pop();
                    // aをrightに
                    rsum += a; right.push(a);
                }
            }
        }
        if(type == 2) {
            ll res = b_sum;
            ll med = left.top();
            res += rsum - med*(right.size());
            res += med*(left.size()) - lsum;
            printf("%lld %lld\n", med, res);
        }
    }
    return 0;
}

