        if (q == 1) {
            ll a,b;
            cin >> a >> b;
            height += b;
            qu.push(a);
            if (a < med.first || med.second < a) {
                height += min(abs(a - med.first), abs(a - med.second));
            }
            med = qu.get_median();
        } else {
            cout << med.first << " " << height << endl;
        }
    }
    return 0;
}

