	int sum = 0;
	s.insert(a);
	sum += b;
	auto itr = s.begin();
	int p = a;
	int l = 0, r = 0;
	int lc = 0, rc = 0;
	bool L = false, R = false;
	map<int, int> m;
	while (Q--) {
		cin >> q;
		if (q == 1) {
			cin >> a >> b;
			sum += b;
			m[a]++;
			s.insert(a);
			if (p < a && (L || (!L && !R))) {
				itr++;
				l += p;
				r += a;
				p = *itr;
				lc++;
				r -= *itr;
				if (L) {
					L = false;
				} else {
					R = true;
				}
			} else if (p < a) {
				rc++;
				r += a;
				R = false;
			} else if (p > a && (R || (!L && !R))) {
				itr--;
				r += p;
				l += a;
				p = *itr;
				rc++;
				l -= *itr;
				if (R) {
					R = false;
				} else {
					L = true;
				}
