void solve() {
    cin>>Q;
    int a,b,c;
    multiset<int> l, r;
    int ls=0, rs=0, bs=0;
    while(Q--) {
        cin>>c;
        if (c==2) {
            auto it = l.end();
            int lv = *(--it);
            int ans = bs;
            ans += lv * l.size() - ls;
            ans += rs - lv * r.size();
            out("%lld %lld\n", lv, ans);
            continue;
        }
        cin>>a>>b;
        bs += b;
        if (l.empty()) {
            l.insert(a);
            ls += a;
            continue;
        }
        auto it = l.end();
        int lv = *(--it);
        if (lv > a) {
            l.insert(a);
            ls += a;
            if (l.size() > r.size() + 1) {
                auto it = l.end();
                int lv = *(--it);
                r.insert(lv);
                l.erase(lv);
                rs += lv;
                ls -= lv;
            }

        }
        else if (lv < a) {
            r.insert(a);
            rs += a;
            if (r.size() > l.size()) {
                int rv = *r.begin();
                l.insert(rv);
                r.erase(rv);
                ls += rv;
                rs -= rv;
            }
        }
        else {
            if (l.size() > r.size()) {
                r.insert(a);
                rs += a;
            } else {
                l.insert(a);
                ls += a;
            }
        }
    }
}

