class BIT{
public:
  typedef long long ll;
  ll n;
  map<ll, ll> bit0, bit1;
  BIT(){n=-1;}
  BIT(ll n_){
    n=1;
    while(n<n_)n*=2;
  }

  ll sum(map<ll, ll> &b,ll i){
    ll s=0;
    while(i>0){
      s = (s + b[i]);// % mod;
      i -= i & -i;
    }
    return s;
  }

  void add(map<ll, ll> &b,ll i,ll v){
    // v = (mod + v % mod) % mod;
    while(i<=n){
      b[i] = (b[i] + v);//% mod;
      i += i & -i;
    }
  }

  //[a,b)にxを加算 0オリジン
  void add (ll a,ll b,ll x){
    // x = (mod + x % mod) % mod;
    if(a == b) return;
    a++;
    assert(a <= b && 1 <= a && b <= n);
    add(bit0, a, -x*(a-1));
    add(bit1, a, x);
    add(bit0, b+1, x*b);
    add(bit1, b+1, -x);
  }

  //[a,b)のsumを得る 0オリジン
  ll sum(ll a,ll b){
    if(a == b) return 0;
    a++;
    assert(a <= b && 1 <= a && b <= n);
    ll s = sum(bit0,b);
    ll t = sum(bit1,b) * b;
    ll u = sum(bit0,a-1);
    ll v = sum(bit1,a-1) * (a-1);
    return s + t - u - v;
    //return ((s + t) + (mod - u%mod) + (mod - v%mod)) % mod;
  }
};



