      Int M = (L + R) / 2;
      bit.sum(M, M + 1) >= 0? (L = M):(R = M);
    };
    return L;
  };

  auto calcR =[&](BIT &bit){
    Int L = 0, R = LENGTH;
    while(L + 1 < R){
      Int M = (L + R) / 2;
      bit.sum(M, M + 1) > 0? (L = M):(R = M);
