void upd(lli n,lli s,lli e,lli idx,lli val)
{
    if(s == e)
    {
        tr[n]+=val;
        return;
    }

    lli mid = (s+e)/2;

    if(idx>=s && idx<=mid)
        upd(2*n,s,mid,idx,val);

    else upd(2*n + 1,mid+1,e,idx,val);

    tr[n] = tr[2*n] + tr[2*n + 1];

}

lli qry(lli n,lli s,lli e,lli l,lli r)
{
    if(l>e || s>r)
        return 0;

    if(s>=l && r>=e)
        return tr[n];

    lli mid = (s+e)/2;

    lli x = qry(2*n,s,mid,l,r);
    lli y = qry(2*n + 1,mid+1,e,l,r);

    return x+y ;
}


