			if (small_as.size() > 0LL)
			{
				if (small_as.size() == large_as.size())
				{
					if (large_as.top() < a)
					{
						res += a - large_as.top();
						small_as.push(large_as.top());
						large_as.pop();
						large_as.push(a);
					}
					else
					{
						res += max(small_as.top() - a, 0LL);
						small_as.push(a);
					}
				}
				else
				{
					if (small_as.top() < a)
					{
						res += a - small_as.top();
						large_as.push(a);
					}
					else
					{
						res += small_as.top() - a;
						large_as.push(small_as.top());
						small_as.pop();
