set<int> ms;

int get_next(int x) {
	set<int>::iterator iter = ms.find(x);
	iter++;
	return *iter;
}

int get_prev(int x) {
	set<int>::iterator iter = ms.find(x);
	iter--;
	return *iter;
}

int main() {
