struct FenwickTree {
    int length;
    vector<ll> node;
    FenwickTree (int N) : length(N), node(length + 1, 0) {}
    void add(int idx, ll val) {
        ++idx;
        while (idx <= length) {
            node[idx] += val;
            idx += (idx & (-idx));
        }
    }
    ll getsum(int idx) {
        ll ans = 0;
        while (idx) {
            ans += node[idx];
            idx -= (idx & (-idx));
        }
        return ans;
    }
    int lowerBound(ll x) {
        int ans = 0;
        int l = 1;
        while ((l << 1) <= length) l <<= 1;
        while (l) {
            if (ans + l <= length) {
                if (node[ans + l] < x) {
                    x -= node[ans + l];
                    ans += l;
                }
            }
            l >>= 1;
        }
        return ans + 1;
    }
};

