double comd(int n, int r) {
    assert(n < 2020);
    static vvd(comb, 2020, 2020);
    if (comb[0][0] == 0) {
        comb[0][0] = 1;
        rep(i, 2000) {
            comb[i + 1][0] = 1;
            rep(j, 1, i + 2) {
                comb[i + 1][j] = comb[i][j] + comb[i][j - 1];
            }
        }
    }
    return comb[n][r];
}
