    vector<T> b = a;
    compress(b);
    int n = sz(b);
    BIT<int> bt(n + 3);
    int cou = 0;
    rer(i, n - 1) {
        cou += bt.get(b[i]);
        bt.add(b[i], 1);
    }
    return cou;
}
