	ll sum = 0;
	for(int i = 0; i < q; i++) {
		int type;
		scanf("%d", &type);
		if(type == 1) {
			int a, b;
			scanf("%d %d", &a, &b);
			sum += b;
			lo.insert(a);
			sum_a += a;
			while(!lo.empty() and !hi.empty() and *prev(lo.end()) > *hi.begin()) {
				int elem = *prev(lo.end());
				lo.erase(prev(lo.end()));
				sum_a -= elem;
				sum_b += elem;
				hi.insert(elem);
			}
			while((int)lo.size() - (int)hi.size() >= 2) {
				int elem = *prev(lo.end());
				lo.erase(prev(lo.end()));
				sum_a -= elem;
				sum_b += elem;
				hi.insert(elem);
			}
			while((int)hi.size() - (int)lo.size() >= 2) {
				int elem = *hi.begin();
				hi.erase(hi.begin());
				sum_a += elem;
				sum_b -= elem;
				lo.insert(elem);
			}
		}
		else {
			int x = *prev(lo.end());
			ll ans = sum;
			ans += (int)lo.size() * x - sum_a;
			ans += sum_b - (int)hi.size() * x;
			printf("%d %lld\n", x, ans);
		}
	}
