#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

int main(){
	ll q;
	scanf("%lld",&q);

	priority_queue<ll> L;
	priority_queue<ll,vector<ll>,greater<ll>> R;
	ll ret = 0;

	ll t,a,b;
	scanf("%lld%lld%lld",&t,&a,&b);
	L.push(a);
	ret = b;
	q --;

	for(;q>0;q--){
		scanf("%lld",&t);
		if(t == 1){
			scanf("%lld%lld",&a,&b);
			if(a <= L.top()){
				ret += abs(a-L.top());
				L.push(a);
				if(L.size() >= R.size()+2){
					R.push(L.top());
					L.pop();
				}
			}
			else {
				ret += abs(a-L.top());
				R.push(a);
				if(L.size() < R.size()){
					ret -= R.top()-L.top();
					L.push(R.top());
					R.pop();
				}
			}
			ret += b;
		}
		else {
			printf("%lld %lld\n",L.top(),ret);
		}
	}
}

