int main() {
    int q;
    cin >> q;

    priority_queue<lint> front_queue;
    priority_queue<lint, vector<lint>, greater<lint>> back_queue;
    long long front_sum = 0, back_sum = 0, b_sum = 0;

    auto queue_size = [&] () { return (int)front_queue.size() + back_queue.size(); };
    auto queue_empty = [&] () { return (front_queue.empty() and back_queue.empty()); };
    auto balance = [&] () {
        if (queue_size() % 2 == 0) {
            if (front_queue.size() == back_queue.size()) return;
            if (front_queue.size() < back_queue.size()) {
                while (front_queue.size() != back_queue.size()) {
                    front_queue.emplace(back_queue.top());
                    back_sum -= back_queue.top();
                    front_sum += back_queue.top();
                    back_queue.pop();
                }
            } else {
                while (front_queue.size() != back_queue.size()) {
                    back_queue.emplace(front_queue.top());
                    front_sum -= front_queue.top();
                    back_sum += front_queue.top();
                    front_queue.pop();
                }
            }
        } else {
            if ((int)front_queue.size() == (int)back_queue.size()+1) return;
            if (front_queue.size() < back_queue.size()+1) {
                while (front_queue.size() < back_queue.size()) {
                    front_queue.emplace(back_queue.top());
                    back_sum -= back_queue.top();
                    front_sum += back_queue.top();
                    back_queue.pop();
                }
            } else {
                while (front_queue.size() > back_queue.size()+1) {
                    back_queue.emplace(front_queue.top());
                    front_sum -= front_queue.top();
                    back_sum += front_queue.top();
                    front_queue.pop();
                }
            }
        }
    };

    auto add = [&] (lint a, lint b) {
        b_sum += b;
        if (queue_empty()) { front_queue.emplace(a); front_sum += a; return; }
        balance();
        lint med = front_queue.top();
        if (med < a) { back_queue.emplace(a); back_sum += a; }
        else { front_queue.emplace(a); front_sum += a; }
    };

    auto answer = [&] () {
        balance();
        lint a = front_queue.top();
        lint s = (long long)front_queue.size();
        lint t = (long long)back_queue.size();
        lint ans = b_sum;
        ans += abs(a * s - front_sum);
        ans += abs(a * t - back_sum);
        cout << a << " " << ans << '\n';
    };

    while (q--) {
        int op;
        cin >> op;
        if (op == 1) {
            lint a, b;
            cin >> a >> b;
            add(a, b);
        } else {
            answer();
        }
    }
    return 0;
}

