int opt[N],x[N],y[N];
void fix(int l,int r,int k,int x)
{
    if(l==r)
    {
        t[k]+=hs[l];
        si[k]++;
        return;
    }
    int m=l+r>>1;
    if(x<=m) fix(l,m,k<<1,x);
    else fix(m+1,r,k<<1|1,x);
    t[k]=t[k<<1]+t[k<<1|1];
    si[k]=si[k<<1]+si[k<<1|1];
}
ll query(int l,int r,int k)
{
    if(l==r)
    {
        ans1=hs[l];
        return si1*hs[l]-sum1+sum2-si2*hs[l];
    }
    int m=l+r>>1;
    if(si2+si[k<<1|1]<=s/2)
    {
        sum2+=t[k<<1|1];
        si2+=si[k<<1|1];
        return query(l,m,k<<1);
    }
    else
    {
        sum1+=t[k<<1];
        si1+=si[k<<1];
        return query(m+1,r,k<<1|1);
    }
}
