    ll ng = 1e18;//解が存在しない最大値
    */

    while(abs(ok-ng) > 1){
      int mid = (ok+ng)/2;
      if((this->sum(mid)) >= x){//((C+1)+1)/2
        ok = mid; 
      }else{
        ng = mid;
      }
    } 
    return ok;
  }

