      aa.push_back(a[i]);
    }
  }

  sort(all(aa));
  aa.erase(unique(all(aa)), aa.end());
  map<int, int> dict;
  int size = aa.size();
  rep(i, size) {
    dict[aa[i]] = i;
  }

  BIT<ll> bitnum(size, 0);
  BIT<ll> bitsum(size, 0);

  ll cnt = 0, fconst = 0;
  rep(i, n) {
