int copy(int v, int &u)
{
    L[sz] = L[v];
    R[sz] = R[v];
    sum[sz] = sum[v];
    return u = sz++;
}


void add(int pos, int x, int v = rt, int l = -MX, int r = MX) {
    sum[v] += x;
    cnt[v]++;
    if (r - l == 1)
        return;
    int m = (l + r) / 2;
    if (pos < m)
        add(pos, x, copy(L[v], L[v]), l, m);
    else
        add(pos, x, copy(R[v], R[v]), m, r);
}

pair<ll, int> sumPair(const pair<ll, int> &a, const pair<ll, int> &b) {
    return {a.fr + b.fr, a.sc + b.sc};
}

pair<ll, int> get(int a, int b, int v = rt, int l = -MX, int r = MX) {
    if (a <= l && r <= b)
        return {sum[v], cnt[v]};
    if (r <= a || b <= l || cnt[v] == 0)
        return {0, 0};
    int m = (l + r) / 2;
    return sumPair(get(a, b, L[v], l, m), get(a, b, R[v], m, r));
}


