void pushit(int now,int num)
{
    add[now]+=num,tree[now]+=sum[now]*num;
}
void pushdown(int now)
{
    if(add[now])
        pushit(lnode,add[now]),pushit(rnode,add[now]),add[now]=0;
}
void change(int now,int l,int r,int ql,int qr,ll num)
{
    if(l==ql&&r==qr){pushit(now,num);return;}
    pushdown(now);
    if(qr<=mid)change(lnode,l,mid,ql,qr,num);
    else if(ql>mid)change(rnode,mid+1,r,ql,qr,num);
    else change(lnode,l,mid,ql,mid,num),change(rnode,mid+1,r,mid+1,qr,num);
    tree[now]=tree[lnode]+tree[rnode];
}
ll query(int now,int l,int r,int pos)
{
    if(l==r)return tree[now];
    pushdown(now);
    if(pos<=mid)return query(lnode,l,mid,pos);
    else return tree[lnode]+query(rnode,mid+1,r,pos);
}
void create(int now,int l,int r)
{
    if(l==r)
    {
        sum[now]=num[l];return;
    }
    create(lnode,l,mid),create(rnode,mid+1,r);
    sum[now]=sum[lnode]+sum[rnode];
}
