map<int, int> dp;
int tot;

int currMedian;
ll currLessCount;
ll lessSum, greaterSum;

ll shift;

void update(int a, int b) {
  shift += b;
  dp[a]++; tot++;
  if(tot == 1) currMedian = a;
  if(a <= currMedian) {
    currLessCount++;
    lessSum += currMedian - a;
  }
  else {
    greaterSum += a - currMedian;
  }
  while(2*currLessCount >= tot) {
    if(2*(currLessCount-dp[currMedian]) >= tot) {
      int cand;
      {
        auto x = dp.find(currMedian);
        x--;
        cand = x->first;
      }
      currLessCount -= dp[currMedian];
      lessSum -= currLessCount * (currMedian - cand);
      greaterSum += (tot - currLessCount) * (currMedian - cand);
      currMedian = cand;
    }
    else {
      break;
    }
  }
  while(2*currLessCount < tot) {
    int cand = dp.upper_bound(currMedian)->first;
    lessSum += currLessCount * (cand - currMedian);
    greaterSum -= (tot - currLessCount) * (cand - currMedian);
    currLessCount += dp[cand];
    currMedian = cand;
  }
}

void query() {
  cout << currMedian << " " << lessSum + greaterSum + shift << "\n";
}

void solve() {
  int n;
