				s1 += x[1];
			} else {
				pq2.push(x[1]);
				s2 += x[1];
			}
			m++;
		} else {
			ll x = pq1.top();
			ll res = s2 - s1 + s3;
			if (m % 2 == 1) {
				x = pq2.top();
				res -= x;
			}
			put(x, res);
		}
	}

	return 0;
}

