lld res = LONG_MAX, x_m = LONG_MAX;
priority_queue <lld, vector <lld>, greater <lld> > heap_min;
priority_queue <lld, vector <lld>, less <lld> >    heap_max;

void Insert(lld x, lld y)
{
    A += x, B += y, c++;
    int d_min = heap_min.size();
    int d_max = heap_max.size();
    if (d_max == 0)      heap_max.push(x);
    else if (d_min == 0) heap_min.push(x);
    else
    {
        lld L_max = heap_max.top();
        lld R_min = heap_min.top();
        if (x < R_min)      heap_max.push(x);
        else if (x > L_max) heap_min.push(x);
    }
}

void Equal_lize()
{
    int d_min = heap_min.size();
    int d_max = heap_max.size();
    if (d_min != 0 && d_max != 0)
    {
        while (heap_max.size() != 0 && heap_max.top() > heap_min.top())
        {
            lld temp = heap_max.top();
            heap_max.pop();
            heap_min.push(temp);
        }
        while (heap_min.size() > heap_max.size())
        {
            lld temp = heap_min.top();
            heap_min.pop();
            heap_max.push(temp);
        }
    }
}

void Calculate(int i)
{
    lld temp = heap_max.top();
    res = abs(i * temp - A) + B;
    x_m = temp;
}

