// 座標圧縮 計算量 O(NlogN) (Nは要素数)
// unzip...元々のvector zip...圧縮後のmap 返り値... 圧縮後の要素数
// compress(unzip,zip); をすると、それ以降は
// unzip[(圧縮後のval)] = (元々のval);
// zip[(元々のval)] = (圧縮後のval); となる
int compress(vector<ll>& unzip, map<ll, int>& zip) {
  sort(unzip.begin(), unzip.end());
  unzip.erase(unique(unzip.begin(), unzip.end()), unzip.end());
  for (int i = 0; i < sz(unzip); i++) {
      zip[unzip[i]] = i;
  }
  return sz(unzip);
}

template< typename T >
struct BIT {
  int N; int max_2beki;

  vector< T > data;
  // 初期化 1-indexedでデータを管理する 0で初期化
  BIT(int size){
      N = ++size;
      data.assign(N, 0);
      max_2beki = 1;
      while(max_2beki * 2 <= N) max_2beki *= 2;
  }

  // [0,k](閉区間)の総和 閉区間に注意！
  T sum(int k) {
    if(k < 0) return 0; // k<0のとき0を返す
    T ret = 0;
    for(++k; k > 0; k -= k & -k) ret += data[k];
    return (ret);
  }

  // data[k] += x;
  void add(int k, T x) {
    for(++k; k < N; k += k & -k) data[k] += x;
  }

  // lower_bound sum(i)がval以上となる最小のi
  int lower_bound(T w){
    if(w <= 0) return 0;
    int x = 0;
    for(int k = max_2beki; k > 0; k /= 2){
      if(x+k <= N - 1 && data[x + k] < w){
        w -= data[x + k];
        x += k;
      }
    }
    return x;
  }

  // upper_bound sum(i)がvalより大きくなる最小のi
  int upper_bound(T w){
    if(w < 0) return 0;
    int x = 0;
    for(int k = max_2beki; k > 0; k /= 2){
      if(x+k <= N - 1 && data[x + k] <= w){
        w -= data[x + k];
        x += k;
      }
    }
    return x;
  }
};

int main(){
  ini(Q);
  vector<ll> unzip;
  map<ll, int> zip;
  vector<int> cmd(Q),A(Q),B(Q);
  BIT<ll> bit(Q);
