    ini(c); cmd[i] = c;
    if(c == 1){
      ini(a,b);
      A[i] = a; B[i] = b;
      unzip.pb(a);
    }
    else if(c == 2){
      cmd[i] = c;
    }
  }
  compress(unzip , zip);
  ll a_idx = 0; int cnt = 0;
  ll a_sum = 0, b_sum = 0;
  rep(i,Q){
    if(cmd[i] == 1){
      cnt++;
      bit.add( zip[A[i]] , 1);
      b_sum += B[i];
      if(cnt % 2 == 0){
        a_sum += abs ( unzip[a_idx] - A[i] );
        a_idx = bit.lower_bound( (cnt + 1) / 2 );
      }
      else {
        a_idx = bit.lower_bound( (cnt + 1) / 2 );
