        }

        if(t == 2) {
            lint sz = rbst.size();
            lint mid = (sz-1)/2;
            lint med = rbst.get(mid);

            // [0, mid), [mid, sz)
            auto lr = rbst.split(rbst.root, mid);
            lint lsum = rbst.sum(lr.first);
            lint rsum = rbst.sum(lr.second);
            rbst.root = rbst.merge(lr.first, lr.second);

            lint ans = (med*mid - lsum) + (rsum - med*(sz-mid)) + bsum;
            cout << med << " " << ans << endl;
        }
    }
}

