		cin >> a;
		if (a == 1) {
			long long b, c;
			cin >> b >> c;
			settings[b] = 1;
			inputs.push_back(make_tuple(1, b, c));
		}
		else {
			inputs.push_back(make_tuple(2,0, 0));
		}
	}
	tmp_a = 0;
	for (auto i = settings.begin(); i != settings.end(); ++i) {
		i->second = tmp_a;
		gyaku[tmp_a] = i->first;
		tmp_a++;
	}
	long long summing = 0;
	set<long long> gogo;
	long long now_max = 0;
	long long cnts = 0;
	REP(i, query) {
		if (get<0>(inputs[i]) == 1) {
			//set query
			summing += get<2>(inputs[i]);
			seg_tree[(seg_size + settings[get<1>(inputs[i])])].first += get<1>(inputs[i]);
			seg_tree[(seg_size + settings[get<1>(inputs[i])])].second++;
			seg_set((seg_size + settings[get<1>(inputs[i])]) / 2LL);
			gogo.insert(get<1>(inputs[i]));
			now_max = max(now_max, get<1>(inputs[i]));
			cnts++;
		}
		else {
			//find query
			long long ans = 0;
			long long bot = now_max;
			long long top = -1000000001LL;
			while(llabs(top - bot) > 1) {
				long long mid = (top + bot) / 2LL;
				auto q = gogo.lower_bound(mid);
				long long cnt = seg_find(1, 0, seg_size, 0, settings[*q]+1).second;
				if (cnt >= (cnts+1) / 2) {
					bot = mid;
				}
				else {
					top = mid;
				}
			}
			auto j = gogo.lower_bound(bot);
			long long target = *j;
			pair<long long, long long> now = seg_find(1, 0, seg_size, 0, settings[target]+1);
			ans += now.second * target - now.first;
			now = seg_find(1, 0, seg_size, settings[target], seg_size);
			ans += now.first - now.second * target;
			cout << target << " " << ans+summing << endl;
		}
	}
}

