			sum += b;

			if (small.top() > a) {
				small.emplace(a);
			} else {
				big.emplace(a);
			}

			if (sz & 1) {
				while (big.size() >= small.size()) {
					int tmp = big.top();
					big.pop();
					small.emplace(tmp);
				}

				while (small.size() >= big.size() + 2) {
					int tmp = small.top();
					small.pop();
					big.emplace(tmp);
				}
			} else {
				while (big.size() > small.size()) {
					int tmp = big.top();
					big.pop();
					small.emplace(tmp);
				}
				while (big.size() < small.size()) {
					int tmp = small.top();
					small.pop();
					big.emplace(tmp);
				}
			}

			if (sz == 2) {
				v += abs(a - (small.top() != a ? small.top() : big.top()));
			} else {
				v += abs(a - small.top());
			}
		} else {
			printf("%lld %lld\n", small.top(), v + sum);
		}
	}
}

