    // Get median with 2 priority_queue
    priority_queue<int> pq_lft;
    priority_queue<int, vector<int>, greater<int>> pq_rgt;
    pq_lft.push(-INF); pq_rgt.push(INF);
    for(int i=0; i<q; i++){
        cin >> id;
