        if(id == 1){
            cin >> a >> b;
            // Add bias
            ans += b;
            // Insert a
            if(pq_lft.size() == pq_rgt.size()){
                if(a < pq_rgt.top()){
                    if(a < pq_lft.top()){
                        ans += pq_lft.top() - a;
                    }
                    pq_lft.push(a);
                }
                else{
                    ans += a - pq_rgt.top();
                    pq_rgt.push(a);
                    pq_lft.push(pq_rgt.top()); pq_rgt.pop();
                }
            }
            else{
                ans += abs(pq_lft.top() - a);
                if(a > pq_lft.top()){
                    pq_rgt.push(a);
