int solve() {
    ll Q;
    cin>>Q;
    ll b = 0;
    multiset<ll> upper;
    multiset<ll> lower;
    ll su = 0;
    ll sl = 0;
    ll mid = 0;
    ll cnt = 0;
    while (Q--) {
        ll q;
        cin>>q;
        dbgset(upper)
        dbg(mid)
        dbgset(lower)
        dbg(su)
        dbg(sl)
        dbg(cnt)
        if(q == 1) {
            ll x, y;
            cin>>x>>y;
            b += y;
            cnt++;
            if(cnt==1){
                mid = x;
                continue;
            }
            if(upper.size()>lower.size()){
                if(x>=mid){
                    upper.insert(x);
                    ll mi = *upper.begin();
                    upper.erase(upper.begin());
                    su += x - mi;
                    sl += mid;
                    lower.insert(mid);
                    mid = mi;
                }else{
                    lower.insert(x);
                    sl += x;
                }
            }else{
                if(x>mid){
                    upper.insert(x);
                    su += x;
                }else{
                    lower.insert(x);
                    ll ma = *lower.rbegin();
                    lower.erase(lower.find(ma));
                    sl += x - ma;
                    su += mid;
                    upper.insert(mid);
                    mid = ma;
                }
            }
        }else{
            ll ans = mid*lower.size()-sl + su - upper.size()*mid + b;
            out2(mid,ans);
        }
    }
    return 0;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout<<std::setprecision(10);
    solve();
}

