    priority_queue<ll> tail, head;
    ll med, tail_sum = 0, head_sum = 0, bias = 0;
    ll number, a, b;
    cin >> number >> a >> b;
    med = a;
    bias += b;
    tail.push(a);
    tail_sum += a;
    for (int i = 0; i < Q - 1; i++) {
        cin >> number;
        if (number == 1) {
            cin >> a >> b;
            bias += b;
            if (a >= med) {
                head.push(-a);
                head_sum += a;
            }
            else {
                tail.push(a);
                tail_sum += a;
            }
            if (tail.size() - head.size() >= 2) {
                head.push(-med);
                head_sum += med;
                tail.pop();
                tail_sum -= med;
                med = tail.top();
            }
            else if (head.size() - tail.size() >= 1) {
                med = -head.top();
                head.pop();
                head_sum -= med;
                tail.push(med);
                tail_sum += med;
            }
        }
        else {
            cout << med << ' ' << head_sum - ll(head.size()) * med + ll(tail.size()) * med - tail_sum + bias << endl;
        }
    }
    return 0;
}

