            query.emplace_back(make_tuple(1,a,b));
            xs.emplace_back(a);
        }else{
            query.emplace_back(make_tuple(2,-1,-1));
        }
    }

    sort(begin(xs),end(xs));
    xs.erase(unique(begin(xs),end(xs)),end(xs));

    print(xs);

    unordered_map<i64,i64> zip;
    rep(i,0,xs.size()){
        zip[xs[i]]=i;
    }

    segtree<i64> seg(xs.size(), 0);
    i64 base=0;
    vector<i64> v;
    rep(i,0,Q){
        i64 k,a,b;
        tie(k,a,b)=query[i];
        if(k==1){
            i64 x=zip[a];
            seg.add(0,x,-1);
