void update(int a, int b, priority_queue<int>& less,
            priority_queue<int, vector<int>, greater<int>>& more,
            int& dless, int& dmore, int& off) {
    off += b;

    int n = less.size(), m = more.size();

    if(n == 0) {
        less.push(a);
        dless += a;
    } else if(n < m) {
        if(a > more.top()) {
            dmore -= more.top();
            less.push(more.top());
            dless += more.top();
            more.pop();
            dmore += a;
            more.push(a);
        } else {
            dless += a;
            less.push(a);
        }
    } else if(n > m) {
        if(a < less.top()) {
            dless -= less.top();
            more.push(less.top());
            dmore += less.top();
            less.pop();
            dless += a;
            less.push(a);
        } else {
            dmore += a;
            more.push(a);
        }
    } else {
        if(a > more.top()) {
            dmore += a;
            more.push(a);
        } else {
            less.push(a);
            dless += a;
        }
    }
}

void print(priority_queue<int>& less, priority_queue<int, vector<int>, greater<int>>& more,
           int dless, int dmore, int off) {
    int n = less.size(), m = more.size();
    if(m == 0) {
        cout << less.top() << " " << off << endl;
    } else if(n < m) {
        int mid = more.top();
        int dist = dmore-mid*more.size() + mid*less.size()-dless;
        cout << mid << " " << dist+off << endl;
    } else {
        int mid = less.top();
        int dist = mid*less.size()-dless + dmore-mid*more.size();
        cout << mid << " " << dist+off << endl;
    }
}

