struct Med{
	multiset<int>f,b;
	ll s1=0,s2=0;
	void balance(){
		int n=f.size()+b.size();
		int sz1=(n%2==0?n/2:n/2+1);
		int sz2=n-sz1;
		while(f.size()>sz1){
			int t=*f.rbegin();
			f.erase(--f.end());
			s1-=t;
			s2+=t;
			b.insert(t);
		}
		while(b.size()>sz2){
			int t=*b.begin();
			b.erase(b.begin());
			s2-=t;
			s1+=t;
			f.insert(t);
		}
	}
	void insert(int x){
		if(!b.empty()&&*b.begin()<x){
			b.insert(x),s2+=x;
		}
		else f.insert(x),s1+=x;
		balance();
	}
};
