template<class T>
struct SegTree
{
	lint n;
	vector<T> t;
	T neutral;

	SegTree(lint _n, const T& _neutral) : neutral(_neutral)
	{
		n = 1;
		while (n < _n)
		{
			n *= 2;
		}
		rep(i, n)
		{
			t.resize(2 * n, neutral);
		}
	}

	using funcT = T(T val1, T val2);
	funcT* un;

	void update(lint i, const T& val)
	{
		i += n - 1;
		t[i] = val;
		while (i > 0)
		{
			i = (i - 1) / 2;
			t[i] = un(t[i * 2 + 1], t[i * 2 + 2]);
		}
	}

	T query_impl(lint a, lint b, lint k, lint l, lint r)
	{
		if (r <= a || b <= l)
			return neutral;
		if (a <= l && r <= b)
			return t[k];
		else
		{
			const T c1 = query_impl(a, b, 2 * k + 1, l, (l + r) / 2);
			const T c2 = query_impl(a, b, 2 * k + 2, (l + r) / 2, r);
			return un(c1, c2);
		}
	}

	T query(lint l, lint r)
	{
		return query_impl(l, r, 0, 0, n);
	}

};

int main()
{
	lint n;
	cin >> n;

	lint bb = 0;

	struct Q
	{
		lint q, a, b;
	};
	vect<Q> q(n);

	vec aa(n + 1);

	rep(i, n)
	{
		cin >> q[i].q;
		if (q[i].q == 1)
		{
			cin >> q[i].a >> q[i].b;
			aa[i] = q[i].a;
		}
	}
	aa[n] = inf;
	sort(all(aa));

	SegTree<lint> seg(n + 1, 0), seg2(n + 1, 0);
	seg.un = [](lint x, lint y)
	{
		return x + y;
	};
	seg2.un = seg.un;


	auto f = [&](lint ii)
	{
		lint
			q1 = seg.query(0, ii + 1),
			q2 = seg.query(ii + 1, n),
			q3 = seg2.query(0, ii + 1), 
			q4 = seg2.query(ii + 1, n);

		return -q1 + q2 + q3 * aa[ii] - q4 * aa[ii] + bb;
	};

	rep(i, n)
	{
		if (q[i].q == 1)
		{
			bb += q[i].b;
			lint ii = lower_bound(all(aa), q[i].a) - aa.begin();

			seg.update(ii, seg.query(ii, ii + 1) + q[i].a);
			seg2.update(ii, seg2.query(ii, ii + 1) + 1);
		}
		else
		{
			//rep(i, n)
			//{
			//	cout << aa[i] << ' ' << f(i) << endl;
			//}

			lint ll = 0, rr = n;

			while (rr - ll != 0)
			{
				lint tl = (ll * 2 + rr * 1) / 3;
				lint tr = (ll * 1 + rr * 2) / 3;
				lint al = f(tl), ar = f(tr);

				if (al < ar)
				{
					rr = tl;
				}
				else if (al > ar)
				{
					ll = tr;
				}
				else
				{
					ll = tl;
					rr = tr;
				}
			}
			while (ll > 0 && f(ll) == f(ll - 1))
				ll--;
			cout << aa[ll] << ' ' << f(ll) << endl;
		}

	}

	return 0;
}

