int main(){

    int Q;
    cin >> Q;

    int cnt = 0;
    long long bSum = 0;
    pair<int, int> median;
    long long leftSum = 0;
    long long rightSum = 0;
    set<pair<int, int>> s;
    for(int i = 0; i < Q; i++){
        int type;
        cin >> type;
        if(type == 1){
            int a, b;
            cin >> a >> b;

            cnt++;
            s.insert(make_pair(a, cnt));

            bSum += b;

            if(i == 0){
                median = make_pair(a, cnt);
            }
            else{
                if(make_pair(a, cnt) < median){
                    if(cnt % 2 == 0){
                        // left
                        auto temp = s.find(median);
                        temp--;
                        rightSum += median.first;
                        leftSum += a;
                        median = *temp;
                    }
                    else{
                        // same
                        leftSum += a;
                        rightSum -= median.first;
                    }
                }
                else{
                    if(cnt % 2 == 0){
                        // same
                        rightSum += a;
                        leftSum += median.first;
                    }
                    else{
                        // right
                        auto temp = s.find(median);
                        temp++;
                        rightSum += a;
                        median = *temp;
                        rightSum -= median.first;
                    }
                }
            }
        }
        else{
            long long ans = bSum - leftSum + rightSum;
