multiset<int> ls = {-INF}, rs = {INF};

pll update(Query &q, ll fx) {
    int lx = *ls.rbegin();
    int rx = (ls.size() == rs.size()) ? *rs.begin() : lx;
    if (q.a < lx) {
        fx += lx - q.a;
    } else if (rx < q.a) {
        fx += q.a - rx;
    }
    fx += q.b;

    if (ls.size() > rs.size()) {
        rs.insert(q.a);
    } else {
        ls.insert(q.a);
    }
    auto lr = *ls.rbegin(), rl = *rs.begin();
    if (lr > rl) {
        ls.erase(--ls.end());
        rs.erase(rs.begin());
        ls.insert(rl);
        rs.insert(lr);
    }

    return {*ls.rbegin(), fx};
}

void solve() {
    pll ans = {0, 0};
    for (int i = 0; i < Q; i++) {
        if (qs[i].ty) {
            cout << ans.first << " " << ans.second << endl;
        } else {
            ans = update(qs[i], ans.second);
        }
    }
}

