ll arr[MAXN] = {0}, aux[MAXN] = {0};

ll t[4*MAXN]={0}, t2[4*MAXN]={0};
void build(ll node, ll start, ll end){
    if(start == end){
        t[node] = arr[start];
        return ;
    }
    ll mid = (start + end) / 2;
    build(2*node, start, mid);
    build(2*node+1, mid+1, end);
    t[node] = t[2*node] + t[2*node+1]; 
}

void update(ll node, ll start, ll end, ll idx, ll val){
    if(start == end){
        aux[idx] = 1;
        arr[idx] = val;
        t[node] = val;
        t2[node] = 1;
        return ;
    }
    ll mid = (start + end) / 2;
    if(idx >= start && idx <= mid){
        update(2*node, start, mid, idx, val);
    }
    else {
        update(2*node+1, mid+1, end, idx, val);
    }
    t[node] = t[2*node] + t[2*node+1];
    t2[node] = t2[2*node] + t2[2*node+1];
}

ll query(ll node, ll start, ll end, ll l, ll r){
    if(r < start || l > end || l>r){
        return 0;    // range represented by node is completely outside the given range
    }
    else if(l <= start && r >= end){
        return t[node];  // range represented by a node is completely inside the given range
    }
    // range represented by a node is partially inside and partially outside the given range
    ll mid = (start + end) / 2;
    ll p1 = query(2*node, start, mid, l, r);
    ll p2 = query(2*node+1, mid+1, end, l, r);
    return (p1 + p2);
}

ll query2(ll node, ll start, ll end, ll l, ll r){
    if(r < start || l > end || l>r){
        return 0;    // range represented by node is completely outside the given range
    }
    else if(l <= start && r >= end){
        return t2[node];  // range represented by a node is completely inside the given range
    }
    // range represented by a node is partially inside and partially outside the given range
    ll mid = (start + end) / 2;
    ll p1 = query2(2*node, start, mid, l, r);
    ll p2 = query2(2*node+1, mid+1, end, l, r);
    return (p1 + p2);
}


