signed main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	int Q;
	priority_queue<int> lpq;
	priority_queue<int, vector<int>, greater<int>> rpq;
	int sl = 0, sr = 0;
	int m = INF;
	int B = 0;
	int q, a, b;

	cin >> Q;
	rep(i, 0, Q)
	{
		cin >> q;
		if (q == 1)
		{
			cin >> a >> b;
			B += b;
			if (m == INF)
			{
				m = a;
			}
			else
			{
				if (a <= m)
				{
					lpq.push(a);
					sl += m - a;
				}
				else
				{
					rpq.push(a);
					sr += a - m;
				}

				if (SZ(lpq) > SZ(rpq)+1)
				{
					int t = lpq.top();
					rpq.push(m);
					sr += (m - t)*SZ(rpq);
					sl -= (m - t)*SZ(lpq);
					m = t;
					lpq.pop();
				}
				if (SZ(lpq) < SZ(rpq))
				{
					int t = rpq.top();
					lpq.push(m);
					sl += (t - m)*SZ(lpq);
					sr -= (t - m)*SZ(rpq);
					m = t;
					rpq.pop();
				}

			}
		}
		else
		{
			cout << m << " " << sl + sr + B << endl;
		}
	}

	return 0;
}

