typedef long long ll;

class Bit {
  int n_;
  map<int, int> m_;
public:
  explicit Bit(int n) : n_(n) {}
  void insert(int a, int w) {
    for (ll x = a; x <= n_; x += x & -x) {
      m_[x] += w;
    }
  }
  ll sum(int a) {
    ll ret = 0;
    for (ll x = a; x > 0; x -= x & -x) {
      auto it = m_.find(x);
      if (it != m_.end()) ret += it->second;
    }
    return ret;
  }
};

int main() {
  int Q;
  scanf("%d", &Q);
  int B = 1000000000;
  Bit f(B*2+1);
  Bit v(B*2+1);
  int n = 0;
  ll t = 0;
  for (int i = 0; i < Q; i++) {
    int q;
    scanf("%d", &q);
    if (q == 1) {
      int a, b;
      scanf("%d%d", &a, &b);
      n++;
      t += b;
      //printf("a=%d b=%d\n", a, b);
      f.insert(B+1+a, 1);
      v.insert(B+1+a, a);
    } else {
      ll l = 0;
      ll r = 2*B+1;
      for (int j = 0; j < 40; j++) {
        ll mid = (l + r) / 2;
        int s = f.sum(mid) * 2;
        //printf("sum(%lld)=%d\n", mid, s);
        if (s < n) {
          l = mid;
        } else {
          r = mid;
        }
      }
      // (p-x1) + (p-x2) + ... (p-xi)
      // (x1-p) + (x2-p) + ...
      ll x = r-(B+1);
      ll d = f.sum(r-1) * x - v.sum(r-1) +
        (v.sum(2*B+1) - v.sum(r)) - (f.sum(2*B+1)-f.sum(r));
      printf("%lld %lld\n", r-(B+1), t+d);
      fflush(stdout);
    }
  }
}

