ll H, W;
string S;

void solve() {
	// f(x) = 0
	// 1 4 2
	// f(x) = 0 + |x - 4| + 2
	// 2 -> 2
	// 1 1 -8
	// f(x) = |x-4| + 2 + |x-1| -8
	// f(x) = |x-4| + |x-1| + 2 - 8
	// sigma_1-Q |x-ai| + bi
	// グラフは下がって上がる
	// あるxについて、下がっている絶対値の数と上がっている絶対値の数を比較
	// 下がりが多い -> 下がっているので続ける
	// 等しいとき-> 値の変化がないので最小
	// 上りが多い -> 上がっているので、上がり始めるときに最小
	cin >> Q;
	vpii Ans;

	multiset<pair<ll, ll>> A;
	vi As;

	ll B = 0;

	ll up = 0;
	ll down = 0;

	{
		ll i, a, b;
		cin >> i >> a >> b;
		A.insert(mp(a, 0));
		As.pb(a);
		B += b;
		down += a;
	}

	auto itr = A.begin();
	auto size = 1;


	repa(i, 1, Q) {
		ll query;
		cin >> query;

		if (query == 1) {
			ll a, b;
			cin >> a >> b;
			A.insert(mp(a, i));
			As.pb(a);
			B += b;
			size++;

			ll m = (*itr).first;
			if (a < m) {
				if (size % 2 == 0) {
					up += m;
					down -= m;
					down += a;
					itr--;
				}
				else {
					down += a;
				}
			}
			else {
				if (size % 2 == 1) {
					down += m;
					up -= m;
					up += a;
					itr++;
				}
				else {
					up += a;
				}
			}
		}
		else {
			ll m = (*itr).first;

			ll ds = (size + 1) / 2;
			ll us = size - ds;

			ll a = up - us * m + ds * m - down;
			Ans.pb(mp(m, a + B));
		}
	}

	for (auto a : Ans) {
		cout << a.first << " " << a.second << endl;
	}
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	solve();
	return 0;
}

