struct 
{
	ll sumL, sumR;
	multiset<int> L, R;
	void init()
	{
		L.insert(-INF);
		R.insert(INF);
		sumL = sumR = 0;
	}
	void add(int a)
	{
		if (a <= *L.rbegin())
		{
			L.insert(a);
			sumL += a;
		}
		else
		{
			R.insert(a);
			sumR += a;
		}
		if (R.size() > L.size())
		{
			int x = *R.begin();
			R.erase(R.lower_bound(x));
			L.insert(x);
			sumR -= x;
			sumL += x;
		}
		else if (L.size() > R.size()+1)
		{
			int x = *L.rbegin();
			L.erase(L.lower_bound(x));
			R.insert(x);
			sumL -= x;
			sumR += x;
		}
	}
	pll solve()
	{
		int x = *L.rbegin();
		ll y = (x*(ll)L.size()-sumL)+(sumR-x*(ll)R.size());
		return {x, y};
	}
}G;

int main()
{

	ll sum = 0;
	G.init();
	for (int T = inp(); T --; )
	{
		int t = inp();
		if (t == 1)
		{
			int a = inp();
			int b = inp();
			G.add(a);
			sum += b;
		}
		else
		{
			auto ret = G.solve();
			printf("%lld %lld\n", ret.X, ret.Y+sum);
		}
	}

	return 0;
}

