int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    cin >> N;
    ll small_sum=0,large_sum=0;
    ll base=0;
    priority_queue<ll> pq_small;//大きい順に取り出す
    priority_queue<ll,vl,greater<ll>> pq_large;
    rep(i,N){
        int q;
        cin >> q;
        if(q==1){
            ll a,b;
            cin >> a >> b;
            base+=b;
            if(pq_small.size()==0){
                small_sum+=a;
                pq_small.push(a);
            }
            else{
                pq_small.push(a);
                small_sum+=a;
                ll k;
                while(pq_small.size()-1>pq_large.size()){
                    k=pq_small.top();
                    pq_small.pop();
                    pq_large.push(k);
                    small_sum-=k;
                    large_sum+=k;
                }
                while(pq_large.top()<pq_small.top()){
                    ll s=pq_large.top(),t=pq_small.top();
                    pq_large.pop();pq_small.pop();
                    pq_large.push(t);pq_small.push(s);
                    small_sum+=s-t;large_sum+=t-s;
                }
            }
        }
        if(q==2){
            ll s=pq_small.top();
            cout << s << " " << base+(s*(ll)pq_small.size()-small_sum)+(large_sum-s*(ll)pq_large.size()) << endl;
        }
    }
}

