                  sl+=x;
              }
           }
           else
           {
               if(x>mid)
               {
                   hi.insert(x);
                   sh+=x;
               }
               else
               {
                   lo.insert(x);
                   int val=*lo.rbegin();
                   lo.erase(lo.find(val));
                   sl+=x;
                   sl-=val;
                   sh+=mid;
                   hi.insert(mid);
                   mid=val;
               }
           }

        }
        else
        {
            int ses=mid*lo.size()-sl;
            ses+=bsum;
            ses+=(sh-hi.size()*mid);
            cout<<mid<<" "<<ses<<"\n";
        }
    }
    return 0;

}

