                    nextr=tmpr;
                    L.emplace(a);
                    suml+=(ll)(nextl-tmpl)*cntl;
                    suml+=nextl-a;
                    cntl++;
                }
                else{
                    nextl=tmpr;
                    suml+=(ll)(nextl-tmpl)*cntl;
                    R.pop();
                    L.emplace(tmpr);
                    R.emplace(a);
                    nextr=R.top();
                    sumr+=a-nextr;
                    sumr+=(nextr-tmpr)*cntr;
                    cntl++;
                }
            }
            else{
               int tmpl=L.top(),tmpr=R.top();
                int nextl,nextr;
                if(a>tmpl) {
