class xorshift{
private:
    uint64_t x;
public:
    xorshift(){
        random_device rnd;
        mt19937 mt(rnd());
        x = mt();
        for(int i = 0; i < 50; i++){
            random();
        }
    }
    uint64_t random(){
        x = x ^ (x << 7);
        return x = x ^ (x >> 9);
    }
};



struct SumMonoid{
