        return INF;
    }
    static T op(T a, T b){
        return min(a, b);
    }
};

struct MaxMonoid{
    static constexpr T id(){
        return -INF;
    }
    static T op(T a, T b){
        return max(a, b);
    }
};

struct UpdateMonoid{
    static constexpr T id(){
        return INF;
    }
    static T op(T a, T b){
        return b;
    }
};



// RSQ
struct Modifier{
    static T op(T a, T b, int sz){
        return b == UpdateMonoid::id() ? a : b * sz;
    }
};

