                if(tree[c] < qs[i].second.first) l = c;
                else r = c;
            }
            tree.insert(l, qs[i].second.first);
        }
    }


    ll l = 0, r = 0, c = ((ll)tree.size() - 1) / 2;
    for(int i = 0; i < c; i++){
