struct Data {
  multiset<ll> s;
  ll _sum = 0;
  void push(ll a) { s.insert(a); _sum += a; }
  ll popMax() {
    auto it = s.end(); it--;
    ll value = *it; s.erase(it);
    _sum -= value;
    return value;
  }
  ll popMin() {
    auto it = s.begin();
    ll value = *it; s.erase(it);
    _sum -= value;
    return value;
  }
  ll min() {
    return *s.begin();
  }
  ll max() {
    auto it = s.end(); --it;
    return *it;
  }
  ll sum() {
    return _sum;
  }
  int size() { return s.size(); }
};

