    ll x = -INF;
    priority_queue<ll> l;
    priority_queue<ll,VL,greater<ll>> r;

    ll num = 0;
    ll sum = 0, sum_b = 0;
    REP(_,Q){
        int t; cin >> t;
        if(t == 1){
            ll a,b; cin >> a >> b;
            if(num%2 == 0){
                if(x <= a){
                    r.push(a);
                    l.push(x);
                    x = r.top(); r.pop();
                }
                else{
                    l.push(a);
                }
                sum += abs(a-x);
