using namespace std;
typedef long long Int;

const int MAX_Q = 210000;

Int a_bit[MAX_Q + 1], b_bit[MAX_Q + 1];
Int qt[MAX_Q + 1], qa[MAX_Q + 1], qb[MAX_Q + 1];

void add(Int *bit, int p, Int val)
{
  for (p += 1; p <= MAX_Q; p += p & -p) {
    bit[p] += val;
  }
}

Int _val(Int *bit, int p)
{
  Int res = 0;
  for (p += 1; p; p -= p & -p) {
    res += bit[p];
  }
  return res;
}

Int val(int p, Int xp)
{
  Int ret = _val(a_bit, p) * xp;
  ret += _val(b_bit, p);
  return ret;
}

int main()
{
  int q;

  scanf("%d", &q);

  vector<Int> xs;

  for (int i = 0; i < q; i++) {
    scanf("%lld", qt + i);
    if (qt[i] == 1) {
      scanf("%lld %lld", qa + i, qb + i);
      xs.push_back(qa[i]);
    }
  }

  sort(xs.begin(), xs.end());
  xs.erase(unique(xs.begin(), xs.end()), xs.end());

  for (int i = 0; i < q; i++) {
    if (qt[i] == 1) {
      int pos = lower_bound(xs.begin(), xs.end(), qa[i]) - xs.begin();
      add(a_bit, 0, -1);
      add(a_bit, pos, 2);
      add(b_bit, 0, qa[i] + qb[i]); 
      add(b_bit, pos, -2 * qa[i]);
    }
    else {
      int l = 0, r = (int)xs.size() - 1;
      while (l != r) {
        int m = (l + r) / 2;
        if (val(m, xs[m]) <= val(m + 1, xs[m + 1])) r = m;
        else l = m + 1;
      }
      printf("%d %lld\n", xs[l], val(l, xs[l]));
    }
  }

  return 0;
}

