			bs += b;
			as += a;
			num++;
			root = insertNode(a, root);
		}
		else {
			pair<int, int> p = searchNode((num - 1) / 2 + 1, root);
			int n = (num - 1) / 2 + 1;
			// cout << p.second << endl;
			cout << p.first << " " << (n * p.first - p.second) - (num - n) * p.first + as - p.second + bs << endl;
		}
	}

}

