                if(tree.size() % 2 == 1){
                    ll t = tree[c + 1] - tree[c];
                    l += c * t;
                    r -= (tree.size() - c - 1) * t;
                    c++;
                }
                else{
                    c--;
                }
            }
            else if(idx > c){
                r -= abs(tree[c] - a);
