                    tree.erase(idx);
                    l = r = 0;
                    continue;
                }
                if(tree.size() % 2 == 1){
                    ll t = tree[c] - tree[c - 1];
                    l -= c * t;
                    r += (tree.size() - 1 - c) * t;
                    c--;

