                }
                else{
                    ll t = tree[c + 1] - tree[c];
                    l += c * t;
                    r -= (tree.size() - 1 - c) * t;
                    c++;

                    tree.erase(idx);
                }
            }
        }
        else{
            ans.push_back({tree[(tree.size() - 1) / 2], l + r + b});
        }
    }

    for(int i = (int)ans.size() - 1; i >= 0; i--){
        printf("%lld %lld\n", ans[i].first, ans[i].second);
    }
}

