        if (t == 1)
        {
            long long a, b;
            cin >> a >> b;
            fixed += b;
            multiset<long long>::iterator it = left.end();
            it--;
            long long prev = *it, prevLarger = right.size(), prevSmaller = left.size();
            if (left.empty() || prev >= a)
            {
                left.insert(a);
            }
            else
            {
                right.insert(a);
            }
            if (left.size() > right.size() + 1)
            {
                it = left.end();
                it--;
                right.insert(*it);
                left.erase(it);
            }
            if (right.size() > left.size())
            {
                it = right.begin();
                left.insert(*it);
                right.erase(it);
            }
            it = left.end();
            it--;
            long long curr = *it;
            if (left.size() + right.size() == 1)
            {
                continue;
            }
            value += (prev - curr) * prevSmaller + (curr - prev) * prevLarger;
        }
        else
        {
            cout << *(left.rbegin()) << " " << value + fixed << '\n';
        }
    }


