void lax() {
	while (A.size() > (sz + 1) / 2) {
		multiset<long long>::iterator it = A.end();
		it--;
		as += 2 * (*it);
		B.insert(*it);
		A.erase(*it);
	}
	while (!B.empty()) {
		multiset<long long>::iterator it = A.end();
		it--;
		if (*it > *B.begin()) {
			long long a = *it, b = *B.begin();
			A.erase(it);
			B.erase(B.begin());
			as += 2 * a;
			as -= 2 * b;
			A.insert(b);
			B.insert(a);
		}
		else
			break;
	}
}
long long geten() {
	multiset<long long>::iterator it = A.end();
	it--;
	return *it;
}

