template <typename T>
class BIT {
  int n; vector<T> bit;
public:
  BIT(int _n) : n(_n) {
    bit = vector<T>(n+1,(T)0);  
  }
  T sum(int i) {
    T s = 0;
    while(i > 0){
      s += bit[i];
      i -= i & -i;
    }
    return s;
  }
  void add(int i, T x) {
    while(i <= n){
    bit[i] += x;
    i += i & -i;
    }
  }
  T lowerbound(T w) {
    if(w <= 0) return 0;
    int x = 0; int p = 1;
    while(true){
      if(p*2 > n) break;
      p *= 2;
    }
    for(int k = p; k > 0; k /= 2){
      if(x+k <= n && bit[x+k] < w){
        w -= bit[x+k];
        x += k;
      }
    }
    return x+1;
  }
};

