void sub(int a) {
	if (a <= F.top()) {
		F.push(a);
		X += a;

		if (F.size() >= G.size() + 2) {
			LL k = F.top(); F.pop();
			G.push(k);
			X -= k;
			Y += k;
		}
	} else {
		G.push(a);
		Y += a;

		if (G.size() >= F.size() + 1) {
			LL k = G.top(); G.pop();
			F.push(k);
			Y -= k;
			X += k;
		}
	}

	LL pos = F.top();
	LL val = (Y - X) - pos * ((int)G.size() - (int)F.size());
	ans = PP(pos, val);
}

