            // 値を追加する際、que2のtopよりも大きい場合はque2に、それ以外はque1に追加していく
            // 個数のバランスが崩れた際には、はみ出した方のtopをもう一方に移す
            // sum1,sum2はque1,que2それぞれの和
			if(que2.empty() || a <= que2.top()){
				que2.push(a);
				sum2 += a;

				if(que2.size() > que1.size() + 1){
					a=que2.top();que2.pop();
					que1.push(a);

					sum2-=a;
					sum1+=a;
				}
			} else {
				que1.push(a);
				sum1+=a;

				if(que1.size()>que2.size()){
					a=que1.top();que1.pop();
					que2.push(a);
					sum2+=a;
					sum1-=a;
				}
			}
		}
	}
    cout << que1.top() << endl;
    cout << que2.top() << endl;
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N=2e5+5;
int q,ans1,tot=0,hs[N];
ll sum,s,sum1,sum2,si1,si2,t[N*4],si[N*4];
int opt[N],x[N],y[N];
void fix(int l,int r,int k,int x)
{
    if(l==r)
    {
        t[k]+=hs[l];
        si[k]++;
        return;
    }
    int m=l+r>>1;
    if(x<=m) fix(l,m,k<<1,x);
    else fix(m+1,r,k<<1|1,x);
    t[k]=t[k<<1]+t[k<<1|1];
    si[k]=si[k<<1]+si[k<<1|1];
}
ll query(int l,int r,int k)
{
    if(l==r)
    {
        ans1=hs[l];
        return si1*hs[l]-sum1+sum2-si2*hs[l];
    }
    int m=l+r>>1;
    if(sum2+si[k<<1|1]<=s/2)
    {
        sum2+=t[k<<1|1];
        si2+=si[k<<1|1];
        return query(l,m,k<<1);
    }
    else
    {
        sum1+=t[k<<1];
        si1+=si[k<<1];
        return query(m+1,r,k<<1|1);
    }
}
int main()
{
    scanf("%d",&q);
    for(int i=1;i<=q;i++)
    {
        scanf("%d",&opt[i]);
        if(opt[i]==1)
            scanf("%d%d",&x[i],&y[i]),hs[++tot]=x[i];
    }
    sort(hs+1,hs+1+tot);
    for(int i=1;i<=q;i++)
    {
        if(opt[i]==1)
        {
            s++;
            fix(1,tot,1,lower_bound(hs+1,hs+1+tot,x[i])-hs);
            sum+=y[i];
        }
        else
        {
            sum1=sum2=si1=si2=0;
            ll ans2=query(1,tot,1)+sum;
            printf("%d %lld\n",ans1,ans2);
        }
    }
}

