#define MAX_N (1<<18) //260000
template<typename T>
struct segtree{
    int n;
    T dat[2*MAX_N-1];
    T cnt[2*MAX_N-1];

    void init(int n_){
        n = 1;
        while(n < n_) n *= 2;
        for(int i = 0; i < 2*n-1; i++) dat[i] = 0;
        for(int i = 0; i < 2*n-1; i++) cnt[i] = 0;
    }

    void update(int k, T a){
        k += n-1;
        dat[k] = a;
        cnt[k]++;
        while(k > 0){
            k = (k-1)/2;
            dat[k] = dat[k*2+1] + dat[k*2+2];
            cnt[k] = cnt[k*2+1] + cnt[k*2+2];
        }
    }

    //(a,b,0,0,seg.n)で呼ぶ
    T query(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return 0;
        if(a <= l && r <= b) return dat[k];
        else{
            T vl = query(a,b,k*2+1,l,(l+r)/2);
            T vr = query(a,b,k*2+2,(l+r)/2,r);
            return vl + vr;
        }
    }

    int bin(int k, int mid){
        if (k >= n-1) {
            return k-(n-1);
        }
        if (cnt[k*2+1] >= mid) bin(k*2+1, mid);
        else bin(k*2+2, mid - cnt[k*2+1]);
    }
};

