void solv()
{
	int Q; scanf("%d", &Q);

	long long int mid = 0, sumb = 0, sumleft = 0, sumright = 0;
	multiset<int> leftset, rightset;

	int p, a, b; scanf("%d%d%d", &p, &a, &b);
	mid = a; sumb += b;
	for (int i = 1; i < Q; i++){
		int p; scanf("%d", &p);
		if (1 == p){
			int a, b; scanf("%d%d", &a, &b);
			sumb += b;
			if (a < mid){
				leftset.insert(a);
				sumleft += mid - a;
			}
			else{
				rightset.insert(a);
				sumright += a - mid;
			}
			if (leftset.size() > rightset.size()){
				multiset<int>::iterator itr = leftset.end(); itr--;

				rightset.insert(mid);
				sumright += (mid - *itr)*rightset.size();
				sumleft -= (mid - *itr)*leftset.size();

				mid = *itr;
				leftset.erase(itr);
			}
			else if (rightset.size() > leftset.size()+1){
				multiset<int>::iterator itr = rightset.begin();

				leftset.insert(mid);
				sumleft += (*itr - mid)*leftset.size();
				sumright -= (*itr - mid)*rightset.size();

				mid = *itr;
				rightset.erase(itr);
			}
		}
		else{
			printf("%lld %lld\n", mid, sumleft + sumright + sumb);
		}
	}

	return;
}

