		int type;
		cin>>type;
		if(type==1){
			int a,b;
			cin>>a>>b;
			sumb+=b;
			if(l.empty())l.push(a);
			else if(l.size()==r.size()){
				if(l.top()<=a&&a<=r.top()){
					l.push(a);
				}
				else if(a<l.top()){
					diff+=l.top()-a;
					l.push(a);
				}
				else{
					r.push(a);
					int memo=r.top();
					diff+=a-memo;
					l.push(memo);
					r.pop();
				}
			}
			else{
				if(l.top()<=a){
					r.push(a);
					diff+=a-l.top();
				}
				else{
					int memo=l.top();
					l.pop();
					r.push(memo);
					if(l.empty()){
						l.push(a);
						diff+=memo-a;
					}
					else{
						if(l.top()<a){
							diff-=memo-a;
						}
						else{
							diff-=memo-l.top();
							diff+=l.top()-a;
						}
						l.push(a);
					}
				}
			}
		}
		if(type==2){
			cout<<l.top()<<" "<<diff+sumb<<endl;
		}
	}
