ll partitio(ll *arra, ll left, ll right)
{
 if (arra == NULL)
 return -1;

 ll pos = right;
 right--;
 while (left <= right)
 {
 while (left < pos && arra[left] <= arra[pos])
  left++;

 while (right >= 0 && arra[right] > arra[pos])
  right--;

 if (left >= right)
  break;

 swap(arra[left], arra[right]);
 }
 swap(arra[left], arra[pos]);

 return left;
}
ll getMidIndex(ll *arra, ll siz)
{
 if (arra == NULL || siz <= 0)
 return -1;

 ll left = 0;
 ll right = siz - 1;
 ll midPos = right >> 1;
 ll index = -1;

 while (index != midPos)
 {
 index = partitio(arra, left, right);

 if (index < midPos)
 {
  left = index + 1;
 }
 else if (index > midPos)
 {
  right = index - 1;
 }
 else
 {
  break;
 }
 }

 assert(index == midPos);
 return arra[index];
}
