      if (ql.size() != 0) {
        if (ql.top() <= a && a <= qr.top()) {
          suma += 0;
        } else {
          suma += min(abs(ql.top() - a), abs(a - qr.top()));
        }
      }

      sumb += b;

      ql.push(a);
      ql.push(a);
      while (ql.size() > qr.size()) {
        qr.push(ql.top());
        ql.pop();
      }

    } else if (q == 2) {
