template<class Val>
struct BinaryIndexedTree {
    int n;
    vector<Val> t;
    BinaryIndexedTree() {}
    BinaryIndexedTree(int _n) :n(_n + 1), t(_n + 1) {}
    void add(int k, Val val) {
        k++;
        while (k < n) {
            t[k] += val;
            k += (k&-k);
        }
    }
    void set(int k, Val val) {
        add(k, -sum(k, k + 1));
        add(k, val);
    }
    Val sum(int k) {
        Val r = 0;
        while (k > 0) {
            r += t[k];
            k -= (k&-k);
        }
        return r;
    }
    Val sum(int l, int r) {
        return sum(r) - sum(l);
    }
};

template<class Val>
vector<Val> compress(vector<Val> &v) {
    vector<Val> a = v;
    sort(all(a));
    a.erase(unique(all(a)), a.end());
    each(b, v)b = (int)(lower_bound(all(a), b) - a.begin());
    return a;
}

void solve() {
    int Q;
    cin >> Q;
    vi P(Q), A(Q), B(Q);

    rep(i, Q) {
        cin >> P[i];
        if (P[i] == 1) {
            cin >> A[i] >> B[i];
        }
    }

    ll sb = 0;

    auto C = compress(A);
    int N = sz(C);
    BinaryIndexedTree<ll> sumA(N), cntA(N);

    set<int> S;
    int x = A[0], m = 0;
    rep(i, Q) {
        if (P[i] == 1) {
            m++;
            sumA.add(A[i], C[A[i]]);
            cntA.add(A[i], 1);
            S.insert(A[i]);
            sb += B[i];
            auto it = S.find(A[0]);
            auto itit = it;
            if (cntA.sum(*it) >= (m + 1) / 2) {
                --it;
            } else if (cntA.sum(*it + 1) < (m + 1) / 2) {
                ++it;
            }
            x = *it;
        } else {
            ll ans = sb;
            ans += cntA.sum(x)*C[x] - sumA.sum(x);
            ans += sumA.sum(x, N) - cntA.sum(x, N)*C[x];
            cout << C[x] << ' ' << ans << endl;
        }
    }
}

int main() {
	ios::sync_with_stdio(false);
