    ll lsum = 0, rsum = 0;
    ll sum = 0;
    rep(_, q)
    {
        ll x = in();
        if (x == 1)
        {
            ll a = in(), b = in();
            sum += b;
            if (left.size() <= right.size())
            {
                left.push(a);
                lsum += a;
            }
            else
            {
                right.push(a);
                rsum += a;
            }

            if (!right.empty() && left.top() > right.top())
            {
                ll l = left.top();
                ll r = right.top();
                left.pop();
                right.pop();
                lsum -= l;
                rsum -= r;
                left.push(r);
                right.push(l);
                lsum += r;
                rsum += l;
