					rs.push(b), rs.push(b);

					//もともとの更新前の中央値番の点と今回入力された点の間で差分更新を行う
					ans += min(abs(ls.top() - b), abs(b - rs.top()));

					//最小値をとる場所は*ls.end()に更新
					anspos = ls.top();
				}
			}
		}
		else {

			//求値クエリ
			cout << anspos << " " << ans + B << endl;
		}
	}
