//BIT
class BinaryIndexedTree{
  int N;
  vector<int> BIT;

  public:  

  BinaryIndexedTree(int n):BIT(n+1,0){ N = n; }//1-indexed
  BinaryIndexedTree(vector<int> v):BIT(v.size()+1,0){
    N = v.size();
    for(int i=1; i<=N; i++){
      add(i,v[i-1]); 
    }
  }

  void add(int x, int y){//0-indexed originから呼び出される時
    for(int i=x+1; i <= N; i += i&-i){
      BIT[i] += y;
    }
  }

  int sum(int x){
    int ret = 0;
    for(int i=x+1; i>0; i -= i&-i){
      ret += BIT[i];
    }
    return ret;
  }

  int getXth(int x){
    //最小値を求める時
    int ok = N+1;//解が存在する最大値
    int ng = -1;//解が存在しない最小値
    /*
    //最大値を求める時
    ll ok = -1;//解が存在する最小値
    ll ng = 1e18;//解が存在しない最大値
    */

    while(abs(ok-ng) > 1){
      int mid = (ok+ng)/2;
      if((this->sum(mid)) >= x){//((C+1)+1)/2
        ok = mid; 
      }else{
        ng = mid;
      }
    } 
    return ok;
  }

  inline int operator [] (int index) const{//読み取り
     return BIT[index];
  }
  inline int& operator [] (int index){//書き取り
     return BIT[index];
  }
};

//座標圧縮
class CC{
  public:
  map<ll,int> mp;//0-indexed
  map<int,ll> rmp;
  bool isUnique = true;

  CC(vector<ll> v){//座標圧縮が必要になるのはlonglongintの時が多い？
    sort(v.begin(),v.end());
    auto result = unique(v.begin(),v.end());
    isUnique = (result == v.end());
    v.erase(result, v.end());//重複を除いてもmapから参照できる。

    for(int i=0; i<v.size(); i++){
      mp.emplace_hint(mp.end(),v[i],i);//key→value
      rmp.emplace_hint(rmp.end(),i,v[i]);//value→key
    }
  }

  ll getKey(int value){//keyが必要な場合は座標圧縮前のベクトルから参照できるため、これは不要？
    //座標圧縮後valueに対応するkeyを取得→0-indexedの時value+1番目のkey→v[value]で良いのでは？
    //key0がvalue0に対応している点に注意。
    return this->rmp[value];
  }


  /*
