      va[c] = a; vb[c] = b;
      c ++;
    }else{
      continue; 
    }
  }

  //main
  CC cc(va);//まず座標圧縮

  // output
  //aの個数を管理。
  BinaryIndexedTree bit(va.size());//Qが上界。
  ll center = 0;

  int count = 0;

  for(int i=0; i<Q; i++){
    if(vt[i]==1){//クエリ1
      bit.add(cc.mp[va[count]],1); 
      sum_b += vb[count];

      if(count == 0){
        center = va[count];
      }else if((count+1)%2){//aが偶数から奇数になる。
        if(va[count]<=center){//左側
          //center = center;
          sum_a += abs(va[count]-center);
        }else{//右側
          center = cc.getKey(bit.getXth(count/2+1));
          sum_a += abs(va[count]-center);
        }
      }else{//aが奇数から偶数になる。
        if(va[count]>=center){//右側
          //center = center;
          sum_a += abs(va[count]-center);
        }else{//左側
          int x = cc.getKey(bit.getXth((count+1)/2));
          ll g = abs(center-x);
          center = x;
          sum_a += (abs(va[count]-center) + g);
        }
      }

      count ++;

    }else{//クエリ2
      printf("%lld %lld\n", center, sum_a+sum_b);
    }
  }

  return 0;
}

