#include<bits/stdc++.h>
using namespace std;
using ll=long long;

class lazyseg
{
	int n,size;
	vector<ll> node,lazy;
public:
	lazyseg(vector<ll> a)
	{
		n=a.size();
		size=1;
		while (size<n) size*=2;
		node.resize(2*size-1,0);
		lazy.resize(2*size-1,0);
	}

	void lazy_eva(int k,int l,int r)
	{
		if (lazy[k]!=0)
		{
			node[k]+=lazy[k];
			if (r-l>1)
			{
				lazy[2*k+1]=lazy[k]/2;
				lazy[2*k+2]=lazy[k]/2;
			}
			lazy[k]=0;
		}
	}
	void add_point (int a,int x) //0-indexed
	{
        a+=size-1;
		node[a]+=x;
		while (a>0)
        {
            a=(a-1)/2;
            node[a]+=x;
        }
		return;
	}

	void add(int a,int b,ll x,int k=0,int l=0, int r=0) //0-indexed 
	{
		if (l>=r) {r=size;}
		lazy_eva(k,l,r);
		if (b<=l || r<=a) return ;
		if (a<=l && r<=b)
		{
			lazy[k]+=(r-l)*x;
			lazy_eva(k,l,r);
		}
		else
		{
			add(a,b,x,2*k+1,l,(l+r)/2);
			add(a,b,x,2*k+2,(l+r)/2,r);
			node[k]=node[2*k+1]+node[2*k+2];
		}
		return ;
	}

	ll sum(int a,int b, int k=0,int l=0,int r=0) //0-indexed
	{
		if (r<=l) r=size;

		if (r<=a || b<=l ) return 0;
		lazy_eva(k,l,r);
		if (a<=l && r<= b) return node[k];
		else return sum(a,b,2*k+1,l,(l+r)/2)+sum(a,b,2*k+2,(l+r)/2,r);
	}
};

