#include <bits/stdc++.h>
using namespace std;
using lint = long long;

int main() {
    int q;
    cin >> q;

    long long front_sum = 0, back_sum = 0, b_sum = 0;
    priority_queue<lint> front_queue;
    priority_queue<lint, vector<lint>, greater<lint>> back_queue;

    auto balance = [&] () {
        if (front_queue.size() < back_queue.size()) {
            while (front_queue.size() < back_queue.size()) {
                front_queue.emplace(back_queue.top());
                back_sum -= back_queue.top();
                front_sum += back_queue.top();
                back_queue.pop();
            }
        } else {
            while (front_queue.size() > back_queue.size()) {
                back_queue.emplace(front_queue.top());
                front_sum -= front_queue.top();
                back_sum += front_queue.top();
                front_queue.pop();
            }
        }
    };

    auto add = [&] (lint a, lint b) {
        b_sum += b;
        if (front_queue.empty() and back_queue.empty()) {
            front_queue.emplace(a); front_sum += a; return;
        }
        balance();
        lint med = front_queue.top();
        if (med < a) { back_queue.emplace(a); back_sum += a; }
        else { front_queue.emplace(a); front_sum += a; }
    };

    auto answer = [&] () {
        balance();
        lint a = front_queue.top();
        lint s = front_queue.size(), t = back_queue.size();
        lint ans = b_sum+abs(a*s-front_sum)+abs(a*t-back_sum);
        cout << a << " " << ans << '\n';
    };

    while (q--) {
        int op, a, b;
        cin >> op;
        if (op == 1) {
            cin >> a >> b;
            add(a, b);
        } else {
            answer();
        }
    }
    return 0;
}

