//クエリ1入ったら更新
ll update(ll a,int& s){
  ll res=0;
  if(s==0){//
    set_lef.insert(a);
    s++;
    return 0;
  }
  if(s%2==0){//even
    auto itr=set_lef.end();itr--;//メジアンのイテレータを取得
    auto itr2=set_rig.begin();//メジアンの次の要素のイテレータを取得
    if(a<*itr) res=*itr-a;
    else if(*itr2<=a) res=a-*itr2;
    else res=0;
    set_lef.insert(a);//左のsetに挿入
    s++;
    return res;
  }
  else{//odd
    auto itr=set_lef.end();itr--;//メジアンのイテレータを取得
    res=std::abs(a-*itr);
    if(*itr<=a){
      set_rig.insert(a);//右のsetに挿入
    }
    else{
      set_lef.insert(a);//左のsetに挿入し左の一番大きい要素(元メジアン)を右のsetに挿入
      set_rig.insert(*itr);
      set_lef.erase(*itr);
    }
    s++;
    return res;
  }
}
