                    rightsum+=x;
                    right.push(x);
                }
                cnt++;
            }else{
                ll l=left.top(),r=right.top();
                if(l<=x&&x<=r){
                    leftsum+=x;
                    left.push(x);
                }else if(x<l){
                    leftsum+=x;
                    left.push(x);
                }else{
                    rightsum-=r;
                    right.pop();

                    leftsum+=r;
                    left.push(r);

                    rightsum+=x;
                    right.push(x);
                }
                cnt++;
            }
        }else{
            ll mid,ans=0;
            if(cnt%2==0){
                mid=left.top();
                ans+=(mid)*(cnt/2)-leftsum;
                ans+=rightsum-(mid)*(cnt/2);
            }else{
                mid=right.top();
                ans+=(mid)*(cnt/2)-leftsum;
                ans+=rightsum-(mid)*(cnt/2+1);
            }
            cout<<mid<<" "<<ans+b<<endl;
        }
    }
}

