void ins(vector<int>& a, int A) {
	int s = a.size();
	if (s == 0) {
		a.push_back(A);
		return;
	}
	auto it = a.begin();
	int i = 0;
	while (a.at(i) < A) {
		i++;
		it++;
		if (i >= s - 1)break;
	}
	a.insert(it, A);
}

