int main() {
  using LL = long long;
  struct Query {LL n, a, b;};
  LL D = 1e9 + 1;

  int N;
  cin >> N;

  vector<Query> Q(N);
  for(auto& q: Q) {
    cin >> q.n;
    if(q.n == 1) cin >> q.a >> q.b;
  }

  vector<LL> p = {0, LL(1e9+D)};
  for(auto& q: Q) q.a += D;
  for(const auto& q: Q) if(q.n == 1) p.emplace_back(q.a);
  Compression<LL> comp(p);

  SegmentTree<LL> sum(comp.size()+1), num(comp.size()+1);
  auto f = [&](auto i) {
    auto x = comp[i];
    return x*num.sum(0, i)-sum.sum(0, i) + sum.sum(i+1, comp.size())-x*num.sum(i+1, comp.size());
  };
  LL c = 0;
  for(const auto& q: Q) {
    if(q.n == 1) {
