  SegTree(vector<ll> v){
    ll sz=v.size();
    n=1;
    while(n<sz) n*=2;
    node.resize(2*n-1,0);
    for(int i=0;i<sz;i++) node[i+n-1]=v[i];
    for(int i=n-2;i>=0;i--) node[i]=node[2*i+1]+node[2*i+2];
  }
  void update(ll x,ll val){
    x+=(n-1);
    node[x]+=val;
    while(x>0){
      x=(x-1)/2;
      node[x]+=val;
    }
  }
  ll getsum(ll a,ll b,ll k=0,ll l=0,ll r=-1){
    if(r<0) r=n;
    if(r<=a||b<=l) return 0;
    if(a<=l&&r<=b) return node[k];
    return getsum(a,b,2*k+1,l,(l+r)/2)+getsum(a,b,2*k+2,(l+r)/2,r);
  }
  void debug(){
    for(int i=0;i<node.size();i++) cout<<node[i]<<" ";
    cout<<endl;
  }
};
