      cin >> a >> b;

      bsum += b;
      if (left.size() > 0) {
        if (left.begin()->first <= a && a <= right.begin()->first) {
          asum += 0;
        } else {
          if (abs(left.begin()->first - a) < abs(right.begin()->first - a)) {
            asum += abs(left.begin()->first - a);
          } else {
            asum += abs(right.begin()->first - a);
          }
        }
      } else {
        asum = 0;
      }

      // Insert new a and b
      left.insert(make_pair(a, b));
      right.insert(make_pair(a, b));

      if (left.begin()->first > right.begin()->first) {
        // swap
        pair<long, long> tmpleft = *left.begin();
        pair<long, long> tmpright = *right.begin();

        left.erase(left.begin());
        right.erase(right.begin());

        left.insert(tmpright);
        right.insert(tmpleft);
      }

    } else if (qtype == 2) {
      auto ans = left.begin()->first;
      cout << ans << " " << asum + bsum << endl;
    }
  }

  return 0;
}

