void update(
    std::map<int64_t, uint64_t> &joints,
    int64_t &b, int &n)
{
  int a_, b_;
  std::cin >> a_ >> b_;
  joints[a_] += 1;
  b += b_;
  n++;

  // print_map(joints, "updated joints");
}

void print(
    std::map<int64_t, uint64_t> &joints,
    int64_t &b, int &n)
{
  int n_ = (n + 1)/ 2;
  // std::cout << "n: " << n << " n_: " << n_ << std::endl;
  int sum = 0;

  int argmin = 0;
  for(auto it : joints) {
    auto k = it.first;
    auto v = it.second;
    sum += v;
    if(n_ <= sum) {
      argmin = k;
      break;
    }
  }

  int64_t min = b;
  for(auto it: joints) {
    auto k = it.first;
    auto v = it.second;
    int sign = k < argmin ? 1 : -1;
    // std::cout << "min: " << min << std::endl;
    // std::cout << "k: " << k << " v:" << v << " sign: " << sign << " argmin: " << argmin << std::endl;
    min += sign * v * (argmin - k);
  }

  std::cout << argmin << " " << min << std::endl;
}

