		if (t == 1) std::cin >> a >> b;
		q[i] = Query{ t, a, b };
	}

	std::map<int, int> map;
	int sz = 0;
	{
		REP(i, Q) {
			if (q[i].t == 1) map[q[i].a];
		}
		for (auto& p : map) p.second = sz++;
	}
	BIT bit(sz + 1);

	int sum = 0;
	std::set<int> set;
	int cnt = 0;
	int now = 0;
	int low = 0;
	{
		sum += q[0].b;
		set.insert(q[0].a);
		now = q[0].a;
		bit.add(map[q[0].a], 1);
	}
	FOR(i, 1, Q) {
		int type = q[i].t, a = q[i].a, b = q[i].b;

		if (type == 1) {
			sum += b;
			low += std::abs(now - a);
			bit.add(map[a], 1);
			[&]{
				auto it = map.upper_bound(now);
				if (it == map.end()) return;
				int to = it->first;
				int tlow = low;
				tlow += (to - now) * bit.sum(map[to] + 1);
