  ll popMax() {
    auto it = s.end(); it--;
    ll value = *it; s.erase(it);
    _sum -= value;
    return value;
  }
  ll popMin() {
    auto it = s.begin();
    ll value = *it; s.erase(it);
    _sum -= value;
    return value;
  }
  ll min() {
    return *s.begin();
  }
  ll max() {
    auto it = s.end(); --it;
    return *it;
  }
  ll sum() {
    return _sum;
