void solve() {
    LL q,t,a,b;
    cin >> q;
    priority_queue<LL,VLL,less<LL>> ql;
    priority_queue<LL,VLL,greater<LL>> qr;
    LL suma = 0, sumb = 0;
    REP(qq,0,q) {
        cin >> t;
        if (t == 1) {
            cin >> a >> b;
            sumb += b;

            if (ql.size() == 0) {
                ql.push(a);
                suma -= a;
            } else if (ql.top() < a) {
                qr.push(a);
                suma += a;
            } else {
                ql.push(a);
                suma -= a;
            }

            if (ql.size() - qr.size() == 2) {
                suma += 2 * ql.top();
                qr.push(ql.top());
                ql.pop();
            } else if (qr.size() > ql.size()) {
                suma -= 2 * qr.top();
                ql.push(qr.top());
                qr.pop();
            }
        } else if (t == 2) {
            cout << ql.top() << " ";
            LL add = 0;
            if (ql.size() - qr.size() == 1) add += ql.top();
            cout << suma + sumb + add << endl;
        }
    }
}

