int Signum(int a, int b) {
    if(a == b) return 0;
    return a < b ? -1 : 1;
}
int suml, sumr;
int getMedian(int e, int &m, priority_queue<int> &l, heap<int> &r) {
    switch(Signum(l.size(), r.size())) {
    case 1:
        if (e <= m) {
            r.push(l.top());
            sumr += l.top();
            suml -= l.top();
            l.pop();
            l.push(e);
            suml += e;
        } else {
            r.push(e); 
            sumr += e;
        } 
        m = l.top(); 
        break; 
    case 0:
        if (e <= m) { 
            l.push(e); 
            suml += e;
            m = l.top(); 
        } else { 
            r.push(e); 
            sumr += e;
            m = r.top(); 
        }
        break; 
    case -1:
        if (e <= m) {
            l.push(e); 
            suml += e;
        } else {
            l.push(r.top());
            suml += r.top();
            sumr -= r.top();
            r.pop(); 
            r.push(e); 
            sumr += e;
        }
        m = l.top();
        break; 
    }
    return m; 
} 
