struct solver {
    ll x, fx;
    map<ll, int> used;
    int l, r;
    solver() {
        x = 0;
        fx = 0;
        l = r = 0;
    }

    void update(ll a, ll b) {
        fx += abs(x - a) + b;
        used[a] += 1;
        if (a < x) {
            ++ l;
            while (l >= used[x] + r) {
                ll nx = prev(used.find(x))->first;
                fx -= (x - nx) * (l - used[x] - r);
                r += used[x];
                l -= used[nx];
                x = nx;
            }
        } else if (x < a) {
            ++ r;
            while (l + used[x] < r) {
                ll nx = next(used.find(x))->first;
                fx -= (nx - x) * (r - used[x] - l);
                l += used[x];
                r -= used[nx];
                x = nx;
            }
        } else {
            // nop
        }
    }

    pair<ll, ll> get() {
        return make_pair(x, fx);
    }
};

