#include <bits/stdc++.h>
using namespace std;
const int maxn = 234567;
long long f[2][maxn];
void upd(int w, int x, int v){
	for(; x < maxn ; x += x & - x) f[w][x] += v;
}
long long sum(int w, int x){
	long long ans = 0;
	for(; x; x -= x & - x) ans += f[w][x];
	return ans;
}
int main(){
	vector<pair<int,int> > qe;
	vector<int> where;
	int q; cin >> q;
	const int ten9 = 1000000000;
	for(int i = 0; i < q; i++){
		int ty; cin >> ty;
		if(ty == 1){
			int a, b; cin >> a >> b;
			qe.push_back({a, b});
			where.push_back(a);
		} else {
			qe.push_back({ten9 + 1, ten9 + 1});
		}
	}
	sort(where.begin(), where.end());
	where.erase(unique(where.begin(), where.end()), where.end());
	long long add = 0;
	for(int i = 0; i < q; i++){
		int x, y; tie(x, y) = qe[i];
		if(x == ten9 + 1 && y == ten9 + 1){
			auto fdx = [&](int pt){
				int h = lower_bound(where.begin(), where.end(), pt) - where.begin(); h++;
				long long onL = sum(0, h - 1);
				long long onR = sum(0, maxn - 3) - onL;
				long long suL = sum(1, h - 1);
				long long suR = sum(1, maxn - 3) - suL;
				return (onL * pt - suL) + (suR - onR * pt); 
			};
			long long best = 1ll<<60, pt = -1;
			int lo = -ten9, hi = ten9;
			while(hi - lo >= 5){
				int mid = (lo + hi) / 2;
				if(fdx(mid) > fdx(mid + 1)) lo = mid + 1;
				else hi = mid;
			}
			while(lo <= hi){
				long long now = fdx(lo);
				if(now < best) best = now, pt = lo;
				lo++;
			}
			cout << pt << " " << best + add << endl;
		} else {
			int pt = lower_bound(where.begin(), where.end(), x) - where.begin(); pt++;
			add += y;
			upd(0, pt, 1);
			upd(1, pt, x);
		}
	}
	return 0;
}

