priority_queue<li> pq[2];

li add_base = 0;

inline void swap() {
    while (pq[0].top() > -pq[1].top()) {
        li t0 = pq[0].top();
        li t1 = -pq[1].top();
        pq[0].pop();
        pq[1].pop();
        pq[0].push(t1);
        pq[1].push(-t0);
    }
}

inline void add(li a) {
    if ((sz(pq[0]) + sz(pq[1])) % 2 > 0) {
        add_base += abs(a - pq[0].top());
    } else {
        //p3(a, pq[0].top(), pq[1].top());
        if (a < pq[0].top()) {
            add_base += pq[0].top() - a;
        } else if (a > -pq[1].top()) {
            add_base += a - (-pq[1].top());
        }
    }
    pq[0].push(a);
    while (sz(pq[0]) > sz(pq[1]) + 1) {
        li pass = pq[0].top();
        pq[0].pop();
        pq[1].push(-pass);
    }
    if (!pq[1].empty()) {
        swap();
    }
}

