int main() {
  int Q;
  cin>>Q;
  ll query, a, b;
  vector<ll> ansarr;
  vector<ll> ansarr1;
  ll add=0, sub=0;
  multiset<ll> st1, st2;
  ll bash=big;
  auto tmp1=st1.begin(), tmp2=st2.begin(); // st1: ちっちゃいほう, st2: おっきいほう
  ll ans = 0;
  for(int i=0;i<Q;++i) {
    cin>>query;
    if(query==1) {
      cin>>a>>b;
      ans += b;
      if(st1.empty() && bash==big) {
        bash = a;
        continue;
      }
      if(bash==big) {
        if(st1.empty()) {
          bash = a;
        }
        else {
          tmp1 = st1.end();
          tmp1--;
          tmp2 = st2.begin();
          if(*tmp1<=a && a<=*tmp2) bash = a;
          else if(a<*tmp1) {
            bash = *tmp1;
            sub -= *tmp1;
            st1.erase(st1.find(*tmp1));
            sub += a;
            st1.insert(a);
          }
          else {
            bash = *tmp2;
            add -= *tmp2;
            st2.erase(st2.find(*tmp2));
            add += a;
            st2.insert(a);
          }
        }
      }
      else {
        if(bash<=a) {
          add += a;
          sub += bash;
          st1.insert(bash);
          st2.insert(a);
        }
        else {
          add += bash;
          sub += a;
          st1.insert(a);
          st2.insert(bash);
        }
        bash = big;
      }
    }
    else {
      if(bash==big) {
        tmp1 = st1.end();
        tmp1--;
        ansarr1.push_back(*tmp1);
      }
      else ansarr1.push_back(bash);
      ansarr.push_back(add-sub+ans);
    }
  }
  for(int i=0;i<ansarr.size();++i) cout<<ansarr1[i]<<" "<<ansarr[i]<<endl;
}

