	multiset<int> S;
	cin >> N;
	cin >> l >> j >> k;
	B += k;
	S.insert(j);
	auto pos = S.begin();
	int cur = j;
	//同じ値なら左に行く
	int left = 0;
	int right = 0;
	long long int total = 0;
	for(i=1;i<N;++i)
	{
		cin >> l;
		if(l==1)
		{
			cin >> j >> k;
			B += k;
			S.insert(j);
			total += ABS(cur-j);
			if(cur <= j)
				right++;
			else
				left++;

			if(right > left + 1 && pos != S.end())
			{
				pos ++;
				total -= (right-left-1)*(*pos-cur);
				right --;
				left++;
				cur = *pos;
			}
			else if(right < left && pos != S.begin())
			{
				pos--;
				total += (left-right-1)*(cur-*pos);
				right++;
				left--;
				cur=*pos;
			}
		} 
		else
		{
			cout << *pos << " " << total+B << endl;
		}
	}

	return 0;
}

