signed main() {
    int Q; cin >> Q;
    map<int, int> cmp;
    vector<int> q(Q), a(Q), b(Q), p(Q);
    for(int i=0; i<Q; i++) {
        cin >> q[i];
        if(q[i] == 1) {
            cin >> a[i] >> b[i];
            cmp[ a[i] ]++;
        }
    }

    int id = 0;
    vector<int> rev;
    for(auto &e : cmp) rev.push_back(e.first), e.second = id++;
    for(int i=0; i<Q; i++) {
        if(q[i] == 1) {
            p[i] = cmp[ a[i] ];
            // fprintf(stderr, "p = %lld\n", p[i]);
        }
    }

    vector<int> used(id);
    SegmentTree<int, SegFunc> seg1(id, 0), seg2(id, 0);
    int acc = 0, cnt = 0;
    for(int i=0; i<Q; i++) {
        if(q[i] == 1) {
            acc += b[i];
            {
                cnt++;
                seg1.update(p[i], 1   );
                seg2.update(p[i], a[i]);
                used[ p[i] ] = true;
            }
        }
        else {
            int k = 1, sum = 0;
            // fprintf(stderr, "seg1.n = %lld\n", seg1.n);
            while(k < seg1.n) {
                int target = (cnt + 1) / 2;
                //fprintf(stderr, "k = %lld, nl = %lld, nr = %lld\n",
                //        k, seg1.node[2*k], seg1.node[2*k+1]);
                if(seg1.node[2*k] + sum >= target) {
                    k = 2*k;
                }
                else {
                    k = 2*k+1;
                    sum += seg1.node[2*k];
                }
            }
            int idx = k - seg1.n;
            // fprintf(stderr, "idx = %lld\n", idx);
            int al = rev[idx];

            int cl = seg1.query(0, idx);
            int cr = seg1.query(idx+1, id);
            int vl = seg2.query(0, idx);
            int vr = seg2.query(idx+1, id);

            int ar = (cl*al - vl) + (vr - cr*al) + acc;
            printf("%lld %lld\n", al, ar);
        }
    }
    return 0;
}

