#define LC(k)   (k * 2 + 1)
#define RC(k)   (k * 2 + 2)
#define M(l,r)  ((l + r) / 2)

template<typename T> class SegTree2 {
public:
  int n;
  int sz;
  T def;
  vector<T> dat;

  void init(int _n, T _def) {
    n = _n;
    sz = 1; while (sz < n) sz <<= 1;
    sz = sz * 2 - 1;
    def = _def;
    dat.resize(sz, def);
  }

  void update(int a, int b, T x, int k, int l, int r) {
    if (r <= a || b <= l) return;
    if (a <= l && r <= b) {
      dat[k] += x;
      return;
    }
    if (r - l > 1) {
      update(a, b, x, LC(k), l, M(l, r));
      update(a, b, x, RC(k), M(l, r), r);
    }
  }

  void update(int a, int b, T x) {
    update(a, b, x, 0, 0, n);
  }

  T query(int a, int b, int k, int l, int r) {
    T ret = def;
    if (r <= a || b <= l) return ret;
    ret += dat[k];
    if (r - l > 1) {
      ret += query(a, b, LC(k), l, M(l, r));
      ret += query(a, b, RC(k), M(l, r), r);
    }
    return ret;
  }

  T query(int a, int b) {
    return query(a, b, 0, 0, n);
  }

  void dump() {
    REP(i, sz) printf("%d%c", dat[i], i + 1 == sz ? '\n' : ' ');
  }
};

