int a[Q_MAX];
int b[Q_MAX];

int N;
map<int, int> mp;
map<int, int> rmp;

SegTree2<int> st1;
SegTree2<ll> st2;

void compress() {
  mp[INF] = 1;
  mp[-INF] = 1;
  REP(i, Q) if (Query[i] == 1) mp[a[i]] = 1;
  int k = 0;
  ITR(mp, it) {
    it->second = k++;
    rmp[it->second] = it->first;
  }
}

bool C(int x) {
  return st1.query(x, x + 1) >= 0;
}

int bsearch() {
  int lo = 0;
  int hi = N;
  while (hi - lo > 1) {
    int mi = (lo + hi) / 2;
    if (C(mi)) hi = mi;
    else lo = mi;
  }
  return hi;
}

void solve() {
  compress();
  N = mp.size();

  st1.init(N, 0);
  st2.init(N, 0);
  REP(i, Q) {
    if (Query[i] == 1) {
      int ac = mp[a[i]];
      st1.update(0, ac, -1);
      st1.update(ac, N, 1);
      st2.update(0, ac, b[i] + a[i]);
      st2.update(ac, N, b[i] - a[i]);
    } else {
      int xc = bsearch();
      ll x = rmp[xc];
      ll v = st1.query(xc, xc + 1) * x + st2.query(xc, xc + 1);
      printf("%lld %lld\n", x, v);
    }
  }
}

