    //クエリの順番が入れ替わってもいいようにする
    pbds_sum(vi &a) : bco(sz(a) + 3), bsu(sz(a) + 3) {        vi b = a;        b.push_back(-linf - 100);        b.push_back(linf + 100);        i_v = compress(b);        rep(i, sz(a)) { v_i[a[i]] = b[i]; }    }
    pbds_sum(vi &a, vi &b) : bco(sz(a) + sz(b) + 3), bsu(sz(a) + sz(b) + 3) {        vi c = a;        vi d = b;        c.push_back(-linf - 100);        c.push_back(linf + 100);        d.push_back(-linf - 100);        d.push_back(linf + 100);        i_v = compress(c, d);        rep(i, sz(a)) {            v_i[a[i]] = c[i];            v_i[b[i]] = d[i];        }    }
    pbds_sum(vi &a, vi &b, vi &c) : bco(sz(a) + sz(b) + sz(c) + 3), bsu(sz(a) + sz(b) + sz(c) + 3) {        vi d = a;        vi e = b;        vi f = c;        d.push_back(-linf - 100);        d.push_back(linf + 100);        e.push_back(-linf - 100);        e.push_back(linf + 100);        f.push_back(-linf - 100);        f.push_back(linf + 100);        i_v = compress(d, e, f);        rep(i, sz(a)) {            v_i[a[i]] = d[i];            v_i[b[i]] = e[i];            v_i[c[i]] = f[i];        }    }
    void add(int v, int c = 1) {        count += c;        int ind = v_i[v];        bco.add(ind, c);        bsu.add(ind, v * c);    }
    //rv未満の合計
    int sum(int rv) {        int i = (std::lower_bound(all(i_v), rv) - i_v.begin());        return bsu.sum(i);    }
    //半開区間 l rは存在しない値でもいい
    int sum(int l, int r) {        return sum(r) - sum(l);    }
    //圧縮された座標を渡す
    int sum_fast_i(int li, int ri) {        return bsu.sum(ri) - bsu.sum(li);    }
    //rv未満の個数
    int cou(int rv) {        int i = (std::lower_bound(all(i_v), rv) - i_v.begin());        return bco.sum(i);    }
    //半開区間 l rは存在しない値でもいい
    int cou(int l, int r) {        return cou(r) - cou(l);    }
    int find_by_order(int k) {        int i = bco.lower_bound(k + 1);        return i_v[i];    }
    int order_by_key(int v) {        v = *std::lower_bound(all(i_v), v);        int i = v_i[v];        return bco.sum(i);    }
    //中央値を返す 左より)
    int mid() {        return find_by_order((count - 1) >> 1);    }
    //全要素との 最小の差の和をかえす (中央値との差)
    int min_dis() {        int mv = mid();        int mi = v_i[mv];        int lcou = bco.sum(mi);        int rcou = bco.sum(mi + 1, linf);        int lsum = mv * lcou - bsu.sum(mi);        int rsum = bsu.sum(mi + 1, linf) - mv * rcou;        return lsum + rsum;    }
    //存在しない場合マイナスになってしまう
    void erase(int v, int c = 1) {        int ind = v_i[v];        assert(bco[ind] >= c);        count -= c;        bco.add(ind, -c);        bsu.add(ind, v * -c);    }
