    long C{0};
    for(unsigned long i = 0, a, b, c; i < Q; ++i)if(in.scan(c), c == 1) {
        in.scan(a, b);
        pq1.push(a);
        auto t = pq1.top();
        pq1.pop();
        C += b - a + 2 * t;
        pq2.push(t);
        if (pq1.size() < pq2.size()) {
            auto k = pq2.top();
            pq2.pop();
            C -= 2 * k;
            pq1.push(k);
        }
    }else out.print(pq1.top(), ' ', C + (pq1.size() != pq2.size()) * pq1.top(), '\n');
    return 0;
}

