template<class T> class RunningMedian {
 private:
  std::priority_queue<T, std::vector<T>, std::greater<T>> upper;
  std::priority_queue<T, std::vector<T>, std::less<T>> lower;

 public:
  RunningMedian(){
    upper.push(std::numeric_limits<T>::max());
    lower.push (std::numeric_limits<T>::min());
  }
  void push(T val){
    if(val>=upper.top()) upper.push(val);
    else lower.push(val);

    if(upper.size()-lower.size()==2){
      lower.push(upper.top());
      upper.pop();
    } else if(lower.size()-upper.size()==2){
      upper.push(lower.top());
      lower.pop();
    }
  }

  T getMedian() const {
    if(upper.size()==lower.size()) return(upper.top()+lower.top())/((T)2.0);
    else if(upper.size()>lower.size()) return upper.top();
    else return lower.top();
  }
};



int main (void) {

  int Q; std::cin >> Q;

  std::vector<std::pair<long long, long long>> ans; ans.reserve(Q);

  RunningMedian<long long> P;
  std::vector<long long> A; A.reserve(Q);

  long long constant = 0;
  for(int i=0; i<Q; i++) {
    long long c; std::cin >> c;
    if ( c == 1 ) {
      long long a,b; std::cin >> a >> b;
      constant += b;
      P.push(a); A.push_back(a);
    }
    if ( c == 2 ) {
      long long median = P.getMedian();
      std::sort(A.begin(), A.end());
      auto itr_lwr = std::lower_bound(A.begin(), A.end(), median);
      long long ans_x = itr_lwr == A.begin() ? *itr_lwr : *std::prev(itr_lwr);
      long long ans_tmp = 0; for(int i=0; i<A.size(); i++) ans_tmp += std::abs(A[i] - ans_x);
      ans.push_back( { ans_x, ans_tmp+constant} );
    }
  }

  for(int i=0; i<ans.size(); i++) std::cout << ans[i].first << " " << ans[i].second << std::endl;

  return 0;
}

