            int tot = t.t[1];
            int id = it.get(1, 1, n, tot / 2);
            long long res = delta;
            res += t.get(id);
            res += 1ll * val[id] * tx.get(id);
            cout << val[id] << ' ' << res << '\n';
        } else {
