ll get_cnt (int r) {	
	int res = 0;
	while (r >= 0) {
		res += cnt[r];
		r = (r & (r + 1)) - 1;
	}
	return res;
}

ll get_sum (int r) {
	ll res = 0;
	while (r >= 0) {
		res += f[r];
		r = (r & (r + 1)) - 1;
	}
	return res;
}

pair <ll,ll> g(ll x) {
	int pos = lower_bound(every(vl), x) - vl.begin() - 1;
	ll res = 0;

	res += get_cnt(pos) * x - get_sum(pos);
	res += suma - (get_cnt(vl.size()) - get_cnt(pos)) * x - get_sum(pos);
	return mp(res + sumb, x);
}

