int main(){
    ll Q; cin >> Q;
    priority_queue<ll> L;
    priority_queue<ll, vector<ll>, greater<ll>> R;

    ll LSum = 0, RSum = 0, bsum = 0;
    REP(i, Q){
        ll t, a, b; cin >> t;
        if(t == 1){
            cin >> a >> b; bsum += b;
            if(L.empty()){
                L.push(a); LSum += a;
            }
            else if(L.top() < a){
                R.push(a); RSum += a;
            }
            else{
                L.push(a); LSum += a;
            }

            while(L.size() >= R.size()+2){
                ll tmp = L.top(); L.pop(); LSum -= tmp;
                R.push(tmp); RSum += tmp;
            }
            while(L.size()+1 <= R.size()){
                ll tmp = R.top(); R.pop(); RSum -= tmp;
                L.push(tmp); LSum += tmp;
            }
        }
        else{
            ll x = L.top();
            ll ans = bsum;
            ans += x*L.size() - LSum;
            ans += RSum - x*R.size();
            cout << x << " " << ans << endstr;
        }
    }
    return 0;
}

