	for (int i = 0; i < q; i++)
	{
		cin >> t[i];
		if (t[i] == 1) {
			cin >> a[i] >> b[i];
			v.push_back(a[i]);
		}
	}


	//座標圧縮
	sort(t.begin(), t.end());
	t.erase(unique(t.begin(), t.end()), t.end());

	map<ll, ll> mp;
	ll siz = v.size();

	//座標圧縮後の値を保持
	for (ll i = 0; i < siz; i++)
	{
		mp[v[i]] = i+1;//インデックスを割り当てる
	}


	ll B = 0;
	ll add_times = 0;//挿入クエリの回数
	BinaryIndexTree<ll> bitnum(siz);//出現回数
	BinaryIndexTree<ll> bitsum(siz);//累積和


	for (int i = 0; i < q; i++)
	{
