#include <bits/stdc++.h>

using namespace std;

int N;
int Q;
long long BIT[200005][2];
vector<pair<int, int>> qu;
vector<int> cmp;

void upd(int n, long long v, int t){
    for(int i = n; i<=N; i+=i&-i){
        BIT[i][t] += v;
    }
}

int climb(long long n, int t){
    int idx = 0;
    long long s = 0;
    for(int i = 18; i>=0; i--){
        if((1<<i) <= N && s + BIT[(1<<i)+idx][t] < n){
            s += BIT[(1<<i)+idx][t];
            idx += (1<<i);
        }
    }
    return idx+1;
}

long long query(int n, int t){
    long long s = 0;
    for(int i = n; i>0; i-=i&-i){
        s += BIT[i][t];
    }
    return s;
}

int main(){
    cin.sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    cin >> Q;
    while(Q--){
        int c;
        cin >> c;
        if( c== 1){
            int n, m;
            cin >> n >> m;
            qu.push_back({n, m});
            cmp.push_back(n);
        }
        else{
            qu.push_back({INT_MIN, INT_MIN});
        }
    }
    sort(cmp.begin(), cmp.end());
    cmp.erase(unique(cmp.begin(), cmp.end()), cmp.end());
    N = cmp.size();
    int cnt = 0;
    long long C = 0;
    for(auto p : qu){
        if(p.first == INT_MIN){
            int mid = cnt/2+1;
            int idx = climb(mid, 0);
            long long ans = 0;
            ans += query(idx, 0)*cmp[idx-1]-query(idx, 1);
            ans += query(N, 1) - query(idx, 1) - (query(N, 0) - query(idx, 0))*cmp[idx-1];
            cout << cmp[idx-1] << " " << (ans + C) << "\n";
        }
        else{
            cnt++;
            C += p.second;
            int idx = lower_bound(cmp.begin(), cmp.end(), p.first)-cmp.begin()+1;
            upd(idx, 1, 0);
            upd(idx, p.first, 1);
        }
    }
}

