using P = pair<ll, ll>;

int main() {
	int Q;
	cin >> Q;
	vector<P> res;
	ll x = 0, f = 0;
	priority_queue<ll> que1;
	priority_queue<ll, vector<ll>, greater<ll>> que2;
	for (int q = 0; q < Q; ++q) {
		int op;
		cin >> op;
		if (op == 1) {
			ll a, b;
			cin >> a >> b;
			f += b;
			if (que1.empty() || que2.empty()) {
				if (que1.empty()) {
					que1.push(a);
					x = a;
				} else {
					if (que1.top() < a) {
						que2.push(a);
						f += abs(a - x);
					} else {
						que2.push(que1.top());
						que1.pop();
						que1.push(a);
						f += abs(a - x);
						x = a;
					}
				}
			} else {
				if (que1.top() >= a) { que1.push(a); }
				else { que2.push(a); }
				if (que1.size() - que2.size() > 1) {
					que2.push(que1.top());
					que1.pop();
				}
				ll nx = que1.top();
				f += abs(a - nx) + abs(nx - x);
				x = nx;
			}
		} else {
			res.push_back(P(x, f));
		}
	}

	for (int i = 0; i < res.size(); ++i) {
		cout << res[i].first << " " << res[i].second << endl;
	}

	return 0;
}

