struct BinaryIndexedTree
{
    vector<T> dat;

    BinaryIndexedTree(int sz){
        dat.assign(sz+1, 0);
    }

    T sum(int k){
        T res = 0;
        for(k++; k > 0; k -= k & -k) res += dat[k];
        return res;
    }

    void add(int k, T x){
        for(k++; k < dat.size(); k += k & -k) dat[k] += x;
    }
};

