signed main() {
    int Q;
    cin >> Q;
    multiset<int> left, right;
    int middle = -1, leftSum = 0, rightSum = 0, delta = 0;
    pair<int, int> ans;
    auto update = [&](int a, int b) {
        delta += b;
        auto calc = [&]() {
            int mid = middle;
            if (mid == -1) mid = *left.rbegin();
            int temp = mid * (int)left.size() - leftSum;
            temp += rightSum - mid * (int)right.size();
            ans.first = mid;
            ans.second = temp + delta;
        };
        if (middle == -1) {
            if (left.empty() && right.empty()) {
                middle = a;
            } else {
                multiset<int> temp;
                temp.insert(a);
                {
                    // left
                    auto itr = left.end();
                    --itr;
                    temp.insert(*itr);
                    left.erase(itr);
                    leftSum -= *itr;
                }
                {
                    // right
                    auto itr = right.begin();
                    temp.insert(*itr);
                    right.erase(itr);
                    rightSum -= *itr;
                }
                left.insert(*temp.begin());
                leftSum += *temp.begin();
                right.insert(*temp.rbegin());
                rightSum += *temp.rbegin();
                middle = *next(temp.begin(), 1);
            }
            calc();
        } else {
            int down = min(a, middle);
            int up = max(a, middle);
            left.insert(down);
            leftSum += down;
            right.insert(up);
            rightSum += up;
            middle = -1;
            calc();
        }
    };

    for (int i = 0; i < Q; i++) {
        int q;
        cin >> q;
        if (q == 1) {
            int a, b;
            cin >> a >> b;
            update(a, b);
        } else {
            cout << ans.first << " " << ans.second << endl;
        }
    }
}

