int main() {
    int q;
    cin >> q;

    multiset<ll> s;
    ll sb = 0, sa = 0, m = 0, pos = 0;

    while(q--) {
        ll tipo, a, b, dif, des = 0;
        auto idx = s.begin();
        cin >> tipo;
        if(tipo == 1) {
            cin >> a >> b;
            sa += abs(m-a);
            sb += b;


            s.insert(a);
            if(s.size() == 1) {
                idx = s.begin();
                pos = 0;
                m = a;
                sa = 0;
                continue;
            }

            // cout << "idx = " << (int)(idx-s.begin()) << endl;
            // dif = abs(a-m);
            // cout << "oi" << endl;
            if(a >= m) {
                // idx = s.lower_bound(m);
                if(s.size()%2) {
                    idx = next(idx);

                    if(des < 0) {
                        pos++;
                        dif = (*idx)-m;
                        sa += dif*pos;
                        sa -= dif*(ll)(s.size()-pos-1);
                        m = *idx;
                    }
                    else {
                        des = 0;
                    }
                }
                else {
                    des++;
                }

            }
            else {
                // idx = s.lower_bound(m);
                if(s.size()%2) {
                    idx = prev(idx);

                    if(des > 0) {
                        pos--;
                        dif = m-(*idx);
                        sa -= dif*pos;
                        sa += dif*(ll)(s.size()-pos-1);
                        m = *idx;
                    }
                    else {
                        des = 0;
                    }
                }
                else {
                    des--;
                }

            }
            // cout << "foi" << endl;
            // cout << "novo *idx = " << (*idx) << endl;

        }
        else {
            cout << m << " " << sa + sb << endl;
        }

    }


    return 0;
}

