int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int q; cin >> q;
    ll C=0;
    priority_queue<ll> zen;
    priority_queue<ll, vector<ll>, greater<ll>> kou;
    ll zensum=0, kousum=0;

    while(q--){
        int type; cin >> type;
        if(type==1){
            ll a, b; cin >> a >> b; C+=b;
            if(zen.size()>kou.size()){
                ll t=zen.top();
                if(a>=t) kou.push(a), kousum+=a;
                else{
                    zen.pop(); zensum-=t;
                    zen.push(a); zensum+=a;
                    kou.push(t); kousum+=t;
                }
            }
            else{
                if(zen.size()==0) zen.push(a), zensum+=a;
                else{
                    ll t=kou.top();
                    if(a<=t) zen.push(a), zensum+=a;
                    else{
                        kou.pop(); kousum-=t;
                        kou.push(a); kousum+=a;
                        zen.push(t); zensum+=t;
                    }
                }
            }
        }
        else{
            ll x=zen.top();
            cout << x << ' ' << x*(int)zen.size() - zensum + kousum - x*(int)kou.size() + C << endl;
        }
        //cout << zensum << ' ' << kousum << endl;
    }

    return 0;
}

