      if (lhs.size() == rhs.size() + 2) {
        lhs_sum -= lhs.top();
        rhs_sum += lhs.top();

        rhs.push(lhs.top());
        lhs.pop();
      }

      if (!rhs.empty() && lhs.top() > rhs.top()) {
        lhs_sum += rhs.top() - lhs.top();
        rhs_sum += lhs.top() - rhs.top();

        lhs.push(rhs.top()); rhs.pop();
        rhs.push(lhs.top()); lhs.pop();
