      else if (a < L.top()) L.push(a), Ls += a;
      else if (R.empty()) R.push(a), Rs += a;
      else if (a > R.top()) R.push(a), Rs += a;
      else {
        assert(L.top() <= a and a <= R.top());
        L.push(a);
        Ls += a;
      }
      while (L.size() > R.size() + 1) 
        R.push(L.top()), Rs += L.top(), Ls -= L.top(), L.pop();
      while (R.size() > L.size()) 
        L.push(R.top()), Ls += R.top(), Rs -= R.top(), R.pop();
      B += b;
    }
    else {
      LL x = L.top();
      LL ans = x * L.size() - Ls + Rs - x * R.size() + B;
      cout << x << ' ' << ans << '\n';
    }
  }
}

