            sum[i + N - 1] = dat[i];
        }
        for(int i = N - 2 ; i >= 0 ; --i){
            sum[i] = sum[i * 2 + 1] + sum[i * 2 + 2];
        }
        return;
    }

    void update(int k, long long x){
        k += N - 1;
        sum[k] = x;
        while(k > 0){
            k = (k - 1) / 2;
            sum[k] = sum[k * 2 + 1] + sum[k * 2 + 2];
        }
        return;
    }

    void add(int k, long long x){
        update(k, sum[k + N - 1] + x);
        return;
    }

    long long getSum(int a, int b, int k, int l, int r){
        if(r <= a || b <= l){
            return 0LL;
        }
        if(a <= l && r <= b){
            return sum[k];
        }
        long long vl = getSum(a, b, k * 2 + 1, l, (l + r) / 2);
        long long vr = getSum(a, b, k * 2 + 2, (l + r) / 2, r);
        return vl + vr;
    }

    long long getSum(int a, int b){
        return getSum(a, b, 0, 0, N);
    }

    int lower_bound(long long x){
        int left = 0, right = N;
        while(right - left > 1){
            int mid = (left + right) / 2;
            if(getSum(0, mid) < x){
                left = mid;
            }else{
                right = mid;
            }
        }
        return left;
    }
};

template<typename T>
int compress(vector<T> &v, map<T, int> &zip, vector<T> &unzip){
    sort(v.begin(), v.end());
    unzip.resize(v.size());
    for(int i = 0, i_len = (int)v.size() ; i < i_len ; ++i){
        zip[v[i]] = i;
        unzip[i] = v[i];
    }
    return (int)v.size();
}

