    priority_queue<int> lower, upper;
    auto insert = [&](int v) {
        if (lower.empty() || lower.top() >= v) {
            lower.push(v);
            lsum += v;
        }
        else {
            usum += v;
            upper.push(-v);
        }
        while (lower.size() < upper.size()) {
            lsum -= upper.top();
            usum += upper.top();
            lower.push(-upper.top());
            upper.pop();
        }
        while (lower.size() > upper.size() + 1) {
            lsum -= lower.top();
            usum += lower.top();
            upper.push(-lower.top());

            lower.pop();
        }

        if (upper.size())
            assert(lower.top() <= -upper.top());
    };

