				if(qa.size() > qb.size()){
					qb.push(qa.top());
					qa.pop();
					if(!qa.empty()){
						sa -= (qb.top() - qa.top()) * qa.size();
						sb += (qb.top() - qa.top()) * qb.size();
						qa.push(a);
						sa += qa.top() - a;
					}else{
