typedef long long ll;
const ll N = 4e5 + 10;
ll q, A[N], B[N];
long long S[N], T[N];
vector < ll > U;
inline void Add(ll i, long long val, long long * F)
{
    for (i ++; i < N; i += i & -i)
        F[i] += val;
}
inline long long Get(ll i, long long * F)
{
    long long rt = 0;
    for (i ++; i; i -= i & -i)
        rt += F[i];
    return rt;
}
int main()
{
    scanf("%lld", &q);
    for (ll i = 0; i < q; i++)
    {
        ll tp;
        scanf("%lld", &tp);
        if (tp == 1)
            scanf("%lld%lld", &A[i], &B[i]), U.push_back(A[i]);
        else
            A[i] = LLONG_MAX;
    }
    sort(U.begin(), U.end());
    U.resize(unique(U.begin(), U.end()) - U.begin());
    ll n = 0;
    long long sum = 0, suma = 0;
    for (ll i = 0; i < q; i++)
    {
        if (A[i] != LLONG_MAX)
        {
            sum += B[i];
            suma += A[i];
            ll a = lower_bound(U.begin(), U.end(), A[i]) - U.begin();
            Add(a, 1, S);
            Add(a + 1, A[i], T);
            n ++;
        }
        else
        {
            ll le = -1, ri = (ll)U.size(), md;
            while (ri - le > 1)
            {
                md = (le + ri) >> 1;
                if (Get(md, S) >= ((n + 1) >> 1))
                    ri = md;
                else
                    le = md;
            }
            long long res = sum + suma - Get(ri, T) - Get(ri + 1, T);
            if (n % 2 == 0)
                res -= U[ri];
            printf("%lld %lld\n", U[ri], res);
        }
    }
    return 0;
}

