#define down(i, a, b, s) for (int i = (a); (b) < i; i -= (s))

struct _solver {
  long long ls, rs, bs;
  priority_queue<int, vector<int>, less<int>> lhs;
  priority_queue<int, vector<int>, greater<int>> rhs;

  void clear() {
    ls = rs = bs = 0;
    while (!lhs.empty()) lhs.pop();
    while (!rhs.empty()) rhs.pop();
  }

  inline void push_l(int x) {
    lhs.push(x);
    ls += x;
  }

  inline void push_r(int x) {
    rhs.push(x);
    rs += x;
  }

  inline long long pop_l() {
    long long k = lhs.top();
    ls -= k;
    lhs.pop();
    return k;
  }

  inline long long pop_r() {
    long long k = rhs.top();
    rs -= k;
    rhs.pop();
    return k;
  }

  void update(int a, int b) {
    bs += b;
    if (lhs.size() == 0 || lhs.top() >= a) {
      push_l(a);
    } else {
      push_r(a);
    }
    while (lhs.size() > rhs.size() + 1) {
      push_r(pop_l());
    }
    while (rhs.size() > lhs.size() + 1) {
      push_l(pop_r());
    }
  }

  pair<long long, long long> query() {
    long long k = lhs.top();
    long long l = k * (long long)lhs.size() - ls;
    long long r = rs - k * (long long)rhs.size();
    return mp(k, l + r + bs);
  }
} solver;

int q, a, b, c;

int main(int argc, char const *argv[]) {
  // freopen("F.txt", "r", stdin);

  while (cin >> q) {
    solver.clear();
    range(_, 0, q, 1) {
      cin >> c;
      if (c == 1) {
        cin >> a >> b;
        solver.update(a, b);
      } else {
        auto ans = solver.query();
        cout << ans.fi << " " << ans.se << endl;
      }
    }
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
using large = long long;

int main() {
    int nq;
    cin >> nq;

    auto a_left = multiset<int, greater<int>>();
    auto a_right = multiset<int>();
    auto a_cnt = 0;
    auto a_left_sum = 0LL;
    auto a_right_sum = 0LL;
    auto b_sum = 0LL;

    for (int i = 0; i < nq; ++i) {
        large type, a, b;
        cin >> type;

        if (type == 1) {
            cin >> a >> b;
            b_sum += b;
            ++a_cnt;

            if (a_left.empty()) {
                a_left.insert(a);
                a_left_sum += a;
            } else if (a_left.size() == a_right.size()) { // insert to left
                auto largest_left = *a_left.begin();
                if (a < largest_left) {
                    a_left.insert(a);
                    a_left_sum += a;
                } else {
                    auto smallest_right = *a_right.begin();
                    a_right.erase(a_right.begin());
                    a_right_sum -= smallest_right;
                    a_right.insert(a);
                    a_right_sum += a;

                    a_left.insert(smallest_right);
                    a_left_sum += smallest_right;
                }
            } else { // insert to right
                auto largest_left = *a_left.begin();
                if (a >= largest_left) {
                    a_right.insert(a);
                    a_right_sum += a;
                } else {
                    a_left.erase(a_left.begin());
                    a_left_sum -= largest_left;
                    a_left.insert(a);
                    a_left_sum += a;

                    a_right.insert(largest_left);
                    a_right_sum += largest_left;
                }
            }
        } else {
            // SUM( a[i] - a ) ---> SUM( a[i] ) - N*a
            // SUM( a - a[i] ) ---> N*a - SUM( a[i] )

            auto a_mid = *a_left.begin();
            auto left_sum = a_left_sum - ((large)a_left.size() * a_mid);
            auto right_sum = a_right_sum - ((large)a_right.size() * a_mid);
            auto sum = -left_sum + right_sum;

            cout << a_mid << " " << (sum + b_sum) << "\n";
        }
    }

    return 0;
}

