				lmin = a;
			}
			else q.emplace_back(t, a, b);
			tor.push_back(a);
		}
		else q.emplace_back(t, 0, 0);
	}
	tor.push_back(-1001001001);
	sort(tor.begin(), tor.end());
	tor.erase(unique(tor.begin(), tor.end()), tor.end());
	map<int, int> toc;
	for(int i = 0; i < tor.size(); i++) toc[tor[i]] = i;

	BIT<int> bt(tor.size());
	bt.add(0, -1);
	bt.add(toc[lmin], 2);
	for(auto p: q) {
		int t, a, b;
		tie(t, a, b) = p;
