			cout << lmin << ' ' <<  fmin << endl;
			continue;
		}
		bt.add(0, -1);
		bt.add(toc[a], 2);
		int nl;
		{
			int l = -1, r = tor.size();
			while(r - l > 1) {
				int c = (l + r) / 2;
				if (bt.sum(c) >= 0) r = c;
				else l = c;
			}
			nl = tor[r];
