using namespace std;
using ll = long long;
constexpr int inf = 1000000000;
constexpr ll INF = 1000000000000000000;

struct FenwickTree {
    int length;
    vector<ll> node;
    FenwickTree (int N) : length(N), node(length + 1, 0) {}
    void add(int idx, ll val) {
        ++idx;
        while (idx <= length) {
            node[idx] += val;
            idx += (idx & (-idx));
        }
    }
    ll getsum(int idx) {
        ll ans = 0;
        while (idx) {
            ans += node[idx];
            idx -= (idx & (-idx));
        }
        return ans;
    }
    int lowerBound(ll x) {
        int ans = 0;
        int l = 1;
        while ((l << 1) <= length) l <<= 1;
        while (l) {
            if (ans + l <= length) {
                if (node[ans + l] < x) {
                    x -= node[ans + l];
                    ans += l;
                }
            }
            l >>= 1;
        }
        return ans + 1;
    }
};

int main() {
    int Q;
    cin >> Q;
    vector<ll> a(Q, 0), b(Q, INF), c(Q, INF);
    rep(i, Q) {
        cin >> a[i];
        if (a[i] == 1) cin >> b[i] >> c[i];
    }

    vector<ll> S;
    rep(i, Q) {
        if (a[i] == 1) S.push_back(b[i]);
    }
    sort(ALL(S));
    map<ll, int> mp;
    mp[S[0]] = 0;
    REP(i, SZ(S)) {
        if (S[i - 1] == S[i]) continue;
        mp[S[i]] = mp[S[i - 1]] + 1;
    }
    vector<ll> T(Q, 0);
    for (auto p : mp) T[p.second] = p.first;

    int cnt = 0;
    vector<int> C(Q, 0);
    FenwickTree FT1(Q), FT2(Q);
    ll sum = 0;
    rep(i, Q) {
        if (a[i] == 1) {
            sum += b[i] + c[i];
            FT1.add(mp[b[i]], 1);
            FT2.add(mp[b[i]], b[i]);
            ++C[mp[b[i]]];
            ++cnt;
        } else {
            int idx = FT1.lowerBound((cnt + 1) / 2);
            --idx;
            cout << T[idx] << " ";
            cout << sum - FT2.getsum(idx) - T[idx] * cnt << "\n";
        }
    }
}

