struct node {
    node *l, *r;
    ll val, cnt;
    node() {
        val = cnt = 0;
        l = NULL;
        r = NULL;
    }
} *root;


int getmid(int tl, int tr) {
    int t1, t2;
    t1 = tl + pls;
    t2 = tr + pls;
    return (((t1 + t2) / 2) - pls);
}


ll getval(node *&v) {
    if (!v) return 0ll;
    return v->val;
}


ll getcnt(node *&v) {
    if (!v) return 0ll;
    return v->cnt;
}


void upd(node *&v, int tl, int tr, ll pos) {
    if (!v)
        v = new node();
    if (tl == tr) {
        v->val += pos;
        v->cnt++;
        return;
    }
    int tm = getmid(tl, tr);
    if (pos <= tm)
        upd(v->l, tl, tm, pos);
    else
        upd(v->r, tm + 1, tr, pos);
    v->val = getval(v->l) + getval(v->r);
    v->cnt = getcnt(v->l) + getcnt(v->r);
}


pll get(node *&v, int tl, int tr, int l, int r) {
    if (!v || r < tl || tr < l)
        return {0, 0};
    int tm = getmid(tl, tr);
    if (l <= tl && tr <= r)
        return {v->val, v->cnt};
    pll t1, t2;
    t1 = get(v->l, tl, tm, l, r);
    t2 = get(v->r, tm + 1, tr, l, r);
    return {t1.f + t2.f, t1.se + t2.se};
}


ll cnt = 0, cb = 0, sm = 0, tp, a, b;
int L, R, M;


ll getv(ll x) {
    pll t1 = get(root, -inff, inff, -inff, x);
    // cout << x << " " << t1.f << " " << t1.se << "\n";
    pll t2 = {sm - t1.f, cnt - t1.se};
    return x * t1.se - t1.f + t2.f - x * t2.se + cb;
}


