            R = inff;
            pll ans = {inf, inf};
            while (L <= R) {
                M = getmid(L, R);
                ans = min(ans, {getv(M), M});
                if (getv(M) <= getv(M + 1))
                    R = M - 1;
                else
                    L = M + 1;
