	ll q; cin >> q;
	vector<tuple<ll,ll,ll>> vs(q);
	map<ll,ll> a2idx;
	vl idx2a;
	{
		set<ll> zatu;
		ll sum = 0, cnt = 0;
		REP(i, q) {
			ll t; cin >> t;
			if (t == 1) {
				ll a, b; cin >> a >> b;
				zatu.insert(a);
				vs[i] = make_tuple(1, a, b);
			} else {
				vs[i] = make_tuple(2, 0, 0);
			}
		}
		ll idx = 0;
		for(ll a : zatu)  {
			a2idx[a] = idx++;
			idx2a.push_back(a);
		}
	}

	ll constant = 0, cnt = 0;
	SegTree<SumTrait<ll>> st(a2idx.size()), stcnt(a2idx.size());
	set<ll> cur;
	REP(i, q) {
		if (get<0>(vs[i]) == 1) {
			ll a = get<1>(vs[i]);
			constant += get<2>(vs[i]);
			cnt++;

			ll idx = a2idx[a];
			cur.insert(idx);
			st.set(idx, st[idx] + a);
			stcnt.set(idx, stcnt[idx] + 1);
		} else {
			ll idx = bsearch(0, a2idx.size(), [&](ll idx) {
				return stcnt.get(0, idx + 1) <= cnt / 2 + cnt % 2;
			});
			idx = *--cur.upper_bound(idx);
			ll a = idx2a[idx];
			ll ans = a * stcnt.get(0, idx) - st.get(0, idx); // left
			ans += st.get(idx + 1, a2idx.size()) - a * stcnt.get(idx + 1, a2idx.size()); // right
