constexpr ll inf = 2e18;
int q, o, a, b;

ll off, cen = inf;
multiset<ll> low, upp;
ll poplow() {
	if (low.empty())
		return 0;
	multiset<ll>::iterator ite;

	ite = low.end();
	ite--;

	ll r = *ite;
	low.erase(ite);
	if (low.empty())
		return r;

	ite = low.end();
	ite--;

	off -= (r - *ite) * low.size();
	return r;
}
ll popupp() {
	if (upp.empty())
		return 0;
	multiset<ll>::iterator ite;

	ite = upp.begin();

	ll r = *ite;
	upp.erase(ite);
	if (upp.empty())
		return r;

	ite = upp.begin();

	off -= (*ite - r) * upp.size();
	return r;
}
void pushlow(ll a) {
	if (!low.empty() && a <= *low.rbegin())
		off += *low.rbegin() - a;
	else if (!low.empty())
			off += a - *low.rbegin();
	low.emplace(a);
}
void pushupp(ll a) {
	if (!upp.empty() && *upp.begin() <= a)
		off += a - *upp.begin();
	else if (!upp.empty())
		off += *upp.begin() - a;
	upp.emplace(a);
}
void push(ll a) {
	if (!low.empty() && a <= *low.rbegin()) {
		pushlow(a);
		pushlow(a);
		pushupp(poplow());
	}
	else {
		pushupp(a);
		pushupp(a);
		pushlow(popupp());
	}
}
