int main(void){
  int q;
  std::cin >> q;

  std::multiset<llint> lower;
  std::multiset<llint> upper;
  llint center = 1e12;

  llint a_distance = 0;
  llint b_total = 0;
  for(int i=0; i<q; i++){
    llint patt;
    std::cin >> patt;
    if(patt==1){
      llint a, b;
      std::cin >> a >> b;
      b_total+=b;

      if(center==1e12){
	center = a;
      }else if(center < a){
	a_distance += a-center;
	upper.insert(a);
      }else{
	a_distance += center-a;
	lower.insert(a);
      }


      if(upper.size() > lower.size() + 1){
	llint prev_center = center;
	lower.insert(center);
	center = *(upper.begin());
	upper.erase(upper.begin());
	a_distance += (center-prev_center)*(lower.size() - 1 - upper.size());
      }else if(upper.size() < lower.size()){
	llint prev_center = center;
	upper.insert(center);
	center = *(lower.rbegin());
	lower.erase(std::prev(lower.end()));
	a_distance += (prev_center-center)*(upper.size()+1 - lower.size());
      }

    }else{
      // output
      std::cout << center << " " << a_distance+b_total << std::endl;
    }

  }
  return 0;

}

