using namespace std;
using ULL = unsigned long long;
using UL = unsigned;
using LL = long long;
#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {

	void Solve(){
		UL Q; cin >> Q;
		multiset<LL> Al, Ar;
		Al.insert(-10000000000);
		Ar.insert(10000000000);
		LL B = 0;
		rep(i, Q) {
			UL c; cin >> c;
			if (c == 1) {
				LL a, b; cin >> a >> b;
				B += b;
				if (Al.size() == Ar.size()) {
					LL m = *--Al.end();
					if (a <= m) {
						B += m - a;
						Al.insert(a);
					}
					else if (a <= *Ar.begin()) {
						Al.insert(a);
					}
					else {
						Ar.insert(a);
						LL nm = *Ar.begin();
						B += a - nm;
						Al.insert(nm);
						Ar.erase(Ar.begin());
					}
				}
				else {
					LL m = *--Al.end();
					if (a <= m) {
						B += m - a;
						Al.insert(a);
						Ar.insert(max(a, m));
						Al.erase(--Al.end());
					}
					else {
						Ar.insert(a);
						B += a - m;
					}
				}
			}
			else if (c == 2) {
				cout << (*--Al.end()) << " " << B << endl;
			}
		}
	}


	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
