				int to = it->first;
				int tlow = low;
				tlow += (to - now) * bit.sum(map[to]);
				tlow -= (to - now) * bit.sum(map[to], sz + 1);
				if (low > tlow) {
					now = to;
					low = tlow;
				}
			}();
			[&]{
				auto it = std::prev(map.lower_bound(now));
				if (it == map.end()) return;
				int to = it->first;
				int tlow = low;
				tlow += (to - now) * bit.sum(map[to] + 1);
				tlow -= (to - now) * bit.sum(map[to] + 1, sz + 1);
				if (low >= tlow) {
					now = to;
					low = tlow;
				}
			}();
		}
		else {
			OUT(now)SP OUT(low + sum)BR;
		}
	}

	return 0;
}

