#define ll long long
const int maxn = 200000 + 5;
ll tot, t, k; // 1 ~ tot
ll ch[maxn][2], key[maxn], pri[maxn], sz[maxn], h[maxn];
void update(ll u) {
	sz[u] = sz[ch[u][0]] + sz[ch[u][1]] + 1;
	h[u] = h[ch[u][0]]+h[ch[u][1]];
}
void rotate(ll &u, ll d /* 0 or 1 */) {
	ll v = ch[u][d^1];
	ch[u][d^1] = ch[v][d];
	ch[v][d] = u;
	update(u);
	update(v);
	u = v;
}
void insert(ll &u, ll k) {
	if (u == 0) {
		u = ++tot;
		key[u] = k, pri[u] = rand(), sz[u]=1, h[u]=k;
		return;
	}
	int d = (k > key[u]);
	insert(ch[u][d], k);
	update(u); 
	if (pri[ch[u][d]] < pri[u]) rotate(u, d ^ 1);
}
void erase(ll &u,ll x) {
	if (u == 0) return;
	if (key[u] == x) {
		if (!ch[u][0]) u = ch[u][1];
		else if (!ch[u][1]) u = ch[u][0];
		else {
			int d = (pri[ch[u][0]] < pri[ch[u][1]]);
			rotate(u, d);
			erase(ch[u][d], x);
		}
	} else {
		int d = (x > key[u]);
		erase(ch[u][d], x);
	}
	if (u) update(u);
}
int Rank(ll u,ll x) {
	if(!u) return 0;
	if(x <= key[u]) return Rank(ch[u][0],x);
	else return sz[ch[u][0]] + 1 + Rank(ch[u][1],x);
}
int zhui(ll u, ll x){
	if(!u) return 0;
	if (x == sz[ch[u][0]] + 1) return h[ch[u][0]];
	else if (x <= sz[ch[u][0]]) return zhui(ch[u][0], x);
	else return h[ch[u][0]]+zhui(ch[u][1], x - sz[ch[u][0]] - 1);
}
int select(ll u,ll x) {
	if (x == sz[ch[u][0]] + 1) return key[u];
	else if (x <= sz[ch[u][0]]) return select(ch[u][0], x);
	else return select(ch[u][1], x - sz[ch[u][0]] - 1);
}
void dfs(ll u) {
	if (ch[u][0]) dfs(ch[u][0]);
	//cout << key[u] << " ";
	if (ch[u][1]) dfs(ch[u][1]);
}
