template<typename T> struct BIT {
	vector<T> bit;
	int n;

	BIT() {}
	BIT(int n) : bit(vector<T>(n + 2, 0)), n(n) {}

	T sum(int i) {
		i++;
		T s = 0;
		while (i > 0) {
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}

	void add(int i, T x) {
		i++;
		while (i <= n) {
			bit[i] += x;
			i += i & -i;
		}
	}

	T pquery(int i) {
		return sum(i) - sum(i - 1);
	}

	int lower_bound(T x) {
		int l = -1, r = bit.size();
		while (r - l > 1) {
			int m = (l + r) / 2;

			if (sum(m) >= x) r = m;
			else l = m;
		}
		if (r == bit.size()) r = -1;

		return r;
	}
};

