ll a_left_sum = 0;
ll a_right_sum = 0;
priority_queue<ll> a_left, a_right;
ll a_left_size = 0;
ll a_right_size = 0;
ll a_ans = 0;
ll a_num = 0;

void update(ll a){
  a_left.push(a);
  a_left_sum += a;
  ll a_left_cand = a_left.top(); a_left.pop();
  a_left_sum -= a_left_cand;

  a_right.push(-a_left_cand);
  a_right_sum += a_left_cand;
  ll a_cand_right = -a_right.top(); a_right.pop();
  a_right_sum -= a_cand_right;

  if(a_num==0){
    a_ans = a;
  }else{
    if(a_left.size()==a_right.size()){
      ll a_cand = max(a_ans, a_cand_right);
      a_ans = min(a_ans, a_cand_right);
      a_right.push(-a_cand);
      a_right_sum += a_cand;
      a_right_size++;
    }else{
      ll a_cand = min(a_ans, a_cand_right);
      a_ans = max(a_ans, a_cand_right);
      a_left.push(a_cand);
      a_left_sum += a_cand;
      a_left_size++;
    }
  }

  return;
}

