ll l,r,B;

void insert(int x){
	if(Maxheap.empty()) {
		Maxheap.push(x);
		l+=x;
	}
	else {
		if(x<=Maxheap.top()){
			Maxheap.push(x);
			l+=x;
			if((int)Maxheap.size()-(int)Minheap.size()>=2){
				int t=Maxheap.top();
				Maxheap.pop();
				Minheap.push(t);
				l-=t;
				r+=t; 
			}
		}
		else {
			Minheap.push(x);
			r+=x;
			if(Minheap.size()>Maxheap.size()){
				int t=Minheap.top();
				Minheap.pop();
				Maxheap.push(t);
				l+=t;
				r-=t;
			}
		}
	}
} 

