		ll a, b; scanf("%lld%lld", &a, &b);
		if(ii%2){
			// DEBUG("Here mi=%d\n", mi.size());
			auto x1 = mi.end(); x1--;
			// DEBUG("There\n");
			auto x2 = mx.begin();
			if(a < *x1){
				x = *x1;
				mi.erase(x1);
				mi.insert(a);
			} else if(a > *x2){
				x = *x2;
				mx.erase(x2);
				mx.insert(a);
			} else {
				x = a;
			}
