int q,opt,x,y;
ll sum1,sum2,sum;
int main()
{
    scanf("%d",&q);
    while(q--)
    {
        scanf("%d",&opt);
        if(opt==1)
        {
            scanf("%d%d",&x,&y);
            sum+=y;
