#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int LOG = 29, ADD = 1e9 + 100, N = ADD << 1;

struct fenwick {
	unordered_map<int, ll> cnt, sum;
	void add(ll x) {
		ll val = (x += ADD);
		for (; x < N; x += x & -x)
			cnt[x]++, sum[x] += val;
	}
	int get(int dex) { // 1 2 3 ...
		ll now = 0;
		for (int i = LOG; ~i; i--)
			if(cnt[now + (1 << i)] < dex)
				dex -= cnt[now += 1 << i];
		return now + 1 - ADD;
	}
	int GET(int dex) { // 1 2 3 ...
		ll res = 0, now = 0;
		for (int i = LOG; ~i; i--)
			if(cnt[now + (1 << i)] < dex) {
				dex -= cnt[now += 1 << i];
				res += sum[now];
			}
		return res + (now + 1 - ADD) * dex;
	}
} CNT;

ll q, type, a, b, cnt, s, to_add;

int main() {
	ios::sync_with_stdio(false), cin.tie(0);
	cin >> q;
	while(q--) {
		cin >> type;
		if(type == 1) {
			cin >> a >> b;
			CNT.add(a);
			s += a;
			to_add += b;
			cnt++;
		}
		else {
			int dex = (cnt - 1) / 2 + 1;
			ll x = CNT.get(dex);
			cout << x << ' ' << to_add + (2 * (dex - 1) - cnt) * x + s - 2 * CNT.GET(dex - 1) << '\n';
		}
	}
	return 0;
}

#include<cstdio>
#include<set>

int main() {
	int q;
	scanf("%d", &q);
	long long b_sum = 0;
	int n = 0;
	std::multiset<int> l, r;
	long long l_sum = 0, r_sum = 0;
	int median = 0;
	for(int i=0;i<q;i++) {
		int t;
		scanf("%d", &t);
		if(t == 1) {
			int a, b;
			scanf("%d %d", &a, &b);
			b_sum += b;
			if(n % 2 == 0) {
				if(median < a) {
					r.insert(a);
					r_sum += a;
					auto it = r.begin();
					median = *it;
					r.erase(it);
					r_sum -= median;
				} else {
					l.insert(a);
					l_sum += a;
					auto it = l.rbegin();
					median = *it;
					l.erase((++it).base());
					l_sum -= median;
				}
			} else {
				if(median < a) {
					l.insert(median);
					l_sum += median;
					r.insert(a);
					r_sum += a;
				} else {
					l.insert(a);
					l_sum += a;
					r.insert(median);
					r_sum += median;
					median = *(l.rbegin());
				}
			}
			n++;
		} else {
			printf("%d %lld\n", median, r_sum - l_sum + b_sum);
		}
	}
	return 0;
}

