	int q; cin >> q;
	ll Y = 0;
	ll L = 0;
	ll R = 0;
	priority_queue<ll> Max;
	priority_queue<ll, vector<ll>, greater<ll>> Min;
	while (q--) {
		int z; cin >> z;
		if (z == 1) {
			ll x, y; cin >> x >> y;
			Y += y;
			if (Max.size() <= Min.size()) {
				Max.push(x);
				L += x;
			}
			else {
				Min.push(x);
				R += x;
			}
			if (!Max.empty() && !Min.empty() && Max.top() > Min.top()) {
				ll tmp = Max.top();  Max.pop();
				ll tmp1 = Min.top(); Min.pop();
				L = L - tmp + tmp1;
				R = R - tmp1 + tmp;
				Min.push(tmp); Max.push(tmp1);
			}
		}
		else {
			ll SSum = Y + (Max.top() * Max.size()) - L + R - (Min.size() * Max.top());
			cout << Max.top() << ' ' << SSum << '\n';
		}
	}
}

