using namespace std;

struct node_t{
    int weight;
    node_t *l;
    node_t *r;
    long long sum;

    node_t(int weight,node_t *l,node_t *r,long long sum = 0){
        this->weight = weight;
        this->l = l;
        this->r = r;
        this->sum = sum;
    }
}*nill,*aint;

void add(node_t *root,int l,int r,int pos){
    if(r < pos || l > pos){
        return ;
    }

    if(l == r){
        root->weight++;
        root->sum += pos;
        return ;
    }

    int mid = (l + r) / 2;

    if(root->l == nill){
        root->l = new node_t(0,nill,nill);
    }

    if(root->r == nill){
        root->r = new node_t(0,nill,nill);
    }

    add(root->l,l,mid,pos);
    add(root->r,mid + 1,r,pos);

    root->weight = root->l->weight + root->r->weight;
    root->sum = root->l->sum + root->r->sum;
}

long long offset = 0;

pair<int,long long> get_elem(node_t *root,int l,int r,int pos){
    if(l == r){
        return {l,offset};
    }

    int mid = (l + r) / 2;

    if(root->l->weight < pos){
        pos -= root->l->weight;
        auto tmp = get_elem(root->r,mid + 1,r,pos);
        tmp.second = tmp.second + 1LL * root->l->weight * tmp.first - root->l->sum;
        return tmp;
    }
    else{
        auto tmp = get_elem(root->l,l,mid,pos);
        tmp.second = tmp.second - 1LL * root->r->weight * tmp.first + root->r->sum;
        return tmp;
    }
}

int q;

int main(){
    nill = new node_t(0,NULL,NULL);
    aint = new node_t(0,nill,nill);

    scanf("%d",&q);

    while(q--){
        int t;
        scanf("%d",&t);

        if(t == 1){
            int a,b;
            scanf("%d %d",&a,&b);
            offset += b;
            add(aint,-1e9,1e9,a);
        }
        else{
            auto tmp = get_elem(aint,-1e9,1e9,(1 + aint->weight) / 2);
            printf("%d %lld\n",tmp.first,tmp.second);
        }
    }

    return 0;
}

