void solve(){
    vl ts(q), as(q), bs(q);
    rep(i, q){
        in1(ts[i]);
        if (ts[i] == 1) in2(as[i], bs[i]);
    }

    vl vs(as);
    vs.pb(-MOD); vs.pb(MOD);
    vs = compress(vs);
    mll d = dict(vs);

    BIT bit_for_idx(vs.size() + 1);
    BIT bit_for_loc(vs.size() + 1);

    ll b_tot = 0, num = 0;
    rep(i, q){
        if (ts[i] == 1){
            bit_for_idx.update(d[as[i]], 1);
            bit_for_loc.update(d[as[i]], as[i]);
            b_tot += bs[i]; num++;
        }else{
            ll lb = bit_for_idx.lower_bound((num + 1) / 2);
            ll med = vs[lb];
            ll upper_tot = bit_for_loc.query(vs.size() - 1) - bit_for_loc.query(lb);
            ll n_upper = bit_for_idx.query(vs.size() - 1) - bit_for_idx.query(lb);
            ll lower_tot = bit_for_loc.query(lb - 1);
            ll n_lower = bit_for_idx.query(lb - 1);
            ll fm = upper_tot - med * n_upper - (lower_tot - med * n_lower);
            prl2(med, b_tot + fm);
        }
    }

    // check negative MOD
    // check index flow
    // check overwrite of the input variables
}

