    cin >> Q;
    priority_queue<ll> p;
    priority_queue<ll,vector<ll>,greater<ll>> q;
    ll sum_p=0,sum_q=0;
    ll c=0;
    ll i=0;
    while(Q--){
        ll k;
        cin >> k;
        if(k==1){
            ll a,b;
            cin >> a >> b;
            c+=b;
            if(p.empty()){
                p.push(a);
                sum_p+=a;
                continue;
            }
            if(q.empty()){
                ll x=p.top();
                if(x<=a){
                    q.push(a);
                    sum_q+=a;
                }
                else{
                    p.pop();
                    sum_p-=x;
                    p.push(a);
                    sum_p+=a;
                    q.push(x);
                    sum_q+=x;
                }
                continue;
