            ll x=p.top();
            if(p.size()==q.size()){
                if(a<=x){
                    p.push(a);
                    sum_p+=a;
                }
                else{
                    q.push(a);
                    sum_q+=a;
                    ll y=q.top();
                    q.pop();
                    sum_q-=y;
                    p.push(y);
