//	cnt サイズの x の配列から k 番目の大きな値を返す
//	x の値をモリモリ変更するので注意
int FindMean_K(int* x, int cnt, int k){
	//	quick-sort っぽいの
	int top= cnt, i= 1;
	while(i<top) if( *x < x[i] ) std::swap( x[i], x[--top] ); else i++;
	if( --i== k ) return *x;
	std::swap( *x, x[i] );
	return k < i ? FindMean_K( x, i, k ) : FindMean_K( x+i+1, cnt-i-1, k-i-1 );
}
