void printMedians(ll arr[], ll B[], bool P[],int n) {
    priority_queue<ll> s;
    priority_queue<ll, vector<ll>, greater<ll> > g;
    set<int> st;
    ll medl = arr[0], medr = arr[0], sum = B[0];
    s.push(arr[0]);
    st.insert(arr[0]);
    for (int i = 1; i < n; i++) {
        if(P[i])cout << medl << " " << sum << endl;
        ll x = arr[i];
        ll mi_t = *st.begin(), mx_t = *st.rbegin(),medl_t = medl, medr_t = medr;

        if (s.size() > g.size()) {
            if (x <= (medl + medr)/2) {
                g.push(s.top());
                s.pop();
                s.push(x);
            } else
                g.push(x);

            medl = min(s.top(),g.top()),medr = max(s.top(), g.top());
        }

            // case2(both heaps are balanced)
        else if (s.size() == g.size()) {
            if (x < (medl + medr)/2) {
                s.push(x);
                medl = medr = (ll) s.top();
            } else {
                g.push(x);
                medl = medr = (ll) g.top();
            }
        }

            // case3(right side heap has more elements)
        else {
            if (x > (medl + medr)/2) {
                s.push(g.top());
                g.pop();
                g.push(x);
            } else
                s.push(x);

            medl = min(s.top(),g.top()),medr = max(s.top(), g.top());
        }
        if(i&1){
            x += min(abs(x-medl), abs(x-medr));
//            if(x >= medr)sum += abs(x - medl);if(x <=medl)sum += abs(x - medr);
        }
        else sum += medr - medl;
        sum += B[i];
        st.insert(x);
    }

}

