int main (int argc, char **argv) {
  int q;
  std::cin >> q;

  int opt;
  ll a, b;
  ll sum_b = 0, sum_max = 0, sum_min = 0;
  for (int i=1; i <= q; i++) {
    std::cin >> opt;
    if (opt == 1) {
      std::cin >> a >> b;
      sum_b += b;

      if (max_qq.size() > min_qq.size()) {
        if (a >= max_qq.top()) {
          min_qq.push(a);
          sum_min += a;
        } else {
          int tmp = max_qq.top();
          max_qq.pop();
          sum_max -= tmp;

          min_qq.push(tmp);
          sum_min += tmp;

          max_qq.push(a);
          sum_max += a;
        }

      } else if (max_qq.size() < min_qq.size()) {
        if (a <= min_qq.top()) {
          max_qq.push(a);
          sum_max += a;
        } else {
          int tmp = min_qq.top();
          min_qq.pop();
          sum_min -= tmp;

          max_qq.push(tmp);
          sum_max += tmp;

          min_qq.push(a);
          sum_min += a;
        }

      } else {
        min_qq.push(a);
        sum_min += a;
      }

    } else if (opt == 2) {
