                    int newmid = high.top();
                    low_s += lsize * (newmid - mid) + newmid - mid;
                    low.push(mid);
                    high_s -= (hsize-1) * (newmid - mid);
                    high_s -= newmid - mid;
                    high.pop();
                    mid = newmid;
                }
            }
            else
            {
                int bsize = low.size();
                int hsize = high.size();
                low.push(a);
                low_s += mid - a;
                if(low.size() <= high.size()) continue;
                int newmid = low.top();
                low_s -= bsize * (mid - newmid);
                high.push(mid);
                mid = newmid;
                low.pop();
                high_s += hsize * (mid - newmid);
                high_s += mid - newmid;
            }
        }
    }
}

