using namespace std;

priority_queue<lld, vector <lld>, greater <lld> > heap_min;
priority_queue<lld, vector <lld>, less    <lld> > heap_max;
int q;
int l_min, l_max;
lld t_min, t_max;
lld a_sum, b_sum;
lld s_min, s_max;
lld result, xmin;

void setvaA(lld x)
{
    heap_max.push(x);
    s_max += x;
}

void setvaI(lld x)
{
    heap_min.push(x);
    s_min += x;
}

void popvaA(lld x)
{
    heap_max.pop();
    s_max -= x;
}

void popvaI(lld x)
{
    heap_min.pop();
    s_min -= x;
}

void prepare()
{
    l_min = heap_min.size();
    l_max = heap_max.size();
}

void update(lld x, lld y)
{
    b_sum += y;
    prepare();
    if      (l_min == 0 && l_max == 0) setvaA(x);
    else if (l_min == 0 && l_max != 0) setvaI(x);
    else
    {
        t_min = heap_min.top();
        t_max = heap_max.top();
        if      (x >  t_max)               setvaI(x);
        else if (x <  t_min)               setvaA(x);
        else if (x == t_min && x == t_max) setvaA(x);
    }
}

void impartial()
{
    t_min = heap_min.top();
    t_max = heap_max.top();
    if (t_max > t_min)
    {
        popvaA(t_max);
        popvaI(t_min);
        setvaA(t_min);
        setvaI(t_max);
    }
}

void equitable()
{
    while (heap_max.size() > heap_min.size())
    {
        t_max = heap_max.top();
        popvaA(t_max);
        setvaI(t_max);
    }
    while (heap_max.size() < heap_min.size())
    {
        t_min = heap_min.top();
        popvaI(t_min);
        setvaA(t_min);
    }
}

void ketqua()
{
    if (heap_max.size() >= 1)
    {
        lld temp = heap_max.top();
        if (l_min == l_max)
            temp = b_sum + (s_min - s_max);
        else if (l_max = l_min + 1)
            temp = b_sum + (s_min - s_max + temp);

        result = temp;
        xmin   = heap_max.top();
    }
}

void solve()
{
    cin >> q;
    for (int i = 1; i <= q; i++)
    {
        int query;
        cin >> query;
        if (query == 1)
        {
            lld a, b;
            cin >> a >> b;
            update(a, b);
            prepare();
            if (l_min + l_max == 2)     impartial();
            else if (l_min + l_max > 2) equitable();
        }
        else
        {
            prepare();
            ketqua();
            cout << xmin << ' ' << result << '\n';
        }
    }
}

