struct medianset {
	std::multiset<long long> left;
	std::multiset<long long> right;
	long long left_sum;
	long long right_sum;

	medianset() {left_sum = right_sum = 0;}

	void balance() {
		if (left.size() == right.size() + 2) {
			right.insert(*left.rbegin());
			left.erase(--left.end());
			right_sum += *right.begin();
			left_sum -= *right.begin();
		}
		if (left.size() + 1 == right.size()) {
			left.insert(*right.begin());
			right.erase(right.begin());
			left_sum += *left.rbegin();
			right_sum -= *left.rbegin();;
		}
	}

	void insert(long long x) {
		if (left.empty()) {
			left.insert(x);
			left_sum += x;
			return;
		}
		if (x <= *left.rbegin()) {
			left.insert(x);
			left_sum += x;
		} else {
			right.insert(x);
			right_sum += x;
		}
		balance();
	}

	// return false : erasure failed
	bool erase(long long x) {
		auto itr1 = left.end();
		auto itr2 = right.end();
		if (x <= *left.rbegin()) itr1 = left.find(x);
		if (*right.begin() <= x) itr2 = right.find(x);
		if (itr2 != right.end()) {
			right.erase(itr2);
			right_sum -= x;
		} else if (itr1 != left.end()) {
			left.erase(itr1);
			left_sum -= x;
		}
		else return false;
		balance();
		return true;
	}

	std::pair<long long, long long> get_median() {
		assert(left.size());
		if (left.size() == right.size()) return {*left.rbegin(), *right.begin()};
		else return {*left.rbegin(), *left.rbegin()};
	}
};

int main() {
	long long q;
	std::cin >> q;
	medianset st;
	long long sum = 0;
	while (q--) {
		long long x;
		std::cin >> x;
		if (x == 1) {
			long long a, b;
			std::cin >> a >> b;
			st.insert(a);
			sum += b;
		} else {
			x = st.get_median().first;
			std::cout << x << ' ';
			std::cout << x * (long long)st.left.size() - st.left_sum + st.right_sum - x * (long long)st.right.size() + sum << '\n';
		}
	}
}

