#define KI_MAX (1 << 18) /* 262144 */

int count_ki[KI_MAX * 2 - 1];
int64_t sum_ki[KI_MAX * 2 - 1];

void add_count(int idx, int delta) {
	int pos = (KI_MAX - 1) + idx;
	count_ki[pos] += delta;
	while (pos > 0) {
		pos = (pos - 1) / 2;
		count_ki[pos] += delta;
	}
}

int get_count_i(int idx, int qmin, int qmax, int smin, int smax) {
	if (qmax <= smin || smax <= qmin) { /* クエリがセグメントから完全に外れている */
		return 0;
	} else if (qmin <= smin && smax <= qmax) { /* セグメントがクエリに完全に含まれる */
		return count_ki[idx];
	} else {
		int smid = smin + (smax - smin) / 2;
		int left = get_count_i(idx * 2 + 1, qmin, qmax, smin, smid);
		int right = get_count_i(idx * 2 + 2, qmin, qmax, smid, smax);
		return left + right;
	}
}

int get_count(int min, int max) {
	return min >= max ? 0 : get_count_i(0, min, max, 0, KI_MAX);
}

void add_sum(int idx, int64_t delta) {
	int pos = (KI_MAX - 1) + idx;
	sum_ki[pos] += delta;
	while (pos > 0) {
		pos = (pos - 1) / 2;
		sum_ki[pos] += delta;
	}
}

int64_t get_sum_i(int idx, int qmin, int qmax, int smin, int smax) {
	if (qmax <= smin || smax <= qmin) { /* クエリがセグメントから完全に外れている */
		return 0;
	} else if (qmin <= smin && smax <= qmax) { /* セグメントがクエリに完全に含まれる */
		return sum_ki[idx];
	} else {
		int smid = smin + (smax - smin) / 2;
		int64_t left = get_sum_i(idx * 2 + 1, qmin, qmax, smin, smid);
		int64_t right = get_sum_i(idx * 2 + 2, qmin, qmax, smid, smax);
		return left + right;
	}
}

int64_t get_sum(int min, int max) {
	return min >= max ? 0 : get_sum_i(0, min, max, 0, KI_MAX);
}

int hikaku(const void* x, const void* y) {
	int a = *(const int*)x, b = *(const int*)y;
	return a < b ? -1 : a > b;
}

