int qsort_int(const void *a, const void *b)
{
    return *(int *)a - *(int *)b;
}

int solve(int a_len, int a[])
{
    long long sum, min;
    int i;
    int min_x;

    qsort(a, a_len, sizeof(int), qsort_int);

    for (i = 0; i < a_len; i++) {
        sum += a[i];
    }
    sum -= (long long) a[0] * a_len;

    min = sum;
    min_x = a[0];
    for (i = 1; i < a_len; i++) {
        if (a[i] == a[i - 1]) {continue;}
        sum += (long long) (a[i] - a[i - 1]) * i;
        sum -= (long long) (a[i] - a[i - 1]) * (a_len - i);

        if (sum < min) {
            min = sum;
            min_x = a[i];
        }
    }

    return(min_x);
}

int main(int argc, char *argv[])
{
    int n;
    int query;
    int a_len;
    int a[200000];
    int b;
    int i, j;
    int x;
    long long b_sum;
    long long sum;
    int ans;

    scanf("%d", &n);

    a_len = 0;
    b_sum = 0;
    for (i = 0; i < n; i++) {
        scanf("%d", &query);
        if (query == 1) {
            scanf("%d %d", &a[a_len++], &b);
            b_sum += b;
        } else if (query == 2) {
            x = solve(a_len, a);
            sum = b_sum;
            for (j = 0; j < a_len; j++) {
                sum += abs(x - a[j]);
            }
            printf("%d %lld\n", x, sum);
        } else {
            printf("syntax error.\n");
            exit(1);
        }
    }

    return 0;
}

