long long sselect(long long a[],int n,int k){
	int l,r=n-1;
	for(l=0;l<=r;){
		long long p=a[(l+r)/2];
		int i=l-1,j=r+1;
		while(1){
			while(a[++i]<p);
			while(a[--j]>p);
			if(i>=j)break;
			long long tmp=a[i];
			a[i]=a[j];
			a[j]=tmp;
		}
		if(k==i-l)return a[i];
		else if(k<i-l)r=i-1;
		else if(k>i-l){
			k-=(i-l+1);
			l=j+1;
		}
	}
	return 0;
}

