int R[2]={1,1};
int C[2]={1,1};
int H[2][400010],N[2][400010];
long long h0=0,h1=0;
//評価関数（いまはMIN）
int hyouka(int a,int b,int n){
  if(C[n]<b)return 1;
  if(C[n]<a||b==0)return 0;
  if(n==0)return N[n][H[n][a]]>N[n][H[n][b]]?1:0;
  if(n==1)return N[n][H[n][a]]<N[n][H[n][b]]?1:0;
}
//挿入関数
void hin(int a,int n){
  int i=C[n]++;
  if(n==0)h0+=2e9-a;
  else    h1+=2e9+a;
  for(N[n][H[n][0]=R[n]]=a;hyouka(0,i/2,n);i/=2)H[n][i]=H[n][i/2];
  H[n][i]=R[n]++;
}
//取り出す関数
int hout(int n){
  int rt=H[n][1],i,j=2,k=H[n][--C[n]];
  if(n==0)h0-=2e9-N[n][rt];
  else    h1-=2e9+N[n][rt];
  for(i=1;hyouka(i,C[n],n);i=j)H[n][i]=H[n][j=i*2+1-hyouka(i*2,i*2+1,n)];
  H[n][j/2]=k;
  return rt;
}
