      while(N[0][H[0][1]]>N[1][H[1][1]]){
	hin(N[0][hout(0)],1);
	hin(N[1][hout(1)],0);
      }//printf("%d %d %d\n",C[0]-1,C[1]-1,N[0][H[0][1]]);
