int first = 1;
int mmax = 0;
int mmin = 0;
int64_t med_sum = 0;
void update(int val) {
    if(val >= mmin) {
        enqueue_min(val);
        enqueue_min(val);
        int nval = dequeue_min();
        enqueue_max(nval);
    } else if(val <= mmax) {
        enqueue_max(val);
        enqueue_max(val);
        int nval = dequeue_max();
        enqueue_min(nval);
    } else {
        enqueue_max(val);
        enqueue_min(val);
    }
    if(first) {
        // med_sum stays 0
        first = 0;
    } else {
        if(mmax <= val && val <= mmin) {
            // do nothing
        } else {
            med_sum += min(abs(val-mmax), abs(val-mmin));
        }
    }
    // update
    mmax = max_heap[1];
    mmin = min_heap[1];
#ifdef DEBUG
    printf("%d %d -> %lld\n", mmax, mmin, med_sum);
#endif
}

