#define MAPSIZE 1048576

typedef struct {
	int arr[MAPSIZE][2];
} map;

void minit(map *m) {
	for (int i = 0; i < MAPSIZE; i++) {
		m->arr[i][1] = -1;
	}
}

int mhash(int x) {
	x = (20981 + x%20981) % 20981;
	return ((long long int) x * 10487 + 1049) % MAPSIZE;
}

void madd(map *m, int x) {
	int h = x;
	do h = mhash(h);
	while (m->arr[h][1] != -1 && m->arr[h][0] != x);
	m->arr[h][0] = x;
	if (m->arr[h][1] == -1) m->arr[h][1] += 2;
	else m->arr[h][1]++;
}

int mget(map *m, int x) {
	int h = x;
	do h = mhash(h);
	while (m->arr[h][1] != -1 && m->arr[h][0] != x);
	return m->arr[h][1];
}

int cmpmin(int a, int b) {
	return a-b;
}

int cmpmax(int a, int b) {
	return b-a;
}

typedef struct {
	int n, arr[200000];
	int (*cmp)(int, int);
} heap;

void hpush(heap *h, int x) {
	int i = h->n++;
	h->arr[i] = x;

	while (i > 0) {
		int p = (i-1)/2;
		if (h->cmp(h->arr[p], h->arr[i]) > 0) {
			int t = h->arr[p];
			h->arr[p] = h->arr[i];
			h->arr[i] = t;
			i = p;
		} else break;
	}
}

int hpop(heap *h) {
	int ret = h->arr[0];
	h->arr[0] = h->arr[--h->n];

	int i = 0, c;
	while ((c = i*2 + 1) < h->n) {
		if (c+1 < h->n && h->cmp(h->arr[c], h->arr[c+1]) > 0) {
			c++;
		}

		if (h->cmp(h->arr[i], h->arr[c]) > 0) {
			int t = h->arr[c];
			h->arr[c] = h->arr[i];
			h->arr[i] = t;
			i = c;
		} else break;
	}

	return ret;
}

int hpeek(const heap *h) {
	return h->arr[0];
}

heap left = {.n = 0, .cmp = cmpmax}, right = {.n = 0, .cmp = cmpmin};
map icnt;

int main(void) {
	int q;
	scanf("%d", &q);

	long long int y = 0, d = 0;
	minit(&icnt);

	while (q--) {
		int t;
		scanf("%d", &t);
		if (t == 1) {
			int a, b;
			scanf("%d%d", &a, &b);
			int px = hpeek(&left);
			y += abs(px-a);
			d += b;
			madd(&icnt, a);

			if (a < px) hpush(&left, a);
			else hpush(&right, a);

			int diff = left.n - right.n;
			if (diff == 2) hpush(&right, hpop(&left));
			else if (diff == -1) hpush(&left, hpop(&right));

			int x = hpeek(&left);
			if (x != px) {
				int lc = left.n;
				int rc = right.n;
				int hcnt = mget(&icnt, x);
				if (hpeek(&right) == x) {
					rc -= hcnt-1;
					lc--;
				} else lc -= hcnt;

				y += (long long int) (x-px) * (lc - rc);
				y -= (long long int) (abs(x-px)) * hcnt;
			}
		} else {
			printf("%d %lld\n", hpeek(&left), y+d);
		}
	}
}

