			{
				for (j = n - 1; j >= 0; j--)
				{
					if (a[j] > y)
						a[j + 1] = a[j];
					else
					{
						a[j + 1] = y;
						break;
					}
					if (j == 0)
						a[0] = y;
				}
			}
			n++;
			b += z;
		}
		else
		{
			m = a[(n - 1) / 2];
			ans = b;
			for (j = 0; j < n; j++)
				ans += absll(m - a[j]);
			printf("%lld %lld\n", m, ans);
		}
	}
	return 0;
}

