		Scanner sc =  new Scanner(System.in);
		int query = sc.nextInt();
		int[] a = new int[query];
		int acount = 1;
		long bSum = 0;
		StringBuilder sb = new StringBuilder();
		sc.next();
		a[0] = sc.nextInt();
		bSum += sc.nextInt();
		for(int i=1;i<query;i++) {
			int order = sc.nextInt();
			if(order == 1) {
				int addA = sc.nextInt();
				bSum += sc.nextInt();
				int j;
				for(j=acount;j>0;j--) {
					if(addA < a[j-1])
						a[j] = a[j-1];
					else {
						a[j] = addA;
						break;
					}
				}
				if(j==0)
					a[0] = addA;
				acount++;
			}else {
				long atotal = 0;
				for(int j=0;j<(acount-1)/2;j++)
					atotal -= a[j];
				for(int j=(acount-1)/2+1;j<acount;j++)
					atotal += a[j];
				atotal -= acount%2 == 0? a[(acount-1)/2]:0;
				sb.append(a[(acount-1)/2]).append(' ').append(atotal+bSum).append('\n');
			}
		}
		sc.close();
		System.out.println(sb.toString());
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.List;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int q = Integer.parseInt(br.readLine());
		LinkedList<Integer> list = new LinkedList<Integer>();
		String[] sa = br.readLine().split(" ");
		int a0 = Integer.parseInt(sa[1]);
		int b0 = Integer.parseInt(sa[2]);
		list.add(a0);
		int idx = 0;
		int x = a0;
		long v = b0;
		int cnt = 1;

		for (int i = 1; i < q; i++) {
			sa = br.readLine().split(" ");
			int y = Integer.parseInt(sa[0]);
			if (y == 1) {
				int a = Integer.parseInt(sa[1]);
				int b = Integer.parseInt(sa[2]);
				if (cnt % 2 == 0) {
					idx++;
				}
				int j = binarySearch(list, a);
				list.add(j, a);
				v += Math.abs(x - a) + b;
				x = list.get(idx);
				cnt++;
			} else {
				System.out.println(x + " " + v);
			}
		}
	}

	static int binarySearch(List<Integer> list, long val) {
		int start = -1;
		int end = list.size();

		while (Math.abs(end - start) > 1) {
			int mid = (end + start) / 2;
			if (list.get(mid) >= val) {
				end = mid;
			} else {
				start = mid;
			}
		}
		return end;
	}
}

