                    continue;
                }
                if (n % 2 == 1) {
                    if (mid <= a) {
                        if (index == data.get(mid) - 1) {
                            Map.Entry<Long, Integer> entry = data.higherEntry(mid);
                            index = 0;
                            mid = entry.getKey();
                        } else {
                            index++;
                        }
                    }
                    value += Math.abs(a - mid);
                } else {
                    value += Math.abs(mid - a);
                    if (a < mid) {
                        if (index == 0) {
                            Map.Entry<Long, Integer> entry = data.lowerEntry(mid);
                            index = entry.getValue() - 1;
                            mid = entry.getKey();
                        } else {
                            index--;
                        }
                    }
                }
            } else {
                out.println(mid, base + value);
            }
        }
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

