		ArrayList<Long> s=new ArrayList<Long>();
		int[] a=new int[q];
		long sum=0;
		for(int i=0;i<q;i++) {
			int x=scan.nextInt();
			a[i]=x;
			if(x==1) {
				int ai=scan.nextInt();
				int bi=scan.nextInt();
				al.add(ai);
				sum+=bi;
				s.add(sum);
			}
		}
		int[] arr=new int[al.size()];
		for(int i=0;i<al.size();i++) {
			arr[i]=al.get(i);
		}
		median=new ArrayList<Integer>();
		printMedian(arr);
		int j=0;
		for(int i=0;i<q;i++) {
			if(a[i]==1) {
				j++;
			}
			else {
				long ans=s.get(j-1);
				for(int k=0;k<j;k++) {
					ans+=(long)Math.abs(median.get(j-1)-al.get(k));
				}
				out.println(median.get(j-1)+" " +ans);
			}
		}
