    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final int[] da = {-1, 0, 1, 0, -1, 1, 1, -1, -1};

    void solve() {
        int q = in.nextInt();
        long base = 0;
        int n = 0;
        long mid = 0;
        long value = 0;
        TreeMap<Long, Integer> data = new TreeMap<>();
        int index = 0;
        for (int i = 0; i < q; i++) {
            int t = in.nextInt();
            if (t == 1) {
                long a = in.nextInt();
                long b = in.nextInt();
                base += b;
                n++;
                data.merge(a, 1, Integer::sum);
                if (n == 1) {
                    mid = a;
                    continue;
                }
                if (n % 2 == 1) {
                    if (mid <= a) {
                        if (index == data.get(mid) - 1) {
                            Map.Entry<Long, Integer> entry = data.higherEntry(mid);
                            index = 0;
                            mid = entry.getKey();
                        } else {
                            index++;
                        }
                        value += a - mid;
                    }
                } else {
                    if (a < mid) {
                        value += mid - a;
                        if (index == 0) {
                            Map.Entry<Long, Integer> entry = data.lowerEntry(mid);
                            index = entry.getValue() - 1;
                            mid = entry.getKey();
                        } else {
                            index--;
                        }
                    }
                }
            } else {
                out.println(mid, base + value);
            }
        }
    }

