class bit {
    int n;
    long b[]; 
    bit(int n){
        this.n = n;
        b = new long[n+1];
    }
    long sum(int i){
        long s = 0;
        while(i > 0){
            s += b[i];
            i -= i&-i;
        }
        return s;   
    }
    void add(int i, int x){
        while(i <= n){
            b[i] += x;
            i += i&-i;
        }
    }

    int lb(long x) {
    	//lower bound sum(i)がx以上となるような最小のi
    	int dw=1,up=n,md,min=this.n+1;
    	for (int i = 0; i < 60; i++) {
			md=(dw+up)/2;
			if(x<=sum(md)) {
				min=min(min,md);
				up=md;
			} else {
				dw=md;
			}
		}
    	if(min==n+1)return -1;
    	return min;
    }
}

