public class Main {


  private static void solve() {
    int q = ni();


    PriorityQueue<Long> ql = new PriorityQueue<>();
    PriorityQueue<Long> qr = new PriorityQueue<>();

    long lsum = 0;
    long rsum = 0;

    long bsum = 0;
    for (int i = 0; i < q; i ++) {
      int t = ni();
      if (t == 1) {
        long a = nl();
        bsum += nl();

        if (ql.size() == 0 || ql.peek() < a) {
          ql.add(a);
          lsum += a;
        } else {
          qr.add(a);
          rsum += a;
        }

        while (ql.size() < qr.size()) {
          long x = qr.poll();
          ql.add(x);
          rsum -= x;
          lsum += x;
        }

        while (ql.size() > qr.size()) {
          long x = ql.poll();
          qr.add(x);
          lsum -= x;
          rsum += x;
        }
      } else {

        if (qr.size() > ql.size()) {
          long x = qr.peek();
          long n = ql.size();
          long ret = (rsum - x - x * n) + (x * n - lsum) + bsum;
