    private static boolean DEBUG_FLG = false;

    public static void main(String[] args) {
    	int Q = sc.nextInt();
    	long sum = 0;
    	int mida = 0;
    	PriorityQueue<Integer> lefta = new PriorityQueue<>((a, b) -> b - a);
    	PriorityQueue<Integer> righta = new PriorityQueue<>((a, b) -> b - a);
    	int leftasize = 0;
    	int rightasize = 0;
    	for(int i=0; i<Q; i++) {
    		int befmida = mida;
    		int query = sc.nextInt();
    		if(query == 1) {
    			int a = sc.nextInt();
    			long b = sc.nextLong();
    			sum += b;
    			if(i == 0) {
    				mida = a;
    			} else {
    				if(a < mida) {
    					lefta.add(a);
    					leftasize++;
    					if((leftasize + rightasize + 1) % 2 == 0) {
        					int x = lefta.poll();
        					leftasize--;
        					righta.add(mida);
        					rightasize++;
        					mida = x;
        					sum += Math.abs((long)mida - (long)befmida);
        				}
    				} else {
    					righta.add(a);
    					rightasize++;
    					if((leftasize + rightasize + 1) % 2 != 0) {
    						int x = righta.poll();
    						rightasize--;
    						lefta.add(mida);
    						leftasize++;
    						mida = x;
    						sum += Math.abs((long)mida - (long)befmida);
    					}
    				}
    			}
    		} else {
