import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;
import java.math.BigInteger;

public class Main implements Runnable {

	static int mod = 1000000007;

    public static void main(String[] args) {
    	new Thread(null, new Main(), "", 1024 * 1024 * 1024).start();
    }

    public void run() {
    	PrintWriter out = new PrintWriter(System.out);
        FastScanner sc = new FastScanner();

        int q = sc.nextInt();
        long B = 0;
        int lmed = Integer.MAX_VALUE;
        PriorityQueue<Integer> l = new PriorityQueue<Integer>(Comparator.reverseOrder());
        PriorityQueue<Integer> r = new PriorityQueue<Integer>();
        long lsum = 0;
        long rsum = 0;

        for(int i=0;i<q;i++){
        	if(sc.nextInt() == 1){	//更新
        		int a = sc.nextInt();
        		B += sc.nextInt();

        		if(a<=lmed){
        			l.offer(a);
        			lsum += a;
        		}
        		else{
        			r.offer(a);
        			rsum += a;
        		}

        		if(l.size()>r.size()+1){
        			int move = l.poll();
        			lsum -= move;
        			r.offer(move);
        			rsum += move;
        		}
        		else if(l.size()<r.size()){	//常に奇数はl側
        			int move = r.poll();
        			rsum -= move;
        			l.offer(move);
        			lsum += move;
        		}

        		lmed = l.peek();
        	}
        	else{	//求値
        		long ans = B;

    			ans += lmed*l.size() - lsum;
    			ans += rsum - lmed*r.size();

        		out.println(lmed + " " + ans);
        	}
        }

        out.flush();
    }
}


