/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        FAbsoluteMinima solver = new FAbsoluteMinima();
        solver.solve(1, in, out);
        out.close();
    }

    static class FAbsoluteMinima {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int q = in.readInt();
            long[] a1 = in.readLongArray(3);
            TreeSet<LongIntPair> set = new TreeSet<>();
            LongIntPair cur = new LongIntPair(a1[1], 0);
            set.add(cur);
            long cnt = 1;
            long sum = 0;
            long bsum = a1[2];
            for (int i = 1; i < q; i++) {
                long a = in.readLong();
                if (a == 1) {
                    long b = in.readLong();
                    long c = in.readLong();
                    LongIntPair add = new LongIntPair(b, i);
                    set.add(add);
                    int comp = add.compareTo(cur);
                    if (comp > 0) {
                        if (cnt % 2 == 0) {
                            cur = set.higher(cur);
                        }
                        sum += b - cur.first;
                    } else {
                        sum += cur.first - b;
                        if (cnt % 2 == 1) {
                            cur = set.lower(cur);
                        }
                    }
                    bsum += c;
                    cnt++;
                } else {
                    long ans = sum + bsum;
                    out.printLine(cur.first + " " + ans);
                }
            }
        }

    }

    static class LongIntPair implements Comparable<LongIntPair> {
        public final long first;
        public final int second;

        public LongIntPair(long first, int second) {
            this.first = first;
            this.second = second;
        }

        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (o == null || getClass() != o.getClass()) {
                return false;
            }

            LongIntPair pair = (LongIntPair) o;

            return first == pair.first && second == pair.second;
        }

        public int hashCode() {
            int result = Long.hashCode(first);
            result = 31 * result + Integer.hashCode(second);
            return result;
        }

        public String toString() {
            return "(" + first + "," + second + ")";
        }

        public int compareTo(LongIntPair o) {
            int value = Long.compare(first, o.first);
            if (value != 0) {
                return value;
            }
            return Integer.compare(second, o.second);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public long[] readLongArray(int size) {
            long[] array = new long[size];
            for (int i = 0; i < size; i++) {
                array[i] = readLong();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long readLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }
}

import java.util.PriorityQueue;

public class Main {


  private static void solve() {
    int q = ni();


    PriorityQueue<Long> ql = new PriorityQueue<>((o1, o2) -> Long.compare(o2, o1));
    PriorityQueue<Long> qr = new PriorityQueue<>();

    long lsum = 0;
    long rsum = 0;

    long bsum = 0;
    for (int i = 0; i < q; i ++) {
      int t = ni();
      if (t == 1) {
        long a = nl();
        bsum += nl();

        if (ql.size() > 0 && ql.peek() > a) {
          ql.add(a);
          lsum += a;
        } else if (qr.size() > 0 && qr.peek() <= a) {
          qr.add(a);
          rsum += a;
        } else {
          qr.add(a);
          rsum += a;
        }

        while (ql.size() < qr.size()) {
          long x = qr.poll();
          ql.add(x);
          rsum -= x;
          lsum += x;
        }

        while (ql.size() > qr.size()) {
          long x = ql.poll();
          qr.add(x);
          lsum -= x;
          rsum += x;
        }
      } else {

        if (qr.size() > ql.size()) {
          long x = qr.peek();
          long n = ql.size();
          long ret = (rsum - x - x * n) + (x * n - lsum) + bsum;
          out.println(x + " " + ret);
        } else {
          long x = ql.peek();
          long n = ql.size();
          long ret = (rsum - x * n) + (x * (n - 1) - (lsum - x)) + bsum;
          out.println(x + " " + ret);
        }
      }
    }
  }

