                    B += b;
                } else {
                    long x = (A.size() % 2 == 0) ? A.get(A.size() / 2 - 1) : A.get(A.size() / 2);

                    long y = B;
                    for (long a : A) {
                        y += Math.abs(x - a);
                    }

                    ans.append(x + " " + y).append("\n");
                }
            }

            System.out.print(ans.toString());
        }
    }

