	  SList list = new SList();

	  long sum = 0;
	  for( int i = 0; i < K; ++i ) {
		  switch( cin.nextInt() ) {
		  case 1:
			  list.add(cin.nextInt());
			  sum += cin.nextInt();
			  break;
		  case 2:
			  list.center(sum);
			  break;
		  }
	  }

