  class SList {
	  private PriorityQueue<Integer> lo;
	  private PriorityQueue<Integer> hi;
	  long loSum;
	  long hiSum;
	  SList() {
		  lo = new PriorityQueue<Integer>();
		  hi = new PriorityQueue<Integer>();
		  loSum = 0;
		  hiSum = 0;
	  }
	  void add(int K) {
		  if( lo.size() == 0 ) {
			  lo.add(-K);
			  loSum += -K;
			  return;
		  }
		  if( hi.size() == 0 ) {
			  int V = -lo.peek();
			  if( V <= K ) {
				  hi.add(K);
				  hiSum += K;
			  }
			  else {
				  lo.poll();
				  loSum -= -V;
				  hi.add(V);
				  hiSum += V;
				  lo.add(-K);
				  loSum += -K;
			  }
			  return;
		  }
		  int L = -lo.peek();
		  int H = hi.peek();
		  if( K >= H ) {
			  hi.add(K);
			  hiSum += K;
			  if( hi.size() == lo.size() + 1 ) {
				  int V = hi.poll();
				  hiSum -= V;
				  lo.add(-V);
				  loSum += -V;
			  }
		  }
		  else {
			  lo.add(-K);
			  loSum += -K;
			  if( lo.size() == hi.size() + 2 ) {
				  int V = -lo.poll();
				  loSum -= -V;
				  hi.add(V);
				  hiSum += V;
			  }
		  }
	  }
	  void center(long base) {
		  long V;
		  if( lo.size() == 0 ) {
			  System.out.println("0 0");
			  return;
		  }
		  if( hi.size() == 0 || lo.size() == hi.size() || lo.size() == hi.size() + 1 ) {
			  V = -lo.peek();
		  }
		  else {
			  V = hi.peek();
		  }
		  long total = hiSum + loSum + V * (lo.size() - hi.size()) + base;
		  // System.err.println(V + " " + (lo.size() + hi.size()) + " " + (loSum - hiSum) + " " + base);
		  System.out.println(V + " " + total);
	  }

  }

}

