class SegmentTree{
	int n;
	long[] node;

	//単位元
	long e = 0;

	//結合律が成り立つ二項演算
	private long func(long e1, long e2){
		return e1 + e2;
	}

	/* 元配列vをセグメント木で表現する */
	public SegmentTree(long[] v){
		int sz = v.length;
		n = 1;
		while(n < sz) n *= 2;
		node = new long[2*n-1];

		for(int i = 0; i < sz; i++)
			node[i+n-1] = v[i];

		for(int i = n-2; i >= 0; i--)
			node[i] = func(node[2*i+1], node[2*i+2]);
	}

	/* 0-indexed:xの要素をvalに更新 */
	public void updata(int index, long val){
		int x = index;
		x = x + n - 1;
		//更新
		node[x] = val;
		while(x > 0){
			x = (x - 1) / 2;
			node[x] = func(node[2*x+1], node[2*x+2]);
		}
	}

	/* 0-indexed:xの要素にvalを加算 */
	public void add(int index, long val){
		int x = index;
		x = x + n - 1;
		//加算
		node[x] += val;
		while(x > 0){
			x = (x - 1) / 2;
			node[x] = func(node[2*x+1], node[2*x+2]);
		}
	}

	/* 指定した区間[a,b)の最小値を求めるクエリ */
	public long query(int a, int b){
		return query(a, b, 0, 0, n);
	}

	private long query(int a, int b, int k, int l, int r){
		if(r <= a || b <= l) return e;
		if(a <= l && r <= b) return node[k];
		long vl = query(a, b, 2*k+1, l, (l+r)/2);
		long vr = query(a, b, 2*k+2, (l+r)/2, r);
		return func(vl, vr);
	}
}

class FastScanner {
    private InputStream in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    public FastScanner(InputStream in) {
		this.in = in;
	}
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() {
    	if (hasNextByte()) return buffer[ptr++];
    	else return -1;
    }
    private static boolean isPrintableChar(int c){
    	return 33 <= c && c <= 126;
    }
    public boolean hasNext() {
    	while(hasNextByte() && !isPrintableChar(buffer[ptr]))
    		ptr++; return hasNextByte();
    }
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public String nextLine() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(b != 10) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() {
    	return Double.parseDouble(next());
    }
}

