				int l = -1;
				int r = q;
				while (r - l > 1) {
					int mid = l + (r - l) / 2;
					if (rsqi.query(0, mid + 1) >= (cnt + 1) / 2) {
//					if (data[mid] > value) {
						r = mid;
					} else {
						l = mid;
					}
				}

				int mi = ab.get(r).i;
				int mii = index.get(mi);
				long sumb = rsqb.query(0, q);
				long suma = -rsqa.query(0, mii + 1) + rsqa.query(mii + 1, q);
				if (cnt % 2 == 1) {
					suma += ab.get(r).a;
				}

				pr.printf("%d %d%n", ab.get(r).a, suma + sumb);
				break;
			}

		}
	}

	static class Pair implements Comparable<Pair> {
		int a;
		int b;
		int i;

		Pair(int a, int b, int i) {
			this.a = a;
			this.b = b;
			this.i = i;
		}

		@Override
		public int compareTo(Pair o) {
			if (a == o.a) {
				if (b == o.b) {
					return Integer.compare(i, o.i);
				}
				return Integer.compare(b, o.b);
			}

			return Integer.compare(a, o.a);
		}

		@Override
		public int hashCode() {
			return Integer.hashCode(a + b);
		}

		@Override
		public boolean equals(Object obj) {
			Pair o = (Pair) obj;
			return a == o.a && b == o.b;
		}

		@Override
		public String toString() {
			// [xxx, xxxx]
			StringBuilder stmp = new StringBuilder(32);
			stmp.append('[');
			stmp.append(a);
			stmp.append(',');
			stmp.append(' ');
			stmp.append(b);
			stmp.append(']');

			return stmp.toString();
		}
	}

	/**
	 * Segment Tree による Range Sum Query
	 */
	static class RSQ {
		long[] st;
		int n;

		/**
		 * n 個の要素を持つSegmentTreeを生成する
		 * 
		 * @param n 要素数
		 */
		RSQ(int n) {
			this.n = 1;
			while (this.n < n) {
				this.n *= 2;
			}
			st = new long[2 * this.n - 1];
		}

		/**
		 * i 番目の要素に x を足す
		 * 
		 * @param i 対象となる要素(0-indexed)
		 * @param x 追加する値
		 */
		void add(int i, int x) {
			i = n - 1 + i;
			st[i] += x;
			while (i > 0) {
				i = (i - 1) / 2;
				st[i] += x;
			}
		}

		/**
		 * 指定した区間の合計値を返す
		 * 
		 * @param a 区間の端点。[a,b)(0-indexed)
		 * @param b 区間の端点。[a,b)(0-indexed)
		 * @return 指定された区間の合計値
		 */
		long query(int a, int b) {
			return query(a, b, 0, 0, n);
		}

		private long query(int a, int b, int i, int l, int r) {
			if (a >= r || b <= l) {
				return 0;
			}
			if (a <= l && b >= r) {
				return st[i];
			}

			return query(a, b, i * 2 + 1, l, (l + r) / 2) + query(a, b, i * 2 + 2, (l + r) / 2, r);
		}
	}

