	public static void main(String[] args) {
		FastScanner fs = new FastScanner(System.in);
		int q = fs.nextInt();
		long sum = 0, suml = 0, sums = 0;
		PriorityQueue<Integer> ql = new PriorityQueue<>();//大きい方の集合を管理
		PriorityQueue<Integer> qs = new PriorityQueue<>((a1,a2)-> a2-a1);//小さい方の集合を管理
		for(int i=0;i<q;i++) {
			int t = fs.nextInt();
			if(t==1) {
				int a = fs.nextInt(), b = fs.nextInt();
				sum += b;

				suml += a;
				ql.add(a);
				int d = ql.poll();
				suml -= d;
				sums += d; 
				qs.add(d);
				if(qs.size()>ql.size()) {
					d = qs.poll();
					sums -= d;
					suml += d; 
					ql.add(d);
				}


			}
			else {//解答
				if(qs.size()==ql.size()) {
					long ans = sum + suml - sums;
					System.out.println(qs.peek() + " " + ans);
				}
				else {
					long p = ql.peek();//大きい集合の最小で、今回無視する値
					long ans = sum + (suml - p) - sums;
					System.out.println(p + " " + ans);
				}
			}
		}
	}

	//MOD culculations
	static long plus(long x, long y) {
		long res = (x + y) % mod;
		return res < 0 ? res + mod : res;
	}

	static long sub(long x, long y) {
		long res = (x - y) % mod;
		return res < 0 ? res + mod : res;
	}

	static long mul(long x, long y) {
		long res = (x * y) % mod;
		return res < 0 ? res + mod : res;
	}

	static long div(long x, long y) {
		long res = x * pow(y, mod - 2) % mod;
		return res < 0 ? res + mod : res;
	}

	static long pow(long x, long y) {
		if (y < 0)
			return 0;
		if (y == 0)
			return 1;
		if (y % 2 == 1)
			return (x * pow(x, y - 1)) % mod;
		long root = pow(x, y / 2);
		return root * root % mod;
	}
}

