class MyLong implements Comparable{
    long l;
    static long count=0;
    MyLong(long l){this.l=l;}
    @Override public String toString(){return String.valueOf(l*count+l);}
    public int compareTo(Object o){
        if(!(o instanceof MyLong)) return 0;
        MyLong ml=(MyLong) o;
        return l>=ml.l?1:-1;
    }
