		PriorityQueue<Long> leftQueue = new PriorityQueue<>(Collections.reverseOrder());
		Long center = null;
		PriorityQueue<Long> rightQueue = new PriorityQueue<>();
		long sum = 0L;
		long min = 0L;
		{
			sc.nextInt(); // 1 a b
			long a = sc.nextLong();
