					long left = leftQueue.poll();
					long right = rightQueue.poll();
					if (a < left) {
						leftQueue.add(a);
						rightQueue.add(right);
						center = left;
						min += center - a;
					} else if (right < a) {
						rightQueue.add(a);
						leftQueue.add(left);
						center = right;
						min += a - center;
					} else {
						rightQueue.add(right);
						leftQueue.add(left);
						center = a;
					}
				} else {
					if (center <= a) {
						rightQueue.add(a);
						leftQueue.add(center);
						min += a - center;
					} else {
						leftQueue.add(a);
						rightQueue.add(center);
						min += center - a;
					}
					center = null;
				}
			} else {
				if (center == null) {
					System.out.print(leftQueue.peek() + " ");
				} else {
					System.out.print(center + " ");
				}
				System.out.println(min + sum);
			}
		}
	}

	class Scanner {
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int index;
		private int length;

		public Scanner(InputStream in) {
			this.in = in;
		}

		private boolean isPrintableChar(int c) {
			return '!' <= c && c <= '~';
		}

		private boolean isDigit(int c) {
			return '0' <= c && c <= '9';
		}

		private boolean hasNextByte() {
			if (index < length) {
				return true;
			} else {
				try {
					length = in.read(buffer);
					index = 0;
				} catch (IOException e) {
					e.printStackTrace();
				}
				return length > 0;
			}
		}

		private boolean hasNext() {
			while (hasNextByte() && !isPrintableChar(buffer[index])) {
				index++;
			}
			return hasNextByte();
		}

		private int readByte() {
			return hasNextByte() ? buffer[index++] : -1;
		}

		public String next() {
			if (!hasNext()) {
				throw new RuntimeException("no input");
			}
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (isPrintableChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public long nextLong() {
			if (!hasNext()) {
				throw new RuntimeException("no input");
			}
			long value = 0L;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			while (isPrintableChar(b)) {
				if (isDigit(b)) {
					value = value * 10 + (b - '0');
				}
				b = readByte();
			}
			return minus ? -value : value;
		}

		public int nextInt() {
			return (int)nextLong();
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}
	}

