import java.util.*;
import java.lang.*;
import java.math.*;
import java.awt.*;

public class Main{

    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        PriorityQueue<Long> pribig = new PriorityQueue<>(Comparator.naturalOrder());
        PriorityQueue<Long> prismall = new PriorityQueue<>(Comparator.reverseOrder());
        long big = 0;
        long small = 0;
        long b = 0;
        long ans;
        for (int i = 0; i < n; i++) {
            int tmp = sc.nextInt();
            if (tmp == 1) {
                // koushin
                long a = sc.nextLong();
                long bb = sc.nextLong();
                b += bb;
                if (prismall.isEmpty() || prismall.peek() >= a) {
                    // prismall.peek -> pribig, a -> prismall
                    prismall.add(a);
                    small+=a;
                    if (!prismall.isEmpty() && prismall.size() > pribig.size() + 1 ) {
                        long change = prismall.poll();
                        pribig.add(change);
                        small -= change;
                        big += change;
                    }
                }else{
                    pribig.add(a);
                    big += a;
                    if (pribig.size() > prismall.size()) {
                        long odsends = pribig.poll();
                        prismall.add(odsends);
                        big -= odsends;
                        small += odsends;
                    }
                }
            }else if(tmp == 2){
                // hanbetsu
                // small = big or small = big + 1
                ans = prismall.peek();
                System.out.println(ans + " " + (-small+big +prismall.size() * ans - pribig.size()* ans + b));
            }

        }

        sc.close();
    }

}

import java.io.PrintWriter;
import java.util.Scanner;
import java.util.TreeSet;

public final class Main {

	private static final Scanner sc = new Scanner(System.in);
	static PrintWriter writer = new PrintWriter(System.out);

	public static void main(String[] args) {
		int Q = sc.nextInt();
		TreeSet<Long> set = new TreeSet<>();
		sc.next();
		long minima = sc.nextLong() << 32;
		set.add(minima << 32);
		long upperSum = 0;
		long lowerSum = 0;
		long sumB = sc.nextInt();
		for (int i = 1; i < Q; i++) {
			int type = sc.nextInt();
			if (type == 1) {
				long a = (sc.nextLong() << 32) + i;
				sumB += sc.nextInt();
				set.add(a);
				if (a < minima) {
					lowerSum += a >> 32;
					if (set.size() % 2 == 0) {
						upperSum += minima >> 32;
						minima = set.lower(minima);
						lowerSum -= minima >> 32;
					}
				} else {
					upperSum += a >> 32;
					if (set.size() % 2 != 0) {
						lowerSum += minima >> 32;
						minima = set.higher(minima);
						upperSum -= minima >> 32;
					}
				}
			} else {
				int countU = set.size() / 2;
				int countL = (set.size() - 1) - countU;
				long ans = minima >> 32;
				long v = upperSum - ans * countU;
				v += ans * countL - lowerSum;
				v += sumB;
				writer.println(ans + " " + v);
			}
		}
		writer.flush();
	}

}

