public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int q = reader.nextInt();
    long bSum = 0;
    Mid mid = new Mid();
    for (int i = 0; i < q; i++) {
      int t = reader.nextInt();
      switch (t) {
      case 1:
        long a = reader.nextLong();
        long b = reader.nextLong();
        mid.insert(a);
        bSum += b;
        break;
      case 2:
        long x = mid.getMid();
        out.printf("%d %d\n", x, bSum);

        break;
      }
    }
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

class ContestReader {
  private BufferedReader reader;
  private StringTokenizer tokenizer;

  ContestReader(InputStream in) {
    reader = new BufferedReader(new InputStreamReader(in));
  }

  public String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  public int nextInt() {
    return Integer.parseInt(next());
  }

  public long nextLong() {
    return Long.parseLong(next());
  }

  public double nextDouble() {
    return Double.parseDouble(next());
  }

  public int[] nextIntArray(int n) {
    int[] array = new int[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextInt();
    }
    return array;
  }

  public long[] nextLongArray(int n) {
    long[] array = new long[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextLong();
    }
    return array;
  }
}

class Algorithm {
  private static void swap(Object[] list, int a, int b) {
    Object tmp = list[a];
    list[a] = list[b];
    list[b] = tmp;
  }

  public static <T extends Comparable<? super T>> boolean nextPermutation(T[] ts) {
    int rightMostAscendingOrderIndex = ts.length - 2;
    while (rightMostAscendingOrderIndex >= 0 &&
        ts[rightMostAscendingOrderIndex].compareTo(ts[rightMostAscendingOrderIndex + 1]) >= 0) {
      rightMostAscendingOrderIndex--;
    }
    if (rightMostAscendingOrderIndex < 0) {
      return false;
    }

    int rightMostGreatorIndex = ts.length - 1;
    while (ts[rightMostAscendingOrderIndex].compareTo(ts[rightMostGreatorIndex]) >= 0) {
      rightMostGreatorIndex--;
    }

    swap(ts, rightMostAscendingOrderIndex, rightMostGreatorIndex);
    for (int i = 0; i < (ts.length - rightMostAscendingOrderIndex - 1) / 2; i++) {
      swap(ts, rightMostAscendingOrderIndex + 1 + i, ts.length - 1 - i);
    }
    return true;
  }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

/**
 * Absolute Minima
 */
public class Main {

    public static void main(String[] args) throws Exception {
        try (Scanner sc = new Scanner(System.in)) {
            int Q = sc.nextInt();

            StringBuilder ans = new StringBuilder();

            List<Long> A = new ArrayList<>();
            long A_SUM = 0, A_LOWER = 0;
            long B = 0;

            for (int i = 0; i < Q; i++) {
                int c = sc.nextInt();
                if (c == 1) {
                    long a = sc.nextLong();
                    long b = sc.nextLong();

                    int pos = Collections.binarySearch(A, a);
                    if (pos < 0) {
                        pos = -(pos + 1);
                    }
                    A.add(pos, a);

                    A_SUM += a;
                    if (A.size() % 2 == 0) {
                        if (pos < A.size() / 2) {
                            A_LOWER += a - A.get(A.size() / 2);
                        }
                    } else {
                        if (pos <= A.size() / 2) {
                            A_LOWER += a;
                        } else {
                            A_LOWER += A.get(A.size() / 2);
                        }
                    }

                    B += b;
                } else {
                    int d = (A.size() % 2 == 0) ? (A.size() / 2) : (A.size() / 2 + 1);

                    long x = A.get(d - 1);
                    long y = (x * d - A_LOWER) + (A_SUM - A_LOWER - x * (A.size() - d)) + B;

                    ans.append(x + " " + y).append("\n");
                }
            }

            System.out.print(ans.toString());
        }
    }

}

