                if(!(fl.l(am.l) && sf.g(am.l))){
                    min+=Math.min(Math.abs(fl.ls(am.l)), Math.abs(sf.ls(am.l)));
                    if(fl.geq(am.l)){
                        if(rm) fir.pollLast();
                        fir.add(am);
                    }
                    else{
