                pribig.add(a);
                big += a;
                if (pribig.size() - prismall.size() >= 2){
                    long ods = pribig.poll();
                    big -= ods;
                    prismall.add(ods);
                    small += ods;
                }
                b += (long)bb;
            }else if(tmp == 2){
                // hanbetsu
                if (pribig.size() == prismall.size()){
                    ans = prismall.peek();
                    System.out.println(ans+" "+  (big - small + b) );
                }else{
                    ans = pribig.peek();
                    System.out.println(ans+" "+  (big - small - pribig.peek() + b) );
                }

            }
        }

