import java.util.PriorityQueue;

public class Main {
  public static void main(String[] args) throws IOException {
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    int Q = Integer.parseInt(br.readLine());
    PriorityQueue<Integer> left = new PriorityQueue<>(Comparator.comparingInt(a -> -a));
    PriorityQueue<Integer> right = new PriorityQueue<>();
    long bsum = 0;
    long ymin = 0;
    StringBuffer sb = new StringBuffer();
    for (int i = 0; i < Q; i++) {
      String line = br.readLine();
      if (line.charAt(0) == '1') {
        String[] nums = line.split(" ");
        int a = Integer.parseInt(nums[1]);
        int b = Integer.parseInt(nums[2]);
        bsum += b;
        if (left.isEmpty()) left.add(a);
        else if (a < left.peek()) {
          left.add(a);
          ymin += left.peek() - a;
        } else {
          right.add(a);
          ymin += a - left.peek();
        }
        if (left.size() - right.size() > 1) {
          right.add(left.poll());
          int o = right.peek();
          int n = left.peek();
          ymin += (o - n) * (right.size() - left.size());
        } else if (right.size() > left.size()) {
          int o = left.peek();
          int n = right.peek();
          ymin += (n - o) * (left.size() - right.size());
          left.add(right.poll());
        }
      } else {
        sb.append(String.format("%d %d\n", left.peek(), bsum + ymin));
      }
    }
    System.out.print(sb.toString());
  }
}

