				sumB += sc.nextInt();
				set.add(a);
				if (a < minima) {
					lowerSum += a >> 32;
					if (set.size() % 2 == 0) {
						upperSum += minima >> 32;
						minima = set.lower(minima);
						lowerSum -= minima >> 32;
					}
				} else {
					upperSum += a >> 32;
					if (set.size() % 2 != 0) {
						lowerSum += minima >> 32;
						minima = set.higher(minima);
						upperSum -= minima >> 32;
					}
				}
			} else {
				int countU = set.size() / 2;
				int countL = (set.size() - 1) - countU;
				long ans = minima >> 32;
				long v = upperSum - ans * countU;
				v += ans * countL - lowerSum;
				v += sumB;
				writer.println(ans + " " + v);
			}
		}
		writer.flush();
	}

}

