public class Main {

	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		int q = ir.nextInt();
		int[] qs = new int[q];
		ArrayList<Long> a = new ArrayList<Long>();
		ArrayList<Long> b = new ArrayList<Long>();
		for (int t = 0; t < q; t++) {
			qs[t] = ir.nextInt();
			if (qs[t] == 1) {
				a.add(ir.nextLong());
				b.add(ir.nextLong());
			}
		}
		long at = 0, bt = 0, amt = 0;
		int p = 0;
		PriorityQueue<Long> s1 = new PriorityQueue<>(Collections.reverseOrder());
		PriorityQueue<Long> s2 = new PriorityQueue<>();
		for (int t = 0; t < q; t++) {
			if (qs[t] == 1) {
				at += a.get(p);
				bt += b.get(p);
				if (s2.isEmpty())
					s2.add(a.get(p));
				else if (p % 2 == 0) {
					if (s1.peek() < a.get(p)) {
						s2.add(a.get(p));
					} else {
						long m = s1.poll();
						s1.add(a.get(p));
						s2.add(m);
						amt = amt - m + a.get(p);
					}
				} else {
					if (s2.peek() > a.get(p)) {
						s1.add(a.get(p));
						amt += a.get(p);
					} else {
						long m = s2.poll();
						s1.add(m);
						s2.add(a.get(p));
						amt += m;
					}
				}
				p++;
			} else {
				out.println((p % 2 == 0 ? s1.peek() : s2.peek()) + " "
						+ (bt + at - 2 * amt - (p % 2 == 1 ? s2.peek() : 0)));
			}
		}
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		out.println(Arrays.deepToString(o));
	}
}

