class BIT{
    int n;
    long[] bit;
    public BIT(int n){
        this.n = n;
        bit = new long[n+1];
    }

    void add(int idx, long val){
        for(int i=idx+1; i<=n; i+=i&(-i)) bit[i-1] += val;
    }

    long sum(int idx){
        long res = 0;
        for(int i=idx+1; i>0; i-=i&(-i)) res += bit[i-1];
        return res;
    }

    long sum(int begin, int end){
        if (begin > end) return 0;
        if(begin == 0) return sum(end);
        return sum(end)-sum(begin-1);
    }
}

