public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() => Calc() switch { bool b => b ? "Yes" : "No", double d => d.ToString("0.####################"), object o => o.ToString(), };
    public object Calc()
    {
        int Q = cr;
        var res = new List<string>();
        _ = cr.Int;
        center = cr.Int;
        b = cr.Int;
        for (int i = 1; i < Q; i++)
        {
            int type = cr;
            if (type == 1)
            {
                int a = cr;
                b += cr.Long;
                var lc = sl.Count;
                var rc = sr.Count;
                if (a < center)
                {
                    if (lc < rc)
                    {
                        sl.Add(a);
                        lsum += a;
                    }
                    else
                    {
                        sr.Add(center);
                        rsum += center;
                        var lmax = sl.Max;
                        if (lmax <= a)
                        {
                            center = a;
                        }
                        else
                        {
                            sl.Add(a);
                            sl.Remove(lmax);
                            lsum += a - lmax;
                            center = lmax;
                        }
                    }
                }
                else
                {
                    if (lc < rc)
                    {
                        sl.Add(center);
                        lsum += center;
                        var rmin = sr.Min;
                        if (a <= rmin)
                        {
                            center = a;
                        }
                        else
                        {
                            sr.Add(a);
                            sr.Remove(rmin);
                            rsum += a - rmin;
                            center = rmin;
                        }
                    }
                    else
                    {
                        sr.Add(a);
                        rsum += a;
                    }
                }
            }
            else res.Add(Query());
        }
        return AllLines(res);
    }
    string Query()
    {
        return $"{center} {rsum - lsum - (long)center * (sr.Count - sl.Count) + b}";
    }
    MultiSet<int> sl = new MultiSet<int> { int.MinValue };
    MultiSet<int> sr = new MultiSet<int> { int.MaxValue };
    long lsum = 0;
    long rsum = 0;
    int center = int.MinValue;
    long b = 0;
}


