partial class Solver
{
    class Query
    {
        public int Index;
        public int Type;
        public int A, B;
    }

    struct Data
    {
        public int Index, Value;
    }

    public void Run()
    {
        var Q = ni();

        var queries = new List<Query>();
        var dataA = new List<Data>();
        long currentBSum = 0;
        for (int _ = 0; _ < Q; _++)
        {
            var t = ni();
            if (t == 1)
            {
                var a = ni();
                var b = ni();
                currentBSum += b;
                queries.Add(new Query { Index = _, Type = t, A = a, B = b });
                dataA.Add(new Data { Index = _, Value = a });
            }
            else if (t == 2)
            {
                queries.Add(new Query { Index = _, Type = t });
            }
        }
        dataA.Sort((d1, d2) => d1.Value.CompareTo(d2.Value));
        var positionFromQueryIndex = dataA
            .Select((d, i) => new { Index = i, QueryIndex = d.Index })
            .ToDictionary(g => g.QueryIndex, g => g.Index);

        var ans = new List<string>();

        queries.Reverse();

        var bit = new BinaryIndexTree(dataA.Count + 2);
        var flg = new BinaryIndexTree(dataA.Count + 2);
        for (int i = 0; i < dataA.Count; i++)
        {
            bit.Add(i, dataA[i].Value);
            flg.Add(i, 1);
        }

        int elements = dataA.Count;

        foreach (var q in queries)
        {
            if (q.Type == 1)
            {
                var pos = positionFromQueryIndex[q.Index];
                var current = bit.Sum(pos, pos);
                if (current != q.A) throw new Exception();
                bit.Add(pos, -current);
                flg.Add(pos, -flg.Sum(pos, pos));

                currentBSum -= q.B;

                elements--;
            }
            else
            {
                var medianIndex = (elements - 1) / 2;

                int pos = -1;
                for (int d = (1 << 18); d > 0; d >>= 1)
                {
                    if (pos + d - 1 >= dataA.Count) continue;
                    var newSum = flg.Sum(0, pos + d - 1);

                    if (newSum <= medianIndex)
                    {
                        pos += d;
                    }
                }
                //cout.WriteLine("! " + pos + " " + medianIndex);

                long x = dataA[pos].Value;
                var leftSum = bit.Sum(0, pos - 1);
                var leftNum = medianIndex;
                long f = currentBSum;
                if (leftNum > 0)
                {
                    f += leftNum * x - leftSum;
                }

                var rightSum = bit.Sum(pos + 1, dataA.Count);
                var rightNum = Math.Max(0, elements - 1 - leftNum);

                if (rightNum > 0)
                {
                    f += rightSum - rightNum * x;
                }

                ans.Add(string.Format("{0} {1}", x, f));
            }
        }
        ans.Reverse();
        foreach (var s in ans)
        {
            cout.WriteLine(s);
        }
    }
}

public class BinaryIndexTree
{
    private long[] array;
    public BinaryIndexTree(int size)
    {
        array = new long[size];
    }
    public long Sum(long a, long b)
    { // [a,b]
        if (a != 0) return Sum(0, b) - Sum(0, a - 1);
        long val = 0;
        for (; b >= 0; b = (b & (b + 1)) - 1) val += array[b];
        return val;
    }

    public void Add(int k, long val)
    {
        for (; k < array.Length; k |= k + 1)
            array[k] += val;
    }
}

