namespace Competitive
{
    internal class Solution
    {
        public int N;
        public long MOD = 1000000007;

        public void Run()
        {
            int Q = Input.ReadInt();

            long cons = 0;

            long v1 = 0;
            long v2 = 0;

            PriorityQueue<int> pq1 = new PriorityQueue<int>((d1, d2) => d1.CompareTo(d2) * (-1)); // 大きい順
            PriorityQueue<int> pq2 = new PriorityQueue<int>((d1, d2) => d1.CompareTo(d2)); // 小さい順
            for (int q = 0; q < Q; q++)
            {
                var line = Input.ReadIntArray();
                int qt = line[0];
                if (qt == 1)
                {
                    int a = line[1];
                    int b = line[2];
                    cons += b;

                    if (a <= pq1.Peek())
                    {
                        pq1.Push(a);
                        v1 += a;
                    }
                    else
                    {
                        pq2.Push(a);
                        v2 += a;
                    }

                    while (pq1.Count() < pq2.Count())
                    {
                        int v = pq2.Pop();
                        pq1.Push(v);
                        v1 += v;
                        v2 -= v;
                    }

                    while (pq1.Count() > pq2.Count() + 1)
                    {
                        int v = pq1.Pop();
                        pq2.Push(v);
                        v1 -= v;
                        v2 += v;
                    }
                }
                else
                {
                    long x = pq1.Peek();
                    long vv = (-v1 + x * pq1.Count()) + (v2 - x * pq2.Count()) + cons;
                    Console.WriteLine($"{x} {vv}");
                }

            }
        }
    }

    // libs ----------
    public class PriorityQueue<T>
    {
        private Comparison<T> _comparison;
        private int _type = 0;

        private T[] _heap;
        private int _sz = 0;

        private int _count = 0;

        /// <summary>
        /// Priority Queue with custom comparer
        /// </summary>
        public PriorityQueue(Comparison<T> comparison)
        {
            _heap = new T[128];
            _comparison = comparison;
        }

        private int Compare(T x, T y)
        {
            return _comparison(x, y);
        }

        public void Push(T x)
        {
            _count++;
            if (_count > _heap.Length)
            {
                var newheap = new T[_heap.Length * 2];
                for (int n = 0; n < _heap.Length; n++) newheap[n] = _heap[n];
                _heap = newheap;
            }

            //node number
            var i = _sz++;

            while (i > 0)
            {
                //parent node number
                var p = (i - 1) / 2;

                if (Compare(_heap[p], x) <= 0) break;

                _heap[i] = _heap[p];
                i = p;
            }

            _heap[i] = x;
        }

        public T Pop()
        {
            _count--;

            T ret = _heap[0];
            T x = _heap[--_sz];

            int i = 0;
            while (i * 2 + 1 < _sz)
            {
                //children
                int a = i * 2 + 1;
                int b = i * 2 + 2;

                if (b < _sz && Compare(_heap[b], _heap[a]) < 0) a = b;

                if (Compare(_heap[a], x) >= 0) break;

                _heap[i] = _heap[a];
                i = a;
            }

            _heap[i] = x;

            return ret;
        }

        public int Count()
        {
            return _count;
        }

        public T Peek()
        {
            return _heap[0];
        }

        public bool Contains(T x)
        {
            for (int i = 0; i < _sz; i++) if (x.Equals(_heap[i])) return true;
            return false;
        }

        public void Clear()
        {
            while (this.Count() > 0) this.Pop();
        }

        public IEnumerator<T> GetEnumerator()
        {
            var ret = new List<T>();

            while (this.Count() > 0)
            {
                ret.Add(this.Pop());
            }

            foreach (var r in ret)
            {
                this.Push(r);
                yield return r;
            }
        }

        public T[] ToArray()
        {
            T[] array = new T[_sz];
            int i = 0;

            foreach (var r in this)
            {
                array[i++] = r;
            }

            return array;
        }
    }

