class Program {
    static StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
    static Scan sc = new Scan();
    const int M = 1000000007;
    const int M2 = 998244353;
    const long LM = 1L << 60;
    const double eps = 1e-11;
    static void Main(string[] args)
    {
        int q = sc.Int;
        var lq = new PriorityQueue<int>();
        var rq = new PriorityQueue<int>(){ rev = true };
        long lsum = 0, rsum = 0;
        long b = 0;
        for (int i = 0; i < q; i++)
        {
            var a = sc.IntArr;
            if (a[0] == 1) {
                b += a[2];
                int x = a[1];
                if (lq.Count == 0 || x < lq.Top) {
                    lq.Push(x);
                    lsum += x;
                }
                else {
                    rq.Push(x);
                    rsum += x;
                }
                while (lq.Count < rq.Count) {
                    int y = rq.Pop();
                    rsum -= y;
                    lq.Push(y);
                    lsum += y;
                }
                while (lq.Count > rq.Count + 1) {
                    int y = lq.Pop();
                    lsum -= y;
                    rq.Push(y);
                    rsum += y;
                }
            }
            else {
                int x = lq.Top;
                long p = x * (long)lq.Count - lsum + rsum - x * (long)rq.Count;
                Prt(x, p + b);
            }
        }
        sw.Flush();
    }

    static void DBG(string a) => Console.WriteLine(a);
