    class F
    {
        static void Main(string[] args)
        {
            Method(args);
        }

        static void Method(string[] args)
        {
            int q = ReadInt();
            int[][] queries = new int[q][];
            for (int i = 0; i < q; i++) queries[i] = ReadInts();

            var list = new List<long>();
            long bSum = 0;
            var minQueue = new PriorityQueue<bool>();
            var maxQueue = new PriorityQueue<bool>();
            long minSum = 0;
            long maxSum = 0;
            long center = -queries[0][1];
            bSum += queries[0][2];
            for (int i = 1; i < q; i++)
            {
                if (queries[i][0] == 1)
                {
                    long now = -queries[i][1];
                    if (now < center)
                    {
                        minQueue.Enqueue(-now, true);
                        long next = -minQueue.Dequeue().Key;
                        while (next >= center)
                        {
                            maxQueue.Enqueue(next, true);
                            next = -minQueue.Dequeue().Key;
                        }
                        maxQueue.Enqueue(center, true);
                        minSum -= (center - next) * minQueue.Count;
                        maxSum += (center - next) * maxQueue.Count;
                        center = next;
                    }
                    if (now > center) {
                        maxQueue.Enqueue(now, true);
                        if ((minQueue.Count + maxQueue.Count + 1) % 2 == 0)
                        {
                            long next = maxQueue.Dequeue().Key;
                            while (next < center)
                            {
                                minQueue.Enqueue(-next, true);
                                next = maxQueue.Dequeue().Key;
                            }
                            minQueue.Enqueue(-center, true);
                            minSum += (next-center) * minQueue.Count;
                            maxSum -= (next - center) * minQueue.Count;
                        }
                    }
                    bSum += queries[i][2];
                }
                else
                {
                    WriteLine(center + " " + minSum + maxSum + bSum);
                }
            }
        }
        class PriorityQueue<T>
        {
            private readonly List<KeyValuePair<long, T>> list;

            public int Count { get; private set; }

            public PriorityQueue()
            {
                list = new List<KeyValuePair<long, T>>();
                Count = 0;
            }

            private void Add(KeyValuePair<long, T> pair)
            {
                if (Count == list.Count)
                {
                    list.Add(pair);
                }
                else
                {
                    list[Count] = pair;
                }
                Count++;
            }

            private void Swap(int a, int b)
            {
                KeyValuePair<long, T> tmp = list[a];
                list[a] = list[b];
                list[b] = tmp;
            }

            public void Enqueue(long key, T value)
            {
                Add(new KeyValuePair<long, T>(key, value));
                int c = Count - 1;
                while (c > 0)
                {
                    int p = (c - 1) / 2;
                    if (list[c].Key >= list[p].Key) break;

                    Swap(p, c);
                    c = p;
                }
            }

            public KeyValuePair<long, T> Dequeue()
            {
                KeyValuePair<long, T> pair = list[0];
                Count--;
                if (Count == 0) return pair;

                list[0] = list[Count];
                int p = 0;
                while (true)
                {
                    int c1 = p * 2 + 1;
                    int c2 = p * 2 + 2;
                    if (c1 >= Count) break;

                    int c = (c2 >= Count || list[c1].Key < list[c2].Key)
                        ? c1 : c2;
                    if (list[c].Key >= list[p].Key) break;

                    Swap(p, c);
                    p = c;
                }
                return pair;
            }
        }

        private static string Read() { return ReadLine(); }
        private static char[] ReadChars() { return Array.ConvertAll(Read().Split(), a => a[0]); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }
    }
}

