    bool chmax<T>(ref T a, T b) where T : IComparable<T> { if (a.CompareTo(b) < 0) { a = b; return true; } return false; }
    bool chmin<T>(ref T a, T b) where T : IComparable<T> { if (b.CompareTo(a) < 0) { a = b; return true; } return false; }

    void solve()
    {
        int T = cin.nextint;
        var S = new Set<int> { IsMultiSet = true };
        var BITP = new FenwickTree(T);
        var BITPC = new FenwickTree(T);
        var BITMC = new FenwickTree(T);
        var BITM = new FenwickTree(T);
        long K = 0;
        long SUM = 0;
        int cnt = 0;


        var A = new pair[T];
        var ID = new int[T];

        for (int t = 0; t < T; t++)
        {
            ID[t] = t;
            if (cin.nextint == 2)
            {
                A[t] = new pair(int.MaxValue, int.MaxValue);
                continue;
            }

            A[t] = new pair(cin.nextint, cin.nextint);
        }

        Array.Sort(A, ID);

        var to = new int[T];
        var H = new HashMap<int, int>();
        for (int i = 0; i < T; i++)
        {
            to[ID[i]] = i;
            H[A[i].f] = i;
        }


        for (int t = 0; t < T; t++)
        {
            var idx = to[t];
            int a = A[idx].f;
            int b = A[idx].s;
            if (a == int.MaxValue)
            {
                var mid = S[(S.Count - 1) / 2];
                var x = H[mid];

                long ans = K;
                //WriteLine(ans);
                //S.Items.join();
                if (mid >= 0)
                {
                    long rp = BITPC[x + 1, T - 1];
                    ans += BITP[x + 1, T - 1] - mid * rp;
                    long lp = BITPC[0, x - 1];
                    ans += mid * lp - BITP[0, x - 1];
                    long lm = BITMC[0, x - 1];
                    ans += mid * lm + BITM[0, x - 1];
                }
                else
                {
                    long rp = BITPC[x + 1, T - 1];
                    ans += BITP[x + 1, T - 1] - mid * rp;
                    long lm = BITMC[0, x - 1];
                    ans += BITM[0, x - 1] + mid * lm;
                    long rm = BITMC[x + 1, T - 1];
                    ans += -mid * rm - BITM[x + 1, T - 1];
                }
                WriteLine(mid + " "  + ans);
                continue;

            }

            K += b;
            S.Add(a);
            if (a >= 0) { BITP.Add(idx, a); BITPC.Add(idx, 1); }
            else BITM.Add(idx, -a); BITMC.Add(idx, 1);
        }
    }
}


