        {
            var sc = new Scanner();
            var sb = new StringBuilder();
            long bSum = 0;
            int Q = sc.NextInt();
            var ss = new SortedSet<S>(new C());
            for (int i = 0; i < Q; i++)
            {
                int type = sc.NextInt();
                if (type == 1)
