        {
            new Program().Solve();
        }

        public void Solve()
        {
            var sc = new Scanner();
            var sb = new StringBuilder();
            long bSum = 0;
            int Q = sc.NextInt();
            var set = new Set<long>();
            set.IsMultiSet = true;
            long l = int.MinValue, r = int.MaxValue;
            long min = 0;
            for (int i = 0; i < Q; i++)
            {
                int type = sc.NextInt();
                if (type == 1)
                {
                    int a = sc.NextInt();
                    int b = sc.NextInt();
                    bSum += b;
                    set.Add(a);
                    if (l <= a && a <= r)
                    {
                        min += 0;
                        l = a;
                        r = a;
                    }
                    else
                    {
                        if (r < a)
                        {
                            min += a - r;
                        }

                        if (a < l)
                        {
                            min += l - a;
                        }

                        if (set.Count % 2 == 0)
                        {
                            l = set[set.Count / 2 - 1];
                            r = set[set.Count / 2];
                        }
                        else
                        {
                            r = set[set.Count - 1];
                            l = r;
                        }
                    }

                }
                else if (type == 2)
                {

                    sb.AppendLine($"{l} {min + bSum}");
                }
            }
            Console.Write(sb.ToString());
        }
    }
