namespace AtCoder
{

    class C : IComparer<S>
    {
        public int Compare(S x, S y)
        {
            if (x.L == y.L)
            {
                return x.Index.CompareTo(y.Index);
            }

            return x.L.CompareTo(y.L);
        }
    }
    struct S
    {
        public long L;
        public int Index;

        public S(long l, int index)
        {
            L = l;
            Index = index;
        }
    }
    class Program
    {

        static void Main(string[] args)
        {
            new Program().Solve();
        }

        public void Solve()
        {
            var sc = new Scanner();
            var sb = new StringBuilder();
            long bSum = 0;
            int Q = sc.NextInt();
            var ss = new SortedSet<S>(new C());
            long l = int.MinValue, r = int.MaxValue;
            long min = 0;
            for (int i = 0; i < Q; i++)
            {
                int type = sc.NextInt();
                if (type == 1)
                {
                    int a = sc.NextInt();
                    int b = sc.NextInt();
                    bSum += b;
                    ss.Add(new S(a, i));
                    if (l <= a && a <= r)
                    {
                        min += 0;
                        l = a;
                        r = a;
                    }
                    else
                    {
                        if (r < a)
                        {
                            min += a - r;
                        }

                        if (a < l)
                        {
                            min += l - a;
                        }

                        var ar = ss.ToArray();

                        if (ar.Length % 2 == 0)
                        {
                            l = ar[ar.Length / 2 - 1].L;
                            r = ar[ar.Length / 2].L;
                        }
                        else
                        {
                            l = r = ar[ar.Length - 1].L;
                        }
                    }

                }
                else if (type == 2)
                {

                    sb.AppendLine($"{l} {min + bSum}");
                }
            }
            Console.Write(sb.ToString());
        }
    }
}




