class Program
{ 
    static void Main(string[] args)
    {
        Solve();
        //WriteLine(Solve());
    }
    static void Solve()
    {
        var q = Input.num;
        var res = new List<string>();
        var b = 0L;
        var sma = 0L;
        var pq = new PriorityQueue<long>();
        var pqM = new PriorityQueue<long>(false);
        var big = 0L;
        while (q-- > 0)
        {
            var que = Input.ar;
            if (que[0] == 1)
            {
                if (pq.Count == 0 || pq.Peek > que[1])
                    sma += pq.Enqueue(que[1]);
                else big += pqM.Enqueue(que[1]);
                if (pq.Count + 1 == pqM.Count)
                {
                    var t = pqM.Dequeue();
                    big -= t;
                    sma += pq.Enqueue(t);
                }
                if (pq.Count == pqM.Count + 2)
                {
                    var t = pq.Dequeue();
                    sma -= t;
                    big += pqM.Enqueue(t);
                }
                b += que[2];
            }
            else
            {
                var calc = pq.Count * pq.Peek - sma;
                calc += big - pqM.Count * pq.Peek;
                res.Add($"{pq.Peek} {calc + b}");
            }
        }
        if(res.Count!=0)
            WriteLine(string.Join("\n", res));
    }
}

