    public class Program
    {
        public object Calc()
        {
            var Q = consoleReader.Int();
            var result = new List<string>(Q);
            var sorted = new SortedCollection();

            long left = 0;
            long right = 0;
            long bottom = 0;
            foreach (var query in consoleReader.RepeatSplitInt(Q))
            {
                if (query[0] == 1)
                {
                    var item = query[1];
                    bottom += query[2];
                    var insertIndex = sorted.Add(item);
                    var halfIndex = sorted.Count / 2;
                    if (sorted.Count % 2 == 0)
                    {
                        if (insertIndex < halfIndex)
                        {
                            left += item;
                            right += sorted[halfIndex];
                        }
                        else
                        {
                            left += sorted[halfIndex - 1];
                            right += item;
                        }
                    }
                    else
                    {
                        if (insertIndex < halfIndex)
                        {
                            left += item - sorted[halfIndex];
                        }
                        else if (insertIndex > halfIndex)
                        {
                            right += item - sorted[halfIndex];
                        }
                    }
                }
                else
                {
                    long sum = bottom + right - left;
                    result.Add($"{sorted[(sorted.Count - 1) / 2]} {sum}");
                }
            }

            return MultiLine(result);
        }

        class SortedCollection : List<int>
        {
            public new int Add(int item)
            {
                base.Add(item);
                for (int i = this.Count - 2; i >= 0; i--)
                {
                    var current = this[i];
                    if (item < current)
                        this[i + 1] = current;
                    else
                    {
                        this[i + 1] = item;
                        return i + 1;
                    }
                }
                this[0] = item;
                return 0;
            }
        }

        public const int mod = 1000000007;
        #region いつもの
        private readonly ConsoleReader consoleReader;
        public Program() : this(new ConsoleReader()) { }
        public Program(ConsoleReader consoleReader) { this.consoleReader = consoleReader; }
        static void Main() => Console.WriteLine(new Program().Calc()); static string MultiLine<T>(IEnumerable<T> source) => string.Join("\n", source);
        #endregion
    }

