class Solver
{
    public void Solve(Scanner sc)
    {
        var Q = sc.Int;
        PriorityQueue<int> left = new PriorityQueue<int>((a, b) => b - a), right = new PriorityQueue<int>();
        var N = 0;
        long B = 0L, lsum = 0, rsum = 0;
        while (Q-- > 0)
        {
            int t = sc.Next<int>();
            if (t == 2)
            {
                if (N % 2 == 0)
                {
                    if (!left.Any()) WriteLine("0 0");
                    else WriteLine($"{left.Top} {B + rsum - lsum}");
                }
                else
                {
                    if (!right.Any()) WriteLine("0 0");
                    else WriteLine($"{right.Top} {B + rsum - lsum - right.Top}");
                }
                continue;
            }
            int a, b;
            sc.Make(out a, out b);
            B += b;
            if (N % 2 == 0)
            {
                if (!right.Any()) { rsum+=right.Push(a); goto END; }
                if (left.Top > a) { var v = left.Pop(); rsum += v; lsum -= v; right.Push(v); lsum += left.Push(a); }
                else rsum += right.Push(a);
            }
            else
            {
                if (right.Top < a) { var v = right.Pop(); lsum += v; rsum -= v; left.Push(v); rsum += right.Push(a); }
                else lsum += left.Push(a);
            }
        END:;
            N++;
        }
    }
}

public class PriorityQueue<T>
{
    private List<T> data = new List<T>();
    private Comparison<T> cmp;
    public int Count { get { return data.Count; } }
    public T Top { get { return data[0]; } }
    public PriorityQueue() { cmp = cmp ?? Comparer<T>.Default.Compare; }

    public PriorityQueue(Comparison<T> comparison) { cmp = comparison; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Parent(int i)
        => (i - 1) >> 1;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Left(int i)
        => (i << 1) + 1;
    public T Push(T val)
    {
        int i = data.Count;
        data.Add(val);
        while (i > 0)
        {
            int p = Parent(i);
            if (cmp(data[p], val) <= 0)
                break;
            data[i] = data[p];
            i = p;
        }
        data[i] = val;
        return val;
    }
    public T Pop()
    {
        var ret = data[0];
        var p = 0;
        var x = data[data.Count - 1];
        while (Left(p) < data.Count - 1)
        {
            var l = Left(p);
            if (l < data.Count - 2 && cmp(data[l + 1], data[l]) < 0) l++;
            if (cmp(data[l], x) >= 0)
                break;
            data[p] = data[l];
            p = l;
        }
        data[p] = x;
        data.RemoveAt(data.Count - 1);
        return ret;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public bool Any() => data.Count > 0;
}
