        static void Solve()
        {
            var Q = Sarray()[0];
            var lSum = 0L;
            var rSum = 0L;
            var bSum = 0L;
            var lPq = new priority_queue<long>((l, r) => l.CompareTo(r));//大きいもの優先
            var rPq = new priority_queue<long>((l, r) => r.CompareTo(l));//小さいもの優先
            lPq.insert(long.MinValue);
            rPq.insert(long.MaxValue);
            for (var i = 0; i < Q; ++i)
            {
                var Query = ReadLine();
                var c = lPq.top;
                if (Query[0] == '1')
                {
                    var ab = Query.Split().Select(long.Parse).ToArray();
                    var a = ab[1];
                    bSum += ab[2];
                    if (c < a)
                    {
                        rPq.insert(a);
                        rSum += a;
                    }
                    else
                    {
                        lPq.insert(a);
                        lSum += a;
                    }
                    if (0 < rPq.num - lPq.num)
                    {
                        var r = rPq.extract();
                        lPq.insert(r);
                        rSum -= r;
                        lSum += r;
                    }
                    if (1 < lPq.num - rPq.num)
                    {
                        var l = lPq.extract();
                        rPq.insert(l);
                        rSum += l;
                        lSum -= l;
                    }
                }
                else
                {
                    var cr = 0L;
                    if (rPq.num < lPq.num)
                        cr = c;
                    WriteLine($"{c} {rSum - lSum + cr + bSum}");
                }
            }
