        }

        static void Solve()
        {
            var Q = Sarray()[0];
            var lSum = 0L;
            var rSum = 0L;
            var bSum = 0L;
            var lPq = new priority_queue<long>((l, r) => l.CompareTo(r));//大きいもの優先
            var rPq = new priority_queue<long>((l, r) => r.CompareTo(l));//小さいもの優先
            lPq.insert(long.MinValue);
            rPq.insert(long.MaxValue);
            for (var i = 0; i < Q; ++i)
            {
                var Query = ReadLine();
                var c = lPq.top;
                if (Query[0] == '1')
                {
                    var ab = Query.Split().Select(long.Parse).ToArray();
                    var a = ab[1];
                    var b = ab[2];
                    bSum += b;
                    var lTop = lPq.top;
                    var rTop = rPq.top;
                    if (c < a)
                    {
                        rPq.insert(a);
                        rSum += Abs(a);
                    }
                    else
                    {
                        lPq.insert(a);
                        lSum += Abs(a);
                    }
                    if (0 < rPq.num - lPq.num)
                    {
                        var r = rPq.extract();
                        lPq.insert(r);
                        rSum -= Abs(r);
                        lSum += Abs(r);
                    }
                    if (1 < lPq.num - rPq.num)
                    {
                        var l = lPq.extract();
                        rPq.insert(l);
                        rSum += Abs(l);
                        lSum -= Abs(l);
                    }
                }
                else
                {
                    var cr = 0L;
                    if (rPq.num < lPq.num)
                        cr = Abs(c);
                    WriteLine($"{c} {(rSum - (lSum - cr) + bSum)}");
                }
            }
        }
        class priority_queue<T>
        {
            Comparison<T> cmp;
            T[] A = new T[2000000];
            // var pq = new priority_queue<long>((l, r) => l.CompareTo(r));
            // とすれば値の大きいものから優先
            public priority_queue(Comparison<T> c)
            {
                cmp = c;
            }
            public int num { get; private set; } = 0;
            public T top { get { return A[0]; }  }
            public void insert(T v)
            {
                A[num] = v;
                ++num;
                increaseKey(num);
            }
            void increaseKey(int i)
            {
                while (1 < i && 0 < cmp(A[i - 1], A[i / 2 - 1]))
                {
                    var t = A[i - 1];
                    A[i - 1] = A[i / 2 - 1];
                    A[i / 2 - 1] = t;
                    i = i / 2;
                }
            }
            public T extract()
            {
                if (num < 1) return default(T);
                var max = A[0];
                A[0] = A[num - 1];
                --num;
                maxHeapify(1);
                return max;
            }
            void maxHeapify(int i)
            {
                var H = num;
                var l = left(i);
                var r = right(i);
                var largest = 0;
                if (l <= H && 0 < cmp(A[l - 1], A[i - 1])) { largest = l; } else { largest = i; }
                if (r <= H && 0 < cmp(A[r - 1], A[largest - 1])) { largest = r; }
                if (largest != i)
                {
                    var t = A[i - 1];
                    A[i - 1] = A[largest - 1];
                    A[largest - 1] = t;
                    maxHeapify(largest);
                }
            }
            int left(int l) => l * 2;
            int right(int r) => r * 2 + 1;
        }

        static long Mod = (long)1e9 + 7;
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static public (T1 a, T2 b) Slice<T1, T2>()
