							var x = SHL.Top * -1;SHL.Pop();
							ltot -= x;
							SHR.Push(x);
							rtot += x;
						}
						while(SHR.Count > rc){
							var x = SHR.Top ;SHR.Pop();
							rtot -= x;
							SHL.Push(-x);
							ltot += x;
						}
					}
				} break;
