public class Prog
{
    private const int INF = 1000000007;
    private struct Pair { public int x, y; public Pair(int x, int y) { this.x = x; this.y = y; } }
    public static void Solve()
    {

        int N = NextInt();
        List<long[]> ans = new List<long[]>();
        long b_sum = 0;
        long small_sum = 0;
        long big_sum = 0;
        PriorityQueue<long, long> big = new PriorityQueue<long, long>();
        PriorityQueue<long, long> small = new PriorityQueue<long, long>(false);
        for (int i = 0; i < N; i++)
        {
            int Q = NextInt();
            if (Q == 1)
            {
                int a = NextInt();
                b_sum += NextInt();
                //とりあえずどっちにも追加する
                big.Add(a, a);
                small.Add(a, a);
                big_sum += a;
                small_sum += a;
                //small.top > big.top swap
                if (small.Peek() > big.Peek())
                {
                    var c0 = small.Take();
                    small_sum -= c0;
                    var c1 = big.Take();
                    big_sum -= c1;
                    big.Add(c0, c0);
                    small.Add(c1, c1);
                    big_sum += c0;
                    small_sum += c1;
                }
            }
            else
            {
                //small.top が中央値
                long mid = small.Peek();
                long c_min = mid * small.Count() - small_sum;
                long c_max = big_sum - mid * big.Count();
                ans.Add(new long[2] { mid, (c_max + c_min) / 2 + b_sum });
            }
        }
        ans.ForEach(v => Console.WriteLine(v[0] + " " + v[1]));
    }

    public static void Main()
    {
        var sw = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
}

public class PriorityQueue<Tkey, Tvalue> where Tkey : IComparable
{
    private List<Tkey> keys = new List<Tkey>();
    private List<Tvalue> values = new List<Tvalue>();
    private int size = 0;
    private bool Descending;
    private int Compare(Tkey a, Tkey b) { return (Descending ? a.CompareTo(b) : b.CompareTo(a)); }

    public PriorityQueue(bool b = true) { Clear(); Descending = b; }
    public int Count() { return size; }
    public void Clear() { keys = new List<Tkey>(); values = new List<Tvalue>(); size = 0; }
    public void Add(Tkey e, Tvalue v)
    {
        keys.Add(e);
        values.Add(v);
        int x = size;
        size += 1;
        while (x != 0)
        {
            int par = (x % 2 == 0 ? x - 2 : x - 1) / 2;
            if (Compare(keys[par], e) <= 0) break;
            Tkey a = keys[x]; keys[x] = keys[par]; keys[par] = a;
            Tvalue b = values[x]; values[x] = values[par]; values[par] = b;
            x = par;
        }
    }
    public void Poll()
    {
        Tkey k = keys[size - 1];
        Tvalue v = values[size - 1];
        int x = 0;
        size--;
        if (size == 0) { Clear(); return; }
        keys.RemoveAt(size);
        values.RemoveAt(size);
        while (true)
        {
            int l = x * 2 + 1;
            int r = x * 2 + 2;
            if (size - 1 < l) break;
            int y = 0;
            if (size - 1 == l) { y = l; }
            else if (Compare(keys[l], keys[r]) == 1) { y = r; }
            else { y = l; }
            if (Compare(keys[y], k) > 0) break;
            keys[x] = keys[y];
            values[x] = values[y];
            x = y;
        }
        keys[x] = k;
        values[x] = v;
    }
    public Tvalue Take() { Tvalue ret = values[0]; Poll(); return ret; }
    public Tvalue Peek() { return values[0]; }
    public void Debug()
    {
        Console.Write("key   : ");
        foreach (var k in keys) Console.Write(k + " ");
        Console.WriteLine();
        Console.Write("value : ");
        foreach (var k in values) Console.Write(k + " ");
        Console.WriteLine();
    }
}
