                    else
                    {
                        if (r < a)
                        {
                            min += a - r;
                        }
                        else if (a < l)
                        {
                            min += l - a;
                        }

                        if (set.Count % 2 == 0)
                        {
                            l = set[set.Count / 2 - 1];
                            r = set[set.Count / 2];
                        }
