                    while (r_ - l_ > 1)
                    {
                        int mid = (l_ + r_) / 2;
                        if (k[mid] < a) l_ = mid;
                        else r_ = mid;
                    }

                    int addIndex = l_ + 1;// 二分探索
                    if (addIndex < k.Count) k.Insert(addIndex, a);
                    else k.Add(a);
                    if (k.Count % 2 == 0)
                    {
                        int mid = k.Count / 2 - 1;
                        if (addIndex <= mid)
                        {
                            l += k[addIndex];
                            r += k[mid + 1];
                        }
                        else
                        {
                            r += k[addIndex];
                            l += k[mid];
                        }
                        x = k[mid];
                    }
                    else
                    {
                        int mid = k.Count / 2;
                        if (addIndex < mid)
                        {
                            l -= k[mid - 1];
                            l += k[addIndex];
                        }
                        else if (addIndex > mid)
                        {
                            r -= k[mid + 1];
                            r += k[addIndex];
                        }
                        x = k[mid];
                    }
                }
                else
                {
                    sb.AppendLine(x + " " + (r - l + offset));
                }

            }

            Draw1D(k.ToArray());
            Console.Write(sb);
        }


    }


