                        var right = alst[alst.Count / 2];
                        if (right < a) fx += a - right;
                        else if (a < left) fx += left - a;
                    }
                    else
                    {
                        var mid = alst[alst.Count / 2];
                        fx += Math.Abs(mid - a);
                    }
                    SortedAdd(alst, a);
                }
                else
                {
                    var minx = 0;
                    if (alst.Count % 2 == 0)//偶数
                    {
                        minx = alst[alst.Count / 2 - 1];
                    }
                    else
                    {
                        minx = alst[alst.Count / 2];
                    }
                    Console.WriteLine($"{minx} {sumb+fx}");
                }
            }
        }
        static void SortedAdd(List<int> lst, int key)
        {
            int min = 0;
            int max = lst.Count - 1;
            lst.Insert(binary_search(lst, key, min, max), key);
        }
        static int binary_search(List<int> lst, int key, int min, int max)
        {
            if (max < min)
                return min;

            int mid = min + (max - min) / 2;
            if (key < lst[mid])
            {
                return binary_search(lst, key, min, mid - 1);
            }
            if (lst[mid] < key)
            {
                return binary_search(lst, key, mid + 1, max);
            }
            else
            {
                return mid;
            }
        }
    }
