                            {
                                minQueue.Enqueue(-next, true);
                                next = maxQueue.Dequeue().Key;
                            }
                            minQueue.Enqueue(-center, true);
                            minSum += (next-center) * minQueue.Count;
                            maxSum -= (next - center) * minQueue.Count;
