        public void Run()
        {
            int Q = Input.ReadInt();

            long cons = 0;

            long v1 = 0;
            long v2 = 0;

            PriorityQueue<int> pq1 = new PriorityQueue<int>((d1, d2) => d1.CompareTo(d2) * (-1)); // 大きい順
            PriorityQueue<int> pq2 = new PriorityQueue<int>((d1, d2) => d1.CompareTo(d2));
            for (int q = 0; q < Q; q++)
            {
                var line = Input.ReadIntArray();
                int qt = line[0];
                if (qt == 1)
                {
                    int a = line[1];
                    int b = line[2];
                    if (pq1.Count() == 0)
                    {
                        cons += b;
                        pq1.Push(a);
                        v1 += a;
                    }
                    else
                    {
                        cons += b;
                        if (a <= pq1.Peek())
                        {
                            pq1.Push(a);
                            v1 += a;
                        }
                        else
                        {
                            pq2.Push(a);
                            v2 += a;
                        }
                    }

                    while (pq1.Count() < pq2.Count())
                    {
                        int v = pq2.Pop();
                        pq1.Push(v);
                        v1 += a;
                        v2 -= a;
                    }
                    while (pq1.Count() > pq2.Count() + 1)
                    {
                        int v = pq1.Pop();
                        pq2.Push(v);
                        v1 -= a;
                        v2 += a;
                    }
                }
                else
                {
                    int val = pq1.Count() == 0 ? 0 : pq1.Peek();
                    long vv = 0;
                    vv += val * pq1.Count();
                    vv -= v1;
                    vv += v2;
                    vv -= val * pq2.Count();
                    vv += cons;
                    Console.WriteLine($"{val} {vv}");
                }

            }
        }
