public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() => Calc() switch { bool b => b ? "Yes" : "No", double d => d.ToString("0.####################"), object o => o.ToString(), };
    public object Calc()
    {
        int Q = cr;
        sl = new PriorityQueue<int>((Q + 1) >> 1, ReverseComparer<int>.Default); sl.Add(int.MinValue);
        sr = new PriorityQueue<int>((Q + 1) >> 1); sr.Add(int.MaxValue);
        var res = new List<string>();
        _ = cr.Int;
        center = cr.Int;
        b = cr.Int;
        for (int i = 1; i < Q; i++)
        {
            int type = cr;
            if (type == 1)
            {
                int a = cr;
                b += cr.Long;
                var lc = sl.Count;
                var rc = sr.Count;
                if (a < center)
                {
                    if (lc < rc)
                    {
                        sl.Add(a);
                        lsum += a;
                    }
                    else
                    {
                        sr.Add(center);
                        rsum += center;
                        if (sl.Peek <= a)
                        {
                            center = a;
                        }
                        else
                        {
                            sl.Add(a);
                            lsum += a - (center = sl.Dequeue());
                        }
                    }
                }
                else
                {
                    if (lc < rc)
                    {
                        sl.Add(center);
                        lsum += center;
                        if (a <= sr.Peek)
                        {
                            center = a;
                        }
                        else
                        {
                            sr.Add(a);
                            rsum += a - (center = sr.Dequeue());
                        }
                    }
                    else
                    {
                        sr.Add(a);
                        rsum += a;
                    }
                }
            }
            else res.Add(Query());
        }
        return AllLines(res);
    }
    string Query()
    {
        return $"{center} {rsum - lsum - (long)center * (sr.Count - sl.Count) + b}";
    }
    PriorityQueue<int> sl;
    PriorityQueue<int> sr;
    long lsum = 0;
    long rsum = 0;
    int center = int.MinValue;
    long b = 0;
}



