using System;
using System.Linq;
using System.Collections.Generic;
class c
{
    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        var list = new List<long>();
        long plusSum = 0;
        long plusCount = 0;
        long minusSum = 0;
        long minusCount = 0;
        long b = 0;
        for (int i = 0; i < n; i++)
        {
            var line = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
            if (line[0] == 1)
            {
                list.Add(line[1]);
                if (line[1] >= 0)
                {
                    plusSum += line[1];
                    plusCount++;
                }
                else
                {
                    minusSum -= line[1];
                    minusCount++;
                }
                list = list.OrderBy(f => f).ToList();
                b += line[2];
            }
            else
            {
                long tmp = list[(list.Count() - 1) / 2];
                Console.WriteLine("{0} {1}", tmp, b + (plusSum + minusSum) - (plusCount * tmp) + (minusCount * tmp));
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class F
{
	static void Main()
	{
		var qs = new int[int.Parse(Console.ReadLine())].Select(_ => Console.ReadLine().Split().Select(int.Parse).ToArray());

		long m = 0, a = 0, b = 0;
		var l = new List<long>();
		var r = new List<string>();
		foreach (var q in qs)
		{
			if (q[0] == 1)
			{
				var toLeft = l.Count % 2 == 1 && q[1] < m;
				var i = l.BinarySearch(q[1]);
				if (i < 0) i = ~i;
				l.Insert(i, q[1]);

				var m2 = l[(l.Count - 1) / 2];
				if (toLeft) a += m - m2;
				a += Math.Abs(m2 - q[1]);
				m = m2;

				b += q[2];
			}
			else r.Add($"{m} {a + b}");
		}
		Console.WriteLine(string.Join("\n", r));
	}
}

