    {
        public object Calc()
        {
            var Q = consoleReader.Int();
            var result = new List<string>(Q);
            var sorted = new SortedCollection<int>();

            long bottom = 0;
            foreach (var query in consoleReader.RepeatSplitInt(Q))
            {
                if (query[0] == 1)
                {
                    sorted.Add(query[1]);
                    bottom += query[2];
                }
                else
                {
                    var C = sorted.Count;
                    var halfIndex = C / 2;
                    long sum = bottom;
                    if (C % 2 == 0)
                    {
                        for (int i = 0; i < halfIndex; i++)
                        {
                            sum += sorted[C - i - 1] - sorted[i];
                        }
                        result.Add($"{sorted[halfIndex - 1]} {sum}");
                    }
                    else
                    {
                        for (int i = 0; i < halfIndex; i++)
                        {
                            sum += sorted[C - i - 1] - sorted[i];
                        }
                        result.Add($"{sorted[halfIndex]} {sum}");
                    }
                }
            }

            return MultiLine(result);
        }

        class SortedCollection<T> : List<T>
        {
            private IComparer<T> Comparer { get; }
            public SortedCollection() : this(Comparer<T>.Default) { }
            public SortedCollection(IComparer<T> comparer) { this.Comparer = comparer; }
            public new void Add(T item)
            {
                base.Add(item);
                for (int i = this.Count - 2; i >= 0; i--)
                {
                    var current = this[i];
                    if (Comparer.Compare(item, current) < 0)
                        this[i + 1] = current;
                    else
                    {
                        this[i + 1] = item;
                        return;
                    }
                }
                this[0] = item;
            }
        }

