class PriorityQueue
  attr_accessor :data, :compare, :compare_method_name

  def initialize(array = [], compare_proc = nil)
    @data = []
    array.each { |a| push(a) }
    @compare_proc = compare_proc
    @compare = "small_compare"
  end

  def change_to_bigger
    @compare = "large_compare"
  end

  def push(element)
    current = @data.size
    while current > 0
      p = parent(current)
      break if compare_equal(@data[p], element)
      @data[current] = @data[p]
      current = p
    end
    @data[current] = element
  end

  def pop
    ret = @data[0]
    x = @data[-1]
    current = 0
    while have_child?(current)
      a = left_child(current)
      b = right_child(current)
      a = b if b < @data.size - 1 && compare(@data[b], @data[a])
      break if compare_equal(x, @data[a])
      @data[current] = @data[a]
      current = a
    end
    @data[current] = x
    @data.pop

    ret
  end

  def front
    @data[0]
  end

  def empty?
    @data.empty?
  end

  def size
    @data.size
  end

  private
  def parent(num)
    (num - 1) / 2
  end

  def left_child(num)
    num * 2 + 1
  end

  def right_child(num)
    num * 2 + 2
  end

  def have_child?(num)
    left_child(num) < @data.size - 1
  end

  def small_compare(a, b)
    a < b
  end

  def large_compare(a, b)
    a > b
  end

  def compare(a, b)
    return @compare_proc.call(a, b) unless @compare_proc.nil?
    send(@compare, a, b)
  end

  def compare_equal(a, b)
    return true if a == b
    compare(a, b)
  end
end

