  for i, a := range A {
    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}

func Insert(A *[]int, a int) int {
  if len((*A)) == 0 {
    (*A) = append((*A), a)
    return 0
  }
  if a <= (*A)[0] {
    (*A) = append((*A)[:1], (*A)[0:]...)
    (*A)[0] = a
    return 0
  }
  if (*A)[len((*A)) - 1] < a {
    (*A) = append((*A), a)
    return len((*A)) - 1
  }
  high := len((*A)) - 1
  low := 0
  for high - low > 1 {
    med := (high + low) / 2
    if a < (*A)[med] {
      high = med
    } else {
      low = med
    }
  }
  (*A) = append((*A)[:high + 1], (*A)[high:]...)
  (*A)[high] = a
  return high
}

