  S := 0
  B := 0
  for i := 0; i < Q; i++ {
    Query := NextIntVec()
    if Query[0] == 1 {
      a := Insert(&A, Query[1])
      B += Query[2]
      if len(A) % 2 == 0 {
        if a < len(A) / 2 {
          S += Query[1]
          L += A[len(A) / 2]
        } else {
          S += A[len(A) / 2 - 1]
          L += Query[1]
        }
      } else {
        if a < len(A) / 2 {
          S += Query[1] - A[len(A) / 2]
        } else if len(A) / 2 < a {
          L += Query[1] - A[len(A) / 2]
        }
      }
    } else {
      x := A[(len(A) - 1) / 2]
      fx := L - S + B
      WriteIntVec([]int{x, fx})
    }
  }
