type smallQ []int

func (pq *smallQ) Len() int { return len(*pq) }

// less なものから pop される
func (pq *smallQ) Less(i, j int) bool    { return (*pq)[i] > (*pq)[j] }
func (pq *smallQ) Swap(i, j int)         { (*pq)[i], (*pq)[j] = (*pq)[j], (*pq)[i] }
func (pq *smallQ) Push(item interface{}) { *pq = append(*pq, item.(int)) }

func (pq *smallQ) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[0 : n-1]
	return item
}

type bigQ []int

func (pq *bigQ) Len() int { return len(*pq) }

func (pq *bigQ) Less(i, j int) bool    { return (*pq)[i] < (*pq)[j] }
func (pq *bigQ) Swap(i, j int)         { (*pq)[i], (*pq)[j] = (*pq)[j], (*pq)[i] }
func (pq *bigQ) Push(item interface{}) { *pq = append(*pq, item.(int)) }

func (pq *bigQ) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[0 : n-1]
	return item
}

// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	Q := io.NextInt()

	sq := &smallQ{}
	heap.Init(sq)

	bq := &bigQ{}
	heap.Init(bq)

	sqSum := 0
	bqSum := 0
	bSum := 0

	updateQ := func(a, b int) {
		bSum += b

		if (*sq).Len() == 0 {
			heap.Push(sq, a)
			sqSum += a
			return
		}

		smallMax := (*sq)[0]

		if a <= smallMax {
			heap.Push(sq, a)
			sqSum += a
		} else {
			heap.Push(bq, a)
			bqSum += a
		}

		sL := (*sq).Len()
		bL := (*bq).Len()

		// 常に sL == bL もしくは sl == bL+1 とする
		// これにより、常に sq の max が最小値を与える最小の値となる
		if sL >= bL+2 {
			smallMax := heap.Pop(sq)
			heap.Push(bq, smallMax)
			sqSum -= smallMax.(int)
			bqSum += smallMax.(int)
		} else if bL >= sL+1 {
			bigMin := heap.Pop(bq)
			heap.Push(sq, bigMin)
			bqSum -= bigMin.(int)
			sqSum += bigMin.(int)
		}
	}

	selectQ := func() {
		x := (*sq)[0]
		v := x*(*sq).Len() - sqSum + bqSum - x*(*bq).Len() + bSum

		io.Println(x, v)
	}

	for i := 0; i < Q; i++ {
		q := io.NextInt()

		if q == 1 {
			a := io.NextInt()
			b := io.NextInt()
			updateQ(a, b)
		} else if q == 2 {
			selectQ()
		}
	}
}

