}
func NextInt() int {
  var n int
  n, _ = strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func WriteIntVec(A []int) {
  S := make([]string, len(A))
  for i, a := range A {
    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}

type Item struct {
  Comparison  int
}
type PriorityQueue []*Item
func (pq PriorityQueue) Len() int { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool {
  return pq[i].Comparison < pq[j].Comparison
}
func (pq PriorityQueue) Swap(i, j int) {
  pq[i], pq[j] = pq[j], pq[i]
}
func (pq *PriorityQueue) Pop() interface{} {
  old := *pq
  n := len(old)
  item := old[n - 1]
  *pq = old[0:n - 1]
  return item
}
func (pq *PriorityQueue) Push(x interface{}) {
  item := x.(*Item)
  *pq = append(*pq, item)
}

func Insert(L, S *PriorityQueue, C *[]int, a int) (l, s int) {
  if len((*C)) > 0 {
    c := (*C)[0]
    (*C) = make([]int, 0)
    if a < c {
      heap.Push(L, &Item{c})
      heap.Push(S, &Item{-a})
      return c, a
    } else {
      heap.Push(L, &Item{a})
      heap.Push(S, &Item{-c})
      return a, c
    }
  } else if L.Len() == 0 {
    (*C) = append((*C), a)
    return 0, 0
  } else {
    l := heap.Pop(L).(*Item).Comparison
    s := heap.Pop(S).(*Item).Comparison
    s *= -1
    if a < s {
      heap.Push(L, &Item{l})
      heap.Push(S, &Item{-a})
      (*C) = append((*C), s)
      return 0, a - s
    } else if l < a {
      heap.Push(L, &Item{a})
      heap.Push(S, &Item{-s})
      (*C) = append((*C), l)
      return a - l, 0
    } else {
      heap.Push(L, &Item{l})
      heap.Push(S, &Item{-s})
      (*C) = append((*C), a)
      return 0, 0
    }
  }
}

func main() {
  Q := NextInt()
  B := 0
  var x int
  var Large, Small PriorityQueue
  L, S := 0, 0
  C := make([]int, 0)
  for i := 0; i < Q; i++ {
    Query := NextIntVec()
    if Query[0] == 1 {
      l, s := Insert(&Large, &Small, &C, Query[1])
      L += l
      S += s
      B += Query[2]
    } else {
      if len(C) > 0 {
        x = C[0]
      } else {
        x = Small[len(Small) - 1].Comparison * -1
      }
      fx := L - S + B
      WriteIntVec([]int{x, fx})
    }
  }
  Output()
}

