	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

func main() {
	var q int
	fmt.Scan(&q)

	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	la := &InverseInt64Heap{}
	ra := &Int64Heap{}
	var laSum int64
	var raSum int64
	heap.Init(la)
	heap.Init(ra)
	var bSum int64
	for i := 0; i < q; i++ {
		scanner.Scan()
		o, _ := strconv.Atoi(scanner.Text())

		if o == 1 {
			scanner.Scan()
			a, _ := strconv.Atoi(scanner.Text())
			aa := int64(a)
			if len(*la) == 0 {
				heap.Push(la, aa)
				laSum += aa
			} else if (*la)[0] < aa {
				heap.Push(ra, aa)
				raSum += aa
				if la.Len() < ra.Len() {
					v := heap.Pop(ra).(int64)
					raSum -= v
					heap.Push(la, v)
					laSum += v
				}
			} else {
				heap.Push(la, aa)
				laSum += aa
				if la.Len()-ra.Len() > 1 {
					v := heap.Pop(la).(int64)
					laSum -= v
					heap.Push(ra, v)
					raSum += v
				}
			}
			// fmt.Printf("la: %v\nlaSum: %d\nra: %v\nraSum: %d\n", *la, laSum, *ra, raSum)
			scanner.Scan()
			b, _ := strconv.Atoi(scanner.Text())
			bSum += int64(b)
		} else {
			x := (*la)[0]
			fx := bSum + (x * int64(la.Len())) - laSum + (-x * int64(ra.Len())) + raSum
			fmt.Printf("%d %d\n", x, fx)
		}
	}
}

