func main() {
  const INF int64 = 10000000000
  input := Input{bufio.NewReaderSize(os.Stdin,1000000)}
  q,_,_ := input.NextInts(true)
  var l,r PriorityQueue
  heap.Init(&l);heap.Push(&l,&Item{priority:INF})
  heap.Init(&r);heap.Push(&r,&Item{priority:INF})
  var x,y,m int64
  for k:=0;k<q;k++ {
    n,a,b := input.NextInts(false)
    if n == 2 {
      fmt.Println(m,x+y)
    } else {
      y += b
      lb := heap.Pop(&l).(*Item)
      ub := heap.Pop(&r).(*Item)
      if a < -lb.priority {
        x += -lb.priority-a
        heap.Push(&l,&Item{priority:-a})
        heap.Push(&l,&Item{priority:-a})
        heap.Push(&r,&Item{priority:-lb.priority})
        heap.Push(&r,&Item{priority:ub.priority})
      } else if ub.priority < a {
        x += a-ub.priority
        heap.Push(&l,&Item{priority:lb.priority})
        heap.Push(&l,&Item{priority:-ub.priority})
        heap.Push(&r,&Item{priority:a})
        heap.Push(&r,&Item{priority:a})
      } else {
        heap.Push(&l,&Item{priority:lb.priority})
        heap.Push(&l,&Item{priority:-a})
        heap.Push(&r,&Item{priority:ub.priority})
        heap.Push(&r,&Item{priority:a})
      }
      t := heap.Pop(&l).(*Item)
      m = -t.priority
      heap.Push(&l,&Item{priority:-m})
    }
  }
}

type Item struct {
  priority int64
  index int
}
type PriorityQueue []*Item
func(pq PriorityQueue) Len() int {
  return len(pq)
}
func(pq PriorityQueue) Swap(i,j int) {
  pq[i],pq[j] = pq[j],pq[i]
  pq[i].index = i
  pq[j].index = j
}
func(pq PriorityQueue) Less(i,j int) bool {
  return pq[i].priority < pq[j].priority
}
func(pq *PriorityQueue) Push(x interface{}) {
  var n int = len(*pq)
  var item *Item = x.(*Item)
  item.index = n
  *pq = append(*pq,item)
}
func(pq *PriorityQueue) Pop() interface{} {
  var old PriorityQueue = *pq
  var n int = len(old)
  var item *Item = old[n-1]
  item.index = -1
  *pq = old[0:n-1]
  return item
}

