    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(i *Input) NextInts(single bool) (int,int64,int64) {
  s := strings.Split(i.NextLine()," ")
  x,_ := strconv.Atoi(s[0])
  if single || len(s) == 1 { return x,0,0 }
  y,_ := strconv.ParseInt(s[1],10,64)
  z,_ := strconv.ParseInt(s[2],10,64)
  return x,y,z
}

