			b += scanInt()
			c++

			now := pq0[len(pq0)-1]
			if now < a {
				pq1.Push(a)
			} else {
				pq0.Push(a)
			}

			if len(pq0) < len(pq1) {
				pq0.Push(pq1.Pop().(int))
			}

			if len(pq0) > len(pq1)+1 {
				pq1.Push(pq0.Pop().(int))
			}

			mid = pq0[len(pq0)-1]

			if c&1 == 0 {
				ans += abs(mid - now)
			}

			ans += abs(mid - a)

		} else {
