	ra := &Int64Heap{}
	var laSum int64
	var raSum int64
	heap.Init(la)
	heap.Init(ra)
	var bSum int64
	for i := 0; i < q; i++ {
		scanner.Scan()
		o, _ := strconv.Atoi(scanner.Text())

		if o == 1 {
			scanner.Scan()
			a, _ := strconv.Atoi(scanner.Text())
			aa := int64(a)
			if len(*la) == 0 {
				heap.Push(la, aa)
				laSum += aa
			} else if (*la)[0] < aa {
				heap.Push(ra, aa)
				raSum += aa
				if la.Len() < ra.Len() {
					v := heap.Pop(ra).(int64)
					raSum -= v
					heap.Push(la, v)
					laSum += v
				}
			} else {
				heap.Push(la, aa)
				laSum += aa
				if la.Len()-ra.Len() > 1 {
					v := heap.Pop(la).(int64)
					laSum -= v
					heap.Push(ra, v)
					raSum += v
				}
