#!/usr/bin/perl
use Data::Dumper;
my ($q_n) = map { $_ - 0 } split(/\s+/,<STDIN>);
my @a = ();
my @s_a = ();
my $sum_b = 0;
for(my $i=0;$i<$q_n;$i++){
  my @q = map { $_ - 0 } split(/\s+/,<STDIN>);
  if( $q[0] == 1 ){
    $sum_b += $q[2];
    my $pos = &ins_pos($q[1]);
    $#a ++;
    $#s_a ++;
    for(my $i=$#a;$i>=$pos+1;$i--){
      $a[$i] = $a[$i-1];
      $s_a[$i] = $s_a[$i-1] + $q[1];
    }
    $a[$pos] = $q[1];
    $s_a[$pos] = ($pos == 0 ? 0 : $s_a[$pos-1]) + $q[1];
    #print &Dumper(\@a,\@s_a);
  }
  if( $q[0] == 2 ){
    if( $#a < 0 ){
      print "0 0\n";
    } elsif( $#a == 0 ){
      print "$a[0] $sum_b\n";
    } elsif( $#a == 1 ){
      my $v = $sum_b + abs($a[0] - $a[1]);
      print "$a[0] $v\n";
    } else {
      my $m_i = int($#a / 2);
      my $aa = $a[$m_i];
      my $v = ( $m_i * $a[$m_i] - $s_a[$m_i - 1] ) + ( $s_a[$#s_a] - $s_a[$m_i] - ($#a - $m_i)*$a[$m_i] ) + $sum_b;
      print "$a[$m_i] $v\n";
    }
  }
}

exit(0);

sub ins_pos {
  my $v = shift;
  if( $#a<0 ){
    return 0;
  }
  if( $#a == 0 ){
    return ( ( $a[0] > $v ) ? 0 : 1 );
  }
  if( $a[$#a] < $v ){
    return 1+$#a;
  }
  my $lb = 0;
  my $rb = $#a;
  my $p = -1;
  while($lb<$rb-1){
    my $mb = int(($lb + $rb)/2);
    if( $a->[$mb] == $v ){
      $p = $mb;
      last;
    }
    if( $a->[$mb] > $v ){
      $rb = $mb;
    } else {
      $lb = $mb;
    }
  }
  $p = $rb if $p<0;
  return $p;
}

