auto solve( long[][] qss )
{
	string[] anss;
	auto c  = 0L;
	auto x  = 0L;
	auto lt = 0L;
	auto lq = heapify( new long[ 10L ^^ 5 + 10 ], 0 );
	auto rt = 0L;
	auto rq = heapify!( ( x, y ) => y < x )( new long[ 10L ^^ 5 + 10 ], 0 );
	auto bt = 0L;
	foreach( qs; qss )
	{
		final switch( qs[ 0 ] )
		{
			case 1:
				// 左右のキューの長さが一致するようにaを追加（全体の個数が奇数の場合は左に寄せる）
				c++;
				if( qs[ 1 ] <= x )
				{
					lt += qs[ 1 ];
					lq.insert( qs[ 1 ] );
					if( lq.length != rq.length + c % 2 )
					{
						rt += lq.front;
						rq.insert( lq.front );
						lt -= lq.front;
						lq.popFront();
					}
				}
				else
				{
					rt += qs[ 1 ];
					rq.insert( qs[ 1 ] );
					if( lq.length != rq.length + c % 2 )
					{
						lt += rq.front;
						lq.insert( rq.front );
						rt -= rq.front;
						rq.popFront();
					}
				}

				// 中央値をxとして使う（全体の個数が奇数の場合は左に寄せる）
				x = lq.front;
				bt += qs[ 2 ];
				break;

			case 2:
				// 左右のキューの合計が x == 0 のときの答えなので、xに合わせてずらす
				auto ltx = ( x * ( lq.length.signed - 1 ) ) - ( lt - x );
				auto rtx = rt - ( x * rq.length.signed );
				anss ~= format( "%s %s", x, ltx + rtx + bt );
				break;
		}
	}
	return anss.join( "\n" );
}

