void main() {
    auto Q = readln.chomp.to!int;
    auto pqmin = new BinaryHeap!(Array!long, "a < b");
    auto pqmax = new BinaryHeap!(Array!long, "a > b");
    long seppen = 0;
    long left = 0;
    long right = 0;
    int cnt = 0;

    while (Q--) {
        auto s = readln.split.map!(to!long);
        if (s[0] == 1) {
            auto a = s[1];
            auto b = s[2];
            seppen += b;
            if (!pqmin.empty && a >= pqmin.front) {
                pqmax.insert(a);
                right += a;
            } else {
                pqmin.insert(a);
                left += a;
            }
            while (pqmax.length.to!int - pqmin.length.to!int > 1) {
                pqmin.insert(pqmax.front);
                left += pqmax.front;
                right -= pqmax.front;
                pqmax.removeFront;
            }
            while (pqmin.length.to!int - pqmax.length.to!int > 1) {
                pqmax.insert(pqmin.front);
                right += pqmin.front;
                left -= pqmin.front;
                pqmin.removeFront;
            }
        } else {
            long ans;
            long l = left;
            long r = right;
            long lcnt = pqmin.length.to!long;
            long rcnt = pqmax.length.to!long;
            if (pqmax.length == pqmin.length) {
                ans = pqmin.front;
                l -= pqmin.front;
                lcnt -= 1;
            } else if (pqmax.length > pqmin.length) {
                ans = pqmax.front;
                r -= pqmax.front;
                rcnt -= 1;
            } else {
                ans = pqmin.front;
                l -= pqmin.front;
                lcnt -= 1;
            }
            writeln(ans, " ", ans * lcnt - l - ans * rcnt + r + seppen);
        }
    }
}

import std.algorithm, std.container, std.conv, std.math, std.range, std.typecons, std.stdio, std.string;

auto rdsp(){return readln.splitter;}
void pick(R,T)(ref R r,ref T t){t=r.front.to!T;r.popFront;}
void pickV(R,T...)(ref R r,ref T t){foreach(ref v;t)pick(r,v);}
void readV(T...)(ref T t){auto r=rdsp;foreach(ref v;t)pick(r,v);}

void main()
{
  int q; readV(q);

  auto a1 = Array!int().heapify!"a<b", s1 = 0L;
  auto a2 = Array!int().heapify!"a>b", s2 = 0L;
  auto bs = 0L, u = 0, c = 0;

  foreach (_; 0..q) {
    auto rd = rdsp;
    int typ; pick(rd, typ);
    switch (typ) {
    case 1:
      int a, b; pickV(rd, a, b);
      bs += b;

      if (u%2 == 0) {
        if (a1.empty || a2.empty) {
          c = a;
        } else if (a1.front > a) {
          a1.insert(a); s1 += a;
          c = a1.front; a1.removeFront(); s1 -= c;
        } else if (a2.front < a) {
          a2.insert(a); s2 += a;
          c = a2.front; a2.removeFront(); s2 -= c;
        } else {
          c = a;
        }
      } else {
        a1.insert(c); s1 += c;
        a1.insert(a); s1 += a;
        auto t = a1.front; a1.removeFront(); s1 -= t;
        a2.insert(t); s2 += t;
      }

      ++u;
      break;
    case 2:
      if (u%2 == 0)
        writeln(a1.front, " ", s2-s1+bs);
      else
        writeln(c, " ", s2-s1+bs);
      break;
    default:
      assert(0);
    }
  }
}

