void main() {
    auto ql = new BinaryHeap!(Array!int, "a < b"); // 大きい値から取り出す
    auto qr = new BinaryHeap!(Array!int, "a > b"); // 小さい値から取り出す
    long suml = 0;
    long sumr = 0;
    long sumb = 0;

    int Q = readint;
    while (Q--) {
        auto t = readints;
        if (t[0] == 1) { // 1 a b
            int a = t[1];
            int b = t[2];
            sumb += b;

            if (ql.length == 0 || a < ql.front) {
                suml += a;
                ql.insert(a);
                if (ql.length > qr.length + 1) { // qr に要素を移動
                    int x = ql.front;
                    suml -= x;
                    sumr += x;
                    qr.insert(x);
                    ql.popFront();
                }
            }
            else {
                sumr += a;
                qr.insert(a);
                if (ql.length < qr.length) { // ql に要素を移動
                    int x = qr.front;
                    suml += x;
                    sumr -= x;
                    ql.insert(x);
                    qr.popFront();
                }
            }
        }
        else {
            int m = ql.front; // 中央値
            long v = sumb + (m * ql.length - suml) + (-m * qr.length + sumr);
            writeln(m, " ", v);
        }
    }
}

