  long left(long x) {
    long l = 0;
    long r = ys.length;
    while (r - l > 1) {
      long c = (l + r) / 2;
      if (ys[c] <= x) {
        l = c;
      } else {
        r = c;
      }
    }
    return ys[l];
  }

  long right(long x) {
    long l = -1;
    long r = ys.length - 1;
    while (r - l > 1) {
      long c = (l + r) / 2;
      if (ys[c] >= x) {
        r = c;
      } else {
        l = c;
      }
    }
    return ys[r];
  }

  long f(long x) {
    long res = 0;

    long y = aa[left(x)];
    long l = seg.query(0, y + 1);
    long l2 = seg2.query(0, y + 1);
    res += x * l - l2;

    long z = aa[right(x)];
    long r = seg.query(z, ys.length);
    long r2 = seg2.query(z, ys.length);
    res += r2 - x * r;

    res += sumB;

    return res;
  }

  foreach (xs; xss) {
    if (xs[0] == 1) {
      long a = xs[1];
      long y = aa[a];
      seg.update(y, seg.get(y) + 1);
      seg2.update(y, seg2.get(y) + a);
      long b = xs[2];
      sumB += b;
    } else {
      long c = 0;
      foreach_reverse (i; 0 .. 35) {
        long t = 1L << i;
        long x = clamp(c - t, -T, T);
        long y = clamp(c, -T, T);
        long z = clamp(c + t, -T, T);
        long fx = f(x);
        long fy = f(y);
        long fz = f(z);
        if (fx <= fy) {
          c = x;
        } else if (fy <= fz) {
          c = y;
        } else {
          c = z;
        }
      }
      writeln(c, " ", f(c));
    }
  }
}

