	auto xh = new RedBlackTree!(long, "a>b", true);
	auto yh = new RedBlackTree!(long, "a<b", true);
	long z;
	bool hasZ;
	long xsum, ysum;
	long bsum;

	foreach(_; 0 .. q){

		print!1("0 xh:", xh[], " xsum:", xsum, " z:", (hasZ? z: 999), " yh:", yh[], " ysum:", ysum, " bsum:", bsum);
		int t = read.to!int;
		if(t == 1){
			long a = read.to!long;
			long b = read.to!long;
			print!1("xh.length:", xh.length, " yh.length:", yh.length, " hasZ:", hasZ);
			print!1("1 xh:", xh[], " xsum:", xsum, " z:", (hasZ? z: 999), " yh:", yh[], " ysum:", ysum, " bsum:", bsum);
			if(hasZ){
				if(a < z){
					print!1("X odd");
					xh.insert(a), xsum += a;
					yh.insert(z), ysum += z;
					hasZ = 0;
				}
