void main() {
  long Q;
  scanln(Q);

  long T = 1000000000;

  long[long] aa;
  long[][] xss = new long[][Q];
  foreach (i; 0 .. Q) {
    xss[i] = readln.split.to!(long[]);
    if (xss[i][0] == 1) {
      aa[xss[i][1]] = -1;
    }
  }
  aa[-T] = -1;
  aa[T] = -1;

  long[] ys = aa.byKey.array.sort!"a<b".array;
  foreach (i, y; ys) {
    aa[y] = i;
  }

  auto seg = SegTree!(
      long,
      "a+b",
      0,
  )(ys.length);
  auto seg2 = SegTree!(
      long,
      "a+b",
      0,
  )(ys.length);

  long sumB = 0;

  long left(long x) {
    long l = 0;
    long r = ys.length;
    while (r - l > 1) {
      long c = (l + r) / 2;
      if (ys[c] <= x) {
        l = c;
      } else {
        r = c;
      }
    }
    return ys[l];
  }

  long right(long x) {
    long l = -1;
    long r = ys.length - 1;
    while (r - l > 1) {
      long c = (l + r) / 2;
      if (ys[c] >= x) {
        r = c;
      } else {
        l = c;
      }
    }
    return ys[r];
  }

  long f(long x) {
    long res = 0;

    long y = aa[left(x)];
    long l = seg.query(0, y + 1);
    long l2 = seg2.query(0, y + 1);
    res += x * l - l2;

    long z = aa[right(x)];
    long r = seg.query(z, ys.length);
    long r2 = seg2.query(z, ys.length);
    res += r2 - x * r;

    res += sumB;

    return res;
  }

  foreach (xs; xss) {
    if (xs[0] == 1) {
      long a = xs[1];
      long y = aa[a];
      seg.update(y, seg.get(y) + 1);
      seg2.update(y, seg2.get(y) + a);
      long b = xs[2];
      sumB += b;
    } else {
      long c = -T;
      foreach_reverse (i; 0 .. 32) {
        long t = 1L << i;
        long x = clamp(c - 1, -T, T);
        long y = clamp(c + 1, -T, T);
        long fx = f(x);
        long fy = f(y);
        if (fx <= fy && x < y) {
          c = clamp(c - t, -T, T);
        } else {
          c = clamp(c + t, -T, T);
        }
      }
      long l = clamp(c - 1, -T, T);
      long r = clamp(c + 1, -T, T);
      if (f(l) <= f(c)) {
        c = l;
      } else if (f(r) < f(c)) {
        c = r;
      }
      writeln(c, " ", f(c));
    }
  }
}

