type PriorityQueue[T] = object
  a: seq[T]
  n: Natural
  cmp: (a: T, b: T) -> bool

proc initPriorityQueue[T](cmp: proc(a, b: T): bool): PriorityQueue[T] =
  result.a = newSeq[T](1)
  result.n = Natural(0)
  result.cmp = cmp

proc len[T](this: PriorityQueue[T]): Natural =
  this.n

proc enqueue[T](this: var PriorityQueue[T], e: T) =
  this.n += 1
  this.a.add(e)
  var i = this.a.len() - 1
  while i > 1 and this.cmp(this.a[i], this.a[i div 2]):
    swap(this.a[i], this.a[i div 2])
    i = i div 2

proc dequeue[T](this: var PriorityQueue[T]): T =
  this.n -= 1
  result = this.a[1]
  this.a[1] = this.a.pop()
  var i = 1
  while i < this.a.len():
    var j = i
    if i * 2 < this.a.len() and this.cmp(this.a[i * 2], this.a[j]):
      j = i * 2
    if i * 2 + 1 < this.a.len() and this.cmp(this.a[i * 2 + 1], this.a[j]):
      j = i * 2 + 1
    if i == j:
      break
    swap(this.a[i], this.a[j])
    i = j

proc front[T](this: PriorityQueue[T]): T =
  this.a[1]

# -------------------------------------------------- #

proc main() =
  var greater = initPriorityQueue[int]((a: int, b: int) => (a < b))
  greater.enqueue(10 ^ 10)
  var less = initPriorityQueue[int]((a: int, b: int) => (a > b))
  less.enqueue(-1 * 10 ^ 10)
  var gsum = 0
  var lsum = 0
  var bsum = 0
  let Q = input(int)
  for q in countup(1, Q):
    var query = input(seq[int])
    if query[0] == 1:
      var (a, b) = (query[1], query[2])
      bsum += b
      case less.len() - greater.len():
        of 0:
          if a <= greater.front():
            less.enqueue(a)
            lsum += a
          else:
            var gmin = greater.dequeue()
            greater.enqueue(a)
            gsum += a - gmin
            less.enqueue(gmin)
            lsum += gmin
        of 1:
          if a >= less.front():
            greater.enqueue(a)
            gsum += a
          else:
            var lmax = less.dequeue()
            less.enqueue(a)
            lsum += a - lmax
            greater.enqueue(lmax)
            gsum += lmax
        else:
          assert false
    elif query[0] == 2:
      if (less.len() + greater.len()) mod 2 == 0:
        echo less.front(), " ", gsum - lsum + bsum
      else:
        echo less.front(), " ", gsum - lsum + bsum + less.front()

main()

