from heapq import heappop, heappush


class Medians:
    def __init__(self):
        self.left = []
        self.right = []
        self.size_l = 0
        self.size_r = 0
        self.sum_l = 0
        self.sum_r = 0

    def add(self, n):
        if self.size_l > self.size_r:
            if self.right:
                if -self.left[0] > n:
                    heappush(self.size_l, -n)
                    self.size_l += 1
                    self.sum_l += n
                else:
                    heappush(self.right, n)
                    self.size_r += 1
                    self.sum_r += n
            else:
                if -self.left[0] > n:
                    a = -heappop(self.left)
                    self.sum_l -= a
                    heappush(self.right, a)
                    self.sum_r += a
                    heappush(self.left, -n)
                    self.sum_l += n
                else:
                    heappush(self.right, n)
                    self.sum_r += n
                self.size_r += 1
        else:
            if self.left:
                if self.right and self.right[0] < n:
                    heappush(self.right, n)
                    self.size_r += 1
                    self.sum_r += n
                else:
                    heappush(self.left, -n)
                    self.size_l += 1
                    self.sum_l += n
            else:
                heappush(self.left, -n)
                self.size_l += 1
                self.sum_l += n

    def get(self):
        if self.size_l >= self.size_r:
            v = -heappop(self.left)
            heappush(self.left, -v)
        else:
            v = heappop(self.right)
            heappush(self.right, v)
        return v


