class StreamMedian(object):
    def __init__(self):
        self.less = []
        self.more = []

    def __repr__(self):
        return "less: {},  more: {}".format(self.less, self.more)

    def push(self, x):
        if not self.less:
            heappush(self.less, -x)
        else:
            if x < self.get():
                heappush(self.less, -x)
                if len(self.less) + 1 > len(self.more):
                    heappush(self.more, -heappop(self.less))
            else:
                heappush(self.more, x)
                if len(self.less) < len(self.more):
                    heappush(self.less, -heappop(self.more))

    def get(self):
        return -self.less[0]

    def diffsum(self, x):
        lesssum = sum(abs(x + xp) for xp in self.less)
        moresum = sum(abs(x - xp) for xp in self.more)
        return lesssum + moresum


