class QueryProcessor(object):
    def __init__(self):
        self.first = []
        self.latter = []
        self.fir_sum = 0
        self.lat_sum = 0
        self.b_sum = 0

    def process_query(self, q):
        query = q.split()
        if int(query[0]) == 1:
            a, b = map(int, query[1:3])
            self.update(a, b)

        else:
            print(-self.first[0], self.find())

    def update(self, a: int, b: int):
        # append new element to first or latter
        if len(self.first) == len(self.latter) == 0:
            heappush(self.first, -a)
            self.fir_sum += a

        elif len(self.first) == len(self.latter):
            if a <= -self.first[0]:
                heappush(self.first, -a)
                self.fir_sum += a

            else:
                tmp = heappop(self.latter)
                heappush(self.first, -tmp)
                heappush(self.latter, a)
                self.fir_sum += tmp
                self.lat_sum += (a-tmp)

        elif len(self.first) - len(self.latter) == 1:
            if a <= -self.first[0]:
                tmp = -heappop(self.first)
                heappush(self.first, -a)
                heappush(self.latter, tmp)
                self.fir_sum += (a-tmp)
                self.lat_sum += tmp

            else:
                heappush(self.latter, a)
                self.lat_sum += a

        # modify sum of first, latter and b
        self.b_sum += b

    def find(self):
        center = -self.first[0]
        return center * len(self.first) - self.fir_sum \
                + self.lat_sum - center * len(self.latter) \
                + self.b_sum


