class Node(object):
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right: Node = None
        self.parent: Node = None
        self.isright = False

    def add_node(self, node):
        if node.value > self.value:
            if self.right is None:
                self.right = node
                node.parent = self
                node.isright = True
            else:
                self.right.add_node(node)
        else:
            if self.left is None:
                self.left = node
                node.parent = self
                node.isright = False
            else:
                self.left.add_node(node)

    def search_nearest_node(self, value):
        if value > self.value:
            if self.right is None:
                return self
            else:
                return self.right.search_nearest_node(value)
        else:
            if self.left is None:
                return self
            else:
                return self.left.search_nearest_node(value)

    def find_lr_value(self, value):
        nearest = self.search_nearest_node(value)
        if nearest.value > value:
            right = nearest.value
            current = nearest
            while True:
                if current.isright:
                    break
                else:
                    current = current.parent
            left = current.value
            return left, right

        else:
            left = nearest.value
            current = nearest
            while True:
                if not current.isright:
                    break
                else:
                    current = current.parent
            right = current.value
            return left, right

    def calc(self, value):
        result = abs(self.value -value)
        if self.left is not None:
            result += self.left.calc(value)
        if self.right is not None:
            result += self.right.calc(value)
        return result


