def update(S, L, M):
    _, a, b = S
    M[0] += b

    if len(L[0]) == len(L[1]):
        r0 = 0 if len(L[0]) == 0 else -1 * L[0][0]

        if len(L[1]) == 0 or a <= L[1][0]:
            heapq.heappush(L[0], -a)
            r1 = -1 * L[0][0]
            d = r1 - r0

            M[1] += d * (len(L[0]) - 1)
            M[1] += r1 - a
            M[2] += d * len(L[1])
        else:
            t = heapq.heappushpop(L[1], a)
            heapq.heappush(L[0], -t)
            r1 = -1 * L[0][0]
            d = r1 - r0
            M[1] += d * (len(L[0]) - 1)
            M[1] += r1 - t
            M[2] -= t - r0
            M[2] -= d * (len(L[1]) - 1)
            M[2] += a - r1

    else:
        r0 = 0 if len(L[0]) == 0 else -1 * L[0][0]
        if r0 <= a:
            heapq.heappush(L[1], a)
            M[2] += a + L[0][0]

        else:
            heapq.heappush(L[0], -a)
            t = -1 * heapq.heappop(L[0])
            heapq.heappush(L[1], t)

            r1 = -1 * L[0][0]
            d = r1 - r0

            M[1] += d * (len(L[0]) - 1)
            M[1] += r1 - a
            M[2] -= d * (len(L[1]) - 1)
            M[2] += t - r1
