import heapq


class Solver:

    def __init__(self):
        self.heap = []
        self.s = 0

    def add(self, a, b):
        if len(self.heap)==0:
            self.s = b
            self.heap = [a]
            return

        i = self.minidx()
        x0 = self.heap[i]

        heapq.heappush(self.heap, a)

        j = self.minidx()
        x1 = self.heap[j]

        if x0 == x1:
            self.s += b + abs(x0-a)
        else:
            dx = x1 - x0
            n1 = len(self.heap[:j])
            n2 = len(self.heap[j+1:])
            self.s += (b + (n1 - n2) * dx) + abs(x1 - a)
        # print(f"s={self.s}")

    def minidx(self):
        n = len(self.heap)
        idx = n//2 - (n%2==0)
        return idx

    def getmin(self):
        return self.heap[self.minidx()], self.s


