class StreamMedian(object):
    def __init__(self):
        self.left = []
        self.right = []

    def __repr__(self):
        return "left: {},  right: {}".format(self.left, self.right)

    def __len__(self):
        return len(self.left) + len(self.right)

    def push(self, x):
        if not self.left:
            self._push_left(x)
        else:
            if x < self._peek_left():
                self._push_left(x)
                if len(self.left) + 1 > len(self.right):
                    self._push_right(self._pop_left())
            else:
                self._push_right(x)
                if len(self.left) < len(self.right):
                    self._push_left(self._pop_right())

    def _push_left(self, x):
        heappush(self.left, -x)

    def _push_right(self, x):
        heappush(self.right, x)

    def _pop_left(self):
        return -heappop(self.left)

    def _pop_right(self):
        return heappop(self.right)

    def _peek_left(self):
        return -self.left[0]

    def is_empty(self):
        return len(self.left) == 0

    def get(self):
        if len(self.left) == len(self.right):
            res = [-self.left[0], self.right[0]]
        else:
            res = [-self.left[0]]
        return res


