                R.enqueue(a)
                sR += a
            else:
                L.enqueue(a)
                sL += a

            while len(R)-len(L) > 1:
                L.enqueue(M)
                sL += M

                M = R.dequeue()
                sR -= M

            while len(L) > len(R):
                R.enqueue(M)
                sR += M

                M = L.dequeue()
                sL -= M

