    def lower_bound(self, x):#和がx以上になる最小のインデックス
        l, r = 1, self.n
        while r-l > 1:
            index = (r+l)//2
            if self.sum(index) >= x:
                r = index
            else:
                l = index

        if self.sum(l) >= x:
            return l
        return r

    def upper_bound(self, x):#和がx以下になる最大のインデックス
        if x <= 0:
            return  0
        l, r = 0, self.n
        while r-l > 1:
            index = (r+l)//2
            if self.sum(index) <= x:
                l = index
            else:
                r = index

        if self.sum(r) <= x:
            return r
        return l


