            }
            A.orderd_insert(a);
            b_sum += b;
        } else if kind == 2 {
            let n = A.len();
            let x = A.get((n-1)/2);
            let mut sum_abs = 0;
            for i in 0..n {
                let a = A.get(i);
                sum_abs += i64::abs(a-x);
            }
            println!("{} {}", x, sum_abs+b_sum);
        } else {
