use std::ops::Range;
struct BIT { size: usize, array: Vec<i64> }
impl BIT {
    fn new(n: usize) -> BIT {
        BIT  { size: n, array: vec![0; n + 1] }
    }
    fn add(&mut self, idx: usize, w: i64) {
        let mut x = idx + 1;
        while x <= self.size {
            self.array[x] += w;
            let xi = x as i64;
            x += (xi&-xi) as usize;
        }
    }
    fn sum_up(&self, idx: usize) -> i64 { // [0, idx)
        let mut sum = 0;
        let mut x = idx;
        while x > 0 {
            sum += self.array[x];
            let xi = x as i64;
            x -= (xi&-xi) as usize;
        }
        sum
    }
    fn sum(&self, range: Range<usize>) -> i64 {
        self.sum_up(range.end) - self.sum_up(range.start)
    }
    fn at(&self, idx: usize) -> i64 {
        self.sum(idx..idx+1)
    }
    fn to_vec(&self) -> Vec<i64> {
        let mut a = vec![];
        for i in 0..self.size {
            a.push(self.at(i));
        }
        a
    }
}

