#[derive(Debug)]
struct MedianHeap {
    head: std::collections::BinaryHeap<i64>,
    tail: std::collections::BinaryHeap<i64>,
    sum_head: i64,
    sum_tail: i64
}
#[derive(Debug, PartialEq, Eq)]
enum Median {
    None,
    Just(i64),
    Between(i64, i64),
}
impl MedianHeap {
    fn new() -> MedianHeap {
        MedianHeap {
            head: std::collections::BinaryHeap::new(),
            tail: std::collections::BinaryHeap::new(),
            sum_head: 0,
            sum_tail: 0,
        }
    }
    fn len(&self) -> usize {
        (self.head.len() + self.tail.len()) / 2
    }
    fn push(&mut self, x: i64) {
        match (self.head.peek(), self.tail.peek()) {
            (None, None) => {
                self.head.push(x);
                self.tail.push(-x);
                self.sum_head = x;
                self.sum_tail = x;
            },
            (Some(&a), Some(&b)) => {
                let b = -b;
                if a <= x && x <= b {
                    self.head.push(x);
                    self.tail.push(-x);
                    self.sum_head += x;
                    self.sum_tail += x;
                } else if x < a {
                    self.head.push(x);
                    self.head.push(x);
                    let _ = self.head.pop();
                    self.tail.push(-a);
                    self.sum_head += x + x;
                    self.sum_head -= a;
                    self.sum_tail += a;
                } else {
                    self.tail.push(-x);
                    self.tail.push(-x);
                    let _ = self.tail.pop();
                    self.head.push(b);
                    self.sum_tail += x + x;
                    self.sum_tail -= b;
                    self.sum_head += b;
                }
            },
            _ => {}
        }
    }
    fn peek(&self) -> Median {
        let n = self.len();
        if n == 0 {
            Median::None
        } else if n % 2 == 1 {
            Median::Just(*self.head.peek().unwrap())
        } else {
            let a = self.head.peek().unwrap();
            let b = self.tail.peek().unwrap();
            Median::Between(*a, -b)
        }
    }
}

