        q: usize,
    }
    let inf = 1i64 << 50;
    let mut base = 0;
    let mut tree = Trie::new();
    let mut center_x = 0;
    let mut dd = 0;
    for qi in 0..q {
        // eprintln!("qi={}", qi);
        input! {
            parser = parser,
            t: usize,
        }
        if t == 1 {
            input! {
                parser = parser,
                a: i64,
                b: i64,
            }
            let a = (a + 1_000_000_000) as u32;
            // eprintln!("insert {}", a);
            tree = Trie::insert(&tree, a);
            let mut ts = vec![];
            Trie::to_vec(&tree, &mut ts);
            // eprintln!("tree = {:?}", ts);
            base += b;
            if qi == 0 {
                center_x = a;
            } else {
                // eprintln!("center_x = {}", center_x);
                let prev_center_i = Trie::x_to_i(&tree, center_x, 31);
                let center_i = (tree.len() - 1) / 2;
                // eprintln!("dd_1 = {}", dd);
                if center_x <= a {
                    dd += a as i64 - center_x as i64;
                } else {
                    dd += center_x as i64 - a as i64;
                }
                // eprintln!("dd_2 = {}", dd);
                if center_i < prev_center_i {
                    // eprintln!("a");
                    let new_center = Trie::i(&tree, center_i);
                    dd += (tree.len() - center_i) as i64 * (center_x as i64 - new_center as i64);
                    dd -= tree.len() as i64 * (center_x as i64 - new_center as i64);
                    center_x = new_center;
                } else if prev_center_i < center_i {
                    // eprintln!("b");
                    let new_center = Trie::i(&tree, center_i);
                    dd -=
                        (tree.len() - center_i - 1) as i64 * (new_center as i64 - center_x as i64);
                    dd += tree.len() as i64 * (new_center as i64 - center_x as i64);
                    center_x = new_center;
                }
                // eprintln!("dd_3 = {}", dd);
            }
        } else if t == 2 {
            let i = (tree.len() - 1) / 2;
            let t = Trie::i(&tree, i);
            writeln!(buf, "{} {}", t as i64 - 1_000_000_000, base + dd);
        }
    }

    buf
}

use std::collections::BTreeMap;
use std::io::*;
use std::str::FromStr;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn insert(ps: &mut Vec<BTreeMap<i64, usize>>, offsets: &mut Vec<i64>, a: i64, cnt: i64, lr: usize) {
    let la = -*ps[0].iter().next().unwrap().0;
    let ra = *ps[1].iter().next().unwrap().0;
    if lr == 0 {
        let entry = ps[0].entry(-a).or_insert(0);
        *entry += 1;
        if a <= la {
            offsets[0] += (la - a).abs();
        } else {
            offsets[0] += (a - la).abs() * ((cnt + 1) / 2);
        }
    } else {
        let entry = ps[1].entry(a).or_insert(0);
        *entry += 1;
        if ra <= a {
            offsets[1] += (a - ra).abs();
        } else {
            offsets[1] += (ra - a).abs() * (cnt / 2);
        }
    }
}

fn push(ps: &mut Vec<BTreeMap<i64, usize>>, offsets: &mut Vec<i64>, a: i64, cnt: i64) {
    if cnt == 0 {
        ps[0].insert(-a, 1);
        return;
    }
    let la = -*ps[0].iter().next().unwrap().0;
    if cnt == 1 {
        if a < la {
            ps[1].insert(la, 1);
            ps[0].clear();
            ps[0].insert(-a, 1);
        } else {
            ps[1].insert(a, 1);
        }
        return;
    }
    let ra = *ps[1].iter().next().unwrap().0;
    if a < ra {
        insert(ps, offsets, a, cnt, 0);
        let la = -*ps[0].iter().next().unwrap().0;
        if cnt % 2 == 1 {
            *ps[0].iter_mut().next().unwrap().1 -= 1;
            if *ps[0].iter().next().unwrap().1 == 0 {
                ps[0].remove(&-la);
                let nla = -ps[0].iter().next().unwrap().0;
                offsets[0] -= (la - nla).abs() * ((cnt + 1) / 2);
            }
            insert(ps, offsets, la, cnt, 1);
        }
    } else {
        insert(ps, offsets, a, cnt, 1);
        let ra = *ps[1].iter().next().unwrap().0;
        if cnt % 2 == 0 {
            *ps[1].iter_mut().next().unwrap().1 -= 1;
            if *ps[1].iter().next().unwrap().1 == 0 {
                ps[1].remove(&ra);
                let nra = ps[1].iter().next().unwrap().0;
                offsets[1] -= (ra - nra).abs() * (cnt / 2);
            }
            insert(ps, offsets, ra, cnt, 0);
        }
    }
}

