fn solve(query: &Vec<(usize, i64, i64)>) -> String {
    let mut ret = "".to_string();
    let q = query.len();
    let mut cnt = 0;
    let mut b_sum = 0;
    let mut ps = vec![BTreeMap::<i64, usize>::new(); 2];
    let mut offsets = vec![0; 2];
    for i in 0..q {
        let t = query[i].0;
        if t == 1 {
            let a = query[i].1;
            let b = query[i].2;
            b_sum += b;
            push(&mut ps, &mut offsets, a, cnt);
            cnt += 1;
        } else {
            let lpos = if cnt == 0 {
                0
            } else {
                -*ps[0].iter().next().unwrap().0
            };
            let rpos = if cnt <= 1 {
                lpos
            } else {
                *ps[1].iter().next().unwrap().0
            };
            // println!("{:?} {} {}", offsets, lpos, rpos);
            let ans = offsets[0] + offsets[1] + cnt / 2 * (rpos - lpos).abs() + b_sum;
            println!("{} {}", lpos, ans);
            // ret += &format!("{} {}\n", lpos, ans);
        }
    }
    return ret;
}

fn naive(query: &Vec<(usize, i64, i64)>) -> String {
    let q = query.len();
    let mut ret = "".to_string();
    let mut b_sum = 0;
    let mut poss = vec![];
    for i in 0..q {
        if query[i].0 == 1 {
            poss.push(query[i].1);
            b_sum += query[i].2;
        } else {
            poss.sort();
            let mut ans = 1i64 << 60;
            let mut pos = poss[0];
            for &p1 in poss.iter() {
                let mut sum = b_sum;
                for &p2 in poss.iter() {
                    sum += (p1 - p2).abs();
                }
                if sum < ans {
                    ans = sum;
                    pos = p1;
                }
            }
            // println!("{} {}", pos, ans);
            ret += &format!("{} {}\n", pos, ans);
        }
    }
    return ret;
}

