use std::rc::Rc;

pub enum Trie {
    None,
    Leaf {
        x: u32,
    },
    Node {
        n: usize,
        left: Rc<Trie>,
        right: Rc<Trie>,
    },
}

impl Trie {
    pub fn new() -> Rc<Trie> {
        Rc::new(Trie::None)
    }
    pub fn insert(trie: &Rc<Trie>, x: u32) -> Rc<Trie> {
        Trie::insert_sub(trie, x, 31)
    }
    pub fn len(&self) -> usize {
        match self {
            &Trie::None => 0,
            &Trie::Leaf { x: _ } => 1,
            &Trie::Node {
                n: n,
                left: _,
                right: _,
            } => n,
        }
    }
    pub fn insert_sub(trie: &Rc<Trie>, x: u32, i: usize) -> Rc<Trie> {
        if i == 0 {
            Rc::new(Trie::Leaf { x: x })
        } else {
            if x & (1 << i) != 0 {
                let (left, right) = match trie.as_ref() {
                    &Trie::None => (
                        Rc::new(Trie::None),
                        Trie::insert_sub(&Rc::new(Trie::None), x, i - 1),
                    ),
                    &Trie::Leaf { x: _ } => {
                        panic!();
                    }
                    &Trie::Node {
                        n: _,
                        left: ref left,
                        right: ref right,
                    } => (left.clone(), Trie::insert_sub(&right, x, i - 1)),
                };
                Rc::new(Trie::Node {
                    n: left.len() + right.len(),
                    left: left,
                    right: right,
                })
            } else {
                let (left, right) = match trie.as_ref() {
                    &Trie::None => (
                        Trie::insert_sub(&Rc::new(Trie::None), x, i - 1),
                        Rc::new(Trie::None),
                    ),
                    &Trie::Leaf { x: _ } => {
                        panic!();
                    }
                    &Trie::Node {
                        n: _,
                        left: ref left,
                        right: ref right,
                    } => (Trie::insert_sub(&left, x, i - 1), right.clone()),
                };
                Rc::new(Trie::Node {
                    n: left.len() + right.len(),
                    left: left,
                    right: right,
                })
            }
        }
    }
    pub fn i(trie: &Rc<Trie>, i: usize) -> u32 {
        assert!(i < trie.len());
        match trie.as_ref() {
            &Trie::None => {
                panic!();
            }
            &Trie::Leaf { x: x } => {
                if i == 0 {
                    x
                } else {
                    panic!();
                }
            }
            &Trie::Node {
                n: _,
                left: ref left,
                right: ref right,
            } => {
                if i < left.len() {
                    Trie::i(left, i)
                } else {
                    Trie::i(right, i - left.len())
                }
            }
        }
    }
    pub fn x_to_i(trie: &Rc<Trie>, t: u32, i: usize) -> usize {
        match trie.as_ref() {
            &Trie::None => {
                panic!();
            }
            &Trie::Leaf { x: x } => {
                if i == 0 && x == t {
                    0
                } else {
                    panic!();
                }
            }
            &Trie::Node {
                n: _,
                left: ref left,
                right: ref right,
            } => {
                if t & (1 << i) != 0 {
                    left.len() + Trie::x_to_i(right, t, i - 1)
                } else {
                    Trie::x_to_i(left, t, i - 1)
                }
            }
        }
    }
    pub fn to_vec(trie: &Rc<Trie>, xs: &mut Vec<u32>) {
        match trie.as_ref() {
            &Trie::None => {}
            &Trie::Leaf { x: x } => {
                xs.push(*x);
            }
            &Trie::Node {
                n: _,
                left: ref left,
                right: ref right,
            } => {
                Trie::to_vec(&left, xs);
                Trie::to_vec(&right, xs);
            }
        }
    }
}

