    let mut lattersum = 0;
    let mut cons = 0;
    for _ in 0..q {
        let ty: i32 = get();
        if ty == 1 {
            // UPD
            let a: i64 = get();
            let b: i64 = get();
            if former.len() == latter.len() {
                former.push(a);
                formersum += a;
            } else {
                latter.push(-a);
                lattersum += a;
                if let (Some(mut x), Some(mut y)) = (former.pop(), latter.pop()) {
                    y = -y;
                    formersum -= x;
                    lattersum -= y;
                    if x > y {
                        std::mem::swap(&mut x, &mut y);
                    }
                    former.push(x);
                    latter.push(-y);
                    formersum += x;
                    lattersum += y;
                }
            }
            cons += b;
        } else {
            // QUE
            let x = former.peek().unwrap();
            let mut ans = -formersum + lattersum;
            ans += (former.len() as i64 - latter.len() as i64) * x;
            println!("{} {}", x, ans + cons);
        }
    }
}

