    }
}

fn solve() {
    let q = get!(usize);

    let queries = get!(String; q);
    let mut bsum = 0;
    let mut lheap = BinaryHeap::new();
    let mut rheap = BinaryHeap::new();
    lheap.push(std::isize::MIN);
    rheap.push(Rev(std::isize::MAX));
    for query in queries {
        if query == "2".to_string() {
            println!("{} {}", lheap.peek().unwrap(), bsum);
            continue;
        }
        let mut iter = query.split_whitespace();
        iter.next().unwrap();
        let a = iter.next().unwrap().parse::<isize>().unwrap();
        let b = iter.next().unwrap().parse::<isize>().unwrap();
        bsum += b;

        let l = lheap.peek().cloned().unwrap();
        let r = rheap.peek().cloned().unwrap().0;
        if a < l {
            lheap.push(a);
            lheap.push(a);
            let val = lheap.pop().unwrap();
            rheap.push(Rev(val));
            bsum += l - a;
        } else if a <= r {
            lheap.push(a);
            rheap.push(Rev(a));
        } else {
            rheap.push(Rev(a));
            rheap.push(Rev(a));
            let val = rheap.pop().unwrap().0;
            lheap.push(val);
            bsum += a - r;
        }
    }
}

