    let q: usize = sc.read();

    let mut bb = 0 as i64;

    use std::collections::BinaryHeap;
    let mut lq = BinaryHeap::new();
    let mut rq = BinaryHeap::new();

    let mut min_ans = 0;
    for _ in 0..q {
        let t:usize = sc.read();
        if t == 1 {
            let a:i64 = sc.read();
            let b:i64 = sc.read();

            let l = lq.pop();
            let r = rq.pop();

            match (l, r) {
                (None, None) => {
                    lq.push(a);
                },
                (Some(l), None) => {
                    if l < a {
                        lq.push(l);
                        rq.push(a);
                    } else {
                        lq.push(a);
                        rq.push(l);
                    }
                    min_ans = (l-a).abs();
                },
                (Some(l), Some(r)) => {
                    if l <= a && a <= r {
                        lq.push(l);
                        rq.push(r);
                        if lq.len() == rq.len() {
                            lq.push(a);
                        } else {
                            rq.push(a);
                        }
                    } else if a < l {
                        lq.push(a);
                        rq.push(r);
                        if lq.len() == rq.len() {
                            lq.push(l);
                        } else {
                            rq.push(l);
                        }
                        min_ans += *lq.peek().unwrap() + a;
                    } else if a > r {
                        lq.push(l);
                        rq.push(a);
                        if lq.len() == rq.len() {
                            lq.push(r);
                        } else {
                            rq.push(r);
                        }
                        min_ans += *lq.peek().unwrap() + a;
                    }

                },
                _ => unreachable!(),
            };

            bb += b;
        } else {
            let x = lq.peek().unwrap();
            println!("{} {}", x, min_ans+bb);
        }
    }
