fn insert(ps: &mut Vec<BinaryHeap<i64>>, offsets: &mut Vec<i64>, a: i64, lr: usize) {
    let la = *ps[0].peek().unwrap();
    let ra = -*ps[1].peek().unwrap();
    if lr == 0 {
        if a <= la {
            offsets[0] += (la - a).abs();
        } else {
            offsets[0] += (a - la).abs() * ps[0].len() as i64;
        }
        ps[0].push(a);
    } else {
        if ra <= a {
            offsets[1] += (a - ra).abs();
        } else {
            offsets[1] += (ra - a).abs() * ps[1].len() as i64;
        }
        ps[1].push(-a);
    }
}

fn push(ps: &mut Vec<BinaryHeap<i64>>, offsets: &mut Vec<i64>, a: i64) {
    if ps[0].len() == 0 {
        ps[0].push(a);
        return;
    }
    let la = *ps[0].peek().unwrap();
    if ps[1].len() == 0 {
        if a < la {
            ps[1].push(-la);
            ps[0].clear();
            ps[0].push(a);
        } else {
            ps[1].push(-a);
        }
        return;
    }
    let ra = -*ps[1].peek().unwrap();
    if a < ra {
        insert(ps, offsets, a, 0);
        let la = *ps[0].peek().unwrap();
        if ps[0].len() == ps[1].len() + 2 {
            ps[0].pop();
            let nla = *ps[0].peek().unwrap();
            offsets[0] -= (la - nla).abs() * ps[0].len() as i64;
            insert(ps, offsets, la, 1);
        }
    } else {
        insert(ps, offsets, a, 1);
        let ra = -*ps[1].peek().unwrap();
        if ps[0].len() < ps[1].len() {
            ps[1].pop();
            let nra = -ps[1].peek().unwrap();
            offsets[1] -= (ra - nra).abs() * ps[1].len() as i64;
            insert(ps, offsets, ra, 0);
        }
    }
}

fn main() {
    let q = read::<usize>();
    let mut query = vec![(0, 0, 0); q];
    for i in 0..q {
        query[i].0 = read::<usize>();
        if query[i].0 == 1 {
            query[i].1 = read::<i64>();
            query[i].2 = read::<i64>();
        }
    }
