    } else {
        solve();
    }
}
fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());

    input!{
        new_stdin_parser = parser,
        q: usize,
    }
    let mut A = Treap::new();
    let mut b_sum = 0;
    for _ in 0..q {
        input!{
            parser = parser,
            kind: usize,
        }
        if kind == 1 {
            input!{
                parser = parser,
                a: i64, b: i64,
            }
            A.orderd_insert(a);
            b_sum += b;
        } else if kind == 2 {
            let n = A.len();
            let x = A.get((n-1)/2);
            let mut sum_abs = 0;
            for i in 0..n {
                let a = A.get(i);
                sum_abs += i64::abs(a-x);
            }
            println!("{} {}", x, sum_abs+b_sum);
        } else {
            unreachable!()
        }
    }
}
