#[derive(Debug)]
struct MedianHeap {
    head: std::collections::BinaryHeap<i64>,
    tail: std::collections::BinaryHeap<i64>,
    sum_head: i64,
    sum_tail: i64
}
#[derive(Debug, PartialEq, Eq)]
enum Median {
    None,
    Just(i64),
    Between(i64, i64),
}
impl MedianHeap {
    fn new() -> MedianHeap {
        MedianHeap {
            head: std::collections::BinaryHeap::new(),
            tail: std::collections::BinaryHeap::new(),
            sum_head: 0,
            sum_tail: 0,
        }
    }
    fn len(&self) -> usize {
        (self.head.len() + self.tail.len()) / 2
    }
    fn push(&mut self, x: i64) {
        match (self.head.peek(), self.tail.peek()) {
            (None, None) => {
                self.head.push(x);
                self.tail.push(-x);
                self.sum_head = x;
                self.sum_tail = x;
            },
            (Some(&a), Some(&b)) => {
                let b = -b;
                if a <= x && x <= b {
                    self.head.push(x);
                    self.tail.push(-x);
                    self.sum_head += x;
                    self.sum_tail += x;
                } else if x < a {
                    self.head.push(x);
                    self.head.push(x);
                    let _ = self.head.pop();
                    self.tail.push(-a);
                    self.sum_head += x + x;
                    self.sum_head -= a;
                    self.sum_tail += a;
                } else {
                    self.tail.push(-x);
                    self.tail.push(-x);
                    let _ = self.tail.pop();
                    self.head.push(b);
                    self.sum_tail += x + x;
                    self.sum_tail -= b;
                    self.sum_head += b;
                }
            },
            _ => {}
        }
    }
    fn peek(&self) -> Median {
        let n = self.len();
        if n == 0 {
            Median::None
        } else if n % 2 == 1 {
            Median::Just(*self.head.peek().unwrap())
        } else {
            let a = self.head.peek().unwrap();
            let b = self.tail.peek().unwrap();
            Median::Between(*a, -b)
        }
    }
}

fn main() {
    let mut sc = Scanner::new();
    let mut med = MedianHeap::new();
    let n: usize = sc.cin();
    let mut base = 0;
    for _ in 0..n {
        let ty: usize = sc.cin();
        if ty == 1 {
            let a: i64 = sc.cin();
            let b: i64 = sc.cin();
            base += b;
            med.push(a);
        } else {

            match med.peek() {
                Median::None => {},
                Median::Just(x) => {
                    // trace!(&med.head, &med.tail);
                    // trace!(&med.sum_head, &med.sum_tail);
                    let left_sum = (med.head.len() as i64 - 1) / 2 * x - (med.sum_head - x) / 2;
                    let right_sum = (med.sum_tail - x) / 2 - (med.tail.len() as i64 - 1) / 2 * x;
                    // trace!(left_sum, right_sum);
                    put!(x, base + left_sum + right_sum);
                },
                Median::Between(x, _) => {
                    // trace!(&med.head, &med.tail);
                    // trace!(&med.sum_head, &med.sum_tail);
                    let left_sum = (med.head.len() as i64) / 2 * x - med.sum_head / 2;
                    let right_sum = med.sum_tail / 2 - (med.tail.len() as i64) / 2;
                    put!(x, base + left_sum + right_sum);
                }
            }

        }
    }
}

