fn main(){
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n:usize = sc.read();
    let mut v = Vec::new();
    for i in 0..n{
        v.push(Vec::new());
    }
    for i in 0..n{
        let q:usize = sc.read();
        if q == 2{
            v[i].push(1);
        }
        else{
            let a:i64 = sc.read();
            v[i].push(a);
            let b:i64 = sc.read();
            v[i].push(b);
        }
    }
    let mut upper = BinaryHeap::new();
    let mut lower = BinaryHeap::new();
    let mut us = 0;
    let mut ls = 0;
    let mut center = 0;
    let mut bs = 0;
    for i in 0..n{
        if v[i].len() == 2{
            bs += v[i][1];
            if lower.len()==0{
                lower.push(v[i][0]);
                ls += v[i][0];
            }
            else{
                if v[i][0]<=center{
                    lower.push(v[i][0]);
                    ls+=v[i][0];
                }
                else{
                    upper.push(-v[i][0]);
                    us+=v[i][0];
                }
            }
            while lower.len()<upper.len() || lower.len() >upper.len() + 1{
                if lower.len() < upper.len(){
                    let up = -1 * upper.pop().unwrap();
                    us -= up;
                    ls += up;
                    lower.push(up);
                }
                else{
                    let down = lower.pop().unwrap();
                    ls -= down;
                    us += down;
                    upper.push(-down);
                }
            }
            center = lower.top();    


        }
        else{
            println!("{} {}", center,bs +  us - (upper.len() as i64)*center + (lower.len() as i64)*center - ls  );
        }
    }

}

trait PeekTop<T> {
    fn top(&mut self) -> T;
}

impl<T> PeekTop<T> for BinaryHeap<T>
where
    T: Copy + Ord,
{
    fn top(&mut self) -> T {
        let top = self.pop().unwrap();
        self.push(top);
        top
    }
}

