            }
            let a = (a + 1_000_000_000) as u32;
            // eprintln!("insert {}", a);
            tree = Trie::insert(&tree, a);
            let mut ts = vec![];
            Trie::to_vec(&tree, &mut ts);
            // eprintln!("tree = {:?}", ts);
            base += b;
            if qi == 0 {
                center_x = a;
            } else {
                // eprintln!("center_x = {}", center_x);
                let prev_center_i = Trie::x_to_i(&tree, center_x, 31);
