                    // eprintln!("a");
                    let new_center = Trie::i(&tree, center_i);
                    dd += (tree.len() - center_i) as i64 * (center_x as i64 - new_center as i64);
                    dd -= (tree.len() + 0) as i64 * (center_x as i64 - new_center as i64);
                    center_x = new_center;
                } else if prev_center_i < center_i {
                    // eprintln!("b");
                    let new_center = Trie::i(&tree, center_i);
                    dd -= (tree.len() - center_i) as i64 * (new_center as i64 - center_x as i64);
