                }
                // eprintln!("dd_3 = {}", dd);
            }
        } else if t == 2 {
            let i = (tree.len() - 1) / 2;
            let t = Trie::i(&tree, i);
            writeln!(buf, "{} {}", t as i64 - 1_000_000_000, base + dd);
        }
    }

    buf
}

