use std::collections::BinaryHeap;

fn add(x: i64,
       head: &mut BinaryHeap<i64>,
       tail: &mut BinaryHeap<i64>,
       ) -> (i64, i64) {
    let mut head_diff = 0;
    let mut tail_diff = 0;
    match (head.peek(), tail.peek()) {
        (None, None) => {
            head.push(x);
            tail.push(-x);
            head_diff += x;
            tail_diff += x;
        },
        (Some(&a), Some(&b)) => {
            if x < a {
                head.push(x);
                head.push(x);
                head_diff += x;
                head_diff += x;
            } else if -b < x {
                tail.push(-x);
                tail.push(-x);
                tail_diff += x;
                tail_diff += x;
            } else {
                head.push(x);
                tail.push(-x);
                head_diff += x;
                tail_diff += x;
            }
        },
        _ => {}
    }
    while head.len() > tail.len() {
        let x = -head.pop().unwrap();
        tail.push(x);
        head_diff += x;
        tail_diff -= x;
    }
    while tail.len() > head.len() {
        let x = -tail.pop().unwrap();
        head.push(x);
        head_diff += x;
        tail_diff -= x;
    }
    (head_diff, tail_diff)
}

