use std::io::prelude::*;

fn input<T: std::str::FromStr>() -> T {
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let q: usize = input();
    let qs: Vec<Query> = (0..q)
        .map(|_| {
            let i: i32 = input();
            if i == 1 {
                Query::Q1(input(), input())
            } else {
                Query::Q2
            }
        })
        .collect();

    let mut xs = vec![i64::min_value(), i64::max_value()];
    for &q in &qs {
        if let Query::Q1(a, _) = q {
            xs.push(a);
        }
    }
    xs.sort();
    xs.dedup();
    let n = xs.len();

    let mut num = FenwickTree::new(n);
    let mut val = FenwickTree::new(n);
    let mut bsum = 0;

    for q in qs {
        if let Query::Q1(a, b) = q {
            let p = xs.lower_bound(&a);
            num.add(p, 1);
            val.add(p, xs[p]);
            bsum += b;
        } else {
            let nx = (num.sum(n) + 1) / 2;
            let med = num.lower_bound(&nx);
            let nl = num.sum(med - 1);
            let nr = num.sum(n) - num.sum(med);
            let vl = nl * xs[med] - val.sum(med - 1);
            let vr = val.sum(n) - val.sum(med) - nr * xs[med];
            println!("{} {}", xs[med], vl + vr + bsum);
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
enum Query {
    Q1(i64, i64),
    Q2,
}

trait LowerBound<T: Ord> {
    fn lower_bound(&self, x: &T) -> usize;
}

impl<T: Ord> LowerBound<T> for [T] {
    fn lower_bound(&self, x: &T) -> usize {
        let mut l = -1 as i64;
        let mut r = self.len() as i64;
        while r - l > 1 {
            let m = ((l + r) / 2) as usize;
            if self[m] >= *x {
                r = m as i64;
            } else {
                l = m as i64;
            }
        }
        r as usize
    }
}

#[derive(Clone, Debug, Default, Eq, Hash, PartialEq)]
struct FenwickTree(Vec<i64>);

impl FenwickTree {
    fn new(n: usize) -> FenwickTree {
        FenwickTree(vec![0; n + 1])
    }

    fn add(&mut self, i: usize, v: i64) {
        let n = self.0.len() as i64;
        let mut i = i as i64;
        while i < n {
            self.0[i as usize] += v;
            i += i & -i;
        }
    }

    fn sum(&self, i: usize) -> i64 {
        let mut i = i as i64;
        let mut r = 0;
        while i > 0 {
            r += self.0[i as usize];
            i -= i & -i;
        }
        r
    }

    fn lower_bound(&self, x: &i64) -> usize {
        let n = self.0.len();
        let mut k = 1;
        while k * 2 < n {
            k *= 2;
        }

        let mut i = 0;
        let mut x = *x;
        while k > 0 {
            if i + k < n && self.0[i + k] < x {
                x -= self.0[i + k];
                i += k;
            }
            k /= 2;
        }
        i + 1
    }
}

