use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        q: usize,
    }
    let inf = 1i64 << 50;
    let mut base = 0;
    let mut ls = BinaryHeap::new();
    let mut rs = BinaryHeap::new();
    let mut l_sum = 0;
    let mut r_sum = 0;
    for qi in 0..q {
        // eprintln!("qi={}", qi);
        input! {
            parser = parser,
            t: usize,
        }
        if t == 1 {
            input! {
                parser = parser,
                a: i64,
                b: i64,
            }
            base += b;
            if qi == 0 {
                ls.push(a);
                rs.push(-a);
            } else {
                let l_top = *ls.peek().unwrap();
                let r_top = -*rs.peek().unwrap();
                if a < l_top {
                    ls.pop();
                    rs.push(-l_top);
                    ls.push(a);
                    ls.push(a);
                    l_sum += l_top - a;
                } else if l_top <= a && a <= r_top {
                    ls.push(a);
                    rs.push(-a);
                } else {
                    rs.pop();
                    ls.push(r_top);
                    rs.push(-a);
                    rs.push(-a);
                    r_sum += a - r_top;
                }
                // eprintln!("l_sum={}, r_sum={}", l_sum, r_sum);
            }
        } else if t == 2 {
            writeln!(buf, "{} {}", ls.peek().unwrap(), base + l_sum + r_sum);
        }
    }

    buf
}

