        }
    }

    pub fn count(t: &Option<Box<Node>>) -> usize {
        match *t {
            Some(ref x) => x.cnt,
            None => 0,
        }
    }

    pub fn sum(t: &Option<Box<Node>>) -> i64 {
        match *t {
            Some(ref x) => x.sum,
            None => 0,
        }
    }

    fn update(t: Box<Node>) -> Box<Node> {
        let mut t = t;
        t.cnt = count(&t.lch) + count(&t.rch) + 1;
        t.sum = sum(&t.lch) + sum(&t.rch) + t.v;
        t
    }

    pub fn merge(l: Option<Box<Node>>, r: Option<Box<Node>>) -> Option<Box<Node>> {
        if l.is_none() && r.is_none() {
            return None
        }
        if l.is_none() {
            return r
        }
        if r.is_none() {
            return l
        }

        assert!(l.is_some() && r.is_some());
        let mut l = l.unwrap();
        let mut r = r.unwrap();

        if l.pri > r.pri {
            let old_rch = l.rch.take();
            l.rch = merge(old_rch, Some(r).into());
            update(l).into()
        } else {
            let old_lch = r.lch.take();
            r.lch = merge(Some(l).into(), old_lch);
            update(r).into()
        }
    }

    // [0,k),[k,n]
    pub fn split(t: Option<Box<Node>>, k: usize) -> (Option<Box<Node>>, Option<Box<Node>>) {
        if t.is_none() {
            return (None.into(), None.into())
        }
        let mut t = t.unwrap();

        let lcnt = count(&t.lch);
        if k <= lcnt {
            let old_lch = t.lch.take();
            let s = split(old_lch, k);
            t.lch = s.1;
            (s.0, Some(update(t)).into())
        } else {
            let old_rch = t.rch.take();
            let s = split(old_rch, k - lcnt - 1);
            t.rch = s.0;
            (Some(update(t)).into(), s.1)
        }
    }

    // split is fast but merge is slow
    pub fn insert(t: Box<Node>, k: usize, v: i64, rand: u64) -> Option<Box<Node>> {
        let (l,r) = split(Some(t).into(), k);
        let newt = merge(l, Some(new_node(v, rand).into()));
        let newt = merge(newt, r);
        newt
    }

    pub fn erase(t: Box<Node>, k: usize) -> Option<Box<Node>> {
        // [0,k),[k,k+1)[k+1,n)
        let (t1, rest) = split(Some(t).into(), k);
        let (t2, t3) = split(rest, 1);
        merge(t1, t3)
    }

    pub fn bisect(t: &Option<Box<Node>>, v: i64) -> usize {
        match *t {
            None => 0,
            Some(ref n) => {
                if v <= n.v {
                    bisect(&n.lch, v)
                } else {
                    count(&n.lch) + 1 + bisect(&n.rch, v)
                }
            }
        }
    }
}

struct Treap {
    rng: Xorshift,
    t: Option<Box<treap::Node>>,
}
impl Treap {
    pub fn new() -> Treap {
        Treap {
            rng: Xorshift::new(),
            t: None,
        }
    }
    #[doc = "[l,r)"]
    pub fn lower_bound(&mut self, l: usize, r: usize, v: i64) -> usize {
        let t = self.t.take();
        let (lt, t) = treap::split(t, l);
        let (t, rt) = treap::split(t, r-l);
        let idx = treap::count(&lt) + treap::bisect(&t, v);
        self.t = treap::merge(lt, treap::merge(t, rt));
        idx
    }
    pub fn orderd_insert(&mut self, v: i64) {
        if self.t.is_none() {
            self.insert(0, v);
        } else {
            let n = self.len();
            let ins_pos = self.lower_bound(0, n, v);
            self.insert(ins_pos, v);
        }
    }
    pub fn insert(&mut self, k: usize, v: i64) {
        if self.t.is_none() {
            self.t = Some(treap::new_node(v, self.rng.next()).into());
        } else {
            let t = self.t.take().unwrap();
            self.t = treap::insert(t, k, v, self.rng.next());
        }
    }
    pub fn erase(&mut self, k: usize) {
        if self.t.is_some() {
            let t = self.t.take().unwrap();
            self.t = treap::erase(t, k).into();
        }
    }
    #[doc = "split into [l,r)+[r,n)"]
    pub fn split(self, k: usize) -> (Treap, Treap) {
        let (a, b) = treap::split(self.t, k);
        (Treap { rng: self.rng.clone(), t: a }, Treap { rng: self.rng.clone(), t: b })
    }
    pub fn len(&self) -> usize {
        treap::count(&self.t)
    }
    #[doc = "[l,r)"]
    pub fn sum(&mut self, l: usize, r: usize) -> i64 {
        if self.t.is_none() {
            return 0
        } else {
            let t = self.t.take();
            // split into a1,b1,b2
            let (a1, a2) = treap::split(t, l);
            let (b1, b2) = treap::split(a2, r-l);
            let res = treap::sum(&b1);
            self.t = treap::merge(treap::merge(a1, b1), b2);
            res
        }
    }
    pub fn get(&mut self, k: usize) -> i64 {
        self.sum(k, k+1)
    }
}

#![allow(unused, non_snake_case, dead_code, non_upper_case_globals)]
use {
    proconio::{marker::*, *},
    std::{cmp::*, collections::*, mem::*},
};

fn main() {
    input! {q:usize}
    let mut med = 0;
    // let mut lower = BinaryHeap::new();
    // let mut upper = BinaryHeap::new();
    let mut lower = PriorityQueue::new();
    let mut upper = PriorityQueue::new();
    let mut lower_sum = 0;
    let mut upper_sum = 0;
    let mut bsm = 0i64;
    for _ in 0..q {
        input! {t:usize}
        // median median
        match t {
            1 => {
                input! {a:i64,b:i64}
                bsm += b;
                if lower.is_empty() {
                    lower.push(a);
                } else {
                    if a < med {
                        lower.push(a);
                        lower_sum += med - a;
                    } else {
                        upper.push(a);
                        upper_sum += a - med;
                    }
                }

                while lower.len() < upper.len() || lower.len() > upper.len() + 1 {
                    if lower.len() < upper.len() {
                        let upper_min = *upper.peek_min().unwrap();
                        let diff = upper_min - med;
                        lower_sum += lower.len() as i64 * diff;
                        upper_sum -= upper.len() as i64 * diff;
                        upper.pop_max();
                        lower.push(upper_min);
                    } else {
                        let lower_max = lower.pop_max().unwrap();
                        let diff = med - lower.peek_max().unwrap();
                        upper.push(lower_max);
                        lower_sum -= lower.len() as i64 * diff;
                        upper_sum += upper.len() as i64 * diff;
                    }
                    med = *lower.peek_max().unwrap();
                }
                med = *lower.peek_max().unwrap();
            }
            _ => {
                //query
                println!("{} {}", med, bsm + lower_sum + upper_sum);
            }
        }
    }
}
struct PriorityQueue<T: Ord + Copy> {
    que_max: BinaryHeap<T>,
    que_min: BinaryHeap<Reverse<T>>,
}
impl<T: Ord + Copy> PriorityQueue<T> {
    fn new() -> PriorityQueue<T> {
        PriorityQueue {
            que_max: BinaryHeap::<T>::new(),
            que_min: BinaryHeap::<Reverse<T>>::new(),
        }
    }
    fn is_empty(&mut self) -> bool {
        self.que_max.is_empty()
    }
    fn push(&mut self, x: T) {
        self.que_max.push(x);
        self.que_min.push(Reverse(x));
    }
    fn len(&mut self) -> usize {
        self.que_max.len()
    }
    fn pop_max(&mut self) -> Option<T> {
        self.que_min.pop();
        self.que_max.pop()
    }
    fn pop_min(&mut self) -> Option<T> {
        self.que_max.pop();
        if let Some(x) = self.que_min.pop() {
            let Reverse(y) = x;
            Some(y)
        } else {
            None
        }
    }
    fn peek_max(&mut self) -> Option<&T> {
        self.que_max.peek()
    }
    fn peek_min(&mut self) -> Option<&T> {
        if let Some(x) = self.que_min.peek() {
            let Reverse(y) = x;
            Some(y)
        } else {
            None
        }
    }
}

