use std::cmp::{Ord, Ordering};
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct Reverse<T: Ord>(pub T);
impl<T: Ord> PartialOrd for Reverse<T> {
    fn partial_cmp(&self, other: &Reverse<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Reverse<T> {
    fn cmp(&self, other: &Reverse<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}
pub trait SortDesc<T> {
    fn sort_desc(&mut self)
    where
        T: Ord;
    fn sort_desc_by_key<K: Ord, F: FnMut(&T) -> K>(&mut self, f: F);
}
impl<T> SortDesc<T> for [T] {
    fn sort_desc(&mut self)
    where
        T: Ord,
    {
        self.sort();
        self.reverse();
    }
    fn sort_desc_by_key<K: Ord, F: FnMut(&T) -> K>(&mut self, mut f: F) {
        self.sort_by_key(|x| Reverse(f(x)));
    }
}
#[derive(PartialEq, PartialOrd)]
pub struct Total<T: PartialOrd + PartialEq>(pub T);
impl<T: PartialOrd + PartialEq> Eq for Total<T> {}
impl<T: PartialOrd + PartialEq> Ord for Total<T> {
    fn cmp(&self, other: &Self) -> Ordering {
        self.partial_cmp(other).unwrap()
    }
}

use std::collections::BinaryHeap;

fn main() {
    read!();
    let mut left = BinaryHeap::new();
    let mut right = BinaryHeap::new();
    read!(_ = (), a = i64, b = i64);
    left.push(a);
    let mut min = b;

    readx_loop!(|_ = (), update = Vec<i64>| {
        let argmin = *left.peek().unwrap();
        if update.is_empty() {
            println!("{} {}", argmin, min);
        } else {
            let a = update[0];
            let b = update[1];
            if left.len() > right.len() {
                if a < argmin {
                    left.pop();
                    left.push(a);
                    right.push(Reverse(argmin));
                } else {
                    right.push(Reverse(a));
                }
            } else {
                if right.peek().unwrap().0 < a {
                    let r = right.pop().unwrap().0;
                    right.push(Reverse(a));
                    left.push(r);
                } else {
                    left.push(a);
                }
            }
            let next = *left.peek().unwrap();
            if left.len() == right.len() {
                min += b + argmin.abs_diff(a);
            } else {
                min += b + next.abs_diff(a) - (next - argmin);
            }
        }

    });
}

#[allow(unused_macros)]
macro_rules! scan {
    () => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().to_string()
        }
    };
    (;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().split_whitespace().map(|s| s.to_string()).collect::<Vec<String>>()
        }
    };
    (;;$n:expr) => {
        {
            (0..$n).map(|_| scan!()).collect::<Vec<_>>()
        }
    };
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
    ($t:ty;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.split_whitespace()
                .map(|t| t.parse::<$t>().unwrap())
                .collect::<Vec<_>>()
        }
    };
    ($t:ty;;$n:expr) => {
        (0..$n).map(|_| scan!($t;;)).collect::<Vec<_>>()
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    scan!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    scan!($($t),*)
        ).collect::<Vec<_>>()
    };
}

fn main() {
    let q = scan!(usize);

    let f = scan!(i64;;);
    let (mut a, mut b) = (f[1], f[2]);
    let mut xs = vec![a];
    for _ in 1..q {
        let vs = scan!(i64;;);
        if vs[0] == 1 {
            xs.push(vs[1]);
            b += vs[2];
            if vs[1] < a {
                a = vs[1];
            }
        } else {
            xs.sort();
            println!(
                "{} {}",
                xs[xs.len() / 2],
                xs.iter()
                    .map(|&v| (v - xs[xs.len() / 2]).abs())
                    .sum::<i64>()
                    + b
            );
        }
    }
}

