fn main() {
    input! {
        Q:usize
    }
    let mut al = BinaryHeap::new();
    let mut ar = BinaryHeap::new();
    // first query
    input! {query:i64,a:i64,b:i64}
    al.push(a);
    // binary heap は最大値しかpopできないので、右側は逆順にしておく。
    ar.push(-a);
    let mut l = a;
    let mut r = a;
    let mut ans = 0;
    let mut bsum = b;

    for _ in 1..Q {
        input! {query:i64}
