                al.push(a);
                al.push(a);
                r = al.pop().unwrap();
                ar.push(-r);
                l = *al.iter().next().unwrap();
            } else if a > r {
                ans += a - r;
                ar.push(-a);
                ar.push(-a);
                l = -ar.pop().unwrap();
                al.push(l);
                r = -*ar.iter().next().unwrap();
            } else {
                al.push(a);
                ar.push(-a);
                l = *al.iter().next().unwrap();
                r = -*ar.iter().next().unwrap();
            }
        } else {
            println!("{} {}", l, ans + bsum);
        }
    }
}

