    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

fn main() {
    let stdin = std::io::stdin();
    let mut sc = Scanner { reader: stdin.lock() };

    let q: usize = sc.read();

    let mut bb = 0 as i64;

    use std::collections::BinaryHeap;
    let mut lq = BinaryHeap::new();
    let mut rq = BinaryHeap::new();

    let mut min_ans = 0;
    for _ in 0..q {
        let t:usize = sc.read();
        if t == 1 {
            let a:i64 = sc.read();
            let b:i64 = sc.read();

            let l = lq.pop();
            let r = rq.pop();

            match (l, r) {
                (None, None) => {
                    lq.push(a);
                },
                (Some(l), None) => {
                    if l < a {
                        lq.push(l);
                        rq.push(a);
                    } else {
                        lq.push(a);
                        rq.push(l);
                    }
                    min_ans = (l-a).abs();
                },
                (Some(l), Some(r)) => {
                    let mut tmp = [l, a, r];
                    tmp.sort();

                    if lq.len() == rq.len() {
                        lq.push(tmp[0]);
                        lq.push(tmp[1]);
                        rq.push(tmp[2]);
                        if !(l <= a && a <= r) {
                            min_ans += (l-a).abs();
                        }
                    } else {
                        lq.push(tmp[0]);
                        rq.push(tmp[1]);
                        rq.push(tmp[2]);
                        min_ans += (l-a).abs();
                    }
                },
                _ => unreachable!(),
            };

            bb += b;
        } else {
            let x = lq.peek().unwrap();
            println!("{} {}", x, min_ans+bb);
        }
    }
}

