        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let q: usize = input();
    let qs: Vec<Query> = (0..q)
        .map(|_| {
            let i: i32 = input();
            if i == 1 {
                //let (a, b) = (input(), input());
                Query::Q1(input(), input())
            } else {
                Query::Q2
            }
        })
        .collect();

    let mut hl = std::collections::BinaryHeap::new();
    let mut hr = std::collections::BinaryHeap::new();
    let mut ans = 0i64;
    for q in qs {
        match q {
            Query::Q1(a, b) => {
                ans += b;
                hl.push(a);
                hr.push(Reverse(a));
                let l = hl.pop().unwrap();
                let Reverse(r) = hr.pop().unwrap();
                if l <= r {
                    hl.push(l);
                    hr.push(Reverse(r));
                } else {
                    ans += i64::abs(r - l);
                    hl.push(r);
                    hr.push(Reverse(l));
                }
            }
            Query::Q2 => {
                println!("{} {}", hl.peek().unwrap(), ans);
            }
        }
    }
}

enum Query {
    Q1(i64, i64),
    Q2,
}

