pub struct Xorshift {
    seed: u64,
}
impl Xorshift {
    #[allow(dead_code)]
    pub fn new() -> Xorshift {
        Xorshift {
            seed: 0xf0fb588ca2196dac,
        }
    }
    #[allow(dead_code)]
    pub fn with_seed(seed: u64) -> Xorshift {
        Xorshift { seed: seed }
    }
    #[inline(always)]
    #[allow(dead_code)]
    pub fn next(&mut self) -> u64 {
        self.seed = self.seed ^ (self.seed << 13);
        self.seed = self.seed ^ (self.seed >> 7);
        self.seed = self.seed ^ (self.seed << 17);
        self.seed
    }
    #[inline(always)]
    #[allow(dead_code)]
    pub fn rand(&mut self, m: u64) -> u64 {
        self.next() % m
    }
    #[inline(always)]
    #[allow(dead_code)]
    pub fn randf(&mut self) -> f64 {
        use std::mem;
        const UPPER_MASK: u64 = 0x3FF0000000000000;
        const LOWER_MASK: u64 = 0xFFFFFFFFFFFFF;
        let tmp = UPPER_MASK | (self.next() & LOWER_MASK);
        let result: f64 = unsafe { mem::transmute(tmp) };
        result - 1.0
    }
}
struct Treap {
    rng: Xorshift,
    t: Option<Box<treap::Node>>,
}
impl Treap {
    fn new() -> Treap {
        Treap {
            rng: Xorshift::new(),
            t: None,
        }
    }
    #[doc = "[l,r)"]
    fn lower_bound(&mut self, l: usize, r: usize, v: i64) -> Option<usize> {
        let lower = l as i64;
        let upper = r as i64;

        let mut lb = lower - 1; 
        let mut ub = upper + 1;
        while ub - lb > 1 {
            let mid = (lb+ub)/2;
            if self.get(mid as usize) > v {
                ub = mid;
            } else {
                lb = mid;
            }
        }
        let latter = ub;
        if latter < 0 {
            None
        } else {
            Some(latter as usize)
        }
    }
    fn orderd_insert(&mut self, v: i64) {
        if self.t.is_none() {
            self.insert(0, v);
        } else {
            let n = self.len();
            let ins_pos = match self.lower_bound(0, n, v) {
                Some(x) => x,
                None => 0
            };
            self.insert(ins_pos, v);
        }
    }
    fn insert(&mut self, k: usize, v: i64) {
        if self.t.is_none() {
            self.t = Some(treap::new_node(v, self.rng.next()).into());
        } else {
            let t = self.t.take().unwrap();
            self.t = treap::insert(t, k, v, self.rng.next()).into();
        }
    }
    fn erase(&mut self, k: usize) {
        if self.t.is_some() {
            let t = self.t.take().unwrap();
            self.t = treap::erase(t, k).into();
        }
    }
    #[doc = "split into [l,r)+[r,n)"]
    fn split(self, k: usize) -> (Treap, Treap) {
        let (a, b) = treap::split(self.t, k);
        (Treap { rng: self.rng.clone(), t: a }, Treap { rng: self.rng.clone(), t: b })
    }
    fn len(&self) -> usize {
        treap::count(&self.t)
    }
    #[doc = "[l,r)"]
    fn sum(&mut self, l: usize, r: usize) -> i64 {
        if self.t.is_none() {
            return 0
        } else {
            let t = self.t.take();
            // split into a1,b1,b2
            let (a1, a2) = treap::split(t, l);
            let (b1, b2) = treap::split(a2, r-l);
            let res = treap::sum(&b1);
            self.t = treap::merge(treap::merge(a1, b1).into(), b2).into();
            res
        }
    }
    fn get(&mut self, k: usize) -> i64 {
        self.sum(k, k+1)
    }
}

use proconio::{fastout, input};
use std::{collections::BinaryHeap, cmp};
use cmp::Reverse;

#[fastout]
fn main() {
    input! {
        q: usize,
    }
    let mut queries = vec![];
    for _ in 0..q {
        input! {
            t: usize,
        }

        if t == 1 {
            input! {
                a: i64,
                b: i64,
            }
            queries.push(Query::Update(a, b))
        } else {
            queries.push(Query::Min)
        }
    }

    // -----------------------
    let mut left = BinaryHeap::new();
    let mut right = BinaryHeap::new();
    let mut value = 0;
    let mut x = 0;
    for query in queries {
        match query {
            Query::Update(a, b) => {
                value += b;
                left.push(a);
                right.push(Reverse(a));

                let l = left.pop().unwrap();
                let Reverse(r) = right.pop().unwrap();
                if l > r {
                    value += l - r;
                    left.push(r);
                    right.push(Reverse(l));
                } else {
                    left.push(l);
                    right.push(Reverse(r));
                }
                x = *left.peek().unwrap();
            },
            Query::Min => {
                println!("{} {}", x, value);
            },
        }
    }
}

enum Query {
    Update(i64, i64),
    Min,
}

