use std::rc::Rc;

pub enum Trie {
    None,
    Leaf {
        x: u32,
    },
    Node {
        n: usize,
        left: Rc<Trie>,
        right: Rc<Trie>,
    },
}

impl Trie {
    pub fn new() -> Rc<Trie> {
        Rc::new(Trie::None)
    }
    pub fn insert(trie: &Rc<Trie>, x: u32) -> Rc<Trie> {
        Trie::insert_sub(trie, x, 31)
    }
    pub fn len(&self) -> usize {
        match self {
            Trie::None => 0,
            Trie::Leaf { x: _ } => 1,
            Trie::Node {
                n: n,
                left: _,
                right: _,
            } => *n,
        }
    }
    pub fn insert_sub(trie: &Rc<Trie>, x: u32, i: usize) -> Rc<Trie> {
        if i == 0 {
            Rc::new(Trie::Leaf { x: x })
        } else {
            if x & (1 << i) != 0 {
                let (left, right) = match trie.as_ref() {
                    Trie::None => (
                        Rc::new(Trie::None),
                        Trie::insert_sub(&Rc::new(Trie::None), x, i - 1),
                    ),
                    Trie::Leaf { x: _ } => {
                        panic!();
                    }
                    Trie::Node {
                        n: _,
                        left: left,
                        right: right,
                    } => (left.clone(), Trie::insert_sub(&right, x, i - 1)),
                };
                Rc::new(Trie::Node {
                    n: left.len() + right.len(),
                    left: left,
                    right: right,
                })
            } else {
                let (left, right) = match trie.as_ref() {
                    Trie::None => (
                        Trie::insert_sub(&Rc::new(Trie::None), x, i - 1),
                        Rc::new(Trie::None),
                    ),
                    Trie::Leaf { x: _ } => {
                        panic!();
                    }
                    Trie::Node {
                        n: _,
                        left: left,
                        right: right,
                    } => (Trie::insert_sub(&left, x, i - 1), right.clone()),
                };
                Rc::new(Trie::Node {
                    n: left.len() + right.len(),
                    left: left,
                    right: right,
                })
            }
        }
    }
    pub fn i(trie: &Rc<Trie>, i: usize) -> u32 {
        assert!(i < trie.len());
        match trie.as_ref() {
            Trie::None => {
                panic!();
            }
            Trie::Leaf { x: x } => {
                if i == 0 {
                    *x
                } else {
                    panic!();
                }
            }
            Trie::Node {
                n: _,
                left: left,
                right: right,
            } => {
                if i < left.len() {
                    Trie::i(left, i)
                } else {
                    Trie::i(right, i - left.len())
                }
            }
        }
    }
    pub fn x_to_i(trie: &Rc<Trie>, t: u32, i: usize) -> usize {
        match trie.as_ref() {
            Trie::None => {
                panic!();
            }
            Trie::Leaf { x: x } => {
                if i == 0 && *x == t {
                    0
                } else {
                    panic!();
                }
            }
            Trie::Node {
                n: _,
                left: left,
                right: right,
            } => {
                if t & (1 << i) != 0 {
                    left.len() + Trie::x_to_i(right, t, i - 1)
                } else {
                    Trie::x_to_i(left, t, i - 1)
                }
            }
        }
    }
    pub fn to_vec(trie: &Rc<Trie>, xs: &mut Vec<u32>) {
        match trie.as_ref() {
            Trie::None => {}
            Trie::Leaf { x: x } => {
                xs.push(*x);
            }
            Trie::Node {
                n: _,
                left: left,
                right: right,
            } => {
                Trie::to_vec(&left, xs);
                Trie::to_vec(&right, xs);
            }
        }
    }
}

use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        q: usize,
    }
    let inf = 1i64 << 50;
    let mut base = 0;
    let mut tree = Trie::new();
    let mut center_x = 0;
    let mut dd = 0;
    for qi in 0..q {
        // eprintln!("qi={}", qi);
        input! {
            parser = parser,
            t: usize,
        }
        if t == 1 {
            input! {
                parser = parser,
                a: i64,
                b: i64,
            }
            let a = (a + 1_000_000_000) as u32;
            // eprintln!("insert {}", a);
            tree = Trie::insert(&tree, a);
            let mut ts = vec![];
            Trie::to_vec(&tree, &mut ts);
            // eprintln!("tree = {:?}", ts);
            base += b;
            if qi == 0 {
                center_x = a;
            } else {
                // eprintln!("center_x = {}", center_x);
                let prev_center_i = Trie::x_to_i(&tree, center_x, 31);
                let center_i = (tree.len() - 1) / 2;
                // eprintln!("dd_1 = {}", dd);
                if center_x <= a {
                    dd += a as i64 - center_x as i64;
                } else {
                    dd += center_x as i64 - a as i64;
                }
                // eprintln!("dd_2 = {}", dd);
                if center_i < prev_center_i {
                    // eprintln!("a");
                    let new_center = Trie::i(&tree, center_i);
                    dd += (tree.len() - center_i) as i64 * (center_x as i64 - new_center as i64);
                    dd -= tree.len() as i64 * (center_x as i64 - new_center as i64);
                    center_x = new_center;
                } else if prev_center_i < center_i {
                    // eprintln!("b");
                    let new_center = Trie::i(&tree, center_i);
                    dd -=
                        (tree.len() - center_i - 1) as i64 * (new_center as i64 - center_x as i64);
                    dd += tree.len() as i64 * (new_center as i64 - center_x as i64);
                    center_x = new_center;
                }
                // eprintln!("dd_3 = {}", dd);
            }
        } else if t == 2 {
            let i = (tree.len() - 1) / 2;
            let t = Trie::i(&tree, i);
            writeln!(buf, "{} {}", t as i64 - 1_000_000_000, base + dd);
        }
    }

    buf
}

