            if a < l {
                ans += l - a;
                al.push(a);
                al.push(a);
                r = al.pop().unwrap();
                ar.push(-r);
                l = *al.peek().unwrap();
            } else if a > r {
                ans += a - r;
                ar.push(-a);
                ar.push(-a);
                l = -ar.pop().unwrap();
                al.push(l);
                r = -*ar.peek().unwrap();
            } else {
                al.push(a);
