use std::cmp::*;
use std::collections::BinaryHeap;
use std::ops::Neg;

pub struct MedianQuery<T> {
    ls: BinaryHeap<T>,
    rs: BinaryHeap<T>,
}

impl<T: Ord + Neg<Output = T> + Copy> MedianQuery<T> {
    pub fn new() -> MedianQuery<T> {
        let ls = BinaryHeap::new();
        let rs = BinaryHeap::new();
        MedianQuery { ls: ls, rs: rs }
    }
    pub fn insert(&mut self, x: T) {
        if self.ls.is_empty() && self.rs.is_empty() {
            self.ls.push(x);
            self.rs.push(-x);
        } else {
            let (l_top, r_top) = self.median();
            if x < l_top {
                self.ls.pop();
                self.rs.push(-l_top);
                self.ls.push(x);
                self.ls.push(x);
            } else if l_top <= x && x <= r_top {
                self.ls.push(x);
                self.rs.push(-x);
            } else {
                self.rs.pop();
                self.ls.push(r_top);
                self.rs.push(-x);
                self.rs.push(-x);
            }
        }
    }
    pub fn median(&self) -> (T, T) {
        let l_top = *self.ls.peek().unwrap();
        let r_top = -*self.rs.peek().unwrap();
        (l_top, r_top)
    }
}

