    let mut mq = MedianQuery::new();
    for qi in 0..q {
        // eprintln!("qi={}", qi);
        input! {
            parser = parser,
            t: usize,
        }
        if t == 1 {
            input! {
                parser = parser,
                a: i64,
                b: i64,
            }
            base += b;
            if qi == 0 {
                mq.insert(a);
            } else {
                let (l_top, r_top) = mq.median();
                mq.insert(a);
                if a < l_top {
                    sum += l_top - a;
                }
                if r_top < a {
                    sum += a - r_top;
                }
            }
        } else if t == 2 {
            writeln!(buf, "{} {}", mq.median().0, base + sum);
        }
    }

    buf
}

