use std::cmp::Ordering;
use std::cmp::Ordering::*;
use std::cmp::PartialOrd;
use std::collections::BinaryHeap;
use std::io::{stdin, Read};

#[derive(PartialEq, Eq, Debug)]
struct Rev<T>(T);

impl<T: Ord> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(match self.0.cmp(&other.0) {
            Less => Greater,
            Equal => Equal,
            Greater => Less,
        })
    }
}

impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Self) -> Ordering {
        self.partial_cmp(other).unwrap()
    }
}

macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, q: usize);
    let mut left = BinaryHeap::<i64>::new();
    let mut right = BinaryHeap::<Rev<i64>>::new();
    let mut c = 0;
    let mut ls = 0;
    let mut s = 0;
    let mut n = 0;
    for _ in 0..q {
        parse!(it, t: usize);
        if t == 1 {
            n += 1;
            parse!(it, a: i64, b: i64);
            c += b;
            s += a;
            match (left.peek(), right.peek()) {
                (None, None) => {
                    left.push(a);
                    ls += a
                }
                (_, Some(&Rev(r))) if a > r => right.push(Rev(a)),
                (_, Some(_)) => {
                    left.push(a);
                    ls += a
                }
                (Some(&l), _) if a <= l => {
                    left.push(a);
                    ls += a
                }
                (Some(_), _) => right.push(Rev(a)),
            }
            // balance
            while left.len() > right.len() + 1 {
                let l = left.pop().unwrap();
                ls -= l;
                right.push(Rev(l));
            }
            while left.len() < right.len() {
                let Rev(r) = right.pop().unwrap();
                ls += r;
                left.push(r);
            }
        } else {
            let &l = left.peek().unwrap();
            let ret = -(n - 2 * ((n + 1) / 2)) * l + s - 2 * ls + c;
            println!("{} {}", l, ret);
        }
    }
}

